const fs = require('fs');
const path = require('path');

const dir = './coverage/.tmp';
const files = fs.readdirSync(dir).filter(f => f.endsWith('.json'));
let allResults = [];
files.forEach(f => {
  const d = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'));
  if (d.result) allResults = allResults.concat(d.result);
});

const targets = [
  'telemetry/telemetry.vue',
  'telemetry/modules/history-data.vue',
  'telemetry/modules/time-series-data.vue',
  'details/modules/give-an-alarm.vue',
  'details/modules/message.vue',
  'details/modules/device-status.vue',
  'shared-with-me/index.vue',
  'warning-message/components/pop-up.vue',
  'warning-message/components/new-information.vue',
  'dashboard/rdi-overview/index.vue'
];

// Group results by url
const byUrl = {};
allResults.filter(r => targets.some(t => r.url.includes(t))).forEach(r => {
  if (!byUrl[r.url]) byUrl[r.url] = [];
  byUrl[r.url].push(r);
});

Object.keys(byUrl).forEach(url => {
  const results = byUrl[url];
  const filePath = url.replace('file:///', '').replace(/\//g, path.sep);
  let src = '';
  try { src = fs.readFileSync(filePath, 'utf8'); } catch (e) { console.log('CANNOT READ: ' + url); return; }

  const lines = src.split('\n');
  const lineStartOffsets = [0];
  let cumOffset = 0;
  for (let i = 0; i < lines.length; i++) {
    cumOffset += lines[i].length + 1;
    lineStartOffsets.push(cumOffset);
  }

  // Collect all ranges from all results for this file
  let allRanges = [];
  results.forEach(r => {
    r.functions.forEach(fn => {
      fn.ranges.forEach(range => {
        allRanges.push({ start: range.startOffset, end: range.endOffset, count: range.count });
      });
    });
  });

  // For each code line, check if it's covered in ANY result
  const codeLines = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line && !line.startsWith('//') && !line.startsWith('*') && !line.startsWith('/*') && !line.startsWith('<!--')) {
      codeLines.push(i + 1);
    }
  }

  const uncoveredLines = [];
  for (const lineNum of codeLines) {
    const lineStart = lineStartOffsets[lineNum - 1];
    const lineEnd = lineStartOffsets[lineNum] - 1;
    const midOffset = Math.floor((lineStart + lineEnd) / 2);

    // Check if covered in any result
    let covered = false;
    for (const r of results) {
      let allR = [];
      r.functions.forEach(fn => {
        fn.ranges.forEach(range => {
          allR.push({ start: range.startOffset, end: range.endOffset, count: range.count });
        });
      });

      // Find innermost range containing midOffset
      let innermost = null;
      for (const ar of allR) {
        if (ar.start <= midOffset && midOffset < ar.end) {
          if (!innermost) {
            innermost = ar;
          } else if (ar.start >= innermost.start && ar.end <= innermost.end && (ar.start > innermost.start || ar.end < innermost.end)) {
            innermost = ar;
          }
        }
      }

      if (innermost && innermost.count > 0) {
        covered = true;
        break;
      }
    }

    if (!covered) {
      uncoveredLines.push(lineNum);
    }
  }

  const totalCodeLines = codeLines.length;
  const coveredCount = totalCodeLines - uncoveredLines.length;
  const pct = Math.round(coveredCount / totalCodeLines * 100);

  const shortPath = url.split('src')[1];
  console.log(shortPath + ' | lines: ' + coveredCount + '/' + totalCodeLines + ' (' + pct + '%) | uncovered: ' + JSON.stringify(uncoveredLines));
});

/**
 * 文件用途：构造 Vite 开发代理表，转发平台 API、文件与 ThingsVis 请求。
 * 核心逻辑：以 env.config.ts 的 createServiceConfig/createProxyPattern 为唯一来源推导代理前缀与目标。
 * 关键注意事项：代理键必须与前端固定路径常量一致（见 src/utils/thingsvis/constants.ts 的 THINGSVIS_API_PROXY_PATH）。
 * 重构建议：新增后端服务时优先扩展 otherBaseURL，而不是在此硬编码新前缀。
 */
import type { ProxyOptions } from 'vite'
import { createProxyPattern, createServiceConfig } from '../../env.config'

/** ThingsVis 代理前缀，必须与 src/utils/thingsvis/constants.ts 保持一致 */
const THINGSVIS_API_PROXY_PATH = '/thingsvis-api'

/**
 * 把形如 http://host:port/api/v1 的 baseURL 拆成代理 target 与需要补回的路径前缀。
 *
 * 代理前缀（/proxy-default）在请求发出前替换掉 baseURL，因此 rewrite 必须把
 * baseURL 的 path 部分（/api/v1）加回去，否则后端会收到不带版本前缀的路径。
 */
function splitBaseURL(baseURL: string) {
  const url = new URL(baseURL)
  const basePath = url.pathname.replace(/\/$/, '')

  return { target: url.origin, basePath }
}

/**
 * 创建 Vite 开发代理。
 *
 * @param env 当前 vite 环境变量
 * @param enable 是否启用代理，未显式传入时取 VITE_HTTP_PROXY === 'Y'
 */
export function createViteProxy(env: Env.ImportMeta, enable?: boolean): Record<string, ProxyOptions> | undefined {
  const isEnable = enable ?? env.VITE_HTTP_PROXY === 'Y'

  if (!isEnable) return undefined

  const { baseURL, otherBaseURL } = createServiceConfig(env)
  const proxy: Record<string, ProxyOptions> = {}

  // 默认平台服务：/proxy-default -> ${origin}/api/v1
  if (baseURL) {
    const { target, basePath } = splitBaseURL(baseURL)
    const pattern = createProxyPattern()

    proxy[pattern] = {
      target,
      changeOrigin: true,
      ws: true,
      rewrite: path => path.replace(new RegExp(`^${pattern}`), basePath)
    }

    // 文件下载/上传走后端同源路径，前端直接请求 /files
    proxy['/files'] = {
      target,
      changeOrigin: true
    }
  }

  // 其它命名服务：/proxy-<key> -> 对应 baseURL
  Object.entries(otherBaseURL ?? {}).forEach(([key, url]) => {
    if (!url || url === baseURL) return

    const { target, basePath } = splitBaseURL(url)
    const pattern = createProxyPattern(key as App.Service.OtherBaseURLKey)

    proxy[pattern] = {
      target,
      changeOrigin: true,
      ws: true,
      rewrite: path => path.replace(new RegExp(`^${pattern}`), basePath)
    }
  })

  // ThingsVis 后端：前端固定请求 /thingsvis-api，重写为 ${VITE_THINGSVIS_API_URL}/api/v1
  const thingsvisTarget = env.VITE_THINGSVIS_API_URL

  if (thingsvisTarget) {
    proxy[THINGSVIS_API_PROXY_PATH] = {
      target: thingsvisTarget,
      changeOrigin: true,
      ws: true,
      rewrite: path => path.replace(new RegExp(`^${THINGSVIS_API_PROXY_PATH}`), '/api/v1')
    }
  }

  return proxy
}

/**
 * 文件用途：装配图标相关的 Vite 插件（本地 svg 雪碧图 + unplugin-icons 组件化图标）。
 * 核心逻辑：注册 `virtual:svg-icons-register` 雪碧图，并把 `Icon<Collection><Name>` 组件名解析为按需图标。
 * 关键注意事项：symbolId 必须与 `src/components/custom/svg-icon.vue` 的 `#${VITE_ICON_LOCAL_PREFIX}-${name}` 一致；
 *   `local` 自定义集合指向 `src/assets/svg-icon`，对应模板里的 `IconLocalAvatar` / `IconLocalLogo`。
 * 重构建议：新增图标集合时同步 package.json 依赖，避免出现模板引用了未安装的集合。
 */
import path from 'node:path'
import process from 'node:process'
import type { PluginOption } from 'vite'
import Icons from 'unplugin-icons/vite'
import { FileSystemIconLoader } from 'unplugin-icons/loaders'
import { createLocalSvgIconsPlugin } from './local-svg-icons'

/** 本地 svg 图标目录，同时用于雪碧图与 `local` 自定义集合 */
export const localIconPath = path.join(process.cwd(), 'src/assets/svg-icon')

export function setupIconPlugins(viteEnv: Env.ImportMeta): PluginOption[] {
  // These prefixes are public build conventions, not deployment secrets.
  const localPrefix = viteEnv.VITE_ICON_LOCAL_PREFIX || 'local-icon'
  const iconPrefix = viteEnv.VITE_ICON_PREFIX || 'icon'

  return [
    createLocalSvgIconsPlugin({
      iconDirs: [localIconPath],
      // 与 svg-icon.vue 的 `#${prefix}-${icon}` 保持一致，图标为平铺目录故不含 [dir]
      symbolId: `${localPrefix}-[name]`,
      inject: 'body-last',
      customDomId: '__SVG_ICON_LOCAL__'
    }),
    Icons({
      compiler: 'vue3',
      customCollections: {
        [localPrefix.replace(`${iconPrefix}-`, '')]: FileSystemIconLoader(localIconPath, svg =>
          svg.replace(/^<svg\s/, '<svg width="1em" height="1em" ')
        )
      },
      scale: 1,
      defaultClass: 'inline-block'
    })
  ]
}

/**
 * 文件用途：根据当前前端运行环境创建服务请求配置。
 * 核心逻辑：为 dev/test/prod 映射 baseURL、其他服务地址和 SSE 入口，默认 dev 指向本地后端。
 * 关键注意事项：这里的默认地址会影响所有请求代理，公开发布前不要写入真实共享环境或私有凭据。
 * 重构建议：建议将环境 URL 校验和 preview-proxy 规则抽成可测试配置函数。
 */
export function createServiceConfig(env: Env.ImportMeta) {
  // Keep the local default stable, but allow verification/development hosts
  // to point at a separately started backend without editing source files.
  const devURL = env.VITE_DEV_API_URL?.trim() || 'http://127.0.0.1:9999/api/v1';
  const testURL = '';
  const prodURL = '';

  const serviceConfigMap: App.Service.ServiceConfigMap = {
    dev: {
      baseURL: devURL,
      otherBaseURL: {
        platform: devURL
      },
      sseEndpoint: '/proxy-default/events'
    },
    test: {
      baseURL: testURL,
      otherBaseURL: {
        platform: testURL
      },
      sseEndpoint: '/api/v1/events'
    },
    prod: {
      baseURL: prodURL,
      otherBaseURL: {
        platform: prodURL
      },
      sseEndpoint: '/api/v1/events'
    }
  };

  const { VITE_SERVICE_ENV = 'dev' } = env;

  return serviceConfigMap[VITE_SERVICE_ENV];
}

/**
 * Get proxy pattern of service url.
 *
 * @param key If not set, the default service proxy is used.
 */
export function createProxyPattern(key?: App.Service.OtherBaseURLKey) {
  if (!key) {
    return '/proxy-default';
  }

  return `/proxy-${key}`;
}

/**
 * Get SSE endpoint URL by current env.
 */
export function getSSEEndpoint(env: Env.ImportMeta) {
  const serviceConfig = createServiceConfig(env);
  return serviceConfig.sseEndpoint;
}

