﻿#!/usr/bin/env node

/**
 * 文件用途：集中执行前端开发阶段的轻量质量检查和架构合规检查。
 * 核心逻辑：调用子命令、读取项目文件并输出彩色检查结果，帮助开发者提交前发现问题。
 * 关键注意事项：新增检查项时保持输出可读，并避免默认格式化整个前端。
 * 重构建议：建议将检查项拆成独立函数和配置清单，便于按 CI/本地场景复用。
 */

import { execSync } from 'child_process'
import fs from 'fs'
import path from 'path'

// 颜色输出
const colors = {
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
  reset: '\x1b[0m',
  bold: '\x1b[1m'
}

function log(message, color = 'reset') {}

function logSection(title) {
  log(`\n${colors.bold}${colors.cyan}${'='.repeat(60)}`, 'cyan')
  log(`${colors.bold}${colors.cyan}${title}`, 'cyan')
  log(`${colors.bold}${colors.cyan}${'='.repeat(60)}`, 'cyan')
}

function logSuccess(message) {
  log(`✅ ${message}`, 'green')
}

function logError(message) {
  log(`❌ ${message}`, 'red')
}

function logWarning(message) {
  log(`⚠️  ${message}`, 'yellow')
}

function logInfo(message) {
  log(`ℹ️  ${message}`, 'blue')
}

/**
 * 运行命令并返回结果
 */
function runCommand(command, description) {
  try {
    logInfo(`执行: ${description}`)
    const result = execSync(command, {
      encoding: 'utf8',
      stdio: 'pipe',
      timeout: 120000 // 2分钟超时
    })
    return { success: true, output: result }
  } catch (error) {
    return {
      success: false,
      error: error.message,
      output: error.stdout || error.stderr || ''
    }
  }
}

/**
 * 检查文件是否存在
 */
function checkFileExists(filePath, description) {
  if (fs.existsSync(filePath)) {
    logSuccess(`${description} 存在`)
    return true
  } else {
    logError(`${description} 不存在: ${filePath}`)
    return false
  }
}

/**
 * 检查 PanelV2 架构合规性
 */
function checkPanelV2Compliance() {
  logSection('PanelV2 架构合规性检查')

  const issues = []

  // 检查渲染器是否包含工具栏
  const rendererDir = path.join(process.cwd(), 'src/components/panelv2/renderers')
  if (!fs.existsSync(rendererDir)) {
    logInfo('panelv2 renderer directory not found; skipping PanelV2 compliance check')
    return true
  }

  const renderers = fs.readdirSync(rendererDir)

  renderers.forEach(renderer => {
    const rendererPath = path.join(rendererDir, renderer)
    if (fs.statSync(rendererPath).isDirectory()) {
      const mainRenderer = path.join(
        rendererPath,
        `${renderer.charAt(0).toUpperCase() + renderer.slice(1)}Renderer.vue`
      )

      if (fs.existsSync(mainRenderer)) {
        const content = fs.readFileSync(mainRenderer, 'utf8')

        // 检查是否包含工具栏相关代码
        if (content.includes('toolbar') && content.includes('<div') && content.includes('toolbar')) {
          issues.push(`${renderer} 渲染器可能包含内置工具栏，违反分离原则`)
        }

        // 检查是否使用主题系统
        if (!content.includes('useThemeStore') && content.includes('<style')) {
          issues.push(`${renderer} 渲染器未集成主题系统`)
        }

        // 检查图标使用是否正确
        const iconImports = content.match(/import.*from.*@vicons\/ionicons5/g)
        if (iconImports) {
          iconImports.forEach(importLine => {
            if (!importLine.includes('Outline')) {
              issues.push(`${renderer} 渲染器使用了错误的图标命名规范`)
            }
          })
        }
      }
    }
  })

  if (issues.length === 0) {
    logSuccess('PanelV2 架构合规性检查通过')
    return true
  } else {
    issues.forEach(issue => logError(issue))
    return false
  }
}

/**
 * 检查必要文件
 */
function checkRequiredFiles() {
  logSection('必要文件检查')

  const requiredFiles = [
    { path: 'README.md', desc: 'Frontend README' },
    { path: 'package.json', desc: 'Package 配置文件' }
  ]

  let allExist = true

  requiredFiles.forEach(file => {
    if (!checkFileExists(file.path, file.desc)) {
      allExist = false
    }
  })

  return allExist
}

/**
 * 代码质量检查
 */
function checkCodeQuality() {
  logSection('代码质量检查')

  const checks = [
    {
      command: 'pnpm lint --max-warnings 0',
      description: 'ESLint 代码规范检查',
      required: true
    },
    {
      command: 'pnpm typecheck',
      description: 'TypeScript 类型检查',
      required: true
    }
  ]

  let allPassed = true

  checks.forEach(check => {
    const result = runCommand(check.command, check.description)

    if (result.success) {
      logSuccess(`${check.description} 通过`)
    } else {
      logError(`${check.description} 失败`)
      if (result.output) {
        log(result.output, 'red')
      }
      if (check.required) {
        allPassed = false
      }
    }
  })

  return allPassed
}

/**
 * CSS 语法检查
 */
function checkCSSIssues() {
  logSection('CSS 语法检查')

  const vueFiles = []

  function findVueFiles(dir) {
    const items = fs.readdirSync(dir)

    items.forEach(item => {
      const fullPath = path.join(dir, item)
      const stat = fs.statSync(fullPath)

      if (stat.isDirectory() && !item.startsWith('.') && item !== 'node_modules') {
        findVueFiles(fullPath)
      } else if (item.endsWith('.vue')) {
        vueFiles.push(fullPath)
      }
    })
  }

  try {
    findVueFiles(path.join(process.cwd(), 'src'))
  } catch (error) {
    logWarning('无法扫描 Vue 文件')
    return true
  }

  let issues = []

  vueFiles.forEach(file => {
    try {
      const content = fs.readFileSync(file, 'utf8')

      // 检查常见的 CSS 语法错误
      const cssIssues = [
        {
          pattern: /justify-between;/,
          fix: 'justify-content: space-between;',
          desc: 'justify-between 应该是 justify-content: space-between'
        },
        { pattern: /align-center;/, fix: 'align-items: center;', desc: 'align-center 应该是 align-items: center' },
        { pattern: /#[0-9a-fA-F]{3,6}/, fix: 'CSS 变量', desc: '发现硬编码颜色，应使用主题变量' }
      ]

      cssIssues.forEach(issue => {
        if (issue.pattern.test(content)) {
          issues.push(`${file}: ${issue.desc}`)
        }
      })
    } catch (error) {
      // 忽略无法读取的文件
    }
  })

  if (issues.length === 0) {
    logSuccess('CSS 语法检查通过')
    return true
  } else {
    issues.forEach(issue => logWarning(issue))
    return issues.length < 5 // 少量问题不阻止提交
  }
}

/**
 * 生成质量报告
 */
function generateQualityReport(results) {
  logSection('质量检查报告')

  const passed = results.filter(r => r.passed).length
  const total = results.length
  const percentage = Math.round((passed / total) * 100)

  log(`\n检查项目: ${total}`)
  log(`通过项目: ${passed}`)
  log(`通过率: ${percentage}%`)

  if (percentage >= 90) {
    logSuccess('代码质量优秀 (A级)')
  } else if (percentage >= 80) {
    logInfo('代码质量良好 (B级)')
  } else if (percentage >= 70) {
    logWarning('代码质量一般 (C级)，建议改进')
  } else {
    logError('代码质量较差 (D级)，必须修复')
  }

  return percentage >= 70
}

/**
 * 主函数
 */
function main() {
  log(`${colors.bold}${colors.magenta}🚀 AetherLink IoT 开发质量检查工具`, 'magenta')
  log(`${colors.magenta}确保代码提交前符合项目质量标准\n`, 'magenta')

  const results = []

  // 执行各项检查
  results.push({ name: '必要文件检查', passed: checkRequiredFiles() })
  results.push({ name: 'PanelV2架构合规性', passed: checkPanelV2Compliance() })
  results.push({ name: '代码质量检查', passed: checkCodeQuality() })
  results.push({ name: 'CSS语法检查', passed: checkCSSIssues() })

  // 生成报告
  const overallPassed = generateQualityReport(results)

  // 输出建议
  logSection('改进建议')

  if (overallPassed) {
    logSuccess('恭喜！代码质量符合提交标准')
    log('\n📋 提交前请确认：')
    log('1. 已完成当前分支需要的提交前自检项')
    log('2. 功能已手动测试并正常工作')
    log('3. 在不同主题下样式显示正常')
    log('4. 浏览器控制台无错误和警告')
  } else {
    logError('代码质量不符合提交标准，请先修复问题')
    log('\n🔧 修复建议：')
    log('1. 运行 pnpm lint --fix 自动修复规范问题')
    log('2. 检查 TypeScript 类型错误并修复')
    log('3. 确保所有组件集成主题系统')
    log('4. 移除渲染器中的工具栏实现')
  }

  process.exit(overallPassed ? 0 : 1)
}

// 运行检查
main()

#!/usr/bin/env node

/**
 * 文件用途：扫描前端源码中的 console.log 并按上下文移除调试输出。
 * 核心逻辑：解析源码文本中的 console.log 调用位置，按文件遍历执行清理。
 * 关键注意事项：清理脚本可能误删带副作用的表达式，扩展规则时必须保持可审计和可回滚。
 * 重构建议：建议先增加 dry-run 与变更摘要，再考虑自动写回，降低批量清理风险。
 */

import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

/**
 * 提取所有 console.log 语句的位置和内容
 * 支持嵌套括号、字符串中的括号、模板字符串等复杂情况
 */
function findConsoleLogs(code) {
  const results = []
  const regex = /console\.log\s*\(/g
  let match

  while ((match = regex.exec(code)) !== null) {
    const start = match.index
    let pos = match.index + match[0].length
    let depth = 1
    let inString = false
    let stringChar = ''
    let escaped = false

    while (pos < code.length && depth > 0) {
      const char = code[pos]

      if (escaped) {
        escaped = false
      } else if (char === '\\') {
        escaped = true
      } else if (!inString && (char === '"' || char === "'" || char === '`')) {
        inString = true
        stringChar = char
      } else if (inString && char === stringChar) {
        inString = false
        stringChar = ''
      } else if (!inString) {
        if (char === '(') {
          depth++
        } else if (char === ')') {
          depth--
        }
      }

      pos++
    }

    if (depth === 0) {
      results.push({
        start,
        end: pos,
        content: code.substring(start, pos)
      })
    }
  }

  return results.reverse() // 反转数组，从后往前删除避免索引变化
}

/**
 * 分析 console.log 的上下文环境，判断如何安全删除
 */
function analyzeConsoleLogContext(code, start, end) {
  // 获取 console.log 前面的代码片段 (最多 300 个字符)
  const beforeCode = code.substring(Math.max(0, start - 300), start)
  // 获取 console.log 后面的代码片段 (最多 100 个字符)
  const afterCode = code.substring(end, Math.min(code.length, end + 100))

  // 检查是否在 try-catch-finally 块中
  const tryBlockPatterns = [
    /try\s*\{\s*$/, // try {
    /catch\s*\([^)]*\)\s*\{\s*$/, // catch (error) {
    /finally\s*\{\s*$/ // finally {
  ]

  const isInTryBlock = tryBlockPatterns.some(pattern => pattern.test(beforeCode.trim()))

  // 检查是否是 try-catch 块中的唯一语句
  const isTryCatchOnlyStatement = /try\s*\{\s*$/.test(beforeCode.trim()) && /^\s*\}\s*catch/.test(afterCode)

  const isCatchOnlyStatement = /catch\s*\([^)]*\)\s*\{\s*$/.test(beforeCode.trim()) && /^\s*\}/.test(afterCode)

  // 检查是否在箭头函数中 - 更精确的匹配
  const arrowFunctionPatterns = [
    /=>\s*$/, // 基本箭头函数: () =>
    /=>\s*console\.log/, // 直接跟console.log
    /"[^"]*=>\s*$/, // Vue模板中: @click="() =>
    /'[^']*=>\s*$/ // Vue模板中: @click='() =>
  ]

  const isInArrowFunction = arrowFunctionPatterns.some(pattern => pattern.test(beforeCode))

  // 检查是否在 Vue 模板的事件处理器中
  // 更精确的 Vue 事件处理器检测
  const vueEventPattern = /@\w+\s*=\s*["'][^"']*=>\s*console\.log/
  const isInVueEventHandler = vueEventPattern.test(beforeCode + 'console.log')

  // 检查 console.log 后是否直接跟着引号结束 (Vue 模板场景)
  const endsWithQuote = /^\s*["']/.test(afterCode)

  // 更通用的箭头函数检测 - 检查前面是否有 =>
  const hasArrowBefore = /=>\s*$/.test(beforeCode.trim())

  // 检查是否整行只有 console.log
  const lines = code.split('\n')
  let lineStart = code.lastIndexOf('\n', start - 1) + 1
  let lineEnd = code.indexOf('\n', end)
  if (lineEnd === -1) lineEnd = code.length

  const currentLine = code.substring(lineStart, lineEnd)
  const beforeLogInLine = code.substring(lineStart, start)
  const afterLogInLine = code.substring(end, lineEnd)

  const lineWithoutLog = (beforeLogInLine + afterLogInLine).trim()
  const isFullLine = lineWithoutLog === '' || lineWithoutLog === ';'

  // 检查是否在对象属性中
  const isInObjectProperty = /:\s*$/.test(beforeCode.trim())

  // 检查是否在函数调用的参数中
  const isInFunctionCall = /\(\s*$/.test(beforeCode.trim()) && /^\s*[,)]/.test(afterCode)

  // 检查是否在注释中
  const isInComment = checkIfInComment(code, start, end)

  return {
    isFullLine,
    isInArrowFunction,
    isInVueEventHandler,
    isInObjectProperty,
    isInFunctionCall,
    isInTryBlock,
    isTryCatchOnlyStatement,
    isCatchOnlyStatement,
    isInComment,
    endsWithQuote,
    hasArrowBefore,
    lineStart,
    lineEnd,
    beforeCode: beforeCode.slice(-80), // 调试用
    afterCode: afterCode.slice(0, 40) // 调试用
  }
}

/**
 * 检查 console.log 是否在注释中
 */
function checkIfInComment(code, start, end) {
  // 找到 console.log 所在的行
  const lineStart = code.lastIndexOf('\n', start - 1) + 1
  const lineEnd = code.indexOf('\n', start)
  const currentLine = code.substring(lineStart, lineEnd === -1 ? code.length : lineEnd)

  // 检查是否在单行注释中 // console.log(...)
  const singleLineCommentIndex = currentLine.indexOf('//')
  if (singleLineCommentIndex !== -1) {
    const consoleLogInLineIndex = start - lineStart
    if (consoleLogInLineIndex > singleLineCommentIndex) {
      return true
    }
  }

  // 检查是否在多行注释中 /* console.log(...) */
  const beforeConsoleLog = code.substring(0, start)
  const afterConsoleLog = code.substring(end)

  // 向前查找最近的 /* 和 */
  const lastMultiCommentStart = beforeConsoleLog.lastIndexOf('/*')
  const lastMultiCommentEnd = beforeConsoleLog.lastIndexOf('*/')

  // 向后查找最近的 */
  const nextMultiCommentEnd = afterConsoleLog.indexOf('*/')

  // 如果最近的 /* 在最近的 */ 之后，且后面有对应的 */，说明在多行注释中
  if (lastMultiCommentStart > lastMultiCommentEnd && nextMultiCommentEnd !== -1) {
    return true
  }

  return false
}

/**
 * 从代码中移除所有 console.log 语句
 * 智能处理各种语法结构，避免破坏代码
 */
function removeConsoleLogs(code) {
  const consoleLogs = findConsoleLogs(code)
  let result = code

  consoleLogs.forEach(log => {
    const beforeLog = result.substring(0, log.start)
    const afterLog = result.substring(log.end)

    // 分析上下文
    const context = analyzeConsoleLogContext(result, log.start, log.end)

    // 如果在注释中，跳过不处理
    if (context.isInComment) {
      return // 跳过这个 console.log，不做任何处理
    }

    if (context.isFullLine) {
      // 整行只有 console.log，删除整行包括换行符
      const lineStart = context.lineStart
      const lineEnd = context.lineEnd + (context.lineEnd < result.length ? 1 : 0) // +1 for \n
      result = result.substring(0, lineStart) + result.substring(lineEnd)
    } else if (context.isTryCatchOnlyStatement) {
      // try 块中只有 console.log，需要保持语法完整
      result = beforeLog + '// try block content removed' + afterLog
    } else if (context.isCatchOnlyStatement) {
      // catch 块中只有 console.log，需要保持语法完整
      result = beforeLog + '// catch block content removed' + afterLog
    } else if (context.isInTryBlock) {
      // 在 try-catch 块中，但不是唯一语句，直接删除
      result = beforeLog + afterLog
    } else if (context.hasArrowBefore && context.endsWithQuote) {
      // 箭头函数 + 引号结尾的情况（主要是Vue模板）
      // () => console.log(...)" 变成 () => {}"
      result = beforeLog + '{}' + afterLog
    } else if (context.hasArrowBefore) {
      // 普通箭头函数，不在引号中
      result = beforeLog + 'void 0' + afterLog
    } else if (context.isInVueEventHandler) {
      // Vue 模板事件处理器的其他情况
      result = beforeLog + '{}' + afterLog
    } else if (context.isInArrowFunction) {
      // 其他箭头函数情况的兜底
      if (context.endsWithQuote) {
        result = beforeLog + '{}' + afterLog
      } else {
        result = beforeLog + 'void 0' + afterLog
      }
    } else if (context.isInObjectProperty) {
      // 在对象属性中，替换为 undefined
      result = beforeLog + 'undefined' + afterLog
    } else if (context.isInFunctionCall) {
      // 在函数调用参数中，替换为 undefined
      result = beforeLog + 'undefined' + afterLog
    } else {
      // 其他情况，直接删除
      result = beforeLog + afterLog
    }
  })

  return result
}

/**
 * 递归获取指定目录下的所有文件
 */
function getAllFiles(dir, fileTypes = ['.js', '.ts', '.vue']) {
  const files = []

  function traverse(currentDir) {
    const entries = fs.readdirSync(currentDir, { withFileTypes: true })

    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name)

      if (entry.isDirectory()) {
        // 跳过 node_modules、dist、.git 等目录
        if (!['node_modules', 'dist', 'build', '.git', '.nuxt', '.next', 'coverage'].includes(entry.name)) {
          traverse(fullPath)
        }
      } else if (entry.isFile()) {
        const ext = path.extname(entry.name)
        if (fileTypes.includes(ext)) {
          files.push(fullPath)
        }
      }
    }
  }

  traverse(dir)
  return files
}

/**
 * 处理单个文件
 */
function processFile(filePath) {
  try {
    const originalContent = fs.readFileSync(filePath, 'utf8')
    const cleanedContent = removeConsoleLogs(originalContent)

    if (originalContent !== cleanedContent) {
      fs.writeFileSync(filePath, cleanedContent, 'utf8')

      // 统计删除的 console.log 数量
      const originalLogs = findConsoleLogs(originalContent)
      const remainingLogs = findConsoleLogs(cleanedContent)
      const removedCount = originalLogs.length - remainingLogs.length

      return removedCount
    }

    return 0
  } catch (error) {
    console.error(`❌ 处理文件失败 ${filePath}:`, error.message)
    return 0
  }
}

/**
 * 主函数
 */
function main() {
  const projectRoot = process.cwd()

  // 获取所有需要处理的文件
  const files = getAllFiles(projectRoot)

  let totalRemoved = 0
  let processedFiles = 0

  // 处理每个文件
  files.forEach(filePath => {
    const removed = processFile(filePath)
    if (removed > 0) {
      totalRemoved += removed
      processedFiles++
    }
  })

  if (totalRemoved === 0) {
    /* intentionally empty */
  }
}

// 运行脚本
const __filename = fileURLToPath(import.meta.url)
if (process.argv[1] === __filename) {
  main()
}

export { findConsoleLogs, removeConsoleLogs, processFile, getAllFiles }

import { existsSync, readdirSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { join } from 'node:path';
import process from 'node:process';

const packagesDir = join(process.cwd(), 'packages');
const packageDirs = readdirSync(packagesDir, { withFileTypes: true })
  .filter(entry => entry.isDirectory())
  .map(entry => entry.name)
  .sort();

for (const packageDir of packageDirs) {
  const config = join('packages', packageDir, 'tsconfig.json');
  if (!existsSync(config)) continue;
  const pnpmEntry = process.env.npm_execpath;
  if (!pnpmEntry) {
    console.error('typecheck:packages must be run through pnpm');
    process.exit(1);
  }
  const result = spawnSync(process.execPath, [pnpmEntry, 'exec', 'tsc', '--project', config, '--noEmit', '--skipLibCheck'], {
    cwd: process.cwd(),
    encoding: 'utf8'
  });
  process.stdout.write(result.stdout ?? '');
  process.stderr.write(result.stderr ?? '');
  if (result.status !== 0) process.exit(result.status ?? 1);
}

