/**
 * 文件用途：提供 Grid Layout Plus 的校验、几何计算、布局变换、导入导出与性能辅助工具。
 * 核心逻辑：围绕网格项集合执行校验、碰撞判断、紧凑化、响应式转换和序列化处理。
 * 关键注意事项：这里的结果会直接影响布局持久化与回放，坐标、尺寸和碰撞规则必须保持稳定。
 * 重构建议：后续可按“校验 / 几何 / 持久化 / 性能”拆分子模块，降低单文件复杂度。
 */

import type {
  GridLayoutPlusItem,
  GridLayoutPlusConfig,
  LayoutOperationResult,
  ResponsiveLayout,
  PerformanceConfig
} from './gridLayoutPlusTypes'

/**
 * 验证网格项
 */
export function validateGridItem(item: GridLayoutPlusItem): LayoutOperationResult<boolean> {
  try {
    // 检查必要字段
    if (!item.i || typeof item.i !== 'string') {
      return {
        success: false,
        error: new Error('Grid item must have a valid string id'),
        message: '网格项必须有有效的字符串ID'
      }
    }

    // 检查位置和尺寸
    if (item.x < 0 || item.y < 0) {
      return {
        success: false,
        error: new Error('Grid position must be >= 0'),
        message: '网格位置必须大于等于0'
      }
    }

    if (item.w <= 0 || item.h <= 0) {
      return {
        success: false,
        error: new Error('Grid size must be > 0'),
        message: '网格尺寸必须大于0'
      }
    }

    // 检查约束条件
    if (item.minW && item.w < item.minW) {
      return {
        success: false,
        error: new Error('Width is less than minimum'),
        message: '宽度小于最小值'
      }
    }

    if (item.maxW && item.w > item.maxW) {
      return {
        success: false,
        error: new Error('Width exceeds maximum'),
        message: '宽度超过最大值'
      }
    }

    if (item.minH && item.h < item.minH) {
      return {
        success: false,
        error: new Error('Height is less than minimum'),
        message: '高度小于最小值'
      }
    }

    if (item.maxH && item.h > item.maxH) {
      return {
        success: false,
        error: new Error('Height exceeds maximum'),
        message: '高度超过最大值'
      }
    }

    return { success: true, data: true }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '网格项验证失败'
    }
  }
}

/**
 * 验证布局
 */
export function validateLayout(layout: GridLayoutPlusItem[]): LayoutOperationResult<boolean> {
  try {
    // 检查ID唯一性
    const ids = layout.map(item => item.i)
    const uniqueIds = new Set(ids)
    if (ids.length !== uniqueIds.size) {
      return {
        success: false,
        error: new Error('Duplicate item IDs found'),
        message: '发现重复ID'
      }
    }

    // 检查每个项目
    for (const item of layout) {
      const itemValidation = validateGridItem(item)
      if (!itemValidation.success) {
        return itemValidation
      }
    }

    return { success: true, data: true }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '布局验证失败'
    }
  }
}

/**
 * 检查两个项目是否重叠
 */
export function isItemsOverlapping(item1: GridLayoutPlusItem, item2: GridLayoutPlusItem): boolean {
  return !(
    item1.x + item1.w <= item2.x ||
    item1.x >= item2.x + item2.w ||
    item1.y + item1.h <= item2.y ||
    item1.y >= item2.y + item2.h
  )
}

/**
 * 寻找可用位置
 */
export function findAvailablePosition(
  w: number,
  h: number,
  layout: GridLayoutPlusItem[],
  colNum: number = 12
): { x: number; y: number } {
  // 采用从左到右、从上到下的顺序扫描，保证初次放置结果稳定可预测。
  for (let y = 0; y < 100; y++) {
    for (let x = 0; x <= colNum - w; x++) {
      const proposed = { x, y, w, h, i: 'temp' }

      // 检查是否与现有项目冲突
      const hasCollision = layout.some(item => isItemsOverlapping(proposed, item))

      if (!hasCollision) {
        return { x, y }
      }
    }
  }

  return { x: 0, y: 0 }
}

/**
 * 生成唯一ID
 */
export function generateId(prefix: string = 'item'): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`
}

/**
 * 深度克隆网格项
 */
export function cloneGridItem(item: GridLayoutPlusItem): GridLayoutPlusItem {
  return {
    ...item,
    props: item.props ? JSON.parse(JSON.stringify(item.props)) : undefined,
    data: item.data ? JSON.parse(JSON.stringify(item.data)) : undefined,
    style: item.style ? { ...item.style } : undefined,
    metadata: item.metadata ? JSON.parse(JSON.stringify(item.metadata)) : undefined
  }
}

/**
 * 批量克隆网格项
 */
export function cloneLayout(layout: GridLayoutPlusItem[]): GridLayoutPlusItem[] {
  return layout.map(cloneGridItem)
}

/**
 * 计算布局边界
 */
export function getLayoutBounds(layout: GridLayoutPlusItem[]): {
  minX: number
  minY: number
  maxX: number
  maxY: number
  width: number
  height: number
} {
  if (layout.length === 0) {
    return { minX: 0, minY: 0, maxX: 0, maxY: 0, width: 0, height: 0 }
  }

  const minX = Math.min(...layout.map(item => item.x))
  const minY = Math.min(...layout.map(item => item.y))
  const maxX = Math.max(...layout.map(item => item.x + item.w))
  const maxY = Math.max(...layout.map(item => item.y + item.h))

  return {
    minX,
    minY,
    maxX,
    maxY,
    width: maxX - minX,
    height: maxY - minY
  }
}

/**
 * 紧凑布局
 */
export function compactLayout(layout: GridLayoutPlusItem[]): GridLayoutPlusItem[] {
  const sortedLayout = [...layout].sort((a, b) => {
    if (a.y !== b.y) return a.y - b.y
    return a.x - b.x
  })

  const compacted: GridLayoutPlusItem[] = []

  for (const item of sortedLayout) {
    let newY = 0

    // 仅向上压缩，不改变列位置，避免产生额外的横向抖动。
    while (newY <= item.y) {
      const tempItem = { ...item, y: newY }
      const hasCollision = compacted.some(placedItem => isItemsOverlapping(tempItem, placedItem))

      if (!hasCollision) {
        break
      }

      newY++
    }

    compacted.push({ ...item, y: newY })
  }

  return compacted
}

/**
 * 布局排序
 */
export function sortLayout(
  layout: GridLayoutPlusItem[],
  sortBy: 'position' | 'size' | 'id' = 'position'
): GridLayoutPlusItem[] {
  return [...layout].sort((a, b) => {
    switch (sortBy) {
      case 'position':
        if (a.y !== b.y) return a.y - b.y
        return a.x - b.x
      case 'size': {
        const sizeA = a.w * a.h
        const sizeB = b.w * b.h
        return sizeB - sizeA // 大的在前
      }
      case 'id':
        return a.i.localeCompare(b.i)
      default:
        return 0
    }
  })
}

/**
 * 过滤布局
 */
export function filterLayout(
  layout: GridLayoutPlusItem[],
  predicate: (item: GridLayoutPlusItem) => boolean
): GridLayoutPlusItem[] {
  return layout.filter(predicate)
}

/**
 * 搜索布局项
 */
export function searchLayout(
  layout: GridLayoutPlusItem[],
  query: string,
  searchFields: (keyof GridLayoutPlusItem)[] = ['i', 'type', 'title']
): GridLayoutPlusItem[] {
  const lowercaseQuery = query.toLowerCase()

  return layout.filter(item => {
    return searchFields.some(field => {
      const value = item[field]
      if (typeof value === 'string') {
        return value.toLowerCase().includes(lowercaseQuery)
      }
      return false
    })
  })
}

/**
 * 布局统计信息
 */
export function getLayoutStats(layout: GridLayoutPlusItem[], colNum: number = 12) {
  const bounds = getLayoutBounds(layout)
  const totalCells = bounds.width * bounds.height
  const usedCells = layout.reduce((sum, item) => sum + item.w * item.h, 0)

  return {
    totalItems: layout.length,
    totalRows: bounds.height,
    totalCells,
    usedCells,
    utilization: totalCells > 0 ? (usedCells / totalCells) * 100 : 0,
    bounds,
    largestItem: layout.reduce(
      (largest, item) => {
        const size = item.w * item.h
        const largestSize = largest ? largest.w * largest.h : 0
        return size > largestSize ? item : largest
      },
      null as GridLayoutPlusItem | null
    ),
    smallestItem: layout.reduce(
      (smallest, item) => {
        const size = item.w * item.h
        const smallestSize = smallest ? smallest.w * smallest.h : Infinity
        return size < smallestSize ? item : smallest
      },
      null as GridLayoutPlusItem | null
    ),
    averageSize: layout.length > 0 ? layout.reduce((sum, item) => sum + item.w * item.h, 0) / layout.length : 0
  }
}

/**
 * 响应式布局转换
 */
export function transformLayoutForBreakpoint(
  layout: GridLayoutPlusItem[],
  fromCols: number,
  toCols: number
): GridLayoutPlusItem[] {
  if (fromCols === toCols) return cloneLayout(layout)

  const scale = toCols / fromCols

  return layout.map(item => ({
    ...item,
    x: Math.round(item.x * scale),
    w: Math.max(1, Math.round(item.w * scale))
    // y 和 h 保持不变，只按列数变化重算水平方向，减少垂直布局跳变。
  }))
}

/**
 * 创建响应式布局
 */
export function createResponsiveLayout(
  baseLayout: GridLayoutPlusItem[],
  breakpoints: Record<string, number>,
  cols: Record<string, number>
): ResponsiveLayout {
  const responsive: ResponsiveLayout = {}
  const baseCols = cols.lg || 12

  Object.keys(breakpoints).forEach(breakpoint => {
    const targetCols = cols[breakpoint] || baseCols
    responsive[breakpoint as keyof ResponsiveLayout] = transformLayoutForBreakpoint(baseLayout, baseCols, targetCols)
  })

  return responsive
}

/**
 * 优化布局性能
 */
export function optimizeLayoutPerformance(
  layout: GridLayoutPlusItem[],
  config: PerformanceConfig
): GridLayoutPlusItem[] {
  let optimizedLayout = [...layout]
  const virtualizationThreshold = config.virtualizationThreshold ?? Number.POSITIVE_INFINITY

  // 这里只保留配置分流入口，真正的可视区域裁剪要结合容器尺寸和滚动状态实现。
  if (config.enableLazyLoading) {
    // 当前没有容器可见区上下文，保持完整布局，避免错误裁剪。
  }

  // 超过阈值后预留虚拟化分支，避免调用方误以为所有项目都会无条件渲染。
  if (config.enableVirtualization && layout.length > virtualizationThreshold) {
    // 虚拟化由渲染层根据滚动窗口处理，此工具函数不删除布局项目。
  }

  return optimizedLayout
}

/**
 * 防抖函数
 */
export function debounce<T extends (...args: any[]) => any>(func: T, delay: number): (...args: Parameters<T>) => void {
  let timeoutId: NodeJS.Timeout
  return (...args: Parameters<T>) => {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => func(...args), delay)
  }
}

/**
 * 节流函数
 */
export function throttle<T extends (...args: any[]) => any>(func: T, delay: number): (...args: Parameters<T>) => void {
  let lastCall = 0
  return (...args: Parameters<T>) => {
    const now = Date.now()
    if (now - lastCall >= delay) {
      lastCall = now
      func(...args)
    }
  }
}

/**
 * 布局导出
 */
export function exportLayout(layout: GridLayoutPlusItem[], format: 'json' | 'csv' = 'json'): string {
  switch (format) {
    case 'json':
      return JSON.stringify(layout, null, 2)
    case 'csv': {
      const headers = ['i', 'x', 'y', 'w', 'h', 'type', 'title']
      const csvRows = [
        headers.join(','),
        ...layout.map(item => headers.map(header => item[header as keyof GridLayoutPlusItem] || '').join(','))
      ]
      return csvRows.join('\n')
    }
    default:
      return JSON.stringify(layout)
  }
}

/**
 * 布局导入
 */
export function importLayout(data: string, format: 'json' | 'csv' = 'json'): GridLayoutPlusItem[] {
  try {
    switch (format) {
      case 'json':
        return JSON.parse(data)
      case 'csv': {
        const lines = data.split('\n')
        const headers = lines[0].split(',')
        return lines.slice(1).map(line => {
          const values = line.split(',')
          const item: any = {}
          headers.forEach((header, index) => {
            const value = values[index]
            if (['x', 'y', 'w', 'h'].includes(header)) {
              item[header] = parseInt(value) || 0
            } else {
              item[header] = value
            }
          })
          return item as GridLayoutPlusItem
        })
      }
      default:
        return JSON.parse(data)
    }
  } catch {
    return []
  }
}

/**
 * 获取项目在指定断点的配置
 */
export function getItemAtBreakpoint(
  item: GridLayoutPlusItem,
  breakpoint: string,
  responsiveLayout?: ResponsiveLayout
): GridLayoutPlusItem {
  if (responsiveLayout && responsiveLayout[breakpoint as keyof ResponsiveLayout]) {
    const breakpointLayout = responsiveLayout[breakpoint as keyof ResponsiveLayout]!
    const found = breakpointLayout.find(i => i.i === item.i)
    if (found) return found
  }
  return item
}

/**
 * 文件用途：提供网格交互的性能辅助 hooks。
 * 核心逻辑：封装节流、批处理、可见性或缓存相关逻辑，降低拖拽缩放时的频繁更新成本。
 * 关键注意事项：性能优化不能改变布局事件顺序，调整节流窗口时需验证拖拽和历史记录行为。
 * 重构建议：可按事件节流、渲染调度和缓存策略继续拆分，便于独立测试。
 */
import { ref, computed, nextTick, onMounted, onUnmounted } from 'vue'
import type { Ref } from 'vue'
import type { GridLayoutPlusItem, PerformanceConfig } from '../gridLayoutPlusTypes'
import { debounce, throttle } from '../gridLayoutPlusUtils'
import { createLogger } from '../../../../utils/logger'

const gridPerformanceLogger = createLogger('GridPerformance')
const MAX_HISTORY_LENGTH = 100
const DEFAULT_VIRTUALIZATION_THRESHOLD = 100
const DEFAULT_CONFIG: PerformanceConfig = {
  enableVirtualization: false,
  virtualizationThreshold: DEFAULT_VIRTUALIZATION_THRESHOLD,
  debounceDelay: 100,
  throttleDelay: 16,
  enableLazyLoading: false,
  lazyLoadingBuffer: 5
}

export interface UseGridPerformanceOptions {
  performanceConfig?: Partial<PerformanceConfig>
  enableMonitoring?: boolean
  monitoringInterval?: number
  autoOptimize?: boolean
}

export interface PerformanceMetrics {
  renderTime: number
  layoutTime: number
  itemCount: number
  memoryUsage: number
  fps: number
  lastUpdated: number
}

interface PerformanceReport {
  current: PerformanceMetrics
  average: Pick<PerformanceMetrics, 'renderTime' | 'layoutTime' | 'fps' | 'memoryUsage'>
  score: number
  suggestions: string[]
  historyLength: number
}

interface PerformanceMonitorOptions {
  enabled: boolean
  interval: number
  isMonitoring: Ref<boolean>
  metrics: Ref<PerformanceMetrics>
  history: Ref<PerformanceMetrics[]>
  onSample: () => void
}

function createPerformanceConfig(overrides: Partial<PerformanceConfig>): PerformanceConfig {
  return {
    ...DEFAULT_CONFIG,
    ...overrides,
    virtualizationThreshold: overrides.virtualizationThreshold ?? DEFAULT_VIRTUALIZATION_THRESHOLD
  }
}

function createInitialMetrics(): PerformanceMetrics {
  return {
    renderTime: 0,
    layoutTime: 0,
    itemCount: 0,
    memoryUsage: 0,
    fps: 60,
    lastUpdated: Date.now()
  }
}

function getVirtualizationThreshold(config: PerformanceConfig): number {
  return config.virtualizationThreshold ?? DEFAULT_VIRTUALIZATION_THRESHOLD
}

function calculatePerformanceScore(metrics: PerformanceMetrics): number {
  const { renderTime, layoutTime, fps, itemCount } = metrics
  let score = 100

  if (renderTime > 16) score -= Math.min(30, (renderTime - 16) / 2)
  if (layoutTime > 10) score -= Math.min(20, (layoutTime - 10) / 2)
  if (fps < 60) score -= Math.min(25, (60 - fps) / 2)
  if (itemCount > 50) score -= Math.min(25, (itemCount - 50) / 10)

  return Math.max(0, Math.floor(score))
}

function buildOptimizationSuggestions(metrics: PerformanceMetrics, config: PerformanceConfig): string[] {
  const suggestions: string[] = []
  const { renderTime, layoutTime, itemCount, fps } = metrics

  if (itemCount >= getVirtualizationThreshold(config) && !config.enableVirtualization) {
    suggestions.push('建议启用虚拟化以提高大数据集性能')
  }
  if (renderTime > 16) {
    suggestions.push('渲染时间过长，考虑减少DOM操作或启用防抖')
  }
  if (layoutTime > 10) {
    suggestions.push('布局计算耗时较长，考虑优化布局算法')
  }
  if (fps < 45) {
    suggestions.push('帧率较低，建议减少动画效果或优化渲染')
  }
  if (!config.enableLazyLoading && itemCount > 30) {
    suggestions.push('考虑启用懒加载以改善初始加载性能')
  }

  return suggestions
}

function appendPerformanceHistory(history: Ref<PerformanceMetrics[]>, metrics: PerformanceMetrics) {
  history.value.push({ ...metrics })
  if (history.value.length > MAX_HISTORY_LENGTH) {
    history.value.shift()
  }
}

function estimateLayoutMemory(layout: GridLayoutPlusItem[]): number {
  const itemSize = 200
  const layoutSize = JSON.stringify(layout).length * 2
  return (layout.length * itemSize + layoutSize) / 1024
}

function averagePerformanceHistory(history: PerformanceMetrics[]) {
  const totals = history.reduce(
    (acc, metric) => ({
      renderTime: acc.renderTime + metric.renderTime,
      layoutTime: acc.layoutTime + metric.layoutTime,
      fps: acc.fps + metric.fps,
      memoryUsage: acc.memoryUsage + metric.memoryUsage
    }),
    { renderTime: 0, layoutTime: 0, fps: 0, memoryUsage: 0 }
  )

  return {
    renderTime: totals.renderTime / history.length,
    layoutTime: totals.layoutTime / history.length,
    fps: totals.fps / history.length,
    memoryUsage: totals.memoryUsage / history.length
  }
}

function buildPerformanceReport(
  history: PerformanceMetrics[],
  current: PerformanceMetrics,
  score: number,
  suggestions: string[]
): PerformanceReport | null {
  if (history.length === 0) return null

  return {
    current,
    average: averagePerformanceHistory(history),
    score,
    suggestions,
    historyLength: history.length
  }
}

function createMeasurementTools(metrics: Ref<PerformanceMetrics>) {
  const measureRenderTime = async (renderFn: () => Promise<void> | void) => {
    const startTime = performance.now()

    try {
      await renderFn()
      await nextTick()
    } catch (error) {
      console.error('[GridPerformance] Render function error:', error)
    }

    const renderTime = performance.now() - startTime
    metrics.value.renderTime = renderTime
    metrics.value.lastUpdated = Date.now()
    return renderTime
  }

  const measureLayoutTime = (layoutFn: () => void) => {
    const startTime = performance.now()

    try {
      layoutFn()
    } catch (error) {
      console.error('[GridPerformance] Layout function error:', error)
    }

    const layoutTime = performance.now() - startTime
    metrics.value.layoutTime = layoutTime
    metrics.value.lastUpdated = Date.now()
    return layoutTime
  }

  const estimateMemoryUsage = (layout: GridLayoutPlusItem[]) => {
    try {
      const totalSize = estimateLayoutMemory(layout)
      metrics.value.memoryUsage = totalSize
      return totalSize
    } catch (error) {
      console.error('[GridPerformance] Failed to estimate memory usage:', error)
      return 0
    }
  }

  return {
    measureRenderTime,
    measureLayoutTime,
    estimateMemoryUsage
  }
}

function createOptimizationTools(config: Ref<PerformanceConfig>, metrics: Ref<PerformanceMetrics>) {
  const applyAutoOptimizations = () => {
    const { itemCount, renderTime } = metrics.value
    let optimized = false

    if (renderTime > 20 && config.value.debounceDelay < 200) {
      config.value.debounceDelay = Math.min(200, config.value.debounceDelay + 50)
      optimized = true
      gridPerformanceLogger.debug(`Increased debounce delay to ${config.value.debounceDelay}ms`)
    }
    if (itemCount > 30 && !config.value.enableLazyLoading) {
      config.value.enableLazyLoading = true
      optimized = true
      gridPerformanceLogger.debug('Auto-enabled lazy loading')
    }

    return optimized
  }

  const createDebouncedFunction = <T extends (...args: any[]) => any>(fn: T, customDelay?: number) => {
    return debounce(fn, customDelay || config.value.debounceDelay)
  }

  const createThrottledFunction = <T extends (...args: any[]) => any>(fn: T, customDelay?: number) => {
    return throttle(fn, customDelay || config.value.throttleDelay)
  }

  return {
    applyAutoOptimizations,
    createDebouncedFunction,
    createThrottledFunction
  }
}

function createFpsMonitor(isMonitoring: Ref<boolean>, metrics: Ref<PerformanceMetrics>) {
  let frameCount = 0
  let startTime = 0
  let animationFrameId = 0

  const measure = () => {
    const now = performance.now()
    if (startTime === 0) {
      startTime = now
      frameCount = 0
    }

    frameCount++
    if (now - startTime >= 1000) {
      metrics.value.fps = Math.round((frameCount * 1000) / (now - startTime))
      startTime = now
      frameCount = 0
    }

    if (isMonitoring.value) {
      animationFrameId = requestAnimationFrame(measure)
    }
  }

  return {
    start() {
      startTime = 0
      frameCount = 0
      measure()
    },
    stop() {
      if (animationFrameId) {
        cancelAnimationFrame(animationFrameId)
        animationFrameId = 0
      }
    }
  }
}

function createPerformanceMonitor(options: PerformanceMonitorOptions) {
  const fpsMonitor = createFpsMonitor(options.isMonitoring, options.metrics)
  let timer: ReturnType<typeof setInterval> | null = null

  const startMonitoring = () => {
    if (options.isMonitoring.value || !options.enabled) return

    options.isMonitoring.value = true
    fpsMonitor.start()
    timer = setInterval(() => {
      appendPerformanceHistory(options.history, options.metrics.value)
      options.onSample()
    }, options.interval)

    gridPerformanceLogger.debug('Monitoring started')
  }

  const stopMonitoring = () => {
    if (!options.isMonitoring.value) return

    options.isMonitoring.value = false
    fpsMonitor.stop()
    if (timer) {
      clearInterval(timer)
      timer = null
    }

    gridPerformanceLogger.debug('Monitoring stopped')
  }

  return {
    startMonitoring,
    stopMonitoring
  }
}

export function useGridPerformance(options: UseGridPerformanceOptions = {}) {
  const { performanceConfig = {}, enableMonitoring = true, monitoringInterval = 1000, autoOptimize = false } = options
  const config = ref<PerformanceConfig>(createPerformanceConfig(performanceConfig))
  const metrics = ref<PerformanceMetrics>(createInitialMetrics())
  const isMonitoring = ref(false)
  const performanceHistory = ref<PerformanceMetrics[]>([])

  const needsVirtualization = computed(() => {
    return metrics.value.itemCount >= getVirtualizationThreshold(config.value)
  })
  const performanceScore = computed(() => calculatePerformanceScore(metrics.value))
  const optimizationSuggestions = computed(() => buildOptimizationSuggestions(metrics.value, config.value))
  const measurementTools = createMeasurementTools(metrics)
  const optimizationTools = createOptimizationTools(config, metrics)
  const monitor = createPerformanceMonitor({
    enabled: enableMonitoring,
    interval: monitoringInterval,
    isMonitoring,
    metrics,
    history: performanceHistory,
    onSample: () => {
      if (autoOptimize && performanceScore.value < 60) {
        optimizationTools.applyAutoOptimizations()
      }
    }
  })

  const getPerformanceReport = () => {
    return buildPerformanceReport(
      performanceHistory.value,
      metrics.value,
      performanceScore.value,
      optimizationSuggestions.value
    )
  }

  onMounted(() => {
    if (enableMonitoring) {
      monitor.startMonitoring()
    }
  })

  onUnmounted(() => {
    monitor.stopMonitoring()
  })

  return {
    config,
    metrics,
    performanceScore,
    needsVirtualization,
    optimizationSuggestions,
    isMonitoring,
    startMonitoring: monitor.startMonitoring,
    stopMonitoring: monitor.stopMonitoring,
    measureRenderTime: measurementTools.measureRenderTime,
    measureLayoutTime: measurementTools.measureLayoutTime,
    estimateMemoryUsage: measurementTools.estimateMemoryUsage,
    createDebouncedFunction: optimizationTools.createDebouncedFunction,
    createThrottledFunction: optimizationTools.createThrottledFunction,
    applyAutoOptimizations: optimizationTools.applyAutoOptimizations,
    getPerformanceReport,
    performanceHistory
  }
}

/**
 * 文件用途：提供网格工具中的基础几何和数据处理函数。
 * 核心逻辑：围绕布局项坐标、尺寸、排序和集合处理提供可复用纯函数。
 * 关键注意事项：基础工具被多个 hook 复用，返回值应保持无副作用和可预测。
 * 重构建议：可按几何计算、集合操作和默认值处理继续拆分，减少单文件职责。
 */
import type { GridLayoutPlusItem } from '../gridLayoutPlusTypes'

/**
 * 生成唯一ID
 */
export function generateId(prefix = 'item'): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
}

/**
 * 深度克隆布局
 */
export function cloneLayout(layout: GridLayoutPlusItem[]): GridLayoutPlusItem[] {
  try {
    return JSON.parse(JSON.stringify(layout))
  } catch (error) {
    console.error('Failed to clone layout:', error)
    return layout.map(item => ({ ...item }))
  }
}

/**
 * 深度克隆网格项
 */
export function cloneGridItem(item: GridLayoutPlusItem): GridLayoutPlusItem {
  try {
    return JSON.parse(JSON.stringify(item))
  } catch (error) {
    console.error('Failed to clone grid item:', error)
    return { ...item }
  }
}

/**
 * 汇总布局的基础统计指标，供调试面板、监控信息和轻量分析使用。
 */
export function getLayoutStats(
  layout: GridLayoutPlusItem[],
  cols: number
): {
  totalItems: number
  totalRows: number
  utilization: number
  density: number
  averageSize: number
  largestItem: { id: string; area: number } | null
  smallestItem: { id: string; area: number } | null
} {
  try {
    if (layout.length === 0) {
      return {
        totalItems: 0,
        totalRows: 0,
        utilization: 0,
        density: 0,
        averageSize: 0,
        largestItem: null,
        smallestItem: null
      }
    }

    const totalItems = layout.length
    const totalRows = Math.max(...layout.map(item => item.y + item.h), 1)
    const totalCells = cols * totalRows

    // 计算所有项目占用的网格单元总数
    const occupiedCells = layout.reduce((sum, item) => sum + item.w * item.h, 0)

    const utilization = totalCells > 0 ? (occupiedCells / totalCells) * 100 : 0
    const density = totalItems > 0 ? occupiedCells / totalItems : 0
    const averageSize = totalItems > 0 ? occupiedCells / totalItems : 0

    // 找到最大和最小的项目
    let largestItem: { id: string; area: number } | null = null
    let smallestItem: { id: string; area: number } | null = null
    let maxArea = 0
    let minArea = Infinity

    for (const item of layout) {
      const area = item.w * item.h

      if (area > maxArea) {
        maxArea = area
        largestItem = { id: item.i, area }
      }

      if (area < minArea) {
        minArea = area
        smallestItem = { id: item.i, area }
      }
    }

    return {
      totalItems,
      totalRows,
      utilization,
      density,
      averageSize,
      largestItem,
      smallestItem
    }
  } catch (error) {
    console.error('Failed to get layout stats:', error)
    return {
      totalItems: layout.length,
      totalRows: 0,
      utilization: 0,
      density: 0,
      averageSize: 0,
      largestItem: null,
      smallestItem: null
    }
  }
}

/**
 * 过滤布局项目
 */
export function filterLayout(
  layout: GridLayoutPlusItem[],
  predicate: (item: GridLayoutPlusItem, index: number) => boolean
): GridLayoutPlusItem[] {
  try {
    return layout.filter(predicate)
  } catch (error) {
    console.error('Failed to filter layout:', error)
    return layout
  }
}

/**
 * 搜索布局项目
 */
export function searchLayout(
  layout: GridLayoutPlusItem[],
  query: string,
  searchFields: Array<keyof GridLayoutPlusItem> = ['i', 'type', 'title']
): GridLayoutPlusItem[] {
  try {
    if (!query.trim()) return layout

    const lowerQuery = query.toLowerCase()

    return layout.filter(item => {
      return searchFields.some(field => {
        const value = item[field]
        if (typeof value === 'string') {
          return value.toLowerCase().includes(lowerQuery)
        }
        if (typeof value === 'number') {
          return value.toString().includes(query)
        }
        return false
      })
    })
  } catch (error) {
    console.error('Failed to search layout:', error)
    return layout
  }
}

/**
 * 项目转换为CSS Grid区域定义
 */
/**
 * 把内部 0 基网格坐标转换成 CSS Grid `grid-area` 可直接使用的字符串。
 */
export function itemToGridArea(item: GridLayoutPlusItem): string {
  try {
    // CSS Grid 的行和列从1开始计数
    const rowStart = item.y + 1
    const rowEnd = item.y + item.h + 1
    const colStart = item.x + 1
    const colEnd = item.x + item.w + 1

    return `${rowStart} / ${colStart} / ${rowEnd} / ${colEnd}`
  } catch (error) {
    console.error('Failed to convert item to grid area:', error)
    return 'auto'
  }
}

/**
 * 计算网格利用率
 */
export function calculateGridUtilization(layout: GridLayoutPlusItem[], cols: number, rows?: number): number {
  try {
    if (layout.length === 0) return 0

    const actualRows = rows || Math.max(...layout.map(item => item.y + item.h), 1)
    const totalCells = cols * actualRows
    const occupiedCells = layout.reduce((sum, item) => sum + item.w * item.h, 0)

    return totalCells > 0 ? (occupiedCells / totalCells) * 100 : 0
  } catch (error) {
    console.error('Failed to calculate grid utilization:', error)
    return 0
  }
}

/**
 * 计算总行数
 */
export function calculateTotalRows(layout: GridLayoutPlusItem[], minRows = 0): number {
  try {
    if (layout.length === 0) return minRows
    return Math.max(...layout.map(item => item.y + item.h), minRows)
  } catch (error) {
    console.error('Failed to calculate total rows:', error)
    return minRows
  }
}

export function calculateColWidth(config: any, containerWidth: number): number {
  const columns = Number(config.columns ?? config.colNum ?? 12)
  const gap = Number(config.gap ?? config.margin?.[0] ?? 0)
  return columns > 0 ? Math.max(0, (containerWidth - gap * (columns - 1)) / columns) : containerWidth
}

export function calculateContainerHeight(totalRows: number, rowHeight: number, gap = 0): number {
  return totalRows > 0 ? totalRows * rowHeight + Math.max(0, totalRows - 1) * gap : 0
}

export function getGridArea(item: GridLayoutPlusItem): string {
  return itemToGridArea(item)
}

export function gridToPixel(gridPos: number, cellSize: number, gap = 0): number {
  return gridPos * (cellSize + gap)
}

export function pixelToGrid(pixel: number, cellSize: number, gap = 0): number {
  const step = cellSize + gap
  return step > 0 ? Math.max(0, Math.round(pixel / step)) : 0
}

export function getItemPixelPosition(
  item: GridLayoutPlusItem,
  config: any,
  containerWidth: number
): { left: number; top: number } {
  const colWidth = calculateColWidth(config, containerWidth)
  const gap = Number(config.gap ?? config.margin?.[0] ?? 0)
  const rowGap = Number(config.gap ?? config.margin?.[1] ?? gap)
  return {
    left: gridToPixel(item.x, colWidth, gap),
    top: gridToPixel(item.y, Number(config.rowHeight ?? 0), rowGap)
  }
}

export function getItemPixelSize(
  item: GridLayoutPlusItem,
  config: any,
  containerWidth: number
): { width: number; height: number } {
  const colWidth = calculateColWidth(config, containerWidth)
  const gap = Number(config.gap ?? config.margin?.[0] ?? 0)
  const rowGap = Number(config.gap ?? config.margin?.[1] ?? gap)
  const rowHeight = Number(config.rowHeight ?? 0)
  return {
    width: item.w * colWidth + Math.max(0, item.w - 1) * gap,
    height: item.h * rowHeight + Math.max(0, item.h - 1) * rowGap
  }
}

export function generateGridBackgroundStyle(config: any, containerWidth: number): Record<string, string> {
  const colWidth = calculateColWidth(config, containerWidth)
  const rowHeight = Number(config.rowHeight ?? 0)
  const gap = Number(config.gap ?? config.margin?.[0] ?? 0)
  const rowGap = Number(config.gap ?? config.margin?.[1] ?? gap)
  return {
    backgroundSize: `${colWidth + gap}px ${rowHeight + rowGap}px`,
    backgroundImage:
      'linear-gradient(to right, rgba(148, 163, 184, 0.25) 1px, transparent 1px), linear-gradient(to bottom, rgba(148, 163, 184, 0.25) 1px, transparent 1px)'
  }
}

/**
 * 获取网格统计信息（详细版本）
 */
/**
 * 在基础统计之外补充分布和启发式性能指标，适合做“相对比较”而非绝对判定。
 */
export function getGridStatistics(
  layout: GridLayoutPlusItem[],
  cols: number
): {
  basic: ReturnType<typeof getLayoutStats>
  distribution: {
    bySize: Record<string, number>
    byPosition: { topHalf: number; bottomHalf: number }
    byWidth: Record<number, number>
    byHeight: Record<number, number>
  }
  performance: {
    fragmentation: number
    compactness: number
    balance: number
  }
} {
  try {
    const basic = getLayoutStats(layout, cols)

    // 尺寸分布
    const sizeDistribution: Record<string, number> = {}
    const widthDistribution: Record<number, number> = {}
    const heightDistribution: Record<number, number> = {}

    for (const item of layout) {
      const area = item.w * item.h
      const sizeCategory = area <= 2 ? 'small' : area <= 6 ? 'medium' : 'large'

      sizeDistribution[sizeCategory] = (sizeDistribution[sizeCategory] || 0) + 1
      widthDistribution[item.w] = (widthDistribution[item.w] || 0) + 1
      heightDistribution[item.h] = (heightDistribution[item.h] || 0) + 1
    }

    // 位置分布
    const totalRows = basic.totalRows
    const halfRows = totalRows / 2
    const topHalf = layout.filter(item => item.y < halfRows).length
    const bottomHalf = layout.length - topHalf

    // 性能指标
    const fragmentation = calculateFragmentation(layout, cols)
    const compactness = calculateCompactness(layout, cols)
    const balance = calculateBalance(layout, cols)

    return {
      basic,
      distribution: {
        bySize: sizeDistribution,
        byPosition: { topHalf, bottomHalf },
        byWidth: widthDistribution,
        byHeight: heightDistribution
      },
      performance: {
        fragmentation,
        compactness,
        balance
      }
    }
  } catch (error) {
    console.error('Failed to get grid statistics:', error)
    return {
      basic: getLayoutStats(layout, cols),
      distribution: {
        bySize: {},
        byPosition: { topHalf: 0, bottomHalf: 0 },
        byWidth: {},
        byHeight: {}
      },
      performance: {
        fragmentation: 0,
        compactness: 0,
        balance: 0
      }
    }
  }
}

/**
 * 计算布局碎片化程度
 */
/**
 * 粗略估算布局碎片化程度：空洞比例越高，说明后续自动排布越难压紧。
 */
function calculateFragmentation(layout: GridLayoutPlusItem[], cols: number): number {
  try {
    if (layout.length === 0) return 0

    const totalRows = Math.max(...layout.map(item => item.y + item.h))
    const grid = Array(totalRows)
      .fill(null)
      .map(() => Array(cols).fill(false))

    // 标记占用的网格单元
    for (const item of layout) {
      for (let y = item.y; y < item.y + item.h; y++) {
        for (let x = item.x; x < item.x + item.w; x++) {
          if (y < totalRows && x < cols) {
            grid[y][x] = true
          }
        }
      }
    }

    // 计算空隙数量
    let gaps = 0
    let totalCells = 0

    for (let y = 0; y < totalRows; y++) {
      for (let x = 0; x < cols; x++) {
        totalCells++
        if (!grid[y][x]) {
          gaps++
        }
      }
    }

    return totalCells > 0 ? (gaps / totalCells) * 100 : 0
  } catch (error) {
    console.error('Failed to calculate fragmentation:', error)
    return 0
  }
}

/**
 * 计算布局紧凑度
 */
function calculateCompactness(layout: GridLayoutPlusItem[], cols: number): number {
  try {
    if (layout.length === 0) return 100

    const totalArea = layout.reduce((sum, item) => sum + item.w * item.h, 0)
    const boundingHeight = Math.max(...layout.map(item => item.y + item.h))
    const boundingArea = cols * boundingHeight

    return boundingArea > 0 ? (totalArea / boundingArea) * 100 : 0
  } catch (error) {
    console.error('Failed to calculate compactness:', error)
    return 0
  }
}

/**
 * 计算布局平衡度
 */
/**
 * 用面积加权重心估算布局平衡度，避免小组件对整体结果产生过大噪声。
 */
function calculateBalance(layout: GridLayoutPlusItem[], cols: number): number {
  try {
    if (layout.length === 0) return 100

    const centerX = cols / 2
    const totalRows = Math.max(...layout.map(item => item.y + item.h))
    const centerY = totalRows / 2

    // 计算重心
    let weightedX = 0
    let weightedY = 0
    let totalWeight = 0

    for (const item of layout) {
      const weight = item.w * item.h
      const itemCenterX = item.x + item.w / 2
      const itemCenterY = item.y + item.h / 2

      weightedX += itemCenterX * weight
      weightedY += itemCenterY * weight
      totalWeight += weight
    }

    if (totalWeight === 0) return 100

    const gravityX = weightedX / totalWeight
    const gravityY = weightedY / totalWeight

    // 计算与中心的偏差
    const deviationX = Math.abs(gravityX - centerX) / centerX
    const deviationY = Math.abs(gravityY - centerY) / centerY
    const totalDeviation = (deviationX + deviationY) / 2

    return Math.max(0, (1 - totalDeviation) * 100)
  } catch (error) {
    console.error('Failed to calculate balance:', error)
    return 0
  }
}

/**
 * 数组去重
 */
export function uniqueArray<T>(array: T[], keyFn?: (item: T) => string | number): T[] {
  try {
    if (!keyFn) {
      return [...new Set(array)]
    }

    const seen = new Set<string | number>()
    return array.filter(item => {
      const key = keyFn(item)
      if (seen.has(key)) {
        return false
      }
      seen.add(key)
      return true
    })
  } catch (error) {
    console.error('Failed to get unique array:', error)
    return array
  }
}

/**
 * 安全的数值解析
 */
export function parseNumber(value: any, defaultValue = 0): number {
  try {
    if (typeof value === 'number' && !isNaN(value)) {
      return value
    }

    if (typeof value === 'string') {
      const parsed = parseFloat(value)
      return isNaN(parsed) ? defaultValue : parsed
    }

    return defaultValue
  } catch (error) {
    return defaultValue
  }
}

/**
 * 限制数值在指定范围内
 */
export function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value))
}

/**
 * 格式化文件大小
 */
export function formatFileSize(bytes: number): string {
  try {
    if (bytes === 0) return '0 B'

    const sizes = ['B', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(1024))
    const size = bytes / Math.pow(1024, i)

    return `${size.toFixed(1)} ${sizes[i]}`
  } catch (error) {
    return '0 B'
  }
}

/**
 * 格式化持续时间
 */
export function formatDuration(milliseconds: number): string {
  try {
    if (milliseconds < 1000) {
      return `${milliseconds.toFixed(1)}ms`
    }

    const seconds = milliseconds / 1000
    if (seconds < 60) {
      return `${seconds.toFixed(1)}s`
    }

    const minutes = seconds / 60
    return `${minutes.toFixed(1)}m`
  } catch (error) {
    return '0ms'
  }
}

/**
 * 文件用途：承载网格自动布局、位置查找和碰撞处理算法。
 * 核心逻辑：根据网格尺寸、已有布局和约束计算可用位置或调整后的布局。
 * 关键注意事项：算法变更会直接影响可视布局结果，需覆盖静态项、边界尺寸和密集碰撞场景。
 * 重构建议：可把碰撞检测、压缩策略和位置搜索拆成独立纯函数并建立基准用例。
 */
import type { GridLayoutPlusItem, LayoutOperationResult } from '../gridLayoutPlusTypes'
/**
 * 以“从上到下、从左到右”的顺序寻找首个可放置位置，适合新增组件时的基础兜底策略。
 */
export function findAvailablePosition(
  layout: GridLayoutPlusItem[],
  w: number,
  h: number,
  cols: number = 12,
  startY: number = 0
): { x: number; y: number } {
  try {
    // 简单的位置查找算法
    for (let y = startY; y < startY + 100; y++) {
      for (let x = 0; x <= cols - w; x++) {
        const proposed = { x, y, w, h }

        // 检查是否与现有项目冲突
        const hasCollision = layout.some(item => {
          return !(
            proposed.x + proposed.w <= item.x ||
            proposed.x >= item.x + item.w ||
            proposed.y + proposed.h <= item.y ||
            proposed.y >= item.y + item.h
          )
        })

        if (!hasCollision) {
          return { x, y }
        }
      }
    }

    // 如果找不到位置，返回底部
    const maxY = Math.max(0, ...layout.map(item => item.y + item.h))
    return { x: 0, y: maxY }
  } catch (error) {
    console.error('Failed to find available position:', error)
    return { x: 0, y: startY }
  }
}

/**
 * 穷举候选位置并打分，偏向更靠上、更靠左且能贴邻现有组件的结果。
 */
export function findOptimalPosition(
  layout: GridLayoutPlusItem[],
  w: number,
  h: number,
  cols: number = 12,
  preferredX?: number,
  preferredY?: number
): { x: number; y: number; score: number } {
  try {
    const candidates: Array<{ x: number; y: number; score: number }> = []

    // 如果有首选位置，先检查
    if (preferredX !== undefined && preferredY !== undefined) {
      const candidate = { x: preferredX, y: preferredY, score: 0 }
      if (isPositionAvailable(layout, preferredX, preferredY, w, h, cols)) {
        candidate.score = 100 // 最高分
        candidates.push(candidate)
      }
    }

    // 搜索最优位置
    const maxY = Math.max(10, ...layout.map(item => item.y + item.h))

    for (let y = 0; y < maxY + 5; y++) {
      for (let x = 0; x <= cols - w; x++) {
        if (isPositionAvailable(layout, x, y, w, h, cols)) {
          // 计算位置得分（越靠上左越好）
          const score = calculatePositionScore(x, y, w, h, layout, cols)
          candidates.push({ x, y, score })
        }
      }
    }

    // 如果没有找到任何可用位置，返回底部位置
    if (candidates.length === 0) {
      const bottomY = Math.max(0, ...layout.map(item => item.y + item.h))
      return { x: 0, y: bottomY, score: 0 }
    }

    // 返回得分最高的位置
    return candidates.reduce((best, current) => (current.score > best.score ? current : best))
  } catch (error) {
    console.error('Failed to find optimal position:', error)
    return { x: 0, y: 0, score: 0 }
  }
}

/**
 * 判断候选区域是否越界或与现有项碰撞；拖拽自身时可通过 `excludeId` 忽略原位置。
 */
export function isPositionAvailable(
  layout: GridLayoutPlusItem[],
  x: number,
  y: number,
  w: number,
  h: number,
  cols: number,
  excludeId?: string
): boolean {
  try {
    // 检查边界
    if (x < 0 || y < 0 || x + w > cols) {
      return false
    }

    // 检查碰撞
    const proposed = { x, y, w, h }
    return !layout.some(item => {
      if (excludeId && item.i === excludeId) return false

      return !(
        proposed.x + proposed.w <= item.x ||
        proposed.x >= item.x + item.w ||
        proposed.y + proposed.h <= item.y ||
        proposed.y >= item.y + item.h
      )
    })
  } catch (error) {
    console.error('Failed to check position availability:', error)
    return false
  }
}

function calculatePositionScore(
  x: number,
  y: number,
  w: number,
  h: number,
  layout: GridLayoutPlusItem[],
  cols: number
): number {
  try {
    let score = 1000

    // Y位置惩罚（越高得分越低）
    score -= y * 10

    // X位置轻微惩罚（偏左更好）
    score -= x * 2

    // 边缘位置加分
    if (x === 0) score += 5 // 左边缘
    if (x + w === cols) score += 3 // 右边缘

    // 与现有项目的邻接关系加分
    for (const item of layout) {
      // 垂直邻接
      if ((item.y + item.h === y || y + h === item.y) && !(x + w <= item.x || x >= item.x + item.w)) {
        score += 20 // 垂直相邻
      }

      // 水平邻接
      if ((item.x + item.w === x || x + w === item.x) && !(y + h <= item.y || y >= item.y + item.h)) {
        score += 15 // 水平相邻
      }
    }

    return Math.max(0, score)
  } catch (error) {
    console.error('Failed to calculate position score:', error)
    return 0
  }
}

/**
 * 紧凑布局算法
 */
/**
 * 仅做纵向紧凑化，尽量消除空行，不主动改变横向先后关系。
 */
export function compactLayout(
  layout: GridLayoutPlusItem[],
  cols: number,
  verticalCompact: boolean = true
): GridLayoutPlusItem[] {
  if (!verticalCompact || layout.length === 0) return layout

  try {
    // 按Y坐标排序，确保我们从上到下处理项目
    const sortedLayout = [...layout].sort((a, b) => {
      if (a.y === b.y) return a.x - b.x
      return a.y - b.y
    })

    // 用于存放已处理和放置好的项目
    const compacted: GridLayoutPlusItem[] = []

    for (const item of sortedLayout) {
      // 从顶部开始为当前项目寻找新的Y坐标
      let newY = 0

      // 持续增加Y坐标，直到找到一个不与 `compacted` 中任何项目碰撞的位置
      while (!isPositionAvailable(compacted, item.x, newY, item.w, item.h, cols)) {
        newY++
      }

      // 将项目放置在找到的第一个可用位置
      compacted.push({
        ...item,
        y: newY
      })
    }

    return compacted
  } catch (error) {
    console.error('Failed to compact layout:', error)
    return layout
  }
}

/**
 * 排序布局项目
 */
export function sortLayout(
  layout: GridLayoutPlusItem[],
  sortBy: 'position' | 'size' | 'id' = 'position'
): GridLayoutPlusItem[] {
  try {
    const sorted = [...layout]

    switch (sortBy) {
      case 'position':
        return sorted.sort((a, b) => {
          if (a.y === b.y) return a.x - b.x
          return a.y - b.y
        })

      case 'size':
        return sorted.sort((a, b) => {
          const aSize = a.w * a.h
          const bSize = b.w * b.h
          return bSize - aSize // 大的在前
        })

      case 'id':
        return sorted.sort((a, b) => a.i.localeCompare(b.i))

      default:
        return sorted
    }
  } catch (error) {
    console.error('Failed to sort layout:', error)
    return layout
  }
}

/**
 * 计算布局边界
 */
export function getLayoutBounds(layout: GridLayoutPlusItem[]): {
  minX: number
  maxX: number
  minY: number
  maxY: number
  width: number
  height: number
} {
  if (layout.length === 0) {
    return { minX: 0, maxX: 0, minY: 0, maxY: 0, width: 0, height: 0 }
  }

  try {
    const minX = Math.min(...layout.map(item => item.x))
    const maxX = Math.max(...layout.map(item => item.x + item.w))
    const minY = Math.min(...layout.map(item => item.y))
    const maxY = Math.max(...layout.map(item => item.y + item.h))

    return {
      minX,
      maxX,
      minY,
      maxY,
      width: maxX - minX,
      height: maxY - minY
    }
  } catch (error) {
    console.error('Failed to get layout bounds:', error)
    return { minX: 0, maxX: 0, minY: 0, maxY: 0, width: 0, height: 0 }
  }
}

/**
 * 计算两个项目的重叠面积
 */
export function getOverlapArea(item1: GridLayoutPlusItem, item2: GridLayoutPlusItem): number {
  try {
    const left = Math.max(item1.x, item2.x)
    const right = Math.min(item1.x + item1.w, item2.x + item2.w)
    const top = Math.max(item1.y, item2.y)
    const bottom = Math.min(item1.y + item1.h, item2.y + item2.h)

    if (left >= right || top >= bottom) {
      return 0 // 没有重叠
    }

    return (right - left) * (bottom - top)
  } catch (error) {
    console.error('Failed to calculate overlap area:', error)
    return 0
  }
}

/**
 * 移动项目到新位置并处理碰撞
 * @param layout - 当前布局
 * @param movingItem - 正在移动的项
 * @param newX - 移动项的新x坐标
 * @param newY - 移动项的新y坐标
 * @param cols - 网格的列数
 * @returns 经过碰撞处理和紧凑化后的新布局
 */
/**
 * 处理拖拽后的连锁碰撞：
 * 会先归一化异常坐标，再用 BFS 推挤碰撞项，最后执行一次纵向压缩。
 */
export function moveItemWithCollisionHandling(
  layout: GridLayoutPlusItem[],
  movingItem: GridLayoutPlusItem,
  newX: number,
  newY: number,
  cols: number
): GridLayoutPlusItem[] {
  // 步骤1: 布局净化与规范化
  // 深拷贝布局以进行修改，并规范化所有项的坐标。
  // 解决新添加项（坐标为 'auto' 或 undefined）无法参与碰撞检测的核心问题。
  const workingLayout = cloneLayout(layout).map(item => {
    // 检查x和y坐标是否为无效值（非数字、NaN、'auto'等）。
    const isInvalidX = typeof item.x !== 'number' || isNaN(item.x)
    const isInvalidY = typeof item.y !== 'number' || isNaN(item.y)

    // 为无效坐标提供一个临时的、可预测的初始位置。
    // 如果y坐标无效，则假定其在顶部（y=0）。
    // 如果x坐标无效，则假定其在最左侧（x=0）。
    // 这使得项的逻辑位置与其初始视觉位置（通常在左上角）相匹配。
    return {
      ...item,
      x: isInvalidX ? 0 : item.x,
      y: isInvalidY ? 0 : item.y
    }
  })

  // 步骤2: 更新移动项的位置
  // 在净化后的工作布局中找到正在移动的项。
  const movingItemInLayout = workingLayout.find(item => item.i === movingItem.i)
  // 如果找不到（理论上不应发生），则返回原始布局以保证安全。
  if (!movingItemInLayout) {
    return layout
  }

  // 将移动项的位置更新为拖拽操作提供的新坐标。
  movingItemInLayout.x = newX
  // 先写入拖拽后的目标坐标，再处理由此引发的碰撞链。
  movingItemInLayout.y = newY

  // 步骤3: 连锁碰撞处理 (BFS)
  // 使用广度优先搜索（BFS）来处理由移动项引起的连锁碰撞。
  const queue: GridLayoutPlusItem[] = [movingItemInLayout]
  // `movedItems` 用于跟踪在此次操作中已经移动过的项，防止在同一次连锁反应中被重复处理，避免无限循环。
  const movedItems = new Set<string>([movingItemInLayout.i])

  // 设置最大迭代次数，作为防止无限循环的安全阀。
  let iterations = 0
  // 保护阈值：异常布局时直接回退，避免拖拽过程卡死。
  const maxIterations = workingLayout.length * workingLayout.length

  while (queue.length > 0) {
    iterations++
    if (iterations > maxIterations) {
      console.error('moveItemWithCollisionHandling: Max iterations reached, aborting.')
      return layout // 检测到可能的无限循环，返回原始布局以避免应用冻结。
    }

    const currentItem = queue.shift()!

    // 遍历布局中的所有其他项以检测与当前项的碰撞。
    for (const other of workingLayout) {
      if (other.i === currentItem.i) continue

      if (collides(currentItem, other)) {
        // 静态项不能被推出原位，因此一旦碰撞就保守回退整次移动。
        // 如果与静态项（static=true）发生碰撞，则认为此次移动无效，立即返回原始布局。
        if (other.static) {
          return layout
        }

        // 计算将 'other' 项向下推到的新y坐标。
        const pushToY = currentItem.y + currentItem.h

        // 只有当 'other' 项当前位置在推挤目标位置之上时，才执行推挤。
        // 这可以防止不必要的移动和潜在的循环。
        // 只推动真正挡路的项，避免重复位移造成布局抖动。
        if (other.y < pushToY) {
          other.y = pushToY

          // 如果 'other' 项是第一次在此操作中被移动，则将其加入队列。
          // 这确保了它引发的后续碰撞也会被处理。
          if (!movedItems.has(other.i)) {
            movedItems.add(other.i)
            queue.push(other)
          }
        }
      }
    }
  }

  // 步骤4: 布局紧凑化
  // 在所有碰撞处理完成后，对布局进行紧凑化，移除因推挤而产生的垂直间隙。
  return compactLayout(workingLayout, cols)
}

/**
 * 深拷贝一个布局数组。
 * @param layout - 要克隆的布局。
 * @returns 返回一个新的布局数组，与原始布局完全独立。
 */
function cloneLayout(layout: GridLayoutPlusItem[]): GridLayoutPlusItem[] {
  return JSON.parse(JSON.stringify(layout))
}

/**
 * 检测两个布局项是否发生碰撞。
 * @param item1 - 第一个布局项。
 * @param item2 - 第二个布局项。
 * @returns 如果两项重叠，则返回 true，否则返回 false。
 */
function collides(item1: GridLayoutPlusItem, item2: GridLayoutPlusItem): boolean {
  if (item1.i === item2.i) return false
  if (item1.x + item1.w <= item2.x) return false
  if (item1.x >= item2.x + item2.w) return false
  if (item1.y + item1.h <= item2.y) return false
  if (item1.y >= item2.y + item2.h) return false
  return true
}

/**
 * 文件用途：提供网格高频操作相关的性能辅助函数。
 * 核心逻辑：封装防抖、节流、批处理或缓存策略，降低拖拽缩放期间的更新压力。
 * 关键注意事项：性能包装必须保留取消、flush 或最终执行语义，避免事件丢失。
 * 重构建议：可将通用节流工具迁移到全局 utils，网格目录只保留布局专属优化。
 */
import type { GridLayoutPlusItem, PerformanceConfig } from '../gridLayoutPlusTypes'

function getHighResolutionTime(): number {
  return globalThis.performance?.now ? globalThis.performance.now() : Date.now()
}

/**
 * 适合输入联想、尺寸监听等场景：只保留最后一次触发。
 */
export function debounce<T extends (...args: any[]) => any>(func: T, delay: number): (...args: Parameters<T>) => void {
  let timeoutId: NodeJS.Timeout | null = null

  return function (this: ThisParameterType<T>, ...args: Parameters<T>) {
    if (timeoutId) {
      clearTimeout(timeoutId)
    }

    timeoutId = setTimeout(() => {
      func.apply(this, args)
      timeoutId = null
    }, delay)
  }
}

/**
 * 适合拖拽、滚动和 resize：限制单位时间内的调用频率，但保留尾调用补发。
 */
export function throttle<T extends (...args: any[]) => any>(func: T, delay: number): (...args: Parameters<T>) => void {
  let lastTime = 0
  let timeoutId: NodeJS.Timeout | null = null

  return function (this: ThisParameterType<T>, ...args: Parameters<T>) {
    const now = Date.now()

    if (now - lastTime >= delay) {
      lastTime = now
      func.apply(this, args)
    } else if (!timeoutId) {
      timeoutId = setTimeout(
        () => {
          lastTime = Date.now()
          func.apply(this, args)
          timeoutId = null
        },
        delay - (now - lastTime)
      )
    }
  }
}

/**
 * 针对布局数据做轻量性能处理；当前主要是惰性加载标记，保留了后续扩展入口。
 */
export function optimizeLayoutPerformance(
  layout: GridLayoutPlusItem[],
  config: PerformanceConfig
): GridLayoutPlusItem[] {
  try {
    let optimizedLayout = [...layout]

    // 懒加载处理
    if (config.enableLazyLoading) {
      optimizedLayout = applyLazyLoading(optimizedLayout, config)
    }

    return optimizedLayout
  } catch (error) {
    console.error('Failed to optimize layout performance:', error)
    return layout
  }
}

/**
 * 基于顺序给后半段组件打上惰性标记，实际渲染裁剪仍由上层消费这些 metadata。
 */
function applyLazyLoading(layout: GridLayoutPlusItem[], config: PerformanceConfig): GridLayoutPlusItem[] {
  try {
    const buffer = config.lazyLoadingBuffer || 5

    // 标记需要懒加载的项目
    return layout.map((item, index) => ({
      ...item,
      metadata: {
        ...item.metadata,
        lazy: index >= buffer,
        lazyIndex: index
      }
    }))
  } catch (error) {
    console.error('Failed to apply lazy loading:', error)
    return layout
  }
}

/**
 * 统一封装运行期性能采样：
 * 优先走浏览器 Performance API，缺失时降级到时间戳计时。
 */
export class PerformanceMonitor {
  private metrics: Map<string, number[]> = new Map()
  private timers: Map<string, number> = new Map()
  private isEnabled = true

  /**
   * 开始监控操作
   */
  start(operation: string): string {
    if (!this.isEnabled) return ''

    const id = `${operation}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
    if (globalThis.performance?.mark) {
      performance.mark(`${id}_start`)
    } else {
      this.timers.set(id, getHighResolutionTime())
    }

    return id
  }

  /**
   * 结束监控并记录
   */
  end(id: string, operation: string): number | null {
    if (!this.isEnabled || !id) return null

    try {
      // 在非浏览器或能力不完整环境下，退化为普通高精度时间差统计。
      if (!globalThis.performance?.mark || !globalThis.performance?.measure) {
        const start = this.timers.get(id)
        if (start === undefined) return null

        const duration = Math.max(0.001, getHighResolutionTime() - start)
        this.timers.delete(id)
        this.recordMetric(operation, duration)
        return duration
      }

      performance.mark(`${id}_end`)
      performance.measure(id, `${id}_start`, `${id}_end`)

      const measures = performance.getEntriesByName(id, 'measure')
      if (measures.length > 0) {
        const duration = measures[0].duration

        // 记录到指标中
        this.recordMetric(operation, duration)

        // 限制记录数量

        // 清理性能条目
        performance.clearMarks(`${id}_start`)
        performance.clearMarks(`${id}_end`)
        performance.clearMeasures(id)

        return duration
      }
    } catch (error) {
      console.error('Performance monitoring error:', error)
    }

    return null
  }

  startTimer(metric: string): void {
    if (!this.isEnabled) return
    this.timers.set(metric, getHighResolutionTime())
  }

  endTimer(metric: string): number {
    if (!this.isEnabled) return 0

    const start = this.timers.get(metric)
    if (start === undefined) return 0

    const duration = Math.max(0.001, getHighResolutionTime() - start)
    this.timers.delete(metric)
    this.recordMetric(metric, duration)
    return duration
  }

  getMetrics(): Record<string, number> {
    const result: Record<string, number> = {}

    for (const [operation, values] of this.metrics.entries()) {
      result[operation] = values.length > 0 ? values[values.length - 1] : 0
    }

    return result
  }

  /**
   * 获取操作的统计信息
   */
  getStats(operation: string): {
    count: number
    average: number
    min: number
    max: number
    recent: number
  } | null {
    const metrics = this.metrics.get(operation)
    if (!metrics || metrics.length === 0) return null

    const count = metrics.length
    const sum = metrics.reduce((a, b) => a + b, 0)
    const average = sum / count
    const min = Math.min(...metrics)
    const max = Math.max(...metrics)
    const recent = metrics[metrics.length - 1]

    return { count, average, min, max, recent }
  }

  /**
   * 获取所有统计信息
   */
  getAllStats(): Record<string, ReturnType<PerformanceMonitor['getStats']>> {
    const stats: Record<string, ReturnType<PerformanceMonitor['getStats']>> = {}

    for (const operation of this.metrics.keys()) {
      stats[operation] = this.getStats(operation)
    }

    return stats
  }

  /**
   * 清理监控数据
   */
  clear(operation?: string): void {
    if (operation) {
      this.metrics.delete(operation)
      this.timers.delete(operation)
    } else {
      this.metrics.clear()
      this.timers.clear()
    }
  }

  reset(): void {
    this.clear()
    this.isEnabled = true
  }

  /**
   * 启用/禁用监控
   */
  setEnabled(enabled: boolean): void {
    this.isEnabled = enabled
  }

  private recordMetric(operation: string, duration: number): void {
    if (!this.metrics.has(operation)) {
      this.metrics.set(operation, [])
    }

    const operationMetrics = this.metrics.get(operation)!
    operationMetrics.push(duration)

    if (operationMetrics.length > 100) {
      operationMetrics.shift()
    }
  }
}

/**
 * 全局性能监控实例
 */
export const performanceMonitor = new PerformanceMonitor()

/**
 * 内存使用监控
 */
export function getMemoryUsage(): {
  used: number
  total: number
  percentage: number
} | null {
  try {
    // 现代浏览器的内存API
    if ('memory' in performance) {
      const memory = (performance as any).memory
      return {
        used: memory.usedJSHeapSize,
        total: memory.totalJSHeapSize,
        percentage: (memory.usedJSHeapSize / memory.totalJSHeapSize) * 100
      }
    }
  } catch (error) {
    console.error('Failed to get memory usage:', error)
  }

  return null
}

/**
 * 缓存管理器
 */
/**
 * 一个带 TTL 和最少使用淘汰策略的轻量缓存，适合短时复用的布局派生数据。
 */
export class CacheManager<K, V> {
  private cache = new Map<K, { value: V; timestamp: number; hits: number }>()
  private maxSize: number
  private ttl: number // 生存时间(ms)

  constructor(maxSize = 100, ttl = 5 * 60 * 1000) {
    // 默认5分钟
    this.maxSize = maxSize
    this.ttl = ttl
  }

  /**
   * 获取缓存值
   */
  get(key: K): V | null {
    const item = this.cache.get(key)
    if (!item) return null

    // 检查是否过期
    if (Date.now() - item.timestamp > this.ttl) {
      this.cache.delete(key)
      return null
    }

    // 更新访问计数
    item.hits++
    return item.value
  }

  has(key: K): boolean {
    return this.get(key) !== null
  }

  /**
   * 设置缓存值
   */
  set(key: K, value: V): void {
    // 如果缓存已满，移除最少使用的项
    if (this.cache.size >= this.maxSize) {
      this.evictLeastUsed()
    }

    this.cache.set(key, {
      value,
      timestamp: Date.now(),
      hits: 0
    })
  }

  /**
   * 删除缓存项
   */
  delete(key: K): boolean {
    return this.cache.delete(key)
  }

  /**
   * 清空缓存
   */
  clear(): void {
    this.cache.clear()
  }

  size(): number {
    return this.cache.size
  }

  /**
   * 获取缓存统计
   */
  getStats(): {
    size: number
    maxSize: number
    hitRate: number
    totalHits: number
  } {
    let totalHits = 0
    let totalAccess = 0

    for (const item of this.cache.values()) {
      totalHits += item.hits
      totalAccess += item.hits + 1 // +1 for the initial set
    }

    return {
      size: this.cache.size,
      maxSize: this.maxSize,
      hitRate: totalAccess > 0 ? totalHits / totalAccess : 0,
      totalHits
    }
  }

  /**
   * 移除最少使用的项
   */
  private evictLeastUsed(): void {
    let leastUsedKey: K | null = null
    let minHits = Infinity
    let oldestTime = Infinity

    for (const [key, item] of this.cache.entries()) {
      if (item.hits < minHits || (item.hits === minHits && item.timestamp < oldestTime)) {
        leastUsedKey = key
        minHits = item.hits
        oldestTime = item.timestamp
      }
    }

    if (leastUsedKey !== null) {
      this.cache.delete(leastUsedKey)
    }
  }
}

/**
 * 异步队列处理器
 */
/**
 * 控制异步任务并发度，避免密集布局任务同时执行时放大主线程压力。
 */
export class AsyncQueue<T> {
  private queue: Array<() => Promise<T>> = []
  private running = false
  private concurrency: number

  constructor(concurrency = 1) {
    this.concurrency = concurrency
  }

  /**
   * 添加任务到队列
   */
  add<R>(task: () => Promise<R>): Promise<R> {
    return new Promise((resolve, reject) => {
      this.queue.push(async () => {
        try {
          const result = await task()
          resolve(result as any)
          return result as any
        } catch (error) {
          reject(error)
          throw error
        }
      })

      this.process()
    })
  }

  /**
   * 处理队列
   */
  private async process(): Promise<void> {
    if (this.running) return

    this.running = true

    try {
      while (this.queue.length > 0) {
        const batch = this.queue.splice(0, this.concurrency)
        await Promise.allSettled(batch.map(task => task()))
      }
    } finally {
      this.running = false
    }
  }

  /**
   * 清空队列
   */
  clear(): void {
    this.queue = []
  }

  /**
   * 获取队列长度
   */
  size(): number {
    return this.queue.length
  }
}

/**
 * 文件用途：提供网格响应式断点和布局转换工具。
 * 核心逻辑：按 breakpoints、cols 和当前宽度选择布局，并在列数变化时转换坐标尺寸。
 * 关键注意事项：断点转换要保留用户布局意图，不能把隐藏或未知项误删。
 * 重构建议：可补充不同列数互转的表驱动测试，明确溢出和压缩策略。
 */
import type { GridLayoutPlusItem, ResponsiveLayout, LayoutOperationResult } from '../gridLayoutPlusTypes'
/**
 * 以基础布局为源，为每个断点派生一份独立布局快照。
 */
export function createResponsiveLayout(
  baseLayout: GridLayoutPlusItem[],
  breakpoints: Record<string, number>,
  cols: Record<string, number>
): ResponsiveLayout {
  try {
    const responsiveLayout: ResponsiveLayout = {}
    const sortedBreakpoints = Object.entries(breakpoints).sort(([, a], [, b]) => b - a) // 从大到小排序

    // 为每个断点生成布局
    for (const [breakpoint] of sortedBreakpoints) {
      const targetCols = cols[breakpoint] || 12
      const baseCols = cols.lg || 12

      responsiveLayout[breakpoint] = transformLayoutForBreakpoint(baseLayout, baseCols, targetCols, breakpoint)
    }

    return responsiveLayout
  } catch (error) {
    console.error('Failed to create responsive layout:', error)
    return {}
  }
}

/**
 * 按列数比例缩放横向位置和宽度，高度则交给断点规则做最小化修正。
 */
export function transformLayoutForBreakpoint(
  sourceLayout: GridLayoutPlusItem[],
  sourceCols: number,
  targetCols: number,
  breakpoint: string
): GridLayoutPlusItem[] {
  try {
    if (sourceCols === targetCols) {
      return sourceLayout.map(item => ({ ...item }))
    }

    const ratio = targetCols / sourceCols

    return sourceLayout.map(item => {
      // 计算新的位置和尺寸
      const newX = Math.floor(item.x * ratio)
      const newW = Math.max(1, Math.floor(item.w * ratio))

      // 确保项目不会超出边界
      const adjustedX = Math.min(newX, targetCols - newW)

      return {
        ...item,
        x: Math.max(0, adjustedX),
        w: newW,
        // Y坐标和高度保持不变，让布局算法自动调整
        // 但可以根据断点特性进行调整
        h: getResponsiveHeight(item, breakpoint)
      }
    })
  } catch (error) {
    console.error('Failed to transform layout for breakpoint:', error)
    return sourceLayout
  }
}

/**
 * 小屏断点下适当抬高组件高度，给内容换行和纵向堆叠留出空间。
 */
function getResponsiveHeight(item: GridLayoutPlusItem, breakpoint: string): number {
  try {
    // 根据断点调整高度
    switch (breakpoint) {
      case 'xs':
      case 'xxs':
        // 小屏幕下可能需要更高的项目来容纳内容
        return Math.max(item.h, 2)

      case 'sm':
        return Math.max(item.h, 1)

      default:
        return item.h
    }
  } catch (error) {
    console.error('Failed to get responsive height:', error)
    return item.h
  }
}

export function mergeResponsiveLayouts(layout1: ResponsiveLayout, layout2: ResponsiveLayout): ResponsiveLayout {
  try {
    const merged: ResponsiveLayout = { ...layout1 }

    for (const [breakpoint, layout] of Object.entries(layout2)) {
      merged[breakpoint] = layout
    }

    return merged
  } catch (error) {
    console.error('Failed to merge responsive layouts:', error)
    return layout1
  }
}

/**
 * 静态校验响应式布局是否引用了合法断点，并确认每个项都没有超出断点列数边界。
 */
export function validateResponsiveLayout(
  responsiveLayout: ResponsiveLayout,
  breakpoints: Record<string, number>,
  cols: Record<string, number>
): LayoutOperationResult<boolean> {
  try {
    for (const [breakpoint, layout] of Object.entries(responsiveLayout)) {
      // 检查断点是否存在
      if (!(breakpoint in breakpoints)) {
        return {
          success: false,
          error: new Error(`Unknown breakpoint: ${breakpoint}`),
          message: `未知的断点: ${breakpoint}`
        }
      }

      // 检查列数配置
      const breakpointCols = cols[breakpoint]
      if (!breakpointCols) {
        return {
          success: false,
          error: new Error(`Missing column config for breakpoint: ${breakpoint}`),
          message: `断点 ${breakpoint} 缺少列配置`
        }
      }

      // 验证布局中的每个项目
      for (const item of layout) {
        if (item.x + item.w > breakpointCols) {
          return {
            success: false,
            error: new Error(`Item ${item.i} exceeds column limit in breakpoint ${breakpoint}`),
            message: `项目 ${item.i} 在断点 ${breakpoint} 中超出列数限制`
          }
        }
      }
    }

    return { success: true, data: true }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '响应式布局验证失败'
    }
  }
}

/**
 * 获取断点信息
 */
/**
 * 根据当前宽度推断所在断点，并附带上下相邻断点，方便上层决定是否需要切换布局。
 */
export function getBreakpointInfo(
  currentWidth: number,
  breakpoints: Record<string, number>
): {
  current: string
  next?: string
  previous?: string
  width: number
} {
  try {
    const sortedBreakpoints = Object.entries(breakpoints).sort(([, a], [, b]) => b - a) // 从大到小排序

    let current = sortedBreakpoints[sortedBreakpoints.length - 1][0] // 默认最小的断点
    let currentIndex = sortedBreakpoints.length - 1

    // 找到当前断点
    for (let i = 0; i < sortedBreakpoints.length; i++) {
      const [breakpoint, minWidth] = sortedBreakpoints[i]
      if (currentWidth >= minWidth) {
        current = breakpoint
        currentIndex = i
        break
      }
    }

    return {
      current,
      next: currentIndex > 0 ? sortedBreakpoints[currentIndex - 1][0] : undefined,
      previous: currentIndex < sortedBreakpoints.length - 1 ? sortedBreakpoints[currentIndex + 1][0] : undefined,
      width: currentWidth
    }
  } catch (error) {
    console.error('Failed to get breakpoint info:', error)
    return {
      current: 'lg',
      width: currentWidth
    }
  }
}

/**
 * 计算断点过渡
 */
/**
 * 描述两个断点之间的切换方向与列数变化幅度，便于上层判断是否需要重排或动画过渡。
 */
export function calculateBreakpointTransition(
  fromBreakpoint: string,
  toBreakpoint: string,
  breakpoints: Record<string, number>,
  cols: Record<string, number>
): {
  direction: 'up' | 'down'
  ratio: number
  significant: boolean
} {
  try {
    const fromWidth = breakpoints[fromBreakpoint] || 0
    const toWidth = breakpoints[toBreakpoint] || 0
    const fromCols = cols[fromBreakpoint] || 12
    const toCols = cols[toBreakpoint] || 12

    const direction = toWidth > fromWidth ? 'up' : 'down'
    const ratio = toCols / fromCols
    const significant = Math.abs(ratio - 1) > 0.2 // 超过20%的列数变化被认为是显著的

    return { direction, ratio, significant }
  } catch (error) {
    console.error('Failed to calculate breakpoint transition:', error)
    return { direction: 'up', ratio: 1, significant: false }
  }
}

/**
 * 自适应调整项目尺寸
 */
/**
 * 基于断点做一次启发式尺寸修正，用于超小屏和小屏场景的保底展示。
 */
export function adaptItemSizeForBreakpoint(
  item: GridLayoutPlusItem,
  breakpoint: string,
  cols: number,
  containerWidth: number
): GridLayoutPlusItem {
  try {
    const adapted = { ...item }

    // 根据断点调整项目属性
    switch (breakpoint) {
      case 'xxs':
      case 'xs':
        // 极小屏幕：项目占满宽度，增加高度
        adapted.x = 0
        adapted.w = cols
        adapted.h = Math.max(adapted.h, 3)
        break

      case 'sm':
        // 小屏幕：最大占用一半宽度
        adapted.w = Math.min(adapted.w, Math.floor(cols / 2))
        adapted.h = Math.max(adapted.h, 2)
        break

      case 'md':
        // 中等屏幕：限制最大宽度
        adapted.w = Math.min(adapted.w, Math.floor(cols * 0.75))
        break

      default:
        // 大屏幕保持原样
        break
    }

    // 确保项目不超出边界
    adapted.w = Math.max(1, adapted.w)
    adapted.x = Math.min(adapted.x, cols - adapted.w)

    return adapted
  } catch (error) {
    console.error('Failed to adapt item size for breakpoint:', error)
    return item
  }
}

/**
 * 响应式媒体查询工具
 */
/**
 * 对 `matchMedia` 做轻量封装，让 grid 侧能按断点订阅变化而不直接散落浏览器 API。
 */
export class ResponsiveMediaQuery {
  private breakpoints: Record<string, number>
  private callbacks: Map<string, Set<(matches: boolean) => void>> = new Map()
  private mediaQueries: Map<string, MediaQueryList> = new Map()

  constructor(breakpoints: Record<string, number>) {
    this.breakpoints = breakpoints
    this.initMediaQueries()
  }

  /**
   * 初始化媒体查询
   */
  private initMediaQueries(): void {
    if (typeof window === 'undefined') return

    for (const [breakpoint, minWidth] of Object.entries(this.breakpoints)) {
      const mediaQuery = window.matchMedia(`(min-width: ${minWidth}px)`)
      this.mediaQueries.set(breakpoint, mediaQuery)

      // 监听变化
      mediaQuery.addListener(e => {
        const callbacks = this.callbacks.get(breakpoint)
        if (callbacks) {
          callbacks.forEach(callback => callback(e.matches))
        }
      })
    }
  }

  /**
   * 监听断点变化
   */
  onBreakpoint(breakpoint: string, callback: (matches: boolean) => void): () => void {
    if (!this.callbacks.has(breakpoint)) {
      this.callbacks.set(breakpoint, new Set())
    }

    const callbacks = this.callbacks.get(breakpoint)!
    callbacks.add(callback)

    // 立即调用一次
    const mediaQuery = this.mediaQueries.get(breakpoint)
    if (mediaQuery) {
      callback(mediaQuery.matches)
    }

    // 返回取消监听的函数
    return () => {
      callbacks.delete(callback)
    }
  }

  /**
   * 检查当前是否匹配断点
   */
  matches(breakpoint: string): boolean {
    const mediaQuery = this.mediaQueries.get(breakpoint)
    return mediaQuery ? mediaQuery.matches : false
  }

  /**
   * 获取当前匹配的断点
   */
  getCurrentBreakpoint(): string {
    const sortedBreakpoints = Object.entries(this.breakpoints).sort(([, a], [, b]) => b - a)

    for (const [breakpoint] of sortedBreakpoints) {
      if (this.matches(breakpoint)) {
        return breakpoint
      }
    }

    return sortedBreakpoints[sortedBreakpoints.length - 1][0] || 'xs'
  }

  /**
   * 销毁监听器
   */
  destroy(): void {
    this.callbacks.clear()
    this.mediaQueries.clear()
  }
}

/**
 * 文件用途：提供网格配置和布局项的输入校验。
 * 核心逻辑：检查坐标、尺寸、边界、重复 id 和配置字段是否满足网格约束。
 * 关键注意事项：校验错误会影响错误处理和用户导入数据，提示应尽量稳定可读。
 * 重构建议：可返回结构化错误码，方便 UI 层做本地化提示和自动修复建议。
 */
import type { GridLayoutPlusItem, LayoutOperationResult } from '../gridLayoutPlusTypes'
/**
 * 校验单个布局项的坐标、尺寸和约束边界；当前默认允许扩展到 99 列。
 */
export function validateGridItem(item: GridLayoutPlusItem, maxCols = 99): LayoutOperationResult<boolean> {
  try {
    // 检查必要字段
    if (!item.i || typeof item.i !== 'string') {
      return {
        success: false,
        error: new Error('Grid item must have a valid string id'),
        message: '网格项必须有有效的字符串ID'
      }
    }

    // 🔥 扩展：检查位置和尺寸 - 支持更大范围
    if (item.x < 0 || item.x >= maxCols) {
      return {
        success: false,
        error: new Error(`Grid X position must be between 0 and ${maxCols - 1}`),
        message: `网格X位置必须在0到${maxCols - 1}之间`
      }
    }

    if (item.y < 0) {
      return {
        success: false,
        error: new Error('Grid Y position must be >= 0'),
        message: '网格Y位置必须大于等于0'
      }
    }

    if (item.w <= 0 || item.w > maxCols) {
      return {
        success: false,
        error: new Error(`Grid width must be between 1 and ${maxCols}`),
        message: `网格宽度必须在1到${maxCols}之间`
      }
    }

    if (item.h <= 0) {
      return {
        success: false,
        error: new Error('Grid height must be > 0'),
        message: '网格高度必须大于0'
      }
    }

    // 🔥 新增：检查是否超出边界
    if (item.x + item.w > maxCols) {
      return {
        success: false,
        error: new Error(`Grid item extends beyond boundary (x:${item.x} + w:${item.w} > maxCols:${maxCols})`),
        message: `网格项超出边界（x:${item.x} + w:${item.w} > 最大列数:${maxCols}）`
      }
    }

    // 检查约束条件
    if (item.minW && item.w < item.minW) {
      return {
        success: false,
        error: new Error('Width is less than minimum'),
        message: '宽度小于最小值'
      }
    }

    if (item.maxW && item.w > item.maxW) {
      return {
        success: false,
        error: new Error('Width exceeds maximum'),
        message: '宽度超过最大值'
      }
    }

    if (item.minH && item.h < item.minH) {
      return {
        success: false,
        error: new Error('Height is less than minimum'),
        message: '高度小于最小值'
      }
    }

    if (item.maxH && item.h > item.maxH) {
      return {
        success: false,
        error: new Error('Height exceeds maximum'),
        message: '高度超过最大值'
      }
    }

    return { success: true, data: true }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '网格项验证失败'
    }
  }
}

/**
 * 对完整布局做基础体检：先校验数组结构和 ID 唯一性，再逐项复用单项校验逻辑。
 */
export function validateLayout(layout: GridLayoutPlusItem[]): LayoutOperationResult<boolean> {
  try {
    // 检查是否为空布局
    if (!Array.isArray(layout)) {
      return {
        success: false,
        error: new Error('Layout must be an array'),
        message: '布局必须是数组类型'
      }
    }

    if (layout.length === 0) {
      return { success: true, data: true } // 空布局是有效的
    }

    // 检查ID唯一性
    const ids = layout.map(item => item.i)
    const uniqueIds = new Set(ids)
    if (ids.length !== uniqueIds.size) {
      const duplicates = ids.filter((id, index) => ids.indexOf(id) !== index)
      return {
        success: false,
        error: new Error(`Duplicate item IDs found: ${duplicates.join(', ')}`),
        message: `发现重复ID: ${duplicates.join(', ')}`
      }
    }

    // 逐个验证网格项
    for (let i = 0; i < layout.length; i++) {
      const itemValidation = validateGridItem(layout[i])
      if (!itemValidation.success) {
        return {
          success: false,
          error: itemValidation.error,
          message: `第 ${i + 1} 个网格项验证失败: ${itemValidation.message}`
        }
      }
    }

    return { success: true, data: true }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '布局验证失败'
    }
  }
}

/**
 * 验证网格位置是否有效
 */
/**
 * 对单次拖拽或临时计算得到的候选位置做快速边界校验。
 */
export function validateGridPosition(
  x: number,
  y: number,
  w: number,
  h: number,
  cols: number
): LayoutOperationResult<boolean> {
  try {
    // 检查基本范围
    if (x < 0 || y < 0 || w <= 0 || h <= 0) {
      return {
        success: false,
        error: new Error('Invalid position or size'),
        message: '无效的位置或尺寸'
      }
    }

    // 检查是否超出列数
    if (x + w > cols) {
      return {
        success: false,
        error: new Error(`Item width exceeds column limit: ${x + w} > ${cols}`),
        message: `项目宽度超出列数限制: ${x + w} > ${cols}`
      }
    }

    return { success: true, data: true }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '网格位置验证失败'
    }
  }
}

/**
 * 检查两个网格项是否重叠
 */
export function checkItemsOverlap(item1: GridLayoutPlusItem, item2: GridLayoutPlusItem): boolean {
  try {
    return !(
      item1.x + item1.w <= item2.x ||
      item1.x >= item2.x + item2.w ||
      item1.y + item1.h <= item2.y ||
      item1.y >= item2.y + item2.h
    )
  } catch (error) {
    console.error('Failed to check items overlap:', error)
    return false
  }
}

/**
 * 检查布局中是否有重叠的项目
 */
/**
 * 穷举两两组合检查重叠，适合静态验证和导入校验，不适合超大布局的高频实时调用。
 */
export function validateNoOverlaps(layout: GridLayoutPlusItem[]): LayoutOperationResult<boolean> {
  try {
    for (let i = 0; i < layout.length; i++) {
      for (let j = i + 1; j < layout.length; j++) {
        if (checkItemsOverlap(layout[i], layout[j])) {
          return {
            success: false,
            error: new Error(`Items overlap: ${layout[i].i} and ${layout[j].i}`),
            message: `项目重叠: ${layout[i].i} 和 ${layout[j].i}`
          }
        }
      }
    }

    return { success: true, data: true }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '重叠检查失败'
    }
  }
}

/**
 * 验证响应式配置
 */
/**
 * 校验断点和列数配置是否一一对应，防止响应式转换阶段出现缺口。
 */
export function validateResponsiveConfig(
  breakpoints: Record<string, number>,
  cols: Record<string, number>
): LayoutOperationResult<boolean> {
  try {
    const breakpointNames = Object.keys(breakpoints)
    const colNames = Object.keys(cols)

    // 检查断点和列配置是否匹配
    for (const bp of breakpointNames) {
      if (!(bp in cols)) {
        return {
          success: false,
          error: new Error(`Missing column config for breakpoint: ${bp}`),
          message: `断点 ${bp} 缺少列配置`
        }
      }
    }

    // 检查断点值是否有效
    for (const [bp, width] of Object.entries(breakpoints)) {
      if (width < 0) {
        return {
          success: false,
          error: new Error(`Invalid breakpoint width: ${bp} = ${width}`),
          message: `无效的断点宽度: ${bp} = ${width}`
        }
      }
    }

    // 检查列数是否有效
    for (const [bp, colCount] of Object.entries(cols)) {
      if (colCount <= 0) {
        return {
          success: false,
          error: new Error(`Invalid column count: ${bp} = ${colCount}`),
          message: `无效的列数: ${bp} = ${colCount}`
        }
      }
    }

    return { success: true, data: true }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '响应式配置验证失败'
    }
  }
}

// 🔥 新增：扩展网格工具函数

/**
 * 验证扩展网格配置（支持0-99列）
 */
/**
 * 为扩展列数场景提供单独校验，和传统 12 列配置区别开来。
 */
export function validateExtendedGridConfig(colNum: number): LayoutOperationResult<boolean> {
  try {
    if (colNum < 1 || colNum > 99) {
      return {
        success: false,
        error: new Error(`Column count must be between 1 and 99, got ${colNum}`),
        message: `列数必须在1到99之间，当前为${colNum}`
      }
    }

    return { success: true, data: true }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '扩展网格配置验证失败'
    }
  }
}

/**
 * 验证大网格布局性能
 */
/**
 * 基于列数、项数和估算网格面积给出性能预警，属于静态启发式提示而非真实性能测量。
 */
export function validateLargeGridPerformance(
  layout: GridLayoutPlusItem[],
  colNum: number
): LayoutOperationResult<{ warning?: string; recommendation?: string }> {
  try {
    const itemCount = layout.length
    const gridSize = colNum * Math.max(...layout.map(item => item.y + item.h), 10) // 估算行数

    // 性能警告阈值
    const warnings: string[] = []
    const recommendations: string[] = []

    if (colNum > 50 && itemCount > 50) {
      warnings.push('大网格（>50列）配合大量组件（>50个）可能影响性能')
      recommendations.push('考虑使用虚拟滚动或分页加载')
    }

    if (gridSize > 5000) {
      warnings.push('网格总单元格数量过大，可能导致渲染缓慢')
      recommendations.push('优化网格密度或减少组件数量')
    }

    if (colNum > 80) {
      warnings.push('超过80列的网格在小屏幕上可能难以操作')
      recommendations.push('启用响应式配置，在小屏幕上减少列数')
    }

    return {
      success: true,
      data: {
        warning: warnings.length > 0 ? warnings.join('; ') : undefined,
        recommendation: recommendations.length > 0 ? recommendations.join('; ') : undefined
      }
    }
  } catch (error) {
    return {
      success: false,
      error: error as Error,
      message: '大网格性能验证失败'
    }
  }
}

/**
 * 自动优化网格项尺寸（适配大网格）
 */
/**
 * 当列数从常规网格放大到大网格时，按比例调整单项位置与宽度。
 */
export function optimizeItemForLargeGrid(
  item: GridLayoutPlusItem,
  targetCols: number,
  sourceCols = 12
): GridLayoutPlusItem {
  try {
    if (targetCols === sourceCols) return { ...item }

    const ratio = targetCols / sourceCols

    // 按比例调整位置和尺寸
    const optimized = {
      ...item,
      x: Math.floor(item.x * ratio),
      w: Math.max(1, Math.floor(item.w * ratio))
    }

    // 确保不超出边界
    if (optimized.x + optimized.w > targetCols) {
      optimized.x = Math.max(0, targetCols - optimized.w)
    }

    return optimized
  } catch (error) {
    console.error('Failed to optimize item for large grid:', error)
    return { ...item }
  }
}

