import { mount } from '@vue/test-utils'
import { afterEach, describe, expect, it, vi } from 'vitest'
import BetterScroll from './better-scroll.vue'

const mountedWrappers: Array<ReturnType<typeof mount>> = []

const mountScroll = (options: Record<string, unknown>) => {
  const wrapper = mount(BetterScroll, {
    props: { options },
    slots: { default: '<div data-test="content">content</div>' }
  })
  mountedWrappers.push(wrapper)
  return wrapper
}

afterEach(() => {
  while (mountedWrappers.length > 0) mountedWrappers.pop()?.unmount()
})

describe('BetterScroll native compatibility boundary', () => {
  it('keeps the slot and directional overflow contract', () => {
    const wrapper = mountScroll({ scrollX: true, scrollY: false, bounce: false })
    const container = wrapper.get('[data-test="native-scroll-container"]')

    expect(wrapper.get('[data-test="content"]').text()).toBe('content')
    expect(container.attributes('style')).toContain('overflow-x: auto')
    expect(container.attributes('style')).toContain('overflow-y: hidden')
  })

  it('exposes refresh, destroy, and scrollTo compatibility methods', () => {
    const scrollTo = vi.fn()
    const wrapper = mountScroll({ scrollY: true })
    const element = wrapper.get('[data-test="native-scroll-container"]').element as HTMLElement
    element.scrollTo = scrollTo
    const instance = (wrapper.vm as unknown as { instance: { refresh: () => void; destroy: () => void; scrollTo: (x: number, y: number) => void } }).instance

    expect(() => instance.refresh()).not.toThrow()
    instance.scrollTo(12, 34)
    expect(scrollTo).toHaveBeenCalledWith({ left: 12, top: 34, behavior: 'auto' })

    instance.destroy()
    instance.scrollTo(56, 78)
    expect(scrollTo).toHaveBeenCalledTimes(1)
  })

  it('reacts when scroll direction options change', async () => {
    const wrapper = mountScroll({ scrollX: false, scrollY: true })
    await wrapper.setProps({ options: { scrollX: true, scrollY: false } })

    const style = wrapper.get('[data-test="native-scroll-container"]').attributes('style')
    expect(style).toContain('overflow-x: auto')
    expect(style).toContain('overflow-y: hidden')
  })
})

/**
 * 文件用途：声明 JSON 表单转换组件 使用的类型契约。
 * 核心逻辑：集中描述组件配置、业务字段或全局类型，供实现文件和测试复用。
 * 关键注意事项：类型字段需要与真实 API、store 数据和组件入参保持一致，不能用过宽类型掩盖漂移。
 * 重构建议：可按业务对象拆分声明，并为关键类型补充类型级 fixture 或验证。
 */
// 基础选项类型，用于下拉选择、单选框组、复选框组等需要选项的表单项
interface Option {
  label: string // 显示给用户的选项文本
  value: any // 选项对应的值
  children?: Option[] // 对于级联选择器，选项可能有子选项
}

// 基础表单项属性，适用于大多数表单项
interface BasicProps {
  label?: string // 表单项的标签
  placeholder?: string // 输入框/选择框的占位符
  disabled?: boolean // 是否禁用表单项
}

// 基础表单项接口，其他所有表单项类型都将扩展此接口
interface FormItemBase {
  type: string // 表单项的类型，如 "Input", "Select"
  key: string // 表单项的唯一键，用于生成最终的表单数据对象
  props?: BasicProps // 基础属性对象
}

// 自动完成表单项，扩展基础表单项
interface AutoCompleteItem extends FormItemBase {
  type: 'AutoComplete'
  fetchSuggestions: (query: string) => Promise<Option[]> // 获取自动完成建议的函数
}

// 选择器表单项，支持单选和多选
interface SelectItem extends FormItemBase {
  type: 'Select'
  options: Option[] // 选择器的选项
  multiple?: boolean // 是否支持多选
}

// 级联选择器表单项
interface CascaderItem extends FormItemBase {
  type: 'Cascader'
  options: Option[] // 级联的选项，支持嵌套
}

// 复选框表单项
interface CheckboxItem extends FormItemBase {
  type: 'Checkbox'
  checked?: boolean // 复选框是否被选中
}

// 复选框组表单项
interface CheckboxGroupItem extends FormItemBase {
  type: 'CheckboxGroup'
  options: Option[] // 复选框组的选项
}

// 单选框表单项
interface RadioItem extends FormItemBase {
  type: 'Radio'
  checked?: boolean // 单选框是否被选中
}

// 单选框组表单项
interface RadioGroupItem extends FormItemBase {
  type: 'RadioGroup'
  options: Option[] // 单选框组的选项
}

// 开关表单项
interface SwitchItem extends FormItemBase {
  type: 'Switch'
  checked?: boolean // 开关是否开启
}

// 滑块表单项
interface SliderItem extends FormItemBase {
  type: 'Slider'
  value?: number // 滑块当前值
  min?: number // 最小值
  max?: number // 最大值
  step?: number // 步长
}

// 日期选择器表单项
interface DatePickerItem extends FormItemBase {
  type: 'DatePicker'
  value?: string // 选择的日期
}

// 时间选择器表单项
interface TimePickerItem extends FormItemBase {
  type: 'TimePicker'
  value?: string // 选择的时间
}

// 日期时间选择器表单项
interface DateTimePickerItem extends FormItemBase {
  type: 'DateTimePicker'
  value?: string // 选择的日期时间
}

// 文件上传表单项
interface UploadItem extends FormItemBase {
  type: 'Upload'
  fileList?: Array<{
    // 已上传文件列表
    name: string // 文件名
    url: string // 文件URL
  }>
}

// 动态标签（动态输入）表单项
interface DynamicTagsItem extends FormItemBase {
  type: 'DynamicTags'
  tags?: string[] // 标签数组
}

// 树选择器表单项
interface TreeSelectItem extends FormItemBase {
  type: 'TreeSelect'
  treeData: Option[] // 树形结构数据，使用Option类型，可包含children表示嵌套
}

// 输入数字表单项
interface InputNumberItem extends FormItemBase {
  type: 'InputNumber'
  value?: number // 当前值
  min?: number // 最小值
  max?: number // 最大值
}

// 评分表单项
interface RateItem extends FormItemBase {
  type: 'Rate'
  value?: number // 当前评分值
}

// 穿梭框表单项
interface TransferItem extends FormItemBase {
  type: 'Transfer'
  dataSource: Option[] // 数据源，包含所有选项
  targetKeys: any[] // 显示在右侧框数据的key集合
}

// 颜色选择器表单项
interface ColorPickerItem extends FormItemBase {
  type: 'ColorPicker'
  value?: string // 当前选择的颜色值
}

// 校验规则接口，定义表单项的校验规则
interface ValidationRule {
  required?: boolean // 是否必填
  message: string // 校验未通过时的提示信息
  validator?: (value: any) => boolean | Promise<boolean> // 自定义校验函数
}

// 表单项接口，将所有类型的表单项聚合在一起
type FormItem =
  | AutoCompleteItem
  | SelectItem
  | CascaderItem
  | CheckboxItem
  | CheckboxGroupItem
  | RadioItem
  | RadioGroupItem
  | SwitchItem
  | SliderItem
  | DatePickerItem
  | TimePickerItem
  | DateTimePickerItem
  | UploadItem
  | DynamicTagsItem
  | TreeSelectItem
  | InputNumberItem
  | RateItem
  | TransferItem
  | ColorPickerItem

// 表单JSON结构，描述整个表单
interface FormJson {
  items: FormItem[] // 包含的表单项数组
}

