import type {
  BuiltChart,
  ChartWidgetConfig,
  LocalFieldValue,
  LocalViewerFields,
  MetricWidgetConfig,
  ResolvedMetric,
  ResolvedText,
  TextWidgetConfig
} from './types'
import { LOCAL_VIEWER_LIMITS } from './types'

function ownField(fields: LocalViewerFields, name: string): LocalFieldValue | undefined {
  return Object.prototype.hasOwnProperty.call(fields, name) ? fields[name] : undefined
}

function scalar(value: LocalFieldValue | undefined): string | number | boolean | null | undefined {
  if (Array.isArray(value)) return undefined
  if (typeof value === 'string' && value.length > LOCAL_VIEWER_LIMITS.stringLength) return undefined
  if (typeof value === 'number' && !Number.isFinite(value)) return undefined
  return value as string | number | boolean | null | undefined
}

export function resolveText(config: TextWidgetConfig, fields: LocalViewerFields): ResolvedText {
  if (!config.field) return { available: true, text: config.text }
  const value = scalar(ownField(fields, config.field))
  if (value === undefined || value === null) {
    return { available: false, text: config.fallback ?? 'Unavailable' }
  }
  return { available: true, text: config.text.replaceAll('{{value}}', String(value)) }
}

export function resolveMetric(config: MetricWidgetConfig, fields: LocalViewerFields): ResolvedMetric {
  const value = scalar(ownField(fields, config.field))
  if (value === undefined || value === null || (typeof value === 'number' && !Number.isFinite(value))) {
    return { available: false, label: config.label, value: config.fallback ?? 'Unavailable', unit: '' }
  }
  const rendered = typeof value === 'number' && config.decimals !== undefined ? value.toFixed(config.decimals) : String(value)
  return { available: true, label: config.label, value: rendered, unit: config.unit ?? '' }
}

function chartData(config: ChartWidgetConfig, fields: LocalViewerFields): { categories: string[]; values: number[] } | null {
  if (config.categories && config.values) {
    return { categories: [...config.categories], values: [...config.values] }
  }
  if (!config.categoryField || !config.valueField) return null
  const categories = ownField(fields, config.categoryField)
  const values = ownField(fields, config.valueField)
  if (!Array.isArray(categories) || !Array.isArray(values) || categories.length !== values.length) return null
  if (categories.length > LOCAL_VIEWER_LIMITS.dataPoints) return null
  if (!categories.every(item => typeof item === 'string' || typeof item === 'number')) return null
  if (!values.every(item => typeof item === 'number' && Number.isFinite(item))) return null
  return { categories: categories.map(String), values: values as number[] }
}

export function buildChartOption(
  type: 'line-chart' | 'bar-chart',
  config: ChartWidgetConfig,
  fields: LocalViewerFields
): BuiltChart {
  const data = chartData(config, fields)
  const emptyOption = {
    title: { text: config.title ?? '', left: 'center' },
    xAxis: { type: 'category' as const, data: [] },
    yAxis: { type: 'value' as const },
    series: []
  }
  if (!data) return { available: false, option: emptyOption }

  return {
    available: true,
    option: {
      title: { text: config.title ?? '', left: 'center' },
      tooltip: { trigger: 'axis' },
      grid: { left: 40, right: 20, top: config.title ? 48 : 20, bottom: 32, containLabel: true },
      xAxis: { type: 'category', data: data.categories },
      yAxis: { type: 'value' },
      series: [
        {
          name: config.seriesName ?? '',
          type: type === 'line-chart' ? 'line' : 'bar',
          data: data.values,
          ...(type === 'line-chart' ? { smooth: false, showSymbol: data.values.length <= 100 } : {})
        }
      ]
    }
  }
}

import { describe, expect, it, vi } from 'vitest'
import { LOCAL_VIEWER_LIMITS } from './types'
import { normalizeLocalDashboard, normalizeLocalViewerFields } from './normalizer'

const dashboard = (widget: Record<string, unknown>) => ({ version: 1, columns: 12, rowHeight: 50, widgets: [widget] })
const textWidget = { id: 'title', x: 0, y: 0, w: 4, h: 1, type: 'text', config: { text: 'Hello' } }

describe('normalizeLocalDashboard', () => {
  it('normalizes a valid version 1 dashboard without mutating the input', () => {
    const input = dashboard(textWidget)
    const snapshot = structuredClone(input)
    const result = normalizeLocalDashboard(input)

    expect(result).toMatchObject({
      ok: true,
      dashboard: {
        version: 1,
        columns: 12,
        rowHeight: 50,
        widgets: [{ id: 'title', type: 'text', originalType: 'text' }]
      }
    })
    expect(input).toEqual(snapshot)
    expect(result.ok && Object.isFrozen(result.dashboard.widgets)).toBe(true)
  })

  it('accepts the explicit legacy layout, i, componentType and properties aliases', () => {
    const result = normalizeLocalDashboard({
      version: 1,
      layout: [{ i: 'legacy', x: 0, y: 0, w: 2, h: 2, componentType: 'line', properties: { categories: ['A'], values: [1] } }]
    })

    expect(result).toMatchObject({ ok: true, dashboard: { widgets: [{ id: 'legacy', type: 'line-chart' }] } })
  })

  it.each([
    ['unknown version', { version: 2, widgets: [] }],
    ['conflicting ids', dashboard({ ...textWidget, i: 'other' })],
    ['duplicate ids', { version: 1, widgets: [textWidget, { ...textWidget }] }],
    ['fractional layout', dashboard({ ...textWidget, x: 0.5 })],
    ['out of bounds layout', dashboard({ ...textWidget, x: 10, w: 4 })],
    ['conflicting collections', { version: 1, widgets: [], layout: [] }],
    ['remote URL', dashboard({ ...textWidget, config: { text: 'https://example.com/a' } })],
    ['script key', dashboard({ ...textWidget, config: { text: 'safe', formatter: 'x' } })],
    ['remote datasource key', dashboard({ ...textWidget, dataSource: 'local' })]
  ])('rejects %s', (_, input) => {
    expect(normalizeLocalDashboard(input).ok).toBe(false)
  })

  it('rejects functions and prototype-bearing objects', () => {
    expect(normalizeLocalDashboard(dashboard({ ...textWidget, config: { text: 'x', extra: () => 1 } })).ok).toBe(false)
    const inherited = Object.create({ version: 1 })
    inherited.widgets = []
    expect(normalizeLocalDashboard(inherited).ok).toBe(false)
  })

  it('rejects widget and chart point limits', () => {
    expect(
      normalizeLocalDashboard({
        version: 1,
        widgets: Array.from({ length: LOCAL_VIEWER_LIMITS.widgets + 1 }, (_, index) => ({ ...textWidget, id: `w-${index}` }))
      }).ok
    ).toBe(false)
    expect(
      normalizeLocalDashboard(
        dashboard({
          ...textWidget,
          type: 'bar-chart',
          config: {
            categories: Array.from({ length: LOCAL_VIEWER_LIMITS.dataPoints + 1 }, () => 'x'),
            values: Array.from({ length: LOCAL_VIEWER_LIMITS.dataPoints + 1 }, () => 1)
          }
        })
      ).ok
    ).toBe(false)
  })

  it('isolates an unknown widget type but discards all of its config', () => {
    const result = normalizeLocalDashboard(dashboard({ ...textWidget, type: 'future-safe', config: { text: 'ignored' } }))
    expect(result).toMatchObject({
      ok: true,
      dashboard: { widgets: [{ type: 'unsupported', originalType: 'future-safe', config: {} }] }
    })
  })

  it('rejects accessor properties without invoking them', () => {
    const getter = vi.fn(() => 'unsafe')
    const config = { text: 'safe' }
    Object.defineProperty(config, 'fallback', { enumerable: true, get: getter })

    expect(normalizeLocalDashboard(dashboard({ ...textWidget, config })).ok).toBe(false)
    expect(getter).not.toHaveBeenCalled()
  })
})

describe('normalizeLocalViewerFields', () => {
  it('copies and freezes bounded scalar and array fields', () => {
    const input = { status: 'online', values: [1, 2] }
    const result = normalizeLocalViewerFields(input)

    expect(result).toMatchObject({ ok: true, fields: input })
    expect(result.ok && Object.isFrozen(result.fields)).toBe(true)
    expect(result.ok && Object.isFrozen(result.fields.values)).toBe(true)
  })

  it.each([
    ['non-plain input', []],
    ['invalid field name', { 'bad field': 1 }],
    ['non-finite number', { value: Number.NaN }],
    ['nested object', { value: { nested: true } }],
    ['too many fields', Object.fromEntries(Array.from({ length: LOCAL_VIEWER_LIMITS.fields + 1 }, (_, index) => [`f${index}`, index]))],
    ['too many points', { values: Array.from({ length: LOCAL_VIEWER_LIMITS.dataPoints + 1 }, () => 1) }]
  ])('rejects %s', (_, input) => {
    expect(normalizeLocalViewerFields(input).ok).toBe(false)
  })

  it('rejects accessor fields without invoking them', () => {
    const getter = vi.fn(() => 'unsafe')
    const input = {}
    Object.defineProperty(input, 'status', { enumerable: true, get: getter })

    expect(normalizeLocalViewerFields(input).ok).toBe(false)
    expect(getter).not.toHaveBeenCalled()
  })
})

import {
  LOCAL_VIEWER_LIMITS,
  type ChartWidgetConfig,
  type LocalFieldValue,
  type LocalViewerFields,
  type LocalWidgetConfig,
  type LocalWidgetType,
  type NormalizeDashboardResult,
  type NormalizeFieldsResult,
  type NormalizedLocalWidget
} from './types'

const FORBIDDEN_KEY = /(?:script|formatter|function|url|uri|endpoint|api|websocket|datasource|device)/i
const REMOTE_VALUE = /(?:https?:\/\/|wss?:\/\/|data:|javascript:)/i
const ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/
const FIELD_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/
const TYPE_ALIASES: Readonly<Record<string, LocalWidgetType>> = {
  text: 'text',
  metric: 'metric',
  line: 'line-chart',
  'line-chart': 'line-chart',
  bar: 'bar-chart',
  'bar-chart': 'bar-chart'
}

class InvalidDashboard extends Error {}

type PlainRecord = Record<string, unknown>

function fail(message: string): never {
  throw new InvalidDashboard(message)
}

function isPlainRecord(value: unknown): value is PlainRecord {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false
  return Object.getPrototypeOf(value) === Object.prototype
}

function assertSafeTree(value: unknown, path = 'dashboard', depth = 0): void {
  if (depth > 12) fail(`${path} exceeds maximum depth`)
  if (typeof value === 'function' || typeof value === 'symbol' || typeof value === 'bigint') {
    fail(`${path} contains an unsupported value`)
  }
  if (typeof value === 'string') {
    if (value.length > LOCAL_VIEWER_LIMITS.stringLength) fail(`${path} is too long`)
    if (REMOTE_VALUE.test(value)) fail(`${path} contains a remote or executable URL`)
    return
  }
  if (Array.isArray(value)) {
    if (value.length > LOCAL_VIEWER_LIMITS.dataPoints) fail(`${path} contains too many entries`)
    value.forEach((item, index) => assertSafeTree(item, `${path}[${index}]`, depth + 1))
    return
  }
  if (value !== null && typeof value === 'object') {
    if (!isPlainRecord(value)) fail(`${path} must be a plain object`)
    for (const key of Object.keys(value)) {
      if (key === '__proto__' || key === 'prototype' || key === 'constructor' || FORBIDDEN_KEY.test(key)) {
        fail(`${path}.${key} is forbidden`)
      }
      const descriptor = Object.getOwnPropertyDescriptor(value, key)
      if (!descriptor || !('value' in descriptor)) fail(`${path}.${key} must be a data property`)
      assertSafeTree(descriptor.value, `${path}.${key}`, depth + 1)
    }
  }
}

function assertKeys(record: PlainRecord, allowed: readonly string[], path: string): void {
  const allowedSet = new Set(allowed)
  for (const key of Object.keys(record)) {
    if (!allowedSet.has(key)) fail(`${path}.${key} is not supported`)
  }
}

function integer(value: unknown, name: string, min: number, max: number): number {
  if (!Number.isInteger(value) || (value as number) < min || (value as number) > max) {
    fail(`${name} must be an integer between ${min} and ${max}`)
  }
  return value as number
}

function shortString(value: unknown, name: string, required = true): string | undefined {
  if (value === undefined && !required) return undefined
  if (typeof value !== 'string' || (required && value.length === 0) || value.length > LOCAL_VIEWER_LIMITS.stringLength) {
    fail(`${name} must be a valid string`)
  }
  return value
}

function fieldName(value: unknown, name: string, required = false): string | undefined {
  const field = shortString(value, name, required)
  if (field !== undefined && !FIELD_PATTERN.test(field)) fail(`${name} is invalid`)
  return field
}

export function normalizeLocalViewerFields(input: unknown): NormalizeFieldsResult {
  try {
    if (!isPlainRecord(input)) fail('fields must be a plain object')
    const entries = Object.keys(input)
    if (entries.length > LOCAL_VIEWER_LIMITS.fields) fail('fields contains too many entries')

    const fields: Record<string, LocalFieldValue> = {}
    for (const key of entries) {
      if (!FIELD_PATTERN.test(key)) fail(`fields.${key} has an invalid name`)
      const descriptor = Object.getOwnPropertyDescriptor(input, key)
      if (!descriptor || !('value' in descriptor)) fail(`fields.${key} must be a data property`)
      const value = descriptor.value
      const values = Array.isArray(value) ? value : [value]
      if (values.length > LOCAL_VIEWER_LIMITS.dataPoints) fail(`fields.${key} contains too many entries`)
      for (const item of values) {
        if (item !== null && typeof item !== 'string' && typeof item !== 'number' && typeof item !== 'boolean') {
          fail(`fields.${key} contains an unsupported value`)
        }
        if (typeof item === 'string' && item.length > LOCAL_VIEWER_LIMITS.stringLength) fail(`fields.${key} is too long`)
        if (typeof item === 'number' && !Number.isFinite(item)) fail(`fields.${key} must contain finite numbers`)
      }
      fields[key] = Array.isArray(value) ? Object.freeze([...values]) : (value as LocalFieldValue)
    }
    return { ok: true, fields: Object.freeze(fields) }
  } catch (error) {
    return { ok: false, error: error instanceof InvalidDashboard ? error.message : 'fields are invalid' }
  }
}

function numberArray(value: unknown, name: string): readonly number[] | undefined {
  if (value === undefined) return undefined
  if (!Array.isArray(value) || value.length > LOCAL_VIEWER_LIMITS.dataPoints) fail(`${name} must be a bounded array`)
  const result = value.map((item, index) => {
    if (typeof item !== 'number' || !Number.isFinite(item)) fail(`${name}[${index}] must be a finite number`)
    return item
  })
  return Object.freeze(result)
}

function stringArray(value: unknown, name: string): readonly string[] | undefined {
  if (value === undefined) return undefined
  if (!Array.isArray(value) || value.length > LOCAL_VIEWER_LIMITS.dataPoints) fail(`${name} must be a bounded array`)
  return Object.freeze(value.map((item, index) => shortString(item, `${name}[${index}]`) as string))
}

function normalizeConfig(type: LocalWidgetType, value: unknown, path: string): LocalWidgetConfig {
  if (!isPlainRecord(value)) fail(`${path} must be a plain object`)

  if (type === 'text') {
    assertKeys(value, ['text', 'field', 'fallback'], path)
    return Object.freeze({
      text: shortString(value.text, `${path}.text`) as string,
      field: fieldName(value.field, `${path}.field`),
      fallback: shortString(value.fallback, `${path}.fallback`, false)
    })
  }
  if (type === 'metric') {
    assertKeys(value, ['label', 'field', 'unit', 'decimals', 'fallback'], path)
    return Object.freeze({
      label: shortString(value.label, `${path}.label`) as string,
      field: fieldName(value.field, `${path}.field`, true) as string,
      unit: shortString(value.unit, `${path}.unit`, false),
      decimals: value.decimals === undefined ? undefined : integer(value.decimals, `${path}.decimals`, 0, 6),
      fallback: shortString(value.fallback, `${path}.fallback`, false)
    })
  }

  assertKeys(value, ['title', 'categoryField', 'valueField', 'categories', 'values', 'seriesName'], path)
  const config: ChartWidgetConfig = {
    title: shortString(value.title, `${path}.title`, false),
    categoryField: fieldName(value.categoryField, `${path}.categoryField`),
    valueField: fieldName(value.valueField, `${path}.valueField`),
    categories: stringArray(value.categories, `${path}.categories`),
    values: numberArray(value.values, `${path}.values`),
    seriesName: shortString(value.seriesName, `${path}.seriesName`, false)
  }
  const hasStatic = config.categories !== undefined || config.values !== undefined
  const hasFields = config.categoryField !== undefined || config.valueField !== undefined
  if (hasStatic && hasFields) fail(`${path} cannot mix static data and field bindings`)
  if (hasStatic && (!config.categories || !config.values || config.categories.length !== config.values.length)) {
    fail(`${path} static chart data must have equal category and value lengths`)
  }
  if (hasFields && (!config.categoryField || !config.valueField)) fail(`${path} requires both chart fields`)
  if (!hasStatic && !hasFields) fail(`${path} requires static data or field bindings`)
  return Object.freeze(config)
}

function normalizeWidget(value: unknown, index: number, columns: number): NormalizedLocalWidget {
  const path = `dashboard.widgets[${index}]`
  if (!isPlainRecord(value)) fail(`${path} must be a plain object`)
  assertKeys(value, ['id', 'i', 'x', 'y', 'w', 'h', 'type', 'componentType', 'config', 'properties'], path)

  const id = value.id
  const legacyId = value.i
  if (id !== undefined && legacyId !== undefined && id !== legacyId) fail(`${path} has conflicting id and i`)
  const normalizedId = shortString(id ?? legacyId, `${path}.id`) as string
  if (!ID_PATTERN.test(normalizedId)) fail(`${path}.id is invalid`)

  const rawType = value.type ?? value.componentType
  if (value.type !== undefined && value.componentType !== undefined && value.type !== value.componentType) {
    fail(`${path} has conflicting type fields`)
  }
  const originalType = shortString(rawType, `${path}.type`) as string
  const type = TYPE_ALIASES[originalType]

  if (value.config !== undefined && value.properties !== undefined) fail(`${path} has conflicting config fields`)
  const x = integer(value.x, `${path}.x`, 0, columns - 1)
  const y = integer(value.y, `${path}.y`, 0, LOCAL_VIEWER_LIMITS.rows - 1)
  const w = integer(value.w, `${path}.w`, 1, columns)
  const h = integer(value.h, `${path}.h`, 1, LOCAL_VIEWER_LIMITS.rows)
  if (x + w > columns || y + h > LOCAL_VIEWER_LIMITS.rows) fail(`${path} exceeds dashboard bounds`)

  return Object.freeze({
    id: normalizedId,
    x,
    y,
    w,
    h,
    type: type ?? 'unsupported',
    originalType,
    config: type ? normalizeConfig(type, value.config ?? value.properties ?? {}, `${path}.config`) : Object.freeze({})
  })
}

export function normalizeLocalDashboard(input: unknown): NormalizeDashboardResult {
  try {
    assertSafeTree(input)
    if (!isPlainRecord(input)) fail('dashboard must be a plain object')
    assertKeys(input, ['version', 'columns', 'rowHeight', 'widgets', 'layout'], 'dashboard')
    if (input.version !== 1) fail('dashboard.version must be 1')
    if (input.widgets !== undefined && input.layout !== undefined) fail('dashboard has conflicting widget collections')
    const source = input.widgets ?? input.layout
    if (!Array.isArray(source)) fail('dashboard.widgets must be an array')
    if (source.length > LOCAL_VIEWER_LIMITS.widgets) fail('dashboard has too many widgets')
    const columns = input.columns === undefined ? 24 : integer(input.columns, 'dashboard.columns', 1, LOCAL_VIEWER_LIMITS.columns)
    const rowHeight = input.rowHeight === undefined ? 60 : integer(input.rowHeight, 'dashboard.rowHeight', 20, 200)
    const widgets = source.map((widget, index) => normalizeWidget(widget, index, columns))
    const ids = new Set<string>()
    for (const widget of widgets) {
      if (ids.has(widget.id)) fail(`dashboard contains duplicate widget id ${widget.id}`)
      ids.add(widget.id)
    }
    return { ok: true, dashboard: Object.freeze({ version: 1, columns, rowHeight, widgets: Object.freeze(widgets) }) }
  } catch (error) {
    return { ok: false, error: error instanceof InvalidDashboard ? error.message : 'dashboard is invalid' }
  }
}

import type { ECOption } from '@/hooks/chart/use-echarts'

export const LOCAL_VIEWER_LIMITS = {
  widgets: 64,
  columns: 24,
  rows: 200,
  stringLength: 1000,
  dataPoints: 500,
  fields: 200
} as const

export type LocalWidgetType = 'text' | 'metric' | 'line-chart' | 'bar-chart'

export type LocalFieldValue = string | number | boolean | null | readonly (string | number | boolean | null)[]
export type LocalViewerFields = Readonly<Record<string, LocalFieldValue>>

export interface TextWidgetConfig {
  text: string
  field?: string
  fallback?: string
}

export interface MetricWidgetConfig {
  label: string
  field: string
  unit?: string
  decimals?: number
  fallback?: string
}

export interface ChartWidgetConfig {
  title?: string
  categoryField?: string
  valueField?: string
  categories?: readonly string[]
  values?: readonly number[]
  seriesName?: string
}

export type LocalWidgetConfig = TextWidgetConfig | MetricWidgetConfig | ChartWidgetConfig

export interface NormalizedLocalWidget {
  id: string
  x: number
  y: number
  w: number
  h: number
  type: LocalWidgetType | 'unsupported'
  originalType: string
  config: LocalWidgetConfig | Readonly<Record<string, never>>
}

export interface NormalizedLocalDashboard {
  version: 1
  columns: number
  rowHeight: number
  widgets: readonly NormalizedLocalWidget[]
}

export type NormalizeDashboardResult =
  | { ok: true; dashboard: NormalizedLocalDashboard }
  | { ok: false; error: string }

export type NormalizeFieldsResult =
  | { ok: true; fields: LocalViewerFields }
  | { ok: false; error: string }

export interface ResolvedText {
  available: boolean
  text: string
}

export interface ResolvedMetric {
  available: boolean
  label: string
  value: string
  unit: string
}

export interface BuiltChart {
  available: boolean
  option: ECOption
}

