        type: 'thingsvis:requestFieldData',
        payload: { dataSourceId: 'ds-1', deviceId: 'dev-1', fieldIds: ['temp', 'device_alarm_count'] }
      },
      client.trustedSource,
      'https://evil.test'
    )
    await dispatchWindowMessage(
      {
        type: 'thingsvis:requestFieldData',
        payload: { dataSourceId: 'ds-1', deviceId: 'dev-1', fieldIds: ['temp'] }
      },
      wrongSource
    )

    expect(hoisted.telemetryDataPub).toHaveBeenCalledTimes(0)
    expect(hoisted.attributeDataPub).toHaveBeenCalledTimes(0)
    expect(hoisted.commandDataPub).toHaveBeenCalledTimes(0)
    expect(hoisted.deviceAlarmStatus).toHaveBeenCalledTimes(0)
    expect(hoisted.telemetryDataHistoryList).toHaveBeenCalledTimes(0)
    expect(client.pushPlatformFieldData).toHaveBeenCalledTimes(0)
    expect(client.postMessageToGuest).toHaveBeenCalledTimes(0)
  })

  it('answers field-data requests with current data, alarm fields, explicit history, and buffered history prefill', async () => {
    await mountWidget({
      data: { temp: 25, flow: 8 },
      deviceId: 'dev-1'
    })
    const client = latestClient()
    await markClientReady(client)

    await dispatchWindowMessage({
      type: 'thingsvis:requestFieldData',
      payload: {
        dataSourceId: 'ds-1',
        deviceId: 'dev-1',
        fieldIds: ['temp', 'temp__history', 'device_alarm_count', 'device_alarm_highest_level'],
        historyConfig: { aggFunction: 'AVG', aggWindow: '1m' }
      }
    })

    expect(hoisted.deviceAlarmStatus).toHaveBeenCalledWith({ device_id: 'dev-1', page: 1, page_size: 20 })
    expect(hoisted.telemetryDataHistoryList).toHaveBeenCalledWith(
      {
        device_id: 'dev-1',
        key: 'temp',
        time_range: 'last_7d',
        aggregate_window: '1m',
        aggregate_function: 'AVG'
      },
      { silentError: true }
    )
    expect(client.pushPlatformFieldHistory).toHaveBeenCalledWith(
      'temp',
      [
        { timestamp: '2026-06-27T01:00:00.000Z', ts: Date.parse('2026-06-27T01:00:00.000Z'), value: 10 },
        { timestamp: 1782514800000, ts: 1782514800000, value: 12 }
      ],
      'dev-1'
    )
    expect(client.pushPlatformFieldData).toHaveBeenLastCalledWith(
      {
        temp: 25,
        temp__history: [
          { timestamp: '2026-06-27T01:00:00.000Z', ts: Date.parse('2026-06-27T01:00:00.000Z'), value: 10 },
          { timestamp: 1782514800000, ts: 1782514800000, value: 12 }
        ],
        device_alarm_count: 2,
        device_alarm_highest_level: 'warning'
      },
      'dev-1'
    )
  })

  it('selects highest active alarm severity instead of the first active alarm row', async () => {
    hoisted.deviceAlarmStatus.mockResolvedValueOnce({
      data: {
        total: 2,
        list: [
          { alarm_status: 'active', alarm_level: 'warning', alarm_name: 'Recent warning', last_trigger_time: '10:30' },
          {
            alarm_status: 'active',
            alarm_level: 'critical',
            alarm_name: 'Critical pressure',
            last_trigger_time: '10:00'
          }
        ]
      }
    })
    await mountWidget({
      data: {},
      deviceId: 'dev-1'
    })
    const client = latestClient()
    await markClientReady(client)

    await dispatchWindowMessage({
      type: 'thingsvis:requestFieldData',
      payload: {
        dataSourceId: 'ds-1',
        deviceId: 'dev-1',
        fieldIds: ['device_alarm_highest_level', 'latest_device_alarm_level']
      }
    })

    expect(client.pushPlatformFieldData).toHaveBeenLastCalledWith(
      {
        device_alarm_highest_level: 'critical',
        latest_device_alarm_level: 'warning'
      },
      'dev-1'
    )
  })

  it('ignores field-data requests for a different preview device and skips template-device history/alarm API calls', async () => {
    await mountWidget({ deviceId: '__template__', platformDevices: [] })
    const client = latestClient()
    await markClientReady(client)

    await dispatchWindowMessage({
      type: 'thingsvis:requestFieldData',
      payload: { dataSourceId: 'ds-1', deviceId: 'other-device', fieldIds: ['temp'] }
    })
    await dispatchWindowMessage({
      type: 'thingsvis:requestFieldData',
      payload: { dataSourceId: 'ds-1', deviceId: '__template__', fieldIds: ['temp__history', 'device_alarm_count'] }
    })

    expect(hoisted.deviceAlarmStatus).toHaveBeenCalledTimes(0)
    expect(hoisted.telemetryDataHistoryList).toHaveBeenCalledTimes(0)
    expect(client.pushPlatformFieldData).not.toHaveBeenLastCalledWith(
      expect.objectContaining({ device_alarm_count: 2 }),
      '__template__'
    )
  })

  it('reacts to config, data, and schema prop changes after the client is ready', async () => {
    const wrapper = await mountWidget()
    const client = latestClient()
    await markClientReady(client)
    client.loadWidgetConfig.mockClear()
    client.pushPlatformFieldData.mockClear()
    client.updateSchema.mockClear()

    await wrapper.setProps({
      config: {
        ...widgetConfig(),
        nodes: [{ id: 'simple-node', type: 'text', props: { text: 'changed' } }]
      }
    })
    await wrapper.setProps({ data: { temp: 30 } })
    await wrapper.setProps({ platformFields: [{ id: 'flow', dataType: 'telemetry', type: 'number' }] })
    await flushAsync()

    expect(client.loadWidgetConfig).toHaveBeenCalledTimes(1)
    expect(client.pushPlatformFieldData).toHaveBeenCalledWith({ temp: 30 }, 'dev-1')
    expect(client.updateSchema).toHaveBeenCalledWith([{ id: 'flow', dataType: 'telemetry', type: 'number' }])
  })

  it('emits save/change from SDK save events, exposes triggerSave and pushPlatformData, and destroys the client on unmount', async () => {
    const wrapper = await mountWidget()
    const client = latestClient()
    await markClientReady(client)

    client.handlers.get('tv:save-config')?.({ config: { id: 'saved-config', nodes: [] } })
    await flushAsync()
    expect(wrapper.emitted('save')).toEqual([[{ id: 'saved-config', nodes: [] }]])
    expect(wrapper.emitted('change')).toEqual([[{ id: 'saved-config', nodes: [] }]])

    wrapper.vm.triggerSave()
    wrapper.vm.pushPlatformData({ temp: 31 }, 'dev-1')

    expect(client.requestSave).toHaveBeenCalledTimes(1)
    expect(client.pushPlatformFieldData).toHaveBeenLastCalledWith({ temp: 31 }, 'dev-1')

    wrapper.unmount()
    expect(client.destroy).toHaveBeenCalledTimes(1)
  })
})

﻿<!--
  Embeds a ThingsVis runtime iframe inside the AetherLink frontend.
  The host owns widget bootstrap, message routing, device data requests, and save handoff.
  Host keys, message types, and compatibility aliases are external contracts and must stay stable.
-->
<!--
  文件说明：
  - 在 AetherLink 前端中嵌入 ThingsVis 运行时 iframe，承担宿主层桥接职责。
  - 负责 widget 初始化、host/guest 消息路由、字段读写、历史数据补齐与保存回传。
  维护提示：
  - message type、provider、saveTarget、兼容别名都属于跨系统契约，改动要非常谨慎。
  - 这里同时覆盖编辑态与预览态，任何设备上下文判断都要考虑 thing-model/current-device/dashboard 三种场景。
-->
<template>
  <div ref="container" class="thingsvis-widget-container"></div>
</template>

<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, watch } from 'vue'
import { bindWindowGuestMessage } from '@/components/thingsvis/hostBridge'
import { createThingsVisWidgetFieldHistoryBridge } from '@/components/thingsvis/thingsvisWidgetFieldHistoryBridge'
import { createThingsVisWidgetFieldRequestHandler } from '@/components/thingsvis/thingsvisWidgetFieldRequestBridge'
import { createThingsVisWidgetPlatformWriteHandler } from '@/components/thingsvis/thingsvisWidgetPlatformWriteBridge'
import {
  THINGSVIS_CONTENT_HEIGHT_MESSAGE_TYPES,
  createThingsVisContentHeightReporter,
  readThingsVisContentHeight,
  type ThingsVisContentHeightReporter
} from '@/components/thingsvis/thingsvisContentHeightReporter'
import {
  getThingsVisFieldRoot as getFieldRoot,
  normalizeThingsVisWidgetLoadConfig,
  parseThingsVisFieldBindingExpression as parseFieldBindingExpression
} from '@/components/thingsvis/thingsvisWidgetConfigNormalizer'
import {
  THINGSVIS_WIDGET_TEMPLATE_DEVICE_ID,
  createThingsVisWidgetRuntimeContract
} from '@/components/thingsvis/thingsvisWidgetRuntimeContractBridge'
import { createThingsVisWidgetWriteNormalizer } from '@/components/thingsvis/thingsvisWidgetWriteNormalizer'
import { ThingsVisClient } from '@/utils/thingsvis/sdk/client'
import {
  attributeDataPub,
  commandDataPub,
  deviceAlarmStatus,
  telemetryDataHistoryList,
  telemetryDataPub
} from '@/service/api/device'
import { getThingsVisStudioBaseUrl } from '@/utils/thingsvis/constants'
import { getThingsVisToken } from '@/utils/thingsvis'

const HISTORY_FIELD_SUFFIX = '__history'
const DEVICE_ALARM_STATUS_FIELD_IDS = new Set([
  'device_alarm_active',
  'device_alarm_count',
  'device_alarm_highest_level',
  'latest_device_alarm_title',
  'latest_device_alarm_level',
  'latest_device_alarm_time'
])
const RUNTIME_STATUS_FIELD_IDS = new Set(['is_online', 'online_text', 'online_status_updated_at'])

const clone = <T,>(value: T): T => {
  if (value === undefined || value === null) return value
  if (typeof structuredClone === 'function') {
    try {
      return structuredClone(value)
    } catch {
      // Vue proxies and SDK mocks can contain non-cloneable internals; JSON keeps the widget payload contract plain.
    }
  }
  return JSON.parse(JSON.stringify(value)) as T
}

const props = defineProps<{
  /** Initial configuration (JSON page schema) */
  config: any
  /** Optional: real-time data pushed by the host */
  data?: Record<string, any>
  /** Optional: platform field schema forwarded to the ThingsVis editor */
  platformFields?: any[]
  /** Optional: device entries forwarded to the ThingsVis editor (enables Device Fields in Field Picker) */
  platformDevices?: any[]
  /** Optional: iframe height */
  height?: string
  /** Render mode: 'viewer' (read-only preview) | 'editor' (visual editor) */
  mode?: 'viewer' | 'editor'
  /** Optional: current device ID used to route tv:platform-write back to the platform API */
  deviceId?: string
  /** Optional: ring buffer capacity for current device platform data. */
  bufferSize?: number
}>()

const emit = defineEmits<{
  (e: 'save', config: any): void
  (e: 'change', config: any): void
  (e: 'ready'): void
}>()

const container = ref<HTMLElement | null>(null)
let client: ThingsVisClient | null = null
let platformFieldDataFrame: number | null = null
let widgetConfigFrame: number | null = null
let widgetSchemaFrame: number | null = null
let widgetInitGeneration = 0
let widgetDisposed = false
let contentHeightReporter: ThingsVisContentHeightReporter | null = null
const pendingPlatformFieldData = new Map<string, Record<string, unknown>>()

const runtimeContract = createThingsVisWidgetRuntimeContract({
  getDeviceId: () => props.deviceId,
  getMode: () => props.mode,
  getBufferSize: () => props.bufferSize,
  getPlatformFields: () => props.platformFields,
  getPlatformDevices: () => props.platformDevices,
  cloneValue: clone
})

const getPreviewDeviceId = runtimeContract.getPreviewDeviceId
const getFieldValueTypeMap = runtimeContract.getFieldValueTypeMap
const getFieldDataTypeMap = runtimeContract.getFieldDataTypeMap

const normalizeWriteData = createThingsVisWidgetWriteNormalizer({
  getConfig: () => props.config,
  historyFieldSuffix: HISTORY_FIELD_SUFFIX,
  getFieldValueTypeMap,
  parseFieldBindingExpression
})

const fieldHistoryBridge = createThingsVisWidgetFieldHistoryBridge({
  getConfig: () => props.config,
  historyFieldSuffix: HISTORY_FIELD_SUFFIX,
  templateDeviceId: THINGSVIS_WIDGET_TEMPLATE_DEVICE_ID,
  runtimeStatusFieldIds: RUNTIME_STATUS_FIELD_IDS,
  getFieldDataTypeMap,
  getFieldRoot,
  parseFieldBindingExpression,
  loadTelemetryHistory: telemetryDataHistoryList
})

const getLoadOptions = runtimeContract.getLoadOptions

const flushPlatformFieldData = () => {
  platformFieldDataFrame = null
  if (!client) {
    pendingPlatformFieldData.clear()
    return
  }

  pendingPlatformFieldData.forEach((fields, deviceId) => {
    if (!deviceId) return
    const payload = clone(fields) || {}
    client?.pushPlatformFieldData(payload, deviceId)
  })
  pendingPlatformFieldData.clear()
}

const schedulePlatformFieldDataFlush = () => {
  if (platformFieldDataFrame !== null) return
  platformFieldDataFrame = window.requestAnimationFrame(flushPlatformFieldData)
}

const pushPlatformFieldData = (fields: Record<string, unknown>, deviceId?: string) => {
  if (!client) return
  if (!deviceId) return
  pendingPlatformFieldData.set(deviceId, {
    ...(pendingPlatformFieldData.get(deviceId) || {}),
    ...fields
  })
  schedulePlatformFieldDataFlush()
}

const pushPlatformFieldDataNow = (fields: Record<string, unknown>, deviceId?: string) => {
  pushPlatformFieldData(fields, deviceId)
  if (platformFieldDataFrame !== null) {
    window.cancelAnimationFrame(platformFieldDataFrame)
    platformFieldDataFrame = null
  }
  flushPlatformFieldData()
}

function normalizeLoadConfig(config: any) {
  return normalizeThingsVisWidgetLoadConfig(config, {
    mode: props.mode,
    previewDeviceId: getPreviewDeviceId(),
    fieldValueTypes: getFieldValueTypeMap()
  })
}

const pushPlatformFieldHistory = (
  fieldId: string,
  history: Array<{ value: unknown; ts: number }>,
  deviceId?: string
) => {
  if (!client) return
  if (!deviceId) return
  client.pushPlatformFieldHistory(fieldId, clone(history) || [], deviceId)
}

const isTrustedThingsVisMessageEvent = (event: MessageEvent) => {
  return !!client?.isTrustedMessageEvent(event)
}

const handlePlatformWrite = createThingsVisWidgetPlatformWriteHandler({
  isTrustedMessageEvent: isTrustedThingsVisMessageEvent,
  postMessageToGuest: (message) => client?.postMessageToGuest(message),
  getPreviewDeviceId,
  getFieldDataTypeMap,
  normalizeWriteData,
  publishAttributeData: attributeDataPub,
  publishCommandData: commandDataPub,
  publishTelemetryData: telemetryDataPub
})

const handleFieldDataRequest = createThingsVisWidgetFieldRequestHandler({
  isTrustedMessageEvent: isTrustedThingsVisMessageEvent,
  getPreviewDeviceId,
  historyFieldSuffix: HISTORY_FIELD_SUFFIX,
  templateDeviceId: THINGSVIS_WIDGET_TEMPLATE_DEVICE_ID,
  alarmStatusFieldIds: DEVICE_ALARM_STATUS_FIELD_IDS,
  getCurrentData: () => props.data,
  collectConfiguredHistoryFields: fieldHistoryBridge.collectConfiguredHistoryFields,
  shouldPrefillHistoryForDataSource: fieldHistoryBridge.shouldPrefillHistoryForDataSource,
  fetchTelemetryHistoryField: fieldHistoryBridge.fetchTelemetryHistoryField,
  pushPlatformFieldHistory,
  loadAlarmStatus: (deviceId) => deviceAlarmStatus({ device_id: deviceId, page: 1, page_size: 20 }),
  pushPlatformFieldData: pushPlatformFieldDataNow
})

// Resolve the device context currently bound to this widget.
const getCurrentPlatformDeviceId = () => props.deviceId || getPreviewDeviceId()

const fetchThingsVisUrlToken = async () => {
  try {
    return (await getThingsVisToken()) || ''
  } catch (error) {
    console.error('[ThingsVisWidget] getThingsVisToken failed, continuing without URL token:', error)
    return ''
  }
}

const createThingsVisWidgetClient = (hostElement: HTMLElement, targetUrl: string) => {
  return new ThingsVisClient({
    container: hostElement,
    mode: 'widget',
    url: targetUrl,
    style: {
      height: props.height || '100%',
      minHeight: '400px'
    }
  })
}

const loadCurrentWidgetConfig = () => {
  client?.loadWidgetConfig(
    normalizeLoadConfig(clone(props.config || {})),
    clone(props.platformFields || []),
    getLoadOptions()
  )
}

const updateCurrentWidgetSchema = () => {
  if (props.platformFields) client?.updateSchema(clone(props.platformFields))
}

const scheduleWidgetConfigLoad = () => {
  if (widgetConfigFrame !== null) return
  widgetConfigFrame = window.requestAnimationFrame(() => {
    widgetConfigFrame = null
    loadCurrentWidgetConfig()
  })
}

const scheduleWidgetSchemaUpdate = () => {
  if (widgetSchemaFrame !== null) return
  widgetSchemaFrame = window.requestAnimationFrame(() => {
    widgetSchemaFrame = null
    updateCurrentWidgetSchema()
  })
}

const pushCurrentWidgetData = () => {
  if (props.data) pushPlatformFieldDataNow(props.data, getCurrentPlatformDeviceId())
}

const handleThingsVisClientReady = () => {
  // loadWidgetConfig (tv:init) must run before emit('ready') so parent pushes
  // arrive after the iframe has registered platform data sources.
  loadCurrentWidgetConfig()
  updateCurrentWidgetSchema()
  pushCurrentWidgetData()
  emit('ready')
}

const handleThingsVisSaveConfig = (payload: any) => {
  // Keep accepting both save payload shapes exposed by existing guest runtimes:
  // 1. triggerSave path: payload = { canvas, nodes, dataBindings, thumbnail, meta }
  // 2. request-save path: payload = { config: { meta, canvas, nodes, dataSources } }
  const config = payload?.config || payload
  emit('save', config)
  emit('change', config)
}

const handleThingsVisContentHeight = (payload: any) => {
  const height = readThingsVisContentHeight(payload)
  if (height === null) return

  if (container.value) {
    container.value.style.minHeight = `${Math.ceil(height)}px`
  }

  contentHeightReporter?.report(height, {
    source: 'thingsvis-widget',
    mode: props.mode || 'viewer'
  })
}

const registerThingsVisClientHandlers = () => {
  const handlers: Array<[string, (...args: any[]) => void]> = [
    ['ready', handleThingsVisClientReady],
    ['tv:save-config', handleThingsVisSaveConfig],
    ...THINGSVIS_CONTENT_HEIGHT_MESSAGE_TYPES.map(
      eventName => [eventName, handleThingsVisContentHeight] as [string, (...args: any[]) => void]
    )
  ]

  handlers.forEach(([eventName, handler]) => {
    client?.on(eventName, handler)
  })
}

type WindowMessageHandler = (event: MessageEvent) => void

let unbindWindowMessageHandlers: Array<() => void> = []

const registerWindowMessageHandlers = () => {
  const handlers: WindowMessageHandler[] = [handlePlatformWrite, handleFieldDataRequest]
  unbindWindowMessageHandlers = handlers.map((handler) => bindWindowGuestMessage(handler))
}

const unregisterWindowMessageHandlers = () => {
  unbindWindowMessageHandlers.forEach((unbind) => unbind())
  unbindWindowMessageHandlers = []
}

const startContentHeightReporting = () => {
  contentHeightReporter?.stop()
  contentHeightReporter = createThingsVisContentHeightReporter({
    getElement: () => container.value,
    getExtraPayload: () => ({
      source: 'thingsvis-widget-shell',
      mode: props.mode || 'viewer'
    })
  })
  contentHeightReporter.start()
}

const initializeThingsVisWidget = async () => {
  const hostElement = container.value
  if (!hostElement) return

  widgetDisposed = false
  const initGeneration = ++widgetInitGeneration

  const baseUrl = getThingsVisStudioBaseUrl()
  const token = await fetchThingsVisUrlToken()
  if (widgetDisposed || initGeneration !== widgetInitGeneration || container.value !== hostElement) return

  const targetUrl = runtimeContract.buildWidgetUrl(baseUrl, token)

  client = createThingsVisWidgetClient(hostElement, targetUrl)
  registerThingsVisClientHandlers()
}

const runWhenClientReady = (value: unknown, action: () => void) => {
  if (client?.ready && value) {
    action()
  }
}

onMounted(async () => {
  // Keep host message listeners alive for the lifetime of this component instance.
  registerWindowMessageHandlers()
  startContentHeightReporting()
  await initializeThingsVisWidget()
})

watch(
  () => props.config,
  (newVal) => {
    runWhenClientReady(newVal, scheduleWidgetConfigLoad)
  },
  { deep: true }
)

watch(
  () => props.data,
  (newVal) => {
    runWhenClientReady(newVal, () => {
      pushPlatformFieldData(newVal as Record<string, unknown>, getCurrentPlatformDeviceId())
    })
  },
  { deep: true }
)

watch(
  () => props.platformFields,
  (newVal) => {
    runWhenClientReady(newVal, scheduleWidgetSchemaUpdate)
  },
  { deep: true }
)

// Host -> Guest -> Host save handshake.
const triggerSave = () => {
  client?.requestSave()
}

/**
 * Forward a real-time field value batch to the embedded ThingsVis widget.
 * Uses closure reference to `client` so it always reflects the live instance,
 * unlike the exposed `client` property which is snapshotted as null at setup time.
 */
const pushPlatformData = (fields: Record<string, unknown>, deviceId?: string) => {
  pushPlatformFieldDataNow(fields, deviceId)
}

const destroyThingsVisWidget = () => {
  widgetDisposed = true
  widgetInitGeneration += 1
  if (platformFieldDataFrame !== null) {
    window.cancelAnimationFrame(platformFieldDataFrame)
    platformFieldDataFrame = null
  }
  if (widgetConfigFrame !== null) {
    window.cancelAnimationFrame(widgetConfigFrame)
    widgetConfigFrame = null
  }
  if (widgetSchemaFrame !== null) {
    window.cancelAnimationFrame(widgetSchemaFrame)
    widgetSchemaFrame = null
  }
  pendingPlatformFieldData.clear()
  contentHeightReporter?.stop()
  contentHeightReporter = null
  if (!client) return
  client.destroy()
  client = null
}

onBeforeUnmount(() => {
  unregisterWindowMessageHandlers()
  destroyThingsVisWidget()
})

defineExpose({
  triggerSave,
  client,
  pushPlatformData
})
</script>

<style scoped>
.thingsvis-widget-container {
  width: 100%;
  min-height: 100%;
  position: relative;
  /* Do not clip the guest iframe content. */
  overflow: auto;
  /* Keep a minimum host height so the iframe cannot collapse. */
  min-height: 400px;
}
</style>

/**
 * 文件说明：
 * - 将 guest 侧发来的字段读取消息规范化为宿主侧可执行的请求对象。
 * - 核心职责是做字段数组清洗和目标设备解析，不参与实际数据获取。
 */
import { normalizeRequestedFieldIds } from '@/components/thingsvis/fieldReadBridge'

export type PlatformFieldReadRequestInput<TPayload extends { fieldIds?: unknown; deviceId?: string } | undefined> = {
  payload: TPayload
  resolveTargetDeviceId: (payload: TPayload) => string | null | undefined
}

export type PlatformFieldReadRequest<TPayload> = {
  payload: TPayload
  fieldIds: string[]
  targetDeviceId?: string
}

export function resolvePlatformFieldReadRequest<
  TPayload extends { fieldIds?: unknown; deviceId?: string } | undefined
>(input: PlatformFieldReadRequestInput<TPayload>): PlatformFieldReadRequest<TPayload> | null {
  const fieldIds = normalizeRequestedFieldIds(input.payload?.fieldIds)
  if (fieldIds.length === 0) return null

  const targetDeviceId = input.resolveTargetDeviceId(input.payload)
  // 允许 undefined，表示继续走宿主默认设备；显式 null 则代表本次请求应被拒绝。
  if (targetDeviceId === null) return null

  return {
    payload: input.payload,
    fieldIds,
    targetDeviceId: targetDeviceId || undefined
  }
}

/**
 * 文件说明：
 * - 承接 ThingsVisAppFrame 中 iframe 初始化、`tv:ready` 调度、viewer/editor 分流和卸载清理编排。
 * - 负责 token/url 初始化、dashboard preload、`tv:init` 发送、viewer 补水启动和 editor 预取触发。
 * 维护提示：
 * - 这里属于宿主生命周期编排层，不应重新吸收 transport、安全校验或设备目录业务细节。
 * - `tv:ready` 去重、iframe load reset、viewer/editor 分支和卸载清理顺序都属于敏感契约，修改前要逐条核对。
 */
import { onBeforeUnmount, onMounted, watch, type Ref } from 'vue'
import {
  buildThingsVisInitConfig,
  buildThingsVisInitMessage,
  loadDashboardPayloadForInit as loadDashboardPayloadForInitBridge
} from '@/components/thingsvis/thingsvisInitBridge'
import { createThingsVisInitScheduler } from '@/components/thingsvis/thingsvisInitSchedulerBridge'
import {
  buildThingsVisHostDiagnostic,
  type ThingsVisHostDiagnostic
} from '@/components/thingsvis/thingsvisHostErrorPayload'
import { buildThingsVisFrameUrl } from '@/components/thingsvis/thingsvisFrameBridge'
import { getThingsVisToken } from '@/utils/thingsvis'
import {
  THINGSVIS_COMPAT_PROVIDER,
  getPlatformApiBase,
  getThingsVisApiBase,
  getThingsVisStudioBaseUrl
} from '@/utils/thingsvis/constants'
import { localStg } from '@/utils/storage'

const THINGSVIS_SAVE_TARGET = 'host'

type ThingsVisAppFrameLifecycleOptions = {
  iframeRef: Ref<HTMLIFrameElement | undefined>
  token: Ref<string>
  url: Ref<string>
  getId: () => string
  getMode: () => string | undefined
  getSchema: () => any
  getTargetOrigin: () => string
  bindMessageHandler: (handler: (event: MessageEvent) => void | Promise<void>) => () => void
  handleMessage: (event: MessageEvent) => void | Promise<void>
  fetchDashboardWithRetry: (id: string) => Promise<any>
  normalizeDashboardConfig: (config: any) => any
  sanitizeDataSourcesForHostSave: (config: any) => any
  resolvePlatformBufferSize: (dataSources: unknown) => number
  resolveRuntimeDeviceId: (dashboardPayload: Record<string, unknown>) => string | undefined
  scheduleViewerHydration: () => void
  prefetchEditor: (dashboardPayload: Record<string, unknown>) => Promise<unknown> | void
  disposeEditorPrefetch: () => void
  disconnectAllDeviceWs: () => void
  resetViewerHydrationState: () => void
  disposeViewerHydration: () => void
  clearPlatformRuntimeDevices: () => void
  clearPlatformDataSourceBindings: () => void
  resetCatalog: () => void
  onDiagnostic?: (diagnostic: ThingsVisHostDiagnostic) => void
  onRecovered?: () => void
  logger: {
    warn: (message: string, ...args: any[]) => void
    error: (message: string, ...args: any[]) => void
  }
}

export type ThingsVisAppFrameLifecycle = {
  handleIframeLoad: () => void
  handleLoadedFrameMessage: () => void
  handleReadyFrameMessage: () => void
  handleRequestInitFrameMessage: () => void
}

export function useThingsVisAppFrameLifecycle(options: ThingsVisAppFrameLifecycleOptions): ThingsVisAppFrameLifecycle {
  let unbindWindowGuestMessage: (() => void) | null = null

  function cancelEditorPrefetch() {
    options.disposeEditorPrefetch()
  }

  function startEditorPrefetch(dashboardPayload: Record<string, unknown>) {
    cancelEditorPrefetch()

    void options.prefetchEditor(dashboardPayload)
  }

  function buildInitSignature() {
    return JSON.stringify({
      id: options.getId(),
      mode: options.getMode(),
      token: options.token.value,
      url: options.url.value
    })
  }

  async function loadDashboardPayloadForInit(): Promise<Record<string, unknown> | null> {
    return loadDashboardPayloadForInitBridge({
      propsId: options.getId(),
      schema: options.getSchema(),
      mode: options.getMode(),
      fetchDashboardWithRetry: options.fetchDashboardWithRetry,
      normalizeDashboardConfig: options.normalizeDashboardConfig,
      sanitizeDataSourcesForHostSave: options.sanitizeDataSourcesForHostSave,
      onPreloadUnavailable: (id, error) => {
        options.logger.warn('[AppFrame] Dashboard preload unavailable, deferring init:', id, error)
      },
      onPreloadError: (id, error) => {
        options.logger.warn('[AppFrame] Failed to preload dashboard schema for embed init:', id, error)
      }
    })
  }

  function getPlatformTokenConfig(): { platformToken?: string } {
    const platformToken = localStg.get('token') as string | undefined
    return platformToken ? { platformToken } : {}
  }

  function postInitMessage(
    dashboardPayload: Record<string, unknown>,
    platformBufferSize: number,
    runtimeDeviceId?: string
  ) {
    options.iframeRef.value?.contentWindow?.postMessage(
      buildThingsVisInitMessage(
        dashboardPayload,
        platformBufferSize,
        buildThingsVisInitConfig({
          token: options.token.value,
          platformToken: getPlatformTokenConfig().platformToken,
          thingsvisApiBaseUrl: getThingsVisApiBase(),
          platformApiBaseUrl: getPlatformApiBase(),
          runtimeDeviceId
        })
      ),
      options.getTargetOrigin()
    )
  }

  function afterInitPosted(dashboardPayload: Record<string, unknown>) {
    cancelEditorPrefetch()

    if (options.getMode() === 'viewer') {
      options.scheduleViewerHydration()
      return
    }

    options.disconnectAllDeviceWs()
    startEditorPrefetch(dashboardPayload)
  }

  async function runInitOnce(): Promise<boolean> {
    if (!options.iframeRef.value?.contentWindow || !options.token.value || !options.getId()) return false

    const dashboardPayload = await loadDashboardPayloadForInit()
    if (!dashboardPayload) return false

    const platformBufferSize = Math.max(100, options.resolvePlatformBufferSize(dashboardPayload.dataSources))
    const runtimeDeviceId = options.resolveRuntimeDeviceId(dashboardPayload)

    postInitMessage(dashboardPayload, platformBufferSize, runtimeDeviceId)
    afterInitPosted(dashboardPayload)
    return true
  }

  const initScheduler = createThingsVisInitScheduler({
    canInit: () => Boolean(options.iframeRef.value?.contentWindow && options.token.value && options.getId()),
    getSignature: buildInitSignature,
    runInit: runInitOnce
  })

  function scheduleInit(delay = 150) {
    initScheduler.schedule(delay)
  }

  function handleIframeLoad() {
    cancelEditorPrefetch()
    initScheduler.resetAfterFrameLoad()
  }

  function handleLoadedFrameMessage() {
    if (options.getMode() === 'viewer') {
      options.scheduleViewerHydration()
    }
  }

  function handleReadyFrameMessage() {
    scheduleInit()
  }

  function handleRequestInitFrameMessage() {
    initScheduler.invalidate()
    scheduleInit()
  }

  onMounted(async () => {
    unbindWindowGuestMessage = options.bindMessageHandler(options.handleMessage)

    try {
      const tokenStr = await getThingsVisToken()
      if (tokenStr) {
        options.token.value = tokenStr
        options.url.value = buildThingsVisFrameUrl({
          token: tokenStr,
          mode: options.getMode(),
          studioBaseUrl: getThingsVisStudioBaseUrl(),
          provider: THINGSVIS_COMPAT_PROVIDER,
          saveTarget: THINGSVIS_SAVE_TARGET,
          thingsVisApiBaseUrl: getThingsVisApiBase(),
          platformApiBaseUrl: getPlatformApiBase()
        })
        options.onRecovered?.()
      } else {
        options.logger.warn('[AppFrame] Token acquisition returned null')
        options.onDiagnostic?.(
          buildThingsVisHostDiagnostic('auth', 'thingsvis_token', 'ThingsVis token acquisition returned empty.')
        )
      }
    } catch (error) {
      options.logger.error('[AppFrame] Failed to initialize ThingsVis authentication', error)
      options.onDiagnostic?.(buildThingsVisHostDiagnostic('auth', 'thingsvis_token', error))
    }
  })

  watch(
    () => options.getId(),
    (nextId) => {
      cancelEditorPrefetch()
      options.resetViewerHydrationState()
      if (!nextId || !options.token.value) return
      scheduleInit()
    }
  )

  onBeforeUnmount(() => {
    unbindWindowGuestMessage?.()
    unbindWindowGuestMessage = null
    cancelEditorPrefetch()
    initScheduler.dispose()
    options.disposeViewerHydration()
    options.clearPlatformRuntimeDevices()
    options.resetCatalog()
    options.clearPlatformDataSourceBindings()
    options.disconnectAllDeviceWs()
  })

  return {
    handleIframeLoad,
    handleLoadedFrameMessage,
    handleReadyFrameMessage,
    handleRequestInitFrameMessage
  }
}

import { createThingsVisDeviceWsBridge, type PlatformDeviceField } from './thingsvisDeviceWsBridge'
import { createThingsVisPlatformRuntimeBridge } from './thingsvisPlatformRuntimeBridge'

type CurrentDashboardConfig = Parameters<typeof createThingsVisPlatformRuntimeBridge>[0]['getCurrentDashboardConfig']

function resolvePlatformBufferSize(dataSources: unknown): number {
  if (!Array.isArray(dataSources)) return 0
  return Math.max(
    0,
    ...dataSources.map((dataSource: any) => {
      const normalizedType = typeof dataSource?.type === 'string' ? dataSource.type.toUpperCase() : ''
      if (normalizedType !== 'PLATFORM_FIELD' && normalizedType !== 'PLATFORM') return 0
      const bufferSize = dataSource?.config?.bufferSize
      return typeof bufferSize === 'number' && Number.isFinite(bufferSize) ? Math.max(0, Math.trunc(bufferSize)) : 0
    })
  )
}

export function createThingsVisAppFrameRuntimeDeviceBridge(options: {
  getCurrentDashboardConfig: CurrentDashboardConfig
  postPlatformData: (fields: Record<string, unknown>, deviceId?: string, dataSourceId?: string) => void
}) {
  const deviceWsBridge = createThingsVisDeviceWsBridge({
    postPlatformData: options.postPlatformData
  })
  const platformRuntimeBridge = createThingsVisPlatformRuntimeBridge({
    getCurrentDashboardConfig: options.getCurrentDashboardConfig
  })

  function ensureDeviceWs(deviceId?: string) {
    if (!deviceId) return
    const device = platformRuntimeBridge.getDevice(deviceId)
    if (!device) return
    deviceWsBridge.ensureTelemetry(device)
  }

  function ensureDeviceStatusWs(deviceId?: string) {
    deviceWsBridge.ensureStatus(deviceId)
  }

  function updateDeviceFields(deviceId: string, fields: PlatformDeviceField[]) {
    const normalizedFields = platformRuntimeBridge.updateDeviceFields(deviceId, fields)
    deviceWsBridge.updateDeviceFields(deviceId, normalizedFields)
  }

  return {
    registerDevices: platformRuntimeBridge.registerDevices,
    ensureDevice: platformRuntimeBridge.ensureDevice,
    ensureDeviceWs,
    ensureDeviceStatusWs,
    updateDeviceFields,
    resolveBindingFromPayload: platformRuntimeBridge.resolveBindingFromPayload,
    getDeviceFields: platformRuntimeBridge.getDeviceFields,
    collectConfiguredDescriptors: platformRuntimeBridge.collectConfiguredDescriptors,
    resolveRuntimeDeviceId: platformRuntimeBridge.resolveRuntimeDeviceId,
    clearDevices: platformRuntimeBridge.clearDevices,
    clearDataSourceBindings: platformRuntimeBridge.clearDataSourceBindings,
    resolvePlatformBufferSize,
    disconnectAllDeviceWs: deviceWsBridge.disconnectAll
  }
}

