import type { PlatformDeviceGroupEntry } from './thingsvisDeviceCatalogBridge'

type DeviceGroupLike = Pick<PlatformDeviceGroupEntry, 'groupId' | 'groupName' | 'parentId'>
type DeviceLike = {
  deviceId: string
}

type MapDevicesForGroup<TDevice, TGroup extends DeviceGroupLike> = (
  rawDevices: any[],
  fallbackGroupId?: string,
  fallbackGroupName?: string,
  groups?: TGroup[]
) => Promise<TDevice[]>

function normalizeNonEmptyString(value: unknown): string | undefined {
  if (value === undefined || value === null) return undefined
  const normalized = String(value).trim()
  return normalized || undefined
}

export async function findPlatformDeviceById<TDevice extends DeviceLike, TGroup extends DeviceGroupLike>(options: {
  deviceId: string
  loadGroups: () => Promise<TGroup[]>
  searchDevices: (deviceId: string) => Promise<any[]>
  listDevices: () => Promise<any[]>
  mapDevicesForGroup: MapDevicesForGroup<TDevice, TGroup>
  loadDevicesByGroup: (groupId: string) => Promise<TDevice[]>
}): Promise<TDevice | null> {
  const normalizedDeviceId = normalizeNonEmptyString(options.deviceId)
  if (!normalizedDeviceId) return null

  const groups = await options.loadGroups()

  const findMappedDevice = async (rawDevices: any[], fallbackGroupId = '', fallbackGroupName = '') => {
    const devices = await options.mapDevicesForGroup(rawDevices, fallbackGroupId, fallbackGroupName, groups)
    return devices.find((device) => device.deviceId === normalizedDeviceId) || null
  }

  const searched = await findMappedDevice(await options.searchDevices(normalizedDeviceId))
  if (searched) return searched

  const listed = await findMappedDevice(await options.listDevices())
  if (listed) return listed

  for (const group of groups) {
    const devices = await options.loadDevicesByGroup(group.groupId)
    const matched = devices.find((device) => device.deviceId === normalizedDeviceId)
    if (matched) return matched
  }

  return null
}

export async function loadPlatformDevicesByGroup<TDevice, TGroup extends DeviceGroupLike>(options: {
  groupId: string
  loadGroups: () => Promise<TGroup[]>
  loadRelatedDevices: (groupId: string) => Promise<any[]>
  mapDevicesForGroup: MapDevicesForGroup<TDevice, TGroup>
  buildFallbackDevices: (groupId: string, groupName: string, groups: TGroup[]) => Promise<TDevice[]>
  normalizeGroupId: (groupId: string) => string
  normalizeGroupName: (groupName?: string, fallbackId?: string) => string
  onError?: (groupId: string, error: unknown) => void
}): Promise<TDevice[]> {
  const normalizedGroupId = options.normalizeGroupId(options.groupId)

  try {
    const [rawDevices, groups] = await Promise.all([
      options.loadRelatedDevices(normalizedGroupId),
      options.loadGroups()
    ])

    const groupName =
      groups.find((group) => group.groupId === normalizedGroupId)?.groupName ||
      options.normalizeGroupName(undefined, normalizedGroupId)

    if (rawDevices.length > 0) {
      return options.mapDevicesForGroup(rawDevices, normalizedGroupId, groupName, groups)
    }

    return options.buildFallbackDevices(normalizedGroupId, groupName, groups)
  } catch (error) {
    options.onError?.(normalizedGroupId, error)
    return []
  }
}

﻿export type NormalizedPlatformDeviceRow = {
  deviceId: string
  deviceName: string
  groupId: string
  groupName: string
  deviceConfigId?: string
  deviceConfigName?: string
  isOnline?: number | string | boolean
  warnStatus?: string
  deviceType?: string
  accessWay?: string
  protocolType?: string
  lastPushTime?: string
  templateId?: string
}

export type PlatformDeviceRowContext = {
  fallbackGroupId: string
  fallbackGroupName: string
  groupNameById: Map<string, string>
  configTemplateMap: Map<string, string>
}

/** 设备嵌套对象（后端返回，字段宽松） */
type DeviceRecordLike = {
  id?: unknown
  name?: unknown
  group?: { id?: unknown; name?: unknown } | null
  device_config?: { id?: unknown; name?: unknown; device_template_id?: unknown; deviceTemplateId?: unknown } | null
  [key: string]: unknown
}

/** 平台设备行（后端返回，字段宽松，snake_case/camelCase 双写法兼容） */
type DeviceRowLike = {
  device?: unknown
  device_info?: unknown
  deviceInfo?: unknown
  device_data?: unknown
  deviceData?: unknown
  device_config?: DeviceRecordLike['device_config']
  group?: DeviceRecordLike['group']
  [key: string]: unknown
}

function firstString(...values: unknown[]): string | undefined {
  for (const value of values) {
    if (value === undefined || value === null) continue
    const normalized = String(value).trim()
    if (normalized) return normalized
  }
  return undefined
}

function firstNumber(...values: unknown[]): number | undefined {
  for (const value of values) {
    if (typeof value === 'number' && Number.isFinite(value)) return value
    if (typeof value === 'string' && value.trim()) {
      const parsed = Number(value)
      if (Number.isFinite(parsed)) return parsed
    }
  }
  return undefined
}

function asRecord(value: unknown): DeviceRecordLike {
  return value && typeof value === 'object' && !Array.isArray(value) ? (value as DeviceRecordLike) : {}
}

function unwrapDeviceRow(row: DeviceRowLike | null | undefined): DeviceRecordLike {
  return asRecord(row?.device || row?.device_info || row?.deviceInfo || row?.device_data || row?.deviceData || row)
}

function resolveDeviceId(row: DeviceRowLike | null | undefined): string | undefined {
  const nestedDevice = row?.device || row?.device_info || row?.deviceInfo || row?.device_data || row?.deviceData
  if (nestedDevice && typeof nestedDevice === 'object') {
    const device = asRecord(nestedDevice)
    return firstString(device.id, device.device_id, device.deviceId)
  }

  return firstString(row?.device_id, row?.deviceId, row?.id)
}

function resolveDeviceName(row: DeviceRowLike | null | undefined, deviceId: string): string {
  const device = unwrapDeviceRow(row)
  return firstString(
    device.device_name,
    device.deviceName,
    row?.device_name,
    row?.deviceName,
    device.name,
    row?.name,
    device.device_number,
    device.deviceNumber,
    row?.device_number,
    row?.deviceNumber,
    deviceId
  ) as string
}

function resolveDeviceConfigId(row: DeviceRowLike | null | undefined): string | undefined {
  const device = unwrapDeviceRow(row)
  return firstString(
    device.device_config_id,
    device.deviceConfigId,
    row?.device_config_id,
    row?.deviceConfigId,
    device.device_config?.id,
    row?.device_config?.id
  )
}

function resolveDeviceConfigDisplayName(row: DeviceRowLike | null | undefined): string | undefined {
  const device = unwrapDeviceRow(row)
  return firstString(
    device.device_config_name,
    device.deviceConfigName,
    row?.device_config_name,
    row?.deviceConfigName,
    device.device_config?.name,
    row?.device_config?.name
  )
}

function resolveDeviceOnlineStatus(row: DeviceRowLike | null | undefined): number | string | boolean | undefined {
  const device = unwrapDeviceRow(row)
  return (
    firstNumber(device.is_online, device.isOnline, row?.is_online, row?.isOnline) ??
    (typeof device.is_online === 'boolean' ? device.is_online : undefined) ??
    (typeof row?.is_online === 'boolean' ? row.is_online : undefined)
  )
}

function resolveDeviceWarnStatus(row: DeviceRowLike | null | undefined): string | undefined {
  const device = unwrapDeviceRow(row)
  return firstString(device.warn_status, device.warnStatus, row?.warn_status, row?.warnStatus)
}

function resolveDeviceType(row: DeviceRowLike | null | undefined): string | undefined {
  const device = unwrapDeviceRow(row)
  return firstString(device.device_type, device.deviceType, row?.device_type, row?.deviceType)
}

function resolveDeviceAccessWay(row: DeviceRowLike | null | undefined): string | undefined {
  const device = unwrapDeviceRow(row)
  return firstString(device.access_way, device.accessWay, row?.access_way, row?.accessWay)
}

function resolveDeviceProtocolType(row: DeviceRowLike | null | undefined): string | undefined {
  const device = unwrapDeviceRow(row)
  return firstString(device.protocol_type, device.protocolType, row?.protocol_type, row?.protocolType)
}

function resolveDeviceLastPushTime(row: DeviceRowLike | null | undefined): string | undefined {
  const device = unwrapDeviceRow(row)
  return firstString(
    device.ts,
    row?.ts,
    device.last_push_time,
    device.lastPushTime,
    row?.last_push_time,
    row?.lastPushTime
  )
}

function resolveDeviceTemplateId(row: DeviceRowLike | null | undefined, configTemplateMap: Map<string, string> = new Map()): string | undefined {
  const device = unwrapDeviceRow(row)
  const configId = resolveDeviceConfigId(row)
  const configName = resolveDeviceConfigDisplayName(row)
  return firstString(
    device.device_config?.device_template_id,
    device.device_config?.deviceTemplateId,
    row?.device_config?.device_template_id,
    row?.device_config?.deviceTemplateId,
    device.device_template_id,
    device.deviceTemplateId,
    row?.device_template_id,
    row?.deviceTemplateId,
    configId ? configTemplateMap.get(configId) : undefined,
    configName ? configTemplateMap.get(configName) : undefined
  )
}

function resolveDeviceGroupId(row: DeviceRowLike | null | undefined): string | undefined {
  const device = unwrapDeviceRow(row)
  return firstString(
    device.group_id,
    device.groupId,
    row?.group_id,
    row?.groupId,
    device.device_group_id,
    device.deviceGroupId,
    row?.device_group_id,
    row?.deviceGroupId,
    device.group?.id,
    row?.group?.id
  )
}

function resolveDeviceGroupName(row: DeviceRowLike | null | undefined): string | undefined {
  const device = unwrapDeviceRow(row)
  return firstString(
    device.group_name,
    device.groupName,
    row?.group_name,
    row?.groupName,
    device.device_group_name,
    device.deviceGroupName,
    row?.device_group_name,
    row?.deviceGroupName,
    device.group?.name,
    row?.group?.name
  )
}

function resolvePlatformDeviceGroupName(
  row: DeviceRowLike | null | undefined,
  groupId: string,
  fallbackGroupName: string,
  groupNameById: Map<string, string>
) {
  return resolveDeviceGroupName(row) || (groupId ? groupNameById.get(groupId) : undefined) || fallbackGroupName
}

export function normalizePlatformDeviceRow(
  row: DeviceRowLike | null | undefined,
  { fallbackGroupId, fallbackGroupName, groupNameById, configTemplateMap }: PlatformDeviceRowContext
): NormalizedPlatformDeviceRow | null {
  const deviceId = resolveDeviceId(row)
  if (!deviceId) return null

  const deviceConfigId = resolveDeviceConfigId(row)
  const deviceConfigName = resolveDeviceConfigDisplayName(row)
  const rowGroupId = resolveDeviceGroupId(row) || fallbackGroupId
  const isOnline = resolveDeviceOnlineStatus(row)
  const warnStatus = resolveDeviceWarnStatus(row)
  const deviceType = resolveDeviceType(row)
  const accessWay = resolveDeviceAccessWay(row)
  const protocolType = resolveDeviceProtocolType(row)
  const lastPushTime = resolveDeviceLastPushTime(row)
  const templateId = resolveDeviceTemplateId(row, configTemplateMap)

  return {
    deviceId,
    deviceName: resolveDeviceName(row, deviceId),
    groupId: rowGroupId,
    groupName: resolvePlatformDeviceGroupName(row, rowGroupId, fallbackGroupName, groupNameById),
    ...(deviceConfigId ? { deviceConfigId } : {}),
    ...(deviceConfigName ? { deviceConfigName } : {}),
    ...(isOnline !== undefined ? { isOnline } : {}),
    ...(warnStatus ? { warnStatus } : {}),
    ...(deviceType ? { deviceType } : {}),
    ...(accessWay ? { accessWay } : {}),
    ...(protocolType ? { protocolType } : {}),
    ...(lastPushTime ? { lastPushTime } : {}),
    ...(templateId ? { templateId } : {})
  }
}

﻿import { extractPlatformFields } from '@/utils/thingsvis/platform-fields'
import type { PlatformField } from '@/utils/thingsvis/types'

export type TemplateEntry = {
  fields: PlatformField[]
  loadError?: unknown
}

type FetchTemplateEntryOptions = {
  templateId: string | number
  pageSize: number
  loadTelemetry: (params: Record<string, unknown>) => Promise<{ data?: unknown } | null | undefined>
  loadAttributes: (params: Record<string, unknown>) => Promise<{ data?: unknown } | null | undefined>
  loadCommands: (params: Record<string, unknown>) => Promise<{ data?: unknown } | null | undefined>
  loadEvents: (params: Record<string, unknown>) => Promise<{ data?: unknown } | null | undefined>
  unwrapList: (payload: unknown) => unknown[]
}

/** 模板详情响应的局部视图（仅读取 data.web_chart_config） */
type TemplateResponseLike = { data?: { web_chart_config?: unknown } | null } | null | undefined

type FetchTemplatePresetsOptions = {
  templateId: string | number
  loadTemplate: (templateId: string | number) => Promise<TemplateResponseLike>
  onError?: (templateId: string | number, error: unknown) => void
}

/** 设备模板挂件预设 */
export type DeviceWidgetPreset = {
  id: string
  name: string
  widget: Record<string, unknown>
  thumbnail?: string
}

type DeviceWithTemplateAssets<TField = PlatformField> = {
  templateId?: string
  fields: TField[]
  presets: DeviceWidgetPreset[]
}

const TEMPLATE_ASSET_LOAD_CONCURRENCY = 3

async function mapWithConcurrency<T>(
  items: T[],
  concurrency: number,
  mapper: (item: T) => Promise<void>
) {
  let nextIndex = 0
  const workerCount = Math.min(Math.max(concurrency, 1), items.length)

  await Promise.all(
    Array.from({ length: workerCount }, async () => {
      while (nextIndex < items.length) {
        const currentIndex = nextIndex
        nextIndex += 1
        await mapper(items[currentIndex])
      }
    })
  )
}

function parseTemplateChartConfig(rawConfig: unknown): Record<string, unknown> | null {
  if (typeof rawConfig === 'string') {
    if (!rawConfig.trim()) return null
    try {
      const parsed = JSON.parse(rawConfig)
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? (parsed as Record<string, unknown>) : null
    } catch {
      return null
    }
  }

  if (rawConfig && typeof rawConfig === 'object' && !Array.isArray(rawConfig)) {
    return rawConfig as Record<string, unknown>
  }

  return null
}

function resolveNodePresetName(node: Record<string, unknown>, index: number) {
  const props =
    node.props && typeof node.props === 'object' && !Array.isArray(node.props)
      ? (node.props as Record<string, unknown>)
      : {}

  return String(
    node.name || props.title || props.label || props.text || props.placeholder || node.type || `挂件 ${index + 1}`
  )
}

export function buildDeviceWidgetPresets(templateId: string, rawConfig: unknown): DeviceWidgetPreset[] {
  const config = parseTemplateChartConfig(rawConfig)
  const nodes = Array.isArray(config?.nodes)
    ? config.nodes.filter(
        (node): node is Record<string, unknown> => Boolean(node) && typeof node === 'object' && !Array.isArray(node)
      )
    : config?.nodesById && typeof config.nodesById === 'object' && !Array.isArray(config.nodesById)
      ? Object.values(config.nodesById).filter(
          (node): node is Record<string, unknown> => Boolean(node) && typeof node === 'object' && !Array.isArray(node)
        )
      : []

  const nodePresets = nodes.map((node, index) => ({
    id: `${templateId}-web-node-${String(node.id || index)}`,
    name: resolveNodePresetName(node, index),
    widget: node,
    ...(typeof node.thumbnail === 'string' ? { thumbnail: node.thumbnail } : {})
  }))

  const presetMap = config?.device_widget_presets
  if (!presetMap || typeof presetMap !== 'object' || Array.isArray(presetMap)) return nodePresets

  const storedPresets = Object.entries(presetMap).flatMap(([presetKey, entries]) => {
    if (!Array.isArray(entries)) return []

    return entries.flatMap((entry, index) => {
      if (!entry?.widget || typeof entry.widget !== 'object' || Array.isArray(entry.widget)) return []

      return [
        {
          id: `${templateId}-stored-${String(entry.id || `${presetKey}-${index}`)}`,
          name: String(entry.name || '挂件预设'),
          widget: entry.widget,
          ...(typeof entry.thumbnail === 'string' ? { thumbnail: entry.thumbnail } : {})
        }
      ]
    })
  })

  return [...nodePresets, ...storedPresets]
}

export async function fetchTemplatePresets(options: FetchTemplatePresetsOptions): Promise<DeviceWidgetPreset[]> {
  try {
    const response = await options.loadTemplate(options.templateId)
    const template = response?.data || {}
    return buildDeviceWidgetPresets(String(options.templateId), template?.web_chart_config)
  } catch (error) {
    options.onError?.(options.templateId, error)
    return []
  }
}

export async function fetchTemplateEntry(options: FetchTemplateEntryOptions): Promise<TemplateEntry> {
  const [telemetryResult, attributesResult, commandsResult, eventsResult] = await Promise.allSettled([
    options.loadTelemetry({ page: 1, page_size: options.pageSize, device_template_id: options.templateId }),
    options.loadAttributes({ page: 1, page_size: options.pageSize, device_template_id: options.templateId }),
    options.loadCommands({ page: 1, page_size: options.pageSize, device_template_id: options.templateId }),
    options.loadEvents({ page: 1, page_size: options.pageSize, device_template_id: options.templateId })
  ])

  const telemetryRes = telemetryResult.status === 'fulfilled' ? telemetryResult.value : null
  const attributesRes = attributesResult.status === 'fulfilled' ? attributesResult.value : null
  const commandsRes = commandsResult.status === 'fulfilled' ? commandsResult.value : null
  const eventsRes = eventsResult.status === 'fulfilled' ? eventsResult.value : null
  const firstLoadError =
    telemetryResult.status === 'rejected'
      ? telemetryResult.reason
      : attributesResult.status === 'rejected'
        ? attributesResult.reason
        : commandsResult.status === 'rejected'
          ? commandsResult.reason
          : eventsResult.status === 'rejected'
            ? eventsResult.reason
            : undefined

  return {
    fields: extractPlatformFields({
      telemetry: options.unwrapList(telemetryRes?.data),
      attributes: options.unwrapList(attributesRes?.data),
      commands: options.unwrapList(commandsRes?.data),
      events: options.unwrapList(eventsRes?.data)
    }),
    ...(firstLoadError ? { loadError: firstLoadError } : {})
  }
}

export async function loadPlatformDeviceTemplateAssets<TField = PlatformField>(options: {
  devices: Array<{ templateId?: string }>
  loadTemplatePresets: (templateId: string) => Promise<DeviceWidgetPreset[]>
  loadTemplateEntry: (templateId: string) => Promise<{ fields: TField[] }>
}): Promise<{ fieldsByTemplateId: Map<string, TField[]>; presetsByTemplateId: Map<string, DeviceWidgetPreset[]> }> {
  const templateIds = Array.from(
    new Set(
      options.devices
        .map((device) => device.templateId)
        .filter((templateId): templateId is string => Boolean(templateId))
    )
  )
  const presetsByTemplateId = new Map<string, DeviceWidgetPreset[]>()
  const fieldsByTemplateId = new Map<string, TField[]>()

  await mapWithConcurrency(templateIds, TEMPLATE_ASSET_LOAD_CONCURRENCY, async (templateId) => {
    const [presets, entry] = await Promise.all([
      options.loadTemplatePresets(templateId),
      options.loadTemplateEntry(templateId)
    ])
    presetsByTemplateId.set(templateId, Array.isArray(presets) ? presets : [])
    fieldsByTemplateId.set(templateId, Array.isArray(entry.fields) ? entry.fields : [])
  })

  return { fieldsByTemplateId, presetsByTemplateId }
}

export function attachPlatformDeviceTemplateAssets<
  TDevice extends DeviceWithTemplateAssets<TField>,
  TField = PlatformField
>(
  device: TDevice,
  assets: { fieldsByTemplateId: Map<string, TField[]>; presetsByTemplateId: Map<string, DeviceWidgetPreset[]> }
): TDevice {
  return {
    ...device,
    fields: device.templateId ? assets.fieldsByTemplateId.get(device.templateId) || device.fields : device.fields,
    presets: device.templateId ? assets.presetsByTemplateId.get(device.templateId) || [] : []
  }
}

/**
 * 文件说明：
 * - 编排 ThingsVis editor 模式在 `tv:init` 之后的设备与字段预取。
 * - 负责从 dashboard 配置中收集平台数据源、预加载设备详情、注册运行时设备，并按设备分组补齐字段数据。
 * 维护提示：
 * - editor 预取保持 fire-and-forget 行为，不在初始化链路中等待完成，避免拖慢 iframe ready 后的可编辑状态。
 * - 本模块不启动 WebSocket，也不管理 viewer 补水 timer；viewer 模式的实时补水仍由 `thingsvisViewerHydrationBridge.ts` 负责。
 * 审查建议：
 * - 后续补测试时重点覆盖设备成功预取后先注册再回推、单设备多数据源字段合并读取、异常静默降级三条行为。
 */
import {
  collectPlatformSourceDeviceIds,
  groupPlatformSourceDescriptorsByDevice,
  hydratePlatformSourceDescriptorGroup,
  type PlatformSourceDescriptor
} from '@/components/thingsvis/thingsvisFieldHydrationBridge'
import type { PlatformDeviceEntry } from '@/components/thingsvis/thingsvisPlatformDeviceCatalogOrchestrator'

type EditorPrefetchOrchestratorOptions = {
  collectConfiguredDescriptors: (dashboardPayload: Record<string, unknown>) => PlatformSourceDescriptor[]
  loadDeviceById: (deviceId: string) => Promise<PlatformDeviceEntry | null>
  registerDevices: (devices: PlatformDeviceEntry[]) => void
  loadRequestedFieldData: (fieldIds: unknown[], deviceId?: string) => Promise<Record<string, unknown>>
  postDeviceById: (payload: { reqId: string; deviceId: string; device: PlatformDeviceEntry }) => void
  postPlatformData: (fields: Record<string, unknown>, deviceId?: string, dataSourceId?: string) => void
  idleTimeout?: number
  fallbackDelay?: number
}

export type ThingsVisEditorPrefetchOrchestrator = {
  prefetch: (dashboardPayload: Record<string, unknown>) => Promise<void>
  dispose: () => void
}

export function createThingsVisEditorPrefetchOrchestrator(
  options: EditorPrefetchOrchestratorOptions
): ThingsVisEditorPrefetchOrchestrator {
  const idleTimeout = options.idleTimeout ?? 1200
  const fallbackDelay = options.fallbackDelay ?? 120

  let prefetchGeneration = 0
  let pendingIdleHandle: number | null = null
  let pendingFallbackTimer: ReturnType<typeof setTimeout> | null = null

  function isCurrentPrefetch(generation: number) {
    return generation === prefetchGeneration
  }

  function clearScheduledPrefetch() {
    if (pendingIdleHandle !== null && typeof window !== 'undefined' && typeof window.cancelIdleCallback === 'function') {
      window.cancelIdleCallback(pendingIdleHandle)
      pendingIdleHandle = null
    }
    if (pendingFallbackTimer) {
      clearTimeout(pendingFallbackTimer)
      pendingFallbackTimer = null
    }
  }

  function schedulePrefetch(callback: () => void) {
    clearScheduledPrefetch()

    if (typeof window !== 'undefined' && typeof window.requestIdleCallback === 'function') {
      pendingIdleHandle = window.requestIdleCallback(
        () => {
          pendingIdleHandle = null
          callback()
        },
        { timeout: idleTimeout }
      )
      return
    }

    pendingFallbackTimer = setTimeout(() => {
      pendingFallbackTimer = null
      callback()
    }, fallbackDelay)
  }

  async function prefetchDevices(deviceIds: string[], generation: number) {
    for (const deviceId of deviceIds) {
      if (!isCurrentPrefetch(generation)) return
      try {
        const device = await options.loadDeviceById(deviceId)
        if (!isCurrentPrefetch(generation)) return
        if (!device) continue

        options.registerDevices([device])
        options.postDeviceById({
          reqId: `__prefetch__${deviceId}`,
          deviceId,
          device
        })
      } catch {
        if (!isCurrentPrefetch(generation)) return
        // editor 预取是体验优化，单个设备失败不能阻断 iframe 初始化。
      }
    }
  }

  async function prefetchDescriptorFields(descriptors: PlatformSourceDescriptor[], generation: number) {
    for (const [deviceId, group] of groupPlatformSourceDescriptorsByDevice(descriptors)) {
      if (!isCurrentPrefetch(generation)) return
      try {
        await hydratePlatformSourceDescriptorGroup({
          deviceId,
          group,
          loadRequestedFieldData: async (fieldIds, targetDeviceId) => {
            if (!isCurrentPrefetch(generation)) return {}
            const fields = await options.loadRequestedFieldData(fieldIds, targetDeviceId)
            return isCurrentPrefetch(generation) ? fields : {}
          },
          postPlatformData: (fields, targetDeviceId, dataSourceId) => {
            if (!isCurrentPrefetch(generation)) return
            options.postPlatformData(fields, targetDeviceId, dataSourceId)
          }
        })
      } catch {
        if (!isCurrentPrefetch(generation)) return
        // 字段补齐失败时保持静默降级，避免 editor 初始化阶段出现噪音。
      }
    }
  }

  async function runPrefetch(dashboardPayload: Record<string, unknown>, generation: number) {
    if (!isCurrentPrefetch(generation)) return

    const descriptors = options.collectConfiguredDescriptors(dashboardPayload)
    await prefetchDevices(collectPlatformSourceDeviceIds(descriptors), generation)
    if (!isCurrentPrefetch(generation)) return

    await prefetchDescriptorFields(descriptors, generation)
  }

  async function prefetch(dashboardPayload: Record<string, unknown>) {
    const generation = prefetchGeneration + 1
    prefetchGeneration = generation

    schedulePrefetch(() => {
      void runPrefetch(dashboardPayload, generation)
    })
  }

  function dispose() {
    prefetchGeneration += 1
    clearScheduledPrefetch()
  }

  return {
    prefetch,
    dispose
  }
}

﻿import { normalizeRequestedFieldIds, splitRequestedFieldIds as splitRequestedFieldIdsByKind } from './fieldReadBridge'
