  name?: unknown
  title?: unknown
  [key: string]: unknown
}

/** 接口响应的局部视图（分页列表 / 设备元信息两种形态的字段并集） */
type ListResponseLike = {
  data?:
    | ({
        list?: unknown[]
        total?: unknown
        data?: unknown[]
        device?: Record<string, unknown> | null
      } & Record<string, unknown>)
    | null
  device?: Record<string, unknown> | null
  pid_number?: unknown
  firmware_version?: unknown
  current_version?: unknown
  description?: unknown
  shared_status?: unknown
  total?: unknown
  [key: string]: unknown
}

function collectFieldRows(kvMap: Record<string, unknown>, rows: unknown) {
  if (!Array.isArray(rows)) return
  rows.forEach(item => {
    if (item?.key !== undefined) kvMap[item.key] = item.value
    if (item?.label) kvMap[item.label] = item.value
  })
}

function collectRdiDeviceMeta(kvMap: Record<string, unknown>, source: ListResponseLike | null) {
  const data = source?.data?.device || source?.data || source?.device || source
  if (!data || typeof data !== 'object') return
  if (data.pid_number !== undefined) kvMap.pid_number = data.pid_number
  if (data.firmware_version !== undefined || data.current_version !== undefined) {
    kvMap.firmware_version = data.firmware_version ?? data.current_version
  }
  if (data.description !== undefined) kvMap.description = data.description
  if (data.shared_status !== undefined) kvMap.shared_status = data.shared_status
}

function normalizeAlarmLevel(raw: unknown) {
  const value = String(raw ?? '')
    .toLowerCase()
    .trim()
  if (value === '1' || value === 'critical' || value === 'high' || value === 'serious') return 'critical'
  if (value === '2' || value === 'warning' || value === 'medium' || value === 'warn') return 'warning'
  if (value === '3' || value === 'info' || value === 'low') return 'info'
  return value || ''
}

function alarmLevelRank(row: AlarmRowLike | null) {
  switch (normalizeAlarmLevel(row?.alarm_level ?? row?.level)) {
    case 'critical':
      return 3
    case 'warning':
      return 2
    case 'info':
      return 1
    default:
      return 0
  }
}

function normalizeAlarmTime(row: AlarmRowLike | null) {
  return row?.last_trigger_time ?? row?.create_time ?? row?.created_at ?? row?.time ?? ''
}

function isActiveAlarm(row: AlarmRowLike): boolean {
  const raw = String(row?.alarm_status ?? row?.status ?? row?.is_active ?? '').toLowerCase()
  return row?.is_active === true || raw === '1' || raw === 'active' || raw === 'triggered' || raw === 'a'
}

function normalizeAlarmStatusResponse(response: ListResponseLike | null): {
  payload: (ListResponseLike & { total?: unknown }) | null
  rows: AlarmRowLike[]
} {
  const payload = ((response?.data ?? response) ?? null) as (ListResponseLike & { total?: unknown }) | null
  const rows = Array.isArray(payload?.list)
    ? (payload.list as AlarmRowLike[])
    : Array.isArray(payload?.data)
      ? (payload.data as AlarmRowLike[])
      : Array.isArray(payload)
        ? (payload as AlarmRowLike[])
        : []
  return { payload, rows }
}

function pickHighestAlarmRow(activeRows: AlarmRowLike[]) {
  return activeRows.reduce<AlarmRowLike | null>(
    (current, row) => (!current || alarmLevelRank(row) > alarmLevelRank(current) ? row : current),
    null
  )
}

function buildAlarmStatusFieldMap(
  payload: (ListResponseLike & { total?: unknown }) | null,
  activeRows: AlarmRowLike[],
  latest: AlarmRowLike | null
): Record<string, unknown> {
  const highest = pickHighestAlarmRow(activeRows) ?? latest
  return {
    device_alarm_active: activeRows.length > 0 ? 1 : 0,
    device_alarm_count: Number(payload?.total ?? activeRows.length ?? 0),
    device_alarm_highest_level: normalizeAlarmLevel(highest?.alarm_level ?? highest?.level),
    latest_device_alarm_title: String(latest?.alarm_name ?? latest?.name ?? latest?.title ?? ''),
    latest_device_alarm_level: normalizeAlarmLevel(latest?.alarm_level ?? latest?.level),
    latest_device_alarm_time: latest ? normalizeAlarmTime(latest) : ''
  }
}

export async function loadCurrentFieldValueMap(options: {
  deviceId: string
  currentFieldIds: string[]
  rdiMetaFieldIds: Set<string>
  silentRequestConfig: unknown
  loadTelemetryCurrent: (deviceId: string, requestConfig: unknown) => Promise<ListResponseLike | null>
  loadAttributeDataSet: (params: { device_id: string }, requestConfig: unknown) => Promise<ListResponseLike | null>
  loadRdiDeviceConfig: (deviceId: string, requestConfig: unknown) => Promise<ListResponseLike | null>
}): Promise<Record<string, unknown>> {
  const shouldLoadRdiDeviceMeta = options.currentFieldIds.some((fieldId) => options.rdiMetaFieldIds.has(fieldId))
  const [telemetryResult, attributeResult, rdiDeviceResult] = await Promise.allSettled([
    options.loadTelemetryCurrent(options.deviceId, options.silentRequestConfig),
    options.loadAttributeDataSet({ device_id: options.deviceId }, options.silentRequestConfig),
    shouldLoadRdiDeviceMeta
      ? options.loadRdiDeviceConfig(options.deviceId, options.silentRequestConfig)
      : Promise.resolve(null)
  ])

  const telemetryRes = telemetryResult.status === 'fulfilled' ? telemetryResult.value : null
  const attributeRes = attributeResult.status === 'fulfilled' ? attributeResult.value : null
  const rdiDeviceRes = rdiDeviceResult.status === 'fulfilled' ? rdiDeviceResult.value : null
  const firstLoadError =
    telemetryResult.status === 'rejected'
      ? telemetryResult.reason
      : attributeResult.status === 'rejected'
        ? attributeResult.reason
        : rdiDeviceResult.status === 'rejected'
          ? rdiDeviceResult.reason
          : undefined

  if (firstLoadError) {
    throw firstLoadError
  }

  const kvMap: Record<string, unknown> = {}
  collectFieldRows(kvMap, telemetryRes?.data)
  collectFieldRows(kvMap, attributeRes?.data)
  collectRdiDeviceMeta(kvMap, rdiDeviceRes)
  return kvMap
}

export async function buildRequestedAlarmStatusData(options: {
  fieldIds: string[]
  deviceId?: string
  loadDeviceAlarmStatus: (params: { device_id: string; page: number; page_size: number }) => Promise<ListResponseLike | null>
  onError?: (deviceId: string, error: unknown) => void
}): Promise<Record<string, unknown>> {
  if (!options.deviceId || options.fieldIds.length === 0) return {}

  try {
    const response = await options.loadDeviceAlarmStatus({ device_id: options.deviceId, page: 1, page_size: 20 })
    const { payload, rows } = normalizeAlarmStatusResponse(response)
    const activeRows = rows.filter(isActiveAlarm)
    const latest = rows[0] ?? null
    const allFields = buildAlarmStatusFieldMap(payload, activeRows, latest)
    return pickRequestedPlatformFields(allFields, options.fieldIds)
  } catch (error) {
    options.onError?.(options.deviceId, error)
    return {}
  }
}

export async function buildRequestedFieldData(options: {
  fieldIds: unknown[]
  deviceId?: string
  alarmStatusFieldIds: Set<string>
  rdiMetaFieldIds: Set<string>
  historyFieldSuffix: string
  silentRequestConfig: unknown
  loadTelemetryCurrent: (deviceId: string, requestConfig: unknown) => Promise<ListResponseLike | null>
  loadAttributeDataSet: (params: { device_id: string }, requestConfig: unknown) => Promise<ListResponseLike | null>
  loadRdiDeviceConfig: (deviceId: string, requestConfig: unknown) => Promise<ListResponseLike | null>
  loadDeviceAlarmStatus: (params: { device_id: string; page: number; page_size: number }) => Promise<ListResponseLike | null>
  onAlarmError?: (deviceId: string, error: unknown) => void
}): Promise<Record<string, unknown>> {
  const requestedFields = normalizeRequestedFieldIds(options.fieldIds)
  if (!options.deviceId || requestedFields.length === 0) return {}

  const { alarmFieldIds, currentFieldIds } = splitRequestedFieldIdsByKind(requestedFields, {
    alarmStatusFieldIds: options.alarmStatusFieldIds,
    historyFieldSuffix: options.historyFieldSuffix
  })
  const alarmDataPromise =
    alarmFieldIds.length > 0
      ? buildRequestedAlarmStatusData({
        fieldIds: alarmFieldIds,
        deviceId: options.deviceId,
        loadDeviceAlarmStatus: options.loadDeviceAlarmStatus,
        onError: options.onAlarmError
      })
      : Promise.resolve({})
  const currentDataPromise =
    currentFieldIds.length > 0
      ? loadCurrentFieldValueMap({
          deviceId: options.deviceId,
          currentFieldIds,
          rdiMetaFieldIds: options.rdiMetaFieldIds,
          silentRequestConfig: options.silentRequestConfig,
          loadTelemetryCurrent: options.loadTelemetryCurrent,
          loadAttributeDataSet: options.loadAttributeDataSet,
          loadRdiDeviceConfig: options.loadRdiDeviceConfig
        }).then(kvMap => pickRequestedPlatformFields(kvMap, currentFieldIds))
      : Promise.resolve({})

  const [alarmData, currentData] = await Promise.all([alarmDataPromise, currentDataPromise])
  return Object.assign({}, alarmData, currentData)
}

/**
 * 文件说明：
 * - 封装 ThingsVis 平台数据源字段补水逻辑，负责解析节点中的字段绑定表达式并构建待补水的数据源描述。
 * - 同时提供按设备分组、按字段裁剪、按数据源回推 `tv:platform-data` 的辅助函数。
 * 维护提示：
 * - `{{ ds.xxx... }}` 表达式解析规则属于 ThingsVis schema 兼容边界，调整前要确认历史大屏配置仍可识别。
 * - 本模块只处理字段收集与补水编排，不直接读写 iframe、WebSocket 或平台接口。
 */
export type PlatformSourceDescriptor = {
  id: string
  deviceId?: string
  requestedFields: string[]
}

export type PlatformSourceDescriptorGroup = {
  descriptors: PlatformSourceDescriptor[]
  requestedFields: Set<string>
}

const FIELD_BINDING_EXPR_RE = /\{\{\s*ds\.([^.\s}]+)\.([^}]+?)\s*\}\}/g

type CollectPlatformSourceDescriptorsOptions = {
  resolveDeviceId: (dataSourceId: string, configuredDeviceId?: string) => string | undefined
}

export function pickRequestedPlatformFields(fields: Record<string, unknown>, requestedFields: string[]) {
  return requestedFields.reduce<Record<string, unknown>>((acc, fieldId) => {
    if (Object.prototype.hasOwnProperty.call(fields, fieldId)) {
      acc[fieldId] = fields[fieldId]
    }
    return acc
  }, {})
}

function collectRequestedFieldsFromValue(value: unknown, requests: Map<string, Set<string>>) {
  if (typeof value === 'string') {
    let match: RegExpExecArray | null = null
    FIELD_BINDING_EXPR_RE.lastIndex = 0
    while ((match = FIELD_BINDING_EXPR_RE.exec(value)) !== null) {
      const dataSourceId = match[1]
      const fieldPath = match[2]?.trim()
      if (!dataSourceId || !fieldPath) continue
      const normalizedPath = fieldPath.replace(/^data(?:\.|\[)/, '')
      const fieldId = normalizedPath.split(/[.[\]\s?:+\-*/=!<>&|(),]/).filter(Boolean)[0]
      if (!fieldId) continue
      const fields = requests.get(dataSourceId) ?? new Set<string>()
      fields.add(fieldId)
      requests.set(dataSourceId, fields)
    }
    return
  }

  if (Array.isArray(value)) {
    value.forEach((item) => collectRequestedFieldsFromValue(item, requests))
    return
  }

  if (!value || typeof value !== 'object') return

  Object.values(value as Record<string, unknown>).forEach((item) => {
    collectRequestedFieldsFromValue(item, requests)
  })
}

function getPlatformDataSources(config: any): any[] {
  return Array.isArray(config?.dataSources) ? config.dataSources : []
}

function isPlatformSourceDataSource(dataSource: any): boolean {
  const typeStr = typeof dataSource?.type === 'string' ? dataSource.type.toUpperCase() : ''
  return typeStr === 'PLATFORM_FIELD' || typeStr === 'PLATFORM'
}

function collectConfiguredRequestedFields(dataSource: any): string[] {
  return Array.isArray(dataSource?.config?.requestedFields)
    ? dataSource.config.requestedFields.filter((fieldId: unknown): fieldId is string => typeof fieldId === 'string')
    : []
}

function buildPlatformSourceRequestedFields(
  dataSourceId: string,
  dataSource: any,
  requests: Map<string, Set<string>>
): string[] {
  const requestedFields = new Set<string>(collectConfiguredRequestedFields(dataSource))
  const bindingFields = requests.get(dataSourceId)
  if (bindingFields) {
    bindingFields.forEach((fieldId) => requestedFields.add(fieldId))
  }
  return Array.from(requestedFields)
}

function buildPlatformSourceDescriptor(
  dataSource: any,
  requests: Map<string, Set<string>>,
  options: CollectPlatformSourceDescriptorsOptions
): PlatformSourceDescriptor {
  const dataSourceId = String(dataSource.id)

  return {
    id: dataSourceId,
    deviceId: options.resolveDeviceId(dataSourceId, dataSource?.config?.deviceId),
    requestedFields: buildPlatformSourceRequestedFields(dataSourceId, dataSource, requests)
  }
}

export function collectPlatformSourceDescriptors(
  config: any,
  options: CollectPlatformSourceDescriptorsOptions
): PlatformSourceDescriptor[] {
  const requests = new Map<string, Set<string>>()
  collectRequestedFieldsFromValue(config?.nodes, requests)

  return getPlatformDataSources(config)
    .filter((dataSource: any) => isPlatformSourceDataSource(dataSource))
    .map((dataSource: any) => buildPlatformSourceDescriptor(dataSource, requests, options))
}

export function groupPlatformSourceDescriptorsByDevice(
  descriptors: PlatformSourceDescriptor[]
): Map<string, PlatformSourceDescriptorGroup> {
  const descriptorsByDevice = new Map<string, PlatformSourceDescriptorGroup>()

  for (const descriptor of descriptors) {
    if (!descriptor.deviceId) continue

    const existing = descriptorsByDevice.get(descriptor.deviceId) ?? {
      descriptors: [],
      requestedFields: new Set<string>()
    }
    existing.descriptors.push(descriptor)
    descriptor.requestedFields.forEach((fieldId) => existing.requestedFields.add(fieldId))
    descriptorsByDevice.set(descriptor.deviceId, existing)
  }

  return descriptorsByDevice
}

export function collectPlatformSourceDeviceIds(descriptors: PlatformSourceDescriptor[]): string[] {
  return [
    ...new Set(
      descriptors.map((descriptor) => descriptor.deviceId).filter((deviceId): deviceId is string => !!deviceId)
    )
  ]
}

export async function hydratePlatformSourceDescriptorGroup(options: {
  deviceId: string
  group: PlatformSourceDescriptorGroup
  ensureDeviceWs?: (deviceId: string) => void
  ensureDeviceStatusWs?: (deviceId: string) => void
  loadRequestedFieldData: (fieldIds: string[], deviceId: string) => Promise<Record<string, unknown>>
  postPlatformData: (fields: Record<string, unknown>, deviceId?: string, dataSourceId?: string) => void
}): Promise<void> {
  const requestedFields = Array.from(options.group.requestedFields)
  if (requestedFields.length === 0) return

  options.ensureDeviceWs?.(options.deviceId)
  options.ensureDeviceStatusWs?.(options.deviceId)

  const fields = await options.loadRequestedFieldData(requestedFields, options.deviceId)

  options.group.descriptors.forEach((descriptor) => {
    options.postPlatformData(
      pickRequestedPlatformFields(fields, descriptor.requestedFields),
      options.deviceId,
      descriptor.id || undefined
    )
  })
}

/**
 * 文件说明：
 * - 编排 ThingsVis guest 发起的字段读取请求，并复用平台字段补水逻辑回推 `tv:platform-data`。
 * - 将字段请求解析、设备绑定解析、当前值/告警/RDI 元数据读取和瞬时错误静默策略从 AppFrame 中拆出。
 * 维护提示：
 * - `resolvePlatformFieldReadRequest` 的 `null` / `undefined` 语义不能改：`null` 表示拒绝请求，`undefined` 表示走默认设备。
 * - 本模块不直接持有 iframe/window/origin，真实 postMessage 由 AppFrame 注入，避免放宽跨域通信边界。
 */
import { resolvePlatformFieldReadRequest } from '@/components/thingsvis/fieldReadRequestBridge'
import { buildRequestedFieldData } from '@/components/thingsvis/thingsvisFieldDataBridge'
import { hydratePlatformSourceDescriptorGroup } from '@/components/thingsvis/thingsvisFieldHydrationBridge'
import { buildThingsVisHostErrorPayload } from '@/components/thingsvis/thingsvisHostErrorPayload'

const DEVICE_ALARM_STATUS_FIELD_IDS = new Set([
  'device_alarm_active',
  'device_alarm_count',
  'device_alarm_highest_level',
  'latest_device_alarm_title',
  'latest_device_alarm_level',
  'latest_device_alarm_time'
])
const RDI_DEVICE_META_FIELD_IDS = new Set(['pid_number', 'firmware_version', 'description', 'shared_status'])
const SILENT_REQUEST_CONFIG = { silentError: true } as const

export type FieldRequestBinding = {
  deviceId?: string | null
  dataSourceId?: string
}

export type FieldRequestHydrationDependencies = {
  loadTelemetryCurrent: (deviceId: string, requestConfig: unknown) => Promise<any>
  loadAttributeDataSet: (params: { device_id: string }, requestConfig: unknown) => Promise<any>
  loadRdiDeviceConfig: (deviceId: string, requestConfig: unknown) => Promise<any>
  loadDeviceAlarmStatus: (params: { device_id: string; page: number; page_size: number }) => Promise<any>
}

export type ThingsVisFieldRequestHydrationBridgeOptions = {
  isFrameReady: () => boolean
  resolveBindingFromPayload: (payload: Record<string, unknown> | undefined) => FieldRequestBinding
  ensureDevice: (deviceId?: string) => void
  ensureDeviceWs: (deviceId?: string) => void
  ensureDeviceStatusWs: (deviceId?: string) => void
  postPlatformData: (fields: Record<string, unknown>, deviceId?: string, dataSourceId?: string) => void
  postToThingsVis?: (type: string, payload: Record<string, unknown>) => void
  dependencies: FieldRequestHydrationDependencies
  onAlarmError?: (deviceId: string, error: unknown) => void
}

export function createThingsVisFieldRequestHydrationBridge(options: ThingsVisFieldRequestHydrationBridgeOptions) {
  async function loadRequestedFieldData(
    fieldIds: unknown[],
    deviceId?: string
  ): Promise<Record<string, unknown>> {
    return buildRequestedFieldData({
      fieldIds,
      deviceId,
      alarmStatusFieldIds: DEVICE_ALARM_STATUS_FIELD_IDS,
      rdiMetaFieldIds: RDI_DEVICE_META_FIELD_IDS,
      historyFieldSuffix: '__history',
      silentRequestConfig: SILENT_REQUEST_CONFIG,
      loadTelemetryCurrent: options.dependencies.loadTelemetryCurrent,
      loadAttributeDataSet: options.dependencies.loadAttributeDataSet,
      loadRdiDeviceConfig: options.dependencies.loadRdiDeviceConfig,
      loadDeviceAlarmStatus: options.dependencies.loadDeviceAlarmStatus,
      onAlarmError: options.onAlarmError
    })
  }

  async function handleFieldDataRequest(payload: Record<string, unknown>) {
    if (!options.isFrameReady()) return

    const binding = options.resolveBindingFromPayload(payload)
    const { dataSourceId } = binding
    let deviceId = binding.deviceId || undefined

    try {
      const request = resolvePlatformFieldReadRequest({
        payload,
        resolveTargetDeviceId: (nextPayload) => options.resolveBindingFromPayload(nextPayload).deviceId
      })
      if (!request) return

      const { fieldIds, targetDeviceId } = request
      deviceId = targetDeviceId

      options.ensureDevice(deviceId)
      await hydratePlatformSourceDescriptorGroup({
        deviceId: deviceId || '',
        group: {
          descriptors: [{ id: dataSourceId || '', deviceId, requestedFields: fieldIds }],
          requestedFields: new Set(fieldIds)
        },
        ensureDeviceWs: options.ensureDeviceWs,
        ensureDeviceStatusWs: options.ensureDeviceStatusWs,
        loadRequestedFieldData: (requestedFieldIds, targetDeviceId) =>
          loadRequestedFieldData(requestedFieldIds, targetDeviceId),
        postPlatformData: options.postPlatformData
      })
    } catch (error) {
      options.postToThingsVis?.('tv:platform-data', {
        dataSourceId,
        deviceId,
        fields: {},
        ...buildThingsVisHostErrorPayload('field_data', error)
      })
    }
  }

  return {
    loadRequestedFieldData,
    handleFieldDataRequest
  }
}

/**
 * 文件说明：
 * - 承接 ThingsVis iframe 宿主侧的 transport 壳，集中 targetOrigin 解析、可信消息判定和 postMessage 出口。
 * - 让 AppFrame 继续聚焦 bridge 装配，避免把 iframe 安全边界与平台数据回推细节重新堆回父组件。
 * 维护提示：
 * - `targetOrigin` 必须来自 ThingsVis Studio URL，不能放宽成 `*`。
 * - `tv:platform-data` 需要保留“带 deviceId 的定向回推 + 通用 fields 广播”双路兼容语义。
 */
import type { Ref } from 'vue'
import { parseTrustedGuestMessage } from '@/components/thingsvis/hostBridge'
import {
  isTrustedThingsVisFrameEvent,
  postToThingsVisFrame,
  resolveThingsVisTargetOrigin
} from '@/components/thingsvis/thingsvisFrameBridge'
import type { TrustedThingsVisFrameMessage } from '@/components/thingsvis/thingsvisFrameMessageDispatcher'
import { getThingsVisStudioBaseUrl } from '@/utils/thingsvis/constants'

type ThingsVisFrameTransportOptions = {
  iframeRef: Ref<HTMLIFrameElement | undefined>
  url: Ref<string>
}

export type ThingsVisFrameTransportBridge = {
  getTargetOrigin: () => string
  getTrustedThingsVisFrameMessage: (event: MessageEvent) => TrustedThingsVisFrameMessage | null
  postToThingsVis: (type: string, payload: Record<string, unknown>) => void
  postPlatformData: (fields: Record<string, unknown>, deviceId?: string, dataSourceId?: string) => void
}

export function createThingsVisFrameTransportBridge(
  options: ThingsVisFrameTransportOptions
): ThingsVisFrameTransportBridge {
  function getThingsVisTargetOrigin(): string {
    return resolveThingsVisTargetOrigin(
      options.url.value || getThingsVisStudioBaseUrl(),
      window.location.href,
      window.location.origin
    )
  }

  function isTrustedThingsVisMessageEvent(event: MessageEvent): boolean {
    return isTrustedThingsVisFrameEvent(
      event,
      options.iframeRef.value?.contentWindow,
      getThingsVisTargetOrigin()
    )
  }

  function getTrustedThingsVisFrameMessage(event: MessageEvent): TrustedThingsVisFrameMessage | null {
    return parseTrustedGuestMessage<Record<string, unknown>>(event, {
      isTrusted: isTrustedThingsVisMessageEvent
    })
  }

  function postToThingsVis(type: string, payload: Record<string, unknown>) {
    postToThingsVisFrame(
      options.iframeRef.value?.contentWindow,
      type,
      payload,
      getThingsVisTargetOrigin()
    )
  }

  function postPlatformData(fields: Record<string, unknown>, deviceId?: string, dataSourceId?: string) {
    if (Object.keys(fields).length === 0) return

    postToThingsVis('tv:platform-data', {
      dataSourceId,
      deviceId,
      fields
    })

    if (deviceId) {
      postToThingsVis('tv:platform-data', { fields })
    }
  }

  return {
    getTargetOrigin: getThingsVisTargetOrigin,
    getTrustedThingsVisFrameMessage,
    postToThingsVis,
    postPlatformData
  }
}

/**
 * 文件说明：
 * - 封装 ThingsVis iframe 宿主动作，包括保存 dashboard、打开预览页和发布 dashboard。
 * - 将 AppFrame 中的路由跳转、发布提示、保存 payload 构造和接口调用集中到一个小接口后面。
 * 维护提示：
 * - `tv:save`、`tv:preview`、`tv:publish` 属于 iframe 到宿主的跨系统契约，响应行为要与 ThingsVis guest 侧保持兼容。
 * - 保存前仍复用 `thingsvisHostSaveBridge.ts` 的数据源清理规则，避免把宿主自动生成的数据源误写回平台。
 * 审查建议：
 * - 后续如果补测试，可用注入的内存 adapter 覆盖 save/preview/publish 三条动作路径，不需要挂载 AppFrame。
 */
import type { UpdateDashboardData } from '@/service/api/thingsvis'
import {
  buildHostSaveUpdatePayload,
  type HostSaveBridgeOptions
} from '@/components/thingsvis/thingsvisHostSaveBridge'

type HostActionsLogger = {
  error: (...args: any[]) => void
}

type HostActionsMessage = {
  success?: (message: string) => void
  error?: (message: string) => void
}

type HostActionsBridgeOptions = HostSaveBridgeOptions & {
  getCurrentId: () => string
  saveDashboard: (id: string, payload: UpdateDashboardData) => Promise<{ data?: unknown; error?: any }>
  publishDashboard: (id: string) => Promise<{ data?: unknown; error?: any }>
  resolvePreviewHref: (id: string) => string
  openPreview: (href: string) => void
  emitHostSaveSuccess: (payload: { id: string; name?: string }) => void
  logger: HostActionsLogger
  message?: HostActionsMessage
  fallbackAlert?: (message: string) => void
}

export type ThingsVisHostActionsBridge = {
  save: (payload: Record<string, unknown>) => Promise<void>
  preview: (projectId: unknown) => void
  publish: (projectId: unknown) => Promise<void>
}

function resolveProjectId(projectId: unknown, fallbackId: string): string {
  return typeof projectId === 'string' && projectId.trim() ? projectId : fallbackId
}

export function createThingsVisHostActionsBridge(options: HostActionsBridgeOptions): ThingsVisHostActionsBridge {
  async function save(payload: Record<string, unknown>) {
    const currentId = options.getCurrentId()
    const updatePayload = buildHostSaveUpdatePayload(payload, options)
    const result = await options.saveDashboard(currentId, updatePayload)

    if (result.error) {
      options.logger.error('[AppFrame] Failed to save dashboard via host bridge:', result.error)
      return
    }

    options.emitHostSaveSuccess({
      id: currentId,
      name: typeof updatePayload.name === 'string' ? updatePayload.name : undefined
    })
  }

  function preview(projectId: unknown) {
    const href = options.resolvePreviewHref(resolveProjectId(projectId, options.getCurrentId()))
    options.openPreview(href)
  }

  async function publish(projectId: unknown) {
    try {
      const res = await options.publishDashboard(resolveProjectId(projectId, options.getCurrentId()))

      if (res.data) {
        if (options.message?.success) {
          options.message.success('发布成功')
        } else {
          options.fallbackAlert?.('发布成功')
        }
        return
      }

      options.logger.error('[AppFrame] Publish failed:', res.error)
      options.message?.error?.(`发布失败: ${res.error?.message || '未知错误'}`)
    } catch (error) {
      options.logger.error('[AppFrame] Publish exception:', error)
    }
  }

  return {
    save,
    preview,
    publish
  }
}

import type { UpdateDashboardData } from '@/service/api/thingsvis'
import { THINGSVIS_HOST_DATA_SOURCE_ID_PREFIX } from '@/utils/thingsvis/constants'

const GENERATED_HOST_DATA_SOURCE_ID_RE = new RegExp(
  `^(?:__platform_.+__|aetherlink_.+|${THINGSVIS_HOST_DATA_SOURCE_ID_PREFIX}.+)$`
)
const HOST_DATA_SOURCE_ID_RE = new RegExp(`^${THINGSVIS_HOST_DATA_SOURCE_ID_PREFIX}.+$`)
const DATA_SOURCE_EXPRESSION_RE = /ds\.([^\s.}]+)\./g

export type HostSaveBridgeOptions = {
  mode?: string
  normalizeCanvasBackground: (background: unknown) => Record<string, unknown>
  normalizeDashboardConfig: <T>(config: T) => T
}

export function collectReferencedDataSourceIds(value: unknown, referencedIds = new Set<string>()): Set<string> {
  if (typeof value === 'string') {
    DATA_SOURCE_EXPRESSION_RE.lastIndex = 0
    let match: RegExpExecArray | null
    while ((match = DATA_SOURCE_EXPRESSION_RE.exec(value))) {
      if (match[1]) referencedIds.add(match[1])
    }
    return referencedIds
  }

  if (Array.isArray(value)) {
    value.forEach((item) => collectReferencedDataSourceIds(item, referencedIds))
    return referencedIds
  }

  if (value && typeof value === 'object') {
    Object.entries(value as Record<string, unknown>).forEach(([key, item]) => {
      if (key === 'dataSourceId' && typeof item === 'string') {
        referencedIds.add(item)
      }
      collectReferencedDataSourceIds(item, referencedIds)
    })
  }

  return referencedIds
}

export function sanitizeDataSourcesForHostSave(
  mode: string | undefined,
  nodes: unknown,
  dataSources: unknown
): unknown[] {
  if (!Array.isArray(dataSources)) return []

  const referencedIds = collectReferencedDataSourceIds(nodes)

  return dataSources
    .filter((dataSource: any) => {
      const id = typeof dataSource?.id === 'string' ? dataSource.id : ''
      if (mode === 'editor' && HOST_DATA_SOURCE_ID_RE.test(id)) return true
      if (!GENERATED_HOST_DATA_SOURCE_ID_RE.test(id)) return true
      return referencedIds.has(id)
    })
    .map((dataSource: any) => {
      if (!dataSource?.__editorAutoManual) return dataSource
      const { __editorAutoManual: _editorAutoManual, mode: _mode, ...rest } = dataSource
      return rest
    })
}

export function buildHostSaveUpdatePayload(
  payload: Record<string, unknown>,
  options: HostSaveBridgeOptions
): UpdateDashboardData {
  const rawConfig = resolveHostSaveRawConfig(payload)
  const config = options.normalizeDashboardConfig(rawConfig) as Record<string, unknown>
  const meta = (config.meta as Record<string, unknown> | undefined) || {}
  const canvas = resolveHostSaveCanvas(config)
  const dataSources = resolveHostSaveDataSources(config)
  const updatePayload: UpdateDashboardData = {}

  if (typeof meta.name === 'string') {
    updatePayload.name = meta.name
  } else if (typeof config.name === 'string') {
    updatePayload.name = config.name
  }
  if (canvas && typeof canvas === 'object') {
    const normalizedCanvas = { ...(canvas as Record<string, unknown>) }
    normalizedCanvas.background = options.normalizeCanvasBackground(normalizedCanvas.background)
    updatePayload.canvasConfig = normalizedCanvas
  }
  if (Array.isArray(config.nodes)) {
    updatePayload.nodes = config.nodes
  }
  if (Array.isArray(dataSources)) {
    updatePayload.dataSources = sanitizeDataSourcesForHostSave(options.mode, config.nodes, dataSources)
  }
  if (config.variables !== undefined) {
    updatePayload.variables = config.variables as unknown[]
  }

  const thumbnail =
    typeof meta.thumbnail === 'string'
      ? meta.thumbnail
      : typeof payload.thumbnail === 'string'
        ? payload.thumbnail
        : undefined

  if (thumbnail !== undefined) {
    updatePayload.thumbnail = thumbnail
  }

  return updatePayload
}

function resolveHostSaveRawConfig(payload: Record<string, unknown>) {
  if (payload.config && typeof payload.config === 'object') {
    return payload.config as Record<string, unknown>
  }
  return payload
}

function resolveHostSaveCanvas(config: Record<string, unknown>) {
  if (config.canvas && typeof config.canvas === 'object') {
    return config.canvas
  }
  if (config.canvasConfig && typeof config.canvasConfig === 'object') {
    return config.canvasConfig
  }
  return null
}

function resolveHostSaveDataSources(config: Record<string, unknown>) {
  if (Array.isArray(config.dataSources)) {
    return config.dataSources
  }
  if (Array.isArray(config.dataBindings)) {
    return config.dataBindings
  }
  return []
}

type DashboardSchemaInput =
  | {
      id?: string
      name?: string
      thumbnail?: string | null
      canvasConfig?: Record<string, unknown>
      nodes?: unknown[]
      dataSources?: unknown[]
      variables?: unknown[]
    }
  | null
  | undefined

type DashboardData = {
  id: string
  name?: string
  thumbnail?: string | null
  canvasConfig: Record<string, unknown>
  nodes: unknown[]
  dataSources: unknown[]
  variables?: unknown[]
}

type LoadDashboardPayloadForInitOptions = {
  propsId: string
  schema: DashboardSchemaInput
  mode?: string
  fetchDashboardWithRetry: (id: string) => Promise<{ data?: any; error?: any }>
  normalizeDashboardConfig: <T>(config: T) => T
  sanitizeDataSourcesForHostSave: (mode: string | undefined, nodes: unknown, dataSources: unknown) => unknown[]
  onPreloadUnavailable?: (id: string, error: unknown) => void
  onPreloadError?: (id: string, error: unknown) => void
}

type ThingsVisInitConfigOptions = {
  token: string
  platformToken?: string
  thingsvisApiBaseUrl: string
  platformApiBaseUrl: string
  runtimeDeviceId?: string
}

export function hasCompleteDashboardSchema(schema: DashboardSchemaInput): schema is NonNullable<DashboardSchemaInput> {
  if (!schema || !schema.canvasConfig || typeof schema.canvasConfig !== 'object') return false
  if (!Array.isArray(schema.nodes)) return false
  if (!Array.isArray(schema.dataSources)) return false
  return true
}

export function dashboardDataFromSchema(propsId: string, schema: DashboardSchemaInput): DashboardData | null {
  if (!hasCompleteDashboardSchema(schema)) return null

  return {
    id: schema.id || propsId,
    name: schema.name,
    thumbnail: schema.thumbnail ?? null,
    canvasConfig: schema.canvasConfig!,
    nodes: schema.nodes!,
    dataSources: schema.dataSources!,
    variables: schema.variables
  }
}

export function buildDashboardPayloadForInit(
  mode: string | undefined,
  data: DashboardData | Record<string, any>,
  normalizeDashboardConfig: <T>(config: T) => T,
  sanitizeDataSourcesForHostSave: (mode: string | undefined, nodes: unknown, dataSources: unknown) => unknown[]
) {
  const nodes = Array.isArray(data.nodes) ? data.nodes : []

  return normalizeDashboardConfig({
    meta: {
      id: data.id,
      name: data.name,
      thumbnail: data.thumbnail
    },
    canvas: data.canvasConfig,
    nodes,
    dataSources: sanitizeDataSourcesForHostSave(mode, nodes, data.dataSources),
    variables: Array.isArray(data.variables) ? data.variables : []
  })
}

export async function loadDashboardPayloadForInit(
  options: LoadDashboardPayloadForInitOptions
): Promise<Record<string, unknown> | null> {
  try {
    const dashboardData = dashboardDataFromSchema(options.propsId, options.schema)
    const fetched = dashboardData
      ? { data: dashboardData, error: null }
      : await options.fetchDashboardWithRetry(options.propsId)
    const { data, error } = fetched

    if (!error && data) {
      return buildDashboardPayloadForInit(
        options.mode,
        data,
        options.normalizeDashboardConfig,
        options.sanitizeDataSourcesForHostSave
      )
    }

    if (!dashboardData) {
      options.onPreloadUnavailable?.(options.propsId, error)
    }
    return null
  } catch (error) {
    options.onPreloadError?.(options.propsId, error)
    return null
  }
}

export function buildThingsVisInitConfig(options: ThingsVisInitConfigOptions) {
  return {
    mode: 'app',
    saveTarget: 'host',
    token: options.token,
    ...(options.platformToken ? { platformToken: options.platformToken } : {}),
    thingsvisApiBaseUrl: options.thingsvisApiBaseUrl,
    platformApiBaseUrl: options.platformApiBaseUrl,
    ...(options.runtimeDeviceId ? { deviceId: options.runtimeDeviceId } : {})
  }
}

export function buildThingsVisInitMessage(
  dashboardPayload: Record<string, unknown>,
  platformBufferSize: number,
  config: Record<string, unknown>
) {
  return {
    type: 'tv:init',
    payload: {
      platformBufferSize,
      data: dashboardPayload,
      config
    }
  }
}

﻿/**
 * 文件说明：
 * - 封装 ThingsVis AppFrame 的平台设备目录编排逻辑，包括设备配置到物模型映射、分组缓存、按组加载、分页搜索和字段加载。
 * - 对 AppFrame 暴露小接口，让 iframe 消息处理只关心“加载什么”，不再关心平台 API、物模型资产和缓存细节。
 * 维护提示：
 * - 设备 ID、分组 ID、deviceConfigId、templateId 和分页响应字段属于 ThingsVis guest 侧可见契约，改动要保持兼容。
 * - 后续如果继续拆目录逻辑，优先在本模块内部拆私有 helper，不要把缓存和 API 装配重新散回 AppFrame。
 * 审查建议：
 * - 当前模块仍依赖真实平台 API 适配器；若要补测试，可从 createThingsVisPlatformDeviceCatalogOrchestrator 的依赖注入接口构造内存 adapter。
 */
import {
  asRecord,
  firstString,
  flattenDeviceGroupTree,
  loadDeviceFilterOptions,
  loadPlatformDeviceGroups,
  normalizeEditorGroupId,
  normalizeEditorGroupName,
  type DeviceFilterOption,
  type PlatformDeviceGroupEntry
} from '@/components/thingsvis/thingsvisDeviceCatalogBridge'
import { findPlatformDeviceById, loadPlatformDevicesByGroup } from '@/components/thingsvis/thingsvisDeviceLookupBridge'
import { attachPlatformDeviceTemplateAssets } from '@/components/thingsvis/thingsvisDeviceTemplateBridge'
import { createThingsVisDeviceConfigTemplateMapCache } from '@/components/thingsvis/thingsvisDeviceConfigTemplateMapCacheBridge'
import { createThingsVisTemplateAssetCacheBridge } from '@/components/thingsvis/thingsvisTemplateAssetCacheBridge'
import {
  normalizePlatformDeviceRow,
  type NormalizedPlatformDeviceRow,
  type PlatformDeviceRowContext
} from '@/components/thingsvis/thingsvisDeviceRowBridge'
import {
  buildSearchDevicesPagedParams,
  normalizeSearchDevicesPagedPayload,
  resolveSearchDevicesGroupContext,
  type SearchDevicesPagedRequest
} from '@/components/thingsvis/searchDevicesPagedBridge'
import type { PlatformDeviceField } from '@/components/thingsvis/thingsvisDeviceWsBridge'
import type { DeviceWidgetPreset } from '@/components/thingsvis/thingsvisDeviceTemplateBridge'

type CatalogLogger = {
  error: (...args: unknown[]) => void
}

type PlatformDependencyResult = {
  data?: unknown
}

type DeviceListParams = Record<string, unknown>

type PlatformDeviceCatalogDependencies = {
  loadDeviceConfigs: (params: DeviceListParams) => Promise<PlatformDependencyResult>
  loadServiceCatalog: (params: DeviceListParams) => Promise<PlatformDependencyResult>
  loadGroupTree: (params: DeviceListParams) => Promise<PlatformDependencyResult>
  listDevices: (params: DeviceListParams) => Promise<PlatformDependencyResult>
  listDevicesByGroup: (params: DeviceListParams) => Promise<PlatformDependencyResult>
  loadTemplate: (templateId: string | number) => Promise<PlatformDependencyResult>
  loadTelemetry: (params: DeviceListParams) => Promise<PlatformDependencyResult>
  loadAttributes: (params: DeviceListParams) => Promise<PlatformDependencyResult>
  loadCommands: (params: DeviceListParams) => Promise<PlatformDependencyResult>
  loadEvents: (params: DeviceListParams) => Promise<PlatformDependencyResult>
}

type PlatformDeviceCatalogLabels = {
  allGroups: string
  protocolPrefix: string
  servicePrefix: string
}

type PlatformDeviceCatalogPageSizes = {
  templateField: number
  deviceConfig: number
  groupDevice: number
}

export type PlatformDeviceEntry = {
  deviceId: string
  deviceName: string
  groupId: string
  groupName: string
  deviceConfigId?: string
  deviceConfigName?: string
  isOnline?: number | string | boolean
  warnStatus?: string
  deviceType?: string
  accessWay?: string
  protocolType?: string
  lastPushTime?: string
  templateId?: string
  fields: PlatformDeviceField[]
  presets: DeviceWidgetPreset[]
}

export type SearchDevicesPagedResponse = {
  devices: PlatformDeviceEntry[]
  total: unknown
}

export type DeviceFieldsResponse = {
  deviceId: string
  templateId: string
  fields: PlatformDeviceField[]
}

export type PlatformDeviceCatalogOrchestrator = {
  loadGroups: () => Promise<PlatformDeviceGroupEntry[]>
  loadFilterOptions: () => Promise<{ deviceConfigs: DeviceFilterOption[]; serviceOptions: DeviceFilterOption[] }>
  loadDeviceById: (deviceId: string) => Promise<PlatformDeviceEntry | null>
  loadDevicesByGroup: (groupId: string) => Promise<PlatformDeviceEntry[]>
  searchDevicesPaged: (request: SearchDevicesPagedRequest) => Promise<SearchDevicesPagedResponse>
  normalizeSearchPayload: (payload: Record<string, unknown>) => SearchDevicesPagedRequest
  loadDeviceFields: (params: {
    deviceId: string
    templateId?: string
    deviceConfigId?: string
  }) => Promise<DeviceFieldsResponse>
  reset: () => void
}

export function createThingsVisPlatformDeviceCatalogOrchestrator(options: {
  dependencies: PlatformDeviceCatalogDependencies
  labels: PlatformDeviceCatalogLabels
  pageSizes: PlatformDeviceCatalogPageSizes
  getLanguage: () => string | undefined
  logger: CatalogLogger
}): PlatformDeviceCatalogOrchestrator {
  let platformDeviceGroupsCache: PlatformDeviceGroupEntry[] | null = null
  let platformDeviceGroupsCachePromise: Promise<PlatformDeviceGroupEntry[]> | null = null
  const platformDevicesByGroupCache = new Map<string, PlatformDeviceEntry[]>()
  const platformDevicesByGroupPromise = new Map<string, Promise<PlatformDeviceEntry[]>>()

  function unwrapList(payload: unknown): unknown[] {
    const record = payload as { list?: unknown[]; data?: unknown[] } | null | undefined
    if (Array.isArray(record?.list)) return record.list
    if (Array.isArray(payload)) return payload
    if (Array.isArray(record?.data)) return record.data
    return []
  }

  const templateAssetCache = createThingsVisTemplateAssetCacheBridge({
    dependencies: options.dependencies,
    templateFieldPageSize: options.pageSizes.templateField,
    unwrapList,
    logger: options.logger
  })

  const deviceConfigTemplateMapCache = createThingsVisDeviceConfigTemplateMapCache({
    loadDeviceConfigs: options.dependencies.loadDeviceConfigs,
    deviceConfigPageSize: options.pageSizes.deviceConfig,
    unwrapList,
    logger: options.logger
  })

  async function loadFilterOptions() {
    return loadDeviceFilterOptions({
      loadDeviceConfigs: () =>
        options.dependencies.loadDeviceConfigs({ page: 1, page_size: options.pageSizes.deviceConfig }),
      loadServiceCatalog: () => options.dependencies.loadServiceCatalog({ language_code: options.getLanguage() }),
      unwrapList,
      firstString,
      asRecord,
      protocolLabelPrefix: options.labels.protocolPrefix,
      serviceLabelPrefix: options.labels.servicePrefix
    })
  }

  async function loadGroups(): Promise<PlatformDeviceGroupEntry[]> {
    if (platformDeviceGroupsCache) {
      return platformDeviceGroupsCache
    }
    if (platformDeviceGroupsCachePromise) {
      return platformDeviceGroupsCachePromise
    }
    platformDeviceGroupsCachePromise = (async () => {
      const groups = await loadPlatformDeviceGroups({
        loadGroupTree: () => options.dependencies.loadGroupTree({}),
        flattenDeviceGroupTree,
        allGroupLabel: options.labels.allGroups,
        onError: (err) => {
          options.logger.error('[AppFrame] Failed to load platform device groups', err)
        }
      })
      platformDeviceGroupsCache = groups
      return groups
    })().finally(() => {
      platformDeviceGroupsCachePromise = null
    })
    return platformDeviceGroupsCachePromise
  }

  function getCachedGroupsForSearch(): PlatformDeviceGroupEntry[] {
    if (platformDeviceGroupsCache) {
      return platformDeviceGroupsCache
    }

    void loadGroups().catch((err) => {
      options.logger.error('[AppFrame] Failed to warm platform device groups for search', err)
    })
    return []
  }

  function buildPlatformDeviceEntry(device: NormalizedPlatformDeviceRow): PlatformDeviceEntry {
    return {
      ...device,
      fields: [],
      presets: []
    }
  }

  function mapPlatformDeviceRowForGroup(
    row: unknown,
    fallbackGroupId: string,
    fallbackGroupName: string,
    groupNameById: Map<string, string>,
    configTemplateMap: Map<string, string>
  ): PlatformDeviceEntry | null {
    const normalized = normalizePlatformDeviceRow(row as Record<string, unknown> | null | undefined, {
      fallbackGroupId,
      fallbackGroupName,
      groupNameById,
      configTemplateMap
    } satisfies PlatformDeviceRowContext)
    return normalized ? buildPlatformDeviceEntry(normalized) : null
  }

  async function buildPlatformDeviceTemplateAssets(devices: PlatformDeviceEntry[]) {
    return templateAssetCache.loadTemplateAssetsForDevices<PlatformDeviceField>(devices)
  }

  async function mapPlatformDevicesForGroup(
    rawDevices: unknown[],
    fallbackGroupId = '',
    fallbackGroupName = '',
    groups: PlatformDeviceGroupEntry[] = []
  ): Promise<PlatformDeviceEntry[]> {
    const groupNameById = new Map(groups.map((group) => [group.groupId, group.groupName]))
    const configTemplateMap = await deviceConfigTemplateMapCache.load()
    const devices = rawDevices
      .map(row => mapPlatformDeviceRowForGroup(row, fallbackGroupId, fallbackGroupName, groupNameById, configTemplateMap))
      .filter((item): item is PlatformDeviceEntry => Boolean(item))

    const templateAssets = await buildPlatformDeviceTemplateAssets(devices)
    return devices.map((device) => attachPlatformDeviceTemplateAssets(device, templateAssets))
  }

  async function buildFallbackPlatformDevicesForDefaultGroup(
    normalizedGroupId: string,
    groupName: string,
    groups: PlatformDeviceGroupEntry[]
  ): Promise<PlatformDeviceEntry[]> {
    const rootGroups = groups.filter((group) => !group.parentId || String(group.parentId) === '0')
    if (rootGroups.length !== 1 || rootGroups[0]?.groupId !== normalizedGroupId) {
      return []
    }

    const deviceRes = await options.dependencies.listDevices({ page: 1, page_size: options.pageSizes.groupDevice })
    const rawDevices = unwrapList(deviceRes?.data)
    return mapPlatformDevicesForGroup(rawDevices, normalizedGroupId, groupName, groups)
  }

  async function loadDeviceById(deviceId: string): Promise<PlatformDeviceEntry | null> {
    return findPlatformDeviceById({
      deviceId,
      loadGroups,
      searchDevices: async (normalizedDeviceId) => {
        const res = await options.dependencies.listDevices({ page: 1, page_size: 20, search: normalizedDeviceId })
        return unwrapList(res?.data)
      },
      listDevices: async () => {
        const res = await options.dependencies.listDevices({ page: 1, page_size: options.pageSizes.groupDevice })
        return unwrapList(res?.data)
      },
      mapDevicesForGroup: mapPlatformDevicesForGroup,
      loadDevicesByGroup
    })
  }

  async function loadDevicesByGroup(groupId: string): Promise<PlatformDeviceEntry[]> {
    const normalizedGroupId = normalizeEditorGroupId(groupId)

    const cached = platformDevicesByGroupCache.get(normalizedGroupId)
    if (cached) {
      return cached
    }

    const pending = platformDevicesByGroupPromise.get(normalizedGroupId)
    if (pending) {
      return pending
    }

    const promise = (async () => {
      try {
        const devices = await loadPlatformDevicesByGroup({
          groupId: normalizedGroupId,
          loadGroups,
          loadRelatedDevices: async (nextGroupId) => {
            const res = await options.dependencies.listDevicesByGroup({
              group_id: nextGroupId,
              page: 1,
              page_size: options.pageSizes.groupDevice
            })
            return unwrapList(res?.data)
          },
          mapDevicesForGroup: mapPlatformDevicesForGroup,
          buildFallbackDevices: buildFallbackPlatformDevicesForDefaultGroup,
          normalizeGroupId: normalizeEditorGroupId,
          normalizeGroupName: normalizeEditorGroupName,
          onError: (failedGroupId, err) => {
            options.logger.error('[AppFrame] Failed to assemble platformDevices for group', failedGroupId, err)
          }
        })
        platformDevicesByGroupCache.set(normalizedGroupId, devices)
        return devices
      } finally {
        platformDevicesByGroupPromise.delete(normalizedGroupId)
      }
    })()

    platformDevicesByGroupPromise.set(normalizedGroupId, promise)
    return promise
  }

  async function searchDevicesPaged(request: SearchDevicesPagedRequest): Promise<SearchDevicesPagedResponse> {
    const res = await options.dependencies.listDevices(buildSearchDevicesPagedParams(request))
    const groups = getCachedGroupsForSearch()
    const { groupId, fallbackGroupName } = resolveSearchDevicesGroupContext(request, groups)
    const devices = await mapPlatformDevicesForGroup(unwrapList(res?.data), groupId, fallbackGroupName, groups)

    return {
      devices,
      total: (res?.data as { total?: unknown } | undefined)?.total
    }
  }

  async function loadDeviceFields(params: {
    deviceId: string
    templateId?: string
    deviceConfigId?: string
  }): Promise<DeviceFieldsResponse> {
    let templateId = params.templateId
    if (!templateId && params.deviceConfigId) {
      templateId = (await deviceConfigTemplateMapCache.load()).get(params.deviceConfigId)
    }
    if (!templateId) {
      return {
        deviceId: params.deviceId,
        templateId: '',
        fields: []
      }
    }

    const entry = await templateAssetCache.loadTemplateEntry(templateId)
    if (entry.loadError) {
      throw entry.loadError
    }
    return {
      deviceId: params.deviceId,
      templateId,
      fields: Array.isArray(entry.fields) ? (entry.fields as PlatformDeviceField[]) : []
    }
  }

  function reset() {
    templateAssetCache.reset()
    platformDeviceGroupsCache = null
    platformDeviceGroupsCachePromise = null
    deviceConfigTemplateMapCache.reset()
    platformDevicesByGroupCache.clear()
    platformDevicesByGroupPromise.clear()
  }

  return {
    loadGroups,
    loadFilterOptions,
    loadDeviceById,
    loadDevicesByGroup,
    searchDevicesPaged,
    normalizeSearchPayload: normalizeSearchDevicesPagedPayload,
    loadDeviceFields,
    reset
  }
}

import {
  buildSearchDevicesPagedResultPayload,
  type SearchDevicesPagedRequest
} from '@/components/thingsvis/searchDevicesPagedBridge'
import type {
  PlatformDeviceCatalogOrchestrator,
  PlatformDeviceEntry
} from '@/components/thingsvis/thingsvisPlatformDeviceCatalogOrchestrator'
import type { PlatformDeviceField } from '@/components/thingsvis/thingsvisDeviceWsBridge'
import {
  buildThingsVisHostDiagnostic,
  buildThingsVisHostErrorPayload,
  type ThingsVisHostDiagnostic
} from '@/components/thingsvis/thingsvisHostErrorPayload'

type DeviceHostLogger = {
  warn: (...args: any[]) => void
}

type DeviceHostBridgeOptions = {
  catalog: PlatformDeviceCatalogOrchestrator
  isFrameReady: () => boolean
  registerDevices: (devices: PlatformDeviceEntry[]) => void
  updateDeviceFields: (deviceId: string, fields: PlatformDeviceField[]) => void
  postToThingsVis: (type: string, payload: Record<string, unknown>) => void
  onDiagnostic?: (diagnostic: ThingsVisHostDiagnostic) => void
  onRecovered?: () => void
  logger: DeviceHostLogger
}

type SearchDevicesPagedResponse = {
  devices: PlatformDeviceEntry[]
  total: unknown
}

function getStringPayloadValue(payload: Record<string, unknown>, key: string, fallback = ''): string {
  const value = payload[key]
  return typeof value === 'string' ? value : fallback
}

export function createThingsVisPlatformDeviceHostBridge(options: DeviceHostBridgeOptions) {
  const {
    catalog,
    isFrameReady,
    registerDevices,
    updateDeviceFields,
    postToThingsVis,
    onDiagnostic,
    onRecovered,
    logger
  } = options

  function reportDiagnostic(scope: string, error: unknown) {
    onDiagnostic?.(buildThingsVisHostDiagnostic('device_bridge', scope, error))
  }

  async function requestDeviceGroups() {
    try {
      const groups = await catalog.loadGroups()
      onRecovered?.()
      postToThingsVis('tv:device-groups', { groups })
    } catch (error) {
      logger.warn('[AppFrame] Failed to load requested device groups:', error)
      reportDiagnostic('device_groups', error)
      postToThingsVis('tv:device-groups', {
        groups: [],
        ...buildThingsVisHostErrorPayload('device_groups', error)
      })
    }
  }

  async function requestDeviceFilterOptions(payload: Record<string, unknown>) {
    const reqId = getStringPayloadValue(payload, 'reqId')

    try {
      const options = await catalog.loadFilterOptions()
      postToThingsVis('tv:device-filter-options', {
        reqId,
        ...options
      })
      onRecovered?.()
    } catch (error) {
      logger.warn('[AppFrame] Failed to load requested device filter options:', error)
      reportDiagnostic('device_filter_options', error)
      postToThingsVis('tv:device-filter-options', {
        reqId,
        deviceConfigs: [],
        serviceOptions: [],
        ...buildThingsVisHostErrorPayload('device_filter_options', error)
      })
    }
  }

  async function requestDeviceById(payload: Record<string, unknown>) {
    const reqId = getStringPayloadValue(payload, 'reqId')
    const deviceId = getStringPayloadValue(payload, 'deviceId')
    if (!deviceId) return

    try {
      const device = await catalog.loadDeviceById(deviceId)
      if (device) registerDevices([device])
      postToThingsVis('tv:device-by-id', {
        reqId,
        deviceId,
        device
      })
      onRecovered?.()
    } catch (error) {
      logger.warn('[AppFrame] Failed to load requested device by id:', deviceId, error)
      reportDiagnostic('device_by_id', error)
      postToThingsVis('tv:device-by-id', {
        reqId,
        deviceId,
        device: null,
        ...buildThingsVisHostErrorPayload('device_by_id', error)
      })
    }
  }

  async function requestDevicesByGroup(payload: Record<string, unknown>) {
    const groupId = getStringPayloadValue(payload, 'groupId') || undefined
    if (!groupId) return

    try {
      const devices = await catalog.loadDevicesByGroup(groupId)
      registerDevices(devices)
      postToThingsVis('tv:devices-by-group', { groupId, devices })
      onRecovered?.()
    } catch (error) {
      logger.warn('[AppFrame] Failed to load requested device group:', groupId, error)
      reportDiagnostic('devices_by_group', error)
      postToThingsVis('tv:devices-by-group', {
        groupId,
        devices: [],
        ...buildThingsVisHostErrorPayload('devices_by_group', error)
      })
    }
  }

  function postSearchDevicesPagedResult(
    request: Pick<SearchDevicesPagedRequest, 'reqId' | 'page' | 'pageSize'>,
    devices: PlatformDeviceEntry[],
    total: unknown,
    extraPayload: Record<string, unknown> = {}
  ) {
    postToThingsVis('tv:search-devices-paged-result', {
      ...buildSearchDevicesPagedResultPayload(request, devices, total),
      ...extraPayload
    })
  }

  async function searchDevicesPaged(request: SearchDevicesPagedRequest): Promise<SearchDevicesPagedResponse> {
    const result = await catalog.searchDevicesPaged(request)
    const devices = result.devices
    registerDevices(devices)
    return result
  }

  async function requestSearchDevicesPaged(payload: Record<string, unknown>) {
    const request = catalog.normalizeSearchPayload(payload)

    try {
      const result = await searchDevicesPaged(request)
      postSearchDevicesPagedResult(request, result.devices, result.total)
      onRecovered?.()
    } catch (error) {
      logger.warn('[AppFrame] Failed to search devices:', error)
      reportDiagnostic('search_devices', error)
      postSearchDevicesPagedResult(request, [], 0, buildThingsVisHostErrorPayload('search_devices', error))
    }
  }

  async function requestDeviceFields(payload: Record<string, unknown>) {
    const deviceId = getStringPayloadValue(payload, 'deviceId') || undefined
    const directTemplateId = getStringPayloadValue(payload, 'templateId') || undefined
    const deviceConfigId = getStringPayloadValue(payload, 'deviceConfigId') || undefined
    if (!isFrameReady() || !deviceId) return

    try {
      const result = await catalog.loadDeviceFields({
        deviceId,
        templateId: directTemplateId,
        deviceConfigId
      })
      updateDeviceFields(deviceId, result.fields)
      postToThingsVis('tv:device-fields', result)
      onRecovered?.()
    } catch (error) {
      logger.warn('[AppFrame] Failed to load requested device fields:', deviceId, directTemplateId, error)
      reportDiagnostic('device_fields', error)
      postToThingsVis('tv:device-fields', {
        deviceId,
        templateId: directTemplateId,
        deviceConfigId,
        fields: [],
        ...buildThingsVisHostErrorPayload('device_fields', error)
      })
    }
  }

  return {
    requestDeviceGroups,
    requestDeviceFilterOptions,
    requestDeviceById,
    requestDevicesByGroup,
    searchDevicesPaged: requestSearchDevicesPaged,
    requestDeviceFields
  }
}

import { firstString } from '@/components/thingsvis/thingsvisDeviceCatalogBridge'
import {
  collectPlatformSourceDescriptors,
  type PlatformSourceDescriptor
} from '@/components/thingsvis/thingsvisFieldHydrationBridge'
import type { PlatformDeviceEntry } from '@/components/thingsvis/thingsvisPlatformDeviceCatalogOrchestrator'
import type { PlatformDeviceField } from '@/components/thingsvis/thingsvisDeviceWsBridge'

const PLATFORM_DEVICE_DATA_SOURCE_ID_RE = /^__platform_(.+)__$/
const AETHERLINK_DATA_SOURCE_ID_RE = /^aetherlink_.+$/

type CurrentDashboardConfig = {
  id?: string
  name?: string
  canvas?: unknown
  nodes?: unknown[]
  dataSources?: unknown[]
  variables?: unknown[]
}

type PlatformSourceDeviceBinding = {
  dataSourceId?: string
  deviceId?: string
}

type PlatformSourceBindingInput = {
  dataSourceId?: unknown
  deviceId?: unknown
  configuredDeviceId?: unknown
  syncCurrentSchema?: boolean
}

function parsePlatformDeviceIdFromDataSourceId(dataSourceId: unknown): string | undefined {
  if (typeof dataSourceId !== 'string') return undefined
  const matched = PLATFORM_DEVICE_DATA_SOURCE_ID_RE.exec(dataSourceId)
  return firstString(matched?.[1])
}

export function buildPlatformSourceBindingOptions(source: PlatformSourceBindingInput) {
  return {
    dataSourceId: typeof source.dataSourceId === 'string' ? source.dataSourceId : undefined,
    deviceId: typeof source.deviceId === 'string' ? source.deviceId : undefined,
    configuredDeviceId: typeof source.configuredDeviceId === 'string' ? source.configuredDeviceId : undefined,
    syncCurrentSchema: source.syncCurrentSchema
  }
}

export function createThingsVisPlatformRuntimeBridge(options: {
  getCurrentDashboardConfig: () => CurrentDashboardConfig | null
}) {
  const activePlatformDevices = new Map<string, { deviceId: string; fields: PlatformDeviceField[] }>()
  const activePlatformDataSourceDeviceIds = new Map<string, string>()

  function registerDevices(devices: PlatformDeviceEntry[]) {
    devices.forEach((device) => {
      if (!device?.deviceId) return
      const existing = activePlatformDevices.get(device.deviceId)
      activePlatformDevices.set(device.deviceId, {
        deviceId: device.deviceId,
        fields: Array.isArray(existing?.fields) && existing.fields.length > 0 ? existing.fields : device.fields || []
      })
    })
  }

  function updateDeviceFields(deviceId: string, fields: PlatformDeviceField[]) {
    const normalizedFields = Array.isArray(fields) ? fields : []
    activePlatformDevices.set(deviceId, { deviceId, fields: normalizedFields })
    return normalizedFields
  }

  function ensureDevice(deviceId?: string) {
    if (!deviceId || activePlatformDevices.has(deviceId)) return
    activePlatformDevices.set(deviceId, { deviceId, fields: [] })
  }

  function getDevice(deviceId?: string) {
    return deviceId ? activePlatformDevices.get(deviceId) : undefined
  }

  function getDeviceFields(deviceId?: string): PlatformDeviceField[] {
    return getDevice(deviceId)?.fields || []
  }

  function findConfiguredDeviceId(dataSourceId: unknown): string | undefined {
    return typeof dataSourceId === 'string' ? activePlatformDataSourceDeviceIds.get(dataSourceId) : undefined
  }

  function syncDevicesFromCurrentSchema() {
    const dashboardData = options.getCurrentDashboardConfig()
    if (!dashboardData) return
    syncDevicesFromConfig(dashboardData)
  }

  function resolveDeviceIdFromDataSourceId(dataSourceId: unknown, syncCurrentSchema = true): string | undefined {
    if (syncCurrentSchema && typeof dataSourceId === 'string' && !activePlatformDataSourceDeviceIds.has(dataSourceId)) {
      syncDevicesFromCurrentSchema()
    }

    const configuredDeviceId = findConfiguredDeviceId(dataSourceId)
    if (configuredDeviceId) return configuredDeviceId
    if (typeof dataSourceId === 'string' && AETHERLINK_DATA_SOURCE_ID_RE.test(dataSourceId)) return undefined
    return parsePlatformDeviceIdFromDataSourceId(dataSourceId)
  }

  function resolveBinding(options: ReturnType<typeof buildPlatformSourceBindingOptions>): PlatformSourceDeviceBinding {
    const deviceId =
      options.deviceId ||
      options.configuredDeviceId ||
      resolveDeviceIdFromDataSourceId(options.dataSourceId, options.syncCurrentSchema)

    return {
      dataSourceId: options.dataSourceId,
      deviceId
    }
  }

  function resolveBindingFromPayload(source: PlatformSourceBindingInput): PlatformSourceDeviceBinding {
    return resolveBinding(buildPlatformSourceBindingOptions(source))
  }

  function collectConfiguredDescriptors(config: any): PlatformSourceDescriptor[] {
    return collectPlatformSourceDescriptors(config, {
      resolveDeviceId: (dataSourceId, configuredDeviceId) =>
        resolveBinding(
          buildPlatformSourceBindingOptions({
            dataSourceId,
            configuredDeviceId,
            syncCurrentSchema: false
          })
        ).deviceId
    })
  }

  function syncDevicesFromConfig(config: any) {
    activePlatformDevices.clear()
    activePlatformDataSourceDeviceIds.clear()

    collectConfiguredDescriptors(config).forEach((descriptor) => {
      if (descriptor.deviceId) {
        activePlatformDataSourceDeviceIds.set(descriptor.id, descriptor.deviceId)
      }
      if (!descriptor.deviceId || activePlatformDevices.has(descriptor.deviceId)) return

      activePlatformDevices.set(descriptor.deviceId, {
        deviceId: descriptor.deviceId,
        fields: []
      })
    })
  }

  function resolveRuntimeDeviceId(dashboardPayload: Record<string, unknown>, mode?: string) {
    syncDevicesFromConfig(dashboardPayload)
    if (mode !== 'viewer') return undefined
    return activePlatformDevices.size === 1 ? Array.from(activePlatformDevices.keys())[0] : undefined
  }

  function clearDevices() {
    activePlatformDevices.clear()
  }

  function clearDataSourceBindings() {
    activePlatformDataSourceDeviceIds.clear()
  }

  return {
    registerDevices,
    updateDeviceFields,
    ensureDevice,
    getDevice,
    getDeviceFields,
    resolveBindingFromPayload,
    collectConfiguredDescriptors,
    syncDevicesFromConfig,
    resolveRuntimeDeviceId,
    clearDevices,
    clearDataSourceBindings
  }
}

/**
 * 文件说明：
 * - 封装 ThingsVis 平台写入请求的纯解析逻辑，包括设备 ID、字段 ID、字段类型、命令参数和错误文案。
 * - AppFrame 保留实际 API 发布调用，本模块只负责把 iframe payload 转成可执行的写入意图。
 * 维护提示：
 * - telemetry、attribute、command 三类写入的字段类型语义会影响设备控制链路，新增类型时要同步宿主和 ThingsVis runtime。
 * - command 写入要求 payload 中只有一个命令字段，避免多个命令被错误合并到同一次下发。
 */
import type { PlatformField } from '@/utils/thingsvis/types'

export class PlatformWriteValidationError extends Error {}

export type PlatformWriteRequest = {
  deviceId: string
  data: unknown
}

type ResolvePlatformWriteRequestOptions = {
  resolveDeviceId: (payload: Record<string, unknown>) => string | undefined
}

export type PlatformWritePublishDependencies = {
  telemetryDataPub: (params: { device_id: string; value: string }) => Promise<any>
  attributeDataPub: (params: { device_id: string; value: string }) => Promise<any>
  commandDataPub: (params: { device_id: string; identify: string; value: string }) => Promise<any>
}

export function resolveWriteFieldId(data: unknown): string | undefined {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return undefined
  const keys = Object.keys(data as Record<string, unknown>)
  return keys.length === 1 ? keys[0] : undefined
}

export function resolveWriteFieldType(
  fields: Array<Pick<PlatformField, 'id' | 'name' | 'dataType'>>,
  fieldId?: string
): PlatformField['dataType'] | undefined {
  if (!fieldId) return undefined
  const field = fields.find((item) => item.id === fieldId || item.name === fieldId)
  return field?.dataType
}

export function resolveCommandWrite(data: unknown, fieldId?: string): { identify: string; value: string } | null {
  if (!fieldId || !data || typeof data !== 'object' || Array.isArray(data)) return null
  const params = (data as Record<string, unknown>)[fieldId]
  return {
    identify: fieldId,
    value: JSON.stringify(params ?? {})
  }
}

export function buildPlatformWriteValue(data: unknown): string {
  return typeof data === 'string' ? data : JSON.stringify(data)
}

export async function publishPlatformWriteByFieldType(options: {
  deviceId: string
  data: unknown
  value: string
  fieldType: PlatformField['dataType'] | undefined
  fieldId?: string
  dependencies: PlatformWritePublishDependencies
}): Promise<any> {
  if (options.fieldType === 'attribute') {
    return options.dependencies.attributeDataPub({ device_id: options.deviceId, value: options.value })
  }

  if (options.fieldType === 'command') {
    const commandWrite = resolveCommandWrite(options.data, options.fieldId)
    if (!commandWrite) {
      throw new PlatformWriteValidationError('Command write requires a single command field payload')
    }
    return options.dependencies.commandDataPub({
      device_id: options.deviceId,
      identify: commandWrite.identify,
      value: commandWrite.value
    })
  }

  if (options.fieldType === 'telemetry' || options.fieldType === undefined) {
    return options.dependencies.telemetryDataPub({ device_id: options.deviceId, value: options.value })
  }

  throw new PlatformWriteValidationError(`Unsupported write field type '${options.fieldType}'`)
}

export async function publishPlatformWrite(options: {
  deviceId: string
  data: unknown
  fields: Array<Pick<PlatformField, 'id' | 'name' | 'dataType'>>
  dependencies: PlatformWritePublishDependencies
}): Promise<any> {
  const value = buildPlatformWriteValue(options.data)
  const fieldId = resolveWriteFieldId(options.data)
  const fieldType = resolveWriteFieldType(options.fields, fieldId)

  return publishPlatformWriteByFieldType({
    deviceId: options.deviceId,
    data: options.data,
    value,
    fieldType,
    fieldId,
    dependencies: options.dependencies
  })
}

export function resolvePlatformWriteRequest(
  payload: Record<string, unknown>,
  options: ResolvePlatformWriteRequestOptions
): PlatformWriteRequest | null {
  const deviceId = options.resolveDeviceId(payload)
  const data = payload.data
  if (!deviceId || data === undefined) return null

  return { deviceId, data }
}

export function resolvePlatformWriteErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error || 'Platform write failed')
}

import {
  fetchTemplateEntry,
  fetchTemplatePresets,
  loadPlatformDeviceTemplateAssets,
  type TemplateEntry
} from '@/components/thingsvis/thingsvisDeviceTemplateBridge'

type DeviceListParams = Record<string, unknown>

type TemplateAssetCacheDependencies = {
  loadTemplate: (templateId: string | number) => Promise<any>
  loadTelemetry: (params: DeviceListParams) => Promise<any>
  loadAttributes: (params: DeviceListParams) => Promise<any>
  loadCommands: (params: DeviceListParams) => Promise<any>
  loadEvents: (params: DeviceListParams) => Promise<any>
}

type TemplateAssetCacheLogger = {
  error: (...args: any[]) => void
}

export type ThingsVisTemplateAssetCacheBridgeOptions = {
  dependencies: TemplateAssetCacheDependencies
  templateFieldPageSize: number
  unwrapList: (payload: any) => any[]
  logger: TemplateAssetCacheLogger
}

export function createThingsVisTemplateAssetCacheBridge(options: ThingsVisTemplateAssetCacheBridgeOptions) {
  const templateEntryCache = new Map<string, TemplateEntry>()
  const templateEntryPromise = new Map<string, Promise<TemplateEntry>>()
  const templatePresetCache = new Map<string, any[]>()
  const templatePresetPromise = new Map<string, Promise<any[]>>()

  async function loadTemplatePresets(templateId: string | number): Promise<any[]> {
    const cacheKey = String(templateId)
    if (templatePresetCache.has(cacheKey)) {
      return templatePresetCache.get(cacheKey) || []
    }
    if (templatePresetPromise.has(cacheKey)) {
      return templatePresetPromise.get(cacheKey) as Promise<any[]>
    }

    const promise = (async () => {
      const presets = await fetchTemplatePresets({
        templateId,
        loadTemplate: options.dependencies.loadTemplate,
        onError: (failedTemplateId, error) => {
          options.logger.error('[AppFrame] Failed to load thing-model presets', failedTemplateId, error)
        }
      })
      templatePresetCache.set(cacheKey, presets)
      return presets
    })().finally(() => {
      templatePresetPromise.delete(cacheKey)
    })

    templatePresetPromise.set(cacheKey, promise)
    return promise
  }

  async function loadTemplateEntry(templateId: string | number): Promise<TemplateEntry> {
    const cacheKey = String(templateId)
    if (templateEntryCache.has(cacheKey)) {
      return templateEntryCache.get(cacheKey) as TemplateEntry
    }
    if (templateEntryPromise.has(cacheKey)) {
      return templateEntryPromise.get(cacheKey) as Promise<TemplateEntry>
    }

    const promise = (async () => {
      const entry = await fetchTemplateEntry({
        templateId,
        pageSize: options.templateFieldPageSize,
        loadTelemetry: options.dependencies.loadTelemetry,
        loadAttributes: options.dependencies.loadAttributes,
        loadCommands: options.dependencies.loadCommands,
        loadEvents: options.dependencies.loadEvents,
        unwrapList: options.unwrapList
      })
      if (!entry.loadError) {
        templateEntryCache.set(cacheKey, entry)
      }
      return entry
    })().finally(() => {
      templateEntryPromise.delete(cacheKey)
    })

    templateEntryPromise.set(cacheKey, promise)
    return promise
  }

  async function loadTemplateAssetsForDevices<TField>(devices: Array<{ templateId?: string }>) {
    return loadPlatformDeviceTemplateAssets<TField>({
      devices,
      loadTemplatePresets: async (templateId) => loadTemplatePresets(templateId),
      loadTemplateEntry: async (templateId) => {
        const entry = await loadTemplateEntry(templateId)
        return {
          fields: Array.isArray(entry.fields) ? (entry.fields as TField[]) : []
        }
      }
    })
  }

  function reset() {
    templateEntryCache.clear()
    templateEntryPromise.clear()
    templatePresetCache.clear()
    templatePresetPromise.clear()
  }

  return {
    loadTemplateEntry,
    loadTemplatePresets,
    loadTemplateAssetsForDevices,
    reset
  }
}

/**
 * 文件说明：
 * - 封装 ThingsVis viewer 模式的平台数据补水调度，集中处理延迟触发、进行中保护、完成标记和 dashboard 配置缓存。
 * - AppFrame 只注入 dashboard 读取、字段读取、WebSocket ensure 和 postPlatformData 等副作用能力。
 * 维护提示：
 * - viewer 补水只应在 viewer 模式执行；editor 模式的预取和消息回推仍留在 AppFrame。
 * - dashboard 配置为空时不能标记完成，避免 ThingsVis iframe 比平台配置更早 ready 时丢失后续补水机会。
 * 审查建议：
 * - 后续补测试时应覆盖 schema 直传、接口回退、重复 schedule、reset 后重新补水和 dispose 清理。
 */
import {
  groupPlatformSourceDescriptorsByDevice,
  hydratePlatformSourceDescriptorGroup,
  type PlatformSourceDescriptor
} from '@/components/thingsvis/thingsvisFieldHydrationBridge'

type DashboardSchemaInput =
  | {
      id?: string
      name?: string
      canvasConfig?: Record<string, unknown>
      nodes?: unknown[]
      dataSources?: unknown[]
      variables?: unknown[]
    }
  | null
  | undefined

type ViewerHydrationContext = {
  id: string
  mode?: string
  schema?: DashboardSchemaInput
}

type ViewerHydrationOptions = {
  getContext: () => ViewerHydrationContext
  fetchDashboardWithRetry: (id: string) => Promise<{ data?: any; error?: any }>
  normalizeDashboardConfig: <T>(config: T) => T
  collectConfiguredDescriptors: (config: any) => PlatformSourceDescriptor[]
  ensureDeviceWs: (deviceId: string) => void
  ensureDeviceStatusWs: (deviceId: string) => void
  loadRequestedFieldData: (fieldIds: string[], deviceId: string) => Promise<Record<string, unknown>>
  postPlatformData: (fields: Record<string, unknown>, deviceId?: string, dataSourceId?: string) => void
  onLoadError?: (id: string, error: unknown) => void
  delay?: number
}

export type ThingsVisViewerHydrationBridge = {
  schedule: () => void
  reset: () => void
  dispose: () => void
}

export function createThingsVisViewerHydrationBridge(
  options: ViewerHydrationOptions
): ThingsVisViewerHydrationBridge {
  const delay = options.delay ?? 200

  let hydrationTimers: Array<ReturnType<typeof setTimeout>> = []
  let hydrationInFlight = false
  let hydrationDone = false
  let dashboardConfigCache: Record<string, unknown> | null = null
  let dashboardConfigPromise: Promise<Record<string, unknown> | null> | null = null
  let dashboardConfigCacheId: string | null = null

  function clearTimers() {
    hydrationTimers.forEach((timer) => clearTimeout(timer))
    hydrationTimers = []
  }

  function normalizeSchemaConfig(context: ViewerHydrationContext): Record<string, unknown> | null {
    if (!context.schema) return null
    return options.normalizeDashboardConfig({
      id: context.schema.id || context.id,
      name: context.schema.name,
      canvas: context.schema.canvasConfig,
      nodes: Array.isArray(context.schema.nodes) ? context.schema.nodes : [],
      dataSources: Array.isArray(context.schema.dataSources) ? context.schema.dataSources : [],
      variables: Array.isArray(context.schema.variables) ? context.schema.variables : []
    })
  }

  async function loadDashboardConfig(): Promise<Record<string, unknown> | null> {
    const context = options.getContext()
    if (context.mode !== 'viewer') return null

    const schemaConfig = normalizeSchemaConfig(context)
    if (schemaConfig) return schemaConfig

    if (dashboardConfigCache && dashboardConfigCacheId === context.id) return dashboardConfigCache
    if (dashboardConfigPromise) return dashboardConfigPromise

    dashboardConfigPromise = (async () => {
      try {
        const { data, error } = await options.fetchDashboardWithRetry(context.id)
        if (error || !data) return null

        dashboardConfigCacheId = context.id
        dashboardConfigCache = options.normalizeDashboardConfig({
          id: data.id,
          name: data.name,
          canvas: data.canvasConfig,
          nodes: Array.isArray(data.nodes) ? data.nodes : [],
          dataSources: Array.isArray(data.dataSources) ? data.dataSources : [],
          variables: Array.isArray(data.variables) ? data.variables : []
        })
        return dashboardConfigCache
      } catch (error) {
        options.onLoadError?.(context.id, error)
        return null
      } finally {
        dashboardConfigPromise = null
      }
    })()

    return dashboardConfigPromise
  }

  async function hydrateConfiguredSources(): Promise<boolean> {
    const config = await loadDashboardConfig()
    if (!config) return false

    const descriptors = options.collectConfiguredDescriptors(config)
    if (descriptors.length === 0) return true

    for (const [deviceId, group] of groupPlatformSourceDescriptorsByDevice(descriptors)) {
      await hydratePlatformSourceDescriptorGroup({
        deviceId,
        group,
        ensureDeviceWs: options.ensureDeviceWs,
        ensureDeviceStatusWs: options.ensureDeviceStatusWs,
        loadRequestedFieldData: options.loadRequestedFieldData,
        postPlatformData: options.postPlatformData
      })
    }

    return true
  }

  function schedule() {
    const context = options.getContext()
    if (context.mode !== 'viewer') return
    if (hydrationDone || hydrationInFlight) return

    clearTimers()

    const timer = setTimeout(async () => {
      if (hydrationDone || hydrationInFlight) return

      hydrationInFlight = true
      try {
        const hasConfig = await hydrateConfiguredSources()
        if (hasConfig) {
          hydrationDone = true
        }
      } finally {
        hydrationInFlight = false
      }
    }, delay)

    hydrationTimers.push(timer)
  }

  function reset() {
    clearTimers()
    hydrationInFlight = false
    hydrationDone = false
  }

  function dispose() {
    reset()
    dashboardConfigCache = null
    dashboardConfigCacheId = null
    dashboardConfigPromise = null
  }

  return {
    schedule,
    reset,
    dispose
  }
}

