  [key: string]: unknown
}

/** 小部件节点（JSON 配置，字段宽松，运行时逐个校验） */
type ThingsVisNodeLike = {
  type?: unknown
  data?: ThingsVisFieldBinding[] | null
  props?: Record<string, unknown> | null
  events?: ThingsVisNodeEventHandler[] | null
  x?: unknown
  y?: unknown
  width?: unknown
  height?: unknown
}

/** 小部件页面配置（JSON 配置，字段宽松） */
type ThingsVisWidgetConfigLike = {
  nodes?: ThingsVisNodeLike[] | null
  dataSources?: ThingsVisDataSourceLike[] | null
  canvas?: ThingsVisCanvasLike | null
  canvasConfig?: ThingsVisCanvasLike | null
  [key: string]: unknown
}

const CARTESIAN_CHART_TYPES = new Set(THINGSVIS_WIDGET_CARTESIAN_CHART_TYPES)
const PIE_CHART_TYPES = new Set(THINGSVIS_WIDGET_PIE_CHART_TYPES)
const GAUGE_CHART_TYPES = new Set(THINGSVIS_WIDGET_GAUGE_CHART_TYPES)
const MODEL_3D_TYPES = new Set(THINGSVIS_WIDGET_MODEL_3D_TYPES)

const DEFAULT_CARTESIAN_CHART_FONT_SIZES: ChartFontSizeConfig = {
  title: 16,
  legend: 12,
  axisLabel: 12,
  axisName: 12,
  seriesLabel: 12,
  tooltip: 12
}

const DEFAULT_PIE_CHART_FONT_SIZES: ChartFontSizeConfig = {
  title: 16,
  legend: 12,
  pieLabel: 12,
  tooltip: 12
}

const DEFAULT_GAUGE_CHART_FONT_SIZES: ChartFontSizeConfig = {
  title: 16,
  axisLabel: 11,
  value: 24,
  gaugeDetail: 16,
  tooltip: 12
}

const DEFAULT_MODEL_3D_PROPS = {
  acceptedExtensions: THINGSVIS_WIDGET_MODEL_3D_ACCEPTED_EXTENSIONS,
  maxUploadSizeMb: THINGSVIS_WIDGET_MODEL_3D_MAX_UPLOAD_SIZE_MB,
  cameraControls: true,
  autoRotate: false,
  backgroundColor: 'transparent'
}

type ThingsVisWidgetMode = 'viewer' | 'editor'

type NormalizeThingsVisWidgetLoadConfigOptions = {
  mode?: ThingsVisWidgetMode
  previewDeviceId?: string
  fieldValueTypes: Record<string, string>
}

export const parseThingsVisFieldBindingExpression = (expression: unknown) => {
  if (typeof expression !== 'string') return null
  const match = FIELD_BINDING_EXPR_RE.exec(expression.trim())
  if (!match?.[1] || !match?.[2]) return null

  return {
    dataSourceId: match[1],
    fieldPath: match[2]
  }
}

export const getThingsVisFieldRoot = (fieldPath?: string) => {
  if (!fieldPath) return ''
  return fieldPath.split(/[.[\]]/).filter(Boolean)[0] || ''
}

const getEzuikitPlaybackDefaults = () => {
  const spaceId = String(import.meta.env.VITE_EZUIKIT_DEFAULT_SPACE_ID ?? '').trim()
  const busType = String(import.meta.env.VITE_EZUIKIT_DEFAULT_BUS_TYPE ?? '').trim()
  const compatDefaultsEnabled = import.meta.env.VITE_ENABLE_EZUIKIT_COMPAT_DEFAULTS === 'Y'

  return {
    spaceId: spaceId || (compatDefaultsEnabled ? EZUIKIT_COMPAT_DEFAULT_SPACE_ID : ''),
    busType: busType || (compatDefaultsEnabled ? EZUIKIT_COMPAT_DEFAULT_BUS_TYPE : '')
  }
}

const isPlatformFieldDataSource = (dataSource: ThingsVisDataSourceLike) => {
  const rawType = dataSource?.type
  const type = typeof rawType === 'string' ? rawType.toUpperCase() : ''
  return type === 'PLATFORM_FIELD' || type === 'PLATFORM'
}

const normalizeViewerPlatformDataSources = (
  config: ThingsVisWidgetConfigLike,
  options: NormalizeThingsVisWidgetLoadConfigOptions
) => {
  if (!config || options.mode !== 'viewer' || !Array.isArray(config.dataSources)) return config

  const previewDeviceId = options.previewDeviceId
  if (!previewDeviceId) return config

  return {
    ...config,
    dataSources: config.dataSources.map((dataSource) => {
      if (!isPlatformFieldDataSource(dataSource)) return dataSource
      if (dataSource?.config?.deviceId) return dataSource

      return {
        ...dataSource,
        config: {
          ...(dataSource.config || {}),
          deviceId: previewDeviceId
        }
      }
    })
  }
}

const resolveInteractiveWriteBinding = (
  node: ThingsVisNodeLike,
  options: NormalizeThingsVisWidgetLoadConfigOptions
) => {
  const bindings = Array.isArray(node?.data) ? node.data : []
  const valueBinding = bindings.find((binding) => binding?.targetProp === 'value')
  const parsed =
    parseThingsVisFieldBindingExpression(valueBinding?.expression) ||
    parseThingsVisFieldBindingExpression(node?.props?.value)
  if (!parsed?.dataSourceId || !parsed.fieldPath) return null

  const fieldId = getThingsVisFieldRoot(parsed.fieldPath)
  if (!fieldId) return null

  return {
    dataSourceId: parsed.dataSourceId,
    fieldId,
    fieldValueType: options.fieldValueTypes[fieldId]
  }
}

const buildInteractiveAutoWriteAction = (dataSourceId: string, fieldId: string, fieldValueType?: string) => ({
  type: 'callWrite',
  dataSourceId,
  payload: `({ ${JSON.stringify(fieldId)}: ${fieldValueType === 'number' ? 'payload ? 1 : 0' : 'payload'} })`,
  __thingsvisAutoWrite: AUTO_WRITE_MARKER,
  ...(fieldValueType === 'number' || fieldValueType === 'boolean'
    ? { __thingsvisAutoWriteValueType: fieldValueType }
    : {})
})

const upsertNodeEventActions = (
  events: ThingsVisNodeEventHandler[],
  eventName: string,
  resolveActions: (actions: ThingsVisNodeEventAction[]) => ThingsVisNodeEventAction[] | null
) => {
  const nextEvents = [...events]
  const index = nextEvents.findIndex((handler) => handler?.event === eventName)

  if (index >= 0) {
    const existing = nextEvents[index]
    const actions = Array.isArray(existing?.actions) ? existing.actions : []
    const nextActions = resolveActions(actions)
    if (nextActions) {
      nextEvents[index] = {
        ...existing,
        actions: nextActions
      }
    }
    return nextEvents
  }

  const nextActions = resolveActions([])
  if (nextActions) {
    nextEvents.push({
      event: eventName,
      actions: nextActions
    })
  }

  return nextEvents
}

const upsertInteractiveAutoWriteEvent = (
  events: ThingsVisNodeEventHandler[],
  eventName: string,
  autoAction: ReturnType<typeof buildInteractiveAutoWriteAction>
) =>
  upsertNodeEventActions(events, eventName, (actions) => {
    const manualActions = actions.filter((action) => action?.__thingsvisAutoWrite !== AUTO_WRITE_MARKER)
    return [...manualActions, autoAction]
  })

const normalizeInteractiveWriteNode = (
  node: ThingsVisNodeLike,
  options: NormalizeThingsVisWidgetLoadConfigOptions
) => {
  const rawNodeType = node?.type
  const eventName = typeof rawNodeType === 'string' ? DEFAULT_WRITE_EVENT_BY_COMPONENT[rawNodeType] : undefined
  if (!eventName) return node

  const binding = resolveInteractiveWriteBinding(node, options)
  if (!binding) return node

  const events = Array.isArray(node?.events) ? node.events : []
  const autoAction = buildInteractiveAutoWriteAction(binding.dataSourceId, binding.fieldId, binding.fieldValueType)

  return {
    ...node,
    events: upsertInteractiveAutoWriteEvent(events, eventName, autoAction)
  }
}

const ensureInteractiveWriteEvents = (
  config: ThingsVisWidgetConfigLike,
  options: NormalizeThingsVisWidgetLoadConfigOptions
) => {
  if (!config || !Array.isArray(config.nodes)) return config

  return {
    ...config,
    nodes: config.nodes.map((node) => normalizeInteractiveWriteNode(node, options))
  }
}

const resolvePlatformDataSourceId = (config: ThingsVisWidgetConfigLike): string | undefined => {
  const dataSources = Array.isArray(config?.dataSources) ? config.dataSources : []
  const platformDs = dataSources.find((dataSource) => isPlatformFieldDataSource(dataSource))
  return typeof platformDs?.id === 'string' ? platformDs.id : undefined
}

const buildEzuikitWriteAction = (dataSourceId: string, payload: string) => ({
  type: 'callWrite',
  dataSourceId,
  payload
})

const upsertEzuikitWriteEvent = (
  events: ThingsVisNodeEventHandler[],
  eventName: string,
  action: ReturnType<typeof buildEzuikitWriteAction>
) =>
  upsertNodeEventActions(events, eventName, (actions) => {
    if (actions.length === 0) return [action]
    return null
  })

const ensureEzuikitNodeEvents = (node: ThingsVisNodeLike, dataSourceId: string) => {
  const events = Array.isArray(node?.events) ? node.events : []
  const playbackAction = buildEzuikitWriteAction(
    dataSourceId,
    `({ ${JSON.stringify(EZUIKIT_PLAYBACK_COMMAND)}: payload })`
  )
  const liveAction = buildEzuikitWriteAction(
    dataSourceId,
    `({ ${JSON.stringify(EZUIKIT_PLAYBACK_COMMAND)}: { type: "live" } })`
  )

  return upsertEzuikitWriteEvent(
    upsertEzuikitWriteEvent(events, 'playbackRequest', playbackAction),
    'liveRequest',
    liveAction
  )
}

const normalizeEzuikitNodeProps = (nodeProps: Record<string, unknown> | null | undefined) => {
  const nextProps: Record<string, unknown> = { ...(nodeProps || {}) }
  delete nextProps.ezopenUrl
  delete nextProps.playbackBegin
  delete nextProps.playbackEnd
  delete nextProps.streamSuffix
  delete nextProps.playbackParamsUrl

  const playbackDefaults = getEzuikitPlaybackDefaults()
  if (!String(nextProps.spaceId ?? '').trim() && playbackDefaults.spaceId) {
    nextProps.spaceId = playbackDefaults.spaceId
  }
  if (!String(nextProps.busType ?? '').trim() && playbackDefaults.busType) {
    nextProps.busType = playbackDefaults.busType
  }

  return nextProps
}

const buildEzuikitBinding = (dataSourceId: string, targetProp: string, fieldId: string) => ({
  targetProp,
  expression: `{{ ds.${dataSourceId}.data.${fieldId} }}`
})

const ensureEzuikitBinding = (
  bindings: ThingsVisFieldBinding[],
  dataSourceId: string,
  targetProp: string,
  fieldId: string
) => {
  if (bindings.some((binding) => binding?.targetProp === targetProp)) return bindings
  return [...bindings, buildEzuikitBinding(dataSourceId, targetProp, fieldId)]
}

const normalizeEzuikitNodeDataBindings = (node: ThingsVisNodeLike, dataSourceId: string) => {
  const data = (Array.isArray(node?.data) ? node.data : []).filter(
    (binding) => !['ezopenUrl', 'playbackParamsUrl', 'spaceId', 'busType'].includes(String(binding?.targetProp))
  )
  const defaultBindings: Array<[string, string]> = [
    ['accessToken', 'ys7_playback_access_token'],
    ['deviceSerial', 'ys7_device_serial'],
    ['channelNo', 'ys7_channel_no']
  ]

  return defaultBindings.reduce((bindings, [targetProp, fieldId]) => {
    return ensureEzuikitBinding(bindings, dataSourceId, targetProp, fieldId)
  }, data)
}

const normalizeEzuikitPlaybackNode = (node: ThingsVisNodeLike, dataSourceId: string) => {
  if (node?.type !== 'media/ezuikit-player') return node

  return {
    ...node,
    props: normalizeEzuikitNodeProps(node.props),
    data: normalizeEzuikitNodeDataBindings(node, dataSourceId),
    events: ensureEzuikitNodeEvents(node, dataSourceId)
  }
}

const ensureEzuikitPlaybackEvents = (config: ThingsVisWidgetConfigLike) => {
  if (!config || !Array.isArray(config.nodes)) return config

  const dataSourceId = resolvePlatformDataSourceId(config)
  if (!dataSourceId) return config

  return {
    ...config,
    nodes: config.nodes.map((node) => normalizeEzuikitPlaybackNode(node, dataSourceId))
  }
}

const chartFontSizeDefaultsForType = (nodeType: unknown): ChartFontSizeConfig | null => {
  if (typeof nodeType !== 'string') return null
  if (CARTESIAN_CHART_TYPES.has(nodeType)) return DEFAULT_CARTESIAN_CHART_FONT_SIZES
  if (PIE_CHART_TYPES.has(nodeType)) return DEFAULT_PIE_CHART_FONT_SIZES
  if (GAUGE_CHART_TYPES.has(nodeType)) return DEFAULT_GAUGE_CHART_FONT_SIZES
  return null
}

const normalizeChartFontSizeNode = (node: ThingsVisNodeLike) => {
  const defaults = chartFontSizeDefaultsForType(node?.type)
  if (!defaults) return node

  const props = node?.props && typeof node.props === 'object' ? node.props : {}
  const existingFontSizes =
    props.fontSizes && typeof props.fontSizes === 'object' && !Array.isArray(props.fontSizes)
      ? props.fontSizes
      : {}

  return {
    ...node,
    props: {
      ...props,
      fontSizes: {
        ...defaults,
        ...existingFontSizes
      }
    }
  }
}

const normalizeModel3DNode = (node: ThingsVisNodeLike) => {
  if (typeof node?.type !== 'string' || !MODEL_3D_TYPES.has(node.type)) return node

  const props = node?.props && typeof node.props === 'object' ? node.props : {}
  const acceptedExtensions = Array.isArray(props.acceptedExtensions)
    ? props.acceptedExtensions
    : DEFAULT_MODEL_3D_PROPS.acceptedExtensions
  const maxUploadSizeMb =
    typeof props.maxUploadSizeMb === 'number' && props.maxUploadSizeMb > 0
      ? props.maxUploadSizeMb
      : DEFAULT_MODEL_3D_PROPS.maxUploadSizeMb

  return {
    ...node,
    props: {
      ...DEFAULT_MODEL_3D_PROPS,
      ...props,
      acceptedExtensions,
      maxUploadSizeMb
    }
  }
}

const normalizeThingsVisRuntimeDefaultNode = (node: ThingsVisNodeLike) =>
  normalizeModel3DNode(normalizeChartFontSizeNode(node))

const ensureChartFontSizeDefaults = (config: ThingsVisWidgetConfigLike) => {
  if (!config || !Array.isArray(config.nodes)) return config

  return {
    ...config,
    nodes: config.nodes.map((node) => normalizeThingsVisRuntimeDefaultNode(node))
  }
}

type PositionedThingsVisNode = ThingsVisNodeLike & {
  x: number
  y: number
  width: number
  height: number
}

const hasPositionedNodeBounds = (node: ThingsVisNodeLike): node is PositionedThingsVisNode => {
  return [node?.x, node?.y, node?.width, node?.height].every((value) => typeof value === 'number')
}

const getPositionedNodeBounds = (nodes: ThingsVisNodeLike[]) => {
  const positionedNodes = nodes.filter(hasPositionedNodeBounds)
  if (positionedNodes.length === 0) return null

  const minX = Math.min(...positionedNodes.map((node) => node.x))
  const minY = Math.min(...positionedNodes.map((node) => node.y))
  const maxX = Math.max(...positionedNodes.map((node) => node.x + node.width))
  const maxY = Math.max(...positionedNodes.map((node) => node.y + node.height))

  return {
    minX,
    minY,
    width: Math.ceil(maxX - minX + VIEWER_INFINITE_CANVAS_PADDING * 2),
    height: Math.ceil(maxY - minY + VIEWER_INFINITE_CANVAS_PADDING * 2)
  }
}

const offsetPositionedNodes = (nodes: ThingsVisNodeLike[], offsetX: number, offsetY: number) => {
  return nodes.map((node) => {
    if ([node?.x, node?.y].every((value) => typeof value === 'number')) {
      return {
        ...node,
        x: (node.x as number) + offsetX,
        y: (node.y as number) + offsetY
      }
    }
    return node
  })
}

const normalizeInfiniteCanvasConfig = (config: ThingsVisWidgetConfigLike) => {
  const canvas = config.canvas || config.canvasConfig
  if (!canvas || canvas.mode !== 'infinite') return config

  const nodes = Array.isArray(config.nodes) ? config.nodes : []
  const bounds = getPositionedNodeBounds(nodes)

  if (!bounds) {
    return {
      ...config,
      canvas: {
        ...canvas,
        scaleMode: canvas.scaleMode || 'fit-min'
      }
    }
  }

  const offsetX = VIEWER_INFINITE_CANVAS_PADDING - bounds.minX
  const offsetY = VIEWER_INFINITE_CANVAS_PADDING - bounds.minY

  return {
    ...config,
    canvas: {
      ...canvas,
      width: Math.max(canvas.width || 0, bounds.width),
      height: Math.max(canvas.height || 0, bounds.height),
      scaleMode: canvas.scaleMode || 'fit-min'
    },
    nodes: offsetPositionedNodes(nodes, offsetX, offsetY)
  }
}

function normalizeViewerConfig(config: ThingsVisWidgetConfigLike, options: NormalizeThingsVisWidgetLoadConfigOptions) {
  if (!config || options.mode !== 'viewer') return config

  const platformNormalizedConfig = normalizeViewerPlatformDataSources(
    ensureChartFontSizeDefaults(ensureEzuikitPlaybackEvents(ensureInteractiveWriteEvents(config, options))),
    options
  )

  return normalizeInfiniteCanvasConfig(platformNormalizedConfig)
}

export function normalizeThingsVisWidgetLoadConfig<T>(config: T, options: NormalizeThingsVisWidgetLoadConfigOptions): T {
  const writeNormalizedConfig = ensureChartFontSizeDefaults(
    ensureInteractiveWriteEvents(ensureEzuikitPlaybackEvents(config as ThingsVisWidgetConfigLike), options)
  )
  return normalizeViewerConfig(writeNormalizedConfig, options) as T
}

/**
 * 文件说明：
 * - 承接 ThingsVisWidget 中历史字段补水相关的配置扫描与时序读取逻辑。
 * - 负责从 widget 配置推导 `__history` 字段需求、判断是否需要 buffer 预填，并统一遥测历史接口返回。
 * 维护提示：
 * - 这里直接影响 widget 首屏时序完整性；调整字段表达式、时间范围或接口归一化规则前要同步核对 guest 绑定协议。
 * - 该模块只负责“历史需求识别 + 历史数据读取”，不负责 `tv:platform-data` 回推。
 */
import type { HistoryRequestConfig } from '@/components/thingsvis/widgetFieldDataBridge'

const FIELD_BINDING_EXPR_GLOBAL_RE = /\{\{\s*ds\.([^.\s]+)\.data(?:\.(.+?))?\s*\}\}/g

const HISTORY_TIME_RANGE_BY_PRESET: Record<string, string> = {
  '1h': 'last_1h',
  '6h': 'last_6h',
  '24h': 'last_24h',
  '7d': 'last_7d',
  '30d': 'last_30d',
  all: 'last_30d'
}
const TELEMETRY_HISTORY_CACHE_TTL_MS = 1000
const TELEMETRY_HISTORY_CACHE_MAX_ENTRIES = 200

type ParsedFieldBinding = {
  dataSourceId: string
  fieldPath: string
}

type TelemetryHistoryRow = {
  value: unknown
  ts: number
}

type TelemetryHistoryCacheEntry = {
  rows: TelemetryHistoryRow[]
  cachedAt: number
}

type ThingsVisWidgetFieldHistoryBridgeOptions = {
  getConfig: () => any
  historyFieldSuffix: string
  templateDeviceId: string
  runtimeStatusFieldIds: Set<string>
  getFieldDataTypeMap: () => Record<string, string>
  getFieldRoot: (fieldPath: string) => string
  parseFieldBindingExpression: (input: unknown) => ParsedFieldBinding | null
  loadTelemetryHistory: (
    params: Record<string, unknown>,
    options?: Record<string, unknown>
  ) => Promise<any>
}

const normalizeTelemetryHistoryRows = (payload: any) => {
  // 历史接口存在多种返回壳结构，这里统一压成 widget 能直接消费的时序点。
  const source = payload?.data !== undefined ? payload.data : payload
  const rows = Array.isArray(source)
    ? source
    : Array.isArray(source?.list)
      ? source.list
      : Array.isArray(source?.data)
        ? source.data
        : []

  return rows
    .map((item: any) => {
      const timestamp = item?.timestamp ?? item?.time ?? item?.ts ?? item?.x
      const value = item?.value ?? item?.y ?? item?.avg
      const ts =
        typeof timestamp === 'number'
          ? timestamp
          : typeof timestamp === 'string'
            ? Date.parse(timestamp)
            : Number(timestamp)
      return { timestamp, ts, value: Number(value) }
    })
    .filter((item: any) => Number.isFinite(item.ts) && Number.isFinite(item.value))
}

const normalizeHistoryTimeRange = (value: unknown) => {
  if (typeof value !== 'string') return 'last_30d'
  if (value.startsWith('last_')) return value
  return HISTORY_TIME_RANGE_BY_PRESET[value] || 'last_30d'
}

const normalizeHistoryConfig = (config?: HistoryRequestConfig): Required<HistoryRequestConfig> => ({
  timeRange: normalizeHistoryTimeRange(config?.timeRange),
  aggFunction: config?.aggFunction || 'NONE_RAW',
  aggWindow: config?.aggWindow || 'no_aggregate'
})

const buildTelemetryHistoryCacheKey = (
  deviceId: string,
  fieldId: string,
  historyConfig: Required<HistoryRequestConfig>
) =>
  [
    deviceId,
    fieldId,
    historyConfig.timeRange,
    historyConfig.aggWindow,
    historyConfig.aggFunction
  ].join('|')

const visitStringLeaves = (value: unknown, visitor: (input: string) => void) => {
  if (typeof value === 'string') {
    visitor(value)
    return
  }

  if (Array.isArray(value)) {
    value.forEach((item) => visitStringLeaves(item, visitor))
    return
  }

  if (value && typeof value === 'object') {
    Object.values(value).forEach((item) => visitStringLeaves(item, visitor))
  }
}

const resolveNodeHistoryTimeRange = (node: any) => {
  return normalizeHistoryTimeRange(node?.props?.timeRangePreset)
}

const mergeHistoryTimeRange = (current: string | undefined, next: string) => {
  const historyTimeRangeWeight: Record<string, number> = {
    last_1h: 1,
    last_6h: 2,
    last_24h: 3,
    last_7d: 4,
    last_30d: 5
  }
  if (!current) return next
  const currentWeight = historyTimeRangeWeight[current] ?? 0
  const nextWeight = historyTimeRangeWeight[next] ?? 0
  return nextWeight > currentWeight ? next : current
}

const registerParsedHistoryBinding = (
  requests: Map<string, string>,
  parsed: ParsedFieldBinding | null,
  dataSourceId: string | undefined,
  timeRange: string,
  getFieldRoot: (fieldPath: string) => string,
  historyFieldSuffix: string
) => {
  if (!parsed || (dataSourceId && parsed.dataSourceId !== dataSourceId)) return

  const fieldRoot = getFieldRoot(parsed.fieldPath)
  if (!fieldRoot.endsWith(historyFieldSuffix)) return

  const sourceFieldId = fieldRoot.slice(0, -historyFieldSuffix.length)
  if (!sourceFieldId) return

  requests.set(sourceFieldId, mergeHistoryTimeRange(requests.get(sourceFieldId), timeRange))
}

const registerNodeHistoryBindings = (
  requests: Map<string, string>,
  node: any,
  dataSourceId: string | undefined,
  options: Pick<
    ThingsVisWidgetFieldHistoryBridgeOptions,
    'parseFieldBindingExpression' | 'getFieldRoot' | 'historyFieldSuffix'
  >
) => {
  const bindings = Array.isArray(node?.data) ? node.data : []

  bindings.forEach((binding: any) => {
    registerParsedHistoryBinding(
      requests,
      options.parseFieldBindingExpression(binding?.expression),
      dataSourceId,
      normalizeHistoryTimeRange(binding?.historyConfig?.timeRange),
      options.getFieldRoot,
      options.historyFieldSuffix
    )
  })
}

const registerNodeHistoryStringLeaves = (
  requests: Map<string, string>,
  node: any,
  dataSourceId: string | undefined,
  options: Pick<ThingsVisWidgetFieldHistoryBridgeOptions, 'getFieldRoot' | 'historyFieldSuffix'>
) => {
  const historyTimeRange = resolveNodeHistoryTimeRange(node)

  visitStringLeaves(node, (input) => {
    FIELD_BINDING_EXPR_GLOBAL_RE.lastIndex = 0

    let match: RegExpExecArray | null
    while ((match = FIELD_BINDING_EXPR_GLOBAL_RE.exec(input)) !== null) {
      if (!match[1] || !match[2]) continue

      registerParsedHistoryBinding(
        requests,
        {
          dataSourceId: match[1],
          fieldPath: match[2]
        },
        dataSourceId,
        historyTimeRange,
        options.getFieldRoot,
        options.historyFieldSuffix
      )
    }
  })
}

const getConfiguredPlatformDataSource = (config: any, dataSourceId?: string) => {
  if (!dataSourceId) return null
  const dataSources = Array.isArray(config?.dataSources) ? config.dataSources : []
  return dataSources.find((dataSource: any) => dataSource?.id === dataSourceId) || null
}

export const createThingsVisWidgetFieldHistoryBridge = (options: ThingsVisWidgetFieldHistoryBridgeOptions) => {
  const telemetryHistoryCache = new Map<string, TelemetryHistoryCacheEntry>()
  const telemetryHistoryInFlight = new Map<string, Promise<TelemetryHistoryRow[]>>()

  const pruneTelemetryHistoryCache = () => {
    if (telemetryHistoryCache.size <= TELEMETRY_HISTORY_CACHE_MAX_ENTRIES) return
    const overflow = telemetryHistoryCache.size - TELEMETRY_HISTORY_CACHE_MAX_ENTRIES
    Array.from(telemetryHistoryCache.keys())
      .slice(0, overflow)
      .forEach((key) => telemetryHistoryCache.delete(key))
  }

  const collectConfiguredHistoryFields = (dataSourceId?: string) => {
    // 同时扫描 data 绑定和节点字符串属性里的历史字段引用。
    const requests = new Map<string, string>()
    const config = options.getConfig()
    const nodes = Array.isArray(config?.nodes) ? config.nodes : []

    nodes.forEach((node: any) => {
      registerNodeHistoryBindings(requests, node, dataSourceId, options)
      registerNodeHistoryStringLeaves(requests, node, dataSourceId, options)
    })

    return requests
  }

  const shouldPrefillHistoryForDataSource = (dataSourceId?: string) => {
    const dataSource = getConfiguredPlatformDataSource(options.getConfig(), dataSourceId)
    const bufferSize = dataSource?.config?.bufferSize
    return typeof bufferSize === 'number' && Number.isFinite(bufferSize) && bufferSize > 0
  }

  const fetchTelemetryHistoryField = async (deviceId: string, fieldId: string, config?: HistoryRequestConfig) => {
    if (!deviceId || deviceId === options.templateDeviceId || !fieldId) return [] as TelemetryHistoryRow[]
    if (options.runtimeStatusFieldIds.has(fieldId)) return [] as TelemetryHistoryRow[]

    const fieldDataTypeMap = options.getFieldDataTypeMap()
    // 非 telemetry 字段没有时序历史，不要误打历史查询接口。
    if (fieldDataTypeMap[fieldId] && fieldDataTypeMap[fieldId] !== 'telemetry') return [] as TelemetryHistoryRow[]

    const historyConfig = normalizeHistoryConfig(config)
    const cacheKey = buildTelemetryHistoryCacheKey(deviceId, fieldId, historyConfig)
    const cached = telemetryHistoryCache.get(cacheKey)
    if (cached && Date.now() - cached.cachedAt <= TELEMETRY_HISTORY_CACHE_TTL_MS) return cached.rows
    const inFlight = telemetryHistoryInFlight.get(cacheKey)
    if (inFlight) return inFlight

    const request = (async () => {
      try {
        const response = await options.loadTelemetryHistory(
          {
            device_id: deviceId,
            key: fieldId,
            time_range: historyConfig.timeRange,
            aggregate_window: historyConfig.aggWindow,
            aggregate_function: historyConfig.aggFunction
          },
          { silentError: true }
        )
        const rows = response?.error ? ([] as TelemetryHistoryRow[]) : normalizeTelemetryHistoryRows(response)
        telemetryHistoryCache.set(cacheKey, { rows, cachedAt: Date.now() })
        pruneTelemetryHistoryCache()
        return rows
      } catch (error) {
        console.warn('[ThingsVisWidget] telemetry history request failed:', fieldId, error)
        return [] as TelemetryHistoryRow[]
      } finally {
        telemetryHistoryInFlight.delete(cacheKey)
      }
    })()

    telemetryHistoryInFlight.set(cacheKey, request)
    return request
  }

  return {
    collectConfiguredHistoryFields,
    shouldPrefillHistoryForDataSource,
    fetchTelemetryHistoryField
  }
}

/**
 * 文件说明：
 * - 承接 ThingsVisWidget 中 `thingsvis:requestFieldData` 的宿主桥接逻辑。
 * - 负责可信消息解析、目标设备约束、字段响应拼装与 `tv:platform-data` 回推前的数据装配。
 * 维护提示：
 * - 这里是 widget guest 拉取平台字段的主入口，任何 payload 兼容、设备绑定或空响应策略调整都要谨慎。
 * - 该模块依赖 `widgetFieldDataBridge.ts` 与历史字段桥提供的能力，本身不直接维护历史扫描或写回逻辑。
 */
import { resolvePlatformFieldReadRequest } from '@/components/thingsvis/fieldReadRequestBridge'
import { parseTrustedGuestMessage } from '@/components/thingsvis/hostBridge'
import {
  buildWidgetFieldDataResponseFields,
  type FieldDataRequestPayload,
  type HistoryRequestConfig,
  type ResolvedFieldDataRequest
} from '@/components/thingsvis/widgetFieldDataBridge'

type TelemetryHistoryRow = {
  value: unknown
  ts: number
}

type ThingsVisWidgetFieldRequestBridgeOptions = {
  isTrustedMessageEvent: (event: MessageEvent) => boolean
  getPreviewDeviceId: () => string | undefined
  historyFieldSuffix: string
  templateDeviceId: string
  alarmStatusFieldIds: Set<string>
  getCurrentData: () => Record<string, unknown> | undefined
  collectConfiguredHistoryFields: (dataSourceId?: string) => Map<string, string>
  shouldPrefillHistoryForDataSource: (dataSourceId?: string) => boolean
  fetchTelemetryHistoryField: (
    deviceId: string,
    fieldId: string,
    config?: HistoryRequestConfig
  ) => Promise<TelemetryHistoryRow[]>
  pushPlatformFieldHistory: (fieldId: string, history: TelemetryHistoryRow[], deviceId?: string) => void
  loadAlarmStatus: (deviceId: string) => Promise<any>
  pushPlatformFieldData: (fields: Record<string, unknown>, deviceId?: string) => void
}

const resolveFieldDataDeviceScope = (
  getPreviewDeviceId: () => string | undefined,
  payload?: FieldDataRequestPayload
) => {
  const previewDeviceId = getPreviewDeviceId()
  if (payload?.deviceId && previewDeviceId && payload.deviceId !== previewDeviceId) return null
  return payload?.deviceId || previewDeviceId
}

const resolveFieldDataRequest = (
  getPreviewDeviceId: () => string | undefined,
  payload?: FieldDataRequestPayload
): ResolvedFieldDataRequest | null => {
  const resolved = resolvePlatformFieldReadRequest({
    payload,
    resolveTargetDeviceId: (currentPayload) => resolveFieldDataDeviceScope(getPreviewDeviceId, currentPayload)
  })
  if (!resolved) return null
  return {
    payload: resolved.payload,
    fieldIds: resolved.fieldIds,
    targetDeviceId: resolved.targetDeviceId
  }
}

const buildFieldDataResponseFields = async (
  request: ResolvedFieldDataRequest,
  options: Omit<
    ThingsVisWidgetFieldRequestBridgeOptions,
    'isTrustedMessageEvent' | 'getPreviewDeviceId' | 'pushPlatformFieldData'
  >
) => {
  // 字段读取既可能返回实时值，也可能顺带补告警派生字段与历史序列。
  return buildWidgetFieldDataResponseFields(request, {
    historyFieldSuffix: options.historyFieldSuffix,
    templateDeviceId: options.templateDeviceId,
    alarmStatusFieldIds: options.alarmStatusFieldIds,
    currentData: options.getCurrentData(),
    collectConfiguredHistoryFields: options.collectConfiguredHistoryFields,
    shouldPrefillHistoryForDataSource: options.shouldPrefillHistoryForDataSource,
    fetchTelemetryHistoryField: options.fetchTelemetryHistoryField,
    pushPlatformFieldHistory: options.pushPlatformFieldHistory,
    loadAlarmStatus: options.loadAlarmStatus
  })
}

export const createThingsVisWidgetFieldRequestHandler = (options: ThingsVisWidgetFieldRequestBridgeOptions) => {
  return async (event: MessageEvent) => {
    const message = parseTrustedGuestMessage<FieldDataRequestPayload>(
      event,
      {
        isTrusted: options.isTrustedMessageEvent
      },
      'thingsvis:requestFieldData'
    )
    if (!message) return

    const request = resolveFieldDataRequest(options.getPreviewDeviceId, message.payload)
    if (!request) return

    const fields = await buildFieldDataResponseFields(request, options)
    if (Object.keys(fields).length === 0) return

    options.pushPlatformFieldData(fields, request.targetDeviceId)
  }
}

/**
 * 文件说明：
 * - 承接 ThingsVisWidget 中 `tv:platform-write` 的宿主桥接逻辑。
 * - 负责可信消息解析、目标设备约束、字段类型归一化后的写入发布，以及写回结果回传。
 * 维护提示：
 * - 这里属于 iframe guest 与 AetherLink 平台 API 的跨系统契约层，`message type` 和回包结构要保持稳定。
 * - 任何新的写入类型都应优先扩展这里，而不是重新塞回 `ThingsVisWidget.vue` 主文件。
 */
import { parseTrustedGuestMessage, type TrustedGuestMessage } from '@/components/thingsvis/hostBridge'

type PlatformWriteMessagePayload = {
  dataSourceId?: string
  data?: unknown
  deviceId?: string
}

type PlatformWriteRequest = {
  requestId?: string
  dataSourceId: string
  data: unknown
  deviceId?: string
}

type PlatformWritePayload = {
  normalizedData: unknown
  fieldId?: string
  fieldType?: string
  valueStr: string
}

type PlatformWritePublishResult = { success: true; result: any } | { success: false; error: string }

type PostGuestMessage = (message: Record<string, unknown>) => void

type PlatformWriteBridgeOptions = {
  isTrustedMessageEvent: (event: MessageEvent) => boolean
  postMessageToGuest: PostGuestMessage
  getPreviewDeviceId: () => string | undefined
  getFieldDataTypeMap: () => Record<string, string>
  normalizeWriteData: (dataSourceId: string, data: unknown) => unknown
  publishAttributeData: (payload: { device_id: string; value: string }) => Promise<any>
  publishCommandData: (payload: { device_id: string; identify: string; value: string }) => Promise<any>
  publishTelemetryData: (payload: { device_id: string; value: string }) => Promise<any>
}

type TrustedThingsVisWidgetMessage<TPayload extends Record<string, unknown> = Record<string, unknown>> =
  TrustedGuestMessage<TPayload>

const postPlatformWriteResult = (
  requestId: string | undefined,
  payload: Record<string, unknown>,
  postMessageToGuest: PostGuestMessage
) => {
  if (!requestId) return

  postMessageToGuest({
    type: 'tv:platform-write-result',
    requestId,
    ...payload
  })
}

const postPlatformWriteSuccess = (
  requestId: string | undefined,
  echo: unknown,
  postMessageToGuest: PostGuestMessage
) => {
  postPlatformWriteResult(
    requestId,
    {
      success: true,
      echo
    },
    postMessageToGuest
  )
}

const postPlatformWriteError = (
  requestId: string | undefined,
  error: string,
  postMessageToGuest: PostGuestMessage
) => {
  postPlatformWriteResult(
    requestId,
    {
      success: false,
      error
    },
    postMessageToGuest
  )
}

const resolveWritableDeviceId = (
  getPreviewDeviceId: () => string | undefined,
  requestedDeviceId?: string
) => {
  const previewDeviceId = getPreviewDeviceId()
  const normalizedRequestedDeviceId = typeof requestedDeviceId === 'string' ? requestedDeviceId.trim() : ''

  if (!previewDeviceId) {
    return { error: 'Missing deviceId' } as const
  }

  if (normalizedRequestedDeviceId && normalizedRequestedDeviceId !== previewDeviceId) {
    return { error: 'Device mismatch' } as const
  }

  return { deviceId: previewDeviceId } as const
}

const normalizePlatformWriteRequest = (
  message: TrustedThingsVisWidgetMessage<PlatformWriteMessagePayload>
): PlatformWriteRequest | { requestId?: string; error: string } => {
  const { requestId, payload: writePayload } = message
  const { dataSourceId, data, deviceId } = writePayload ?? {}

  if (!dataSourceId || data === undefined) {
    return {
      requestId,
      error: 'Missing dataSourceId or data'
    }
  }

  return {
    requestId,
    dataSourceId,
    data,
    deviceId
  }
}

const resolveCommandWrite = (data: unknown, fieldId?: string): { identify: string; value: string } | null => {
  if (!fieldId || data === null || typeof data !== 'object' || Array.isArray(data)) return null
  const params = (data as Record<string, unknown>)[fieldId]
  return {
    identify: fieldId,
    value: JSON.stringify(params ?? {})
  }
}

const buildPlatformWritePayload = (
  dataSourceId: string,
  data: unknown,
  getFieldDataTypeMap: () => Record<string, string>,
  normalizeWriteData: (dataSourceId: string, data: unknown) => unknown
): PlatformWritePayload => {
  const normalizedData = normalizeWriteData(dataSourceId, data)
  const dataObject =
    normalizedData !== null && typeof normalizedData === 'object' ? (normalizedData as Record<string, unknown>) : null
  const fieldEntries = dataObject ? Object.entries(dataObject) : []
  const fieldId = fieldEntries.length === 1 ? fieldEntries[0]?.[0] : undefined
  const fieldTypeMap = getFieldDataTypeMap()
  const fieldType = fieldId ? fieldTypeMap[fieldId] : undefined
  // 平台写接口最终都吃字符串，因此这里统一完成序列化。
  const valueStr = typeof normalizedData === 'string' ? normalizedData : JSON.stringify(normalizedData)

  return {
    normalizedData,
    fieldId,
    fieldType,
    valueStr
  }
}

const publishPlatformWrite = async (
  deviceId: string,
  payload: PlatformWritePayload,
  options: Pick<
    PlatformWriteBridgeOptions,
    'publishAttributeData' | 'publishCommandData' | 'publishTelemetryData'
  >
): Promise<PlatformWritePublishResult> => {
  if (payload.fieldType === 'attribute') {
    return {
      success: true,
      result: await options.publishAttributeData({ device_id: deviceId, value: payload.valueStr })
    }
  }

  if (payload.fieldType === 'command') {
    const commandWrite = resolveCommandWrite(payload.normalizedData, payload.fieldId)
    if (!commandWrite) {
      return {
        success: false,
        error: 'Command write requires a single command field payload'
      }
    }

    return {
      success: true,
      result: await options.publishCommandData({
        device_id: deviceId,
        identify: commandWrite.identify,
        value: commandWrite.value
      })
    }
  }

  return {
    success: true,
    result: await options.publishTelemetryData({ device_id: deviceId, value: payload.valueStr })
  }
}

export const createThingsVisWidgetPlatformWriteHandler = (options: PlatformWriteBridgeOptions) => {
  return async (event: MessageEvent) => {
    const message = parseTrustedGuestMessage<PlatformWriteMessagePayload>(
      event,
      {
        isTrusted: options.isTrustedMessageEvent
      },
      'tv:platform-write'
    )
    if (!message) return

    const request = normalizePlatformWriteRequest(message)
    if ('error' in request) {
      postPlatformWriteError(request.requestId, request.error, options.postMessageToGuest)
      return
    }

    // 写回请求只允许命中当前 widget 绑定的设备，避免 guest 越权写别的设备。
    const targetDevice = resolveWritableDeviceId(options.getPreviewDeviceId, request.deviceId)
    if ('error' in targetDevice) {
      if (targetDevice.error === 'Missing deviceId') {
        console.warn('[ThingsVisWidget] tv:platform-write received but deviceId prop is not set')
      }
      postPlatformWriteError(request.requestId, targetDevice.error as string, options.postMessageToGuest)
      return
    }

    try {
      const writePayload = buildPlatformWritePayload(
        request.dataSourceId,
        request.data,
        options.getFieldDataTypeMap,
        options.normalizeWriteData
      )
      const published = await publishPlatformWrite(targetDevice.deviceId, writePayload, options)
      if (!published.success) {
        postPlatformWriteError(request.requestId, published.error, options.postMessageToGuest)
        return
      }

      postPlatformWriteSuccess(
        request.requestId,
        published.result?.data ?? writePayload.normalizedData,
        options.postMessageToGuest
      )
    } catch (error) {
      console.error('[ThingsVisWidget] telemetryDataPub failed for tv:platform-write:', error)
      const message = error instanceof Error ? error.message : String(error || 'Platform write failed')
      postPlatformWriteError(request.requestId, message, options.postMessageToGuest)
    }
  }
}

import {
  THINGSVIS_COMPAT_PROVIDER,
  getPlatformApiBase,
  getThingsVisApiBase
} from '@/utils/thingsvis/constants'
import { localStg } from '@/utils/storage'
import { THINGSVIS_WIDGET_RUNTIME_CAPABILITIES } from './thingsvisWidgetRuntimeCapabilities'

export const THINGSVIS_WIDGET_TEMPLATE_DEVICE_ID = '__template__'

type ThingsVisWidgetMode = 'viewer' | 'editor'
type ThingsVisEmbeddedContext = 'device-template' | 'current-device' | 'dashboard'

type ThingsVisWidgetRuntimeContractOptions = {
  getDeviceId: () => string | undefined
  getMode: () => ThingsVisWidgetMode | undefined
  getBufferSize: () => number | undefined
  getPlatformFields: () => any[] | undefined
  getPlatformDevices: () => any[] | undefined
  cloneValue: <T>(value: T) => T
}

export function createThingsVisWidgetRuntimeContract(options: ThingsVisWidgetRuntimeContractOptions) {
  const getPreviewDeviceId = () => {
    const deviceId = options.getDeviceId()
    if (typeof deviceId === 'string' && deviceId.trim()) return deviceId

    const platformDevices = options.getPlatformDevices()
    if (platformDevices?.length === 1) {
      const platformDeviceId = platformDevices[0]?.deviceId
      if (typeof platformDeviceId === 'string' && platformDeviceId.trim()) return platformDeviceId
    }

    return undefined
  }

  const getEmbeddedContext = (): ThingsVisEmbeddedContext => {
    if (options.getDeviceId() === THINGSVIS_WIDGET_TEMPLATE_DEVICE_ID) return 'device-template'
    if (getPreviewDeviceId()) return 'current-device'
    return 'dashboard'
  }

  const buildWidgetUrl = (baseUrl: string, token: string) => {
    const route = options.getMode() === 'editor' ? 'editor' : 'embed'
    const tokenParams = token ? `&token=${encodeURIComponent(token)}` : ''
    const embeddedContext = encodeURIComponent(getEmbeddedContext())
    const thingsvisApiBaseUrl = encodeURIComponent(getThingsVisApiBase())
    const platformApiBaseUrl = encodeURIComponent(getPlatformApiBase())

    // saveTarget=host and provider are fixed host/guest runtime handshake params.
    return `${baseUrl}#/${route}?mode=embedded&provider=${THINGSVIS_COMPAT_PROVIDER}&saveTarget=host${tokenParams}&context=${embeddedContext}&thingsvisApiBaseUrl=${thingsvisApiBaseUrl}&platformApiBaseUrl=${platformApiBaseUrl}`
  }

  const getPlatformDevices = () => {
    const platformDevices = options.getPlatformDevices()
    if (Array.isArray(platformDevices) && platformDevices.length > 0) return options.cloneValue(platformDevices)
    if (getEmbeddedContext() !== 'device-template') return []

    return [
      {
        deviceId: THINGSVIS_WIDGET_TEMPLATE_DEVICE_ID,
        deviceName: 'thing-model-fields',
        groupId: THINGSVIS_WIDGET_TEMPLATE_DEVICE_ID,
        groupName: 'thing-model-fields',
        fields: options.cloneValue(options.getPlatformFields() || [])
      }
    ]
  }

  const getPlatformFieldStringMap = (property: 'dataType' | 'type') => {
    return (options.getPlatformFields() || []).reduce<Record<string, string>>((acc, field) => {
      const fieldId = typeof field?.id === 'string' ? field.id : ''
      if (fieldId) {
        acc[fieldId] = typeof field?.[property] === 'string' ? field[property] : ''
      }
      return acc
    }, {})
  }

  const getFieldValueTypeMap = () => getPlatformFieldStringMap('type')
  const getFieldDataTypeMap = () => getPlatformFieldStringMap('dataType')

  const getLoadOptions = () => ({
    platformBufferSize: options.getBufferSize() ?? 0,
    platformDevices: getPlatformDevices(),
    deviceId: options.getDeviceId() || getPreviewDeviceId(),
    thingsvisApiBaseUrl: getThingsVisApiBase(),
    platformApiBaseUrl: getPlatformApiBase(),
    platformToken: localStg.get('token') as string | undefined,
    runtimeCapabilities: options.cloneValue(THINGSVIS_WIDGET_RUNTIME_CAPABILITIES)
  })

  return {
    getPreviewDeviceId,
    getEmbeddedContext,
    buildWidgetUrl,
    getPlatformDevices,
    getPlatformFieldStringMap,
    getFieldValueTypeMap,
    getFieldDataTypeMap,
    getLoadOptions
  }
}

/**
 * 文件说明：
 * - 承接 ThingsVisWidget 中平台字段写入前的字段推断与类型归一化逻辑。
 * - 负责从 widget config 反推 dataSource -> field 绑定，并将 guest 写入值按平台字段类型整理。
 * 维护提示：
 * - 这里只处理纯数据归一化，不负责消息可信校验、平台 API 发布或 guest 回包。
 * - 自动写回字段的推断依赖 ThingsVis 节点 value 绑定与 requestedFields 约定，修改前要先确认 guest 契约。
 */

type ParsedThingsVisFieldBinding = {
  dataSourceId: string
  fieldPath: string
}

type CreateThingsVisWidgetWriteNormalizerOptions = {
  getConfig: () => any
  historyFieldSuffix: string
  getFieldValueTypeMap: () => Record<string, string>
  parseFieldBindingExpression: (expression: unknown) => ParsedThingsVisFieldBinding | null
}

const collectConfiguredWriteFields = ({
  getConfig,
  parseFieldBindingExpression
}: Pick<CreateThingsVisWidgetWriteNormalizerOptions, 'getConfig' | 'parseFieldBindingExpression'>) => {
  const fieldIdsByDataSourceId = new Map<string, Set<string>>()
  const config = getConfig()
  const nodes = Array.isArray(config?.nodes) ? config.nodes : []

  nodes.forEach((node: any) => {
    const bindings = Array.isArray(node?.data) ? node.data : []
    const valueBinding = bindings.find((binding: any) => binding?.targetProp === 'value')
    const parsed =
      parseFieldBindingExpression(valueBinding?.expression) || parseFieldBindingExpression(node?.props?.value)

    if (!parsed) return

    const fieldSet = fieldIdsByDataSourceId.get(parsed.dataSourceId) || new Set<string>()
    fieldSet.add(parsed.fieldPath)
    fieldIdsByDataSourceId.set(parsed.dataSourceId, fieldSet)
  })

  const dataSources = Array.isArray(config?.dataSources) ? config.dataSources : []
  dataSources.forEach((dataSource: any) => {
    const dataSourceId = typeof dataSource?.id === 'string' ? dataSource.id : ''
    if (!dataSourceId) return

    const configuredFields = Array.isArray(dataSource?.config?.requestedFields)
      ? dataSource.config.requestedFields.filter(
          (fieldId: unknown): fieldId is string => typeof fieldId === 'string' && !!fieldId
        )
      : []

    if (configuredFields.length !== 1) return

    const fieldSet = fieldIdsByDataSourceId.get(dataSourceId) || new Set<string>()
    fieldSet.add(configuredFields[0]!)
    fieldIdsByDataSourceId.set(dataSourceId, fieldSet)
  })

  return fieldIdsByDataSourceId
}

const normalizeBooleanValue = (value: unknown) => {
  if (typeof value === 'boolean') return value
  if (value === 'true' || value === '1' || value === 1) return true
  if (value === 'false' || value === '0' || value === 0) return false
  return value
}

const normalizeNumberValue = (value: unknown) => {
  if (typeof value === 'boolean') return value ? 1 : 0
  if (typeof value === 'number') return Number.isFinite(value) ? value : value
  if (typeof value === 'string' && value.trim()) {
    const parsed = Number(value)
    if (Number.isFinite(parsed)) return parsed
  }
  return value
}

export const createThingsVisWidgetWriteNormalizer = ({
  getConfig,
  historyFieldSuffix,
  getFieldValueTypeMap,
  parseFieldBindingExpression
}: CreateThingsVisWidgetWriteNormalizerOptions) => {
  const normalizeFieldWriteValue = (fieldId: string, value: unknown) => {
    const fieldValueType = getFieldValueTypeMap()[fieldId]
    if (!fieldValueType) return value

    if (fieldValueType === 'boolean') return normalizeBooleanValue(value)
    if (fieldValueType === 'number') return normalizeNumberValue(value)
    return value
  }

  const normalizeWriteDataObject = (data: Record<string, unknown>) => {
    return Object.entries(data).reduce<Record<string, unknown>>((acc, [fieldId, value]) => {
      acc[fieldId] = normalizeFieldWriteValue(fieldId, value)
      return acc
    }, {})
  }

  const normalizeSingleFieldWriteData = (dataSourceId: string, data: unknown) => {
    const configuredFields = collectConfiguredWriteFields({
      getConfig,
      parseFieldBindingExpression
    }).get(dataSourceId)
    const writableFields = Array.from(configuredFields || []).filter((fieldId) => !fieldId.endsWith(historyFieldSuffix))
    if (writableFields.length !== 1) return data

    const fieldId = writableFields[0]
    if (!fieldId) return data

    return {
      [fieldId]: normalizeFieldWriteValue(fieldId, data)
    }
  }

  return (dataSourceId: string, data: unknown) => {
    if (data !== null && typeof data === 'object') {
      return normalizeWriteDataObject(data as Record<string, unknown>)
    }

    return normalizeSingleFieldWriteData(dataSourceId, data)
  }
}

/**
 * 文件说明：
 * - ThingsVis 字段读取桥接里的“响应拼装层”。
 * - 负责把 guest 请求拆成实时值、告警派生字段、历史序列三部分并合并返回。
 * - 这里的策略会直接影响 widget 首屏数据完整性，是嵌入体验的关键稳定点。
 */
import { classifyRequestedFieldIds, type RequestedFieldGroups } from '@/components/thingsvis/fieldReadBridge'

const HISTORY_TIME_RANGE_WEIGHT: Record<string, number> = {
  last_1h: 1,
  last_6h: 2,
  last_24h: 3,
  last_7d: 4,
  last_30d: 5
}
const DEFAULT_HISTORY_FETCH_CONCURRENCY = 4
const DEFAULT_PREFILL_HISTORY_FIELD_LIMIT = 8

export type HistoryRequestConfig = {
  timeRange?: string
  aggFunction?: string
  aggWindow?: string
}

export type FieldDataRequestPayload = {
  dataSourceId?: string
  deviceId?: string
  fieldIds?: string[]
  historyConfig?: HistoryRequestConfig
}

export type ResolvedFieldDataRequest = {
  payload: FieldDataRequestPayload | undefined
  fieldIds: string[]
  targetDeviceId: string | undefined
}

type TelemetryHistoryRow = {
  value: unknown
  ts: number
}

type FieldDataBridgeOptions = {
  historyFieldSuffix: string
  templateDeviceId: string
  alarmStatusFieldIds: Set<string>
  currentData?: Record<string, unknown>
  collectConfiguredHistoryFields: (dataSourceId?: string) => Map<string, string>
  shouldPrefillHistoryForDataSource: (dataSourceId?: string) => boolean
  fetchTelemetryHistoryField: (
    deviceId: string,
    fieldId: string,
    config?: HistoryRequestConfig
  ) => Promise<TelemetryHistoryRow[]>
  pushPlatformFieldHistory: (fieldId: string, history: TelemetryHistoryRow[], deviceId?: string) => void
  loadAlarmStatus: (deviceId: string) => Promise<any>
}

const mergeHistoryTimeRange = (current: string | undefined, next: string) => {
  // 同一字段被多个节点请求时，选择覆盖范围更大的时间窗口，避免数据不足。
  if (!current) return next
  const currentWeight = HISTORY_TIME_RANGE_WEIGHT[current] ?? 0
  const nextWeight = HISTORY_TIME_RANGE_WEIGHT[next] ?? 0
  return nextWeight > currentWeight ? next : current
}

const registerHistoryTimeRange = (requests: Map<string, string | undefined>, fieldId: string, timeRange?: string) => {
  const current = requests.get(fieldId)
  if (!timeRange) {
    if (!requests.has(fieldId)) requests.set(fieldId, current)
    return
  }

  requests.set(fieldId, mergeHistoryTimeRange(current, timeRange))
}

const buildRequestedFieldData = (
  fieldIds: string[],
  currentData: Record<string, unknown> | undefined,
  historyFieldSuffix: string
) => {
  if (!fieldIds.length) return {}

  const result: Record<string, unknown> = {}
  fieldIds.forEach((fieldId) => {
    // __history 字段由历史查询通道处理，这里只负责当前值。
    if (fieldId.endsWith(historyFieldSuffix)) return
    if (currentData && Object.prototype.hasOwnProperty.call(currentData, fieldId)) {
      result[fieldId] = currentData[fieldId]
    }
  })

  return result
}

const normalizeAlarmLevel = (raw: unknown) => {
  const value = String(raw ?? '')
    .toLowerCase()
    .trim()
  if (value === '1' || value === 'critical' || value === 'high' || value === 'serious') return 'critical'
  if (value === '2' || value === 'warning' || value === 'medium' || value === 'warn') return 'warning'
  if (value === '3' || value === 'info' || value === 'low') return 'info'
  return value || ''
}

const alarmLevelRank = (row: any) => {
  switch (normalizeAlarmLevel(row?.alarm_level ?? row?.level)) {
    case 'critical':
      return 3
    case 'warning':
      return 2
    case 'info':
      return 1
    default:
      return 0
  }
}

const normalizeAlarmTime = (row: any) =>
  row?.last_trigger_time ?? row?.create_time ?? row?.created_at ?? row?.time ?? ''

const getRequestedAlarmStatusFields = (fieldIds: string[], alarmStatusFieldIds: Set<string>) => {
  return fieldIds.filter((fieldId) => alarmStatusFieldIds.has(fieldId))
}

const normalizeAlarmStatusPayload = (response: any) => response?.data ?? response

const getAlarmStatusRows = (payload: any) => {
  if (Array.isArray(payload?.list)) return payload.list
  if (Array.isArray(payload?.data)) return payload.data
  if (Array.isArray(payload)) return payload
  return []
}

const pickHighestAlarmRow = (activeRows: any[], fallback: any) => {
  return (
    activeRows.reduce<any | null>(
      (current, row) => (!current || alarmLevelRank(row) > alarmLevelRank(current) ? row : current),
      null
    ) ?? fallback
  )
}

const buildAlarmStatusFields = (payload: any, rows: any[]) => {
  const activeRows = rows.filter((row) => {
    const raw = String(row?.alarm_status ?? row?.status ?? row?.is_active ?? '').toLowerCase()
    return row?.is_active === true || raw === '1' || raw === 'active' || raw === 'triggered' || raw === 'a'
  })
  const latest = rows[0] ?? null
  const highest = pickHighestAlarmRow(activeRows, latest)

  return {
    device_alarm_active: activeRows.length > 0 ? 1 : 0,
    device_alarm_count: Number(payload?.total ?? activeRows.length ?? 0),
    device_alarm_highest_level: normalizeAlarmLevel(highest?.alarm_level ?? highest?.level),
    latest_device_alarm_title: String(latest?.alarm_name ?? latest?.name ?? latest?.title ?? ''),
    latest_device_alarm_level: normalizeAlarmLevel(latest?.alarm_level ?? latest?.level),
    latest_device_alarm_time: latest ? normalizeAlarmTime(latest) : ''
  } as Record<string, unknown>
}

const pickRequestedFieldValues = (fieldValues: Record<string, unknown>, requestedFields: string[]) => {
  return requestedFields.reduce<Record<string, unknown>>((acc, fieldId) => {
    acc[fieldId] = fieldValues[fieldId]
    return acc
  }, {})
}

const buildRequestedAlarmStatusData = async (
  fieldIds: string[],
  deviceId: string | undefined,
  options: Pick<FieldDataBridgeOptions, 'alarmStatusFieldIds' | 'templateDeviceId' | 'loadAlarmStatus'>
) => {
  const requestedAlarmFields = getRequestedAlarmStatusFields(fieldIds, options.alarmStatusFieldIds)
  // 模板设备与空设备上下文没有真实告警数据，直接跳过。
  if (!deviceId || deviceId === options.templateDeviceId || requestedAlarmFields.length === 0) return {}

  try {
    const response = await options.loadAlarmStatus(deviceId)
    const payload = normalizeAlarmStatusPayload(response)
    const rows = getAlarmStatusRows(payload)
    return pickRequestedFieldValues(buildAlarmStatusFields(payload, rows), requestedAlarmFields)
  } catch (error) {
    console.warn('[ThingsVisWidget] device alarm status request failed:', deviceId, error)
    return {}
  }
}

const registerExplicitHistoryRequests = (historyRequests: Map<string, string | undefined>, fieldIds: Set<string>) => {
  fieldIds.forEach((fieldId) => registerHistoryTimeRange(historyRequests, fieldId))
}

const registerPrefillHistoryRequests = (
  historyRequests: Map<string, string | undefined>,
  payload: FieldDataRequestPayload | undefined,
  fieldGroups: RequestedFieldGroups,
  configuredHistoryFields: Map<string, string>,
  shouldPrefillHistoryForDataSource: (dataSourceId?: string) => boolean
) => {
  if (!shouldPrefillHistoryForDataSource(payload?.dataSourceId)) return

  // 开启 buffer 预填时，即使 guest 没显式请求 __history，也会为相关当前值补一份历史序列。
  const historyBoundFieldIds = new Set<string>([
    ...fieldGroups.explicitHistorySourceFieldIds,
    ...Array.from(configuredHistoryFields.keys())
  ])
  const prefillFieldIds =
    historyBoundFieldIds.size > 0
      ? fieldGroups.currentFieldIds.filter((fieldId) => historyBoundFieldIds.has(fieldId))
      : fieldGroups.currentFieldIds

  prefillFieldIds.slice(0, DEFAULT_PREFILL_HISTORY_FIELD_LIMIT).forEach((fieldId) => {
    registerHistoryTimeRange(historyRequests, fieldId)
  })
}

const buildHistoryRequests = (
  payload: FieldDataRequestPayload | undefined,
  fieldGroups: RequestedFieldGroups,
  options: Pick<FieldDataBridgeOptions, 'collectConfiguredHistoryFields' | 'shouldPrefillHistoryForDataSource'>
) => {
  const historyRequests = new Map<string, string | undefined>()
  const configuredHistoryFields = options.collectConfiguredHistoryFields(payload?.dataSourceId)

  registerExplicitHistoryRequests(historyRequests, fieldGroups.explicitHistorySourceFieldIds)
  registerPrefillHistoryRequests(
    historyRequests,
    payload,
    fieldGroups,
    configuredHistoryFields,
    options.shouldPrefillHistoryForDataSource
  )
  configuredHistoryFields.forEach((timeRange, fieldId) => {
    registerHistoryTimeRange(historyRequests, fieldId, timeRange)
  })

  return historyRequests
}

const buildRequestedCurrentFieldPayload = async (
  fieldIds: string[],
  deviceId: string | undefined,
  options: FieldDataBridgeOptions
) => ({
  ...buildRequestedFieldData(fieldIds, options.currentData, options.historyFieldSuffix),
  ...(await buildRequestedAlarmStatusData(fieldIds, deviceId, options))
})

const mapWithConcurrency = async <T, R>(items: T[], concurrency: number, mapper: (item: T) => Promise<R>) => {
  const results: R[] = new Array(items.length)
  let nextIndex = 0
  const workerCount = Math.min(Math.max(concurrency, 1), items.length)

  await Promise.all(
    Array.from({ length: workerCount }, async () => {
      while (nextIndex < items.length) {
        const currentIndex = nextIndex
        nextIndex += 1
        results[currentIndex] = await mapper(items[currentIndex])
      }
    })
  )

  return results
}

const pushRequestedHistoryFields = async (
  request: ResolvedFieldDataRequest,
  historyRequests: Map<string, string | undefined>,
  fields: Record<string, unknown>,
  explicitHistoryFieldIds: string[],
  options: Pick<FieldDataBridgeOptions, 'historyFieldSuffix' | 'fetchTelemetryHistoryField' | 'pushPlatformFieldHistory'>
) => {
  if (historyRequests.size === 0 || !request.targetDeviceId) return

  // 历史数据除了用于即时响应，也会主动推回 widget 的平台历史缓存。
  const historyEntries = await mapWithConcurrency(
    Array.from(historyRequests.entries()),
    DEFAULT_HISTORY_FETCH_CONCURRENCY,
    async ([fieldId, timeRange]) => {
      const rows = await options.fetchTelemetryHistoryField(request.targetDeviceId!, fieldId, {
        ...(request.payload?.historyConfig || {}),
        timeRange: request.payload?.historyConfig?.timeRange || timeRange || 'last_30d'
      })
      return [fieldId, rows] as const
    }
  )

  historyEntries.forEach(([fieldId, rows]) => {
    if (rows.length > 0) {
      options.pushPlatformFieldHistory(fieldId, rows, request.targetDeviceId)
    }
    if (explicitHistoryFieldIds.includes(`${fieldId}${options.historyFieldSuffix}`)) {
      fields[`${fieldId}${options.historyFieldSuffix}`] = rows
    }
  })
}

export async function buildWidgetFieldDataResponseFields(
  request: ResolvedFieldDataRequest,
  options: FieldDataBridgeOptions
) {
  const fieldGroups = classifyRequestedFieldIds(request.fieldIds, options.historyFieldSuffix)
  const historyRequests = buildHistoryRequests(request.payload, fieldGroups, options)
  const fields = await buildRequestedCurrentFieldPayload(fieldGroups.currentFieldIds, request.targetDeviceId, options)

  await pushRequestedHistoryFields(
    request,
    historyRequests,
    fields,
    fieldGroups.explicitHistoryFieldIds,
    options
  )

  return fields
}

import { describe, expect, it } from 'vitest'
import type { ConfigurationIntegrationBridge } from './ConfigurationIntegrationBridge'
import { configurationIntegrationBridge } from './ConfigurationIntegrationBridge'

const createComponentId = (name: string) => `configuration-bridge-test-${name}`

describe('ConfigurationIntegrationBridge', () => {
  it('distinguishes an uninitialized component from an initialized default configuration', () => {
    const componentId = createComponentId('initialize')

    expect(configurationIntegrationBridge.getConfiguration(componentId)).toBeNull()
    expect(configurationIntegrationBridge.initializeConfiguration(componentId, {
      base: { title: 'Local widget' },
      customize: { metric: 'temperature' }
    })).toEqual({
      base: { title: 'Local widget' },
      component: {},
      dataSource: null,
      interaction: {},
      metadata: {},
      customize: { metric: 'temperature' }
    })
  })

  it('keeps existing initialization and merges section updates', () => {
    const componentId = createComponentId('merge')

    configurationIntegrationBridge.initializeConfiguration(componentId, {
      base: { title: 'Original' },
      customize: { metric: 'temperature' }
    })
    expect(configurationIntegrationBridge.initializeConfiguration(componentId, {
      base: { title: 'Ignored reinitialization' }
    })).toMatchObject({ base: { title: 'Original' } })

    const result = configurationIntegrationBridge.updateConfiguration(componentId, 'customize', {
      unit: '°C'
    })

    expect(result).toEqual({ success: true, persisted: false, scope: 'runtime' })
    expect(configurationIntegrationBridge.getConfiguration(componentId)?.customize).toEqual({
      metric: 'temperature',
      unit: '°C'
    })
  })

  it('replaces a configuration locally without claiming durable persistence', () => {
    const componentId = createComponentId('replace')

    const result = configurationIntegrationBridge.setConfiguration(componentId, {
      component: { properties: { color: 'blue' } }
    })

    expect(result).toEqual({ success: true, persisted: false, scope: 'runtime' })
    expect(configurationIntegrationBridge.getConfiguration(componentId)).toEqual({
      base: {},
      component: { properties: { color: 'blue' } },
      dataSource: null,
      interaction: {},
      metadata: {},
      customize: {}
    })
  })

  it('preserves the exported class contract for compatibility adapters', () => {
    const bridge: ConfigurationIntegrationBridge = configurationIntegrationBridge
    expect(bridge).toBe(configurationIntegrationBridge)
  })
})

/**
 * 文件用途: visual-editor 运行时配置集成桥。
 * 核心逻辑: 按组件 ID 初始化、读取、设置和局部更新 WidgetConfiguration，供 data-architecture 运行时读取。
 * 关键注意事项: 该桥仅保存当前页面进程内状态；写入成功不代表 dashboard 或 localStorage 已持久化。
 * 重构建议: dashboard 装载链路稳定后，将其收敛为统一配置 store 的兼容适配器。
 */
import type { ConfigurationUpdateResult, WidgetConfiguration } from './types'

interface RuntimeConfigurationUpdateResult extends ConfigurationUpdateResult {
  persisted: false
  scope: 'runtime'
}

class ConfigurationIntegrationBridge {
  private readonly configurations = new Map<string, WidgetConfiguration>()

  async initialize() {
    return true
  }

  initializeConfiguration(componentId: string, initialConfig: WidgetConfiguration = {}): WidgetConfiguration {
    const existing = this.configurations.get(componentId)
    if (existing) {
      return existing
    }

    const initialized = this.createDefaultConfiguration(initialConfig)
    this.configurations.set(componentId, initialized)
    return initialized
  }

  getConfiguration(componentId: string): WidgetConfiguration | null {
    return this.configurations.get(componentId) || null
  }

  setConfiguration(componentId: string, config: WidgetConfiguration): RuntimeConfigurationUpdateResult {
    this.configurations.set(componentId, this.createDefaultConfiguration(config))
    return this.createRuntimeUpdateResult()
  }

  updateConfiguration(
    componentId: string,
    sectionOrConfig: string | WidgetConfiguration,
    value?: Record<string, any>
  ): RuntimeConfigurationUpdateResult {
    const current = this.getConfiguration(componentId) || this.createDefaultConfiguration()
    if (typeof sectionOrConfig === 'string') {
      this.configurations.set(componentId, {
        ...current,
        [sectionOrConfig]: {
          ...(current[sectionOrConfig] || {}),
          ...(value || {})
        }
      })
    } else {
      this.configurations.set(componentId, this.createDefaultConfiguration({ ...current, ...sectionOrConfig }))
    }
    return this.createRuntimeUpdateResult()
  }

  private createRuntimeUpdateResult(): RuntimeConfigurationUpdateResult {
    return { success: true, persisted: false, scope: 'runtime' }
  }

  private createDefaultConfiguration(config: WidgetConfiguration = {}): WidgetConfiguration {
    return {
      base: {},
      component: {},
      dataSource: null,
      interaction: {},
      metadata: {},
      customize: {},
      ...config
    }
  }
}

export const configurationIntegrationBridge = new ConfigurationIntegrationBridge()
export type { ConfigurationIntegrationBridge }

