import type { ComponentDataStorage, DataStorageItem } from './DataWarehouse'

interface ComponentCacheStoreOptions {
  getDefaultCacheExpiry: () => number
  calculateDataSize: (data: any) => number
  isExpired: (item: DataStorageItem) => boolean
}

interface ValidComponentDataCollection {
  data: Record<string, any>
  hasData: boolean
}

export class ComponentCacheStore {
  constructor(
    private readonly componentStorage: Map<string, ComponentDataStorage>,
    private readonly options: ComponentCacheStoreOptions
  ) {}

  getOrCreateComponentStorage(componentId: string, now: number): ComponentDataStorage {
    let componentStorage = this.componentStorage.get(componentId)
    if (!componentStorage) {
      componentStorage = {
        componentId,
        dataSources: new Map(),
        createdAt: now,
        updatedAt: now
      }
      this.componentStorage.set(componentId, componentStorage)
    }
    return componentStorage
  }

  createStorageItem(
    componentId: string,
    sourceId: string,
    data: any,
    sourceType: string,
    dataSize: number,
    dataVersion: string,
    executionId: string,
    customExpiry: number | undefined,
    now: number
  ): DataStorageItem {
    return {
      data,
      timestamp: now,
      expiresAt: customExpiry ? now + customExpiry : now + this.options.getDefaultCacheExpiry(),
      source: {
        sourceId,
        sourceType,
        componentId
      },
      size: dataSize,
      accessCount: 0,
      lastAccessed: now,
      dataVersion,
      executionId
    }
  }

  writeDataSourceItem(
    componentStorage: ComponentDataStorage,
    sourceId: string,
    storageItem: DataStorageItem,
    now: number
  ): void {
    componentStorage.dataSources.set(sourceId, storageItem)
    componentStorage.updatedAt = now
    this.invalidateMergedData(componentStorage)
  }

  getValidMergedStorageItem(componentStorage: ComponentDataStorage): DataStorageItem | null {
    const mergedItem = componentStorage.mergedData
    if (!mergedItem || this.options.isExpired(mergedItem)) {
      return null
    }

    this.markStorageItemAccessed(mergedItem)
    return mergedItem
  }

  collectValidComponentData(componentStorage: ComponentDataStorage): ValidComponentDataCollection {
    const collection: ValidComponentDataCollection = {
      data: {},
      hasData: false
    }

    for (const [sourceId, item] of componentStorage.dataSources) {
      this.collectDataSourceItem(componentStorage, sourceId, item, collection)
    }

    return collection
  }

  unwrapCompleteComponentData(componentData: Record<string, any>): Record<string, any> {
    if (!this.hasCompleteDataSource(componentData)) {
      return componentData
    }

    return this.unwrapCompleteDataSource(componentData.complete)
  }

  cacheMergedComponentData(componentStorage: ComponentDataStorage, finalData: Record<string, any>): void {
    componentStorage.mergedData = this.createMergedStorageItem(componentStorage.componentId, finalData)
  }

  getValidDataSourceItem(componentStorage: ComponentDataStorage, sourceId: string): DataStorageItem | null {
    const item = componentStorage.dataSources.get(sourceId)
    if (!item) {
      return null
    }

    if (this.options.isExpired(item)) {
      componentStorage.dataSources.delete(sourceId)
      return null
    }

    return item
  }

  markStorageItemAccessed(item: DataStorageItem): void {
    item.accessCount++
    item.lastAccessed = Date.now()
  }

  invalidateMergedData(componentStorage: ComponentDataStorage): void {
    componentStorage.mergedData = undefined
  }

  private collectDataSourceItem(
    componentStorage: ComponentDataStorage,
    sourceId: string,
    item: DataStorageItem,
    collection: ValidComponentDataCollection
  ): void {
    if (this.options.isExpired(item)) {
      componentStorage.dataSources.delete(sourceId)
      return
    }

    collection.data[sourceId] = item.data
    collection.hasData = true
    this.markStorageItemAccessed(item)
  }

  private hasCompleteDataSource(componentData: Record<string, any>): boolean {
    return 'complete' in componentData && Boolean(componentData.complete)
  }

  private unwrapCompleteDataSource(completeData: any): Record<string, any> {
    if (this.hasNestedDeviceData(completeData)) {
      return completeData.deviceData.data
    }

    return completeData
  }

  private hasNestedDeviceData(data: any): boolean {
    return Boolean(data?.deviceData?.data)
  }

  private createMergedStorageItem(componentId: string, finalData: Record<string, any>): DataStorageItem {
    const now = Date.now()
    return {
      data: finalData,
      timestamp: now,
      expiresAt: now + this.options.getDefaultCacheExpiry(),
      source: {
        sourceId: '*merged*',
        sourceType: 'merged',
        componentId
      },
      size: this.options.calculateDataSize(finalData),
      accessCount: 1,
      lastAccessed: now
    }
  }
}

/**
 * 文件用途: 配置事件总线模块。
 * 核心逻辑: 提供配置变更事件的订阅、过滤、优先级分发和执行器调用解耦能力。
 * 关键注意事项: 事件名称、优先级和组件 ID 过滤规则会影响配置变更后的运行时联动。
 * 重构建议: 将事件存储、过滤策略和调度策略拆分，便于后续接入更明确的生命周期管理。
 */

export interface ConfigChangeEvent {
  /** 组件ID */
  componentId: string
  /** 组件类型 */
  componentType: string
  /** 变更的配置层级 */
  section: 'base' | 'component' | 'dataSource' | 'interaction'
  /** 变更前的配置 */
  oldConfig: any
  /** 变更后的配置 */
  newConfig: any
  /** 变更时间戳 */
  timestamp: number
  /** 变更来源 */
  source: 'user' | 'system' | 'api' | 'import'
  /** 额外的上下文信息 */
  context?: {
    /** 触发变更的UI组件 */
    triggerComponent?: string
    /** 是否需要触发数据执行 */
    shouldTriggerExecution?: boolean
    /** 变更的具体字段路径 */
    changedFields?: string[]
  }
}

export type ConfigEventType =
  | 'config-changed' // 任意配置变更
  | 'data-source-changed' // 数据源配置变更
  | 'component-props-changed' // 组件属性变更
  | 'base-config-changed' // 基础配置变更
  | 'interaction-changed' // 交互配置变更
  | 'before-config-change' // 配置变更前（可用于验证）
  | 'after-config-change' // 配置变更后（用于清理工作）

export type ConfigEventHandler = (event: ConfigChangeEvent) => void | Promise<void>

export interface ConfigEventFilter {
  /** 过滤器名称 */
  name: string
  /** 过滤条件函数 */
  condition: (event: ConfigChangeEvent) => boolean
  /** 过滤器优先级（数字越大优先级越高） */
  priority?: number
}

/**
 * 配置事件总线类
 * 实现配置变更的事件驱动处理，解耦配置管理与业务逻辑
 */
export class ConfigEventBus {
  /** 事件处理器映射 */
  private eventHandlers = new Map<ConfigEventType, Set<ConfigEventHandler>>()

  /** 全局事件过滤器列表 */
  private globalFilters: ConfigEventFilter[] = []

  /** 事件处理统计（用于调试和性能分析） */
  private statistics = {
    eventsEmitted: 0,
    eventsFiltered: 0,
    handlersExecuted: 0,
    errors: 0
  }

  /**
   * 注册配置变更事件处理器
   * @param eventType 事件类型
   * @param handler 事件处理函数
   * @returns 取消注册的函数
   */
  onConfigChange(eventType: ConfigEventType, handler: ConfigEventHandler): () => void {
    if (!this.eventHandlers.has(eventType)) {
      this.eventHandlers.set(eventType, new Set())
    }

    const handlers = this.eventHandlers.get(eventType)!
    handlers.add(handler)
    // 返回取消注册的函数
    return () => {
      handlers.delete(handler)
      if (handlers.size === 0) {
        this.eventHandlers.delete(eventType)
      }
    }
  }

  /**
   * 发出配置变更事件
   * @param event 配置变更事件
   */
  async emitConfigChange(event: ConfigChangeEvent): Promise<void> {
    this.statistics.eventsEmitted++

    // 应用全局过滤器
    if (!this.passesGlobalFilters(event)) {
      this.statistics.eventsFiltered++
      return
    }

    // 确定要触发的事件类型
    const eventTypesToTrigger = this.determineEventTypes(event)

    // 并行执行所有相关事件类型的处理器
    const handlerPromises: Promise<void>[] = []

    for (const eventType of eventTypesToTrigger) {
      const handlers = this.eventHandlers.get(eventType)
      if (handlers) {
        for (const handler of handlers) {
          handlerPromises.push(this.executeHandler(handler, event, eventType))
        }
      }
    }

    // 等待所有处理器执行完成
    if (handlerPromises.length > 0) {
      try {
        await Promise.allSettled(handlerPromises)
      } catch (error) {
        console.error('[ConfigEventBus] handler execution failed:', error)
      }
    }
  }

  /**
   * 添加全局事件过滤器
   * @param filter 事件过滤器
   */
  addEventFilter(filter: ConfigEventFilter): void {
    // 按优先级插入（优先级高的在前）
    const insertIndex = this.globalFilters.findIndex(f => (f.priority || 0) < (filter.priority || 0))
    if (insertIndex === -1) {
      this.globalFilters.push(filter)
    } else {
      this.globalFilters.splice(insertIndex, 0, filter)
    }
  }

  /**
   * 移除全局事件过滤器
   * @param filterName 过滤器名称
   */
  removeEventFilter(filterName: string): void {
    const index = this.globalFilters.findIndex(f => f.name === filterName)
    if (index !== -1) {
      this.globalFilters.splice(index, 1)
    }
  }

  /**
   * 获取事件总线统计信息
   */
  getStatistics() {
    return { ...this.statistics }
  }

  /**
   * 清除所有事件处理器和过滤器（用于测试和清理）
   */
  clear(): void {
    this.eventHandlers.clear()
    this.globalFilters.length = 0
    this.statistics = {
      eventsEmitted: 0,
      eventsFiltered: 0,
      handlersExecuted: 0,
      errors: 0
    }
  }

  // ===== 私有方法 =====

  /**
   * 检查事件是否通过全局过滤器
   */
  private passesGlobalFilters(event: ConfigChangeEvent): boolean {
    for (const filter of this.globalFilters) {
      try {
        if (!filter.condition(event)) {
          return false
        }
      } catch (error) {
        // 过滤器执行失败时，默认让事件通过
      }
    }
    return true
  }

  /**
   * 根据事件内容确定要触发的事件类型
   */
  private determineEventTypes(event: ConfigChangeEvent): ConfigEventType[] {
    const eventTypes: ConfigEventType[] = ['config-changed'] // 总是触发通用事件

    // 根据配置层级添加特定事件类型
    switch (event.section) {
      case 'dataSource':
        eventTypes.push('data-source-changed')
        break
      case 'component':
        eventTypes.push('component-props-changed')
        break
      case 'base':
        eventTypes.push('base-config-changed')
        break
      case 'interaction':
        eventTypes.push('interaction-changed')
        break
    }
    return eventTypes
  }

  /**
   * 安全地执行事件处理器
   */
  private async executeHandler(
    handler: ConfigEventHandler,
    event: ConfigChangeEvent,
    eventType: ConfigEventType
  ): Promise<void> {
    try {
      this.statistics.handlersExecuted++

      const result = handler(event)

      // 如果处理器返回Promise，等待执行完成
      if (result instanceof Promise) {
        await result
      }
    } catch (error) {
      this.statistics.errors++

      // 不重新抛出错误，避免影响其他处理器的执行
    }
  }
}

// 创建全局配置事件总线实例
export const configEventBus = new ConfigEventBus()

// ✅ 简化：移除过度复杂的事件去重系统
// 事件去重由调用方自行处理，保持事件系统简单直接

// 添加一些默认的过滤器
configEventBus.addEventFilter({
  name: 'ignore-system-updates',
  condition: event => {
    // 忽略某些系统级别的配置更新，避免无限循环
    return event.source !== 'system' || event.context?.shouldTriggerExecution !== false
  },
  priority: 100
})

// 事件去重逻辑由调用方自行处理，保持事件系统简单直接。
// 事件处理逻辑保持简单直接，不过度分析配置内容。

// 监听基础配置变更事件，自动触发数据源重新执行。
let dataExecutionTriggerCallback: ((event: ConfigChangeEvent) => void) | null = null

/**
 * 注册数据执行触发器。
 * 允许外部系统注册一个回调函数，在配置变更时触发数据重新执行
 */
export function registerDataExecutionTrigger(callback: (event: ConfigChangeEvent) => void): () => void {
  dataExecutionTriggerCallback = callback

  return () => {
    dataExecutionTriggerCallback = null
  }
}

// 监听所有配置变更事件，特别关注基础配置和数据源配置变更。
configEventBus.onConfigChange('config-changed', async event => {
  // 对于需要触发数据执行的事件，调用注册的触发器
  if (event.context?.shouldTriggerExecution && dataExecutionTriggerCallback) {
    try {
      const result = dataExecutionTriggerCallback(event)

      if (result instanceof Promise) {
        await result
      }
    } catch (error) {
      console.error('[ConfigEventBus] data execution trigger failed', {
        componentId: event.componentId,
        error: error instanceof Error ? error.message : error
      })
    }
  }
})

// 监听基础配置变更事件。
configEventBus.onConfigChange('base-config-changed', async event => {
  // 基础配置变更通常都需要触发数据重新执行
  if (!event.context) {
    event.context = {}
  }
  event.context.shouldTriggerExecution = true
  // 调用数据执行触发器
  if (dataExecutionTriggerCallback) {
    try {
      dataExecutionTriggerCallback(event)
    } catch (error) {
      console.error('[ConfigEventBus] base config data execution trigger failed', {
        componentId: event.componentId,
        error: error instanceof Error ? error.message : error
      })
    }
  }
})

// 监听数据源配置变更事件。
configEventBus.onConfigChange('data-source-changed', async event => {
  // 数据源配置变更通常都需要触发数据重新执行
  if (!event.context) {
    event.context = {}
  }
  event.context.shouldTriggerExecution = true
  // 调用数据执行触发器
  if (dataExecutionTriggerCallback) {
    try {
      dataExecutionTriggerCallback(event)
    } catch (error) {
      console.error('[ConfigEventBus] data-source config execution trigger failed', {
        componentId: event.componentId,
        error: error instanceof Error ? error.message : error
      })
    }
  }
})

// Diagnostic support: expose the event bus globally for console inspection.
if (typeof window !== 'undefined') {
  ;(window as any).configEventBus = configEventBus
  ;(window as any).registerDataExecutionTrigger = registerDataExecutionTrigger
}

/**
 * 文件用途: ConfigToSimpleDataAdapter 的转换边界测试。
 * 核心逻辑: 验证历史配置归一、本地静态数据转换和不支持类型的显式阻断。
 * 关键注意事项: 适配器必须保留旧配置契约，但不能把未知类型透传给运行时执行器。
 */

import { afterEach, describe, expect, it, vi } from 'vitest'

import {
  batchConvertConfigs,
  convertToSimpleDataRequirement,
  extractComponentType,
  shouldConvertConfig
} from './ConfigToSimpleDataAdapter'

afterEach(() => {
  vi.restoreAllMocks()
})

describe('ConfigToSimpleDataAdapter', () => {
  it('converts a simple object into a local static data source', () => {
    expect(convertToSimpleDataRequirement('card-1', { value: 42 })).toEqual({
      componentId: 'card-1',
      dataSources: [
        {
          id: 'main',
          type: 'static',
          config: { data: { value: 42 } }
        }
      ]
    })
  })

  it('parses JSON rawData from legacy binding maps', () => {
    expect(
      convertToSimpleDataRequirement('card-2', {
        dataSourceBindings: {
          primary: { rawData: '{"temperature":21.5}' }
        }
      })
    ).toEqual({
      componentId: 'card-2',
      dataSources: [
        {
          id: 'primary',
          type: 'static',
          config: { data: { temperature: 21.5 } }
        }
      ]
    })
  })

  it('normalizes the persisted api alias to the runtime http type', () => {
    const result = convertToSimpleDataRequirement('card-3', {
      rawDataList: [
        {
          id: 'remote',
          type: 'api',
          config: { url: '/api/devices', method: 'GET' }
        },
        {
          id: 'disabled',
          type: 'static',
          enabled: false,
          config: { data: 'ignored' }
        }
      ]
    })

    expect(result?.dataSources).toEqual([
      {
        id: 'remote',
        type: 'http',
        config: { url: '/api/devices', method: 'GET' },
        filterPath: undefined,
        processScript: undefined
      }
    ])
  })

  it('blocks unknown data-source types instead of passing them to runtime', () => {
    const errorSpy = vi.spyOn(console, 'error').mockImplementation(() => undefined)
    const result = convertToSimpleDataRequirement('card-4', {
      rawDataList: [
        { id: 'unsupported', type: 'mqtt', config: { topic: 'devices' } },
        { id: 'local', type: 'static', config: { data: [1, 2, 3] } }
      ]
    })

    expect(result?.dataSources).toEqual([
      {
        id: 'local',
        type: 'static',
        config: { data: [1, 2, 3] },
        filterPath: undefined,
        processScript: undefined
      }
    ])
    expect(errorSpy).toHaveBeenCalledWith(
      '[ConfigAdapter] UNSUPPORTED_DATA_SOURCE_TYPE: unsupported (mqtt)'
    )
  })

  it('returns null for malformed raw JSON and reports the parse failure', () => {
    const errorSpy = vi.spyOn(console, 'error').mockImplementation(() => undefined)

    expect(
      convertToSimpleDataRequirement('card-5', {
        dataSourceBindings: { primary: { rawData: '{broken' } }
      })
    ).toBeNull()
    expect(errorSpy).toHaveBeenCalled()
  })

  it('detects convertible shapes and extracts component metadata safely', () => {
    expect(shouldConvertConfig({ rawDataList: [] })).toBe(true)
    expect(shouldConvertConfig({ value: 1 })).toBe(true)
    expect(shouldConvertConfig({ type: 'static' })).toBe(false)
    expect(shouldConvertConfig(null)).toBe(false)
    expect(extractComponentType({ metadata: { componentType: 'rdi-card' } })).toBe('rdi-card')
    expect(extractComponentType(undefined)).toBe('unknown')
  })

  it('batch converts only eligible configurations with valid data sources', () => {
    vi.spyOn(console, 'error').mockImplementation(() => undefined)

    expect(
      batchConvertConfigs({
        local: { status: 'ok' },
        ignored: { type: 'static', metadata: { componentType: 'existing' } },
        blocked: { rawDataList: [{ id: 'external', type: 'mqtt' }] }
      })
    ).toEqual({
      local: {
        componentId: 'local',
        dataSources: [
          {
            id: 'main',
            type: 'static',
            config: { data: { status: 'ok' } }
          }
        ]
      }
    })
  })
})

/**
 * 文件用途: 复杂配置到 SimpleDataBridge 简化配置的转换适配器。
 * 核心逻辑: 把现有组件数据源配置归一成组件数据需求和简化数据源配置。
 * 关键注意事项: 字段映射需要兼容历史配置，默认值变化会影响已保存组件的数据执行。
 * 重构建议: 将 compatibility 字段归一、默认值填充和错误报告拆成独立转换步骤。
 */

import type { ComponentDataRequirement, SimpleDataSourceConfig } from '@/core/data-architecture/SimpleDataBridge'

type LooseRecord = Record<string, unknown>
type DataSourceBindingMap = LooseRecord
type BindingMapDescriptor = { bindings: DataSourceBindingMap; parseErrorMessage: string }

function hasConvertibleInput(config: unknown): boolean {
  return Boolean(config)
}

function hasOwnField(value: unknown, field: string): boolean {
  return Boolean(value && typeof value === 'object' && Object.prototype.hasOwnProperty.call(value, field))
}

function hasRawDataBindingMap(value: unknown): value is DataSourceBindingMap {
  return Boolean(
    value &&
      typeof value === 'object' &&
      !Array.isArray(value) &&
      Object.values(value as LooseRecord).some((binding) => hasOwnField(binding, 'rawData'))
  )
}

function hasConvertibleRawDataList(value: unknown): value is unknown[] {
  return (
    Array.isArray(value) &&
    value.some((item) => {
      const record = item as LooseRecord | null | undefined
      return Boolean(record && record.enabled !== false && (hasOwnField(record, 'rawData') || record.type))
    })
  )
}

function createStaticDataSource(id: string, data: unknown): SimpleDataSourceConfig {
  return {
    id,
    type: 'static',
    config: {
      data
    }
  }
}

function parseRawDataValue(rawData: unknown, sourceId: string, parseErrorMessage: string): unknown | null {
  if (typeof rawData !== 'string') {
    return rawData
  }

  try {
    return JSON.parse(rawData)
  } catch (error) {
    console.error(`${parseErrorMessage}: ${sourceId}`, error)
    return null
  }
}

function mapStaticRawDataSource(rawData: unknown, sourceId: string, parseErrorMessage: string): SimpleDataSourceConfig | null {
  const parsedData = parseRawDataValue(rawData, sourceId, parseErrorMessage)

  if (parsedData === null) {
    return null
  }

  return createStaticDataSource(sourceId, parsedData)
}

function collectMappedDataSources<T>(
  items: T[],
  mapItem: (item: T, index: number) => SimpleDataSourceConfig | null
): SimpleDataSourceConfig[] {
  const dataSources: SimpleDataSourceConfig[] = []

  items.forEach((item, index) => {
    const dataSource = mapItem(item, index)

    if (dataSource) {
      dataSources.push(dataSource)
    }
  })

  return dataSources
}

function mapRawDataBinding(key: string, binding: unknown, parseErrorMessage: string): SimpleDataSourceConfig | null {
  if (!hasOwnField(binding, 'rawData')) {
    return null
  }

  return mapStaticRawDataSource((binding as LooseRecord).rawData, key, parseErrorMessage)
}

function normalizeDataSourceType(type: unknown): SimpleDataSourceConfig['type'] | null {
  if (type === 'api') {
    return 'http'
  }

  if (['static', 'http', 'json', 'websocket', 'file', 'data-source-bindings'].includes(String(type))) {
    return type as SimpleDataSourceConfig['type']
  }

  return null
}

function mapRawDataListItem(item: unknown, index: number, parseErrorMessage: string): SimpleDataSourceConfig | null {
  const record = item as LooseRecord | null | undefined
  if (!record || record.enabled === false) {
    return null
  }

  const sourceId = (record.id || record.sourceId || `dataSource${index + 1}`) as string

  if (hasOwnField(record, 'rawData')) {
    return mapStaticRawDataSource(record.rawData, sourceId, parseErrorMessage)
  }

  const normalizedType = normalizeDataSourceType(record.type)
  if (!normalizedType) {
    console.error(`[ConfigAdapter] UNSUPPORTED_DATA_SOURCE_TYPE: ${sourceId} (${String(record.type)})`)
    return null
  }

  return {
    id: sourceId,
    type: normalizedType,
    config: (record.config || {}) as LooseRecord,
    filterPath: record.filterPath as string | undefined,
    processScript: record.processScript as string | undefined
  }
}

function mapDataSourceBindings(bindings: DataSourceBindingMap, parseErrorMessage: string): SimpleDataSourceConfig[] {
  return collectMappedDataSources(Object.entries(bindings), ([key, binding]) =>
    mapRawDataBinding(key, binding, parseErrorMessage)
  )
}

function mapRawDataList(rawDataList: unknown[], parseErrorMessage: string): SimpleDataSourceConfig[] {
  return collectMappedDataSources(rawDataList, (item, index) => mapRawDataListItem(item, index, parseErrorMessage))
}

function collectBindingMaps(config: unknown): BindingMapDescriptor[] {
  const bindingMaps: BindingMapDescriptor[] = []
  const record = (config ?? {}) as LooseRecord
  const rawDataSources = record.rawDataSources as LooseRecord | null | undefined

  if (hasRawDataBindingMap(rawDataSources?.dataSourceBindings)) {
    bindingMaps.push({
      bindings: rawDataSources.dataSourceBindings as DataSourceBindingMap,
      parseErrorMessage: '[ConfigAdapter] Failed to parse rawDataSources rawData'
    })
  }

  if (hasRawDataBindingMap(record.bindings)) {
    bindingMaps.push({
      bindings: record.bindings as DataSourceBindingMap,
      parseErrorMessage: '[ConfigAdapter] Failed to parse bindings rawData'
    })
  }

  return bindingMaps
}

function mapConfiguredDataSources(config: unknown): SimpleDataSourceConfig[] {
  const dataSources: SimpleDataSourceConfig[] = []
  const record = (config ?? {}) as LooseRecord
  const nested = record.config as LooseRecord | null | undefined

  if (record.dataSourceBindings) {
    dataSources.push(...mapDataSourceBindings(record.dataSourceBindings as DataSourceBindingMap, '❌ [ConfigAdapter] 解析rawData失败'))
  }

  if (nested?.dataSourceBindings) {
    dataSources.push(
      ...mapDataSourceBindings(nested.dataSourceBindings as DataSourceBindingMap, '❌ [ConfigAdapter] 解析嵌套rawData失败')
    )
  }

  collectBindingMaps(config).forEach(({ bindings, parseErrorMessage }) => {
    dataSources.push(...mapDataSourceBindings(bindings, parseErrorMessage))
  })

  collectBindingMaps(nested || {}).forEach(({ bindings, parseErrorMessage }) => {
    dataSources.push(...mapDataSourceBindings(bindings, parseErrorMessage))
  })

  if (hasConvertibleRawDataList(record.rawDataList)) {
    dataSources.push(...mapRawDataList(record.rawDataList, '[ConfigAdapter] Failed to parse rawDataList rawData'))
  }

  if (hasConvertibleRawDataList(nested?.rawDataList)) {
    dataSources.push(
      ...mapRawDataList(nested.rawDataList, '[ConfigAdapter] Failed to parse nested rawDataList rawData')
    )
  }

  return dataSources
}

function isSimpleObjectConfig(config: unknown): boolean {
  const record = config as LooseRecord
  return (
    typeof record === 'object' &&
    !Array.isArray(record) &&
    !record.type &&
    !record.dataSourceBindings &&
    !record.rawDataSources &&
    !record.rawDataList &&
    !hasRawDataBindingMap(record.bindings) &&
    !record.config
  )
}

function mapDefaultCompatibleDataSource(config: unknown): SimpleDataSourceConfig[] {
  if (!isSimpleObjectConfig(config)) {
    return []
  }

  return [createStaticDataSource('main', config)]
}

function assembleRequirement(
  componentId: string,
  dataSources: SimpleDataSourceConfig[]
): ComponentDataRequirement | null {
  if (dataSources.length === 0) {
    console.error(`⚠️ [ConfigAdapter] 没有找到有效的数据源配置: ${componentId}`)
    return null
  }

  return {
    componentId,
    dataSources
  }
}

/**
 * 将复杂的数据源配置转换为简化格式
 * @param componentId 组件ID
 * @param config 原始配置对象
 * @returns 简化的组件数据需求
 */
export function convertToSimpleDataRequirement(componentId: string, config: unknown): ComponentDataRequirement | null {
  if (!hasConvertibleInput(config)) {
    return null
  }

  const dataSources = [...mapConfiguredDataSources(config), ...mapDefaultCompatibleDataSource(config)]

  return assembleRequirement(componentId, dataSources)
}

/**
 * 检查配置是否需要转换
 * @param config 配置对象
 * @returns 是否需要转换
 */
export function shouldConvertConfig(config: unknown): boolean {
  if (!config || typeof config !== 'object') {
    return false
  }

  const record = config as LooseRecord
  const nested = record.config as LooseRecord | null | undefined
  const rawDataSources = record.rawDataSources as LooseRecord | null | undefined
  const nestedRawDataSources = nested?.rawDataSources as LooseRecord | null | undefined

  if (
    record.dataSourceBindings ||
    nested?.dataSourceBindings ||
    hasRawDataBindingMap(rawDataSources?.dataSourceBindings) ||
    hasRawDataBindingMap(record.bindings) ||
    hasRawDataBindingMap(nestedRawDataSources?.dataSourceBindings) ||
    hasRawDataBindingMap(nested?.bindings) ||
    Array.isArray(record.rawDataList) ||
    Array.isArray(nested?.rawDataList)
  ) {
    return true
  }

  return !Array.isArray(config) && !record.type && !record.enabled && !record.metadata
}

/**
 * 从配置中提取组件类型
 * @param config 配置对象
 * @returns 组件类型
 */
export function extractComponentType(config: unknown): string {
  const record = config as LooseRecord | null | undefined
  const metadata = record?.metadata as LooseRecord | null | undefined
  return (metadata?.componentType || 'unknown') as string
}

/**
 * 批量转换多个组件配置
 * @param configs 配置映射 {componentId: config}
 * @returns 转换结果映射
 */
export function batchConvertConfigs(configs: Record<string, unknown>): Record<string, ComponentDataRequirement> {
  const results: Record<string, ComponentDataRequirement> = {}

  Object.entries(configs).forEach(([componentId, config]) => {
    if (shouldConvertConfig(config)) {
      const requirement = convertToSimpleDataRequirement(componentId, config)
      if (requirement) {
        results[componentId] = requirement
      }
    }
  })

  return results
}

