const TYPE_COMPATIBILITY_DEBUG_GLOBAL = '__TYPE_COMPATIBILITY_CHECKER__'

/**
 * 按需安装调试接口。模块导入本身不会污染宿主全局；返回的清理函数仅撤销本次安装。
 */
export function installTypeCompatibilityDebugGlobal(target: typeof globalThis = globalThis): () => void {
  const debugTarget = target as typeof globalThis & Record<string, unknown>
  const hadOwnValue = Object.prototype.hasOwnProperty.call(debugTarget, TYPE_COMPATIBILITY_DEBUG_GLOBAL)
  const previousValue = debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL]
  const debugApi = {
    checker: typeCompatibilityChecker,
    checkHttpConfig: checkHttpConfigCompatibility,
    checkComponentRequirement: checkComponentDataRequirementCompatibility,
    checkDataType: checkDataTypeCompatibility,
    getStats: () => typeCompatibilityChecker.getTypeMappingStats(),
    getHistory: () => typeCompatibilityChecker.getCheckHistory(),
    clearHistory: () => typeCompatibilityChecker.clearCheckHistory()
  }

  debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL] = debugApi

  return () => {
    if (debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL] !== debugApi) {
      return
    }

    if (hadOwnValue) {
      debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL] = previousValue
    } else {
      delete debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL]
    }
  }
}

