    const replacementBridge = getVisualEditorBridge()
    expect(replacementBridge).not.toBe(firstBridge)

    await firstBridge.updateComponentExecutor('card-old-instance', 'widget', {
      type: 'json',
      config: { jsonString: '{}' }
    })
    expect(callback).not.toHaveBeenCalled()

    const replacementCallback = vi.fn()
    replacementBridge.onDataUpdate(replacementCallback)
    await replacementBridge.updateComponentExecutor('card-new-instance', 'widget', {
      type: 'json',
      config: { jsonString: '{}' }
    })
    expect(replacementCallback).toHaveBeenCalledWith('card-new-instance', { main: { value: 26 } })
  })

  it('proxies component data and cache clearing through SimpleDataBridge', () => {
    simpleDataBridgeMock.getComponentData.mockReturnValue({ main: { value: 26 } })
    const bridge = new VisualEditorBridge()

    expect(bridge.getComponentData('card-cache')).toEqual({ main: { value: 26 } })
    bridge.clearComponentCache('card-cache')

    expect(simpleDataBridgeMock.getComponentData).toHaveBeenCalledWith('card-cache')
    expect(simpleDataBridgeMock.clearComponentCache).toHaveBeenCalledWith('card-cache')
  })
})

/**
 * 文件用途: 连接 Visual Editor 保存态配置与数据架构执行入口。
 * 核心职责: 负责配置归一化、基础参数注入、绑定表达式替换，以及向 SimpleDataBridge 下发执行请求。
 * 桥接边界: 这里只做“编辑器配置 -> 数据需求”的单向转换，不直接反查 Visual Editor store，也不维护编辑器内部状态。
 * 循环依赖说明: 若在此层直接引入编辑器配置桥或节点状态查询，会把 data-architecture 与 visual-editor 再次耦合，形成循环依赖。
 * 兼容性注意: 历史字段别名、whitelist 持久化别名与默认值注入策略都会影响旧组件配置回放结果。
 */

import {
  simpleDataBridge,
  type ComponentDataRequirement,
  type DataResult,
  type SimpleDataSourceConfig
} from '@/core/data-architecture/SimpleDataBridge'
import type { DataSourceConfiguration } from '@/core/data-architecture/executors/MultiLayerExecutorChain'
import { dataSourceBindingConfig, type AutoBindConfig } from '@/core/data-architecture/DataSourceBindingConfig'
import { createLogger } from '@/utils/logger'

const bridgeLogger = createLogger('VisualEditorBridge')

type StandardDataSource = DataSourceConfiguration['dataSources'][number]
type BridgeDataSource = SimpleDataSourceConfig | StandardDataSource

// 保持这个可选导入处于禁用状态，避免桥接层反向依赖编辑器配置模块并形成循环依赖。
// import { configurationIntegrationBridge } from '@/components/visual-editor/configuration/ConfigurationIntegrationBridge'

/** 组件数据载荷（与 SimpleDataBridge 缓存结构一致，字段宽松） */
type ComponentDataPayload = Record<string, unknown>

/** 编辑器保存态配置（历史格式宽松，运行时逐个校验） */
type EditorComponentConfig = {
  base?: Record<string, unknown> | null
  dataSource?: Record<string, unknown> | null
  componentType?: unknown
  [key: string]: unknown
}

/** 编辑器数据源声明（历史格式宽松，字段运行时逐个校验） */
type EditorDataSourceLike = {
  type?: unknown
  enabled?: unknown
  config?: (Record<string, unknown> & { params?: Record<string, unknown> | null }) | null
  autoBind?: AutoBindConfig | null
  componentType?: string
  deviceId?: unknown
  metricsList?: unknown
  filterPath?: string
  processScript?: string
  [key: string]: unknown
}

type ResolvedBridgeConfig = {
  resolvedConfig: EditorDataSourceLike | null
  baseConfig: Record<string, unknown> | null
}

/** 编辑器标准数据项行（sourceId 槽位内的 dataItem） */
type EditorStandardDataItem = {
  item?: { type?: unknown; config?: Record<string, unknown> | null } | null
  processing?: { filterPath?: unknown; customScript?: unknown } | null
}

/**
 * Visual Editor 专用的数据桥接器
 * 封装 SimpleDataBridge，提供编辑器运行时数据接口
 */
export class VisualEditorBridge {
  private dataUpdateCallbacks = new Map<number, (componentId: string, data: ComponentDataPayload) => void>()
  private nextDataUpdateCallbackId = 1

  private normalizeDataSourceType(type: unknown, sourceId: string): SimpleDataSourceConfig['type'] | null {
    if (type === 'api') {
      return 'http'
    }

    if (['static', 'http', 'json', 'websocket', 'file', 'data-source-bindings'].includes(String(type))) {
      return type as SimpleDataSourceConfig['type']
    }

    bridgeLogger.error('[VisualEditorBridge] UNSUPPORTED_DATA_SOURCE_TYPE', {
      sourceId,
      type: String(type)
    })
    return null
  }

  /**
   * 更新组件执行器
   * @param componentId 组件ID
   * @param componentType 组件类型
   * @param config 数据源配置
   */
  async updateComponentExecutor(
    componentId: string,
    componentType: string,
    config: EditorComponentConfig | null
  ): Promise<DataResult> {
    // 将编辑器保存态配置转换为当前数据架构可执行的数据需求。
    const requirement = this.convertConfigToRequirement(componentId, componentType, config)

    const result = await simpleDataBridge.executeComponent(requirement)

    // 通知数据更新回调
    this.notifyDataUpdate(componentId, result.data)

    return result
  }

  /**
   * 监听数据更新。
   * 返回的退订函数可重复调用，不依赖随机数生成订阅标识。
   * @param callback 数据更新回调函数
   */
  onDataUpdate(callback: (componentId: string, data: ComponentDataPayload) => void): () => void {
    const callbackId = this.nextDataUpdateCallbackId++
    this.dataUpdateCallbacks.set(callbackId, callback)

    return () => {
      this.dataUpdateCallbacks.delete(callbackId)
    }
  }

  /**
   * 释放当前桥接器持有的本地订阅。
   * 数据执行与缓存由共享的 SimpleDataBridge 管理，不在这里越权清空。
   */
  dispose(): void {
    this.dataUpdateCallbacks.clear()
  }

  /**
   * 获取组件当前数据
   * @param componentId 组件ID
   */
  getComponentData(componentId: string): Record<string, unknown> | null {
    return simpleDataBridge.getComponentData(componentId)
  }

  /**
   * 清除组件数据缓存
   * @param componentId 组件ID
   */
  clearComponentCache(componentId: string): void {
    simpleDataBridge.clearComponentCache(componentId)
  }

  /**
   * 通知数据更新
   * @param componentId 组件ID
   * @param data 数据
   */
  private notifyDataUpdate(componentId: string, data: ComponentDataPayload): void {
    this.dataUpdateCallbacks.forEach((callback) => {
      try {
        callback(componentId, data)
      } catch (error) {
        bridgeLogger.error('[VisualEditorBridge] 数据更新回调执行失败:', {
          componentId,
          error: error instanceof Error ? error.message : error
        })
      }
    })
  }

  /**
   * 将旧的配置格式转换为新的数据需求格式
   * @param componentId 组件ID
   * @param componentType 组件类型
   * @param config 配置对象
   */
  private convertConfigToRequirement(
    componentId: string,
    componentType: string,
    config: EditorComponentConfig | null
  ): ComponentDataRequirement {
    const { resolvedConfig, baseConfig } = this.resolveBridgeConfig(config)
    const dataSources =
      resolvedConfig && typeof resolvedConfig === 'object'
        ? this.resolveDataSourcesInPriorityOrder(resolvedConfig, baseConfig)
        : []

    return {
      componentId,
      componentType,
      dataSources,
      enabled: true
    }
  }

  private resolveDataSourcesInPriorityOrder(
    resolvedConfig: EditorDataSourceLike,
    baseConfig: Record<string, unknown> | null
  ): BridgeDataSource[] {
    const dataSources: BridgeDataSource[] = []
    const collectors = [
      () => this.collectStandardDataSources(dataSources, resolvedConfig),
      () => this.collectRawDataListSources(dataSources, resolvedConfig),
      () => this.collectNamedDataSources(dataSources, resolvedConfig, baseConfig),
      () => this.collectSingleDataSource(dataSources, resolvedConfig, baseConfig)
    ]

    for (const collect of collectors) {
      collect()
      if (dataSources.length > 0) {
        break
      }
    }

    return dataSources
  }

  private resolveBridgeConfig(config: EditorComponentConfig | null): ResolvedBridgeConfig {
    let resolvedConfig: EditorDataSourceLike | null = config
    let baseConfig: Record<string, unknown> | null = null

    if (config && typeof config === 'object' && (config.base || config.dataSource)) {
      baseConfig = config.base || {}
      resolvedConfig = {
        ...config.dataSource,
        deviceId: baseConfig.deviceId,
        metricsList: baseConfig.metricsList,
        ...(config.dataSource || {})
      }
      resolvedConfig = this.injectBaseConfigToDataSource(resolvedConfig, baseConfig)
    }

    return { resolvedConfig, baseConfig }
  }

  private injectBaseConfigToDataSource<T>(dataSourceConfig: T, baseConfig: Record<string, unknown> | null): T {
    if (!baseConfig) {
      return dataSourceConfig
    }

    // 绑定替换会原地修改嵌套配置，这里先克隆，避免污染编辑器原始配置对象。
    const enhanced = JSON.parse(JSON.stringify(dataSourceConfig)) as T

    this.processBindingReplacements(enhanced as Record<string, unknown>, baseConfig)

    return enhanced
  }

  private collectStandardDataSources(dataSources: BridgeDataSource[], resolvedConfig: EditorDataSourceLike): void {
    if (!resolvedConfig.dataSources || !Array.isArray(resolvedConfig.dataSources)) {
      return
    }

    resolvedConfig.dataSources.forEach(dataSource => {
      if (!dataSource.sourceId || !Array.isArray(dataSource.dataItems)) {
        return
      }

      dataSources.push({
        sourceId: dataSource.sourceId,
        dataItems: dataSource.dataItems.map(dataItem => this.convertStandardDataItem(dataItem)).filter(Boolean),
        mergeStrategy: dataSource.mergeStrategy || { type: 'object' }
      })
    })
  }

  private convertStandardDataItem(dataItem: EditorStandardDataItem | null | undefined) {
    if (!dataItem || !dataItem.item) {
      return null
    }

    return {
      item: {
        type: dataItem.item.type,
        config: this.convertItemConfig(dataItem.item)
      },
      processing: {
        filterPath: dataItem.processing?.filterPath || '$',
        customScript: dataItem.processing?.customScript,
        defaultValue: {}
      }
    }
  }

  private collectRawDataListSources(dataSources: BridgeDataSource[], resolvedConfig: EditorDataSourceLike): void {
    if (dataSources.length > 0 || !Array.isArray(resolvedConfig.rawDataList)) {
      return
    }

    resolvedConfig.rawDataList.forEach((item, index) => {
      if (!item || !item.type || item.enabled === false) {
        return
      }

      const sourceId = item.id || item.sourceId || `dataSource${index + 1}`
      const normalizedType = this.normalizeDataSourceType(item.type, sourceId)
      if (!normalizedType) {
        return
      }

      dataSources.push({
        id: sourceId,
        type: normalizedType,
        config: item.config || {},
        filterPath: item.filterPath,
        processScript: item.processScript
      })
    })
  }

  private collectNamedDataSources(
    dataSources: BridgeDataSource[],
    resolvedConfig: EditorDataSourceLike,
    baseConfig: Record<string, unknown> | null
  ): void {
    if (dataSources.length > 0) {
      return
    }

    for (const [key, value] of Object.entries(resolvedConfig)) {
      if (!key.startsWith('dataSource') || !value || typeof value !== 'object') {
        continue
      }

      const enhancedDataSourceConfig = this.injectBaseConfigToDataSource(value as EditorDataSourceLike, baseConfig)
      if (!enhancedDataSourceConfig.type || enhancedDataSourceConfig.enabled === false) {
        continue
      }

      const normalizedType = this.normalizeDataSourceType(enhancedDataSourceConfig.type, key)
      if (!normalizedType) {
        continue
      }

      dataSources.push({
        id: key,
        type: normalizedType,
        config: enhancedDataSourceConfig.config || {},
        filterPath: enhancedDataSourceConfig.filterPath,
        processScript: enhancedDataSourceConfig.processScript
      })
    }
  }

  private collectSingleDataSource(
    dataSources: BridgeDataSource[],
    resolvedConfig: EditorDataSourceLike,
    baseConfig: Record<string, unknown> | null
  ): void {
    if (dataSources.length > 0 || !resolvedConfig.type || resolvedConfig.enabled === false) {
      return
    }

    if (resolvedConfig.type === 'data-source-bindings') {
      this.collectBindingAliasSources(dataSources, resolvedConfig)
      return
    }

    const enhancedConfig = this.injectBaseConfigToDataSource(resolvedConfig, baseConfig)
    const sourceId = 'dataSource1'
    const normalizedType = this.normalizeDataSourceType(enhancedConfig.type, sourceId)
    if (!normalizedType) {
      return
    }

    dataSources.push({
      id: sourceId,
      type: normalizedType,
      config: enhancedConfig.config || enhancedConfig,
      filterPath: enhancedConfig.filterPath,
      processScript: enhancedConfig.processScript
    })
  }

  private collectBindingAliasSources(dataSources: BridgeDataSource[], resolvedConfig: EditorDataSourceLike): void {
    for (const [key, value] of Object.entries(resolvedConfig)) {
      if (!key.startsWith('dataSource') || !value || typeof value !== 'object') {
        continue
      }

      dataSources.push({
        id: key,
        type: 'data-source-bindings',
        config: { dataSourceBindings: { [key]: value } },
        filterPath: undefined,
        processScript: undefined
      })
    }
  }

  /**
   * 在克隆后的数据源配置上替换绑定表达式。
   * 这里允许原地修改，因为调用方已经先做了深拷贝。
   */
  private processBindingReplacements(config: EditorDataSourceLike, baseConfig: Record<string, unknown>): void {
    const autoBindConfig = this.getAutoBindConfigFromDataSource(config)

    if (autoBindConfig && autoBindConfig.enabled) {
      // 使用autoBind配置处理参数绑定（同步版本）
      this.processAutoBindParamsSync(config, baseConfig, autoBindConfig)
    } else {
      // 使用传统方式处理参数绑定
      this.processTraditionalBinding(config, baseConfig)
    }
  }

  /**
   * 将 autoBind 规则落到请求参数中。
   */
  private processAutoBindParamsSync(
    config: EditorDataSourceLike,
    baseConfig: Record<string, unknown>,
    autoBindConfig: AutoBindConfig
  ): void {
    // 构建完整配置对象
    const fullConfig = {
      base: baseConfig,
      dataSource: config,
      componentType: config.componentType || 'widget'
    }

    // 使用autoBind生成HTTP参数
    const autoBindParams = dataSourceBindingConfig.buildAutoBindParams(fullConfig, autoBindConfig, config.componentType)

    // 将autoBind参数注入到HTTP配置中
    if (config.type === 'http' && config.config) {
      config.config.params = {
        ...config.config.params,
        ...autoBindParams
      }
    } else if (config.config) {
      config.config = {
        ...config.config,
        ...autoBindParams
      }
    }

    bridgeLogger.debug('[VisualEditorBridge] AutoBind参数注入完成:', {
      mode: autoBindConfig.mode,
      autoBindParams,
      finalConfig: config.config
    })
  }

  /**
   * 传统方式处理参数绑定
   */
  private processTraditionalBinding(config: EditorDataSourceLike, baseConfig: Record<string, unknown>): void {
    // 1. 首先处理基础配置注入（原有逻辑，模拟设备ID的硬编码机制）
    if (config.config && typeof config.config === 'object') {
      config.config = {
        ...config.config,
        // 注入基础配置中的设备属性（模拟设备ID硬编码逻辑）
        ...(baseConfig.deviceId && { deviceId: baseConfig.deviceId }),
        ...(baseConfig.metricsList && { metricsList: baseConfig.metricsList })
      }
    } else {
      // 如果没有 config 对象，直接在顶层注入
      config.deviceId = config.deviceId || baseConfig.deviceId
      config.metricsList = config.metricsList || baseConfig.metricsList
    }

    // 2. 递归替换嵌套配置中的 component/base 绑定表达式。
    this.recursivelyReplaceBindings(config)
  }

  /**
   * 从数据源配置中提取 autoBind 设置。
   * @param dataSourceConfig 数据源配置
   * @returns autoBind配置或null
   */
  private getAutoBindConfigFromDataSource(dataSourceConfig: EditorDataSourceLike): AutoBindConfig | null {
    // 检查数据源配置中的autoBind设置
    if (dataSourceConfig.autoBind) {
      return dataSourceConfig.autoBind
    }

    // 检查config层级的autoBind设置
    if (dataSourceConfig.config?.autoBind) {
      return dataSourceConfig.config.autoBind
    }

    return null
  }

  /**
   * 递归替换绑定表达式。
   * 支持 component、base，以及历史遗留 whitelist 持久化别名。
   */
  private recursivelyReplaceBindings(obj: Record<string, unknown>): void {
    if (!obj || typeof obj !== 'object') {
      return
    }

    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        const val = obj[key]

        if (typeof val === 'string') {
          // 识别当前桥接层支持的绑定表达式格式。
          // 格式1: componentId.component.propertyName （标准组件属性绑定）
          const componentBindingMatch = val.match(/^([^.]+)\.component\.(.+)$/)

          // 格式2: componentId.base.propertyName （基础配置绑定）
          const baseBindingMatch = val.match(/^([^.]+)\.base\.(.+)$/)

          // whitelist 是历史持久化别名，读取时继续兼容，但新配置应统一写成 component 绑定格式。
          const whitelistBindingMatch = val.match(/^([^.]+)\.whitelist\.(.+)$/)

          if (componentBindingMatch) {
            const [, componentId, propertyName] = componentBindingMatch

            const actualValue = this.getComponentPropertyValueFixed(componentId, propertyName)
            if (actualValue !== undefined) {
              obj[key] = String(actualValue)
            }
            // actualValue 为 undefined 时保留原绑定表达式，等待组件属性就绪后再替换
          } else if (baseBindingMatch) {
            const [, componentId, propertyName] = baseBindingMatch

            // 尝试获取基础配置值（使用已有的获取逻辑）
            const actualValue = this.getBaseConfigPropertyValue(componentId, propertyName)
            if (actualValue !== undefined) {
              obj[key] = String(actualValue)
            }
            // actualValue 为 undefined 时保留原绑定表达式
          } else if (whitelistBindingMatch) {
            // 兼容历史 whitelist 别名，并按组件属性绑定处理。
            const [, componentId, propertyName] = whitelistBindingMatch

            const actualValue = this.getComponentPropertyValueFixed(componentId, propertyName)
            if (actualValue !== undefined) {
              obj[key] = String(actualValue)
            }
            // actualValue 为 undefined 时保留原绑定表达式
          }
          // 不是绑定表达式的字符串值无需处理
        } else if (typeof val === 'object' && val !== null) {
          // 递归处理嵌套对象
          this.recursivelyReplaceBindings(val as Record<string, unknown>)
        }
      }
    }
  }

  /**
   * 桥接边界说明:
   * 这里暂时不负责反向读取 component/base 绑定值。
   * 只有当 Visual Editor 上层提供稳定的配置查询入口后，才能安全接入；
   * 否则会把桥接层重新耦合回编辑器实现，破坏当前的单向依赖边界。
   */
  private logUnsupportedPropertyRead(scope: 'base' | 'component', componentId: string, propertyName: string): void {
    bridgeLogger.error('[VisualEditorBridge] Unsupported property binding read:', {
      scope,
      componentId,
      propertyName,
      reason: 'No reliable Visual Editor store/configuration read path is wired for this bridge.'
    })
  }

  private getBaseConfigPropertyValue(componentId: string, propertyName: string): undefined {
    this.logUnsupportedPropertyRead('base', componentId, propertyName)
    return undefined
  }

  /**
   * 组件属性反向读取占位点。
   * 理想优先级应为: 最新配置 > 编辑器节点 > DOM。
   * 当前仍返回 undefined，表示桥接层只保留绑定表达式，不在这里擅自补齐编辑器读路径。
   */
  private getComponentPropertyValueFixed(componentId: string, propertyName: string): undefined {
    this.logUnsupportedPropertyRead('component', componentId, propertyName)
    return undefined
  }

  /**
   * 转换数据项配置，处理字段映射
   */
  private convertItemConfig(item: NonNullable<EditorStandardDataItem['item']>) {
    const { type, config } = item

    switch (type) {
      case 'json':
        // JSON类型：jsonString → jsonContent
        return {
          ...config,
          jsonContent: config.jsonString || config.jsonContent
        }

      case 'http':
        // HTTP类型：保持原有字段
        return config

      case 'script':
        // Script类型：script → scriptContent
        return {
          ...config,
          scriptContent: config.script || config.scriptContent
        }

      default:
        return config
    }
  }
}

// 端口隔离的VisualEditorBridge实例管理
const bridgeInstances = new Map<string, VisualEditorBridge>()

/**
 * 获取端口ID（用于多端口开发环境的实例隔离）
 */
function getPortId(): string {
  if (typeof window !== 'undefined') {
    return window.location.port || 'default'
  }
  return 'default'
}

/**
 * 获取当前端口的VisualEditorBridge实例
 * 确保不同端口使用独立的桥接器实例，避免数据回调干扰
 */
export function getVisualEditorBridge(): VisualEditorBridge {
  const portId = getPortId()

  if (!bridgeInstances.has(portId)) {
    bridgeInstances.set(portId, new VisualEditorBridge())
  }

  return bridgeInstances.get(portId)!
}

/**
 * 释放当前端口的桥接实例及其本地订阅。
 * 可重复调用；下一次获取时会创建全新的隔离实例。
 */
export function disposeVisualEditorBridge(): void {
  const portId = getPortId()
  const bridge = bridgeInstances.get(portId)
  if (!bridge) {
    return
  }

  bridge.dispose()
  bridgeInstances.delete(portId)
}

import { describe, expect, it } from 'vitest'

import { ConfigurationAdapter } from './ConfigurationAdapter'
import type { DataSourceConfiguration } from '../executors/MultiLayerExecutorChain'

function createHttpConfiguration(
  body: unknown,
  scripts: { preRequestScript?: string; postResponseScript?: string } = {}
): DataSourceConfiguration {
  return {
    componentId: 'component-1',
    dataSources: [
      {
        sourceId: 'http-source',
        dataItems: [
          {
            item: {
              type: 'http',
              config: {
                url: 'https://example.test/data',
                method: 'POST',
                body,
                ...scripts
              }
            },
            processing: {}
          }
        ],
        mergeStrategy: { type: 'object' }
      }
    ],
    createdAt: 1,
    updatedAt: 1
  }
}

describe('ConfigurationAdapter HTTP body conversion', () => {
  it.each([0, false, ''])('preserves the falsy body %j through a v1/v2 round trip', body => {
    const adapter = new ConfigurationAdapter()
    const original = createHttpConfiguration(body)

    const upgraded = adapter.upgradeV1ToV2(original)
    const upgradedConfig = upgraded.dataSources[0].dataItems[0].item.config as {
      body?: { type: string; content: unknown }
    }
    expect(upgradedConfig.body).toEqual({ type: 'json', content: body })

    const downgraded = adapter.downgradeV2ToV1(upgraded)
    expect(downgraded.dataSources[0].dataItems[0].item.config.body).toBe(body)
  })

  it.each([null, undefined])('treats the absent body %j as undefined', body => {
    const adapter = new ConfigurationAdapter()
    const upgraded = adapter.upgradeV1ToV2(createHttpConfiguration(body))
    const upgradedConfig = upgraded.dataSources[0].dataItems[0].item.config as {
      body?: { type: string; content: unknown }
    }

    expect(upgradedConfig.body).toBeUndefined()
  })

  it('preserves request and response scripts through a v1/v2 round trip', () => {
    const adapter = new ConfigurationAdapter()
    const original = createHttpConfiguration(undefined, {
      preRequestScript: 'config.headers.Authorization = token',
      postResponseScript: 'return response.data'
    })

    const upgraded = adapter.upgradeV1ToV2(original)
    const upgradedConfig = upgraded.dataSources[0].dataItems[0].item.config as {
      preRequestScript?: string
      responseScript?: string
    }
    expect(upgradedConfig.preRequestScript).toBe('config.headers.Authorization = token')
    expect(upgradedConfig.responseScript).toBe('return response.data')

    const downgraded = adapter.downgradeV2ToV1(upgraded)
    const downgradedConfig = downgraded.dataSources[0].dataItems[0].item.config
    expect(downgradedConfig.preRequestScript).toBe('config.headers.Authorization = token')
    expect(downgradedConfig.postResponseScript).toBe('return response.data')
  })

  it('blocks HTTP parameter migration instead of silently dropping the configuration', () => {
    const adapter = new ConfigurationAdapter()
    const original = createHttpConfiguration(undefined)
    const httpConfig = original.dataSources[0].dataItems[0].item.config
    httpConfig.params = [
      {
        key: 'deviceId',
        value: 0,
        enabled: true,
        isDynamic: false,
        dataType: 'number',
        variableName: 'var_device_id',
        description: 'Device ID',
        paramType: 'query'
      }
    ]

    expect(() => adapter.upgradeV1ToV2(original)).toThrow('UNSUPPORTED_HTTP_PARAMETER_MIGRATION')

    const result = adapter.adaptToVersion(original, 'v2.0')
    expect(result.success).toBe(false)
    expect(result.data).toBeUndefined()
    expect(result.errors).toEqual(['UNSUPPORTED_HTTP_PARAMETER_MIGRATION'])
  })

  it('reports an unsupported plugin type instead of creating a fake v1 item', () => {
    const adapter = new ConfigurationAdapter()
    const pluginConfig = {
      componentId: 'component-1',
      version: '2.0.0',
      dataSources: [
        {
          sourceId: 'plugin-source',
          dataItems: [
            {
              item: { type: 'plugin-stream', id: 'plugin-1', config: { endpoint: 'external' } },
              processing: {}
            }
          ],
          mergeStrategy: { type: 'object' as const }
        }
      ],
      dynamicParams: [],
      enhancedFeatures: {},
      createdAt: 1,
      updatedAt: 1
    }

    expect(() => adapter.downgradeV2ToV1(pluginConfig as any)).toThrow(
      'UNSUPPORTED_DATA_ITEM_TYPE:plugin-stream'
    )

    const result = adapter.adaptToVersion(pluginConfig, 'v1.0')
    expect(result.success).toBe(false)
    expect(result.data).toBeUndefined()
    expect(result.errors).toEqual(['UNSUPPORTED_DATA_ITEM_TYPE:plugin-stream'])
  })

  it('returns an isolated snapshot when the source already matches the target version', () => {
    const adapter = new ConfigurationAdapter()
    const original = {
      version: '2.0.0',
      componentId: 'component-1',
      nested: { value: 1 }
    }

    const result = adapter.adaptToVersion(original, 'v2.0')
    expect(result.success).toBe(true)

    result.data.nested.value = 2
    expect(original.nested).toEqual({ value: 1 })
  })

  it.each(['__proto__', 'prototype', 'constructor'])('filters the unsafe HTTP header key %s in both directions', key => {
    const adapter = new ConfigurationAdapter()
    const original = createHttpConfiguration(undefined)
    const headers = Object.create(null)
    headers['X-Safe'] = 'value'
    headers[key] = 'polluted'
    original.dataSources[0].dataItems[0].item.config.headers = headers

    const upgraded = adapter.upgradeV1ToV2(original)
    const upgradedConfig = upgraded.dataSources[0].dataItems[0].item.config as any
    expect(upgradedConfig.headers).toEqual([
      { key: 'X-Safe', value: 'value', enabled: true, isDynamic: false }
    ])

    upgradedConfig.headers.push({ key, value: 'polluted', enabled: true, isDynamic: false })
    const downgraded = adapter.downgradeV2ToV1(upgraded)
    expect(downgraded.dataSources[0].dataItems[0].item.config.headers).toEqual({ 'X-Safe': 'value' })
  })
})

/**
 * 文件用途: 配置版本适配器实现。
 * 核心逻辑: 检测配置版本并在 v1/v2 与标准数据项格式之间做升级、降级和兼容转换。
 * 关键注意事项: 转换必须尽量无损，版本字段和数据项结构变更需要历史配置样本验证。
 * 重构建议: 把版本检测、升级、降级和差异报告拆成独立适配阶段。
 */

import type {
  // 现有类型
  DataSourceConfiguration as V1DataSourceConfiguration,
  ExecutionResult
} from '../executors/MultiLayerExecutorChain'

import type {
  DataItem as V1DataItem,
  JsonDataItemConfig as V1JsonDataItemConfig,
  HttpDataItemConfig as V1HttpDataItemConfig
} from '../executors/DataItemFetcher'

import type {
  // 增强类型
  EnhancedDataSourceConfiguration,
  DataItemConfig,
  EnhancedJsonDataItemConfig,
  EnhancedHttpDataItemConfig,
  HttpHeader,
  HttpParam,
  ConfigurationAdapter as IConfigurationAdapter
} from '../types/enhanced-types'

import { DEFAULT_ENHANCED_FEATURES } from '@/core/data-architecture/types/enhanced-types'
import { smartDeepClone } from '@/utils/deep-clone'

const FORBIDDEN_HEADER_KEYS = new Set(['__proto__', 'prototype', 'constructor'])

function isSafeHeaderKey(key: unknown): key is string {
  return typeof key === 'string' && key.length > 0 && !FORBIDDEN_HEADER_KEYS.has(key)
}

/**
 * 配置转换结果
 */
export interface ConversionResult<T = any> {
  /** 转换是否成功 */
  success: boolean

  /** 转换后的数据 */
  data?: T

  /** 转换过程中的警告 */
  warnings: string[]

  /** 转换过程中的错误 */
  errors: string[]

  /** 转换元信息 */
  metadata: {
    /** 源版本 */
    sourceVersion: string
    /** 目标版本 */
    targetVersion: string
    /** 转换时间 */
    convertedAt: number
  }
}

/**
 * 配置版本适配器实现类
 */
export class ConfigurationAdapter implements IConfigurationAdapter {
  /**
   * 归一化版本字符串，兼容 `2.0.0`、`v2.0`、`V2.1` 等历史写法。
   */
  private normalizeVersionString(version: string): 'v1.0' | 'v2.0' | null {
    const normalizedVersion = version.trim().toLowerCase()

    if (/^v?2(?:[._-]|$)/.test(normalizedVersion)) {
      return 'v2.0'
    }

    if (/^v?1(?:[._-]|$)/.test(normalizedVersion)) {
      return 'v1.0'
    }

    return null
  }

  /**
   * 检测配置版本
   */
  detectVersion(config: any): 'v1.0' | 'v2.0' {
    // 检查版本字段
    if (config && typeof config.version === 'string') {
      const normalizedVersion = this.normalizeVersionString(config.version)
      if (normalizedVersion) {
        return normalizedVersion
      }
    }

    // 检查增强特性字段
    if (config && (config.dynamicParams || config.enhancedFeatures)) {
      return 'v2.0'
    }

    // 检查数据项格式特征
    if (config && config.dataSources && Array.isArray(config.dataSources)) {
      const firstDataSource = config.dataSources[0]
      if (firstDataSource && firstDataSource.dataItems && Array.isArray(firstDataSource.dataItems)) {
        const firstDataItem = firstDataSource.dataItems[0]
        if (firstDataItem && firstDataItem.id) {
          return 'v2.0' // 有id字段，是v2格式
        }
      }
    }

    // 默认为v1格式
    return 'v1.0'
  }

  /**
   * 适配配置到指定版本
   */
  adaptToVersion(config: any, targetVersion: 'v1.0' | 'v2.0'): ConversionResult {
    const sourceVersion = this.detectVersion(config)

    try {
      if (sourceVersion === targetVersion) {
        return {
          success: true,
          data: smartDeepClone(config),
          warnings: [],
          errors: [],
          metadata: {
            sourceVersion,
            targetVersion,
            convertedAt: Date.now()
          }
        }
      }

      const convertedData = targetVersion === 'v2.0' ? this.upgradeV1ToV2(config) : this.downgradeV2ToV1(config)

      return {
        success: true,
        data: convertedData,
        warnings: [],
        errors: [],
        metadata: {
          sourceVersion,
          targetVersion,
          convertedAt: Date.now()
        }
      }
    } catch (error) {
      return {
        success: false,
        warnings: [],
        errors: [error instanceof Error ? error.message : String(error)],
        metadata: {
          sourceVersion,
          targetVersion,
          convertedAt: Date.now()
        }
      }
    }
  }

  /**
   * v1升级到v2（无损升级）
   */
  upgradeV1ToV2(v1Config: V1DataSourceConfiguration): EnhancedDataSourceConfiguration {
    const enhancedConfig: EnhancedDataSourceConfiguration = {
      // 保留所有原有字段
      ...v1Config,

      // 添加版本标识
      version: '2.0.0',

      // 默认动态参数配置
      dynamicParams: [],

      // 默认增强功能开关
      enhancedFeatures: {
        ...DEFAULT_ENHANCED_FEATURES
      },

      // 添加配置元数据
      metadata: {
        name: `配置_${v1Config.componentId}`,
        description: `从v1.0升级的配置`,
        author: 'system',
        versionHistory: [
          {
            version: '2.0.0',
            timestamp: Date.now(),
            changelog: '从v1.0自动升级到v2.0',
            author: 'ConfigurationAdapter'
          }
        ],
        tags: ['upgraded', 'v2']
      },

      // 升级数据源配置
      dataSources: v1Config.dataSources.map((dataSource) => ({
        ...dataSource,
        dataItems: dataSource.dataItems.map((dataItemWrapper, index) => ({
          ...dataItemWrapper,
          item: this.upgradeDataItemToV2(dataItemWrapper.item, `${dataSource.sourceId}_item_${index}`)
        }))
      }))
    }

    return enhancedConfig
  }

  /**
   * v2降级到v1（兼容降级）
   */
  downgradeV2ToV1(v2Config: EnhancedDataSourceConfiguration): V1DataSourceConfiguration {
    const v1Config: V1DataSourceConfiguration = {
      componentId: v2Config.componentId,
      dataSources: v2Config.dataSources.map((dataSource) => ({
        sourceId: dataSource.sourceId,
        dataItems: dataSource.dataItems.map((dataItemWrapper) => ({
          item: this.downgradeDataItemToV1(dataItemWrapper.item),
          processing: dataItemWrapper.processing
        })),
        mergeStrategy: dataSource.mergeStrategy
      })),
      createdAt: v2Config.createdAt,
      updatedAt: Date.now() // 更新时间戳
    }

    return v1Config
  }

  /**
   * 数据项升级到v2格式
   */
  private upgradeDataItemToV2(v1Item: V1DataItem, itemId: string): DataItemConfig {
    const baseItem: DataItemConfig = {
      type: v1Item.type,
      id: itemId,
      config: v1Item.config,
      metadata: {
        displayName: `${v1Item.type}数据项`,
        description: `从v1.0升级的${v1Item.type}数据项`,
        createdAt: Date.now(),
        lastUpdated: Date.now(),
        enabled: true,
        tags: ['upgraded']
      }
    }

    // 特殊处理不同类型的配置
    switch (v1Item.type) {
      case 'json': {
        const v1JsonConfig = v1Item.config as V1JsonDataItemConfig
        const enhancedJsonConfig: EnhancedJsonDataItemConfig = {
          jsonData: v1JsonConfig.jsonString, // 字段重命名
          validation: {
            enableFormat: true,
            enableStructure: false
          },
          preprocessing: {
            removeComments: false,
            formatOutput: false
          }
        }
        return { ...baseItem, config: enhancedJsonConfig }
      }

      case 'http': {
        const v1HttpConfig = v1Item.config as V1HttpDataItemConfig
        const hasUnsupportedParameterConfiguration =
          v1HttpConfig.pathParameter !== undefined ||
          (v1HttpConfig.pathParams?.length ?? 0) > 0 ||
          (v1HttpConfig.params?.length ?? 0) > 0 ||
          (v1HttpConfig.parameters?.length ?? 0) > 0 ||
          v1HttpConfig.addressType !== undefined ||
          v1HttpConfig.selectedInternalAddress !== undefined ||
          v1HttpConfig.enableParams !== undefined

        if (hasUnsupportedParameterConfiguration) {
          throw new Error('UNSUPPORTED_HTTP_PARAMETER_MIGRATION')
        }

        const enhancedHttpConfig: EnhancedHttpDataItemConfig = {
          url: v1HttpConfig.url,
          method: v1HttpConfig.method,
          headers: this.convertHeadersRecordToArray(v1HttpConfig.headers || {}),
          params: [], // 已确认源配置没有增强类型无法表达的参数字段。
          body:
            v1HttpConfig.body !== null && v1HttpConfig.body !== undefined
              ? {
                  type: 'json',
                  content: v1HttpConfig.body
                }
              : undefined,
          timeout: v1HttpConfig.timeout,
          preRequestScript: v1HttpConfig.preRequestScript,
          responseScript: v1HttpConfig.postResponseScript,
          retry: {
            maxRetries: 3,
            retryDelay: 1000
          }
        }
        return { ...baseItem, config: enhancedHttpConfig }
      }

      default:
        // 其他类型保持原样
        return baseItem
    }
  }

  /**
   * 数据项降级到v1格式
   */
  private downgradeDataItemToV1(v2Item: DataItemConfig): V1DataItem {
    switch (v2Item.type) {
      case 'json': {
        const enhancedJsonConfig = v2Item.config as EnhancedJsonDataItemConfig
        return {
          type: 'json',
          config: {
            jsonString: enhancedJsonConfig.jsonData // 字段重命名回去
          }
        }
      }

      case 'http': {
        const enhancedHttpConfig = v2Item.config as EnhancedHttpDataItemConfig
        return {
          type: 'http',
          config: {
            url: enhancedHttpConfig.url,
            method: enhancedHttpConfig.method,
            headers: this.convertHeadersArrayToRecord(enhancedHttpConfig.headers),
            body: enhancedHttpConfig.body?.content,
            timeout: enhancedHttpConfig.timeout,
            preRequestScript: enhancedHttpConfig.preRequestScript,
            postResponseScript: enhancedHttpConfig.responseScript
          }
        }
      }

      case 'websocket':
        return {
          type: 'websocket',
          config: v2Item.config // WebSocket配置保持不变
        }

      case 'script':
        return {
          type: 'script',
          config: v2Item.config // Script配置保持不变
        }

      default:
        // v1 联合类型没有未知插件类型的安全表示，必须显式报告阻断。
        throw new Error(`UNSUPPORTED_DATA_ITEM_TYPE:${v2Item.type}`)
    }
  }

  /**
   * 将Record格式的headers转换为Array格式
   */
  private convertHeadersRecordToArray(headers: Record<string, string>): HttpHeader[] {
    return Object.entries(headers)
      .filter(([key]) => isSafeHeaderKey(key))
      .map(([key, value]) => ({
        key,
        value,
        enabled: true,
        isDynamic: false
      }))
  }

  /**
   * 将Array格式的headers转换为Record格式
   */
  private convertHeadersArrayToRecord(headers: HttpHeader[]): Record<string, string> {
    return headers
      .filter((header) => header.enabled && isSafeHeaderKey(header.key))
      .reduce(
        (acc, header) => {
          acc[header.key] = header.value
          return acc
        },
        {} as Record<string, string>
      )
  }

  /**
   * 批量转换配置
   */
  public batchConvert(configs: any[], targetVersion: 'v1.0' | 'v2.0'): ConversionResult[] {
    return configs.map((config) => this.adaptToVersion(config, targetVersion))
  }

  /**
   * 验证配置转换的一致性
   */
  public validateConversion(original: any, converted: any): { valid: boolean; issues: string[] } {
    const issues: string[] = []

    // 检查基本字段
    if (original.componentId !== converted.componentId) {
      issues.push('componentId不匹配')
    }

    if (original.dataSources.length !== converted.dataSources.length) {
      issues.push('dataSources数量不匹配')
    }

    // 检查数据源
    for (let i = 0; i < original.dataSources.length; i++) {
      const origDs = original.dataSources[i]
      const convDs = converted.dataSources[i]

      if (origDs.sourceId !== convDs.sourceId) {
        issues.push(`数据源${i}的sourceId不匹配`)
      }

      if (origDs.dataItems.length !== convDs.dataItems.length) {
        issues.push(`数据源${i}的dataItems数量不匹配`)
      }
    }

    return {
      valid: issues.length === 0,
      issues
    }
  }
}

// ==================== 工厂函数 ====================

/**
 * 创建配置适配器实例
 */
export function createConfigurationAdapter(): ConfigurationAdapter {
  return new ConfigurationAdapter()
}

// ==================== 便捷函数 ====================

/**
 * 快速检测配置版本
 */
export function detectConfigVersion(config: any): 'v1.0' | 'v2.0' {
  return createConfigurationAdapter().detectVersion(config)
}

/**
 * 快速升级配置到v2
 */
export function upgradeToV2(v1Config: V1DataSourceConfiguration): EnhancedDataSourceConfiguration {
  return createConfigurationAdapter().upgradeV1ToV2(v1Config)
}

/**
 * 快速降级配置到v1
 */
export function downgradeToV1(v2Config: EnhancedDataSourceConfiguration): V1DataSourceConfiguration {
  return createConfigurationAdapter().downgradeV2ToV1(v2Config)
}

