/**
 * 文件说明:
 * - 集中维护 DynamicParameterEditor 新增参数流程中的纯业务逻辑。
 * - 包括默认参数创建、参数 key 校验、按新增配置生成参数，以及快捷新增选项的参数预设。
 * 维护提示:
 * - 这里不直接调用 message、emit、nextTick 或任何 Vue ref，组件只负责 UI 编排。
 * - 修改默认字段时，需要同步检查参数导入、模板合并和设备参数补水逻辑。
 */
import type { EnhancedParameter } from '@/core/data-architecture/types/parameter-editor'
import { ParameterTemplateType } from '@/core/data-architecture/components/common/templates/index'
import { DEVICE_CONFIG_TEMPLATE_ID, type NewParamConfig } from './dynamicParameterEditorState'

type NewParameterValidationResult =
  | { ok: true; key: string }
  | { ok: false; reason: 'empty' | 'duplicate'; key: string }

/**
 * 创建编辑器内部使用的默认参数。
 *
 * `_id` 用于 Vue 列表稳定追踪，不能替换为业务 key，否则空 key 新增和重复 key 提示会出现错位。
 */
export const createDefaultParameter = (): EnhancedParameter => ({
  key: '',
  value: '',
  enabled: true,
  isDynamic: false,
  valueMode: ParameterTemplateType.MANUAL,
  selectedTemplate: 'manual',
  dataType: 'string',
  variableName: '',
  description: '',
  _id: `param_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
})

export const validateNewParameterKey = (
  rawKey: string,
  existingParameters: EnhancedParameter[]
): NewParameterValidationResult => {
  const key = rawKey.trim()

  if (!key) {
    return { ok: false, reason: 'empty', key }
  }

  if (existingParameters.some(param => param.key === key)) {
    return { ok: false, reason: 'duplicate', key }
  }

  return { ok: true, key }
}

const applyManualNewParamConfig = (param: EnhancedParameter, config: NewParamConfig) => {
  param.valueMode = ParameterTemplateType.MANUAL
  param.selectedTemplate = 'manual'
  param.value = config.value
  param.isDynamic = false
}

const applyPropertyNewParamConfig = (param: EnhancedParameter, config: NewParamConfig) => {
  param.valueMode = ParameterTemplateType.COMPONENT
  param.selectedTemplate = 'component-property-binding'
  param.value = config.propertyBinding || ''
  param.isDynamic = true
}

const applyDeviceNewParamConfig = (param: EnhancedParameter, config: NewParamConfig) => {
  param.valueMode = ParameterTemplateType.COMPONENT
  param.selectedTemplate = DEVICE_CONFIG_TEMPLATE_ID
  param.value = config.deviceConfig || ''
  param.isDynamic = true
}

const applyNewParamConfigType = (param: EnhancedParameter, config: NewParamConfig) => {
  switch (config.configType) {
    case 'manual':
      applyManualNewParamConfig(param, config)
      break
    case 'property':
      applyPropertyNewParamConfig(param, config)
      break
    case 'device':
      applyDeviceNewParamConfig(param, config)
      break
  }
}

export const buildNewParamFromDrawerConfig = (config: NewParamConfig, key: string) => {
  const newParam = createDefaultParameter()
  newParam.key = key
  newParam.description = config.description || `${newParam.key}参数`
  applyNewParamConfigType(newParam, config)
  return newParam
}

export const createManualAddOptionParameter = () => {
  const newParam = createDefaultParameter()
  newParam.selectedTemplate = 'manual'
  newParam.valueMode = ParameterTemplateType.MANUAL
  return newParam
}

export const createPropertyAddOptionParameter = () => {
  const newParam = createDefaultParameter()
  newParam.selectedTemplate = 'component-property-binding'
  newParam.valueMode = ParameterTemplateType.COMPONENT
  newParam.isDynamic = true
  return newParam
}

/**
 * 文件说明：
 * - 集中维护 DynamicParameterEditor 参数列表行级操作的纯函数。
 * - 包括参数增删改、key 实时输入、value 更新、重复 key 校验、编辑索引计划和渲染前稳定 ID 补齐。
 * 维护提示：
 * - 这里只返回新的参数数组或校验结果，不直接调用 emit、message、logger、nextTick。
 * - key 自动重置规则会影响用户输入体验，修改前要同步检查 blur 校验和重复 key 提示。
 * 审查建议：
 * - 后续可补单元测试覆盖删除正在编辑项、追加后聚焦、重复 key 重置、旧配置缺少 `_id` 时的归一化。
 */
import type { EnhancedParameter } from '@/core/data-architecture/types/parameter-editor'
import { createStableParameterId, inferParameterDynamicState } from './dynamicParameterEditorState'

export type ParameterKeyValidationResult =
  | { ok: true }
  | { ok: false; defaultKey: string; duplicateKey?: string }

export const removeParameterAt = (parameters: EnhancedParameter[], index: number) =>
  parameters.filter((_, paramIndex) => paramIndex !== index)

export const getEditingIndexAfterRemoval = (currentEditingIndex: number, removedIndex: number) => {
  if (currentEditingIndex === removedIndex) {
    return -1
  }

  if (removedIndex < currentEditingIndex) {
    return currentEditingIndex - 1
  }

  return currentEditingIndex
}

export const getFirstAppendedFocusIndex = (finalLength: number, appendedCount: number) => {
  if (appendedCount <= 0) {
    return null
  }

  return finalLength - appendedCount
}

export const updateParameterAt = (parameters: EnhancedParameter[], index: number, param: EnhancedParameter) => {
  const updatedParams = [...parameters]
  updatedParams[index] = { ...param }
  return updatedParams
}

export const updateParameterKeyAt = (
  parameters: EnhancedParameter[],
  index: number,
  param: EnhancedParameter,
  key: string
) => updateParameterAt(parameters, index, { ...param, key })

export const updateParameterValueAt = (
  parameters: EnhancedParameter[],
  index: number,
  param: EnhancedParameter,
  value: string
) => updateParameterAt(parameters, index, { ...param, value })

export const createDefaultParameterKey = (index: number) => `param${index + 1}`

export const isDuplicateParameterKey = (parameters: EnhancedParameter[], key: string, index: number) =>
  parameters.some((param, paramIndex) => paramIndex !== index && param.key === key)

export const validateExistingParameterKey = (
  parameters: EnhancedParameter[],
  param: EnhancedParameter,
  index: number
): ParameterKeyValidationResult => {
  const trimmedKey = param.key?.trim() || ''
  const defaultKey = createDefaultParameterKey(index)

  if (!trimmedKey) {
    return { ok: false, defaultKey }
  }

  if (isDuplicateParameterKey(parameters, trimmedKey, index)) {
    return { ok: false, defaultKey, duplicateKey: trimmedKey }
  }

  return { ok: true }
}

export const normalizeRenderedParameter = (param: EnhancedParameter, index: number): EnhancedParameter => ({
  ...param,
  isDynamic: inferParameterDynamicState(param),
  _id: param._id || createStableParameterId(index)
})

export const ensureParameterHasId = (param: EnhancedParameter, index: number): EnhancedParameter =>
  param._id ? param : normalizeRenderedParameter(param, index)

/**
 * 文件说明:
 * - 集中维护 DynamicParameterEditor 的参数模板切换纯逻辑。
 * - 包括统一设备配置模板识别、模板默认值应用、模板变化动作计划和下拉模板能力查询。
 * 维护提示:
 * - 这里不打开抽屉、不触发 emit，也不读取 Vue props；调用方根据 TemplateChangePlan 决定 UI 行为。
 * - 组件模板默认值不能无条件覆盖已有绑定路径，否则会破坏已保存的组件属性绑定。
 */
import type { EnhancedParameter } from '@/core/data-architecture/types/parameter-editor'
import { generateVariableName } from '@/core/data-architecture/types/http-config'
import {
  getTemplateById,
  ParameterTemplateType,
  type ParameterTemplate
} from '@/core/data-architecture/components/common/templates/index'
import { DEVICE_CONFIG_TEMPLATE_ID } from './dynamicParameterEditorState'

export type TemplateParameterNextAction = 'commit' | 'open-component-editor'

export type TemplateChangePlan =
  | { action: 'noop' }
  | { action: 'open-unified-device-config' }
  | { action: 'commit'; updatedParam: EnhancedParameter }
  | { action: 'open-component-editor'; updatedParam: EnhancedParameter }

type ParameterType = 'header' | 'query' | 'path'

const PARAMETER_TYPE_DISPLAY_NAME: Record<ParameterType, string> = {
  header: '请求头',
  query: '查询',
  path: '路径'
}

export const isUnifiedDeviceConfigTemplate = (templateId: string) => templateId === DEVICE_CONFIG_TEMPLATE_ID

const applyTemplateDefaultValue = (updatedParam: EnhancedParameter, template: ParameterTemplate) => {
  if (template.type === ParameterTemplateType.COMPONENT) {
    if (!updatedParam.value && template.defaultValue !== undefined) {
      updatedParam.value = template.defaultValue
    }

    if (template.defaultValue !== undefined && !updatedParam.defaultValue) {
      updatedParam.defaultValue = template.defaultValue
    }
    return
  }

  if (template.defaultValue !== undefined) {
    updatedParam.value = template.defaultValue
  }
}

const applyPropertyTemplateMetadata = (
  updatedParam: EnhancedParameter,
  sourceParam: EnhancedParameter,
  parameterType: ParameterType
) => {
  if (sourceParam.key) {
    updatedParam.variableName = generateVariableName(sourceParam.key)
    updatedParam.description = updatedParam.description || `${PARAMETER_TYPE_DISPLAY_NAME[parameterType]}参数：${sourceParam.key}`
  }
  updatedParam.isDynamic = true
}

const applyStaticTemplateMetadata = (updatedParam: EnhancedParameter) => {
  updatedParam.variableName = ''
  updatedParam.description = ''
  updatedParam.isDynamic = false
}

const applyTemplateMetadata = (
  updatedParam: EnhancedParameter,
  sourceParam: EnhancedParameter,
  template: ParameterTemplate,
  parameterType: ParameterType
): TemplateParameterNextAction => {
  if (template.type === ParameterTemplateType.PROPERTY) {
    applyPropertyTemplateMetadata(updatedParam, sourceParam, parameterType)
    return 'commit'
  }

  if (template.type === ParameterTemplateType.COMPONENT) {
    updatedParam.isDynamic = true
    return 'open-component-editor'
  }

  applyStaticTemplateMetadata(updatedParam)
  return 'commit'
}

export const prepareTemplateParameterUpdate = (
  param: EnhancedParameter,
  templateId: string,
  template: ParameterTemplate,
  parameterType: ParameterType
) => {
  const updatedParam: EnhancedParameter = {
    ...param,
    selectedTemplate: templateId,
    valueMode: template.type as EnhancedParameter['valueMode']
  }

  applyTemplateDefaultValue(updatedParam, template)
  const nextAction = applyTemplateMetadata(updatedParam, param, template, parameterType)

  return { updatedParam, nextAction }
}

export const buildTemplateChangePlan = (
  param: EnhancedParameter,
  templateId: string,
  parameterType: ParameterType
): TemplateChangePlan => {
  if (isUnifiedDeviceConfigTemplate(templateId)) {
    return { action: 'open-unified-device-config' }
  }

  const template = getTemplateById(templateId)
  if (!template) {
    return { action: 'noop' }
  }

  const { updatedParam, nextAction } = prepareTemplateParameterUpdate(param, templateId, template, parameterType)
  if (nextAction === 'open-component-editor') {
    return { action: 'open-component-editor', updatedParam }
  }

  return { action: 'commit', updatedParam }
}

export const getCurrentTemplateOptions = (param: EnhancedParameter) => {
  if (param.valueMode !== ParameterTemplateType.DROPDOWN || !param.selectedTemplate) return []
  const template = getTemplateById(param.selectedTemplate)
  return template?.options || []
}

export const isCustomInputAllowed = (param: EnhancedParameter) => {
  if (param.valueMode !== ParameterTemplateType.DROPDOWN || !param.selectedTemplate) return false
  const template = getTemplateById(param.selectedTemplate)
  return template?.allowCustom || false
}

/**
 * 文件用途: 覆盖 DynamicParameterEditor 参数 helper 的纯函数契约。
 * 核心逻辑: 验证 API 模板 seed、过滤、构建和按 key 合并行为。
 * 关键注意事项: 这些测试不挂载 Vue 组件，专门保护数据架构参数合并语义。
 * 重构建议: 若后续拆出设备参数合并，应新增独立测试文件，避免混入 API 模板契约。
 */
import { describe, expect, it } from 'vitest'

import type { EnhancedParameter } from '@/core/data-architecture/types/parameter-editor'
import {
  buildApiTemplateParameters,
  filterApiTemplateParams,
  mergeTemplateParameters,
  resolveApiTemplateSeedValue,
  type ApiTemplateInfo
} from './parameter-editor-helpers'

const createDefaultParameter = (overrides: Partial<EnhancedParameter> = {}): EnhancedParameter => ({
  key: 'placeholder',
  value: '',
  enabled: true,
  isDynamic: false,
  valueMode: 'manual',
  selectedTemplate: 'manual',
  dataType: 'string',
  variableName: '',
  description: '',
  _id: `id-${overrides.key || 'placeholder'}`,
  ...overrides
})

describe('parameter-editor-helpers', () => {
  it('resolves API template seed values without dropping falsy examples', () => {
    expect(resolveApiTemplateSeedValue({ example: 0, defaultValue: 10 })).toBe(0)
    expect(resolveApiTemplateSeedValue({ example: false, defaultValue: true })).toBe(false)
    expect(resolveApiTemplateSeedValue({ example: '', defaultValue: 'fallback' })).toBe('')
    expect(resolveApiTemplateSeedValue({ defaultValue: 'defaulted' })).toBe('defaulted')
    expect(resolveApiTemplateSeedValue({})).toBe('')
  })

  it('filters API template params by query, path, and header context', () => {
    const apiInfo: ApiTemplateInfo = {
      url: '/api/devices/:deviceId/telemetry',
      pathParamNames: ['deviceId'],
      commonParams: [
        { name: 'deviceId', type: 'string' },
        { name: 'page', type: 'number' },
        { name: 'X-Trace-Id', type: 'string', paramType: 'header' },
        { name: 'Authorization', type: 'string', in: 'header' }
      ]
    }

    expect(filterApiTemplateParams(apiInfo, 'query').map(param => param.name)).toEqual(['page'])
    expect(filterApiTemplateParams(apiInfo, 'path').map(param => param.name)).toEqual(['deviceId'])
    expect(filterApiTemplateParams(apiInfo, 'header').map(param => param.name)).toEqual(['X-Trace-Id', 'Authorization'])
  })

  it('builds API template parameters with manual templates, data types, and fallback keys', () => {
    const params = buildApiTemplateParameters(
      {
        url: '/api/devices/:deviceId/telemetry',
        pathParamNames: ['deviceId'],
        commonParams: [
          { name: 'page', type: 'number', description: 'page index', example: 0 },
          { name: 'active', type: 'boolean', description: 'active flag', example: false },
          { name: 'payload', type: 'object', defaultValue: '' }
        ]
      },
      'query',
      () => createDefaultParameter()
    )

    expect(params).toEqual([
      expect.objectContaining({
        key: 'page',
        value: 0,
        defaultValue: 0,
        dataType: 'number',
        valueMode: 'manual',
        selectedTemplate: 'manual'
      }),
      expect.objectContaining({
        key: 'active',
        value: false,
        defaultValue: false,
        dataType: 'boolean'
      }),
      expect.objectContaining({
        key: 'payload',
        value: '',
        defaultValue: '',
        dataType: 'string'
      })
    ])

    expect(
      buildApiTemplateParameters({ url: '/api/group/current', commonParams: [] }, 'query', () =>
        createDefaultParameter()
      )
    ).toEqual([expect.objectContaining({ key: 'groupId', description: '分组ID', valueMode: 'manual' })])
  })

  it('merges template parameters by key while preserving existing ids and unrelated metadata', () => {
    const deviceContext = { sourceType: 'device-selection' as const, timestamp: 1000 }
    const parameterGroup = { groupId: 'group-1', role: 'primary' as const, isDerived: false }
    const existingDeviceParam = createDefaultParameter({
      key: 'deviceId',
      value: 'original-device',
      _id: 'keep-device-id',
      deviceContext,
      parameterGroup
    })
    const existingPageParam = createDefaultParameter({
      key: 'page',
      value: 'old-page',
      _id: 'keep-page-id'
    })
    const templatePageParam = createDefaultParameter({
      key: 'page',
      value: 1,
      defaultValue: 1,
      dataType: 'number',
      _id: 'template-page-id'
    })
    const templateActiveParam = createDefaultParameter({
      key: 'active',
      value: false,
      defaultValue: false,
      dataType: 'boolean',
      _id: 'template-active-id'
    })

    const merged = mergeTemplateParameters(
      [existingDeviceParam, existingPageParam],
      [templatePageParam, templateActiveParam]
    )

    expect(merged).toEqual([
      existingDeviceParam,
      expect.objectContaining({
        key: 'page',
        value: 1,
        defaultValue: 1,
        _id: 'keep-page-id'
      }),
      templateActiveParam
    ])
    expect(merged[0]).toBe(existingDeviceParam)
    expect(merged[0].deviceContext).toBe(deviceContext)
    expect(merged[0].parameterGroup).toBe(parameterGroup)
  })
})

/**
 * 文件用途: 提供 DynamicParameterEditor 的纯参数合并辅助函数。
 * 核心逻辑: 从 API 模板元数据构造参数，并按 key 合并到现有参数列表。
 * 关键注意事项: API 模板种子值允许 0、false 和空字符串，合并时必须保留既有参数 _id。
 * 重构建议: 后续可继续把设备参数合并与表单校验拆到独立 helper。
 */
import type { EnhancedParameter } from '@/core/data-architecture/types/parameter-editor'

export type ApiTemplateParameterType = 'header' | 'query' | 'path'

export type ApiTemplateParamSource = Record<string, any> & {
  name: string
  description?: string
  type?: string
  paramType?: string
  location?: string
  in?: string
  example?: any
  defaultValue?: any
}

export type ApiTemplateInfo = {
  url: string
  commonParams?: ApiTemplateParamSource[]
  pathParamNames?: string[]
}

export type CreateDefaultParameter = () => EnhancedParameter

export const resolveApiTemplateSeedValue = (param: Pick<ApiTemplateParamSource, 'example' | 'defaultValue'>) => {
  return param.example ?? param.defaultValue ?? ''
}

const isHeaderParam = (param: ApiTemplateParamSource) =>
  param.type === 'header' || param.paramType === 'header' || param.location === 'header' || param.in === 'header'

export const filterApiTemplateParams = (
  apiInfo: Pick<ApiTemplateInfo, 'commonParams' | 'pathParamNames'>,
  parameterType: ApiTemplateParameterType
) => {
  const commonParams = apiInfo.commonParams || []
  const pathParamNames = apiInfo.pathParamNames || []

  if (parameterType === 'query') {
    return commonParams.filter(param => !pathParamNames.includes(param.name) && !isHeaderParam(param))
  }

  if (parameterType === 'path') {
    return commonParams.filter(param => pathParamNames.includes(param.name))
  }

  if (parameterType === 'header') {
    return commonParams.filter(isHeaderParam)
  }

  return commonParams
}

const resolveApiTemplateDataType = (type: string | undefined): EnhancedParameter['dataType'] => {
  if (type === 'number') return 'number'
  if (type === 'boolean') return 'boolean'
  return 'string'
}

const buildFallbackTemplateParameter = (apiInfo: ApiTemplateInfo, createDefaultParameter: CreateDefaultParameter) => {
  const defaultParam = createDefaultParameter()

  if (apiInfo.url.includes('device')) {
    defaultParam.key = 'deviceId'
    defaultParam.description = '设备ID'
  } else if (apiInfo.url.includes('group')) {
    defaultParam.key = 'groupId'
    defaultParam.description = '分组ID'
  } else if (apiInfo.url.includes('user')) {
    defaultParam.key = 'userId'
    defaultParam.description = '用户ID'
  } else {
    defaultParam.key = 'id'
    defaultParam.description = '标识符'
  }

  defaultParam.selectedTemplate = 'manual'
  defaultParam.valueMode = 'manual'
  return defaultParam
}

export const buildApiTemplateParameters = (
  apiInfo: ApiTemplateInfo,
  parameterType: ApiTemplateParameterType,
  createDefaultParameter: CreateDefaultParameter
) => {
  if (apiInfo.commonParams && apiInfo.commonParams.length > 0) {
    return filterApiTemplateParams(apiInfo, parameterType).map(param => {
      const enhancedParam = createDefaultParameter()
      const seededValue = resolveApiTemplateSeedValue(param)
      enhancedParam.key = param.name
      enhancedParam.description = param.description || `${param.name}参数`
      enhancedParam.dataType = resolveApiTemplateDataType(param.type)
      enhancedParam.selectedTemplate = 'manual'
      enhancedParam.valueMode = 'manual'
      enhancedParam.value = seededValue
      enhancedParam.defaultValue = seededValue
      return enhancedParam
    })
  }

  return [buildFallbackTemplateParameter(apiInfo, createDefaultParameter)]
}

export const mergeTemplateParameters = (existingParams: EnhancedParameter[], templateParams: EnhancedParameter[]) => {
  const existingKeys = new Set(existingParams.map(param => param.key))
  const newParams = templateParams.filter(templateParam => !existingKeys.has(templateParam.key))

  return [
    ...existingParams.map(existingParam => {
      const templateParam = templateParams.find(param => param.key === existingParam.key)
      if (templateParam) {
        return { ...templateParam, _id: existingParam._id }
      }
      return existingParam
    }),
    ...newParams
  ]
}

