describe('MultiLayerExecutorChain examples', () => {
  it('validates the bundled JSON example configuration', () => {
    const executorChain = new MultiLayerExecutorChain()

    expect(executorChain.validateConfiguration(createJsonExampleConfig())).toBe(true)
  })

  it('exposes supported executor chain capabilities', () => {
    const executorChain = new MultiLayerExecutorChain()
    const statistics = executorChain.getChainStatistics()

    expect(statistics.supportedDataTypes).toContain('json')
    expect(statistics.supportedMergeStrategies).toContain('object')
  })

  it('processes JSON data through the full chain and returns merged component data', async () => {
    const executorChain = new MultiLayerExecutorChain()
    const config = createJsonExampleConfig()

    const result = await executorChain.executeDataProcessingChain(config, true)

    expect(result.success).toBe(true)
    expect(result.componentData).toBeDefined()
    // ComponentData 按 sourceId 分桶：json-source-1 是 object 合并后的 user+product。
    // object 合并是浅层键覆盖：product.name='商品A' 覆盖 user.name='张三'。
    expect(result.componentData['json-source-1'].type).toBe('json')
    expect(result.componentData['json-source-1'].data).toMatchObject({
      name: '商品A',
      age: 25,
      hobbies: ['读书', '游泳'],
      price: 199
    })
    expect(result.componentData['json-source-1'].metadata.success).toBe(true)
    // json-source-2 是 array 合并：$[0] 单元素被包装进数组。
    expect(result.componentData['json-source-2'].type).toBe('json')
    expect(Array.isArray(result.componentData['json-source-2'].data)).toBe(true)
    expect(result.componentData['json-source-2'].data[0]).toMatchObject({ id: 1, name: '项目1' })
    expect(result.executionState).toBeDefined()
    expect(result.executionState?.stages.rawData.size).toBeGreaterThan(0)
    expect(result.executionState?.stages.processedData.size).toBeGreaterThan(0)
    expect(result.executionState?.stages.mergedData).not.toBeNull()
    expect(result.executionState?.stages.finalData).not.toBeNull()
  })

  it('completes the chain when script merge strategy is used and degrades on script engine limits', async () => {
    const executorChain = new MultiLayerExecutorChain()
    const config = createScriptMergeExampleConfig()

    const result = await executorChain.executeDataProcessingChain(config, false)

    expect(result.success).toBe(true)
    // script 合并策略依赖 script-engine 在测试上下文中执行用户脚本；
    // 当脚本引擎无法执行复杂脚本时，merger 走 fallback 返回 {}，但整条链不崩溃。
    expect(result.componentData['script-merge-source']).toBeDefined()
    expect(result.componentData['script-merge-source'].type).toBe('json')
  })

  it('marks an empty data source as a failed chain while retaining its diagnostic bucket', async () => {
    const executorChain = new MultiLayerExecutorChain()
    const config = createEmptyDataItemsConfig()

    const result = await executorChain.executeDataProcessingChain(config, false)

    expect(result).toMatchObject({
      success: false,
      errorCode: 'DATA_SOURCE_NO_SUCCESSFUL_ITEMS',
      isEmpty: true
    })
    expect(result.componentData?.['empty-source']).toBeDefined()
    expect(result.componentData?.['empty-source'].data).toBeNull()
    expect(result.componentData?.['empty-source'].metadata.success).toBe(false)
  })

  it('preserves the stable failure code when every source fails', async () => {
    const executorChain = new MultiLayerExecutorChain()
    const config = createInvalidJsonConfig()

    const result = await executorChain.executeDataProcessingChain(config, false)

    expect(result).toMatchObject({ success: false, errorCode: 'JSON_PARSE_ERROR', isEmpty: true })
    expect(result.componentData?.['invalid-json-source']).toBeDefined()
    expect(result.componentData?.['invalid-json-source'].data).toBeNull()
    expect(result.componentData?.['invalid-json-source'].metadata).toMatchObject({
      success: false,
      errorCode: 'JSON_PARSE_ERROR'
    })
  })

  it('keeps partial success when a local source succeeds and WebSocket is external-blocked', async () => {
    const config = createInvalidJsonConfig()
    config.dataSources = [
      {
        sourceId: 'local-source',
        dataItems: [
          {
            item: { type: 'json', config: { jsonString: '{"value":7}' } },
            processing: { filterPath: '$', defaultValue: {} }
          }
        ],
        mergeStrategy: { type: 'object' }
      },
      {
        sourceId: 'stream-source',
        dataItems: [
          {
            item: { type: 'websocket', config: { wsUrl: 'wss://example.test/telemetry' } },
            processing: { filterPath: '$', defaultValue: {} }
          }
        ],
        mergeStrategy: { type: 'object' }
      }
    ]

    const result = await new MultiLayerExecutorChain().executeDataProcessingChain(config, false)

    expect(result.success).toBe(true)
    expect(result.errorCode).toBeUndefined()
    expect(result.componentData?.['local-source'].metadata.success).toBe(true)
    expect(result.componentData?.['stream-source'].metadata).toMatchObject({
      success: false,
      errorCode: 'WS_EXTERNAL_BLOCKED'
    })
  })

  it('rejects configuration missing componentId or dataSources', () => {
    const executorChain = new MultiLayerExecutorChain()

    expect(executorChain.validateConfiguration({ componentId: '', dataSources: [] } as any)).toBe(false)
    expect(
      executorChain.validateConfiguration({
        componentId: 'ok',
        dataSources: [{ sourceId: '', dataItems: [], mergeStrategy: { type: 'object' } }]
      } as any)
    ).toBe(false)
  })
})

/**
 * 文件用途: 多层级执行器链协调器。
 * 核心逻辑: 串联数据项获取、处理、合并和多源整合，完成数据源到组件数据的转换。
 * 关键注意事项: 每层返回结构和错误传播方式会影响组件最终渲染与诊断信息。
 * 重构建议: 将链路编排抽成可观测 pipeline，并为每层建立更明确的接口契约。
 */

import type { DataItem } from '@/core/data-architecture/executors/DataItemFetcher'
import {
  DataItemProcessor,
  ProcessingConfig,
  IDataItemProcessor
} from '@/core/data-architecture/executors/DataItemProcessor'
import { DataSourceMerger, MergeStrategy, IDataSourceMerger } from '@/core/data-architecture/executors/DataSourceMerger'
import {
  MultiSourceIntegrator,
  ComponentData,
  DataSourceResult,
  IMultiSourceIntegrator
} from '@/core/data-architecture/executors/MultiSourceIntegrator'
import { unifiedDataExecutor, type UnifiedDataConfig } from '@/core/data-architecture/UnifiedDataExecutor'
import { shouldSuppressUnmockedTestConsole } from '@/utils/test-console'

function chainWarn(...args: any[]): void {
  if (!shouldSuppressUnmockedTestConsole(console.warn)) console.warn(...args)
}

function chainError(...args: any[]): void {
  if (!shouldSuppressUnmockedTestConsole(console.error)) console.error(...args)
}

/** 在内部抛出时保留统一执行器的稳定错误代码。 */
class DataItemExecutionError extends Error {
  constructor(message: string, readonly code?: string) {
    super(message)
    this.name = 'DataItemExecutionError'
  }
}

/**
 * 数据源配置结构
 */
export interface DataSourceConfiguration {
  componentId: string
  dataSources: Array<{
    sourceId: string
    dataItems: Array<{
      item: DataItem
      processing: ProcessingConfig
    }>
    mergeStrategy: MergeStrategy
  }>
  createdAt: number
  updatedAt: number
}

/**
 * 执行状态跟踪 (用于调试监控)
 */
export interface ExecutionState {
  componentId: string
  dataSourceId: string
  stages: {
    /** 第一层: 原始数据获取结果 */
    rawData: Map<string, { data: any; timestamp: number; success: boolean }>
    /** 第二层: 数据处理结果 */
    processedData: Map<string, { data: any; timestamp: number; success: boolean }>
    /** 第三层: 数据源合并结果 */
    mergedData: { data: any; timestamp: number; success: boolean } | null
    /** 第四层: 最终组件数据 */
    finalData: { data: any; timestamp: number; success: boolean } | null
  }
  debugMode: boolean
  lastExecuted: number
}

/**
 * 执行结果
 */
export interface ExecutionResult {
  /** 是否成功 */
  success: boolean
  /** 组件数据 */
  componentData?: ComponentData
  /** 错误信息 */
  error?: string
  /** 稳定错误代码 */
  errorCode?: string
  /** 是否没有可用组件数据 */
  isEmpty?: boolean
  /** 执行时间（毫秒） */
  executionTime: number
  /** 时间戳 */
  timestamp: number
  /** 调试状态 */
  executionState?: ExecutionState
}

/**
 * 多层级执行器链接口
 */
export interface IMultiLayerExecutorChain {
  /**
   * 执行完整的数据处理管道
   * @param config 数据源配置
   * @param debugMode 是否开启调试模式
   * @returns 执行结果
   */
  executeDataProcessingChain(config: DataSourceConfiguration, debugMode?: boolean): Promise<ExecutionResult>
}

/**
 * 多层级执行器链实现类
 */
export class MultiLayerExecutorChain implements IMultiLayerExecutorChain {
  private dataItemProcessor: IDataItemProcessor
  private dataSourceMerger: IDataSourceMerger
  private multiSourceIntegrator: IMultiSourceIntegrator

  constructor() {
    this.dataItemProcessor = new DataItemProcessor()
    this.dataSourceMerger = new DataSourceMerger()
    this.multiSourceIntegrator = new MultiSourceIntegrator()
  }

  /**
   * 执行完整的数据处理管道
   */
  async executeDataProcessingChain(
    config: DataSourceConfiguration,
    debugMode: boolean = false
  ): Promise<ExecutionResult> {
    const startTime = Date.now()

    try {
      const dataSourceResults: DataSourceResult[] = []
      let executionState: ExecutionState | undefined

      // 初始化调试状态
      if (debugMode) {
        executionState = this.initializeExecutionState(config.componentId)
      }

      // 处理每个数据源
      for (const dataSourceConfig of config.dataSources) {
        if (!dataSourceConfig.dataItems || dataSourceConfig.dataItems.length === 0) {
          chainError('[MultiLayerExecutorChain] Data source has no dataItems.', {
            sourceId: dataSourceConfig.sourceId,
            dataItemsType: typeof dataSourceConfig.dataItems,
            dataItems: dataSourceConfig.dataItems
          })
        }

        try {
          const sourceResult = await this.processDataSource(dataSourceConfig, executionState, config.componentId)

          dataSourceResults.push(sourceResult)
        } catch (error) {
          chainError('[MultiLayerExecutorChain] processDataSource failed:', {
            sourceId: dataSourceConfig.sourceId,
            errorType: typeof error,
            errorMessage: error instanceof Error ? error.message : error,
            errorStack: error instanceof Error ? error.stack : undefined
          })

          dataSourceResults.push({
            sourceId: dataSourceConfig.sourceId,
            type: 'unknown',
            data: {},
            success: false,
            error: error instanceof Error ? error.message : 'Unknown error'
          })
        }
      }

      // 第四层：多源整合
      const componentData = await this.multiSourceIntegrator.integrateDataSources(dataSourceResults, config.componentId)
      const successfulSources = dataSourceResults.filter(source => source.success).length
      const allSourcesFailed = dataSourceResults.length === 0 || successfulSources === 0

      // 更新调试状态
      if (executionState) {
        executionState.stages.finalData = {
          data: componentData,
          timestamp: Date.now(),
          success: Object.keys(componentData).length > 0
        }
        executionState.lastExecuted = Date.now()
      }

      const executionTime = Date.now() - startTime

      const firstFailure = dataSourceResults.find(source => !source.success)

      return {
        success: !allSourcesFailed,
        componentData,
        error: allSourcesFailed ? firstFailure?.error || '所有数据源执行失败' : undefined,
        errorCode: allSourcesFailed ? firstFailure?.errorCode : undefined,
        executionTime,
        timestamp: Date.now(),
        executionState,
        isEmpty: allSourcesFailed
      }
    } catch (error) {
      const executionTime = Date.now() - startTime

      return {
        success: false,
        error: error instanceof Error ? error.message : 'Executor chain failed',
        executionTime,
        timestamp: Date.now()
      }
    }
  }

  /**
   * 处理单个数据源
   */
  private async processDataSource(
    dataSourceConfig: {
      sourceId: string
      dataItems: Array<{ item: DataItem; processing: ProcessingConfig }>
      mergeStrategy: MergeStrategy
    },
    executionState?: ExecutionState,
    componentId?: string
  ): Promise<DataSourceResult> {
    try {
      const processedItems: any[] = []
      let successfulItems = 0
      let firstItemError: DataItemExecutionError | undefined

      if (dataSourceConfig.dataItems.length === 0) {
        chainWarn('[MultiLayerExecutorChain] dataItems is empty; no data fetch will run.', {
          sourceId: dataSourceConfig.sourceId
        })
      }

      // 处理每个数据项
      for (let i = 0; i < dataSourceConfig.dataItems.length; i++) {
        const { item, processing } = dataSourceConfig.dataItems[i]
        const itemId = `${dataSourceConfig.sourceId}_item_${i}`

        try {
          if (item.type === 'http' && item.config) {
            const allParams = [
              ...(item.config.params || []),
              ...(item.config.parameters || []),
              ...(item.config.pathParams || [])
            ]

            allParams.forEach((param, paramIndex) => {
              if (param.value && typeof param.value === 'string') {
                const isSuspiciousPath = !param.value.includes('.') && param.value.length < 10 && param.variableName

                if (isSuspiciousPath) {
                  chainError('[MultiLayerExecutorChain] Suspicious binding path before fetchData.', {
                    componentId: componentId || 'unknown',
                    sourceId: dataSourceConfig.sourceId,
                    paramIndex,
                    key: param.key,
                    value: param.value,
                    variableName: param.variableName,
                    param: JSON.stringify(param, null, 2)
                  })
                }
              }
            })
          }

          const rawData = await this.fetchRawData(item, dataSourceConfig.sourceId, i)
          successfulItems += 1

          // 更新调试状态
          if (executionState) {
            executionState.stages.rawData.set(itemId, {
              data: rawData,
              timestamp: Date.now(),
              success: Object.keys(rawData || {}).length > 0
            })
          }

          // 第二层：数据项处理
          const processedData = await this.dataItemProcessor.processData(rawData, processing)

          // 更新调试状态
          if (executionState) {
            executionState.stages.processedData.set(itemId, {
              data: processedData,
              timestamp: Date.now(),
              success: Object.keys(processedData || {}).length > 0
            })
          }

          processedItems.push(processedData)
        } catch (error) {
          chainError('[MultiLayerExecutorChain] Data item processing failed:', {
            itemId,
            itemType: item.type,
            itemIndex: i,
            errorType: typeof error,
            errorMessage: error instanceof Error ? error.message : error,
            errorStack: error instanceof Error ? error.stack : undefined,
            itemConfig: item.config
          })
          if (!firstItemError) {
            firstItemError =
              error instanceof DataItemExecutionError
                ? error
                : new DataItemExecutionError(error instanceof Error ? error.message : String(error))
          }
          processedItems.push(null)
        }
      }

      // 第三层：数据源合并
      const mergedData = await this.dataSourceMerger.mergeDataItems(processedItems, dataSourceConfig.mergeStrategy)

      // 更新调试状态
      if (executionState) {
        executionState.stages.mergedData = {
          data: mergedData,
          timestamp: Date.now(),
          success: Object.keys(mergedData || {}).length > 0
        }
      }

      return {
        sourceId: dataSourceConfig.sourceId,
        type: dataSourceConfig.dataItems[0]?.item.type || 'unknown',
        data: successfulItems > 0 ? mergedData : null,
        success: successfulItems > 0,
        error: successfulItems === 0 ? firstItemError?.message || '数据源没有可执行的数据项' : undefined,
        errorCode: successfulItems === 0 ? firstItemError?.code || 'DATA_SOURCE_NO_SUCCESSFUL_ITEMS' : undefined
      }
    } catch (error) {
      return {
        sourceId: dataSourceConfig.sourceId,
        type: 'unknown',
        data: {},
        success: false,
        error: error instanceof Error ? error.message : '数据源处理失败'
      }
    }
  }

  private async fetchRawData(item: DataItem, sourceId: string, index: number): Promise<any> {
    const config: UnifiedDataConfig = {
      id: `${sourceId}_${index}`,
      type: item.type as UnifiedDataConfig['type'],
      config: this.normalizeUnifiedConfig(item.config)
    }
    const result = await unifiedDataExecutor.execute(config)

    if (!result.success) {
      throw new DataItemExecutionError(result.error || `Data item ${config.id} execution failed`, result.errorCode)
    }

    return result.data
  }

  private normalizeUnifiedConfig(config: Record<string, any> = {}): Record<string, any> {
    return {
      ...config,
      jsonContent: config.jsonContent ?? config.jsonString
    }
  }

  /**
   * 初始化执行状态
   */
  private initializeExecutionState(componentId: string): ExecutionState {
    return {
      componentId,
      dataSourceId: '',
      stages: {
        rawData: new Map(),
        processedData: new Map(),
        mergedData: null,
        finalData: null
      },
      debugMode: true,
      lastExecuted: 0
    }
  }

  /**
   * 验证数据源配置
   */
  validateConfiguration(config: DataSourceConfiguration): boolean {
    if (!config.componentId || !config.dataSources) {
      return false
    }

    // 允许数据项数组为空，这样可以返回 null 数据
    return config.dataSources.every((ds) => ds.sourceId && Array.isArray(ds.dataItems) && ds.mergeStrategy)
  }

  /**
   * 获取执行器链统计信息
   */
  getChainStatistics(): {
    version: string
    supportedDataTypes: string[]
    supportedMergeStrategies: string[]
    features: string[]
  } {
    return {
      version: '1.0.0',
      supportedDataTypes: ['json', 'http', 'websocket', 'script'],
      supportedMergeStrategies: ['object', 'array', 'select', 'script'],
      features: [
        'JSONPath数据过滤',
        '自定义脚本处理',
        '多种合并策略',
        '调试监控机制',
        'Visual Editor兼容',
        'Card2.1兼容'
      ]
    }
  }
}

import { afterEach, describe, expect, it, vi } from 'vitest'

import { MultiSourceIntegrator, type DataSourceResult } from './MultiSourceIntegrator'

describe('MultiSourceIntegrator', () => {
  afterEach(() => {
    vi.useRealTimers()
  })

  it('integrates successful and failed sources with one consistent timestamp', async () => {
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2026-08-05T12:34:56.789Z'))
    const integrator = new MultiSourceIntegrator()

    const result = await integrator.integrateDataSources(
      [
        { sourceId: 'sensor', type: 'json', data: { value: 26 }, success: true },
        { sourceId: 'external', type: 'websocket', data: { stale: true }, success: false, error: 'WS_EXTERNAL_BLOCKED' }
      ],
      'card-1'
    )

    expect(result.sensor).toEqual({
      type: 'json',
      data: { value: 26 },
      lastUpdated: Date.now(),
      metadata: {
        componentId: 'card-1',
        success: true,
        error: undefined,
        processedAt: '2026-08-05T12:34:56.789Z'
      }
    })
    expect(result.external).toEqual({
      type: 'websocket',
      data: null,
      lastUpdated: Date.now(),
      metadata: {
        componentId: 'card-1',
        success: false,
        error: 'WS_EXTERNAL_BLOCKED',
        processedAt: '2026-08-05T12:34:56.789Z'
      }
    })
  })

  it('does not expose the successful source payload by reference', async () => {
    const integrator = new MultiSourceIntegrator()
    const payload = { nested: { value: 1 } }

    const result = await integrator.integrateDataSources(
      [{ sourceId: 'sensor', type: 'json', data: payload, success: true }],
      'card-1'
    )

    result.sensor.data.nested.value = 2

    expect(payload).toEqual({ nested: { value: 1 } })
  })

  it.each(['', '__proto__', 'prototype', 'constructor'])('skips the unsafe source id %j', async sourceId => {
    const integrator = new MultiSourceIntegrator()
    const source: DataSourceResult = { sourceId, type: 'json', data: { polluted: true }, success: true }

    const result = await integrator.integrateDataSources([source], 'card-1')

    expect(result).toEqual({})
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype)
    expect(integrator.validateDataSourceResult(source)).toBe(false)
  })

  it('merges only newer safe updates without exposing the update entry by reference', () => {
    const integrator = new MultiSourceIntegrator()
    const existing = {
      sensor: { type: 'json', data: { value: 1 }, lastUpdated: 10 }
    }
    const newerUpdate = { type: 'json', data: { value: 2 }, lastUpdated: 20 }
    const updates = {
      sensor: newerUpdate,
      stale: { type: 'json', data: { value: 3 }, lastUpdated: 5 }
    }

    const result = integrator.mergeComponentData(existing, updates)
    result.sensor.data.value = 99

    expect(newerUpdate.data).toEqual({ value: 2 })
    expect(existing.sensor.data).toEqual({ value: 1 })
    expect(result.stale).toEqual(updates.stale)
  })

  it.each(['__proto__', 'prototype', 'constructor'])('skips the unsafe incremental source id %s', sourceId => {
    const integrator = new MultiSourceIntegrator()
    const updates = Object.create(null)
    updates[sourceId] = { type: 'json', data: { polluted: true }, lastUpdated: 20 }

    const result = integrator.mergeComponentData({}, updates)

    expect(result).toEqual({})
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype)
  })

  it('cleans expired and unsafe entries without exposing retained data by reference', () => {
    vi.useFakeTimers()
    vi.setSystemTime(1_000)
    const integrator = new MultiSourceIntegrator()
    const componentData = Object.create(null)
    componentData.current = { type: 'json', data: { value: 1 }, lastUpdated: 900 }
    componentData.expired = { type: 'json', data: { value: 2 }, lastUpdated: 100 }
    componentData.prototype = { type: 'json', data: { polluted: true }, lastUpdated: 900 }

    const result = integrator.cleanupExpiredData(componentData, 200)
    result.current.data.value = 99

    expect(result).toEqual({ current: { type: 'json', data: { value: 99 }, lastUpdated: 900 } })
    expect(componentData.current.data).toEqual({ value: 1 })
  })

  it('creates an isolated Visual Editor payload and skips unsafe source ids', () => {
    const integrator = new MultiSourceIntegrator()
    const componentData = Object.create(null)
    componentData.sensor = { type: 'json', data: { value: 1 }, lastUpdated: 10 }
    componentData.constructor = { type: 'json', data: { polluted: true }, lastUpdated: 10 }

    const result = integrator.toVisualEditorFormat(componentData)
    result.sensor.value = 99

    expect(result).toEqual({ sensor: { value: 99 } })
    expect(componentData.sensor.data).toEqual({ value: 1 })
  })

  it('serializes safe Card 2.1 sources independently and skips circular or unsafe entries', () => {
    const integrator = new MultiSourceIntegrator()
    const circular: Record<string, any> = {}
    circular.self = circular
    const componentData = Object.create(null)
    componentData.sensor = { type: 'json', data: { value: 1 }, lastUpdated: 10 }
    componentData.circular = { type: 'json', data: circular, lastUpdated: 10 }
    componentData.__proto__ = { type: 'json', data: { polluted: true }, lastUpdated: 10 }

    expect(integrator.toCard21Format(componentData)).toEqual({
      rawDataSources: {
        dataSourceBindings: {
          sensor: { rawData: '{"value":1}' }
        }
      }
    })
  })
})

/**
 * 文件用途: 数据源执行链第四层多源整合器。
 * 核心逻辑: 将多个 DataSourceResult 按 key 整合为组件最终 ComponentData。
 * 关键注意事项: sourceId、success/error 和 lastUpdated 字段会影响组件数据可见性与错误展示。
 * 重构建议: 抽出成功/失败结果 normalize，并补重复 sourceId、失败源和空源列表测试。
 */

import { smartDeepClone } from '@/utils/deep-clone'

const FORBIDDEN_SOURCE_IDS = new Set(['__proto__', 'prototype', 'constructor'])

function isSafeSourceId(sourceId: unknown): sourceId is string {
  return typeof sourceId === 'string' && sourceId.length > 0 && !FORBIDDEN_SOURCE_IDS.has(sourceId)
}

export interface ComponentData {
  [dataSourceKey: string]: {
    /** 数据源类型 */
    type: string
    /** 解析后的数据 */
    data: any
    /** 最后更新时间 */
    lastUpdated: number
    /** 元数据 */
    metadata?: any
  }
}

export interface DataSourceResult {
  /** 数据源ID */
  sourceId: string
  /** 数据源类型 */
  type: string
  /** 合并后的数据 */
  data: any
  /** 是否成功 */
  success: boolean
  /** 错误信息 */
  error?: string
  /** 稳定错误代码，供上层区分外部阻断、配置错误和执行失败。 */
  errorCode?: string
}

/**
 * 多源整合器接口
 */
export interface IMultiSourceIntegrator {
  /**
   * 按key整合多数据源
   * @param sources 数据源结果列表
   * @param componentId 组件ID
   * @returns 组件最终数据，出错时返回空ComponentData
   */
  integrateDataSources(sources: DataSourceResult[], componentId: string): Promise<ComponentData>
}

/**
 * 多源整合器实现类
 */
export class MultiSourceIntegrator implements IMultiSourceIntegrator {
  /**
   * 多数据源整合主方法
   */
  async integrateDataSources(sources: DataSourceResult[], componentId: string): Promise<ComponentData> {
    try {
      const result: ComponentData = {}
      const timestamp = Date.now()
      const processedAt = new Date(timestamp).toISOString()

      for (const source of sources) {
        if (!this.validateDataSourceResult(source)) {
          continue
        }

        result[source.sourceId] = {
          type: source.type || 'unknown',
          // 整合结果拥有独立数据快照，避免调用方修改结果后反向污染执行层输入。
          data: source.success ? smartDeepClone(source.data) : null,
          lastUpdated: timestamp,
          metadata: {
            componentId,
            success: source.success,
            error: source.error,
            errorCode: source.errorCode,
            processedAt
          }
        }
      }

      return Object.keys(result).length === 0 ? {} : result
    } catch (_error) {
      return {} // 统一错误处理：返回空ComponentData
    }
  }

  /**
   * 验证数据源结果的有效性，并拒绝会影响普通对象原型的保留键。
   */
  validateDataSourceResult(source: DataSourceResult): boolean {
    return !!(source && isSafeSourceId(source.sourceId) && source.type !== undefined)
  }

  /**
   * 获取组件数据统计信息
   */
  getDataStatistics(componentData: ComponentData): {
    totalSources: number
    successfulSources: number
    failedSources: number
    lastUpdated: number
  } {
    const sources = Object.entries(componentData)
    const successful = sources.filter(([_, data]) => data.metadata?.success !== false)
    const failed = sources.filter(([_, data]) => data.metadata?.success === false)
    const lastUpdated = Math.max(...sources.map(([_, data]) => data.lastUpdated), 0)

    return {
      totalSources: sources.length,
      successfulSources: successful.length,
      failedSources: failed.length,
      lastUpdated
    }
  }

  /**
   * 检查组件数据是否有效
   */
  isValidComponentData(componentData: ComponentData): boolean {
    if (!componentData || typeof componentData !== 'object') {
      return false
    }

    // 至少要有一个数据源
    const sourceKeys = Object.keys(componentData)
    if (sourceKeys.length === 0) {
      return false
    }

    // 检查每个数据源的结构
    return sourceKeys.every(key => {
      const source = componentData[key]
      return (
        source && typeof source.type === 'string' && typeof source.lastUpdated === 'number' && source.data !== undefined
      )
    })
  }

  /**
   * 合并多个 ComponentData，用时间戳选择更新，并隔离输入对象引用。
   */
  mergeComponentData(existing: ComponentData, updates: ComponentData): ComponentData {
    const result: ComponentData = {}

    for (const [sourceId, sourceData] of Object.entries(existing)) {
      if (isSafeSourceId(sourceId)) {
        result[sourceId] = smartDeepClone(sourceData)
      }
    }

    for (const [sourceId, sourceData] of Object.entries(updates)) {
      if (!isSafeSourceId(sourceId)) {
        continue
      }

      const existingData = result[sourceId]
      if (!existingData || existingData.lastUpdated < sourceData.lastUpdated) {
        result[sourceId] = smartDeepClone(sourceData)
      }
    }

    return result
  }

  /**
   * 清理过期或危险键的数据源，并返回与输入隔离的快照。
   */
  cleanupExpiredData(componentData: ComponentData, maxAge: number = 5 * 60 * 1000): ComponentData {
    const now = Date.now()
    const result: ComponentData = {}

    for (const [sourceId, sourceData] of Object.entries(componentData)) {
      if (isSafeSourceId(sourceId) && now - sourceData.lastUpdated <= maxAge) {
        result[sourceId] = smartDeepClone(sourceData)
      }
    }

    return result
  }

  /**
   * 转换为 Visual Editor 兼容格式，并返回安全键组成的独立 payload 快照。
   */
  toVisualEditorFormat(componentData: ComponentData): Record<string, any> {
    const result: Record<string, any> = {}

    for (const [sourceId, sourceData] of Object.entries(componentData)) {
      if (isSafeSourceId(sourceId)) {
        result[sourceId] = smartDeepClone(sourceData.data)
      }
    }

    return result
  }

  /**
   * 转换为 Card 2.1 兼容格式；危险键或无法 JSON 序列化的数据源会被隔离跳过。
   */
  toCard21Format(componentData: ComponentData): any {
    const dataSourceBindings: Record<string, { rawData: string }> = {}

    for (const [sourceId, sourceData] of Object.entries(componentData)) {
      if (!isSafeSourceId(sourceId)) {
        continue
      }

      try {
        dataSourceBindings[sourceId] = { rawData: JSON.stringify(sourceData.data) }
      } catch (_error) {
        // 单个外部数据源不可序列化时，不阻断其他本地数据源输出。
      }
    }

    return {
      rawDataSources: {
        dataSourceBindings
      }
    }
  }
}

/**
 * 文件用途: 组件配置管理接口定义。
 * 核心逻辑: 描述基础配置、组件属性、数据源配置和交互配置的分层管理契约。
 * 关键注意事项: 配置层名称和事件结构会影响编辑器保存、撤销和局部更新设计。
 * 重构建议: 将持久化配置、编辑态补丁和事件通知类型拆分，降低接口膨胀。
 */

/**
 * 配置层类型
 */
export type ConfigLayer = 'base' | 'component' | 'dataSource' | 'interaction'

/**
 * 基础配置（位置、大小、样式等）
 */
export interface BaseConfig {
  position?: { x: number; y: number }
  size?: { width: number; height: number }
  zIndex?: number
  visible?: boolean
  locked?: boolean
  [key: string]: any
}

/**
 * 组件属性配置（组件特有的业务属性）
 */
export interface ComponentConfig {
  properties?: Record<string, any>
  styles?: Record<string, any>
  behavior?: Record<string, any>
  [key: string]: any
}

/**
 * 数据源配置（编辑态和持久化数据绑定契约）。
 * `api` 是历史持久化别名；交给运行时执行器前必须由适配器转换为 `http`。
 */
export interface DataSourceConfig {
  type?: 'static' | 'api' | 'websocket' | 'data-source-bindings'
  enabled?: boolean
  dataSourceBindings?: Record<string, any>
  config?: Record<string, any>
  metadata?: {
    componentType?: string
    updatedAt?: number
    source?: string
    [key: string]: any
  }
  [key: string]: any
}

/**
 * 交互配置（事件响应、动作等）
 */
export interface InteractionConfig {
  configs?: Array<{
    trigger: string
    action: string
    target?: string
    [key: string]: any
  }>
  enabled?: boolean
  metadata?: {
    updatedAt?: number
    [key: string]: any
  }
  [key: string]: any
}

/**
 * 组件完整配置
 */
export interface WidgetConfiguration {
  /** 基础配置层 */
  base: BaseConfig
  /** 组件配置层 */
  component: ComponentConfig
  /** 数据源配置层 */
  dataSource: DataSourceConfig
  /** 交互配置层 */
  interaction: InteractionConfig
  /** 配置元数据 */
  metadata: {
    version: string
    createdAt: number
    updatedAt: number
    description?: string
  }
}

/**
 * 配置变更事件
 */
export interface ConfigChangeEvent {
  widgetId: string
  layer: ConfigLayer
  oldConfig?: any
  newConfig: any
  timestamp: number
}

/**
 * 配置验证结果
 */
export interface ConfigValidationResult {
  valid: boolean
  errors?: Array<{
    layer: ConfigLayer
    field: string
    message: string
  }>
  warnings?: Array<{
    layer: ConfigLayer
    field: string
    message: string
  }>
}

/**
 * 组件配置管理器接口
 * 职责：
 * 1. 管理组件的四层配置数据存取
 * 2. 提供配置验证和默认值处理
 * 3. 发出配置变更事件，但不直接触发数据执行
 * 4. 支持配置的导入导出和版本管理
 */
export interface IComponentConfigManager {
  /**
   * 获取组件完整配置
   */
  getConfiguration(widgetId: string): WidgetConfiguration | null

  /**
   * 设置组件完整配置
   */
  setConfiguration(widgetId: string, config: WidgetConfiguration): void

  /**
   * 获取特定层的配置
   */
  getLayerConfig<T = any>(widgetId: string, layer: ConfigLayer): T | null

  /**
   * 更新特定层的配置
   */
  updateLayerConfig<T = any>(widgetId: string, layer: ConfigLayer, config: T): void

  /**
   * 删除组件配置
   */
  deleteConfiguration(widgetId: string): boolean

  // --- 配置验证和默认值 ---

  /**
   * 验证配置
   */
  validateConfiguration(config: WidgetConfiguration): ConfigValidationResult

  /**
   * 创建默认配置
   */
  createDefaultConfiguration(): WidgetConfiguration

  /**
   * 获取层级默认配置
   */
  getLayerDefaults<T = any>(layer: ConfigLayer): T

  // --- 批量操作 ---

  /**
   * 获取所有组件配置
   */
  getAllConfigurations(): Record<string, WidgetConfiguration>

  /**
   * 批量设置配置
   */
  setMultipleConfigurations(configs: Record<string, WidgetConfiguration>): void

  /**
   * 清空所有配置
   */
  clearAllConfigurations(): void

  // --- 事件监听 ---

  /**
   * 监听配置变更
   */
  onConfigChange(listener: (event: ConfigChangeEvent) => void): () => void

  /**
   * 监听特定组件配置变更
   */
  onWidgetConfigChange(widgetId: string, listener: (event: ConfigChangeEvent) => void): () => void

  /**
   * 监听特定层配置变更
   */
  onLayerConfigChange(layer: ConfigLayer, listener: (event: ConfigChangeEvent) => void): () => void

  // --- 导入导出 ---

  /**
   * 导出配置
   */
  exportConfiguration(widgetId?: string): any

  /**
   * 导入配置
   */
  importConfiguration(data: any, widgetId?: string): boolean

  /**
   * 清理资源
   */
  destroy(): void
}

/**
 * 文件用途: 组件运行时数据管理接口定义。
 * 核心逻辑: 描述数据源注册、运行时数据、缓存和更新通知等组件数据管理能力。
 * 关键注意事项: 数据源类型和运行态字段需要与执行器结果保持一致。
 * 重构建议: 明确缓存策略、订阅模型和错误态类型，便于替换实现。
 */

/**
 * 未来组件数据管理器的最小数据源集合，不代表 UnifiedDataExecutor 的完整类型集合。
 * `websocket` 依赖外部连接宿主；`script` 依赖受限脚本宿主，缺少宿主时必须显式阻断。
 */
export type DataSourceType = 'static' | 'http' | 'websocket' | 'script'

/**
 * 数据源配置。脚本字段只保存接口契约，不授权实现使用 eval 或 Function 执行。
 */
export interface DataSourceDefinition {
  id: string
  type: DataSourceType
  config: {
    // HTTP配置
    url?: string
    method?: 'GET' | 'POST' | 'PUT' | 'DELETE'
    headers?: Record<string, string>
    params?: Record<string, any>
    body?: any
    timeout?: number

    // 静态数据配置
    data?: any

    // WebSocket配置
    wsUrl?: string
    reconnect?: boolean

    // 脚本配置
    script?: string
    context?: Record<string, any>

    [key: string]: any
  }
  // 数据过滤路径（如JSONPath）
  filterPath?: string
  // 数据处理脚本
  processScript?: string
}

/**
 * 组件数据需求
 */
export interface ComponentDataRequirement {
  /** 组件ID */
  componentId: string
  /** 组件类型 */
  componentType: string
  /** 数据源列表 */
  dataSources: DataSourceDefinition[]
  /** 是否启用 */
  enabled: boolean
}

/**
 * 数据执行结果
 */
export interface DataExecutionResult {
  /** 是否成功 */
  success: boolean
  /** 数据内容 */
  data?: any
  /** 错误信息 */
  error?: string
  /** 执行时间（毫秒） */
  executionTime: number
  /** 时间戳 */
  timestamp: number
}

/**
 * 组件数据状态
 */
export interface ComponentDataState {
  /** 组件ID */
  componentId: string
  /** 组件类型 */
  componentType: string
  /** 当前数据 */
  currentData: Record<string, any>
  /** 最后更新时间 */
  lastUpdated: number
  /** 是否正在加载 */
  loading: boolean
  /** 错误信息 */
  error?: string
  /** 数据源状态 */
  dataSourceStates: Record<
    string,
    {
      lastExecuted: number
      success: boolean
      error?: string
    }
  >
}

/**
 * 数据更新事件
 */
export interface DataUpdateEvent {
  componentId: string
  dataSourceId?: string
  oldData?: any
  newData: any
  timestamp: number
}

/**
 * 组件运行时数据管理器接口
 * 职责：
 * 1. 根据配置获取和处理数据
 * 2. 管理数据缓存和更新策略
 * 3. 提供简单的数据转换功能
 * 4. 通知组件数据变更
 *
 * 设计原则：
 * - 简单直接，不做复杂的状态管理
 * - 无轮询、无WebSocket连接池等重型功能
 * - 只处理基本的HTTP请求和静态数据
 * - 错误容忍，不阻塞界面
 */
export interface IComponentDataManager {
  // --- 数据需求管理 ---

  /**
   * 注册组件数据需求
   */
  registerComponent(requirement: ComponentDataRequirement): void

  /**
   * 注销组件数据需求
   */
  unregisterComponent(componentId: string): void

  /**
   * 更新组件数据需求
   */
  updateComponentRequirement(requirement: ComponentDataRequirement): void

  /**
   * 获取组件数据需求
   */
  getComponentRequirement(componentId: string): ComponentDataRequirement | null

  // --- 数据执行 ---

  /**
   * 执行组件数据获取（手动触发）
   */
  executeComponent(componentId: string): Promise<DataExecutionResult>

  /**
   * 执行特定数据源
   */
  executeDataSource(componentId: string, dataSourceId: string): Promise<DataExecutionResult>

  /**
