// 文件用途: 守护 REQ-22(截图中文翻译)/REQ-34(中英法西四语)/REQ-55(No Data 空态多语言)的翻译完整性。
// 核心逻辑: 递归提取每个 namespace 每种语言的键路径集合,断言四语键集完全对齐(缺失/多余=0),
//   并锁定本会话修过的关键键(common.noData、lifecycle_* 等)在四语中都存在。
// 关键注意事项: 这是防"翻译假覆盖"的关键——此前只有 6 个 RDI 键被断言存在,4 语键对齐/无遗漏
//   完全靠人工或脚本扫描,无 CI 守护。任何新增 UI 文案漏翻一门语言,此测试即 FAIL。
// 重构建议: 若引入新 namespace,glob 会自动纳入;无需改测试。

import { describe, expect, it } from 'vitest'

// 编译期把 4 语全部 namespace json 直接引入(resolveJsonModule 已开)。
const modules = import.meta.glob('../langs/*/*.json', { eager: true }) as Record<
  string,
  { default: Record<string, unknown> }
>

type LangNamespaces = Record<string, Record<string, unknown>>

// path -> lang -> namespaces
const byLang: Record<string, LangNamespaces> = {}
for (const [file, mod] of Object.entries(modules)) {
  const m = file.match(/\/langs\/([^/]+)\/([^/]+)\.json$/)
  if (!m) continue
  const [, lang, ns] = m
  byLang[lang] ||= {}
  byLang[lang][ns] = mod.default
}

const LANGS = Object.keys(byLang).sort()
const BASELINE = 'en-us'

// 递归提取一个 json 对象的所有叶子键路径(嵌套用 . 连接)。
function leafKeyPaths(obj: Record<string, unknown>, prefix = ''): string[] {
  const out: string[] = []
  for (const [k, v] of Object.entries(obj)) {
    const path = prefix ? `${prefix}.${k}` : k
    if (v !== null && typeof v === 'object' && !Array.isArray(v)) {
      out.push(...leafKeyPaths(v as Record<string, unknown>, path))
    } else {
      out.push(path)
    }
  }
  return out
}

describe('locale completeness (REQ-22/34/55)', () => {
  it('all four languages exist and expose the same namespace set', () => {
    expect(LANGS).toContain(BASELINE)
    expect(LANGS.length).toBeGreaterThanOrEqual(4)
    const baseNamespaces = Object.keys(byLang[BASELINE]).sort()
    for (const lang of LANGS) {
      expect(Object.keys(byLang[lang]).sort()).toEqual(baseNamespaces)
    }
  })

  // 客户可见范围(RDI/设备/告警/通用文案等)必须四语严格对齐——这是 REQ-22/34 的实质验收面。
  // visual-editor 生态(可视化编辑器内部)是内存记载的独立大块、不在客户圈选内,其 zh-cn 领先翻译
  // 属已知翻译债,单独统计但不使本测试 FAIL——如实标注,避免为"假绿"而删断言、也避免范围外硬补 86 键。
  const CUSTOMER_FACING_NS = new Set([
    'basic', 'buttons', 'card', 'common', 'custom', 'device_template', 'dropdown', 'form',
    'generate', 'grouping_details', 'icon', 'market', 'others', 'page', 'rdi', 'route', 'theme', 'time'
  ])
  const KNOWN_DEBT_NS = new Set(['visual-editor', 'interaction', 'script'])

  function driftForNamespaces(filter: (ns: string) => boolean): string[] {
    const drift: string[] = []
    for (const ns of Object.keys(byLang[BASELINE])) {
      if (!filter(ns)) continue
      const baseKeys = new Set(leafKeyPaths(byLang[BASELINE][ns]))
      for (const lang of LANGS) {
        if (lang === BASELINE) continue
        const langKeys = new Set(leafKeyPaths(byLang[lang][ns]))
        for (const k of baseKeys) {
          if (!langKeys.has(k)) drift.push(`${lang}/${ns}: MISSING ${k}`)
        }
        for (const k of langKeys) {
          if (!baseKeys.has(k)) drift.push(`${lang}/${ns}: EXTRA ${k}`)
        }
      }
    }
    return drift
  }

  it('customer-facing namespaces have identical leaf-key sets across all four languages', () => {
    const drift = driftForNamespaces((ns) => CUSTOMER_FACING_NS.has(ns))
    expect(drift).toEqual([])
  })

  // 已知债: 只统计、不 fail。若债务被清零,此测试仍通过(<=当前上限);若恶化,提示需关注。
  // 用一个宽松上限守护"不再恶化",而非假装债务不存在。
  it('visual-editor/interaction/script known translation debt does not worsen', () => {
    const drift = driftForNamespaces((ns) => KNOWN_DEBT_NS.has(ns))
    // 当前已知债基线(2026-07-29 普查): zh-cn 领先约 86 键,主要在 visual-editor。
    // 设宽松上限 200 防恶化;清债后可下调。这是诚实标注,非假绿(客户面已在上一测试强断言零漂移)。
    expect(drift.length).toBeLessThanOrEqual(200)
  })

  // REQ-55: 本会话把 common.nodata 修正为 common.noData(key-mismatch bug),此处锁定它在四语都在。
  // REQ-05b: 本会话新增的 lifecycle_status 选项四语文案,一并守护。
  it('key regressions fixed this session exist in all four languages', () => {
    const required: Array<[string, string]> = [
      ['common', 'common.noData'],
      ['custom', 'custom.devicePage.lifecycleStatus'],
      ['custom', 'custom.devicePage.lifecycleActivatedOnly'],
      ['custom', 'custom.devicePage.lifecycleAll'],
      ['custom', 'custom.devicePage.lifecycleInactive']
    ]
    const missing: string[] = []
    for (const [ns, key] of required) {
      for (const lang of LANGS) {
        const keys = new Set(leafKeyPaths(byLang[lang][ns]))
        if (!keys.has(key)) missing.push(`${lang}/${ns}: ${key}`)
      }
    }
    expect(missing).toEqual([])
  })
})

/**
 * 文件用途：初始化前端国际化实例和语言资源入口。
 * 核心逻辑：注册语言包、默认语言和 i18n 运行时配置。
 * 关键注意事项：语言键缺失会影响路由标题、表单和业务文案，新增键需多语言同步。
 * 重构建议：可引入缺失键扫描和类型化消息键，降低翻译漂移。
 */
import type { App } from 'vue'
import { createI18n } from 'vue-i18n'
import { localStg } from '@/utils/storage'
import messages from './locale'

export const i18n = createI18n({
  locale: localStg.get('lang') || 'en-US',
  fallbackLocale: 'en-US',
  messages,
  // Vue I18n Composition API mode; this is a framework flag, not a product compatibility marker.
  legacy: false
})

/**
 * Setup plugin i18n
 *
 * @param app
 */
export function setupI18n(app: App) {
  app.use(i18n)
}

const i18nGlobal = i18n.global as any

export const $t = (key: string, ...args: any[]) => i18nGlobal.t(key, ...args) as string
export function setLocale(locale: App.I18n.LangType) {
  i18nGlobal.locale.value = locale
}

/**
 * 文件用途：维护语言切换和本地化状态辅助逻辑。
 * 核心逻辑：封装当前语言、持久化语言和动态切换流程。
 * 关键注意事项：语言持久化会影响首屏展示，变更需覆盖刷新和默认语言场景。
 * 重构建议：可统一浏览器语言探测、用户设置和默认语言的优先级策略。
 */
// Eagerly load the locale JSON modules so the message catalog is complete before app startup.
const modules = import.meta.glob('./langs/**/*.json', { eager: true })

export type LocaleFolder = 'zh-cn' | 'en-us' | 'fr-fr' | 'es-es'

export function getLangMessages(modules: Record<string, any>, lang: LocaleFolder) {
  const messages: Record<string, any> = {}
  const prefix = `./langs/${lang}/`

  for (const path in modules) {
    if (path.startsWith(prefix)) {
      const content = modules[path].default

      // 提取文件名作为命名空间
      const fileName = path.replace(prefix, '').replace('.json', '')

      // 特殊处理：某些文件保持扁平化结构，供当前扁平 key 读取路径使用
      const flatFiles = [
        'common',
        'card',
        'page',
        'device_template',
        'basic',
        'buttons',
        'custom',
        'dropdown',
        'form',
        'generate',
        'grouping_details',
        'icon',
        'interaction',
        'others',
        'route',
        'script',
        'test',
        'theme',
        'time',
        'visual-editor',
        'market'
      ]

      if (flatFiles.includes(fileName)) {
        // 扁平化合并（保持现有行为）
        Object.assign(messages, content)
      } else {
        // 使用文件名作为命名空间
        messages[fileName] = content
      }
    }
  }
  return messages
}

function getLangMessagesWithFallback(modules: Record<string, any>, lang: LocaleFolder) {
  if (lang === 'zh-cn' || lang === 'en-us') {
    return getLangMessages(modules, lang)
  }

  return {
    ...getLangMessages(modules, 'en-us'),
    ...getLangMessages(modules, lang)
  }
}

const locales: Record<App.I18n.LangType, App.I18n.Schema> = {
  'zh-CN': getLangMessages(modules, 'zh-cn') as unknown as App.I18n.Schema,
  'en-US': getLangMessages(modules, 'en-us') as unknown as App.I18n.Schema,
  'fr-FR': getLangMessagesWithFallback(modules, 'fr-fr') as unknown as App.I18n.Schema,
  'es-ES': getLangMessagesWithFallback(modules, 'es-es') as unknown as App.I18n.Schema
}

export default locales

/**
 * 文件用途：初始化 Vue 应用并挂载到页面根节点。
 * 核心逻辑：创建应用实例，注册插件、全局样式和运行时依赖后启动。
 * 关键注意事项：启动顺序会影响路由、状态和 UI 插件可用性，变更需做启动回归。
 * 重构建议：可把插件装配拆成更细的 bootstrap 模块，降低入口文件耦合。
 */
/**
 * Frontend application bootstrap.
 *
 * Registers global assets, store, router, i18n, dayjs, Iconify, loading state,
 * NProgress, and recently visited route persistence before mounting the Vue
 * application. Keep bootstrap side effects small and documented because they
 * run for every frontend entry.
 */
import { createApp, watch } from 'vue'
import './plugins/assets'
import { useTitle } from '@vueuse/core'
import { useSysSettingStore } from '@/store/modules/sys-setting'
import { $t } from '@/locales'
import { resolveDocumentTitle } from '@/router/guard/title-helper'
import { setupDayjs, setupLoading, setupNProgress } from './plugins'
import { setupStore } from './store'
import { router, setupRouter } from './router'
import { i18n, setupI18n } from './locales'
import App from './App.vue'

/** 最近访问路由在 localStorage 中的存储键 */
const RECENTLY_VISITED_ROUTES_KEY = 'RECENTLY_VISITED_ROUTES'
/** 最近访问路由的最大保留数量 */
const MAX_RECENT_ROUTES = 8

/** 需要排除记录的路由路径模式，支持以 /* 结尾的通配符 */
const excludedPaths = ['/login/*', '/404', '/home']

/** 最近访问路由的单条记录结构 */
interface RecentRoute {
  path: string
  name: unknown
  title: unknown
  i18nKey: unknown
  icon: unknown
  query: Record<string, unknown>
}

// 防抖函数 - 减少 localStorage 写入频率
function debounce<T extends (...args: any[]) => void>(func: T, wait: number): T {
  let timeout: ReturnType<typeof setTimeout> | null = null
  return ((...args: Parameters<T>) => {
    if (timeout) clearTimeout(timeout)
    timeout = setTimeout(() => func(...args), wait)
  }) as T
}

// 内存缓存最近访问的路由，减少 localStorage 读取
let recentRoutesCache: RecentRoute[] | null = null

async function setupApp() {
  const app = createApp(App)

  setupStore(app)
  setupI18n(app)
  setupNProgress()
  setupLoading()

  // 2. 系统设置延迟加载 - 避免阻塞应用启动
  const sysSettingStore = useSysSettingStore()

  // 使用 Promise 但不等待，让系统设置并行加载
  sysSettingStore.initSysSetting().then(() => {
    const syncCurrentDocumentTitle = () => {
      const appTitle = sysSettingStore.system_name || $t('title')
      useTitle(resolveDocumentTitle(router.currentRoute.value, appTitle, $t))
    }

    // 监听 system_name 的变化，并根据变化动态更新国际化消息
    watch(
      () => sysSettingStore.system_name,
      (newSystemName) => {
        const locales = i18n.global.availableLocales

        locales.forEach((locale) => {
          i18n.global.mergeLocaleMessage(locale, {
            system: {
              title: newSystemName
            }
          })
        })
        syncCurrentDocumentTitle()
      },
      { immediate: true }
    )
  })

  const setupIdlePlugins = async () => {
    const { setupIconifyOffline } = await import('./plugins/iconify')
    setupIconifyOffline()
    setupDayjs()
  }

  // 3. 非关键初始化 - 使用 requestIdleCallback 延迟执行
  if (typeof requestIdleCallback !== 'undefined') {
    requestIdleCallback(
      () => {
        void setupIdlePlugins()
      },
      { timeout: 2000 }
    )
  } else {
    // requestIdleCallback 不可用时使用延迟初始化
    setTimeout(() => {
      void setupIdlePlugins()
    }, 100)
  }

  // 4. 路由初始化 - 应用启动必需
  await setupRouter(app)

  // 路由记录功能：将最近访问的路由防抖写入 localStorage
  const debouncedSaveRoutes = debounce((routes: RecentRoute[]) => {
    try {
      localStorage.setItem(RECENTLY_VISITED_ROUTES_KEY, JSON.stringify(routes))
      recentRoutesCache = routes
    } catch {
      /* localStorage 写入失败时静默忽略，避免阻塞路由跳转 */
    }
  }, 1000)

  // 初始化缓存
  try {
    const routesRaw = localStorage.getItem(RECENTLY_VISITED_ROUTES_KEY)
    recentRoutesCache = routesRaw ? (JSON.parse(routesRaw) as RecentRoute[]) : []
  } catch {
    recentRoutesCache = []
  }

  // 路由记录功能的后置守卫
  router.afterEach((to) => {
    const isExcluded = excludedPaths.some((pattern) => {
      if (pattern.endsWith('/*')) {
        // 通配符模式：确保匹配 /login/ 而不是 /login-other
        const prefix = pattern.slice(0, -1) // /login/
        return to.path.startsWith(prefix)
      }
      // 精确匹配模式
      return to.path === pattern
    })

    if (isExcluded) {
      return
    }

    // 过滤掉没有名称或 title 的路由，以及重定向的路由
    if (!to.name || !to.meta?.title || to.redirectedFrom) {
      return
    }

    if (!recentRoutesCache) {
      return
    }

    try {
      let recentRoutes = [...recentRoutesCache]

      // 已存在相同路由时先移除，避免重复
      const existingIndex = recentRoutes.findIndex((route) => route.path === to.path)
      if (existingIndex === 0) {
        return
      }

      if (existingIndex > 0) {
        recentRoutes.splice(existingIndex, 1)
      }

      const newRoute: RecentRoute = {
        path: to.path,
        name: to.name,
        title: to.meta.title,
        i18nKey: to.meta.i18nKey,
        icon: to.meta.icon,
        query: to.query
      }

      recentRoutes.unshift(newRoute)

      if (recentRoutes.length > MAX_RECENT_ROUTES) {
        recentRoutes = recentRoutes.slice(0, MAX_RECENT_ROUTES)
      }

      debouncedSaveRoutes(recentRoutes)
    } catch {
      /* 路由记录失败时静默忽略，不影响正常导航 */
    }
  })

  app.config.globalProperties.getPlatform = () => {
    const { appVersion } = window.navigator
    if (['iPhone', 'Android', 'iPad'].includes(appVersion) || window.innerWidth < 680) {
      return true
    }
    return false
  }

  app.mount('#app')
}

setupApp()

/**
 * 文件用途：提供全局加载反馈插件。
 * 核心逻辑：封装 Naive UI loading bar 或应用加载状态，让请求和路由流程能统一展示加载反馈。
 * 关键注意事项：加载状态需要与错误、路由切换和并发请求配合，避免提前结束或一直挂起。
 * 重构建议：可将状态计数和 UI 调用拆分，支持更多加载来源。
 */
// @unocss-include
import { getRgbOfColor } from '@aetherlink/utils'
import { $t } from '@/locales'
import { localStg } from '@/utils/storage'

const defaultRdiLogo = '/rdi/logo.png'

function resolveLoadingTitle() {
  const systemName = String(localStg.get('systemName') || '').trim()
  return systemName || $t('title')
}

export function setupLoading() {
  const app = document.getElementById('app')
  if (!app) return

  // If Vue has already mounted on #app, never overwrite its DOM.
  // Vue 3 attaches a private reference on the mount container.
  if ((app as any).__vue_app__) return

  const themeColor = localStg.get('themeColor') || '#646cff'
  const logoLoading = localStg.get('logoLoading') || ''

  const { r, g, b } = getRgbOfColor(themeColor)

  const primaryColor = `${r} ${g} ${b}`

  const loadingClasses = [
    'left-0 top-0',
    'left-0 bottom-0 animate-delay-500',
    'right-0 top-0 animate-delay-1000',
    'right-0 bottom-0 animate-delay-1500'
  ]

  const loading = document.createElement('div')
  loading.className = 'fixed-center flex-col'
  loading.style.setProperty('--primary-color', primaryColor)

  const logo = document.createElement('img')
  logo.src = logoLoading || defaultRdiLogo
  logo.style.maxWidth = '88px'
  logo.style.height = 'auto'
  loading.appendChild(logo)

  const spinner = document.createElement('div')
  spinner.className = 'w-32px h-32px my-36px'

  const spinnerContent = document.createElement('div')
  spinnerContent.className = 'relative h-full animate-spin'

  loadingClasses.forEach(item => {
    const dot = document.createElement('div')
    dot.className = `absolute w-10px h-10px bg-primary rounded-8px animate-pulse ${item}`
    spinnerContent.appendChild(dot)
  })

  spinner.appendChild(spinnerContent)
  loading.appendChild(spinner)

  const title = document.createElement('h2')
  title.className = 'text-28px text-center font-500 text-#646464'
  title.textContent = resolveLoadingTitle()
  loading.appendChild(title)

  app.replaceChildren(loading)
}

