/**
 * 文件用途：验证 路由守卫单元测试 的关键行为和回归边界。
 * 核心逻辑：通过 Vitest、组件挂载或模块 mock 构造输入，断言状态、事件、请求参数或可见输出。
 * 关键注意事项：测试数据和 mock 必须贴近真实契约，避免只证明代码能运行而没有业务断言。
 * 重构建议：可沉淀共享 fixture 与挂载工具，并补充异常、空数据和权限边界用例。
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createMobileLayoutGuard } from '../mobile';

const appState = vi.hoisted(() => ({
  isMobile: false
}));

vi.mock('@/store/modules/app', () => ({
  useAppStore: () => appState
}));

type TestGuard = (...args: unknown[]) => void;

function installGuard(routes: any[] = []) {
  const beforeEach = vi.fn();
  createMobileLayoutGuard({
    beforeEach,
    getRoutes: () => routes
  } as any);
  return beforeEach.mock.calls[0][0] as TestGuard;
}

function route(overrides: Record<string, any> = {}) {
  return {
    name: 'device_manage',
    meta: {},
    ...overrides
  };
}

describe('mobile layout guard contract', () => {
  beforeEach(() => {
    appState.isMobile = false;
  });

  it('always resolves navigation on desktop routes', () => {
    const guard = installGuard();
    const next = vi.fn();

    guard(route(), route({ name: 'login' }), next);

    expect(next).toHaveBeenCalledTimes(1);
    expect(next).toHaveBeenCalledWith();
  });

  it('checks registered base-layout routes on mobile before resolving navigation', () => {
    appState.isMobile = true;
    const guard = installGuard([
      {
        name: 'device_manage',
        components: { default: { name: 'BaseLayout' } }
      }
    ]);
    const next = vi.fn();

    guard(route(), route({ name: 'login' }), next);

    expect(next).toHaveBeenCalledTimes(1);
  });

  it('does not treat constant, error, or explicitly disabled routes as mobile-layout candidates', () => {
    appState.isMobile = true;
    const getRoutes = vi.fn(() => [
      {
        name: 'login',
        components: { default: { name: 'BaseLayout' } }
      }
    ]);
    const beforeEach = vi.fn();
    createMobileLayoutGuard({ beforeEach, getRoutes } as any);
    const guard = beforeEach.mock.calls[0][0] as TestGuard;
    const next = vi.fn();

    guard(route({ name: 'login', meta: { constant: true } }), route(), next);
    guard(route({ name: '403', meta: {} }), route(), next);
    guard(route({ name: 'device_manage', meta: { disableMobileLayout: true } }), route(), next);

    expect(next).toHaveBeenCalledTimes(3);
    expect(getRoutes).not.toHaveBeenCalled();
  });
});

/**
 * 文件用途：验证 路由守卫单元测试 的关键行为和回归边界。
 * 核心逻辑：通过 Vitest、组件挂载或模块 mock 构造输入，断言状态、事件、请求参数或可见输出。
 * 关键注意事项：测试数据和 mock 必须贴近真实契约，避免只证明代码能运行而没有业务断言。
 * 重构建议：可沉淀共享 fixture 与挂载工具，并补充异常、空数据和权限边界用例。
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPermissionGuard } from '../permission';

const authState = vi.hoisted(() => ({
  token: '',
  userInfo: { roles: [] as string[] },
  resetStore: vi.fn()
}));

const routeState = vi.hoisted(() => ({
  isInitAuthRoute: true,
  initAuthRoute: vi.fn(),
  getIsAuthRouteExist: vi.fn()
}));

vi.mock('@/store/modules/auth', () => ({
  useAuthStore: () => authState
}));

vi.mock('@/store/modules/route', () => ({
  useRouteStore: () => routeState
}));

vi.mock('@/utils/storage', () => ({
  localStg: {
    get: vi.fn((key: string) => (key === 'token' ? authState.token : null))
  }
}));

type TestGuard = (...args: unknown[]) => void;

function installGuard() {
  const beforeEach = vi.fn();
  createPermissionGuard({ beforeEach } as any);
  return beforeEach.mock.calls[0][0] as TestGuard;
}

function route(overrides: Record<string, any> = {}) {
  return {
    name: 'device_manage',
    path: '/device/manage',
    fullPath: '/device/manage',
    query: {},
    hash: '',
    meta: { roles: ['TENANT_ADMIN'] },
    ...overrides
  };
}

describe('permission guard contract', () => {
  beforeEach(() => {
    authState.token = '';
    authState.userInfo = { roles: [] };
    authState.resetStore.mockReset();
    routeState.isInitAuthRoute = true;
    routeState.initAuthRoute.mockReset();
    routeState.getIsAuthRouteExist.mockReset();
  });

  it('redirects anonymous protected navigation to login with the original path', async () => {
    const guard = installGuard();
    const next = vi.fn();

    await guard(route(), route({ fullPath: '/home' }), next);

    expect(next).toHaveBeenCalledWith({ name: 'login', query: { redirect: '/device/manage' } });
  });

  it('allows tenant-admin and super-admin roles through protected routes', async () => {
    const guard = installGuard();
    const next = vi.fn();
    authState.token = 'token';
    authState.userInfo.roles = ['TENANT_ADMIN'];

    await guard(route(), route({ fullPath: '/home' }), next);
    expect(next).toHaveBeenCalledWith();

    next.mockReset();
    authState.userInfo.roles = ['SYS_ADMIN'];
    await guard(route({ meta: { roles: ['TENANT_ADMIN'] } }), route({ fullPath: '/home' }), next);
    expect(next).toHaveBeenCalledWith();
  });

  it('sends logged-in users without route permission to 403', async () => {
    const guard = installGuard();
    const next = vi.fn();
    authState.token = 'token';
    authState.userInfo.roles = ['TENANT_USER'];

    await guard(route(), route({ fullPath: '/home' }), next);

    expect(next).toHaveBeenCalledWith({ name: '403' });
  });

  it('redirects a logged-in user away from login to root', async () => {
    const guard = installGuard();
    const next = vi.fn();
    authState.token = 'token';

    await guard(route({ name: 'login', path: '/login', fullPath: '/login', meta: { constant: true } }), route(), next);

    expect(next).toHaveBeenCalledWith({ name: 'root' });
  });

  it('initializes auth routes and redirects recovered not-found routes', async () => {
    const guard = installGuard();
    const next = vi.fn();
    authState.token = 'token';
    routeState.isInitAuthRoute = false;
    routeState.initAuthRoute.mockResolvedValue(true);

    await guard(
      route({ name: 'not-found', path: '/visualization/thingsvis', fullPath: '/visualization/thingsvis', redirectedFrom: { name: 'device_manage' } }),
      route(),
      next
    );

    expect(routeState.initAuthRoute).toHaveBeenCalledTimes(1);
    expect(next).toHaveBeenCalledWith({
      path: '/visualization/thingsvis',
      replace: true,
      query: {},
      hash: ''
    });
  });
});

/**
 * 文件用途：移动端布局路由守卫。
 * 核心逻辑：在移动端访问业务路由时识别是否需要移动端布局处理，并保留路由层适配入口。
 * 关键注意事项：当前守卫只做候选路由识别和导航放行，实际布局切换仍由布局组件根据 appStore.isMobile 渲染。
 * 重构建议：如果未来需要真正替换路由组件，应抽出明确的布局解析函数并补充重定向/组件替换测试。
 */
import type { RouteLocationNormalized, Router } from 'vue-router'
import { useAppStore } from '@/store/modules/app'

export function createMobileLayoutGuard(router: Router) {
  router.beforeEach((to, _from, next) => {
    const appStore = useAppStore()

    if (appStore.isMobile && shouldUseMobileLayout(to)) {
      const routeMatch = router.getRoutes().find(route => route.name === to.name)

      // Vue Router 不适合在守卫中直接替换已注册组件；这里仅保留移动端候选识别。
      if (routeMatch && isBaseLayoutComponent(routeMatch.components?.default)) {
        // 实际渲染差异交给布局组件根据 isMobile 状态处理。
      }
    }

    next()
  })
}

/**
 * 判断当前路由是否应参与移动端布局候选判断。
 */
function shouldUseMobileLayout(route: RouteLocationNormalized): boolean {
  const excludeRoutes = ['login', '403', '404', '500']

  if (route.meta?.constant) {
    return false
  }

  if (excludeRoutes.includes(route.name as string)) {
    return false
  }

  if (route.meta?.disableMobileLayout) {
    return false
  }

  return true
}

/**
 * 检查路由组件是否为基础布局组件。
 */
function isBaseLayoutComponent(component: any): boolean {
  if (!component) return false

  const componentName = component.name || component.__name || component.displayName
  return (
    componentName === 'BaseLayout' || (component.__asyncResolved && component.__asyncResolved.name === 'BaseLayout')
  )
}

/**
 * 文件用途：全局权限路由守卫。
 * 核心逻辑：协调授权路由初始化、登录重定向、外链路由、角色校验和 403 fallback。
 * 关键注意事项：`next()` 必须单次完成；auth/route store 初始化顺序错误会导致刷新白屏或权限绕过。
 * 重构建议：抽出策略判断为纯函数，并用守卫测试覆盖未登录、已登录、外链、无权限和 not-found 分支。
 */
import type { NavigationGuardNext, RouteLocationNormalized, Router } from 'vue-router'
import type { RouteKey, RoutePath } from '@elegant-router/types'
import { useAuthStore } from '@/store/modules/auth'
import { useRouteStore } from '@/store/modules/route'
import { localStg } from '@/utils/storage'

export function createPermissionGuard(router: Router) {
  router.beforeEach(async (to, from, next) => {
    const pass = await createAuthRouteGuard(to, from, next)

    if (!pass) return

    // 外链路由在新窗口打开，并终止当前导航，避免后续守卫重复调用 next()。
    if (to.meta.href) {
      window.open(to.meta.href, '_blank')
      next({ path: from.fullPath, replace: true, query: from.query, hash: to.hash })
      return
    }

    const authStore = useAuthStore()

    const isLogin = Boolean(localStg.get('token'))
    const needLogin = !to.meta.constant
    const routeRoles = to.meta.roles || []
    const rootRoute: RouteKey = 'root'
    const loginRoute: RouteKey = 'login'
    const noPermissionRoute: RouteKey = '403'

    // 角色为空表示公开给已登录用户；SYS_ADMIN 拥有全部授权路由访问权。
    const SUPER_ADMIN = 'SYS_ADMIN'
    const hasPermission =
      !routeRoles.length ||
      authStore.userInfo?.roles?.includes(SUPER_ADMIN) ||
      authStore.userInfo?.roles?.some(role => routeRoles.includes(role))
    const strategicPatterns: CommonType.StrategicPattern[] = [
      {
        condition: isLogin && to.path.startsWith('/login'),
        callback: () => {
          next({ name: rootRoute })
        }
      },
      {
        condition: !needLogin,
        callback: () => {
          next()
        }
      },
      {
        condition: !isLogin && needLogin,
        callback: () => {
          next({ name: loginRoute, query: { redirect: to.fullPath } })
        }
      },
      {
        condition: isLogin && needLogin && hasPermission,
        callback: () => {
          next()
        }
      },
      {
        condition: isLogin && needLogin && !hasPermission,
        callback: () => {
          next({ name: noPermissionRoute })
        }
      }
    ]

    strategicPatterns.some(({ condition, callback }) => {
      if (condition) {
        callback()
      }

      return condition
    })
  })
}

async function createAuthRouteGuard(
  to: RouteLocationNormalized,
  _from: RouteLocationNormalized,
  next: NavigationGuardNext
) {
  const notFoundRoute: RouteKey = 'not-found'
  const isNotFoundRoute = to.name === notFoundRoute

  if (to.meta.constant && !isNotFoundRoute) {
    return true
  }

  const routeStore = useRouteStore()
  if (routeStore.isInitAuthRoute && !isNotFoundRoute) {
    return true
  }

  if (routeStore.isInitAuthRoute && isNotFoundRoute) {
    const exist = await routeStore.getIsAuthRouteExist(to.path as RoutePath)

    if (exist) {
      const noPermissionRoute: RouteKey = '403'

      next({ name: noPermissionRoute })

      return false
    }

    return true
  }

  const isLogin = Boolean(localStg.get('token'))
  if (!isLogin) {
    const loginRoute: RouteKey = 'login'
    const redirect = to.fullPath

    next({ name: loginRoute, query: { redirect } })

    return false
  }

  const initSuccess = await routeStore.initAuthRoute()

  if (!initSuccess) {
    const authStore = useAuthStore()
    await authStore.resetStore()

    return false
  }

  if (isNotFoundRoute) {
    const rootRoute: RouteKey = 'root'
    const path = to.redirectedFrom?.name === rootRoute ? '/' : to.fullPath

    next({ path, replace: true, query: to.query, hash: to.hash })

    return false
  }

  return true
}

/**
 * 文件用途：路由导航进度条守卫。
 * 核心逻辑：路由进入前启动 NProgress，路由完成后关闭 NProgress。
 * 关键注意事项：`window.NProgress` 可能不存在，调用时必须保持可选链容错。
 * 重构建议：如果后续支持更多加载状态，可抽出统一导航反馈服务。
 */
import type { Router } from 'vue-router'

export function createProgressGuard(router: Router) {
  router.beforeEach((_to, _from, next) => {
    window.NProgress?.start?.()
    next()
  })
  router.afterEach(_to => {
    window.NProgress?.done?.()
  })
}

/**
 * 文件用途：浏览器标题路由守卫。
 * 核心逻辑：根据路由 meta、登录子路径和系统设置生成页面标题。
 * 关键注意事项：登录页子模块标题来自语言包，系统名称为空时回退到默认应用标题。
 * 重构建议：可将标题解析逻辑抽为纯函数，单独覆盖登录子路由和普通业务路由。
 */
import type { Router } from 'vue-router'
import { useTitle } from '@vueuse/core'
import { $t } from '@/locales'
import { useSysSettingStore } from '@/store/modules/sys-setting'
import { resolveDocumentTitle } from './title-helper'

export function createDocumentTitleGuard(router: Router) {
  router.afterEach(to => {
    const sysSettingStore = useSysSettingStore()
    const appTitle = sysSettingStore.system_name || $t('title')
    const documentTitle = resolveDocumentTitle(to, appTitle, $t)

    useTitle(documentTitle)
  })
}

