    get: mockLocalStgGet
  }
}));

import {
  fetchLogin,
  fetchGetUserInfo,
  logout,
  fetchEmailCode,
  fetchEmailCodeByEmail,
  fetchUserList,
  addUser,
  editUser,
  delUser,
  transformUser,
