} from '../auth';

describe('Auth API 层 - auth.ts', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('fetchLogin', () => {
    it('调用 POST /login 并发送 email、password、salt', async () => {
      mockPost.mockResolvedValue({ error: null, data: { token: 't1' } });
