// without importing ThingsVis API details directly.
export const VISUALIZATION_PROVIDER_KINDS = {
  local: 'local',
  external: 'external'
} as const

export type VisualizationProviderKind = (typeof VISUALIZATION_PROVIDER_KINDS)[keyof typeof VISUALIZATION_PROVIDER_KINDS]

export const localVisualizationProvider = nativeBoardProvider
export const externalVisualizationProvider = legacyThingsVisProvider

export function getVisualizationProvider(kind: unknown = VISUALIZATION_PROVIDER_KINDS.local): VisualizationProvider | null {
  if (kind === VISUALIZATION_PROVIDER_KINDS.local) return localVisualizationProvider
  if (kind === VISUALIZATION_PROVIDER_KINDS.external) return externalVisualizationProvider
  return null
}

import { createVisualizationProviderFacade, type VisualizationProviderSelection } from './facade'
import { legacyThingsVisProvider } from './legacy-thingsvis-adapter'
import { nativeBoardProvider } from './native-board-provider'
import {
  LEGACY_THINGSVIS_PROVIDER_ID,
  NATIVE_BOARD_PROJECT_ID,
  NATIVE_BOARD_PROVIDER_ID
} from './provider-ids'
import { VisualizationProviderRegistry } from './registry'

const registry = new VisualizationProviderRegistry()

export function registerDefaultVisualizationProviders(): VisualizationProviderRegistry {
  registry.register(nativeBoardProvider)
  registry.register(legacyThingsVisProvider)
  return registry
}

export function getDefaultVisualizationProviderFacade(selection: VisualizationProviderSelection = {}) {
  const providerId = selection.providerId === undefined ? NATIVE_BOARD_PROVIDER_ID : selection.providerId
  const externalEnabled = import.meta.env.VITE_ENABLE_THINGSVIS_COMPAT === 'Y'
  const effectiveSelection = providerId === LEGACY_THINGSVIS_PROVIDER_ID && !externalEnabled
    ? { ...selection, context: { ...selection.context, available: false } }
    : selection

  return createVisualizationProviderFacade(registerDefaultVisualizationProviders(), effectiveSelection)
}

export function getDefaultVisualizationProviderRegistry() {
  return registerDefaultVisualizationProviders()
}

type RouteQueryValue = unknown

function firstRouteQueryValue(value: RouteQueryValue): string {
  if (Array.isArray(value)) return firstRouteQueryValue(value[0])
  return typeof value === 'string' ? value.trim() : ''
}

/**
 * Resolve the provider for compatibility routes without probing an optional service.
 * Native boards are selected only by an explicit local marker or their built-in
 * project id; every other route keeps the legacy external provider contract.
 */
export function resolveVisualizationProviderId(selection: {
  provider?: RouteQueryValue
  projectId?: RouteQueryValue
}): string {
  const provider = firstRouteQueryValue(selection.provider).toLowerCase()
  const projectId = firstRouteQueryValue(selection.projectId)
  const externalEnabled = import.meta.env.VITE_ENABLE_THINGSVIS_COMPAT === 'Y'

  if (provider === 'native' || provider === 'local' || provider === NATIVE_BOARD_PROVIDER_ID) {
    return NATIVE_BOARD_PROVIDER_ID
  }
  if (
    provider === 'legacy' ||
    provider === 'external' ||
    provider === 'thingsvis' ||
    provider === LEGACY_THINGSVIS_PROVIDER_ID
  ) {
    return LEGACY_THINGSVIS_PROVIDER_ID
  }
  if (projectId === NATIVE_BOARD_PROJECT_ID) {
    return NATIVE_BOARD_PROVIDER_ID
  }
  if (projectId) return LEGACY_THINGSVIS_PROVIDER_ID

  // A route without a provider is the normal product path. Keep it
  // self-contained in the default build, and preserve the historical
  // external default only for the explicitly enabled compatibility profile.
  return externalEnabled ? LEGACY_THINGSVIS_PROVIDER_ID : NATIVE_BOARD_PROVIDER_ID
}

import type {
  VisualizationError,
  VisualizationProvider,
  VisualizationProviderContext,
  VisualizationProviderId,
  VisualizationResult
} from './contracts'
import { VisualizationProviderRegistry } from './registry'
import { NATIVE_BOARD_PROVIDER_ID } from './provider-ids'

export interface VisualizationProviderSelection {
  providerId?: VisualizationProviderId | null
  context?: Partial<VisualizationProviderContext>
  expectedOwnerId?: string
}

const fail = (error: VisualizationError): VisualizationResult<never> => ({ ok: false, error })

export class VisualizationProviderFacade {
  constructor(
    private readonly provider: VisualizationProvider | null,
    readonly selectionError: VisualizationError | null
  ) {}

  get id(): string | null {
    return this.provider?.id ?? null
  }

  execute<T>(operation: (provider: VisualizationProvider) => Promise<VisualizationResult<T>>): Promise<VisualizationResult<T>> {
    if (this.selectionError) return Promise.resolve(fail(this.selectionError))
    if (!this.provider) {
      return Promise.resolve(fail({ code: 'unknown-provider', message: 'Visualization provider is not selected' }))
    }
    return operation(this.provider).catch(cause =>
      fail({ code: 'provider-failure', message: 'Visualization provider operation failed', cause })
    )
  }
}

export function createVisualizationProviderFacade(
  registry: VisualizationProviderRegistry,
  selection: VisualizationProviderSelection = {}
): VisualizationProviderFacade {
  const providerId = selection.providerId === undefined ? NATIVE_BOARD_PROVIDER_ID : selection.providerId
  if (!providerId) {
    return new VisualizationProviderFacade(null, {
      code: 'unknown-provider',
      message: 'Visualization provider is explicitly empty'
    })
  }

  const provider = registry.get(providerId)
  if (!provider) {
    return new VisualizationProviderFacade(null, {
      code: 'unknown-provider',
      message: `Unknown visualization provider: ${providerId}`
    })
  }

  const context = selection.context
  if (context?.available === false) {
    const externalBlocked = provider.deploymentMode === 'optional-external'
    return new VisualizationProviderFacade(null, {
      code: externalBlocked ? 'external-blocked' : 'provider-unavailable',
      message: externalBlocked
        ? `Optional external visualization provider is disabled: ${providerId}`
        : `Visualization provider is unavailable: ${providerId}`
    })
  }
  if (context?.authenticated === false) {
    return new VisualizationProviderFacade(null, {
      code: 'provider-unauthenticated',
      message: `Visualization provider is unauthenticated: ${providerId}`,
      status: 401
    })
  }
  if (selection.expectedOwnerId && context?.ownerId !== selection.expectedOwnerId) {
    return new VisualizationProviderFacade(null, {
      code: 'ownership-mismatch',
      message: `Visualization provider ownership mismatch: ${providerId}`
    })
  }

  return new VisualizationProviderFacade(provider, null)
}

import { beforeEach, describe, expect, it, vi } from 'vitest'
import {
  createVisualizationHomeDashboardResolver,
  type VisualizationHomeDashboardResolverDependencies
} from './home-dashboard'

const dashboard = {
  id: 'home-1',
  name: 'Home dashboard',
  canvasConfig: { mode: 'fit', width: 1280, height: 720 },
  nodes: [{ id: 'node-1', type: 'text' }],
  dataSources: [{ id: 'source-1' }],
  variables: [{ name: 'tenant' }],
  thumbnail: null,
  ignoredProviderField: 'hidden'
}

describe('visualization home dashboard resolver', () => {
  let dependencies: VisualizationHomeDashboardResolverDependencies
  let probe: ReturnType<typeof vi.fn>
  let execute: ReturnType<typeof vi.fn>

  beforeEach(() => {
    probe = vi.fn().mockResolvedValue({ reachable: true, status: 200, dashboard })
    execute = vi.fn().mockResolvedValue({ ok: true, data: dashboard })
    dependencies = {
      provider: { selectionError: null, execute } as VisualizationHomeDashboardResolverDependencies['provider'],
      probe
    }
  })

  it('normalizes probe and provider responses to the small Home interface', async () => {
    const resolver = createVisualizationHomeDashboardResolver(dependencies)

    await expect(resolver.probe()).resolves.toEqual({
      reachable: true,
      status: 200,
      dashboard: {
        id: 'home-1',
        name: 'Home dashboard',
        canvasConfig: { mode: 'fit', width: 1280, height: 720 },
        nodes: [{ id: 'node-1', type: 'text' }],
        dataSources: [{ id: 'source-1' }],
        variables: [{ name: 'tenant' }],
        thumbnail: null
      }
    })
    await expect(resolver.load()).resolves.toMatchObject({ ok: true, data: { id: 'home-1', name: 'Home dashboard' } })
    expect(probe).toHaveBeenCalledTimes(1)
    expect(execute).toHaveBeenCalledTimes(1)
  })

  it('does not probe or call the provider when the optional provider is blocked', async () => {
    const selectionError = {
      code: 'external-blocked' as const,
      message: 'Optional external visualization provider is disabled'
    }
    const blockedDependencies = {
      ...dependencies,
      provider: { ...dependencies.provider, selectionError }
    }
    const resolver = createVisualizationHomeDashboardResolver(blockedDependencies)

    await expect(resolver.probe()).resolves.toEqual({ reachable: false, status: 0, dashboard: null })
    await expect(resolver.load()).resolves.toEqual({ ok: false, error: selectionError })
    expect(probe).not.toHaveBeenCalled()
    expect(execute).not.toHaveBeenCalled()
  })

  it('keeps reachability but rejects an incomplete probe dashboard', async () => {
    probe.mockResolvedValue({ reachable: true, status: 200, dashboard: { id: 'home-1', name: 'Incomplete' } })
    const resolver = createVisualizationHomeDashboardResolver(dependencies)

    await expect(resolver.probe()).resolves.toEqual({ reachable: true, status: 200, dashboard: null })
  })

  it('passes an explicit Native tenant context to the home provider', async () => {
    const getHomeDashboard = vi.fn().mockResolvedValue({ ok: true, data: dashboard })
    execute.mockImplementation((operation: (provider: { getHomeDashboard: typeof getHomeDashboard }) => unknown) =>
      operation({ getHomeDashboard }))
    const resolver = createVisualizationHomeDashboardResolver({
      ...dependencies,
      tenantId: 'tenant-1'
    })

    await expect(resolver.load()).resolves.toMatchObject({ ok: true, data: { id: 'home-1' } })
    expect(getHomeDashboard).toHaveBeenCalledWith({ tenantId: 'tenant-1' })
  })
})

import { probeThingsVisHomeDashboard, type ThingsVisHomeProbeResult } from '@/service/api/thingsvis'
import { getDefaultVisualizationProviderFacade } from './composition'
import type { VisualizationProviderFacade } from './facade'
import { LEGACY_THINGSVIS_PROVIDER_ID, NATIVE_BOARD_PROVIDER_ID } from './provider-ids'
import type {
  VisualizationDashboardNode,
  VisualizationError,
  VisualizationProvider,
  VisualizationResult
} from './contracts'

/**
 * The small dashboard shape the Home page needs to render a viewer.
 * Provider-specific fields stay behind this seam; CRUD callers continue to
 * use the full VisualizationDashboardSchema contract.
 */
export interface VisualizationHomeDashboard {
  id: string
  name: string
  canvasConfig: Record<string, unknown>
  nodes: VisualizationDashboardNode[]
  dataSources: unknown[]
  variables?: unknown[]
  thumbnail?: string | null
  rendererData?: unknown
  providerId?: string
}

export interface VisualizationHomeProbeResult {
  reachable: boolean
  status: number
  dashboard: VisualizationHomeDashboard | null
}

export type VisualizationHomeLoadResult = VisualizationResult<VisualizationHomeDashboard | null>

type HomeProviderFacade = Pick<VisualizationProviderFacade, 'execute' | 'selectionError'>

export interface VisualizationHomeDashboardResolver {
  probe(): Promise<VisualizationHomeProbeResult>
  load(): Promise<VisualizationHomeLoadResult>
}

export interface VisualizationHomeDashboardResolverDependencies {
  provider: HomeProviderFacade
  probe: () => Promise<ThingsVisHomeProbeResult>
  providerId?: string
  tenantId?: string
}

export interface VisualizationHomeDashboardOptions {
  tenantId?: string
}

const providerSelectionFailure = (error: VisualizationError): VisualizationHomeLoadResult => ({
  ok: false,
  error
})

function isRecord(value: unknown): value is Record<string, any> {
  return Boolean(value && typeof value === 'object' && !Array.isArray(value))
}

function normalizeHomeDashboard(value: unknown, providerId?: string): VisualizationHomeDashboard | null {
  if (!isRecord(value)) return null
  if (typeof value.id !== 'string' || !value.id || typeof value.name !== 'string') return null
  if (!isRecord(value.canvasConfig) || !Array.isArray(value.nodes) || !Array.isArray(value.dataSources)) return null

  const dashboard: VisualizationHomeDashboard = {
    id: value.id,
    name: value.name,
    canvasConfig: value.canvasConfig,
    nodes: value.nodes as VisualizationDashboardNode[],
    dataSources: value.dataSources,
    variables: Array.isArray(value.variables) ? value.variables : undefined,
    thumbnail: typeof value.thumbnail === 'string' || value.thumbnail === null ? value.thumbnail : null
  }

  if ('rendererData' in value) dashboard.rendererData = value.rendererData
  if (providerId) dashboard.providerId = providerId
  return dashboard
}

function unavailableProbe(error: VisualizationError | null): VisualizationHomeProbeResult {
  return {
    reachable: false,
    status: error?.status ?? 0,
    dashboard: null
  }
}

export function createVisualizationHomeDashboardResolver(
  dependencies: VisualizationHomeDashboardResolverDependencies
): VisualizationHomeDashboardResolver {
  return {
    async probe() {
      if (dependencies.provider.selectionError) {
        return unavailableProbe(dependencies.provider.selectionError)
      }

      try {
        const result = await dependencies.probe()
        return {
          reachable: result.reachable,
          status: result.status,
          dashboard: normalizeHomeDashboard(result.dashboard, dependencies.providerId)
        }
      } catch {
        return unavailableProbe(null)
      }
    },

    async load() {
      if (dependencies.provider.selectionError) {
        return providerSelectionFailure(dependencies.provider.selectionError)
      }

      const result = await dependencies.provider.execute((provider: VisualizationProvider) => provider.getHomeDashboard(
        dependencies.tenantId ? { tenantId: dependencies.tenantId } : undefined
      ))
      if (!result.ok) return result
      return { ok: true, data: normalizeHomeDashboard(result.data, dependencies.providerId) }
    }
  }
}

async function probeNativeHomeDashboard(provider: HomeProviderFacade, tenantId?: string): Promise<ThingsVisHomeProbeResult> {
  if (provider.selectionError) {
    return { reachable: false, status: provider.selectionError.status ?? 0, dashboard: null }
  }

  try {
    const result = await provider.execute((selected: VisualizationProvider) => selected.getHomeDashboard(
      tenantId ? { tenantId } : undefined
    ))
    if (!result.ok) {
      return { reachable: false, status: result.error.status ?? 0, dashboard: null }
    }

    return {
      reachable: true,
      status: 200,
      dashboard: result.data
        ? ({ ...result.data, isPublished: result.data.published } as unknown as ThingsVisHomeProbeResult['dashboard'])
        : null
    }
  } catch {
    return { reachable: false, status: 0, dashboard: null }
  }
}

function getDefaultResolver(options: VisualizationHomeDashboardOptions = {}) {
  const useExternalProvider = import.meta.env.VITE_ENABLE_THINGSVIS_COMPAT === 'Y'
  const providerId = useExternalProvider ? LEGACY_THINGSVIS_PROVIDER_ID : NATIVE_BOARD_PROVIDER_ID
  const provider = getDefaultVisualizationProviderFacade({ providerId })

  return createVisualizationHomeDashboardResolver({
    provider,
    providerId,
    tenantId: options.tenantId,
    probe: useExternalProvider ? probeThingsVisHomeDashboard : () => probeNativeHomeDashboard(provider, options.tenantId)
  })
}

export function probeVisualizationHomeDashboard(
  options: VisualizationHomeDashboardOptions = {}
): Promise<VisualizationHomeProbeResult> {
  return getDefaultResolver(options).probe()
}

export function loadVisualizationHomeDashboard(
  options: VisualizationHomeDashboardOptions = {}
): Promise<VisualizationHomeLoadResult> {
  const resolver = getDefaultResolver(options)
  return resolver.load()
}

import type {
  CreateVisualizationDashboardPayload,
  CreateVisualizationProjectPayload,
  LocalVisualizationProvider,
  UpdateVisualizationDashboardPayload,
  UpdateVisualizationProjectPayload,
  VisualizationDashboardSchema,
  VisualizationDashboardSummary,
  VisualizationPage,
  VisualizationProject,
  VisualizationResult
} from './contracts'

interface InMemoryVisualizationProviderOptions {
  id?: string
  now?: () => string
}

const success = <T>(data: T): VisualizationResult<T> => ({ ok: true, data })
const failure = <T>(message: string): VisualizationResult<T> => ({
  ok: false,
  error: { code: 'provider-failure', message }
})

function clone<T>(value: T): T {
  return structuredClone(value)
}

function paginate<T>(items: T[], page = 1, limit = 20): VisualizationPage<T> {
  const safePage = Math.max(1, Math.floor(page))
  const safeLimit = Math.max(1, Math.floor(limit))
  const total = items.length
  return {
    items: items.slice((safePage - 1) * safeLimit, safePage * safeLimit),
    page: safePage,
    limit: safeLimit,
    total,
    totalPages: total === 0 ? 0 : Math.ceil(total / safeLimit)
  }
}

function toSummary(dashboard: VisualizationDashboardSchema, home: boolean): VisualizationDashboardSummary {
  return {
    id: dashboard.id,
    name: dashboard.name,
    description: dashboard.description,
    thumbnail: dashboard.thumbnail,
    version: dashboard.version,
    published: dashboard.published,
    publishedAt: dashboard.publishedAt,
    shareToken: dashboard.shareToken,
    home,
    projectId: dashboard.projectId,
    createdAt: dashboard.createdAt,
    updatedAt: dashboard.updatedAt
  }
}

export function createInMemoryLocalVisualizationProvider(
  options: InMemoryVisualizationProviderOptions = {}
): LocalVisualizationProvider {
  const projects = new Map<string, VisualizationProject>()
  const dashboards = new Map<string, VisualizationDashboardSchema>()
  const now = options.now ?? (() => new Date().toISOString())
  let sequence = 0
  let homeDashboardId: string | null = null
  const nextId = (prefix: string) => `${prefix}-${++sequence}`

  return {
    id: options.id ?? 'in-memory-local',
    kind: 'local',
    deploymentMode: 'local-default',

    async listProjects(params) {
      const items = [...projects.values()].map(project => ({
        ...project,
        dashboardCount: [...dashboards.values()].filter(item => item.projectId === project.id).length
      }))
      return success(clone(paginate(items, params?.page, params?.limit)))
    },

    async getProject(id) {
      const project = projects.get(id)
      return project ? success(clone(project)) : failure(`Visualization project not found: ${id}`)
    },

    async createProject(payload: CreateVisualizationProjectPayload) {
      const timestamp = now()
      const project: VisualizationProject = {
        id: nextId('project'),
        name: payload.name,
        description: payload.description ?? null,
        thumbnail: null,
        createdAt: timestamp,
        updatedAt: timestamp,
        dashboardCount: 0
      }
      projects.set(project.id, project)
      return success(clone(project))
    },

    async updateProject(id, payload: UpdateVisualizationProjectPayload) {
      const project = projects.get(id)
      if (!project) return failure(`Visualization project not found: ${id}`)
      const updated: VisualizationProject = {
        ...project,
        ...payload,
        description: payload.description ?? project.description,
        thumbnail: payload.thumbnail ?? project.thumbnail,
        updatedAt: now()
      }
      projects.set(id, updated)
      return success(clone(updated))
    },

    async deleteProject(id) {
      if (!projects.has(id)) return failure(`Visualization project not found: ${id}`)
      if ([...dashboards.values()].some(item => item.projectId === id)) {
        return failure(`Visualization project still contains dashboards: ${id}`)
      }
      projects.delete(id)
      return success(undefined)
    },

    async listDashboards(params) {
      const name = params.name?.trim().toLocaleLowerCase()
      const items = [...dashboards.values()]
        .filter(item => item.projectId === params.projectId)
        .filter(item => !name || item.name.toLocaleLowerCase().includes(name))
        .map(item => toSummary(item, item.id === homeDashboardId))
      return success(clone(paginate(items, params.page, params.limit)))
    },

    async getDashboard(id) {
      const dashboard = dashboards.get(id)
      return dashboard ? success(clone(dashboard)) : failure(`Visualization dashboard not found: ${id}`)
    },

    async getDashboardThumbnail(id) {
      const dashboard = dashboards.get(id)
      return dashboard ? success(dashboard.thumbnail) : failure(`Visualization dashboard not found: ${id}`)
    },

    async createDashboard(payload: CreateVisualizationDashboardPayload) {
      if (!projects.has(payload.projectId)) return failure(`Visualization project not found: ${payload.projectId}`)
      const timestamp = now()
      const dashboard: VisualizationDashboardSchema = {
        id: nextId('dashboard'),
        name: payload.name,
        description: payload.description ?? null,
        thumbnail: null,
        version: 1,
        canvasConfig: {
          mode: payload.canvasConfig?.mode ?? 'fixed',
          width: payload.canvasConfig?.width ?? 1920,
          height: payload.canvasConfig?.height ?? 1080,
          background: payload.canvasConfig?.background ?? null
        },
        nodes: clone(payload.nodes ?? []),
        dataSources: clone(payload.dataSources ?? []),
        variables: clone(payload.variables ?? []),
        rendererData: clone(payload.rendererData),
        published: false,
        publishedAt: null,
        shareToken: null,
        projectId: payload.projectId,
        createdAt: timestamp,
        updatedAt: timestamp
      }
      dashboards.set(dashboard.id, dashboard)
      return success(clone(dashboard))
    },

    async updateDashboard(id, payload: UpdateVisualizationDashboardPayload) {
      const dashboard = dashboards.get(id)
      if (!dashboard) return failure(`Visualization dashboard not found: ${id}`)
      const updated: VisualizationDashboardSchema = {
        ...dashboard,
        ...payload,
        canvasConfig: payload.canvasConfig
          ? clone(payload.canvasConfig as VisualizationDashboardSchema['canvasConfig'])
          : dashboard.canvasConfig,
        nodes: payload.nodes ? clone(payload.nodes) : dashboard.nodes,
        dataSources: payload.dataSources ? clone(payload.dataSources) : dashboard.dataSources,
        variables: payload.variables ? clone(payload.variables) : dashboard.variables,
        rendererData: payload.rendererData === undefined ? dashboard.rendererData : clone(payload.rendererData),
        version: dashboard.version + 1,
        updatedAt: now()
      }
      dashboards.set(id, updated)
      return success(clone(updated))
    },

    async deleteDashboard(id) {
      if (!dashboards.has(id)) return failure(`Visualization dashboard not found: ${id}`)
      dashboards.delete(id)
      if (homeDashboardId === id) homeDashboardId = null
      return success(undefined)
    },

    async publishDashboard(id) {
      const dashboard = dashboards.get(id)
      if (!dashboard) return failure(`Visualization dashboard not found: ${id}`)
      const timestamp = now()
      const published = {
        ...dashboard,
        published: true,
        publishedAt: timestamp,
        shareToken: dashboard.shareToken ?? nextId('share'),
        version: dashboard.version + 1,
        updatedAt: timestamp
      }
      dashboards.set(id, published)
      return success(clone(published))
    },

    async duplicateDashboard(id) {
      const dashboard = dashboards.get(id)
      if (!dashboard) return failure(`Visualization dashboard not found: ${id}`)
      const timestamp = now()
      const duplicate: VisualizationDashboardSchema = {
        ...clone(dashboard),
        id: nextId('dashboard'),
        name: `${dashboard.name} Copy`,
        version: 1,
        published: false,
        publishedAt: null,
        shareToken: null,
        createdAt: timestamp,
        updatedAt: timestamp
      }
      dashboards.set(duplicate.id, duplicate)
      return success(clone(duplicate))
    },

    async setHomeDashboard(id) {
      if (!dashboards.has(id)) return failure(`Visualization dashboard not found: ${id}`)
      homeDashboardId = id
      return success(undefined)
    },

    async unsetHomeDashboard(id) {
      if (!dashboards.has(id)) return failure(`Visualization dashboard not found: ${id}`)
      if (homeDashboardId === id) homeDashboardId = null
      return success(undefined)
    },

    async getHomeDashboard() {
      if (!homeDashboardId) return success(null)
      const dashboard = dashboards.get(homeDashboardId)
      return dashboard ? success(clone(dashboard)) : success(null)
    }
  }
}

import {
  createThingsVisDashboard,
  createThingsVisProject,
  deleteThingsVisDashboard,
  deleteThingsVisProject,
  duplicateThingsVisDashboard,
  getThingsVisDashboard,
  getThingsVisDashboards,
  getThingsVisDashboardThumbnail,
  getThingsVisHomeDashboard,
  getThingsVisProject,
  getThingsVisProjects,
  publishThingsVisDashboard,
  setHomeThingsVisDashboard,
  unsetHomeThingsVisDashboard,
  updateThingsVisDashboard,
  updateThingsVisProject
} from '@/service/api/thingsvis'
import { LEGACY_THINGSVIS_PROVIDER_ID } from './provider-ids'
import type {
  ThirdPartyVisualizationProvider,
  VisualizationDashboardSchema,
  VisualizationDashboardSummary,
  VisualizationError,
  VisualizationPage,
  VisualizationProject,
  VisualizationResult
} from './contracts'

type LegacyResult<T> = { data: T | null; error: { message?: string; status?: number } | string | null }

const invalid = (message: string): VisualizationResult<never> => ({
  ok: false,
  error: { code: 'invalid-response', message }
})

function legacyError(error: LegacyResult<unknown>['error']): VisualizationError {
  const status = typeof error === 'object' && error ? error.status : undefined
  return {
    code: status === 401 ? 'provider-unauthenticated' : 'provider-failure',
    message: (typeof error === 'object' && error ? error.message : error) || 'Legacy ThingsVis provider failed',
    status
  }
}

function isRecord(value: unknown): value is Record<string, any> {
  return Boolean(value && typeof value === 'object' && !Array.isArray(value))
}

function requiredString(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0
}

function mapProject(value: unknown): VisualizationProject | null {
  if (!isRecord(value) || !requiredString(value.id) || typeof value.name !== 'string') return null
  if (typeof value.createdAt !== 'string' || typeof value.updatedAt !== 'string') return null
  return {
    id: value.id,
    name: value.name,
    description: typeof value.description === 'string' ? value.description : null,
    thumbnail: typeof value.thumbnail === 'string' ? value.thumbnail : null,
    tenantId: typeof value.tenantId === 'string' ? value.tenantId : undefined,
    ownerId: typeof value.createdById === 'string' ? value.createdById : undefined,
    createdAt: value.createdAt,
    updatedAt: value.updatedAt,
    dashboardCount: typeof value._count?.dashboards === 'number' ? value._count.dashboards : undefined
  }
}

function mapDashboardSummary(value: unknown): VisualizationDashboardSummary | null {
  if (!isRecord(value) || !requiredString(value.id) || typeof value.name !== 'string') return null
  if (!requiredString(value.projectId) || typeof value.createdAt !== 'string' || typeof value.updatedAt !== 'string') return null
  if (typeof value.version !== 'number' || typeof value.isPublished !== 'boolean' || typeof value.homeFlag !== 'boolean') return null
  return {
    id: value.id,
    name: value.name,
    description: null,
    thumbnail: typeof value.thumbnail === 'string' ? value.thumbnail : null,
    version: value.version,
    published: value.isPublished,
    isPublished: value.isPublished,
    publishedAt: typeof value.publishedAt === 'string' ? value.publishedAt : null,
    shareToken: typeof value.shareToken === 'string' ? value.shareToken : null,
    home: value.homeFlag,
    homeFlag: value.homeFlag,
    projectId: value.projectId,
    createdAt: value.createdAt,
    updatedAt: value.updatedAt
  }
}

function mapDashboard(value: unknown): VisualizationDashboardSchema | null {
  if (!isRecord(value) || !requiredString(value.id) || typeof value.name !== 'string') return null
  if (!isRecord(value.canvasConfig) || !Array.isArray(value.nodes) || !Array.isArray(value.dataSources)) return null
  if (!requiredString(value.projectId) || typeof value.createdAt !== 'string' || typeof value.updatedAt !== 'string') return null
  if (typeof value.version !== 'number' || typeof value.isPublished !== 'boolean') return null
  const canvas = value.canvasConfig
  if (typeof canvas.mode !== 'string' || typeof canvas.width !== 'number' || typeof canvas.height !== 'number') return null
  return {
    id: value.id,
    name: value.name,
    description: null,
    thumbnail: typeof value.thumbnail === 'string' ? value.thumbnail : null,
    version: value.version,
    canvasConfig: {
      mode: canvas.mode,
      width: canvas.width,
      height: canvas.height,
      background: typeof canvas.background === 'string' || isRecord(canvas.background) ? canvas.background : null
    },
    nodes: value.nodes,
    dataSources: value.dataSources,
    variables: Array.isArray(value.variables) ? value.variables : undefined,
    published: value.isPublished,
    publishedAt: typeof value.publishedAt === 'string' ? value.publishedAt : null,
    shareToken: typeof value.shareToken === 'string' ? value.shareToken : null,
    projectId: value.projectId,
    ownerId: typeof value.createdById === 'string' ? value.createdById : undefined,
    createdAt: value.createdAt,
    updatedAt: value.updatedAt
  }
}

type MappedValue<T> = { valid: true; value: T } | { valid: false }

const mapped = <T>(value: T): MappedValue<T> => ({ valid: true, value })
const unmapped = (): MappedValue<never> => ({ valid: false })

async function unwrap<T, U>(request: Promise<LegacyResult<T>>, map: (value: T) => MappedValue<U>, label: string): Promise<VisualizationResult<U>> {
  try {
    const result = await request
    if (result.error) return { ok: false, error: legacyError(result.error) }
    if (result.data === null) return invalid(`Invalid ${label} response`)
    const data = map(result.data)
    return data.valid ? { ok: true, data: data.value } : invalid(`Invalid ${label} response`)
  } catch (cause) {
    return { ok: false, error: { code: 'provider-failure', message: `Legacy ${label} request failed`, cause } }
  }
}

const mapRequired = <T>(map: (value: unknown) => T | null) => (value: unknown): MappedValue<T> => {
  const result = map(value)
  return result === null ? unmapped() : mapped(result)
}

function mapPage<T>(value: unknown, map: (item: unknown) => T | null): VisualizationPage<T> | null {
  if (!isRecord(value) || !Array.isArray(value.data) || !isRecord(value.meta)) return null
  const items = value.data.map(map)
  if (items.some(item => item === null)) return null
  const { page, limit, total, totalPages } = value.meta
  if (![page, limit, total, totalPages].every(item => typeof item === 'number')) return null
  return { items: items as T[], page, limit, total, totalPages }
}

const voidResult = async (request: Promise<LegacyResult<unknown>>): Promise<VisualizationResult<void>> => {
  try {
    const result = await request
    return result.error ? { ok: false, error: legacyError(result.error) } : { ok: true, data: undefined }
  } catch (cause) {
    return { ok: false, error: { code: 'provider-failure', message: 'Legacy ThingsVis request failed', cause } }
  }
}

function withoutUnsupportedDashboardFields<T extends { description?: string }>(payload: T): Omit<T, 'description'> {
  const { description: _description, ...supported } = payload
  return supported
}

export const legacyThingsVisProvider: ThirdPartyVisualizationProvider = {
  id: LEGACY_THINGSVIS_PROVIDER_ID,
  kind: 'third-party',
  deploymentMode: 'optional-external',
  listProjects: params => unwrap(getThingsVisProjects(params), mapRequired(value => mapPage(value, mapProject)), 'project list'),
  getProject: id => unwrap(getThingsVisProject(id), mapRequired(mapProject), 'project'),
  createProject: payload => unwrap(createThingsVisProject(payload), mapRequired(mapProject), 'project'),
  updateProject: (id, payload) => unwrap(updateThingsVisProject(id, payload), mapRequired(mapProject), 'project'),
  deleteProject: id => voidResult(deleteThingsVisProject(id)),
  listDashboards: params => unwrap(getThingsVisDashboards(params), mapRequired(value => mapPage(value, mapDashboardSummary)), 'dashboard list'),
  getDashboard: id => unwrap(getThingsVisDashboard(id), mapRequired(mapDashboard), 'dashboard'),
  getDashboardThumbnail: id => unwrap(getThingsVisDashboardThumbnail(id), value =>
    isRecord(value) && (typeof value.thumbnail === 'string' || value.thumbnail === null)
      ? mapped(value.thumbnail)
      : unmapped(), 'dashboard thumbnail'),
  createDashboard: payload => unwrap(
    createThingsVisDashboard(withoutUnsupportedDashboardFields(payload)),
    mapRequired(mapDashboard),
    'dashboard'
  ),
  updateDashboard: (id, payload) => unwrap(
    updateThingsVisDashboard(id, withoutUnsupportedDashboardFields(payload)),
    mapRequired(mapDashboard),
    'dashboard'
  ),
  deleteDashboard: id => voidResult(deleteThingsVisDashboard(id)),
  publishDashboard: id => unwrap(publishThingsVisDashboard(id), mapRequired(mapDashboard), 'dashboard'),
  duplicateDashboard: id => unwrap(duplicateThingsVisDashboard(id), mapRequired(mapDashboard), 'dashboard'),
  setHomeDashboard: id => voidResult(setHomeThingsVisDashboard(id)),
  unsetHomeDashboard: id => voidResult(unsetHomeThingsVisDashboard(id)),
  getHomeDashboard: async () => {
    try {
      const result = await getThingsVisHomeDashboard()
      if (result.error) return { ok: false, error: legacyError(result.error) }
      if (!isRecord(result.data) || !('data' in result.data)) return invalid('Invalid home dashboard response')
      const nested = result.data.data
      if (nested === null) return { ok: true, data: null }
      const dashboard = mapDashboard(nested)
      return dashboard ? { ok: true, data: dashboard } : invalid('Invalid home dashboard response')
    } catch (cause) {
      return { ok: false, error: { code: 'provider-failure', message: 'Legacy home dashboard request failed', cause } }
    }
  }
}

