import { beforeEach, describe, expect, it, vi } from 'vitest'

const boardApi = vi.hoisted(() => ({
  createBoard: vi.fn(),
  deleteBoard: vi.fn(),
  fetchPublishedBoardByShareToken: vi.fn(),
  fetchBoardById: vi.fn(),
  fetchBoards: vi.fn(),
  publishBoard: vi.fn(),
  updateBoard: vi.fn()
}))

vi.mock('@/service/api/board', () => boardApi)

import {
  NATIVE_BOARD_PROJECT_ID,
  nativeBoardProvider
} from './native-board-provider'

const timestamp = '2026-08-01T00:00:00.000Z'
const config = JSON.stringify({ version: 1, columns: 24, rowHeight: 60, widgets: [] })
const board = (overrides: Record<string, unknown> = {}) => ({
  id: 'board-1',
  name: 'Native board',
  tenant_id: 'tenant-1',
  created_at: timestamp,
  updated_at: timestamp,
  home_flag: 'N',
  config,
  description: 'Description',
  remark: null,
  menu_flag: 'N',
  vis_type: 'native',
  published: false,
  published_at: null,
  share_token: null,
  ...overrides
})

describe('native board visualization provider', () => {
  beforeEach(() => vi.clearAllMocks())

  it('is the local-default provider and keeps external project operations fail-closed', () => {
    expect(nativeBoardProvider).toMatchObject({
      id: 'native-board',
      kind: 'local',
      deploymentMode: 'local-default'
    })
  })

  it('exposes one built-in project and makes project mutation fail closed', async () => {
    expect(await nativeBoardProvider.listProjects()).toMatchObject({
      ok: true,
      data: { items: [{ id: NATIVE_BOARD_PROJECT_ID }], total: 1 }
    })
    expect(await nativeBoardProvider.getProject(NATIVE_BOARD_PROJECT_ID)).toMatchObject({ ok: true })
    expect(await nativeBoardProvider.createProject({ name: 'Other' })).toMatchObject({
      ok: false,
      error: { code: 'unsupported-operation' }
    })
  })

  it('maps paged native boards and preserves home state', async () => {
    boardApi.fetchBoards.mockResolvedValue({ data: { list: [board({ home_flag: 'Y' })], total: 21 }, error: null })

    expect(await nativeBoardProvider.listDashboards({
      projectId: NATIVE_BOARD_PROJECT_ID,
      page: 2,
      limit: 10,
      name: ' Native '
    })).toMatchObject({
      ok: true,
      data: {
        page: 2,
        limit: 10,
        total: 21,
        totalPages: 3,
        items: [{ id: 'board-1', home: true, projectId: NATIVE_BOARD_PROJECT_ID }]
      }
    })
    expect(boardApi.fetchBoards).toHaveBeenCalledWith({ page: 2, page_size: 10, vis_type: 'native', name: 'Native' })
  })

  it('maps list summaries when the paged API omits renderer config', async () => {
    boardApi.fetchBoards.mockResolvedValue({
      data: { list: [board({ config: undefined, description: null })], total: 1 },
      error: null
    })

    await expect(nativeBoardProvider.listDashboards({
      projectId: NATIVE_BOARD_PROJECT_ID,
      page: 1,
      limit: 12
    })).resolves.toMatchObject({
      ok: true,
      data: {
        items: [{ id: 'board-1', name: 'Native board', description: null }]
      }
    })
  })

  it('loads config as renderer data and rejects malformed or non-native boards', async () => {
    boardApi.fetchBoardById.mockResolvedValueOnce({ data: board(), error: null })
    expect(await nativeBoardProvider.getDashboard('board-1')).toMatchObject({
      ok: true,
      data: { id: 'board-1', description: 'Description', version: 1, rendererData: { version: 1, widgets: [] } }
    })

    boardApi.fetchBoardById.mockResolvedValueOnce({ data: board({ config: '{' }), error: null })
    expect(await nativeBoardProvider.getDashboard('board-1')).toMatchObject({ ok: false })

    boardApi.fetchBoardById.mockResolvedValueOnce({ data: board({ vis_type: 'thingsvis' }), error: null })
    expect(await nativeBoardProvider.getDashboard('board-1')).toMatchObject({ ok: false })
  })

  it('creates, updates, duplicates and deletes through the board API', async () => {
    const rendererData = { version: 1, columns: 24, rowHeight: 60, widgets: [] }
    boardApi.createBoard.mockResolvedValueOnce({ data: board(), error: null })
    expect(await nativeBoardProvider.createDashboard({
      name: 'Native board',
      description: 'Description',
      projectId: NATIVE_BOARD_PROJECT_ID,
      rendererData,
      tenantId: ' tenant-2 '
    })).toMatchObject({ ok: true, data: { id: 'board-1', description: 'Description' } })
    expect(boardApi.createBoard).toHaveBeenLastCalledWith(expect.objectContaining({
      name: 'Native board',
      description: 'Description',
      home_flag: 'N',
      menu_flag: 'N',
      vis_type: 'native',
      config: JSON.stringify(rendererData),
      tenant_id: 'tenant-2'
    }))

    boardApi.fetchBoardById.mockResolvedValue({ data: board(), error: null })
    boardApi.updateBoard.mockResolvedValue({ data: board({ name: 'Changed' }), error: null })
    expect(await nativeBoardProvider.updateDashboard('board-1', { name: 'Changed' })).toMatchObject({
      ok: true,
      data: { name: 'Changed' }
    })
    expect(boardApi.updateBoard).toHaveBeenCalledWith(expect.objectContaining({
      id: 'board-1',
      name: 'Changed',
      description: 'Description',
      home_flag: 'N',
      vis_type: 'native'
    }))

    boardApi.createBoard.mockResolvedValueOnce({ data: board({ id: 'board-2', name: 'Native board Copy' }), error: null })
    expect(await nativeBoardProvider.duplicateDashboard('board-1')).toMatchObject({
      ok: true,
      data: { id: 'board-2', name: 'Native board Copy' }
    })

    boardApi.deleteBoard.mockResolvedValue({ data: null, error: null })
    expect(await nativeBoardProvider.deleteDashboard('board-1')).toEqual({ ok: true, data: undefined })
  })

  it('rejects unsupported dashboard fields without calling board write APIs and accepts neutral values', async () => {
    const rendererData = { version: 1, columns: 24, rowHeight: 60, widgets: [] }
    const createPayload = {
      name: 'Native board',
      projectId: NATIVE_BOARD_PROJECT_ID,
      rendererData
    }

    for (const [field, value] of Object.entries({
      canvasConfig: { mode: 'fixed' },
      nodes: [{ id: 'node-1' }],
      dataSources: [{ id: 'source-1' }],
      variables: [{ id: 'variable-1' }]
    })) {
      expect(await nativeBoardProvider.createDashboard({ ...createPayload, [field]: value })).toMatchObject({
        ok: false,
        error: { code: 'unsupported-operation' }
      })
    }
    expect(boardApi.createBoard).not.toHaveBeenCalled()

    for (const [field, value] of Object.entries({
      thumbnail: 'thumbnail.png',
      canvasConfig: { mode: 'fixed' },
      nodes: [{ id: 'node-1' }],
      dataSources: [{ id: 'source-1' }],
      variables: [{ id: 'variable-1' }]
    })) {
      expect(await nativeBoardProvider.updateDashboard('board-1', { [field]: value })).toMatchObject({
        ok: false,
        error: { code: 'unsupported-operation' }
      })
    }
    expect(boardApi.fetchBoardById).not.toHaveBeenCalled()
    expect(boardApi.updateBoard).not.toHaveBeenCalled()

    boardApi.createBoard.mockResolvedValueOnce({ data: board(), error: null })
    expect(await nativeBoardProvider.createDashboard({
      ...createPayload,
      canvasConfig: null,
      nodes: [],
      dataSources: [],
      variables: []
    } as Parameters<typeof nativeBoardProvider.createDashboard>[0])).toMatchObject({ ok: true })

    boardApi.fetchBoardById.mockResolvedValue({ data: board(), error: null })
    boardApi.updateBoard.mockResolvedValue({ data: board({ description: '' }), error: null })
    expect(await nativeBoardProvider.updateDashboard('board-1', {
      description: '',
      thumbnail: null,
      canvasConfig: {},
      nodes: [],
      dataSources: [],
      variables: []
    } as Parameters<typeof nativeBoardProvider.updateDashboard>[1])).toMatchObject({ ok: true })
    expect(boardApi.updateBoard).toHaveBeenCalledWith(expect.objectContaining({ description: '' }))
  })

  it('updates home state with a complete payload and loads the native home board', async () => {
    boardApi.fetchBoardById.mockResolvedValue({ data: board(), error: null })
    boardApi.updateBoard.mockResolvedValue({ data: board({ home_flag: 'Y' }), error: null })

    expect(await nativeBoardProvider.setHomeDashboard('board-1')).toEqual({ ok: true, data: undefined })
    expect(boardApi.updateBoard).toHaveBeenCalledWith(expect.objectContaining({
      id: 'board-1',
      name: 'Native board',
      config,
      description: 'Description',
      home_flag: 'Y',
      vis_type: 'native'
    }))

    boardApi.fetchBoards.mockResolvedValue({ data: { list: [board({ home_flag: 'Y' })], total: 1 }, error: null })
    expect(await nativeBoardProvider.getHomeDashboard()).toMatchObject({ ok: true, data: { id: 'board-1' } })
    expect(boardApi.fetchBoards).toHaveBeenCalledWith({ page: 1, page_size: 1, home_flag: 'Y', vis_type: 'native' })
  })

  it('passes an explicit tenant context when loading a SYS_ADMIN home board', async () => {
    boardApi.fetchBoards.mockResolvedValue({
      data: { list: [board({ home_flag: 'Y', tenant_id: 'tenant-1' })], total: 1 },
      error: null
    })

    await expect(nativeBoardProvider.getHomeDashboard({ tenantId: 'tenant-1' })).resolves.toMatchObject({
      ok: true,
      data: { id: 'board-1', tenantId: 'tenant-1' }
    })
    expect(boardApi.fetchBoards).toHaveBeenCalledWith({
      page: 1,
      page_size: 1,
      home_flag: 'Y',
      vis_type: 'native',
      tenant_id: 'tenant-1'
    })
  })

  it('publishes native boards and loads them through a public share token', async () => {
    boardApi.fetchBoardById.mockResolvedValue({ data: board(), error: null })
    boardApi.publishBoard.mockResolvedValue({
      data: board({ published: true, published_at: timestamp, share_token: 'share-token-1' }),
      error: null
    })

    await expect(nativeBoardProvider.publishDashboard('board-1')).resolves.toMatchObject({
      ok: true,
      data: { id: 'board-1', published: true, publishedAt: timestamp, shareToken: 'share-token-1' }
    })
    expect(boardApi.publishBoard).toHaveBeenCalledWith('board-1')

    boardApi.fetchPublishedBoardByShareToken.mockResolvedValue({
      data: board({ published: true, published_at: timestamp, share_token: 'share-token-1' }),
      error: null
    })
    await expect(nativeBoardProvider.getDashboardByShareToken?.('share-token-1')).resolves.toMatchObject({
      ok: true,
      data: { published: true, shareToken: 'share-token-1' }
    })
    expect(boardApi.fetchPublishedBoardByShareToken).toHaveBeenCalledWith('share-token-1')
  })

  it('rejects invalid configs and API failures', async () => {
    expect(await nativeBoardProvider.createDashboard({
      name: 'Unsafe',
      projectId: NATIVE_BOARD_PROJECT_ID,
      rendererData: { version: 1, widgets: [{ id: 'x', x: 0, y: 0, w: 1, h: 1, type: 'text', config: { text: 'https://remote.test' } }] }
    })).toMatchObject({ ok: false })

    boardApi.fetchBoards.mockResolvedValue({ data: null, error: { message: 'offline' } })
    expect(await nativeBoardProvider.listDashboards({ projectId: NATIVE_BOARD_PROJECT_ID })).toMatchObject({
      ok: false,
      error: { code: 'provider-failure' }
    })
  })
})

import { createBoard, deleteBoard, fetchBoardById, fetchBoards, updateBoard } from '@/service/api/board'
import { fetchPublishedBoardByShareToken, publishBoard, type BoardDetail, type UpdateBoardPayload } from '@/service/api/board'
import { normalizeLocalDashboard } from '@/components/local-visualization-viewer'
import type {
  LocalVisualizationProvider,
  VisualizationDashboardSchema,
  VisualizationDashboardSummary,
  VisualizationPage,
  VisualizationProject,
  VisualizationResult
} from './contracts'

import { NATIVE_BOARD_PROJECT_ID, NATIVE_BOARD_PROVIDER_ID } from './provider-ids'

// Preserve the established direct import path while keeping the identifiers
// owned by the provider seam instead of one concrete adapter implementation.
export { NATIVE_BOARD_PROJECT_ID, NATIVE_BOARD_PROVIDER_ID } from './provider-ids'

const NATIVE_PROJECT: VisualizationProject = {
  id: NATIVE_BOARD_PROJECT_ID,
  name: 'Native boards',
  description: 'AetherLink native visualization boards',
  thumbnail: null,
  createdAt: '1970-01-01T00:00:00.000Z',
  updatedAt: '1970-01-01T00:00:00.000Z'
}

const success = <T>(data: T): VisualizationResult<T> => ({ ok: true, data })
const failure = <T>(message: string, cause?: unknown): VisualizationResult<T> => ({
  ok: false,
  error: { code: 'provider-failure', message, cause }
})

function requestError(label: string, error: unknown): VisualizationResult<never> {
  return failure(`${label} failed`, error)
}

function parseBoardConfig(board: BoardDetail): VisualizationResult<unknown> {
  if (board.vis_type !== 'native' || typeof board.config !== 'string') {
    return failure(`Board is not a native visualization: ${board.id}`)
  }
  try {
    const parsed = JSON.parse(board.config) as unknown
    const normalized = normalizeLocalDashboard(parsed)
    return normalized.ok
      ? success(parsed)
      : failure(`Native board config is invalid: ${board.id}: ${normalized.error}`)
  } catch (cause) {
    return failure(`Native board config is not valid JSON: ${board.id}`, cause)
  }
}

function boardToDashboard(board: BoardDetail): VisualizationResult<VisualizationDashboardSchema> {
  const config = parseBoardConfig(board)
  if (!config.ok) return config
  return success({
    id: board.id,
    name: board.name,
    tenantId: board.tenant_id,
    description: board.description ?? null,
    thumbnail: null,
    version: 1,
    canvasConfig: { mode: 'responsive', width: 1920, height: 1080, background: null },
    nodes: [],
    dataSources: [],
    variables: [],
    rendererData: config.data,
    published: board.published === true,
    publishedAt: board.published_at ?? null,
    shareToken: board.share_token ?? null,
    projectId: NATIVE_BOARD_PROJECT_ID,
    createdAt: board.created_at,
    updatedAt: board.updated_at
  })
}

function boardToSummary(board: BoardDetail): VisualizationResult<VisualizationDashboardSummary> {
  // The paged board API intentionally returns summary columns and omits config.
  // Do not route list items through the detail converter: a valid board summary
  // must remain listable even when its renderer payload was not selected.
  if (board.vis_type !== 'native') {
    return failure(`Board is not a native visualization: ${board.id}`)
  }
  return success({
    id: board.id,
    name: board.name,
    tenantId: board.tenant_id,
    description: board.description ?? null,
    thumbnail: null,
    version: 1,
    published: board.published === true,
    publishedAt: board.published_at ?? null,
    shareToken: board.share_token ?? null,
    home: board.home_flag === 'Y',
    projectId: NATIVE_BOARD_PROJECT_ID,
    createdAt: board.created_at,
    updatedAt: board.updated_at
  })
}

function serializeRendererData(value: unknown): VisualizationResult<string> {
  const normalized = normalizeLocalDashboard(value)
  if (!normalized.ok) return failure(`Native dashboard config is invalid: ${normalized.error}`)
  try {
    return success(JSON.stringify(value))
  } catch (cause) {
    return failure('Native dashboard config cannot be serialized', cause)
  }
}

function fullUpdatePayload(board: BoardDetail, overrides: Partial<UpdateBoardPayload> = {}): UpdateBoardPayload {
  return {
    id: board.id,
    name: board.name,
    config: board.config ?? undefined,
    home_flag: board.home_flag,
    menu_flag: board.menu_flag ?? undefined,
    description: board.description ?? undefined,
    remark: board.remark ?? undefined,
    vis_type: 'native',
    ...overrides
  }
}

async function loadNativeBoard(id: string): Promise<VisualizationResult<BoardDetail>> {
  try {
    const { data, error } = await fetchBoardById(id)
    if (error) return requestError(`Load native board ${id}`, error)
    if (!data || data.id !== id || data.vis_type !== 'native') return failure(`Native board not found: ${id}`)
    return success(data)
  } catch (cause) {
    return requestError(`Load native board ${id}`, cause)
  }
}

const unsupported = <T>(message: string): VisualizationResult<T> => ({
  ok: false,
  error: { code: 'unsupported-operation', message }
})
const isNonNeutral = (value: unknown): boolean => value !== undefined
  && value !== null
  && (!Array.isArray(value) || value.length > 0)
  && (typeof value !== 'object' || Array.isArray(value) || Object.keys(value).length > 0)
const unsupportedProject = <T>(): VisualizationResult<T> => unsupported('Native visualization uses one built-in project')

export const nativeBoardProvider: LocalVisualizationProvider = {
  id: NATIVE_BOARD_PROVIDER_ID,
  kind: 'local',
  deploymentMode: 'local-default',

  async listProjects(params) {
    const page = Math.max(1, Math.floor(params?.page ?? 1))
    const limit = Math.max(1, Math.floor(params?.limit ?? 20))
    return success({
      items: page === 1 ? [{ ...NATIVE_PROJECT }] : [],
      page,
      limit,
      total: 1,
      totalPages: 1
    })
  },

  async getProject(id) {
    return id === NATIVE_BOARD_PROJECT_ID ? success({ ...NATIVE_PROJECT }) : failure(`Visualization project not found: ${id}`)
  },

  async createProject() { return unsupportedProject() },
  async updateProject() { return unsupportedProject() },
  async deleteProject() { return unsupportedProject() },

  async listDashboards(params) {
    if (params.projectId !== NATIVE_BOARD_PROJECT_ID) return failure(`Visualization project not found: ${params.projectId}`)
    const page = Math.max(1, Math.floor(params.page ?? 1))
    const limit = Math.max(1, Math.floor(params.limit ?? 20))
    const name = params.name?.trim()
    try {
      const { data, error } = await fetchBoards({
        page,
        page_size: limit,
        vis_type: 'native',
        ...(name ? { name } : {}),
        ...(params.tenantId ? { tenant_id: params.tenantId } : {})
      })
      if (error) return requestError('List native boards', error)
      if (!data || !Array.isArray(data.list) || typeof data.total !== 'number') return failure('Invalid native board list response')
      const items: VisualizationDashboardSummary[] = []
      for (const board of data.list) {
        const summary = boardToSummary(board)
        if (!summary.ok) return summary
        items.push(summary.data)
      }
      const result: VisualizationPage<VisualizationDashboardSummary> = {
        items,
        page,
        limit,
        total: data.total,
        totalPages: data.total === 0 ? 0 : Math.ceil(data.total / limit)
      }
      return success(result)
    } catch (cause) {
      return requestError('List native boards', cause)
    }
  },

  async getDashboard(id) {
    const board = await loadNativeBoard(id)
    return board.ok ? boardToDashboard(board.data) : board
  },

  async getDashboardByShareToken(token) {
    try {
      const { data, error } = await fetchPublishedBoardByShareToken(token)
      if (error) return requestError('Load published native board', error)
      if (!data || data.vis_type !== 'native' || data.published !== true) {
        return failure('Published native board not found')
      }
      return boardToDashboard(data)
    } catch (cause) {
      return requestError('Load published native board', cause)
    }
  },

  async getDashboardThumbnail(id) {
    const board = await loadNativeBoard(id)
    return board.ok ? success(null) : board
  },

  async createDashboard(payload) {
    if (payload.projectId !== NATIVE_BOARD_PROJECT_ID) return failure(`Visualization project not found: ${payload.projectId}`)
    if ([payload.canvasConfig, payload.nodes, payload.dataSources, payload.variables].some(isNonNeutral)) {
      return unsupported('Native board layout fields are not supported')
    }
    const config = serializeRendererData(payload.rendererData)
    if (!config.ok) return config
    const tenantId = payload.tenantId?.trim()
    try {
      const { data, error } = await createBoard({
        name: payload.name,
        description: payload.description,
        config: config.data,
        home_flag: 'N',
        menu_flag: 'N',
        vis_type: 'native',
        ...(tenantId ? { tenant_id: tenantId } : {})
      })
      if (error) return requestError('Create native board', error)
      if (!data) return failure('Invalid create native board response')
      return boardToDashboard(data)
    } catch (cause) {
      return requestError('Create native board', cause)
    }
  },

  async updateDashboard(id, payload) {
    if ([payload.thumbnail, payload.canvasConfig, payload.nodes, payload.dataSources, payload.variables].some(isNonNeutral)) {
      return unsupported('Native board layout fields are not supported')
    }
    const current = await loadNativeBoard(id)
    if (!current.ok) return current
    let config = current.data.config ?? undefined
    if (payload.rendererData !== undefined) {
      const serialized = serializeRendererData(payload.rendererData)
      if (!serialized.ok) return serialized
      config = serialized.data
    }
    try {
      const { data, error } = await updateBoard(fullUpdatePayload(current.data, {
        name: payload.name ?? current.data.name,
        description: payload.description ?? current.data.description ?? undefined,
        config
      }))
      if (error) return requestError(`Update native board ${id}`, error)
      if (!data) return failure('Invalid update native board response')
      return boardToDashboard(data)
    } catch (cause) {
      return requestError(`Update native board ${id}`, cause)
    }
  },

  async deleteDashboard(id) {
    try {
      const { error } = await deleteBoard(id)
      return error ? requestError(`Delete native board ${id}`, error) : success(undefined)
    } catch (cause) {
      return requestError(`Delete native board ${id}`, cause)
    }
  },

  async publishDashboard(id) {
    const current = await loadNativeBoard(id)
    if (!current.ok) return current
    if (current.data.published && current.data.share_token) return boardToDashboard(current.data)
    try {
      const { data, error } = await publishBoard(id)
      if (error) return requestError(`Publish native board ${id}`, error)
      if (!data) return failure('Invalid publish native board response')
      return boardToDashboard(data)
    } catch (cause) {
      return requestError(`Publish native board ${id}`, cause)
    }
  },

  async duplicateDashboard(id) {
    const current = await loadNativeBoard(id)
    if (!current.ok) return current
    try {
      const { data, error } = await createBoard({
        name: `${current.data.name} Copy`,
        config: current.data.config ?? undefined,
        home_flag: 'N',
        menu_flag: current.data.menu_flag ?? undefined,
        description: current.data.description ?? undefined,
        remark: current.data.remark ?? undefined,
        vis_type: 'native',
        tenant_id: current.data.tenant_id
      })
      if (error) return requestError(`Duplicate native board ${id}`, error)
      if (!data) return failure('Invalid duplicate native board response')
      return boardToDashboard(data)
    } catch (cause) {
      return requestError(`Duplicate native board ${id}`, cause)
    }
  },

  async setHomeDashboard(id) {
    const current = await loadNativeBoard(id)
    if (!current.ok) return current
    try {
      const { error } = await updateBoard(fullUpdatePayload(current.data, { home_flag: 'Y' }))
      return error ? requestError(`Set native home board ${id}`, error) : success(undefined)
    } catch (cause) {
      return requestError(`Set native home board ${id}`, cause)
    }
  },

  async unsetHomeDashboard(id) {
    const current = await loadNativeBoard(id)
    if (!current.ok) return current
    try {
      const { error } = await updateBoard(fullUpdatePayload(current.data, { home_flag: 'N' }))
      return error ? requestError(`Unset native home board ${id}`, error) : success(undefined)
    } catch (cause) {
      return requestError(`Unset native home board ${id}`, cause)
    }
  },

  async getHomeDashboard(params) {
    try {
      const tenantId = params?.tenantId?.trim()
      const { data, error } = await fetchBoards({
        page: 1,
        page_size: 1,
        home_flag: 'Y',
        vis_type: 'native',
        ...(tenantId ? { tenant_id: tenantId } : {})
      })
      if (error) return requestError('Load native home board', error)
      if (!data || !Array.isArray(data.list)) return failure('Invalid native home board response')
      if (data.list.length === 0) return success(null)
      return boardToDashboard(data.list[0])
    } catch (cause) {
      return requestError('Load native home board', cause)
    }
  }
}

/**
 * Keeps the explicitly selected Native-board tenant context for the current
 * authenticated browser session.
 *
 * This is only a UX hint for SYS_ADMIN navigation. The backend remains the
 * authority: every board read/write still validates the tenant against the
 * authenticated claims. The entry is scoped to a stable user identity so a
 * second account in the same browser cannot inherit the previous account's
 * selected tenant.
 */

const STORAGE_KEY = 'aetherlink-native-board-tenant-context'

type ContextEntry = {
  userKey: string
  tenantId: string
  updatedAt: number
}
function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null
}

function firstString(record: Record<string, unknown>, keys: string[]): string {
  for (const key of keys) {
    const value = record[key]
    if (typeof value === 'string' && value.trim()) return value.trim()
    if (typeof value === 'number' && Number.isFinite(value)) return String(value)
  }
  return ''
}

function userKey(userInfo: unknown): string {
  const record = asRecord(userInfo)
  if (!record) return ''
  return firstString(record, ['id', 'userId', 'user_id', 'userName', 'username', 'email'])
}

function getSessionStorage(): Storage | null {
  try {
    return typeof window === 'undefined' ? null : window.sessionStorage
  } catch {
    return null
  }
}

export function readNativeBoardTenantContext(userInfo: unknown): string {
  const currentUserKey = userKey(userInfo)
  if (!currentUserKey) return ''

  const storage = getSessionStorage()
  if (!storage) return ''

  try {
    const raw = storage.getItem(STORAGE_KEY)
    if (!raw) return ''
    const entry = JSON.parse(raw) as Partial<ContextEntry>
    if (entry.userKey !== currentUserKey || typeof entry.tenantId !== 'string') return ''
    return entry.tenantId.trim()
  } catch {
    return ''
  }
}

export function writeNativeBoardTenantContext(userInfo: unknown, tenantId: string | null | undefined): void {
  const currentUserKey = userKey(userInfo)
  const storage = getSessionStorage()
  if (!storage || !currentUserKey) return

  const normalizedTenantId = String(tenantId || '').trim()
  try {
    if (!normalizedTenantId) {
      storage.removeItem(STORAGE_KEY)
      return
    }
    const entry: ContextEntry = {
      userKey: currentUserKey,
      tenantId: normalizedTenantId,
      updatedAt: Date.now()
    }
    storage.setItem(STORAGE_KEY, JSON.stringify(entry))
  } catch {
    // Storage can be unavailable in privacy mode; board operations must still
    // work because this cache is not part of the authorization contract.
  }
}

export function clearNativeBoardTenantContext(): void {
  const storage = getSessionStorage()
  if (!storage) return
  try {
    storage.removeItem(STORAGE_KEY)
  } catch {
    // Ignore unavailable session storage.
  }
}

