/**
 * 文件用途：定义 应用全局状态模块 的 Pinia 状态模块。
 * 核心逻辑：维护模块状态、计算属性和动作，并把状态变化暴露给页面、组件和路由流程。
 * 关键注意事项：状态字段、持久化键和跨模块调用属于前端契约，调整时需要同步测试与调用方。
 * 重构建议：可将副作用、接口访问和纯状态推导拆分，降低 store 文件复杂度。
 */
import { effectScope, onScopeDispose, ref, watch } from 'vue'
import { defineStore } from 'pinia'
import { breakpointsTailwind, useBreakpoints, useTitle } from '@vueuse/core'
import { useBoolean } from '@aetherlink/hooks'
import { message } from '@/utils/common/discrete'
import { router } from '@/router'
import { resolveDocumentTitle } from '@/router/guard/title-helper'
import { SetupStoreId } from '@/enum'
import { $t, setLocale } from '@/locales'
import { setDayjsLocale } from '@/locales/dayjs'
import { localStg } from '@/utils/storage'
import { getToken } from '../auth/shared'
import { useRouteStore } from '../route'
import { useSysSettingStore } from '../sys-setting'
import { useTabStore } from '../tab'
import { useThemeStore } from '../theme'

export const useAppStore = defineStore(SetupStoreId.App, () => {
  const themeStore = useThemeStore()
  const routeStore = useRouteStore()
  const sysSettingStore = useSysSettingStore()
  const tabStore = useTabStore()
  const scope = effectScope()
  const breakpoints = useBreakpoints(breakpointsTailwind)
  const { bool: themeDrawerVisible, setTrue: openThemeDrawer, setFalse: closeThemeDrawer } = useBoolean()
  const { bool: reloadFlag, setBool: setReloadFlag } = useBoolean(true)
  const { bool: fullContent, setBool: setFullContent, toggle: toggleFullContent } = useBoolean()
  const { bool: contentXScrollable, setBool: setContentXScrollable } = useBoolean()
  const { bool: siderCollapse, setBool: setSiderCollapse, toggle: toggleSiderCollapse } = useBoolean()
  const { bool: mixSiderFixed, setBool: setMixSiderFixed, toggle: toggleMixSiderFixed } = useBoolean()

  /** Is mobile layout */
  const isMobile = breakpoints.smaller('sm')

  /**
   * Reload page
   *
   * @param duration Duration time
   */
  async function reloadPage(duration = 0) {
    setReloadFlag(false)

    if (duration > 0) {
      await new Promise(resolve => {
        setTimeout(resolve, duration)
      })
    }

    setReloadFlag(true)
  }

  const locale = ref<App.I18n.LangType>(localStg.get('lang') || 'en-US')

  const localeOptions: App.I18n.LangOption[] = [
    {
      label: 'CN',
      key: 'zh-CN'
    },
    {
      label: 'English',
      key: 'en-US'
    },
    {
      label: 'Français',
      key: 'fr-FR'
    },
    {
      label: 'Español',
      key: 'es-ES'
    }
  ]

  function changeLocale(lang: App.I18n.LangType, options: { persistRemote?: boolean } = {}) {
    const { persistRemote = true } = options
    locale.value = lang
    setLocale(lang)
    localStg.set('lang', lang)
    if (persistRemote) {
      void persistPreferredLanguage(lang)
    }
    message.success($t('common.languageSwitched'))
    // Force reload page to ensure all components update with new locale
    reloadPage(100)
  }

  async function persistPreferredLanguage(lang: App.I18n.LangType) {
    if (!getToken()) return

    try {
      const { savePreferredLanguage } = await import('@/service/api/personal-center')
      await savePreferredLanguage({ prefer_lang: lang, default_language: lang })
    } catch {
      // Keep language switching local if saving the preference fails.
    }
  }

  /** Update document title by locale */
  function updateDocumentTitleByLocale() {
    const appTitle = sysSettingStore.system_name === '' ? $t('title') : sysSettingStore.system_name
    const documentTitle = resolveDocumentTitle(router.currentRoute.value, appTitle || $t('title'), $t)
    useTitle(documentTitle)
  }

  function init() {
    setDayjsLocale(locale.value)
  }

  // watch store
  scope.run(() => {
    // watch isMobile, if is mobile, collapse sider
    watch(
      isMobile,
      newValue => {
        if (newValue) {
          setSiderCollapse(true)

          themeStore.setThemeLayout('vertical')
        }
      },
      { immediate: true }
    )

    // watch locale
    watch(locale, () => {
      // update document title by locale
      updateDocumentTitleByLocale()

      // update global menus by locale
      routeStore.updateGlobalMenusByLocale()

      // update tabs by locale
      tabStore.updateTabsByLocale()

      // set dayjs locale
      setDayjsLocale(locale.value)
    })
  })

  /** On scope dispose */
  onScopeDispose(() => {
    scope.stop()
  })

  // init
  init()

  return {
    isMobile,
    reloadFlag,
    reloadPage,
    fullContent,
    locale,
    localeOptions,
    changeLocale,
    themeDrawerVisible,
    openThemeDrawer,
    closeThemeDrawer,
    setFullContent,
    toggleFullContent,
    contentXScrollable,
    setContentXScrollable,
    siderCollapse,
    setSiderCollapse,
    toggleSiderCollapse,
    mixSiderFixed,
    setMixSiderFixed,
    toggleMixSiderFixed
  }
})

/**
 * 文件用途: Pinia 认证 store，管理 token、登录登出、用户信息和 session 清理。
 * 核心逻辑: 登录后刷新用户信息并初始化授权路由，退出时清理 auth、tab、route 和 ThingsVis token 状态。
 * 关键注意事项: RSA 密码处理、密码策略提示、token storage 和 route 初始化顺序会影响登录后导航。
 * 重构建议: 将密码策略、storage 读写和用户信息 normalize 拆成纯 helper，并覆盖登录失败/退出清理测试。
 */
import { computed, reactive, ref } from 'vue'
import { defineStore } from 'pinia'
import dayjs from 'dayjs'
import { SetupStoreId } from '@/enum'
import { useLoading } from '@aetherlink/hooks'
import { useRouterPush } from '@/hooks/common/router'
import { fetchGetUserInfo, fetchLogin, logout } from '@/service/api'
import { transformUser } from '@/service/api/auth'
import { localStg } from '@/utils/storage'
import { $t } from '@/locales'
import { createLogger } from '@/utils/logger'
import { generateRandomHexString, validPassword } from '@/utils/common/tool'
import { encryptDataByRsa } from '@/utils/security/rsa-encrypt'
import { useRouteStore } from '../route'
import { useTabStore } from '../tab'
import { clearAuthStorage, getToken, getUserInfo } from './shared'
import { clearThingsVisToken } from '@/utils/thingsvis'

const logger = createLogger('AuthStore')

function isFrontendEncryptionEnabled(rawConfig: string | null) {
  if (!rawConfig) return false

  try {
    const config: unknown = JSON.parse(rawConfig)
    if (
      !Array.isArray(config) ||
      !config.every(
        item =>
          item !== null &&
          typeof item === 'object' &&
          typeof (item as { name?: unknown }).name === 'string' &&
          (typeof (item as { enable_flag?: unknown }).enable_flag === 'string' ||
            (item as { enable_flag?: unknown }).enable_flag === undefined)
      )
    ) {
      return false
    }

    return config.some(item => item.name === 'frontend_res' && item.enable_flag === 'enable')
  } catch {
    return false
  }
}

export const useAuthStore = defineStore(SetupStoreId.Auth, () => {
  const routeStore = useRouteStore()
  const { route, toLogin, redirectFromLogin } = useRouterPush(false)
  const { loading: loginLoading, startLoading, endLoading } = useLoading()

  const token = ref(getToken())

  /** Is login */
  const isLogin = computed(() => Boolean(token.value))

  const userInfo: Api.Auth.UserInfo = reactive(getUserInfo())
  /** Reset auth store */
  async function resetStore() {
    clearAuthStorage()
    clearThingsVisToken()
    token.value = ''
    Object.assign(userInfo, {
      authority: '',
      id: '',
      userId: '',
      userName: '',
      roles: []
    })

    if (!route.value.meta.constant) {
      await toLogin()
    }

    await routeStore.resetStore()
  }

  /**
   * Login
   *
   * @param userName User name
   * @param password Password
   */
  async function login(userName: string, password: string) {
    startLoading()
    try {
      let newP = password
      // 注意: enableZcAndYzm 由多个模块通过原生 localStorage 直接读写，未纳入 localStg 类型管理。
      // 后续可统一迁移到 localStg，并在 StorageType.Local 中声明该字段。
      const enableZcAndYzmRaw = localStorage.getItem('enableZcAndYzm')
      let salt: string | null = null
      if (isFrontendEncryptionEnabled(enableZcAndYzmRaw)) {
        salt = generateRandomHexString(16)
        // RSA helper 已迁移为 WebCrypto 异步实现（RSA-OAEP/SHA-256）
        newP = await encryptDataByRsa(password + salt)
      }

      const { data: loginToken } = await fetchLogin(userName, newP, salt ?? null)
      if (!loginToken) {
        await resetStore()
        return
      }

      const { loop, info } = await loginByToken(loginToken)
      if (loop && info) {
        const password_last_updated = info.password_last_updated
        const now = new Date()
        const daysSinceUpdate = dayjs(now).diff(password_last_updated, 'day')
        // 密码不合规或超过 90 天未更新时，仍完成登录流程并跳转，由个人中心引导修改密码
        const tipFunc = async () => {
          await routeStore.initAuthRoute()
          await redirectFromLogin()
        }

        if (!validPassword(password)) {
          tipFunc()
        } else if (!info.password_last_updated || daysSinceUpdate > 90) {
          tipFunc()
        } else {
          await routeStore.initAuthRoute()
          await redirectFromLogin()
        }
      }
    } catch (error) {
      logger.error('[AuthStore] 登录失败:', error instanceof Error ? error.message : error)
      await resetStore()
    } finally {
      endLoading()
    }
  }

  /**
   * enter
   *
   * @param userId userId
   */
  async function enter(userId: string) {
    startLoading()
    const { clearTabs } = useTabStore()
    const { data: loginToken, error } = await transformUser({
      become_user_id: userId
    })

    if (!error) {
      const { info, loop } = await loginByToken(loginToken)

      clearTabs()
      if (loop) {
        await routeStore.initAuthRoute()
        await redirectFromLogin()
        if (routeStore.isInitAuthRoute) {
          window.$notification?.success({
            title: $t('page.login.common.loginSuccess'),
            content: $t('page.login.common.welcomeBack', {
              userName: info?.name
            }),
            duration: 4500
          })
        }
      }
    } else {
      await resetStore()
    }

    endLoading()
  }

  async function loginByToken(loginToken: Api.Auth.LoginToken) {
    // 1. stored in the localStorage, the later requests need it in headers
    localStg.set('token', loginToken.token)
    const expires_in = Date.now() + loginToken.expires_in * 1000
    localStg.set('token_expires_in', expires_in.toString())

    const { data: info, error } = await fetchGetUserInfo()

    if (!error) {
      // 2. store user info
      info.roles = [info.authority]
      localStg.set('userInfo', info)
      // 3. update auth route
      token.value = loginToken.token
      Object.assign(userInfo, info)

      // 4. 清除 ThingsVis token 缓存，确保使用新用户身份重新交换 SSO token
      clearThingsVisToken()

      return { loop: true, info }
    }

    return { loop: false, info }
  }
  async function requestLogout() {
    await logout()
    await resetStore()
  }

  return {
    token,
    userInfo,
    isLogin,
    loginLoading,
    resetStore,
    login,
    enter,
    requestLogout,
    loginByToken
  }
})

/**
 * 文件用途：定义 设备状态模块 的 Pinia 状态模块。
 * 核心逻辑：维护模块状态、计算属性和动作，并把状态变化暴露给页面、组件和路由流程。
 * 关键注意事项：状态字段、持久化键和跨模块调用属于前端契约，调整时需要同步测试与调用方。
 * 重构建议：可将副作用、接口访问和纯状态推导拆分，降低 store 文件复杂度。
 */
import { ref } from 'vue'
import { defineStore } from 'pinia'
import { SetupStoreId } from '@/enum'
import { deviceDetail } from '@/service/api'

export const useDeviceDataStore = defineStore(SetupStoreId.Device, () => {
  const deviceData = ref<DeviceManagement.DeviceDetail | any>({}) // 更具体的类型替换 any
  async function fetchData(id: string) {
    try {
      const { data, error } = await deviceDetail(id)
      if (!error) {
        deviceData.value = data
      } else {
        deviceData.value = {}
      }
    } catch (error) {
      deviceData.value = {}
    }
  }

  return { deviceData, fetchData }
})

/**
 * 文件用途: Pinia 可视化编辑器基础画布 store，保存节点、视口和编辑/预览模式。
 * 核心逻辑: 提供节点增删改查、视口更新、模式切换和重置能力，并在删除节点时同步 widget 选中状态。
 * 关键注意事项: 该 store 与 widget 选择状态耦合，同时需要和 visual-editor 统一架构保持职责边界清晰。
 * 重构建议: 明确 classic 画布状态与 unified-editor 的迁移边界，并补充节点删除、视口重置和选择联动测试。
 */
import { defineStore } from 'pinia'
import type { GraphData, CanvasState } from '@/components/visual-editor/types/base-types'
import { useWidgetStore } from './widget'

// Visual editor canvas state.
interface EditorState {
  nodes: GraphData[]
  viewport: {
    zoom: number
    offsetX: number
    offsetY: number
  }
  mode: 'edit' | 'preview'
}

export const useEditorStore = defineStore('editor', {
  state: (): EditorState => ({
    nodes: [],
    viewport: {
      zoom: 1,
      offsetX: 0,
      offsetY: 0
    },
    mode: 'edit'
  }),
  getters: {
    selectedNodeId: (): string | undefined => {
      const widgetStore = useWidgetStore()
      return widgetStore.selectedIds[0]
    }
  },
  actions: {
    // 节点操作
    addNode(node: GraphData) {
      const widgetStore = useWidgetStore()
      this.nodes.push(node)
      widgetStore.selectNodes([node.id])
    },
    removeNode(id: string) {
      const widgetStore = useWidgetStore()
      this.nodes = this.nodes.filter(node => node.id !== id)
      widgetStore.removeNodeFromSelection(id)
    },
    updateNode(id: string, updates: Partial<GraphData>) {
      const nodeIndex = this.nodes.findIndex(node => node.id === id)
      if (nodeIndex !== -1) {
        this.nodes[nodeIndex] = {
          ...this.nodes[nodeIndex],
          ...updates,
          metadata: {
            ...this.nodes[nodeIndex].metadata,
            updatedAt: Date.now()
          }
        }
      }
    },

    // 视口操作
    updateViewport(updates: Partial<EditorState['viewport']>) {
      Object.assign(this.viewport, updates)
    },

    // 模式切换
    setMode(mode: 'edit' | 'preview') {
      this.mode = mode
    },

    // 重置状态
    reset() {
      this.nodes = []
      this.viewport = { zoom: 1, offsetX: 0, offsetY: 0 }
      this.mode = 'edit'
    }
  }
})

/**
 * 文件用途: Pinia 路由 store，管理动态路由、菜单、缓存路由、面包屑和本地化后的导航状态。
 * 核心逻辑: 根据 auth route mode 合并 generated routes 与后端路由，并把授权路由注册到 Vue Router。
 * 关键注意事项: 登录刷新、权限 guard、菜单可见性和兼容 route supplement 都依赖初始化顺序。
 * 重构建议: 保持 route 生成纯函数在 shared.ts 中可测，拆分后端路由 normalize 与 Vue Router 注册副作用。
 */
import { computed, ref } from 'vue'
import type { RouteRecordRaw } from 'vue-router'
import { defineStore } from 'pinia'
import { useBoolean } from '@aetherlink/hooks'
import type { CustomRoute, ElegantConstRoute, LastLevelRouteKey, RouteKey, RouteMap } from '@elegant-router/types'
import { router } from '@/router'
import { SetupStoreId } from '@/enum'
import { ROOT_ROUTE, createRoutes, getAuthVueRoutes } from '@/router/routes'
import { getRouteName, getRoutePath } from '@/router/elegant/transform'
import { fetchGetUserRoutes } from '@/service/api'
import { useAppStore } from '../app'
import { useAuthStore } from '../auth'
import { useTabStore } from '../tab'
import {
  filterAuthRoutesByRoles,
  getBreadcrumbsByRoute,
  getCacheRouteNames,
  getGlobalMenusByAuthRoutes,
  getSelectedMenuKeyPathByKey,
  isRouteExistByRouteName,
  sortRoutesByOrder,
  updateLocaleOfGlobalMenus
} from './shared'

function routeAllowsRoles(route: ElegantConstRoute, roles: string[]) {
  const routeRoles = route.meta?.roles || []
  if (!routeRoles.length) return true
  if (roles.includes('SYS_ADMIN')) return true
  return routeRoles.some(role => roles.includes(role))
}

export const useRouteStore = defineStore(SetupStoreId.Route, () => {
  const appStore = useAppStore()
  const authStore = useAuthStore()
  const tabStore = useTabStore()
  const { bool: isInitAuthRoute, setBool: setIsInitAuthRoute } = useBoolean()
  const removeRouteFns: (() => void)[] = []

  /**
   * Auth route mode
   *
   * It recommends to use static mode in the development environment, and use dynamic mode in the production
   * environment, if you use static mode in development environment, the auth routes will be auto generated by plugin
   * "@elegant-router/vue"
   */
  const authRouteMode = ref(import.meta.env.VITE_AUTH_ROUTE_MODE)
  /** Home route key */
  const routeHome = ref(import.meta.env.VITE_ROUTE_HOME)
  const DYNAMIC_ROUTE_SUPPLEMENTS: Partial<Record<RouteKey, RouteKey[]>> = {
    device: ['device_share', 'device_shared-with-me'],
    management: ['management_setting'],
    // Visualization detail routes are not menu entries. Keep the local native
    // routes and hybrid compatibility routes reachable when dynamic auth data
    // only returns the visualization parent or a subset of children. The page
    // chooses Native by default; the provider seam still blocks explicit
    // Legacy selection when the optional external profile is disabled.
    visualization: [
      'visualization_thingsvis',
      'visualization_thingsvis-dashboards',
      'visualization_thingsvis-editor',
      'visualization_thingsvis-menu-dashboard',
      'visualization_thingsvis-preview',
      'visualization_native-boards',
      'visualization_native-board',
      'visualization_native-board-editor'
    ]
  }

  /**
   * Set route home
   *
   * @param routeKey Route key
   */
  function setRouteHome(routeKey: LastLevelRouteKey) {
    routeHome.value = routeKey
  }

  /** Global menus */
  const menus = ref<App.Global.Menu[]>([])

  /** Get global menus */
  function getGlobalMenus(routes: ElegantConstRoute[]) {
    menus.value = getGlobalMenusByAuthRoutes(routes)
  }

  /** Update global menus by locale */
  function updateGlobalMenusByLocale() {
    menus.value = updateLocaleOfGlobalMenus(menus.value)
  }

  /** Cache routes */
  const cacheRoutes = ref<RouteKey[]>([])

  /**
   * Get cache routes
   *
   * @param routes Vue routes
   */
  function getCacheRoutes(routes: RouteRecordRaw[]) {
    const { constantVueRoutes } = createRoutes()

    cacheRoutes.value = getCacheRouteNames([...constantVueRoutes, ...routes])
  }

  /**
   * Add cache routes
   *
   * @param routeKey
   */
  function addCacheRoutes(routeKey: RouteKey) {
    if (cacheRoutes.value.includes(routeKey)) return

    cacheRoutes.value.push(routeKey)
  }

  /**
   * Remove cache routes
   *
   * @param routeKey
   */
  function removeCacheRoutes(routeKey: RouteKey) {
    const index = cacheRoutes.value.findIndex(item => item === routeKey)

    if (index === -1) return

    cacheRoutes.value.splice(index, 1)
  }

  /**
   * Re-cache routes by route key
   *
   * @param routeKey
   */
  async function reCacheRoutesByKey(routeKey: RouteKey) {
    removeCacheRoutes(routeKey)

    await appStore.reloadPage()

    addCacheRoutes(routeKey)
  }

  /**
   * Re-cache routes by route keys
   *
   * @param routeKeys
   */
  async function reCacheRoutesByKeys(routeKeys: RouteKey[]) {
    for await (const key of routeKeys) {
      await reCacheRoutesByKey(key)
    }
  }

  /** Global breadcrumbs */
  const breadcrumbs = computed(() => getBreadcrumbsByRoute(router.currentRoute.value, menus.value))

  /** Reset store */
  async function resetStore() {
    routeHome.value = import.meta.env.VITE_ROUTE_HOME
    menus.value = []
    cacheRoutes.value = []
    setIsInitAuthRoute(false)
    resetVueRoutes()
  }

  /** Reset vue routes */
  function resetVueRoutes() {
    removeRouteFns.forEach(fn => fn())
    removeRouteFns.length = 0
  }

  /** Init auth route */
  async function initAuthRoute(): Promise<boolean> {
    let success = false
    if (authRouteMode.value === 'static') {
      success = await initStaticAuthRoute()
    } else {
      success = await initDynamicAuthRoute()
    }

    if (success) {
      tabStore.initHomeTab()
    }

    return success
  }

  /** Init static auth route */
  async function initStaticAuthRoute(): Promise<boolean> {
    const { authRoutes } = createRoutes()

    const filteredAuthRoutes = filterAuthRoutesByRoles(authRoutes, authStore?.userInfo?.roles as string[])

    handleAuthRoutes(filteredAuthRoutes)

    setIsInitAuthRoute(true)

    return true // Indicate success
  }

  /** Init dynamic auth route */
  async function initDynamicAuthRoute(): Promise<boolean> {
    const { data, error } = await fetchGetUserRoutes()

    if (!error) {
      const routes = mergeDynamicRouteSupplements(data?.list || [])

      handleAuthRoutes(routes)

      setRouteHome('home')

      handleUpdateRootRouteRedirect('home')

      setIsInitAuthRoute(true)

      return true // Indicate success
    }

    return false // Indicate failure
  }

  function mergeDynamicRouteSupplements(routes: ElegantConstRoute[]): ElegantConstRoute[] {
    const { authRoutes } = createRoutes()
    // These routes are hybrid compatibility entry points, not an opt-in
    // external-service permission boundary. Keep them resolvable so
    // provider=native works in Native-only deployments; the provider facade
    // rejects provider=legacy when VITE_ENABLE_THINGSVIS_COMPAT is not Y.
    const mergedRoutes = routes.map(route => cloneRoute(route))
    const currentRoles = Array.isArray(authStore.userInfo?.roles) ? authStore.userInfo.roles : []

    Object.entries(DYNAMIC_ROUTE_SUPPLEMENTS).forEach(([parentName, childNames]) => {
      const parentRouteName = parentName as RouteKey
      const parentRoute = findRouteByName(mergedRoutes, parentRouteName)
      const localParentRoute = findRouteByName(authRoutes, parentRouteName)

      if (!parentRoute || !localParentRoute?.children?.length) return

      const existingChildNames = new Set((parentRoute.children || []).map(child => child.name as RouteKey))
      const supplementChildren: ElegantConstRoute[] = childNames
        .map(childName => findRouteByName(localParentRoute.children || [], childName))
        .filter((child): child is ElegantConstRoute => Boolean(child))
        .filter(child => !existingChildNames.has(child.name as RouteKey))
        .filter(child => routeAllowsRoles(child, currentRoles))
        .map(child => {
          const supplementChild = cloneRoute(child)
          supplementChild.meta = {
            ...supplementChild.meta,
            title: supplementChild.meta?.title || child.name,
            hideInMenu: true,
            activeMenu: parentRouteName
          }
          return supplementChild
        })

      if (!supplementChildren.length) return

      parentRoute.children = [...(parentRoute.children || []), ...supplementChildren]
    })

    return mergedRoutes
  }

  function findRouteByName(routes: ElegantConstRoute[], routeName: RouteKey): ElegantConstRoute | null {
    for (const route of routes) {
      if (route.name === routeName) return route
      if (route.children?.length) {
        const childRoute = findRouteByName(route.children, routeName)
        if (childRoute) return childRoute
      }
    }

    return null
  }

  function cloneRoute<T extends ElegantConstRoute>(route: T): T {
    return {
      ...route,
      meta: route.meta ? { ...route.meta } : route.meta,
      children: route.children?.map(child => cloneRoute(child))
    }
  }

  /**
   * Handle routes
   *
   * @param routes Auth routes
   */
  function handleAuthRoutes(routes: ElegantConstRoute[]) {
    const sortRoutes = sortRoutesByOrder(routes)

    const vueRoutes = getAuthVueRoutes(sortRoutes)

    addRoutesToVueRouter(vueRoutes)

    getGlobalMenus(sortRoutes)

    getCacheRoutes(vueRoutes)
  }

  /**
   * Add routes to vue router
   *
   * @param routes Vue routes
   */
  function addRoutesToVueRouter(routes: RouteRecordRaw[]) {
    routes.forEach(route => {
      const removeFn = router.addRoute(route)
      addRemoveRouteFn(removeFn)
    })
  }

  /**
   * Add remove route fn
   *
   * @param fn
   */
  function addRemoveRouteFn(fn: () => void) {
    removeRouteFns.push(fn)
  }

  /**
   * Update root route redirect when auth route mode is dynamic
   *
   * @param redirectKey Redirect route key
   */
  function handleUpdateRootRouteRedirect(redirectKey: LastLevelRouteKey) {
    const redirect = getRoutePath(redirectKey)

    if (redirect) {
      const rootRoute: CustomRoute = { ...ROOT_ROUTE, redirect }

      router.removeRoute(rootRoute.name)

      const [rootVueRoute] = getAuthVueRoutes([rootRoute])

      router.addRoute(rootVueRoute)
    }
  }

  /**
   * Get is auth route exist
   *
   * @param routePath Route path
   */
  async function getIsAuthRouteExist(routePath: RouteMap[RouteKey]) {
    const routeName = getRouteName(routePath)

    if (!routeName) {
      return false
    }

    const { authRoutes } = createRoutes()

    if (isRouteExistByRouteName(routeName, authRoutes)) {
      return true
    }

    if (authRouteMode.value === 'static') {
      return isRouteExistByRouteName(routeName, authRoutes)
    }

    return false
  }

  /**
   * Get selected menu key path
   *
   * @param selectedKey Selected menu key
   */
  function getSelectedMenuKeyPath(selectedKey: string) {
    return getSelectedMenuKeyPathByKey(selectedKey, menus.value)
  }

  return {
    resetStore,
    routeHome,
    menus,
    updateGlobalMenusByLocale,
    cacheRoutes,
    reCacheRoutesByKey,
    reCacheRoutesByKeys,
    breadcrumbs,
    initAuthRoute,
    isInitAuthRoute,
    setIsInitAuthRoute,
    getIsAuthRouteExist,
    getSelectedMenuKeyPath
  }
})

/**
 * 文件用途: route store 的纯转换 helper 集合。
 * 核心逻辑: 处理权限过滤、菜单生成、排序、缓存路由、面包屑和 locale 更新。
 * 关键注意事项: route key、meta、roles 和 menu order 的转换会影响权限边界与可见导航。
 * 重构建议: 将每类转换保持为无副作用函数，并补充后端路由缺字段、角色不匹配和缓存路由测试。
 */
import type { RouteLocationNormalizedLoaded, RouteRecordRaw, _RouteRecordBase } from 'vue-router'
import type { ElegantConstRoute, LastLevelRouteKey, RouteKey, RouteMap } from '@elegant-router/types'
import { useSvgIconRender } from '@aetherlink/hooks'
import SvgIcon from '@/components/custom/svg-icon.vue'
import { resolveRouteLabel } from '@/utils/router/resolve-route-label'

/**
 * 按角色过滤鉴权路由。
 *
 * @param routes 鉴权路由列表
 * @param roles 当前用户角色
 */
export function filterAuthRoutesByRoles(routes: ElegantConstRoute[], roles: string[]) {
  const SUPER_ROLE = 'SYS_ADMIN'
  // 超级管理员直接保留全部路由，避免重复递归裁剪。
  if (roles?.includes(SUPER_ROLE)) {
    return routes
  }

  return routes.flatMap(route => filterAuthRouteByRoles(route, roles))
}

/**
 * 递归过滤单个鉴权路由及其子路由。
 *
 * @param route 当前路由
 * @param roles 当前用户角色
 */
function filterAuthRouteByRoles(route: ElegantConstRoute, roles: string[]) {
  const routeRoles = (route.meta && route.meta.roles) || []
  const currentRoles = Array.isArray(roles) ? roles : []

  // 只要命中任一角色即可保留该路由。
  const hasPermission = !routeRoles.length || routeRoles.some(role => currentRoles.includes(role))
  if (!hasPermission) return []

  const filterRoute = { ...route }

  if (filterRoute.children?.length) {
    filterRoute.children = filterRoute.children.flatMap(item => filterAuthRouteByRoles(item, roles))

    // A public parent is useful only when it still has an authorized child.
    if (!filterRoute.children.length) return []
  }

  return [filterRoute]
}

/**
 * 递归按 `meta.order` 排序单个路由树。
 */
function sortRouteByOrder(route: ElegantConstRoute) {
  if (route.children?.length) {
    route.children.sort((next, prev) => (Number(next.meta?.order) || 0) - (Number(prev.meta?.order) || 0))
    route.children.forEach(sortRouteByOrder)
  }

  return route
}

/**
 * 按 `meta.order` 排序路由列表。
 */
export function sortRoutesByOrder(routes: ElegantConstRoute[]) {
  routes.sort((next, prev) => (Number(next.meta?.order) || 0) - (Number(prev.meta?.order) || 0))
  routes.forEach(sortRouteByOrder)
  return routes
}

/**
 * 根据鉴权路由生成全局菜单树。
 */
export function getGlobalMenusByAuthRoutes(routes: ElegantConstRoute[]) {
  const menus: App.Global.Menu[] = []

  routes.forEach(route => {
    if (!route.meta?.hideInMenu) {
      const menu = getGlobalMenuByBaseRoute(route)

      if (route.children?.some(child => !child.meta?.hideInMenu)) {
        menu.children = getGlobalMenusByAuthRoutes(route.children)
      }

      menus.push(menu)
    }
  })

  return menus
}

/**
 * 重新计算全局菜单的本地化文案。
 */
export function updateLocaleOfGlobalMenus(menus: App.Global.Menu[]) {
  const result: App.Global.Menu[] = []

  menus.forEach(menu => {
    const { i18nKey, label, children } = menu

    const newLabel = resolveRouteLabel(i18nKey, label)

    const newMenu: App.Global.Menu = {
      ...menu,
      label: newLabel
    }

    if (children?.length) {
      newMenu.children = updateLocaleOfGlobalMenus(children)
    }

    result.push(newMenu)
  })

  return result
}

/**
 * 根据路由记录生成单个全局菜单节点。
 */
function getGlobalMenuByBaseRoute(route: RouteLocationNormalizedLoaded | ElegantConstRoute) {
  const { SvgIconVNode } = useSvgIconRender(SvgIcon)

  const { name, path } = route
  const { title, i18nKey, icon = import.meta.env.VITE_MENU_ICON, localIcon, remark } = route.meta ?? {}

  const label = resolveRouteLabel(i18nKey, title)

  const menu: App.Global.Menu = {
    key: name as string,
    label,
    i18nKey,
    routeKey: name as RouteKey,
    routePath: path as RouteMap[RouteKey],
    icon: SvgIconVNode({ icon, localIcon, fontSize: 20 }),
    remark: remark as string
  }

  return menu
}

/**
 * 获取需要 keep-alive 的末级路由名称。
 *
 * @param routes 两级 Vue 路由
 */
export function getCacheRouteNames(routes: RouteRecordRaw[]) {
  const cacheNames: LastLevelRouteKey[] = []

  routes.forEach(route => {
    // 只缓存末级且实际挂载组件的页面路由。
    route.children?.forEach(child => {
      if (child.component && child.meta?.keepAlive) {
        cacheNames.push(child.name as LastLevelRouteKey)
      }
    })
  })

  return cacheNames
}

/**
 * 判断路由树中是否存在指定路由名。
 */
export function isRouteExistByRouteName(routeName: RouteKey, routes: ElegantConstRoute[]) {
  return routes.some(route => recursiveGetIsRouteExistByRouteName(route, routeName))
}

/**
 * 递归判断单棵路由树中是否存在指定路由名。
 */
function recursiveGetIsRouteExistByRouteName(route: ElegantConstRoute, routeName: RouteKey) {
  let isExist = route.name === routeName

  if (isExist) {
    return true
  }

  if (route.children && route.children.length) {
    isExist = route.children.some(item => recursiveGetIsRouteExistByRouteName(item, routeName))
  }

  return isExist
}

/**
 * 获取选中菜单节点的完整 key 路径。
 */
export function getSelectedMenuKeyPathByKey(selectedKey: string, menus: App.Global.Menu[]) {
  const keyPath: string[] = []

  menus.some(menu => {
    const path = findMenuPath(selectedKey, menu)

    const find = Boolean(path?.length)

    if (find) {
      keyPath.push(...path!)
    }

    return find
  })

  return keyPath
}

/**
 * 在菜单树中查找目标节点路径。
 */
function findMenuPath(targetKey: string, menu: App.Global.Menu): string[] | null {
  const path: string[] = []

  function dfs(item: App.Global.Menu): boolean {
    path.push(item.key)

    if (item.key === targetKey) {
      return true
    }

    if (item.children) {
      for (const child of item.children) {
        if (dfs(child)) {
          return true
        }
      }
    }

    path.pop()

    return false
  }

  if (dfs(menu)) {
    return path
  }

  return null
}

/**
 * 将菜单节点转换为面包屑节点。
 */
function transformMenuToBreadcrumb(menu: App.Global.Menu) {
  const { children, ...rest } = menu

  const breadcrumb: App.Global.Breadcrumb = {
    ...rest
  }

  if (children?.length) {
    breadcrumb.options = children.map(transformMenuToBreadcrumb)
  }

  return breadcrumb
}

/**
 * 根据当前路由生成面包屑链路。
 */
export function getBreadcrumbsByRoute(
  route: RouteLocationNormalizedLoaded,
  menus: App.Global.Menu[]
): App.Global.Breadcrumb[] {
  const key = route.name as string
  const activeKey = route.meta?.activeMenu

  const menuKey = activeKey || key

  for (const menu of menus) {
    if (menu.key === menuKey) {
      const breadcrumbMenu = menuKey !== activeKey ? menu : getGlobalMenuByBaseRoute(route)

      return [transformMenuToBreadcrumb(breadcrumbMenu)]
    }

    if (menu.children?.length) {
      const result = getBreadcrumbsByRoute(route, menu.children)
      if (result.length > 0) {
        return [transformMenuToBreadcrumb(menu), ...result]
      }
    }
  }

  return []
}

/**
 * 文件用途：定义 页签状态模块 的 Pinia 状态模块。
 * 核心逻辑：维护模块状态、计算属性和动作，并把状态变化暴露给页面、组件和路由流程。
 * 关键注意事项：状态字段、持久化键和跨模块调用属于前端契约，调整时需要同步测试与调用方。
 * 重构建议：可将副作用、接口访问和纯状态推导拆分，降低 store 文件复杂度。
 */
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { defineStore } from 'pinia'
import { useEventListener } from '@vueuse/core'
import type { RouteKey } from '@elegant-router/types'
import { SetupStoreId } from '@/enum'
import { useRouterPush } from '@/hooks/common/router'
import { localStg } from '@/utils/storage'
import { useThemeStore } from '../theme'
import {
  filterTabsById,
  filterTabsByIds,
  findTabByRouteName,
  getAllTabs,
  getDefaultHomeTab,
  getFixedTabIds,
  getTabByRoute,
  isTabInTabs,
  updateTabByI18nKey,
  updateTabsByI18nKey
} from './shared'

export const useTabStore = defineStore(SetupStoreId.Tab, () => {
  const router = useRouter()
  const themeStore = useThemeStore()
  const { routerPush } = useRouterPush(false)

  /** Tabs */
  const tabs = ref<App.Global.Tab[]>([])

  /** Get active tab */
  const homeTab = ref<App.Global.Tab>()

  /** Init home tab */
  function initHomeTab() {
    homeTab.value = getDefaultHomeTab(router)
  }

  /** Get all tabs */
  const allTabs = computed(() => getAllTabs(tabs.value, homeTab.value))

  /** Active tab id */
  const activeTabId = ref<string>('')

  /**
   * Set active tab id
   *
   * @param id Tab id
   */
  function setActiveTabId(id: string) {
    activeTabId.value = id
  }

  /**
   * Init tab store
   *
   * @param currentRoute Current route
   */
  function initTabStore(currentRoute: App.Global.TabRoute) {
    addTab(currentRoute)
  }

  /**
   * Add tab
   *
   * @param route Tab route
   * @param active Whether to activate the added tab
   */
  function addTab(route: App.Global.TabRoute, active = true) {
    const tab = getTabByRoute(route)

    const isHomeTab = tab.id === homeTab.value?.id

    if (!isHomeTab && !isTabInTabs(tab.id, tabs.value)) {
      tabs.value.push(tab)
    }

    if (active) {
      setActiveTabId(tab.id)
    }
  }

  /**
   * Remove tab
   *
   * @param tabId Tab id
   */
  async function removeTab(tabId: string) {
    const isRemoveActiveTab = activeTabId.value === tabId
    const updatedTabs = filterTabsById(tabId, tabs.value)

    function update() {
      tabs.value = updatedTabs
    }

    if (!isRemoveActiveTab) {
      update()
      return
    }

    const activeTab = updatedTabs.at(-1) || homeTab.value

    if (activeTab) {
      await switchRouteByTab(activeTab)
      update()
    }
  }

  /** remove active tab */
  async function removeActiveTab() {
    await removeTab(activeTabId.value)
  }

  /**
   * remove tab by route name
   *
   * @param routeName route name
   */
  async function removeTabByRouteName(routeName: RouteKey) {
    const tab = findTabByRouteName(routeName, tabs.value)
    if (!tab) return

    await removeTab(tab.id)
  }

  /**
   * Clear tabs
   *
   * @param excludes Exclude tab ids
   */
  async function clearTabs(excludes: string[] = []) {
    const remainTabIds = [...getFixedTabIds(tabs.value), ...excludes]
    const removedTabsIds = tabs.value.map(tab => tab.id).filter(id => !remainTabIds.includes(id))

    const isRemoveActiveTab = removedTabsIds.includes(activeTabId.value)
    const updatedTabs = filterTabsByIds(removedTabsIds, tabs.value)

    function update() {
      tabs.value = updatedTabs
    }

    if (!isRemoveActiveTab) {
      update()
      return
    }

    const activeTab = updatedTabs[updatedTabs.length - 1] || homeTab.value

    await switchRouteByTab(activeTab)
    update()
  }

  /**
   * Switch route by tab
   *
   * @param tab
   */
  async function switchRouteByTab(tab: App.Global.Tab) {
    const fail = await routerPush(tab.fullPath)
    if (!fail) {
      setActiveTabId(tab.id)
    }
  }

  /**
   * Clear left tabs
   *
   * @param tabId
   */
  async function clearLeftTabs(tabId: string) {
    const tabIds = tabs.value.map(tab => tab.id)
    const index = tabIds.indexOf(tabId)
    if (index === -1) return

    const excludes = tabIds.slice(index)
    await clearTabs(excludes)
  }

  /**
   * Clear right tabs
   *
   * @param tabId
   */
  async function clearRightTabs(tabId: string) {
    const tabIds = tabs.value.map(tab => tab.id)
    const index = tabIds.indexOf(tabId)
    if (index === -1) return

    const excludes = tabIds.slice(0, index + 1)
    await clearTabs(excludes)
  }

  /**
   * Set new label of tab
   *
   * @default activeTabId
   * @param label New tab label
   * @param tabId Tab id
   */
  function setTabLabel(label: string, tabId?: string) {
    const id = tabId || activeTabId.value

    const tab = tabs.value.find(item => item.id === id)
    if (!tab) return

    tab.oldLabel = tab.label
    tab.newLabel = label
  }

  /**
   * Reset tab label
   *
   * @default activeTabId
   * @param tabId Tab id
   */
  function resetTabLabel(tabId?: string) {
    const id = tabId || activeTabId.value

    const tab = tabs.value.find(item => item.id === id)
    if (!tab) return

    tab.newLabel = undefined
  }

  /**
   * Is tab retain
   *
   * @param tabId
   */
  function isTabRetain(tabId: string) {
    if (tabId === homeTab.value?.id) return true

    const fixedTabIds = getFixedTabIds(tabs.value)

    return fixedTabIds.includes(tabId)
  }

  /** Update tabs by locale */
  function updateTabsByLocale() {
    tabs.value = updateTabsByI18nKey(tabs.value)

    if (homeTab.value) {
      homeTab.value = updateTabByI18nKey(homeTab.value)
    }
  }

  /** Cache tabs */
  function cacheTabs() {
    // 🧹 禁用localStorage缓存
    // if (!themeStore.tab.cache) return
    // localStg.set('globalTabs', tabs.value)
    return
  }

  // cache tabs when page is closed or refreshed
  useEventListener(window, 'beforeunload', () => {
    cacheTabs()
  })

  return {
    /** All tabs */
    tabs: allTabs,
    activeTabId,
    initHomeTab,
    initTabStore,
    addTab,
    removeTab,
    removeActiveTab,
    removeTabByRouteName,
    clearTabs,
    clearLeftTabs,
    clearRightTabs,
    switchRouteByTab,
    setTabLabel,
    resetTabLabel,
    isTabRetain,
    updateTabsByLocale
  }
})

/**
 * 文件用途：定义 页签状态模块 的 Pinia 状态模块。
 * 核心逻辑：维护模块状态、计算属性和动作，并把状态变化暴露给页面、组件和路由流程。
 * 关键注意事项：状态字段、持久化键和跨模块调用属于前端契约，调整时需要同步测试与调用方。
 * 重构建议：可将副作用、接口访问和纯状态推导拆分，降低 store 文件复杂度。
 */
import type { Router } from 'vue-router'
import type { LastLevelRouteKey, RouteKey, RouteMap } from '@elegant-router/types'
import { $t } from '@/locales'
import { getRoutePath } from '@/router/elegant/transform'
import { resolveRouteLabel } from '@/utils/router/resolve-route-label'

/**
 * Get all tabs
 *
 * @param tabs Tabs
 * @param homeTab Home tab
 */
export function getAllTabs(tabs: App.Global.Tab[], homeTab?: App.Global.Tab) {
  if (!homeTab) {
    return []
  }

  const fixedTabs = tabs.filter(tab => tab.fixedIndex !== undefined).sort((a, b) => a.fixedIndex! - b.fixedIndex!)

  const remainTabs = tabs.filter(tab => tab.fixedIndex === undefined)

  const allTabs = [homeTab, ...fixedTabs, ...remainTabs]

  return updateTabsLabel(allTabs)
}

/**
 * Get tab id by route
 *
 * @param route
 */
export function getTabIdByRoute(route: App.Global.TabRoute) {
  const { path, query = {}, meta } = route

  let id = path

  if (meta.multiTab) {
    const queryKeys = Object.keys(query).sort()
    const qs = queryKeys.map(key => `${key}=${query[key]}`).join('&')

    id = `${path}?${qs}`
  }

  return id
}

/**
 * Get tab by route
 *
 * @param route
 */
export function getTabByRoute(route: App.Global.TabRoute) {
  const { name, path, fullPath = path, meta } = route

  const { title, i18nKey, fixedIndexInTab } = meta

  // Get icon and localIcon from getRouteIcons function
  const { icon, localIcon } = getRouteIcons(route)

  const label = resolveRouteLabel(i18nKey, title)

  const tab: App.Global.Tab = {
    id: getTabIdByRoute(route),
    label,
    routeKey: name as LastLevelRouteKey,
    routePath: path as RouteMap[LastLevelRouteKey],
    fullPath,
    fixedIndex: fixedIndexInTab,
    icon,
    localIcon,
    i18nKey
  }

  return tab
}

/**
 * The vue router will automatically merge the metas of all matched items, and the icons here may be affected by other
 * matching items, so they need to be processed separately
 *
 * @param route
 */
export function getRouteIcons(route: App.Global.TabRoute) {
  // Set default value for icon at the beginning
  let icon: string = route?.meta?.icon || import.meta.env.VITE_MENU_ICON
  let localIcon: string | undefined = route?.meta?.localIcon

  // Route.matched only appears when there are multiple matches,so check if route.matched exists
  if (route.matched) {
    // Find the meta of the current route from matched
    const currentRoute = route.matched.find(r => r.name === route.name)
    // If icon exists in currentRoute.meta, it will overwrite the default value
    icon = currentRoute?.meta?.icon || icon
    localIcon = currentRoute?.meta?.localIcon
  }

  return { icon, localIcon }
}

/**
 * Get default home tab
 *
 * @param router
 */
export function getDefaultHomeTab(router: Router) {
  const homeRouteName = import.meta.env.VITE_ROUTE_HOME
  const homeRoutePath = getRoutePath(homeRouteName)
  const i18nLabel = resolveRouteLabel(`route.${homeRouteName}`, homeRouteName)

  let homeTab: App.Global.Tab = {
    id: getRoutePath(homeRouteName),
    label: i18nLabel || homeRouteName,
    routeKey: homeRouteName,
    routePath: homeRoutePath,
    fullPath: homeRoutePath
  }

  const routes = router.getRoutes()
  const homeRoute = routes.find(route => route.name === homeRouteName)
  if (homeRoute) {
    homeTab = getTabByRoute(homeRoute)
  }

  return homeTab
}

/**
 * Is tab in tabs
 *
 * @param tab
 * @param tabs
 */
export function isTabInTabs(tabId: string, tabs: App.Global.Tab[]) {
  return tabs.some(tab => tab.id === tabId)
}

/**
 * Filter tabs by id
 *
 * @param tabId
 * @param tabs
 */
export function filterTabsById(tabId: string, tabs: App.Global.Tab[]) {
  return tabs.filter(tab => tab.id !== tabId)
}

/**
 * Filter tabs by ids
 *
 * @param tabIds
 * @param tabs
 */
export function filterTabsByIds(tabIds: string[], tabs: App.Global.Tab[]) {
  return tabs.filter(tab => !tabIds.includes(tab.id))
}

/**
 * Get fixed tabs
 *
 * @param tabs
 */
function getFixedTabs(tabs: App.Global.Tab[]) {
  return tabs.filter(tab => tab.fixedIndex !== undefined)
}

/**
 * Get fixed tab ids
 *
 * @param tabs
 */
export function getFixedTabIds(tabs: App.Global.Tab[]) {
  const fixedTabs = getFixedTabs(tabs)

  return fixedTabs.map(tab => tab.id)
}

/**
 * Update tabs label
 *
 * @param tabs
 */
function updateTabsLabel(tabs: App.Global.Tab[]) {
  const updated = tabs.map(tab => ({
    ...tab,
    label: tab.newLabel || tab.oldLabel || tab.label
  }))

  return updated
}

/**
 * Update tab by i18n key
 *
 * @param tab
 */
export function updateTabByI18nKey(tab: App.Global.Tab) {
  const { i18nKey, label } = tab

  return {
    ...tab,
    label: i18nKey ? $t(i18nKey) : label
  }
}

/**
 * Update tabs by i18n key
 *
 * @param tabs
 */
export function updateTabsByI18nKey(tabs: App.Global.Tab[]) {
  return tabs.map(tab => updateTabByI18nKey(tab))
}

/**
 * find tab by route name
 *
 * @param name
 * @param tabs
 */
export function findTabByRouteName(name: RouteKey, tabs: App.Global.Tab[]) {
  const routePath = getRoutePath(name)

  const tabId = routePath
  const multiTabId = `${routePath}?`

  return tabs.find(tab => tab.id === tabId || tab.id.startsWith(multiTabId))
}

/**
 * 文件用途：定义 主题状态模块 的 Pinia 状态模块。
 * 核心逻辑：维护模块状态、计算属性和动作，并把状态变化暴露给页面、组件和路由流程。
 * 关键注意事项：状态字段、持久化键和跨模块调用属于前端契约，调整时需要同步测试与调用方。
 * 重构建议：可将副作用、接口访问和纯状态推导拆分，降低 store 文件复杂度。
 */
import { computed, effectScope, onScopeDispose, ref, toRefs, watch } from 'vue'
import type { Ref } from 'vue'
import { defineStore } from 'pinia'
import { useEventListener, usePreferredColorScheme } from '@vueuse/core'
import { SetupStoreId } from '@/enum'
import { localStg } from '@/utils/storage'
import { addThemeVarsToHtml, createThemeToken, getNaiveTheme, initThemeSettings, toggleCssDarkMode } from './shared'

/** Theme store */
export const useThemeStore = defineStore(SetupStoreId.Theme, () => {
  const scope = effectScope()
  const osTheme = usePreferredColorScheme()

  /** Theme settings */
  const settings: Ref<App.Theme.ThemeSetting> = ref(initThemeSettings())

  /** Dark mode */
  const darkMode = computed(() => {
    if (settings.value.themeScheme === 'auto') {
      return osTheme.value === 'dark'
    }
    return settings.value.themeScheme === 'dark'
  })

  /** Theme colors */
  const themeColors = computed(() => {
    const { themeColor, otherColor, isInfoFollowPrimary } = settings.value
    const colors: App.Theme.ThemeColor = {
      primary: themeColor,
      ...otherColor,
      info: isInfoFollowPrimary ? themeColor : otherColor.info
    }
    return colors
  })

  /** Naive theme */
  const naiveTheme = computed(() => getNaiveTheme(themeColors.value))

  /**
   * Settings json
   *
   * It is for copy settings
   */
  const settingsJson = computed(() => JSON.stringify(settings.value))

  /** Reset store */
  function resetStore() {
    settings.value = initThemeSettings()
  }

  /**
   * Set theme scheme
   *
   * @param themeScheme
   */
  function setThemeScheme(themeScheme: UnionKey.ThemeScheme) {
    settings.value.themeScheme = themeScheme
  }

  /** Toggle theme scheme */
  function toggleThemeScheme() {
    const themeSchemes: UnionKey.ThemeScheme[] = ['light', 'dark', 'auto']

    const index = themeSchemes.findIndex(item => item === settings.value.themeScheme)

    const nextIndex = index === themeSchemes.length - 1 ? 0 : index + 1

    const nextThemeScheme = themeSchemes[nextIndex]

    setThemeScheme(nextThemeScheme)
  }

  /**
   * Update theme colors
   *
   * @param key Theme color key
   * @param color Theme color
   */
  function updateThemeColors(key: App.Theme.ThemeColorKey, color: string) {
    if (key === 'primary') {
      settings.value.themeColor = color
    } else {
      settings.value.otherColor[key] = color
    }
  }

  /**
   * Set theme layout
   *
   * @param mode Theme layout mode
   */
  function setThemeLayout(mode: UnionKey.ThemeLayoutMode) {
    settings.value.layout.mode = mode
  }

  /** Setup theme vars to html */
  function setupThemeVarsToHtml() {
    const { themeTokens, darkThemeTokens } = createThemeToken(themeColors.value)
    addThemeVarsToHtml(themeTokens, darkThemeTokens)
  }

  /** Cache theme settings */
  function cacheThemeSettings() {
    const isProd = import.meta.env.PROD

    if (!isProd) return

    localStg.set('themeSettings', settings.value)
  }

  // cache theme settings when page is closed or refreshed
  useEventListener(window, 'beforeunload', () => {
    cacheThemeSettings()
  })

  // watch store
  scope.run(() => {
    // watch dark mode
    watch(
      darkMode,
      val => {
        toggleCssDarkMode(val)
      },
      { immediate: true }
    )

    // themeColors change, update css vars and storage theme color
    watch(
      themeColors,
      val => {
        setupThemeVarsToHtml()

        localStg.set('themeColor', val.primary)
      },
      { immediate: true }
    )
  })

  /** On scope dispose */
  onScopeDispose(() => {
    scope.stop()
  })

  return {
    ...toRefs(settings.value),
    darkMode,
    themeColors,
    naiveTheme,
    settingsJson,
    resetStore,
    setThemeScheme,
    toggleThemeScheme,
    updateThemeColors,
    setThemeLayout
  }
})

/**
 * 文件用途：定义 主题状态模块 的 Pinia 状态模块。
 * 核心逻辑：维护模块状态、计算属性和动作，并把状态变化暴露给页面、组件和路由流程。
 * 关键注意事项：状态字段、持久化键和跨模块调用属于前端契约，调整时需要同步测试与调用方。
 * 重构建议：可将副作用、接口访问和纯状态推导拆分，降低 store 文件复杂度。
 */
import type { GlobalThemeOverrides } from 'naive-ui'
import { getColorByColorPaletteNumber, getColorPalette } from '@aetherlink/color-palette'
import { addColorAlpha, getRgbOfColor } from '@aetherlink/utils'
import { overrideThemeSettings, themeSettings } from '@/theme/settings'
import { themeVars } from '@/theme/vars'
import { localStg } from '@/utils/storage'

const DARK_CLASS = 'dark'

/** Init theme settings */
export function initThemeSettings() {
  const isProd = import.meta.env.PROD

  // if it is development mode, the theme settings will not be cached, by update `themeSettings` in `src/theme/settings.ts` to update theme settings
  if (!isProd) return themeSettings

  // if it is production mode, the theme settings will be cached in localStorage
  // if want to update theme settings when publish new version, please update `overrideThemeSettings` in `src/theme/settings.ts`

  const settings = localStg.get('themeSettings') || themeSettings

  const isOverride = localStg.get('overrideThemeFlag') === BUILD_TIME

  if (!isOverride) {
    Object.assign(settings, overrideThemeSettings)
    localStg.set('overrideThemeFlag', BUILD_TIME)
  }

  return settings
}

/**
 * Create theme token
 *
 * @param colors Theme colors
 */
export function createThemeToken(colors: App.Theme.ThemeColor) {
  const paletteColors = createThemePaletteColors(colors)

  const themeTokens: App.Theme.ThemeToken = {
    colors: {
      ...paletteColors,
      nprogress: paletteColors.primary,
      container: 'rgb(255, 255, 255)',
      layout: 'rgb(247, 250, 252)',
      inverted: 'rgb(0, 20, 40)',
      base_text: 'rgb(31, 31, 31)'
    },
    boxShadow: {
      header: '0 1px 2px rgb(0, 21, 41, 0.08)',
      sider: '2px 0 8px 0 rgb(29, 35, 41, 0.05)',
      tab: '0 1px 2px rgb(0, 21, 41, 0.08)'
    }
  }

  const darkThemeTokens: App.Theme.ThemeToken = {
    colors: {
      ...themeTokens.colors,
      container: 'rgb(28, 28, 28)',
      layout: 'rgb(18, 18, 18)',
      base_text: 'rgb(224, 224, 224)'
    },
    boxShadow: {
      ...themeTokens.boxShadow
    }
  }

  return {
    themeTokens,
    darkThemeTokens
  }
}

/**
 * Create theme palette colors
 *
 * @param colors Theme colors
 */
function createThemePaletteColors(colors: App.Theme.ThemeColor) {
  const colorKeys = Object.keys(colors) as App.Theme.ThemeColorKey[]
  const colorPaletteVar = {} as App.Theme.ThemePaletteColor

  colorKeys.forEach(key => {
    const { palettes, main } = getColorPalette(colors[key], key)

    colorPaletteVar[key] = main.hexcode

    palettes.forEach(item => {
      colorPaletteVar[`${key}-${item.number}`] = item.hexcode
    })
  })

  return colorPaletteVar
}

/**
 * Get css var by tokens
 *
 * @param tokens Theme base tokens
 */
function getCssVarByTokens(tokens: App.Theme.BaseToken) {
  const styles: string[] = []

  function removeVarPrefix(value: string) {
    return value.replace('var(', '').replace(')', '')
  }

  function removeRgbPrefix(value: string) {
    return value.replace('rgb(', '').replace(')', '')
  }

  for (const [key, tokenValues] of Object.entries(themeVars)) {
    for (const [tokenKey, tokenValue] of Object.entries(tokenValues)) {
      let cssVarsKey = removeVarPrefix(tokenValue)
      let cssValue = tokens[key][tokenKey]

      if (key === 'colors') {
        cssVarsKey = removeRgbPrefix(cssVarsKey)
        const { r, g, b } = getRgbOfColor(cssValue)
        cssValue = `${r} ${g} ${b}`
      }

      styles.push(`${cssVarsKey}: ${cssValue}`)
    }
  }

  const styleStr = styles.join(';')

  return styleStr
}

/**
 * Add theme vars to html
 *
 * @param tokens
 */
export function addThemeVarsToHtml(tokens: App.Theme.BaseToken, darkTokens: App.Theme.BaseToken) {
  const cssVarStr = getCssVarByTokens(tokens)
  const darkCssVarStr = getCssVarByTokens(darkTokens)

  const css = `
    html {
      ${cssVarStr}
    }
  `

  const darkCss = `
    html.${DARK_CLASS} {
      ${darkCssVarStr}
    }
  `

  const style = document.createElement('style')

  style.textContent = css + darkCss

  document.head.appendChild(style)
}

/**
 * Toggle css dark mode
 *
 * @param darkMode Is dark mode
 */
export function toggleCssDarkMode(darkMode = false) {
  function addDarkClass() {
    document.documentElement.classList.add(DARK_CLASS)
  }

  function removeDarkClass() {
    document.documentElement.classList.remove(DARK_CLASS)
  }

  if (darkMode) {
    addDarkClass()
  } else {
    removeDarkClass()
  }
}

type NaiveColorScene = '' | 'Suppl' | 'Hover' | 'Pressed' | 'Active'
type NaiveColorKey = `${App.Theme.ThemeColorKey}Color${NaiveColorScene}`
type NaiveThemeColor = Partial<Record<NaiveColorKey, string>>
interface NaiveColorAction {
  scene: NaiveColorScene
  handler: (color: string) => string
}

/**
 * Get naive theme colors
 *
 * @param colors Theme colors
 */
function getNaiveThemeColors(colors: App.Theme.ThemeColor) {
  const colorActions: NaiveColorAction[] = [
    { scene: '', handler: color => color },
    { scene: 'Suppl', handler: color => color },
    { scene: 'Hover', handler: color => getColorByColorPaletteNumber(color, 500) },
    { scene: 'Pressed', handler: color => getColorByColorPaletteNumber(color, 700) },
    { scene: 'Active', handler: color => addColorAlpha(color, 0.1) }
  ]

  const themeColors: NaiveThemeColor = {}

  const colorEntries = Object.entries(colors) as [App.Theme.ThemeColorKey, string][]

  colorEntries.forEach(color => {
    colorActions.forEach(action => {
      const [colorType, colorValue] = color
      const colorKey: NaiveColorKey = `${colorType}Color${action.scene}`
      themeColors[colorKey] = action.handler(colorValue)
    })
  })

  return themeColors
}

/**
 * Get naive theme
 *
 * @param colors Theme colors
 */
export function getNaiveTheme(colors: App.Theme.ThemeColor) {
  const { primary: colorLoading } = colors

  const theme: GlobalThemeOverrides = {
    common: {
      ...getNaiveThemeColors(colors)
    },
    LoadingBar: {
      colorLoading
    }
  }

  return theme
}

