/**
 * Visual Editor Hook
 * 🔥 提供简化的API给组件使用
 */
export function useVisualEditor() {
  const system = useUnifiedVisualEditorSystem()

  return {
    // 状态访问 - 🔥 使用 computed 确保总是返回最新的服务实例
    get store() {
      return system.store
    },
    get configService() {
      return system.configService
    },
    get dataFlowManager() {
      return system.dataFlowManager
    },
    get card2Adapter() {
      return system.card2Adapter
    },

    // 系统操作
    initialize: () => system.initialize(),
    saveAll: () => system.saveAll(),
    getStatus: () => system.getSystemStatus(),
    cleanup: () => system.cleanup(),

    // 快捷操作
    addNode: async (node: any) => {
      if (!system.dataFlowManager) {
        throw new Error('数据流管理器未初始化，请先调用 initialize()')
      }
      return system.dataFlowManager.handleUserAction({
        type: 'ADD_NODE',
        data: node
      })
    },

    updateNode: async (nodeId: string, updates: any) => {
      if (!system.dataFlowManager) {
        throw new Error('数据流管理器未初始化，请先调用 initialize()')
      }
      return system.dataFlowManager.handleUserAction({
        type: 'UPDATE_NODE',
        targetId: nodeId,
        data: updates
      })
    },

    removeNode: async (nodeId: string) => {
      if (!system.dataFlowManager) {
        throw new Error('数据流管理器未初始化，请先调用 initialize()')
      }
      return system.dataFlowManager.handleUserAction({
        type: 'REMOVE_NODE',
        targetId: nodeId
      })
    },

    updateConfiguration: async (widgetId: string, section: any, config: any) => {
      if (!system.dataFlowManager) {
        throw new Error('数据流管理器未初始化，请先调用 initialize()')
      }
      return system.dataFlowManager.handleUserAction({
        type: 'UPDATE_CONFIGURATION',
        targetId: widgetId,
        data: { section, config }
      })
    },

    selectNodes: async (ids: string[]) => {
      if (!system.dataFlowManager) {
        throw new Error('数据流管理器未初始化，请先调用 initialize()')
      }
      return system.dataFlowManager.handleUserAction({
        type: 'SELECT_NODES',
        data: ids
      })
    },

    // 状态查询
    getSelectedNodes: () => {
      if (!system.store) {
        return []
      }
      return system.store.selectedNodes
    },
    getConfiguration: (widgetId: string) => {
      if (!system.configService) {
        throw new Error('配置服务未初始化，请先调用 initialize()')
      }
      return system.configService.getConfiguration(widgetId)
    },
    getRuntimeData: (widgetId: string) => {
      if (!system.configService) {
        throw new Error('配置服务未初始化，请先调用 initialize()')
      }
      return system.configService.getRuntimeData(widgetId)
    }
  }
}

/**
 * 迁移辅助工具
 * 帮助从旧系统迁移到新系统
 *
 * Boundary: old_editor_data is a compatibility persisted Visual Editor key. This
 * helper is a manual migration entrypoint only; callers must initialize the
 * unified editor system before passing the parsed payload here.
 */
export const MigrationHelper = {
  /**
   * 从旧的编辑器存储迁移数据
   */
  migrateFromOldStore(oldStoreData: any): void {
    const system = useUnifiedVisualEditorSystem()

    // 迁移节点数据
    if (oldStoreData.nodes) {
      oldStoreData.nodes.forEach((node: any) => {
        system.store.addNode(node)
      })
    }

    // 迁移选中状态
    if (oldStoreData.selectedIds) {
      system.store.selectNodes(oldStoreData.selectedIds)
    }

    // 迁移配置数据
    if (oldStoreData.configurations) {
      Object.entries(oldStoreData.configurations).forEach(([widgetId, config]: [string, any]) => {
        system.configService.setConfiguration(widgetId, config)
      })
    }
  },

  /**
   * 检查是否需要迁移
   */
  needsMigration(): boolean {
    // 检查是否存在旧的存储数据
    return localStorage.getItem('old_editor_data') !== null
  }
}

﻿/**
 * 文件用途: Pinia 统一 Visual Editor 状态 store，集中保存画布、组件注册、配置、运行时数据和系统状态。
 * 核心逻辑: 以单一数据源替代分散状态，提供节点操作、组件注册、分层配置、Card 2.1 状态和运行时数据更新。
 * 关键注意事项: 该 store 是 visual-editor 其他服务的状态基础，配置分层和 selectedIds 需要与视图交互保持一致。
 * 重构建议: 按状态域拆分可测试 selector/helper，并补充配置合并、节点选择和 Card 2.1 注册状态测试。
 */

import { defineStore } from 'pinia'
import type {
  GraphData,
  EditorMode,
  WidgetDefinition,
  WidgetConfiguration,
  ComponentDefinition,
  ReactiveDataBinding
} from '@/components/visual-editor/types'

export type {
  GraphData,
  EditorMode,
  WidgetDefinition,
  WidgetConfiguration,
  ComponentDefinition,
  ReactiveDataBinding
} from '@/components/visual-editor/types'

export interface UnifiedEditorState {
  // 编辑器核心状态
  nodes: GraphData[]
  viewport: {
    x: number
    y: number
    zoom: number
  }
  mode: EditorMode
  selectedIds: string[]

  // 组件注册状态
  widgets: Map<string, WidgetDefinition>

  // 配置管理状态 - 分层存储
  baseConfigs: Map<string, BaseConfiguration>
  componentConfigs: Map<string, ComponentConfiguration>
  dataSourceConfigs: Map<string, DataSourceConfiguration>
  interactionConfigs: Map<string, InteractionConfiguration>

  // Card 2.1 集成状态
  card2Components: Map<string, ComponentDefinition>
  dataBindings: Map<string, ReactiveDataBinding>

  // 运行时数据
  runtimeData: Map<string, unknown>

  // 系统状态
  isLoading: boolean
  isDirty: boolean
  lastSaved: Date | null
}

// 基础配置接口
export interface BaseConfiguration {
  title?: string
  opacity?: number
  visible?: boolean
  locked?: boolean
  zIndex?: number
}

// 组件配置接口
export interface ComponentConfiguration {
  properties: Record<string, unknown>
  style?: Record<string, unknown>
  events?: Record<string, unknown>
}

// 数据源配置接口
export interface DataSourceConfiguration {
  type: 'static' | 'api' | 'websocket' | 'device' | 'script'
  config: Record<string, unknown>
  bindings: Record<string, unknown>
  metadata?: Record<string, unknown>
}

// 交互配置接口
export interface InteractionConfiguration {
  click?: unknown
  hover?: unknown
  focus?: unknown
  custom?: Record<string, unknown>
}

/**
 * 统一的 Visual Editor Store
 * 🔥 这是唯一的状态管理中心，替代所有分散的状态存储
 */
export const useUnifiedEditorStore = defineStore('unified-visual-editor', {
  state: (): UnifiedEditorState => ({
    // 编辑器状态
    nodes: [],
    viewport: { x: 0, y: 0, zoom: 1 },
    mode: 'design',
    selectedIds: [],

    // 组件状态
    widgets: new Map(),

    // 配置状态 - 分层管理
    baseConfigs: new Map(),
    componentConfigs: new Map(),
    dataSourceConfigs: new Map(),
    interactionConfigs: new Map(),

    // Card 2.1 状态
    card2Components: new Map(),
    dataBindings: new Map(),

    // 运行时状态
    runtimeData: new Map(),

    // 系统状态
    isLoading: false,
    isDirty: false,
    lastSaved: null
  }),

  getters: {
    /**
     * 获取选中的节点
     */
    selectedNodes(state): GraphData[] {
      return state.nodes.filter(node => state.selectedIds.includes(node.id))
    },

    /**
     * 获取完整的组件配置
     * 🔥 关键：统一的配置访问点
     */
    getFullConfiguration:
      state =>
      (widgetId: string): WidgetConfiguration => {
        return {
          base: state.baseConfigs.get(widgetId) || createDefaultBaseConfig(),
          component: state.componentConfigs.get(widgetId) || createDefaultComponentConfig(),
          dataSource: state.dataSourceConfigs.get(widgetId) || null,
          interaction: state.interactionConfigs.get(widgetId) || createDefaultInteractionConfig(),
          metadata: generateConfigurationMetadata(widgetId, state)
        }
      },

    /**
     * 获取组件的运行时数据
     */
    getRuntimeData: state => (widgetId: string) => {
      return state.runtimeData.get(widgetId)
    },

    /**
     * 检查组件是否有未保存的更改
     */
    hasUnsavedChanges(state): boolean {
      return state.isDirty
    },

    /**
     * 获取所有已注册的组件
     */
    allWidgets(state): WidgetDefinition[] {
      return Array.from(state.widgets.values())
    },

    /**
     * 获取Card2.1组件数量
     */
    card2ComponentCount(state): number {
      return state.card2Components.size
    }
  },

  actions: {
    // ==================== 节点操作 ====================

    /**
     * 添加节点到画布
     */
    addNode(node: GraphData): void {
      this.nodes.push(node)
      this.markDirty()

      // 初始化节点的基础配置
      if (!this.baseConfigs.has(node.id)) {
        this.baseConfigs.set(node.id, createDefaultBaseConfig())
      }
    },

    /**
     * 更新节点信息
     */
    updateNode(id: string, updates: Partial<GraphData>): void {
      const nodeIndex = this.nodes.findIndex(node => node.id === id)
      if (nodeIndex !== -1) {
        this.nodes[nodeIndex] = { ...this.nodes[nodeIndex], ...updates }
        this.markDirty()
      }
    },

    /**
     * 删除节点及其所有配置
     */
    removeNode(id: string): void {
      // 移除节点
      this.nodes = this.nodes.filter(node => node.id !== id)

      // 清理所有相关配置
      this.baseConfigs.delete(id)
      this.componentConfigs.delete(id)
      this.dataSourceConfigs.delete(id)
      this.interactionConfigs.delete(id)
      this.runtimeData.delete(id)

      // 清理选中状态
      this.selectedIds = this.selectedIds.filter(selectedId => selectedId !== id)

      this.markDirty()
    },

    /**
     * 选中节点
     */
    selectNodes(ids: string[]): void {
      this.selectedIds = [...ids]
    },

    // ==================== 配置操作 ====================

    /**
     * 设置基础配置
     */
    setBaseConfiguration(widgetId: string, config: BaseConfiguration): void {
      this.baseConfigs.set(widgetId, { ...config })
      this.markDirty()
    },

    /**
     * 设置组件配置
     */
    setComponentConfiguration(widgetId: string, config: ComponentConfiguration): void {
      this.componentConfigs.set(widgetId, { ...config })
      this.markDirty()
    },

    /**
     * 设置数据源配置
     * 🔥 关键：统一的数据源配置管理
     */
    setDataSourceConfiguration(widgetId: string, config: DataSourceConfiguration): void {
      this.dataSourceConfigs.set(widgetId, { ...config })
      this.markDirty()

      // 触发数据绑定更新
      this.updateDataBinding(widgetId)
    },

    /**
     * 设置交互配置
     */
    setInteractionConfiguration(widgetId: string, config: InteractionConfiguration): void {
      this.interactionConfigs.set(widgetId, { ...config })
      this.markDirty()
    },

    /**
     * 更新运行时数据
     */
    setRuntimeData(widgetId: string, data: unknown): void {
      this.runtimeData.set(widgetId, data)
    },

    // ==================== 组件注册 ====================

    /**
     * 注册组件定义
     */
    registerWidget(definition: WidgetDefinition): void {
      this.widgets.set(definition.type, definition)
    },

    /**
     * 批量注册组件
     */
    registerWidgets(definitions: WidgetDefinition[]): void {
      definitions.forEach(def => this.registerWidget(def))
    },

    // ==================== Card 2.1 集成 ====================

    /**
     * 注册Card2.1组件
     */
    registerCard2Component(definition: ComponentDefinition): void {
      if (!definition.type) return
      this.card2Components.set(definition.type, definition)
    },

    /**
     * 创建数据绑定
     */
    createDataBinding(widgetId: string, binding: ReactiveDataBinding): void {
      this.dataBindings.set(widgetId, binding)
    },

    /**
     * 更新数据绑定
     */
    updateDataBinding(widgetId: string): void {
      const dataSourceConfig = this.dataSourceConfigs.get(widgetId)
      const card2Definition = resolveCard2Definition(widgetId, this.nodes, this.card2Components)

      if (!dataSourceConfig || !card2Definition) {
        this.dataBindings.delete(widgetId)
        return
      }

      const requirement = createCard2DataRequirement(card2Definition, dataSourceConfig)
      this.dataBindings.set(widgetId, {
        id: `${widgetId}_binding`,
        componentId: widgetId,
        requirement,
        isActive: true,
        lastUpdate: new Date()
      })
    },

    // ==================== 系统操作 ====================

    /**
     * 标记为脏状态
     */
    markDirty(): void {
      this.isDirty = true
    },

    /**
     * 标记为已保存
     */
    markSaved(): void {
      this.isDirty = false
      this.lastSaved = new Date()
    },

    /**
     * 设置加载状态
     */
    setLoading(loading: boolean): void {
      this.isLoading = loading
    },

    // ==================== 视图操作 ====================

    /**
     * 更新视图端口
     */
    updateViewport(viewport: { x?: number; y?: number; zoom?: number }): void {
      this.viewport = { ...this.viewport, ...viewport }
    },

    /**
     * 设置编辑器模式
     */
    setMode(mode: EditorMode): void {
      this.mode = mode
    },

    /**
     * 重置视图端口
     */
    resetViewport(): void {
      this.viewport = { x: 0, y: 0, zoom: 1 }
    },

    /**
     * 清理所有状态
     */
    clearAll(): void {
      this.nodes = []
      this.selectedIds = []
      this.viewport = { x: 0, y: 0, zoom: 1 }
      this.mode = 'design'
      this.widgets.clear()
      this.baseConfigs.clear()
      this.componentConfigs.clear()
      this.dataSourceConfigs.clear()
      this.interactionConfigs.clear()
      this.card2Components.clear()
      this.dataBindings.clear()
      this.runtimeData.clear()
      this.isDirty = false
      this.lastSaved = null
    }
  }
})

// ==================== 辅助函数 ====================

/**
 * 创建默认基础配置
 */
function createDefaultBaseConfig(): BaseConfiguration {
  return {
    title: '',
    opacity: 1,
    visible: true,
    locked: false,
    zIndex: 1
  }
}

/**
 * 创建默认组件配置
 */
function createDefaultComponentConfig(): ComponentConfiguration {
  return {
    properties: {},
    style: {},
    events: {}
  }
}

/**
 * 创建默认交互配置
 */
function createDefaultInteractionConfig(): InteractionConfiguration {
  return {
    click: null,
    hover: null,
    focus: null,
    custom: {}
  }
}

function resolveCard2Definition(
  widgetId: string,
  nodes: GraphData[],
  definitions: Map<string, ComponentDefinition>
): ComponentDefinition | undefined {
  const node = nodes.find(item => item.id === widgetId)
  const componentType = node?.componentType || node?.type || node?.metadata?.componentType
  const metadataDefinition = node?.metadata?.card2Definition

  return definitions.get(widgetId) || (componentType ? definitions.get(componentType) : undefined) || metadataDefinition
}

function createCard2DataRequirement(
  definition: ComponentDefinition,
  dataSourceConfig: DataSourceConfiguration
): Record<string, unknown> {
  const requirement: Record<string, unknown> = {}
  const bindings = dataSourceConfig.bindings || {}
  const declaredSources = Array.isArray(definition.dataSources) ? definition.dataSources : []

  declaredSources.forEach(source => {
    const key = source?.key
    if (!key || bindings[key] === undefined) return

    requirement[key] = {
      type: 'object',
      required: !!source.required,
      description: source.description || source.name || key,
      mapping: source.fieldMappings || {},
      config: bindings[key]
    }
  })

  Object.entries(bindings).forEach(([key, config]) => {
    if (requirement[key]) return

    requirement[key] = {
      type: 'object',
      required: false,
      description: key,
      mapping: {},
      config
    }
  })

  return requirement
}

/**
 * 生成配置元数据
 */
function generateConfigurationMetadata(widgetId: string, state: UnifiedEditorState): Record<string, unknown> {
  return {
    id: widgetId,
    createdAt: new Date().toISOString(),
    lastModified: new Date().toISOString(),
    version: '1.0.0',
    hasDataBinding: state.dataBindings.has(widgetId),
    hasRuntimeData: state.runtimeData.has(widgetId),
    configurationSections: {
      base: state.baseConfigs.has(widgetId),
      component: state.componentConfigs.has(widgetId),
      dataSource: state.dataSourceConfigs.has(widgetId),
      interaction: state.interactionConfigs.has(widgetId)
    }
  }
}

/**
 * 文件用途: Pinia 组件选择 store，保存可视化编辑器侧栏和画布共享的选中节点 ID。
 * 核心逻辑: 根据 editor store 中的节点列表推导 selectedNodes，并提供选择、清空和删除后同步能力。
 * 关键注意事项: selectedIds 必须随节点删除及时收敛，否则侧栏可能引用已不存在的节点。
 * 重构建议: 与 editor store 的节点生命周期统一建模，并补充多选、清空和删除节点后的选择状态测试。
 */
import { defineStore } from 'pinia'
import { useEditorStore } from './editor'

// Widget selection state shared by visual-editor surfaces.
interface WidgetState {
  selectedIds: string[]
}

export const useWidgetStore = defineStore('widget', {
  state: (): WidgetState => ({
    selectedIds: []
  }),
  getters: {
    selectedNodes: state => {
      const editorStore = useEditorStore()
      return editorStore.nodes.filter(node => state.selectedIds.includes(node.id))
    }
  },
  actions: {
    // 选择操作
    selectNodes(ids: string[]) {
      this.selectedIds = [...ids]
    },
    clearSelection() {
      this.selectedIds = []
    },
    // 当节点被删除时，也需要更新选中状态
    removeNodeFromSelection(id: string) {
      this.selectedIds = this.selectedIds.filter(selectedId => selectedId !== id)
    },
    reset() {
      this.selectedIds = []
    }
  }
})

/**
 * 文件用途：提供前端 Vitest 测试环境的基础配置和 mock。
 * 核心逻辑：初始化 Vue Test Utils、国际化、全局组件桩和常用浏览器/Naive UI mock。
 * 关键注意事项：全局 mock 会影响全部单测，新增默认行为前需要确认不会隐藏真实问题。
 * 重构建议：可把全局 mock、业务 fixture 和测试工具分层，减少不同测试之间的隐式耦合。
 */
import { vi } from 'vitest';

export const messageMock = {
  success: vi.fn(),
  error: vi.fn(),
  warning: vi.fn(),
  info: vi.fn(),
  loading: vi.fn()
};

export const dialogMock = {
  success: vi.fn(),
  error: vi.fn(),
  warning: vi.fn(),
  info: vi.fn(),
  create: vi.fn()
};

export function resetHoistedMocks() {
  Object.values(messageMock).forEach(fn => fn.mockClear());
  Object.values(dialogMock).forEach(fn => fn.mockClear());
}

/**
 * 文件用途：提供前端 Vitest 测试环境的基础配置和 mock。
 * 核心逻辑：初始化 Vue Test Utils、国际化、全局组件桩和常用浏览器/Naive UI mock。
 * 关键注意事项：全局 mock 会影响全部单测，新增默认行为前需要确认不会隐藏真实问题。
 * 重构建议：可把全局 mock、业务 fixture 和测试工具分层，减少不同测试之间的隐式耦合。
 */
export function createTestI18n() {
  return {
    global: {
      t: (key: string) => key,
      locale: { value: 'en-US' }
    },
    install(app: { config?: { globalProperties?: Record<string, unknown> } }) {
      if (!app.config) return;
      if (!app.config.globalProperties) app.config.globalProperties = {};
      app.config.globalProperties.$t = (key: string) => key;
    }
  };
}

export const testI18n = createTestI18n();

﻿/**
 * 文件用途：提供前端 Vitest 测试环境的基础配置和 mock。
 * 核心逻辑：初始化 Vue Test Utils、国际化、全局组件桩和常用浏览器/Naive UI mock。
 * 关键注意事项：全局 mock 会影响全部单测，新增默认行为前需要确认不会隐藏真实问题。
 * 重构建议：可把全局 mock、业务 fixture 和测试工具分层，减少不同测试之间的隐式耦合。
 */
import { config } from '@vue/test-utils';
import { afterEach, vi } from 'vitest';
import { testI18n } from './i18n';
import { dialogMock, messageMock } from './hoisted-mocks';

const mockedCurrentRoute = vi.hoisted(() => ({
  value: {
    name: 'root',
    path: '/',
    fullPath: '/',
    meta: { constant: true }
  }
}));

vi.mock('@/router/routes', () => ({
  ROOT_ROUTE: { name: 'root', path: '/', meta: { constant: true } },
  createRoutes: () => ({ constantVueRoutes: [], authRoutes: [] }),
  getAuthVueRoutes: (routes: unknown[]) => routes
}));

vi.mock('@/router', () => ({
  router: {
    currentRoute: mockedCurrentRoute,
    push: vi.fn(),
    replace: vi.fn(),
    back: vi.fn(),
    getRoutes: vi.fn(() => []),
    addRoute: vi.fn(() => () => {}),
    removeRoute: vi.fn(),
    isReady: vi.fn(() => Promise.resolve())
  },
  setupRouter: vi.fn(() => Promise.resolve())
}));

// Mock virtual:svg-icons-register (Vite plugin virtual module)
vi.mock('virtual:svg-icons-register', () => ({}));

// Mock SvgIcon component to avoid virtual:svg-icons-register import issues
vi.mock('@/components/custom/svg-icon.vue', () => ({
  default: { template: '<svg><slot /></svg>' }
}));

// 全局 mock i18n
config.global.mocks = {
  $t: (key: string) => key
};

config.global.plugins = [testI18n];

config.global.renderStubDefaultSlot = true;

// 全局 stub 常用组件
config.global.stubs = {
  'router-link': true
};

// Mock window.$message (Naive UI discrete API)
(globalThis as any).$message = {
  success: messageMock.success,
  error: messageMock.error,
  warning: messageMock.warning,
  info: messageMock.info,
  loading: messageMock.loading
};

(globalThis as any).$dialog = dialogMock;

// Mock localStorage
const localStorageMock = (() => {
  let store: Record<string, string> = {};
  return {
    getItem: (key: string) => store[key] || null,
    setItem: (key: string, value: string) => {
      store[key] = value;
    },
    removeItem: (key: string) => {
      delete store[key];
    },
    clear: () => {
      store = {};
    }
  };
})();

Object.defineProperty(globalThis, 'localStorage', { value: localStorageMock, writable: true, configurable: true });

class ResizeObserverMock {
  observe = vi.fn();
  unobserve = vi.fn();
  disconnect = vi.fn();
}

Object.defineProperty(globalThis, 'ResizeObserver', { value: ResizeObserverMock, writable: true, configurable: true });

Object.defineProperty(window, 'matchMedia', {
  writable: true,
  configurable: true,
  value: vi.fn().mockImplementation((query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: vi.fn(),
    removeListener: vi.fn(),
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn()
  }))
});

// Components under test may start a lazy import while Vue is flushing an
// update. Wait for that import chain before Vitest tears down the file's
// environment; otherwise Vitest reports an unhandled EnvironmentTeardownError
// even when every assertion in the file passed.
afterEach(async () => {
  await vi.dynamicImportSettled()
})

/**
 * 文件用途：维护前端主题设置、变量和默认外观配置。
 * 核心逻辑：定义主题色、暗色模式、布局偏好或 CSS 变量入口，供主题 store 和样式层使用。
 * 关键注意事项：主题默认值会影响首屏和本地存储恢复，修改时需要确认兼容旧配置。
 * 重构建议：可将静态配置、运行时推导和 CSS 变量写入拆分成更易测试的模块。
 */
/** Create color palette vars */
function createColorPaletteVars() {
  const colors: App.Theme.ThemeColorKey[] = ['primary', 'info', 'success', 'warning', 'error']
  const colorPaletteNumbers: App.Theme.ColorPaletteNumber[] = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950]

  const colorPaletteVar = {} as App.Theme.ThemePaletteColor

  colors.forEach(color => {
    colorPaletteVar[color] = `rgb(var(--${color}-color))`
    colorPaletteNumbers.forEach(number => {
      colorPaletteVar[`${color}-${number}`] = `rgb(var(--${color}-${number}-color))`
    })
  })

  return colorPaletteVar
}

const colorPaletteVars = createColorPaletteVars()

/** Theme vars */
export const themeVars: App.Theme.ThemeToken = {
  colors: {
    ...colorPaletteVars,
    nprogress: 'rgb(var(--nprogress-color))',
    container: 'rgb(var(--container-bg-color))',
    layout: 'rgb(var(--layout-bg-color))',
    inverted: 'rgb(var(--inverted-bg-color))',
    base_text: 'rgb(var(--base-text-color))'
  },
  boxShadow: {
    header: 'var(--header-box-shadow)',
    sider: 'var(--sider-box-shadow)',
    tab: 'var(--tab-box-shadow)'
  }
}

/**
 * 文件用途：声明 api 相关的前端类型边界。
 * 核心逻辑：通过 namespace、interface 或模块声明约束跨文件调用形态。
 * 关键注意事项：声明文件可能影响全局类型推断或生成类型边界，修改需检查全量 TS 引用。
 * 重构建议：可逐步把宽泛全局声明收敛为模块化导出，并标注生成来源。
 */
/**
 * Namespace Api
 *
 * All backend api type
 */
declare namespace Api {
  namespace BaseApi {
    /** 后端返回的路由数据类型 */
    interface Data {
      name: string
      code: number
      message: string
    }
  }
  namespace Common {
    /** common params of paginating */
    interface PaginatingCommonParams {
      /** current page number */
      current: number
      /** page size */
      size: number
      /** total count */
      total: number
    }

    /** common params of paginating query list data */
    interface PaginatingQueryRecord<T extends NonNullable<unknown>> extends PaginatingCommonParams {
      records: T[]
    }

    /**
     * enable status
     *
     * - "1": enabled
     * - "2": disabled
     */
    type EnableStatus = '1' | '2'

    /** common record */
    type CommonRecord<T extends NonNullable<unknown>> = {
      /** record id */
      id: number
      /** record creator */
      createBy: string
      /** record create time */
      createTime: string
      /** record updater */
      updateBy: string
      /** record update time */
