/*
 * 文件用途：提供循环调用保护管理器，防止组件方法高频递归或互相触发形成死循环。
 * 核心逻辑：跟踪活跃调用、调用历史、递归深度和黑名单，并包装同步/异步方法进行清理。
 * 关键注意事项：误判会阻断合法交互，漏判会导致页面卡死，阈值配置需要谨慎。
 * 重构建议：可继续拆分检测策略和包装执行器，提升可测试性。
 */
/**
 * 🔥 全局循环检测和防护管理器
 *
 * 解决200+组件场景下的循环触发问题：
 * 1. 检测配置变更的循环依赖
 * 2. 防止数据源的递归执行
 * 3. 监控属性绑定的循环更新
 * 4. 提供性能统计和调试信息
 */

export interface LoopDetectionConfig {
  maxDepth: number // 最大递归深度
  timeWindow: number // 时间窗口 (ms)
  maxCallsInWindow: number // 时间窗口内最大调用次数
  enableDebug: boolean // 是否启用调试输出
}

export interface CallRecord {
  timestamp: number
  depth: number
  source: string
  componentId?: string
  action?: string
}

class LoopProtectionManager {
  private static instance: LoopProtectionManager | null = null

  // 配置
  private config: LoopDetectionConfig = {
    maxDepth: 10,
    timeWindow: 5000, // 5秒
    maxCallsInWindow: 50, // 5秒内最多50次调用
    enableDebug: process.env.NODE_ENV === 'development'
  }

  // 调用栈跟踪
  private callStacks = new Map<string, CallRecord[]>() // key: functionName
  private activeCallCounts = new Map<string, number>() // 当前活跃调用计数

  // 时间窗口内的调用统计
  private callHistory = new Map<string, CallRecord[]>() // key: functionName

  // 黑名单：被检测到循环的函数暂时禁用
  private blacklistedFunctions = new Set<string>()
  private blacklistTimeouts = new Map<string, NodeJS.Timeout>()

  // 性能统计
  private performanceStats = {
    totalCallsBlocked: 0,
    totalLoopsDetected: 0,
    averageCallsPerSecond: 0,
    lastResetTime: Date.now()
  }

  private constructor() {
    this.setupGlobalErrorHandling()
    this.startPerformanceMonitoring()
  }

  public static getInstance(): LoopProtectionManager {
    if (!LoopProtectionManager.instance) {
      LoopProtectionManager.instance = new LoopProtectionManager()
    }
    return LoopProtectionManager.instance
  }

  /**
   * 🔥 核心方法：检查函数调用是否应该被允许
   */
  public shouldAllowCall(functionName: string, componentId?: string, action?: string, source = 'unknown'): boolean {
    const callKey = componentId ? `${functionName}:${componentId}` : functionName

    // 1. 检查黑名单
    if (this.blacklistedFunctions.has(callKey)) {
      this.performanceStats.totalCallsBlocked++
      if (this.config.enableDebug) {
        console.warn(`🚫 [LoopProtection] 阻止黑名单函数调用: ${callKey}`)
      }
      return false
    }

    // 2. 检查递归深度
    const currentDepth = this.getCurrentDepth(callKey)
    if (currentDepth >= this.config.maxDepth) {
      this.addToBlacklist(callKey, `递归深度超过${this.config.maxDepth}`)
      return false
    }

    // 3. 检查时间窗口内的调用频率
    if (this.isCallFrequencyTooHigh(callKey)) {
      this.addToBlacklist(callKey, `调用频率过高`)
      return false
    }

    // 4. 记录这次调用
    this.recordCall(callKey, source, componentId, action)

    return true
  }

  /**
   * 🔥 标记函数调用开始
   */
  public markCallStart(functionName: string, componentId?: string, source = 'unknown'): string {
    const callKey = componentId ? `${functionName}:${componentId}` : functionName
    const callId = `${callKey}:${Date.now()}:${Math.random().toString(36).slice(2, 7)}`

    if (!this.shouldAllowCall(functionName, componentId, 'start', source)) {
      return '' // 空字符串表示调用被阻止
    }

    // 增加活跃调用计数
    const currentCount = this.activeCallCounts.get(callKey) || 0
    this.activeCallCounts.set(callKey, currentCount + 1)

    if (this.config.enableDebug && currentCount > 3) {
      console.warn(`⚠️ [LoopProtection] 高并发调用检测: ${callKey} (${currentCount + 1} 个并发)`)
    }

    return callId
  }

  /**
   * 🔥 标记函数调用结束
   */
  public markCallEnd(callId: string, functionName: string, componentId?: string): void {
    if (!callId) return // 调用被阻止的情况

    const callKey = componentId ? `${functionName}:${componentId}` : functionName

    // 减少活跃调用计数
    const currentCount = this.activeCallCounts.get(callKey) || 0
    if (currentCount > 0) {
      this.activeCallCounts.set(callKey, currentCount - 1)
    }

    // 清理调用栈
    this.cleanupCallStack(callKey)
  }

  /**
   * 🔥 获取当前递归深度
   */
  private getCurrentDepth(callKey: string): number {
    const stack = this.callStacks.get(callKey) || []
    return stack.length
  }

  /**
   * 🔥 检查调用频率是否过高
   */
  private isCallFrequencyTooHigh(callKey: string): boolean {
    const now = Date.now()
    const history = this.callHistory.get(callKey) || []

    // 清理过期的历史记录
    const validHistory = history.filter(record => now - record.timestamp <= this.config.timeWindow)
    this.callHistory.set(callKey, validHistory)

    return validHistory.length >= this.config.maxCallsInWindow
  }

  /**
   * 🔥 记录函数调用
   */
  private recordCall(callKey: string, source: string, componentId?: string, action?: string): void {
    const now = Date.now()
    const record: CallRecord = {
      timestamp: now,
      depth: this.getCurrentDepth(callKey),
      source,
      componentId,
      action
    }

    // 更新调用栈
    const stack = this.callStacks.get(callKey) || []
    stack.push(record)
    this.callStacks.set(callKey, stack)

    // 更新历史记录
    const history = this.callHistory.get(callKey) || []
    history.push(record)
    this.callHistory.set(callKey, history)
  }

  /**
   * 🔥 添加到黑名单
   */
  private addToBlacklist(callKey: string, reason: string): void {
    this.blacklistedFunctions.add(callKey)
    this.performanceStats.totalLoopsDetected++

    if (this.config.enableDebug) {
      console.error(`🚫 [LoopProtection] 检测到循环，已加入黑名单: ${callKey}`, {
        reason,
        callHistory: this.callHistory.get(callKey)?.slice(-5), // 最后5次调用
        currentDepth: this.getCurrentDepth(callKey)
      })
    }

    // 设置自动解除黑名单的定时器
    const existingTimeout = this.blacklistTimeouts.get(callKey)
    if (existingTimeout) {
      clearTimeout(existingTimeout)
    }

    const timeout = setTimeout(() => {
      this.removeFromBlacklist(callKey)
    }, 10000) // 10秒后自动解除黑名单

    this.blacklistTimeouts.set(callKey, timeout)
  }

  /**
   * 🔥 从黑名单移除
   */
  private removeFromBlacklist(callKey: string): void {
    this.blacklistedFunctions.delete(callKey)
    this.blacklistTimeouts.delete(callKey)

    // 清理相关的调用历史
    this.callStacks.delete(callKey)
    this.callHistory.delete(callKey)
    this.activeCallCounts.delete(callKey)

    if (this.config.enableDebug) {
      console.info(`✅ [LoopProtection] 已从黑名单移除: ${callKey}`)
    }
  }

  /**
   * 🔥 清理调用栈
   */
  private cleanupCallStack(callKey: string): void {
    const stack = this.callStacks.get(callKey) || []
    if (stack.length > 0) {
      stack.pop() // 移除最后一个调用记录
      this.callStacks.set(callKey, stack)
    }
  }

  /**
   * 🔥 设置全局错误处理
   */
  private setupGlobalErrorHandling(): void {
    // 监听未捕获的异常，可能是循环调用导致的栈溢出
    if (typeof window !== 'undefined') {
      window.addEventListener('error', event => {
        if (event.error && event.error.message.includes('Maximum call stack size exceeded')) {
          console.error('🚫 [LoopProtection] 检测到栈溢出，可能存在无限递归')
          this.performanceStats.totalLoopsDetected++

          // 清空所有活跃调用，防止系统崩溃
          this.activeCallCounts.clear()
          this.callStacks.clear()
        }
      })
    }
  }

  /**
   * 🔥 启动性能监控
   */
  private startPerformanceMonitoring(): void {
    setInterval(() => {
      const now = Date.now()
      const timeDiff = now - this.performanceStats.lastResetTime
      const totalCalls = Array.from(this.callHistory.values()).reduce((sum, history) => sum + history.length, 0)

      this.performanceStats.averageCallsPerSecond = totalCalls / (timeDiff / 1000)
      this.performanceStats.lastResetTime = now

      if (this.config.enableDebug && totalCalls > 0) {
        /* intentionally empty */
      }

      // 清理过期的历史记录
      this.cleanupExpiredHistory()
    }, 30000) // 每30秒统计一次
  }

  /**
   * 🔥 清理过期的历史记录
   */
  private cleanupExpiredHistory(): void {
    const now = Date.now()
    for (const [callKey, history] of this.callHistory.entries()) {
      const validHistory = history.filter(
        record => now - record.timestamp <= this.config.timeWindow * 2 // 保留2倍时间窗口的历史
      )
      if (validHistory.length !== history.length) {
        this.callHistory.set(callKey, validHistory)
      }
    }
  }

  /**
   * 🔥 获取性能统计信息
   */
  public getPerformanceStats() {
    return {
      ...this.performanceStats,
      blacklistedFunctionsCount: this.blacklistedFunctions.size,
      activeCallsCount: Array.from(this.activeCallCounts.values()).reduce((a, b) => a + b, 0),
      totalTrackedFunctions: this.callHistory.size
    }
  }

  /**
   * 🔥 获取当前黑名单
   */
  public getBlacklistedFunctions(): string[] {
    return Array.from(this.blacklistedFunctions)
  }

  /**
   * 🔥 手动清理（用于测试或重置）
   */
  public reset(): void {
    this.callStacks.clear()
    this.callHistory.clear()
    this.activeCallCounts.clear()
    this.blacklistedFunctions.clear()

    // 清理所有定时器
    for (const timeout of this.blacklistTimeouts.values()) {
      clearTimeout(timeout)
    }
    this.blacklistTimeouts.clear()

    this.performanceStats = {
      totalCallsBlocked: 0,
      totalLoopsDetected: 0,
      averageCallsPerSecond: 0,
      lastResetTime: Date.now()
    }
  }

  /**
   * 🔥 更新配置
   */
  public updateConfig(newConfig: Partial<LoopDetectionConfig>): void {
    this.config = { ...this.config, ...newConfig }
  }
}

// 导出单例实例
export const loopProtectionManager = LoopProtectionManager.getInstance()

/**
 * 🔥 装饰器：自动添加循环保护
 */
export function loopProtection(functionName?: string) {
  return function (target: any, propertyKey: string, descriptor: PropertyDescriptor) {
    const originalMethod = descriptor.value
    const fnName = functionName || `${target.constructor.name}.${propertyKey}`

    descriptor.value = function (...args: any[]) {
      const componentId = (this as any).componentId || (this as any).nodeId || 'unknown'
      const callId = loopProtectionManager.markCallStart(fnName, componentId, 'decorator')

      if (!callId) {
        // 调用被阻止
        return Promise.resolve()
      }

      try {
        const result = originalMethod.apply(this, args)

        if (result instanceof Promise) {
          return result.finally(() => {
            loopProtectionManager.markCallEnd(callId, fnName, componentId)
          })
        } else {
          loopProtectionManager.markCallEnd(callId, fnName, componentId)
          return result
        }
      } catch (error) {
        loopProtectionManager.markCallEnd(callId, fnName, componentId)
        throw error
      }
    }

    return descriptor
  }
}

import { $t } from '@/locales'

/**
 * Convert a string record into value/label options for select-like controls.
 */
export function transformRecordToOption<T extends Record<string, string>>(record: T) {
  return Object.entries(record).map(([value, label]) => ({
    value,
    label
  })) as CommonType.Option<keyof T>[]
}

/**
 * Translate option labels that are stored as i18n keys.
 */
export function translateOptions(options: CommonType.Option<string>[]) {
  return options.map(option => ({
    ...option,
    label: $t(option.label as App.I18n.I18nKey)
  }))
}

export function transformObjectToOption<T extends object>(obj: T) {
  return Object.entries(obj).map(([value, label]) => ({
    value,
    label
  })) as Common2.OptionWithKey<keyof T>[]
}

/*
 * 文件用途：提供静态资源、服务地址、深拷贝、JSON、密码校验和随机字符串等通用工具。
 * 核心逻辑：读取运行时环境和浏览器能力，组合 URL、校验字符串并生成随机十六进制内容。
 * 关键注意事项：该文件职责较宽，既有纯函数也有环境依赖函数，改动需谨慎评估调用方。
 * 重构建议：建议按 URL、校验、随机数和对象处理拆分模块。
 */
import { REG_PWD } from '@/constants/reg'
import { createServiceConfig } from '~/env.config'
import { smartDeepClone } from '@/utils/deep-clone'

/** Resolve the primary API base URL from Vite env, falling back to the same-origin preview proxy. */
export const getBaseServerUrl = (): string => {
  const { baseURL } = createServiceConfig(import.meta.env)
  return baseURL || `${window.location.origin}/api/v1`
}

/** Resolve the default platform API base URL used by assets and websocket helpers. */
export const getPlatformApiBaseUrl = (): string => {
  const { otherBaseURL } = createServiceConfig(import.meta.env)
  return otherBaseURL.platform ? otherBaseURL.platform : `${window.location.origin}/api/v1`
}

/**
 * get web socket server url
 *
 * @returns web socket server url
 */
export const getWebsocketServerUrl = (): string => {
  const platformApiBaseUrl = getPlatformApiBaseUrl()
  if (window.location.protocol === 'https:') {
    return platformApiBaseUrl.replace(window.location.protocol, 'wss:')
  }
  return platformApiBaseUrl.replace(window.location.protocol, 'ws:')
}

/** Compatibility wrapper around the shared clone helper used by existing imports. */
export function deepClone(data: any): any {
  return smartDeepClone(data)
}

/** Return true only for JSON strings whose parsed value is an object or array. */
export function isJSON(str: string): boolean {
  if (typeof str === 'string') {
    try {
      const obj = JSON.parse(str)
      if (typeof obj === 'object' && obj) {
        return true
      }
      return false
    } catch (error) {
      return false
    }
  }
  return false
}

/** 登录后弱密码提示用：仅要求非空（与登录表单一致，不做复杂度校验） */
export function validPassword(str: string): boolean {
  return typeof str === 'string' && str.length > 0
}

function getRandomBytes(length: number) {
  return window.crypto.getRandomValues(new Uint8Array(length))
}

function randomBytesToHex(bytes: Uint8Array) {
  return Array.from(bytes)
    .map((b: number) => b.toString(16).padStart(2, '0'))
    .join('')
}

/** Generate cryptographic random bytes and encode them as hex; length is a byte count, so output is length * 2 chars. */
export function generateRandomHexString(length: number) {
  const bytes = getRandomBytes(length)
  const hexString = randomBytesToHex(bytes)
  return hexString
}

export function validName(str: string) {
  if (!str || str?.length > 50) {
    return false
  }
  return true
}

/** 注册/改密等表单：8-20 位，必须包含大小写字母、数字和特殊字符。 */
export function validPasswordByExp(str: string) {
  return typeof str === 'string' && REG_PWD.test(str)
}

/*
 * 文件用途：提供智能深拷贝工具，兼容 Vue 响应式对象与普通对象。
 * 核心逻辑：先解包 unref/toRaw，再按对象类型执行深层克隆。
 * 关键注意事项：需要避免把响应式代理或不可克隆对象错误写入持久状态。
 * 重构建议：建议补充 Map、Date、数组和响应式输入的覆盖测试。
 */
/**
 * 智能深拷贝工具
 * 专门处理Vue 3响应式对象与structuredClone的兼容性问题
 */

import { toRaw, isRef, unref, isReactive, isReadonly } from 'vue'

/**
 * 检查对象是否为Vue响应式对象
 */
const isVueReactiveObject = (obj: any): boolean => {
  return (
    isReactive(obj) ||
    isReadonly(obj) ||
    isRef(obj) ||
    (obj && typeof obj === 'object' && (obj.__v_isReactive || obj.__v_isReadonly || obj.__v_isRef))
  )
}

/**
 * 智能深度toRaw转换
 * 只对Vue响应式对象使用toRaw，避免不必要的处理
 */
const smartDeepToRaw = <T>(obj: T): T => {
  if (obj === null || obj === undefined) return obj

  // 处理基本类型
  if (typeof obj !== 'object') return obj

  // 处理ref对象
  if (isRef(obj)) {
    return smartDeepToRaw(unref(obj)) as T
  }

  // 处理响应式对象
  let raw = obj
  if (isVueReactiveObject(obj)) {
    raw = toRaw(obj)
  }

  // 处理数组
  if (Array.isArray(raw)) {
    return raw.map(smartDeepToRaw) as T
  }

  // 处理Date、RegExp等内置对象
  if (raw instanceof Date || raw instanceof RegExp || raw instanceof Error) {
    return raw
  }

  // 处理Set
  if (raw instanceof Set) {
    const newSet = new Set()
    raw.forEach((value) => {
      newSet.add(smartDeepToRaw(value))
    })
    return newSet as T
  }

  // 处理Map
  if (raw instanceof Map) {
    const newMap = new Map()
    raw.forEach((value, key) => {
      newMap.set(smartDeepToRaw(key), smartDeepToRaw(value))
    })
    return newMap as T
  }

  // 处理普通对象
  if (raw.constructor === Object || raw.constructor === undefined) {
    const result: any = {}
    for (const [key, value] of Object.entries(raw)) {
      result[key] = smartDeepToRaw(value)
    }
    return result
  }

  // 其他类型保持原样
  return raw
}

/**
 * 性能优化的深拷贝函数
 *
 * 策略：
 * 1. 优先使用高性能的 structuredClone()
 * 2. 对Vue响应式对象智能预处理
 * 3. 失败时降级到JSON方法
 * 4. 支持复杂对象类型(Set, Map等)
 */
export const smartDeepClone = <T>(
  obj: T,
  options?: {
    /** 是否启用详细日志 */
    debug?: boolean
    /** 强制使用JSON方法（用于测试） */
    forceJSON?: boolean
  }
): T => {
  const { debug = false, forceJSON = false } = options || {}

  if (obj === null || obj === undefined) return obj

  try {
    // 第一步：智能预处理Vue响应式对象
    const rawObj = smartDeepToRaw(obj)

    if (debug) {
      if (process.env.NODE_ENV === 'development') {
        /* intentionally empty */
      }
    }

    // 第二步：尝试高性能的structuredClone
    if (!forceJSON && typeof structuredClone !== 'undefined') {
      try {
        const cloned = structuredClone(rawObj)
        if (debug) {
          if (process.env.NODE_ENV === 'development') {
            /* intentionally empty */
          }
        }
        return cloned
      } catch (structuredCloneError) {
        if (debug) {
          console.error('⚠️ [smartDeepClone] structuredClone失败，降级到JSON:', structuredCloneError)
        }
        // 继续到JSON方法
      }
    }

    // 第三步：降级到JSON方法
    const jsonCloned = JSON.parse(JSON.stringify(rawObj))
    if (debug) {
      if (process.env.NODE_ENV === 'development') {
        /* intentionally empty */
      }
    }
    return jsonCloned
  } catch (error) {
    console.error('❌ [smartDeepClone] 所有克隆方法都失败了:', error)
    // 最后的兜底：浅拷贝
    if (Array.isArray(obj)) {
      return [...obj] as T
    }
    if (obj && typeof obj === 'object') {
      return { ...obj } as T
    }
    return obj
  }
}

/**
 * 简化版深拷贝（仅用于简单对象，性能更好）
 */
export const simpleDeepClone = <T>(obj: T): T => {
  return smartDeepClone(obj)
}

/**
 * 批量深拷贝（用于数组等批量操作）
 */
export const batchDeepClone = <T>(items: T[]): T[] => {
  try {
    // 尝试批量处理
    const rawItems = items.map(smartDeepToRaw)
    return structuredClone(rawItems)
  } catch {
    // 降级到单个处理
    return items.map((item) => smartDeepClone(item))
  }
}

/**
 * 兼容性深拷贝（确保100%成功）
 */
export const safeDeepClone = <T>(obj: T): T => {
  return smartDeepClone(obj, { forceJSON: true })
}

// 默认导出
export default smartDeepClone

/*
 * 文件用途：封装设备状态 WebSocket 客户端，用于订阅设备在线状态变化。
 * 核心逻辑：管理连接、订阅参数、消息解析和响应式状态更新。
 * 关键注意事项：WebSocket 重连、取消订阅和异常消息处理会影响设备列表实时性。
 * 重构建议：可抽出协议消息解析并补充断线/重复订阅测试。
 */
import { ref, type Ref } from 'vue'
import { useWebSocket } from '@vueuse/core'
import { localStg } from '@/utils/storage'
import { getWebsocketServerUrl } from '@/utils/common/tool'

interface DeviceStatusMessage {
  device_id: string
  is_online: number // 1: 在线, 0: 离线
}

interface SubscriptionParams {
  device_ids: string[]
  token: string
}

/**
 * 设备状态 WebSocket 管理器
 * 用于订阅和接收设备在线/离线状态通知
 */
export class DeviceStatusWebSocket {
  private ws: any = null
  private wsStatus = ref<string>('CLOSED')
  private currentDeviceIds: string[] = []
  private reconnectAttempts = 0
  private readonly MAX_RECONNECT_ATTEMPTS = 5
  private wsUrl: string
  private onStatusChangeCallback?: (deviceId: string, isOnline: boolean) => void
  private isConnecting = false // 新增：标记正在连接中

  constructor() {
    // 动态获取 WebSocket 服务器地址
    this.wsUrl = `${getWebsocketServerUrl()}/device/online/status/ws/batch`
  }

  /**
   * 连接 WebSocket 并订阅设备状态
   * @param deviceIds 设备ID列表
   * @param onStatusChange 状态变化回调函数
   */
  connect(deviceIds: string[], onStatusChange?: (deviceId: string, isOnline: boolean) => void) {
    // 保存回调函数
    if (onStatusChange) {
      this.onStatusChangeCallback = onStatusChange
    }

    // 如果设备列表为空，不建立连接
    if (!deviceIds || deviceIds.length === 0) {
      this.disconnect()
      return
    }

    // 获取 token
    const token = localStg.get('token')
    if (!token) {
      return
    }

    // 如果正在连接中，不重复连接
    if (this.isConnecting) {
      this.currentDeviceIds = [...deviceIds]
      return
    }

    // 如果已连接且设备列表未变化，不需要重新连接
    if (this.ws && this.wsStatus.value === 'OPEN' && this.arraysEqual(this.currentDeviceIds, deviceIds)) {
      return
    }

    // 如果已连接但设备列表变化了（分页切换），关闭旧连接重新建立
    if (this.ws && this.wsStatus.value === 'OPEN' && !this.arraysEqual(this.currentDeviceIds, deviceIds)) {
      this.disconnect()
    }

    // 标记为连接中
    this.isConnecting = true

    // 如果还有旧连接，先断开
    if (this.ws) {
      this.disconnect()
    }

    // 保存当前设备列表
    this.currentDeviceIds = [...deviceIds]

    // 建立新连接
    const { status, data, send, close } = useWebSocket(this.wsUrl, {
      immediate: true,
      autoReconnect: {
        retries: this.MAX_RECONNECT_ATTEMPTS,
        delay: 3000
      },
      heartbeat: {
        message: 'ping',
        interval: 30000,
        pongTimeout: 10000
      },
      onConnected: (ws: WebSocket) => {
        this.reconnectAttempts = 0
        this.isConnecting = false // 连接成功，清除连接中标记

        // 发送订阅消息
        const subscriptionMessage: SubscriptionParams = {
          device_ids: this.currentDeviceIds,
          token
        }
        send(JSON.stringify(subscriptionMessage))
      },
      onMessage: (ws: WebSocket, event: MessageEvent) => {
        try {
          const data = JSON.parse(event.data)

          // 支持批量消息格式（数组）
          if (Array.isArray(data)) {
            data.forEach((item: any) => {
              if (item.device_id && typeof item.is_online === 'number') {
                if (this.onStatusChangeCallback) {
                  this.onStatusChangeCallback(item.device_id, item.is_online === 1)
                }
              }
            })
          }
          // 支持单条消息格式（对象）
          else if (data.device_id && typeof data.is_online === 'number') {
            if (this.onStatusChangeCallback) {
              this.onStatusChangeCallback(data.device_id, data.is_online === 1)
            }
          }
          // 其他格式静默忽略，不报错
        } catch (error) {
          // 解析失败静默忽略
        }
      },
      onError: (ws: WebSocket, event: Event) => {
        this.reconnectAttempts++
        this.isConnecting = false // 连接错误，清除连接中标记
      },
      onDisconnected: (ws: WebSocket, event: CloseEvent) => {
        this.isConnecting = false // 断开连接，清除连接中标记
      }
    })

    this.ws = { status, data, send, close }
    this.wsStatus = status
  }

  /**
   * 更新订阅的设备列表
   * @param deviceIds 新的设备ID列表
   */
  updateSubscription(deviceIds: string[], onStatusChange?: (deviceId: string, isOnline: boolean) => void) {
    if (onStatusChange) {
      this.onStatusChangeCallback = onStatusChange
    }

    if (!deviceIds || deviceIds.length === 0) {
      this.disconnect()
      return
    }

    const token = localStg.get('token')
    if (!token) {
      return
    }

    if (this.ws && this.wsStatus.value === 'OPEN' && this.arraysEqual(this.currentDeviceIds, deviceIds)) {
      return
    }

    if (this.isConnecting) {
      this.currentDeviceIds = [...deviceIds]
      return
    }

    // 如果 WebSocket 已连接，直接发送新的订阅消息
    if (this.ws && this.wsStatus.value === 'OPEN') {
      this.currentDeviceIds = [...deviceIds]
      const subscriptionMessage: SubscriptionParams = {
        device_ids: deviceIds,
        token
      }
      this.ws.send(JSON.stringify(subscriptionMessage))
    } else {
      // 否则重新连接
      this.connect(deviceIds, this.onStatusChangeCallback)
    }
  }

  /**
   * 断开 WebSocket 连接
   */
  disconnect() {
    this.isConnecting = false // 清除连接中标记
    if (this.ws && this.ws.close) {
      this.ws.close()
      this.ws = null
    }
    this.currentDeviceIds = []
    this.reconnectAttempts = 0
  }

  /**
   * 获取当前连接状态
   */
  getStatus(): string {
    return this.wsStatus.value
  }

  /**
   * 比较两个数组是否相等
   */
  private arraysEqual(arr1: string[], arr2: string[]): boolean {
    if (arr1.length !== arr2.length) return false
    const sorted1 = [...arr1].sort()
    const sorted2 = [...arr2].sort()
    return sorted1.every((val, index) => val === sorted2[index])
  }
}

/**
 * 创建设备状态 WebSocket 实例的组合式函数
 * @returns WebSocket 管理器实例
 */
export function useDeviceStatusWebSocket() {
  const wsManager = new DeviceStatusWebSocket()

  return {
    connect: wsManager.connect.bind(wsManager),
    updateSubscription: wsManager.updateSubscription.bind(wsManager),
    disconnect: wsManager.disconnect.bind(wsManager),
    getStatus: wsManager.getStatus.bind(wsManager)
  }
}

