}

/*
 * 文件用途：提供本地图标名称收集工具。
 * 核心逻辑：通过 Vite glob 读取本地 SVG 模块路径并转换为图标名称。
 * 关键注意事项：路径约定依赖构建工具和图标目录结构，移动资源时需要同步验证。
 * 重构建议：可把图标目录约定集中到常量中，降低路径散落风险。
 */
export function getLocalIcons() {
  const svgIcons = import.meta.glob('/src/assets/svg-icon/*.svg')

  const keys = Object.keys(svgIcons)
    .map(item => item.split('/').at(-1)?.replace('.svg', '') || '')
    .filter(Boolean)

  return keys
}

/*
 * 文件用途：统一处理前端 service 调用结果和适配器返回值。
 * 核心逻辑：根据后端响应 code、message、data 执行成功返回、错误提示和登录失效处理。
 * 关键注意事项：这里是接口错误进入 UI 的统一边界，改动会影响大量请求体验。
 * 重构建议：建议减少 `any`，并把错误码策略配置化。
 */
/** 统一失败和成功的请求结果的数据类型 */
export async function handleServiceResult<T = any>(
  error: App.Service.RequestError | null,
  data: any,
  msg: string = ''
) {
  if (error) {
    const fail: App.Service.FailedResult = {
      error,
      data: null
    }
    return fail
  }
  const success: App.Service.SuccessResult<T> = {
    error: null,
    data
  }
  return {
    ...success,
    msg
  }
}

/** 请求结果的适配器：用于接收适配器函数和请求结果 */
export function adapter<T extends App.Service.ServiceAdapter>(
  adapterFun: T,
  ...args: App.Service.MultiRequestResult<Parameters<T>>
): App.Service.RequestResult<ReturnType<T>> {
  let result: App.Service.RequestResult | undefined

  const hasError = args.some(item => {
    const flag = Boolean(item.error)
    if (flag) {
      result = {
        error: item.error,
        data: null
      }
    }
    return flag
  })

  if (!hasError) {
    const adapterFunArgs = args.map(item => item.data)
    result = {
      error: null,
      data: adapterFun(...adapterFunArgs)
    }
  }

  return result!
}

/*
 * 文件用途：集中处理测试环境下未 mock console 的噪声抑制判断。
 * 核心逻辑：Vitest 环境里只有被 mock 的 console 方法才允许继续输出。
 * 关键注意事项：这是测试噪声边界工具，业务代码不要在这里加入运行时日志策略。
 */

export function shouldSuppressUnmockedTestConsole(method: (...args: any[]) => void): boolean {
  return (globalThis as any).process?.env?.VITEST === 'true' && !(method as any).mock
}

/*
 * 文件用途：从 ThingsVis 物模型中提取平台字段定义。
 * 核心逻辑：遍历 telemetry、attributes、commands、events 字段段落，并归一化字段类型为 number/string/boolean/json。
 * 关键注意事项：字段类型映射会影响看板绑定、实时数据展示和后续平台字段请求。
 * 重构建议：建议补充未知类型、空物模型、字符串 JSON 和嵌套字段的单元测试。
 */

import type { PlatformField } from './types'

/**
 * 从物模型中提取平台字段。
 * @param template 物模型数据。
 * @returns 平台字段数组。
 */
export function extractPlatformFields(template: any): PlatformField[] {
  if (!template) return []

  try {
    return platformFieldSections().flatMap(({ key, dataType }) => extractFieldSection(template[key], dataType))
  } catch (error) {
    console.error('Failed to extract platform fields:', error)
    return []
  }
}

export function mergePlatformFieldsById(primary: PlatformField[], fallback: PlatformField[]): PlatformField[] {
  const seen = new Set<string>()
  const merged: PlatformField[] = []

  for (const field of [...primary, ...fallback]) {
    if (!field?.id || seen.has(field.id)) continue
    seen.add(field.id)
    merged.push(field)
  }

  return merged
}

function platformFieldSections(): Array<{ key: string; dataType: PlatformField['dataType'] }> {
  return [
    { key: 'telemetry', dataType: 'telemetry' },
    { key: 'attributes', dataType: 'attribute' },
    { key: 'commands', dataType: 'command' },
    { key: 'events', dataType: 'event' }
  ]
}

function extractFieldSection(section: unknown, dataType: PlatformField['dataType']): PlatformField[] {
  const items = parseFieldSection(section)
  if (!Array.isArray(items)) {
    return []
  }

  return items
    .map((item) => normalizePlatformField(item, dataType))
    .filter((field): field is PlatformField => field !== null)
}

function parseFieldSection(section: unknown): unknown {
  if (typeof section === 'string') {
    return JSON.parse(section)
  }
  return section
}

function normalizePlatformField(item: any, dataType: PlatformField['dataType']): PlatformField | null {
  const id = item?.key || item?.data_identifier || item?.identifier || item?.id
  const name = item?.name || item?.data_name || item?.label || id
  if (!id) return null

  return {
    id,
    name: name || id,
    type: mapDataType(item?.data_type || item?.type),
    dataType,
    unit: item?.unit,
    description: item?.description || item?.define
  }
}

/**
 * 将物模型数据类型映射为 ThingsVis 支持的字段类型。
 */
function mapDataType(type: string): 'number' | 'string' | 'boolean' | 'json' {
  if (!type) return 'string'

  const lowerType = type.toLowerCase()

  if (
    lowerType.includes('int') ||
    lowerType.includes('float') ||
    lowerType.includes('double') ||
    lowerType === 'number'
  ) {
    return 'number'
  }

  if (lowerType.includes('bool')) {
    return 'boolean'
  }

  if (lowerType.includes('json') || lowerType.includes('object') || lowerType.includes('array')) {
    return 'json'
  }

  return 'string'
}

/*
 * 文件用途：ThingsVis 嵌入式 iframe SDK 客户端，负责宿主页与 Guest 页之间的 PostMessage 协议收发。
 * 核心职责：管理 iframe 生命周期、拼装嵌入参数、维护 ready/loaded 阶段队列，并兼容 Widget/App 两种接入模式。
 * 协议边界：`targetOrigin`、`contentWindow`、`event.source` 与 `event.origin` 校验属于安全边界，不能为兼容旧消息而放宽。
 * 维护约束：消息类型常量和 Host/Guest 收发方向需要与 Guest 端 embed 协议保持一致，修改前必须同步核对两端实现。
 */

import { getPlatformApiBase } from '@/utils/thingsvis/constants'
import { createLogger } from '@/utils/logger'

const sdkLogger = createLogger('ThingsVisSDK')

// 与 ThingsVis Guest 端协议保持一致的消息类型常量。
// 这些值一旦改名，Guest 端 MSG_TYPES、嵌入协议适配层和 Host 保存事件别名都要同步更新。
const TV_MSG = {
  // 宿主 -> Guest
  INIT: 'tv:init',
  TRIGGER_SAVE: 'tv:trigger-save',
  REQUEST_SAVE: 'tv:request-save',
  EVENT: 'tv:event',
  // Guest -> 宿主
  SAVE: 'tv:save',
  READY: 'tv:ready',
  REQUEST_INIT: 'tv:request-init',
  // SDK 内部事件名（仅 Host 内部使用）
  SAVE_CONFIG: 'tv:save-config'
} as const

export interface ThingsVisOptions {
  /** iframe 挂载容器。 */
  container: HTMLElement
  /**
   * 接入模式。
   * - widget: 产品模型挂件模式，由宿主提供数据，`saveTarget='host'`
   * - app: 完整编辑器模式，由 Guest 自管数据，`saveTarget='self'`
   */
  mode: 'widget' | 'app'
  /** iframe 地址，例如 `http://localhost:3000/#/embed` 或 `#/editor`。 */
  url: string
  /** 可选的 iframe 样式覆盖。 */
  style?: Partial<CSSStyleDeclaration>
}

export interface WidgetLoadOptions {
  platformBufferSize?: number
  platformDevices?: any[]
  deviceId?: string
  thingsvisApiBaseUrl?: string
  platformApiBaseUrl?: string
  platformToken?: string
  runtimeCapabilities?: any
}

export type MessageHandler = (payload: any) => void

export class ThingsVisClient {
  private iframe: HTMLIFrameElement
  private container: HTMLElement
  private options: ThingsVisOptions
  private targetOrigin: string
  public ready: boolean = false
  /**
   * Guest 完成 `registerAndLoad` 并发出 `LOADED` 后置为 true。
   * `tv:platform-data` / `tv:platform-history` 必须等到这一阶段再发送，
   * 否则消息会早于 PlatformFieldAdapter 挂载而被直接丢弃。
   */
  private loaded: boolean = false
  private messageHandlers: Map<string, MessageHandler[]> = new Map()
  private pendingQueue: Array<() => void> = []
  /** 需要等到 `LOADED` 之后再发送的消息队列。 */
  private postLoadQueue: Array<() => void> = []
  /** 按作用域缓存最近一次实时值，便于 Guest 重新 init 后回放。 */
  private latestPlatformDataByScope: Map<string, { fields: Record<string, unknown>; deviceId?: string }> = new Map()
  /** 按作用域和字段缓存最近一次历史值，便于 Guest 重新 init 后回放。 */
  private latestPlatformHistoryByScope: Map<
    string,
    { fieldId: string; history: Array<{ value: unknown; ts: number }>; deviceId?: string }
  > = new Map()
  private lastInitPayload: any = null
  private platformPushCount = 0

  constructor(options: ThingsVisOptions) {
    this.options = options
    this.container = options.container
    this.targetOrigin = this.resolveTargetOrigin(options.url)
    this.iframe = document.createElement('iframe')
    this.initIframe()
    this.setupMessageListener()
  }

  private resolveTargetOrigin(url: string): string {
    try {
      return new URL(url, window.location.href).origin
    } catch (error) {
      sdkLogger.warn('Failed to resolve ThingsVis iframe target origin:', error)
      return window.location.origin
    }
  }

  private initIframe() {
    // 追加嵌入参数，确保 Guest 页进入 embed 模式并隐藏默认角标按钮。
    const separator = this.resolveEmbedParamSeparator(this.options.url)
    const modeParam = 'mode=embedded&showTopLeft=0&showTopRight=0'
    const finalUrl = `${this.options.url}${separator}${modeParam}`

    this.targetOrigin = this.resolveTargetOrigin(finalUrl)
    this.iframe.src = finalUrl
    this.iframe.allowFullscreen = true
    this.iframe.allow = 'fullscreen; autoplay; clipboard-write; camera; microphone; encrypted-media; picture-in-picture'
    // 默认 iframe 样式。
    this.iframe.style.width = '100%'
    this.iframe.style.height = '100%'
    this.iframe.style.border = 'none'
    this.iframe.style.display = 'block'

    // 合并宿主传入的样式覆盖。
    if (this.options.style) {
      Object.assign(this.iframe.style, this.options.style)
    }

    this.container.appendChild(this.iframe)

    // 保留 onload 钩子，真实可通信时机仍以 Guest 主动发 READY 为准。
    this.iframe.onload = () => {
      // iframe onload 不代表内部 React 已经 hydrate 完成。
      // 当前协议仍以 Guest 发回 READY 作为可发送初始化消息的标志。
    }
  }

  private resolveEmbedParamSeparator(url: string): '?' | '&' {
    const hashIndex = url.indexOf('#')
    const routePart = hashIndex === -1 ? url : url.slice(hashIndex)
    return routePart.includes('?') ? '&' : '?'
  }

  private setupMessageListener() {
    window.addEventListener('message', this.handleMessage)
  }

  private handleMessage = (event: MessageEvent) => {
    if (!this.isTrustedMessageEvent(event)) return

    const { type, payload } = event.data || {}
    if (!type) return

    // 协议适配层：只处理 SDK 关心的消息，其余仍向外透传。

    // 1. 保存回调（Guest -> Host）
    if (type === TV_MSG.SAVE) {
      this.emit(TV_MSG.SAVE_CONFIG, payload) // 转成统一 SDK 内部事件，方便宿主订阅。
    }

    // 2. READY（Guest -> Host）：Guest 已可接收基础协议消息。
    if (type === 'READY' || type === TV_MSG.READY) {
      if (!this.ready) {
        this.ready = true
        // 必须先派发 `ready`，让宿主有机会在 flush 前调用 loadWidgetConfig()
        // 发送 `tv:init`，避免排队中的平台数据先到达，而后又被后续 init 重置。
        this.emit('ready', {})
        this.flushPendingQueue()
        // 注意：这里不能 flush postLoadQueue；平台数据必须等到 LOADED 后再发。
      }
    }

    // 3. LOADED：Guest 完成 registerAndLoad，平台字段适配器已经接好。
    if (type === 'LOADED') {
      if (!this.loaded) {
        this.loaded = true
        this.flushPostLoadQueue()
        this.replayLatestPlatformData()
      }
      this.emit('loaded', payload)
    }

    // 4. Guest 主动请求重新 init，例如内部 bootstrap 重跑之后。
    if (type === TV_MSG.REQUEST_INIT) {
      if (this.lastInitPayload) {
        this.loaded = false
        this.send(TV_MSG.INIT, this.lastInitPayload)
      } else {
        this.emit('ready', {})
      }
    }

    // 5. 其他消息保持透传，交给外部订阅者自行处理。
    this.emit(type, payload)
  }

  /**
   * 触发 SDK 内部事件总线。
   */
  private emit(type: string, payload: any) {
    const handlers = this.messageHandlers.get(type)
    if (handlers) {
      handlers.forEach(handler => handler(payload))
    }
  }

  /**
   * 直接向 iframe 发消息。
   * 这里不做 ready/loaded 判断，调用方自行决定是否排队。
   */
  private postToIframe(message: unknown): void {
    if (!this.iframe.contentWindow) return
    this.iframe.contentWindow.postMessage(message, this.targetOrigin)
  }

  /**
   * 发送基础协议消息；若 Guest 尚未 READY，则先进入 pendingQueue。
   */
  private send(type: string, payload: any = {}) {
    // 当前协议约定 Guest 接收 `{ type, payload }` 结构，不要改成扁平字段。
    const message = { type, payload }
    const action = () => this.postToIframe(message)

    if (this.ready) {
      action()
    } else {
      this.pendingQueue.push(action)
    }
  }

  private flushPendingQueue() {
    while (this.pendingQueue.length > 0) {
      const action = this.pendingQueue.shift()
      if (action) action()
    }
  }

  /**
   * 发送必须等到 Guest 适配器接好后才能消费的消息。
   * 在 `LOADED` 之前调用时会先进入 `postLoadQueue`，待 Guest 就绪后自动冲刷。
   */
  private sendWhenLoaded(type: string, payload: any = {}) {
    const message = { type, payload }
    const action = () => this.postToIframe(message)
    if (this.loaded) {
      action()
    } else {
      this.postLoadQueue.push(action)
    }
  }

  private flushPostLoadQueue() {
    while (this.postLoadQueue.length > 0) {
      const action = this.postLoadQueue.shift()
      if (action) action()
    }
  }

  private replayLatestPlatformData() {
    for (const { fields, deviceId } of this.latestPlatformDataByScope.values()) {
      this.sendWhenLoaded('tv:platform-data', { fields, deviceId })
    }

    for (const { fieldId, history, deviceId } of this.latestPlatformHistoryByScope.values()) {
      this.sendWhenLoaded('tv:platform-history', { fieldId, history, deviceId })
    }
  }

  // ===========================
  // 对外 API：Widget 模式
  // ===========================

  /**
   * [Widget Mode] 加载或更新挂件配置。
   * 方向：Host -> Guest
   * 协议：`tv:init`
   */
  public loadWidgetConfig(config: any, platformFields?: any[], options?: WidgetLoadOptions) {
    this.loaded = false

    // 容忍空配置或损坏配置，至少保证编辑器/预览器可以先以空白画布启动。
    const safeConfig = config || {}
    const safeCanvas = safeConfig.canvas || {
      mode: 'grid',
      width: 1920,
      height: 1080,
      gridCols: 24,
      gridRowHeight: 50,
      gridGap: 5
    }
    const safeNodes = safeConfig.nodes || []
    const safeVariables = Array.isArray(safeConfig.variables) ? safeConfig.variables : []

    // 将平台数据缓冲区配置合并到保存态数据源上，避免 Guest 侧遗漏 bufferSize。
    const existingDataSources: any[] = safeConfig.dataSources ?? []
    const mergedDataSources = existingDataSources.map((ds: any) => {
      const typeStr = typeof ds.type === 'string' ? ds.type.toUpperCase() : ''
      if (typeStr === 'PLATFORM_FIELD' || typeStr === 'PLATFORM') {
        const config = ds.config || {}
        return {
          ...ds,
          config: {
            ...config,
            bufferSize: Math.max(config.bufferSize ?? 0, options?.platformBufferSize ?? 0)
          }
        }
      }
      return ds
    })

    const payload = {
      // `platformDevices` 必须放在顶层，Guest 的 EmbedPage.tsx 直接从 `msg.platformDevices` 读取。
      platformDevices: options?.platformDevices ?? [],
      data: {
        meta: safeConfig.meta || { id: 'widget', name: '挂件' },
        canvas: safeCanvas,
        nodes: safeNodes,
        dataSources: mergedDataSources,
        variables: safeVariables,
        platformFields: platformFields
      },
      config: {
        saveTarget: 'host',
        thingsvisApiBaseUrl: options?.thingsvisApiBaseUrl ?? `${window.location.origin}/thingsvis-api`,
        platformApiBaseUrl: options?.platformApiBaseUrl ?? getPlatformApiBase(),
        ...(options?.platformToken ? { platformToken: options.platformToken } : {}),
        ...(options?.deviceId ? { deviceId: options.deviceId } : {})
      }
    }

    this.lastInitPayload = payload
    this.send(TV_MSG.INIT, payload)
  }

  /**
   * [Widget Mode] 更新平台字段定义，供 Guest 数据源选择器使用。
   * 方向：Host -> Guest
   *
   * 说明：Guest 目前没有专门的 `update-schema` 监听器。
   * 现在仍以 `tv:init` 携带 `platformFields` 为主，这里只是预留一个可选扩展事件。
   */
  public updateSchema(fields: any[]) {
    // 这里发送通用 editor 事件，是否生效取决于 Guest 是否实现对应适配。
    this.send(TV_MSG.EVENT, { event: 'updateSchema', payload: fields })
  }

  /**
   * [Widget Mode] 推送实时平台字段值到嵌入挂件。
   * 协议：`tv:platform-data`，由 Guest 侧 PlatformFieldAdapter 直接消费。
   *
   * @param fields 字段 ID 到当前值的映射，例如 `{ temperature: 25.3 }`
   */
  public pushPlatformFieldData(fields: Record<string, unknown>, deviceId?: string): void {
    this.platformPushCount += 1
    const scopeKey = deviceId ?? '__global__'
    this.latestPlatformDataByScope.set(scopeKey, {
      fields: { ...fields },
      ...(deviceId ? { deviceId } : {})
    })
    // 必须等到 LOADED：PlatformFieldAdapter 的 messageListener 在 registerAndLoad
    // 结束后才会挂上，而 registerAndLoad 又发生在 tv:init 处理之后。
    this.sendWhenLoaded('tv:platform-data', { fields, deviceId })
  }

  /**
   * [Widget Mode] 推送单字段历史值到嵌入挂件。
   * 协议：`tv:platform-history`，同样要求 Guest 已经进入 `LOADED` 阶段。
   */
  public pushPlatformFieldHistory(
    fieldId: string,
    history: Array<{ value: unknown; ts: number }>,
    deviceId?: string
  ): void {
    if (!fieldId || !Array.isArray(history)) return

    const scopeKey = `${deviceId ?? '__global__'}:${fieldId}`
    this.latestPlatformHistoryByScope.set(scopeKey, {
      fieldId,
      history: history.map(item => ({ value: item.value, ts: item.ts })),
      ...(deviceId ? { deviceId } : {})
    })
    this.sendWhenLoaded('tv:platform-history', { fieldId, history, deviceId })
  }

  /**
   * [Widget Mode] 宿主主动触发保存。
   * 方向：Host -> Guest -> Host
   * 协议：`tv:trigger-save` -> `tv:save`
   */
  public triggerSave() {
    this.send(TV_MSG.TRIGGER_SAVE)
  }

  /**
   * [Widget Mode] 监听 Guest 返回的保存结果。
   * 方向：Guest -> Host
   */
  public onWidgetSave(callback: (config: any) => void) {
    // `handleMessage` 会先把 `tv:save` 统一转发为 `tv:save-config`。
    this.on(TV_MSG.SAVE_CONFIG, payload => {
      // 典型 payload 结构为 `{ canvas, nodes, dataBindings }`，这里保持原样透传。
      callback(payload)
    })
  }

  // ===========================
  // 对外 API：App 模式
  // ===========================

  /**
   * [App Mode] 请求编辑器立即执行一次保存。
   * Guest 完成 `saveNow()` 后，宿主仍通过 `onWidgetSave()` 接收返回数据。
   */
  public requestSave() {
    sdkLogger.debug('[SDK] Client requesting save from Editor...')
    // `tv:request-save` 目前属于扩展协议消息，不在通用 EmbedMessage 类型声明里。
    this.send(TV_MSG.REQUEST_SAVE)
  }

  /**
   * [App Mode] 更新 Guest 侧使用的 token。
   * 方向：Host -> Guest
   *
   * App Mode 主流程通常通过 URL 传 token，这里保留 PostMessage 热更新能力。
   */
  public updateToken(token: string) {
    this.send(TV_MSG.EVENT, { event: 'updateToken', payload: { token } })
  }

  /** 校验消息是否来自当前 iframe 且 origin 与目标域完全一致。 */
  public isTrustedMessageEvent(event: MessageEvent): boolean {
    const iframeWindow = this.iframe.contentWindow
    return !!iframeWindow && event.source === iframeWindow && event.origin === this.targetOrigin
  }

  public postMessageToGuest(message: unknown): void {
    this.postToIframe(message)
  }

  // ===========================
  // 消息总线
  // ===========================

  public on(type: string, handler: MessageHandler) {
    if (!this.messageHandlers.has(type)) {
      this.messageHandlers.set(type, [])
    }
    this.messageHandlers.get(type)?.push(handler)
  }

  public off(type: string, handler: MessageHandler) {
    const handlers = this.messageHandlers.get(type)
    if (handlers) {
      const index = handlers.indexOf(handler)
      if (index !== -1) {
        handlers.splice(index, 1)
      }
    }
  }

  public destroy() {
    window.removeEventListener('message', this.handleMessage)
    if (this.iframe.parentNode && this.iframe) {
      this.iframe.parentNode.removeChild(this.iframe)
    }
    this.messageHandlers.clear()
    this.pendingQueue = []
    this.postLoadQueue = []
    this.latestPlatformDataByScope.clear()
    this.latestPlatformHistoryByScope.clear()
    this.lastInitPayload = null
    this.ready = false
    this.loaded = false
  }
}

/*
 * 文件用途：管理物模型详情的本地缓存。
 * 核心逻辑：归一化物模型 ID 后读写和清理缓存，减少重复详情请求。
 * 关键注意事项：物模型 ID 空值或类型转换错误会导致缓存串用。
 * 重构建议：可加入缓存过期和按租户隔离策略。
 */
import { deviceTemplateDetail } from '@/service/api/device'

const templateDetailCache = new Map<string, Promise<any>>()

function normalizeTemplateId(templateId?: string | number) {
  return String(templateId || '').trim()
}

export function clearCachedDeviceTemplateDetail(templateId?: string | number) {
  const normalizedTemplateId = normalizeTemplateId(templateId)
  if (!normalizedTemplateId) return
  templateDetailCache.delete(normalizedTemplateId)
}

export function getCachedDeviceTemplateDetail(templateId?: string | number) {
  const normalizedTemplateId = normalizeTemplateId(templateId)
  if (!normalizedTemplateId) {
    return Promise.resolve(null)
  }

  const cached = templateDetailCache.get(normalizedTemplateId)
  if (cached) return cached

  const request = deviceTemplateDetail({ id: normalizedTemplateId }).catch(error => {
    templateDetailCache.delete(normalizedTemplateId)
    throw error
  })

  templateDetailCache.set(normalizedTemplateId, request)
  return request
}

/*
 * 文件用途：解析 ThingsVis 物模型图表预设配置。
 * 核心逻辑：从物模型图表配置中提取按属性类型和字段 ID 组织的预设 widget。
 * 关键注意事项：配置结构可能来自后端或第三方模板，需要容错未知字段。
 * 重构建议：建议补充非法 JSON、缺字段和多预设合并测试。
 */
import type { PlatformField } from './types'

export type TemplatePresetPropertyType = 'telemetry' | 'attributes'

type TemplatePresetWidget = Record<string, unknown>

type TemplatePresetEntry = {
  id?: string
  name?: string
  widget?: TemplatePresetWidget
  thumbnail?: string
  [key: string]: unknown
}

type TemplatePresetMap = Record<string, TemplatePresetEntry[]>

type TemplateChartConfig = Record<string, unknown> & {
  device_widget_presets?: TemplatePresetMap
  nodes?: TemplatePresetWidget[]
  canvas?: Record<string, unknown>
  dataSources?: unknown[]
}

const DEFAULT_PRESET_CANVAS = {
  mode: 'grid',
  width: 1920,
  height: 1080,
  gridCols: 24,
  gridRowHeight: 50,
  gridGap: 5
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

export function parseTemplateChartConfig(rawConfig: unknown): TemplateChartConfig {
  if (typeof rawConfig === 'string') {
    if (!rawConfig.trim()) return {}
    try {
      const parsed = JSON.parse(rawConfig)
      return isRecord(parsed) ? (parsed as TemplateChartConfig) : {}
    } catch (error) {
      console.warn('[template-presets] Failed to parse chart config:', error)
      return {}
    }
  }

  if (isRecord(rawConfig)) {
    return rawConfig as TemplateChartConfig
  }

  return {}
}

export function getTemplatePresetKey(propertyType: TemplatePresetPropertyType, fieldId: string) {
  return `${propertyType}_${fieldId}`
}

export function getTemplatePresetMap(rawConfig: unknown): TemplatePresetMap {
  const config = parseTemplateChartConfig(rawConfig)
  return isRecord(config.device_widget_presets) ? config.device_widget_presets : {}
}

export function getTemplatePresetEntries(
  rawConfig: unknown,
  propertyType: TemplatePresetPropertyType,
  fieldId: string
): TemplatePresetEntry[] {
  const presets = getTemplatePresetMap(rawConfig)
  const entries = presets[getTemplatePresetKey(propertyType, fieldId)]
  return Array.isArray(entries) ? (entries.filter(isRecord) as TemplatePresetEntry[]) : []
}

export function buildPresetEditorConfig(widget?: TemplatePresetWidget | null) {
  if (!isRecord(widget)) return null

  return {
    meta: {
      id: 'template-preset',
      name: '物模型预设'
    },
    canvas: DEFAULT_PRESET_CANVAS,
    nodes: [widget],
    dataSources: []
  }
}

export function extractFirstNodeFromWidgetConfig(payload: unknown): TemplatePresetWidget | null {
  if (!isRecord(payload)) return null

  if (Array.isArray(payload.nodes) && payload.nodes.length > 0 && isRecord(payload.nodes[0])) {
    return payload.nodes[0] as TemplatePresetWidget
  }

  if (isRecord(payload.nodesById)) {
    const firstNode = Object.values(payload.nodesById).find(isRecord)
    if (firstNode) return firstNode as TemplatePresetWidget
  }

  return null
}

function resolvePresetFieldMeta(
  fieldId: string,
  propertyType: TemplatePresetPropertyType,
  fieldMap: Map<string, PlatformField>
) {
  const field = fieldMap.get(fieldId)

  return {
    fieldId,
    fieldName: field?.name || fieldId,
    propertyType,
    dataType: field?.dataType,
    unit: field?.unit
  }
}

export function buildTemplateDevicePresets(rawConfig: unknown, fields: PlatformField[]) {
  const presetMap = getTemplatePresetMap(rawConfig)
  const fieldMap = new Map(fields.map(field => [field.id, field]))

  return Object.entries(presetMap).flatMap(([presetKey, entries]) => {
    const match = /^(telemetry|attributes)_(.+)$/.exec(presetKey)
    if (!match || !Array.isArray(entries)) return []

    const [, propertyType, fieldId] = match as unknown as [string, TemplatePresetPropertyType, string]
    const fieldMeta = resolvePresetFieldMeta(fieldId, propertyType, fieldMap)

    return entries.flatMap((entry, index) => {
      if (!isRecord(entry?.widget)) return []

      return [
        {
          id: String(entry.id || `${presetKey}_${index}`),
          name: String(entry.name || `${fieldMeta.fieldName}卡片预设`),
          widget: entry.widget,
          thumbnail: typeof entry.thumbnail === 'string' ? entry.thumbnail : undefined,
          ...fieldMeta
        }
      ]
    })
  })
}

export function hasThingsVisChartContent(rawConfig: unknown) {
  const config = parseTemplateChartConfig(rawConfig)

  if (Array.isArray(config.nodes) && config.nodes.length > 0) {
    return true
  }

  return isRecord(config.canvas) || Array.isArray(config.dataSources)
}

/*
 * 文件用途：提供 ThingsVis SSO 认证服务。
 * 核心逻辑：读取当前用户空间，向后端交换 SSO token，并管理缓存、刷新和清理。
 * 关键注意事项：token、spaceId 和错误日志都属于敏感边界，不能泄露或跨用户复用。
 * 重构建议：可把请求、缓存和日志降噪拆分，补充失败/过期分支测试。
 */
/**
 * ThingsVis SSO Authentication Service
 * 实现 AetherLink IoT Token 与 ThingsVis JWT Token 的交换
 */

import { localStg } from '@/utils/storage'
import { createLogger } from '@/utils/logger'
import { shouldSuppressUnmockedTestConsole } from '@/utils/test-console'
import type { SSOExchangeRequest, SSOExchangeResponse } from './types'
import { THINGSVIS_API_PROXY_PATH, THINGSVIS_COMPAT_PLATFORM, getThingsVisApiBase } from './constants'
import { resolveThingsVisSpaceId, type UserInfoLike } from './space'

const ssoLogger = createLogger('ThingsVisSSO')

function isUserInfoLike(value: unknown): value is UserInfoLike {
  if (!value || typeof value !== 'object') {
    return false
  }

  const candidate = value as Record<string, unknown>

  return (
    typeof candidate.userId === 'string' ||
    typeof candidate.id === 'string' ||
    typeof candidate.userName === 'string' ||
    typeof candidate.email === 'string' ||
    typeof candidate.authority === 'string'
  )
}

function ssoLog(...args: any[]): void {
  if (!shouldSuppressUnmockedTestConsole(console.log)) ssoLogger.debug(...args)
}

function ssoWarn(...args: any[]): void {
  if (!shouldSuppressUnmockedTestConsole(console.warn)) ssoLogger.warn(...args)
}

function ssoError(...args: any[]): void {
  if (!shouldSuppressUnmockedTestConsole(console.error)) ssoLogger.error(...args)
}

/**
 * ThingsVis SSO 认证服务类
 */
export class ThingsVisAuthService {
  private cachedToken: string | null = null
  private tokenExpiry: number = 0
  private cachedIdentityKey: string | null = null
  private exchangePromise: Promise<string> | null = null
  private thingsvisApiUrl: string
  private readonly thingsvisApiTarget: string
  private readonly networkFailureCooldownMs = 30_000
  private lastNetworkFailureAt: number = 0
  private lastNetworkFailureReason: string | null = null

  constructor() {
    // SSO API 地址
    // 前端固定请求代理路径 /thingsvis-api 以避免 CORS。
    // Vite 会将其重写为 `${VITE_THINGSVIS_API_URL}/api/v1/*`。
    this.thingsvisApiUrl = THINGSVIS_API_PROXY_PATH
    this.thingsvisApiTarget = import.meta.env.VITE_THINGSVIS_API_URL || getThingsVisApiBase()
  }

  private getFailureCooldownRemaining(): number {
    if (!this.lastNetworkFailureAt) return 0

    return Math.max(0, this.networkFailureCooldownMs - (Date.now() - this.lastNetworkFailureAt))
  }

  private markNetworkFailure(reason: string): Error {
    this.lastNetworkFailureAt = Date.now()
    this.lastNetworkFailureReason = reason

    return new Error(`ThingsVis SSO backend unavailable: ${this.thingsvisApiTarget} (${reason})`)
  }

  private clearNetworkFailure(): void {
    this.lastNetworkFailureAt = 0
    this.lastNetworkFailureReason = null
  }

  private resetTokenCache(clearExchangePromise: boolean = false): void {
    this.cachedToken = null
    this.tokenExpiry = 0
    this.cachedIdentityKey = null

    if (clearExchangePromise) {
      this.exchangePromise = null
    }
  }

  private isNetworkError(error: unknown): boolean {
    const message = error instanceof Error ? error.message : String(error || '')
    const normalized = message.toLowerCase()

    return (
      normalized.includes('failed to fetch') ||
      normalized.includes('networkerror') ||
      normalized.includes('load failed') ||
      normalized.includes('econnrefused')
    )
  }

  private shouldTreatResponseAsUnavailable(status: number, errorText: string): boolean {
    if ([502, 503, 504].includes(status)) return true

    return errorText.toLowerCase().includes('econnrefused')
  }

  /**
   * 等待 userInfo 就绪（处理首次登录时的竞态条件）
   * 当 loginByToken 还未完成 localStg.set('userInfo') 时，首页组件可能已挂载
   */
  private async waitForUserInfo(maxRetries: number = 5, intervalMs: number = 200): Promise<UserInfoLike | null> {
    const initialUserInfo = localStg.get('userInfo')
    let userInfo = isUserInfoLike(initialUserInfo) ? initialUserInfo : null
    let retries = 0

    while (!userInfo && retries < maxRetries) {
      retries++
      ssoLog(`[SSO] 等待 userInfo 就绪... (${retries}/${maxRetries})`)
      await new Promise((resolve) => setTimeout(resolve, intervalMs))
      const nextUserInfo = localStg.get('userInfo')
      userInfo = isUserInfoLike(nextUserInfo) ? nextUserInfo : null
    }

    if (!userInfo) {
      ssoWarn(`[SSO] userInfo 仍未就绪，共尝试 ${retries} 次`)
    }

    return userInfo
  }

  /**
   * 交换 AetherLink IoT Token -> ThingsVis Token
   */
  async exchangeToken(): Promise<string> {
    try {
      const cooldownRemaining = this.getFailureCooldownRemaining()
      if (cooldownRemaining > 0) {
        const retryAfterSeconds = Math.ceil(cooldownRemaining / 1000)
        const reason = this.lastNetworkFailureReason || 'recent network failure'
        throw new Error(
          `ThingsVis SSO backend unavailable: ${this.thingsvisApiTarget} (${reason}; retry in ${retryAfterSeconds}s)`
        )
      }

      // 1. 获取当前 AetherLink IoT 用户信息
      // 注意：首次登录时，userInfo 可能尚未写入 localStorage（竞态条件）
      // 需要等待 userInfo 就绪
      const tpToken = localStg.get('token')
      const userInfo = await this.waitForUserInfo()

      if (!tpToken) {
        throw new Error('AetherLink IoT token not found')
      }

      if (!userInfo) {
        throw new Error('User info not found')
      }

      const resolvedSpaceId = resolveThingsVisSpaceId(userInfo)
      this.cachedIdentityKey = `${userInfo.userId || userInfo.id || ''}::${resolvedSpaceId}`

      // 2. 构建 SSO 请求
      const request: SSOExchangeRequest = {
        platform: THINGSVIS_COMPAT_PLATFORM,
        platformToken: tpToken,
        userInfo: {
          id: userInfo.userId || userInfo.id || '',
          email: userInfo.email || `${userInfo.userName}@aetherlink.local`,
          name: userInfo.userName || 'AetherLink User',
          tenantId: resolvedSpaceId
        }
      }

      // 3. 映射 AetherLink IoT authority -> ThingsVis role，用于注册时初始化默认看板
      const authority = userInfo.authority
      let role: SSOExchangeRequest['role']

      if (authority === 'SYS_ADMIN') {
        role = 'SUPER_ADMIN'
      } else if (authority === 'TENANT_ADMIN') {
        role = 'TENANT_ADMIN'
      } else {
        role = 'EDITOR'
      }

      request.role = role
      ssoLog('[SSO] 角色映射:', { authority, role })

      // 3. 调用 ThingsVis SSO API (通过代理)
      // /thingsvis-api/auth/sso -> ${VITE_THINGSVIS_API_URL}/api/v1/auth/sso
      const ssoUrl = `${this.thingsvisApiUrl}/auth/sso`
      ssoLog('[SSO] 📡 调用 SSO API:', ssoUrl)
      ssoLog('[SSO] 请求目标:', this.thingsvisApiTarget)
      ssoLog('[SSO] 请求数据:', {
        platform: request.platform,
        userEmail: request.userInfo.email,
        role: request.role
      })

      const response = await fetch(ssoUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(request)
      })

      ssoLog('[SSO] 响应状态:', response.status)

      if (!response.ok) {
        const errorText = await response.text()
        ssoError('[SSO] 响应错误:', errorText)
        if (this.shouldTreatResponseAsUnavailable(response.status, errorText)) {
          throw this.markNetworkFailure(`HTTP ${response.status}: ${errorText || 'proxy unavailable'}`)
        }
        throw new Error(`Token exchange failed: ${response.status} - ${errorText}`)
      }

      const data: SSOExchangeResponse = await response.json()
      this.clearNetworkFailure()

      // 4. 缓存 Token
      this.cachedToken = data.accessToken
      this.tokenExpiry = Date.now() + (data.expiresIn || 7200) * 1000 // 默认 2 小时

      ssoLog('✅ SSO Token exchange successful')

      return data.accessToken
    } catch (error) {
      // 清除缓存的 token
      this.resetTokenCache()

      if (this.isNetworkError(error)) {
        const unavailableError = this.markNetworkFailure(error instanceof Error ? error.message : String(error))
        ssoError('❌ SSO Token exchange failed:', unavailableError)
        throw unavailableError
      }

      ssoError('❌ SSO Token exchange failed:', error)
      throw error
    }
  }

  /**
   * 获取有效的 ThingsVis Token (自动刷新)
   */
  async getValidToken(): Promise<string> {
    // 注意：首次登录时，userInfo 可能尚未写入 localStorage
    // identityKey 检查需要等待 userInfo 就绪
    let userInfo = await this.waitForUserInfo(3, 100)
    const identityKey = userInfo
      ? `${userInfo.userId || userInfo.id || ''}::${resolveThingsVisSpaceId(userInfo)}`
      : null

    if (this.cachedIdentityKey && identityKey && this.cachedIdentityKey !== identityKey) {
      this.clearToken()
    }

    // Token 未过期，直接返回
    if (this.cachedToken && Date.now() < this.tokenExpiry) {
      ssoLog('🔄 Using cached ThingsVis token')
      return this.cachedToken
    }

    if (this.exchangePromise) {
      ssoLog('🔄 Waiting for in-flight ThingsVis token exchange...')
      return this.exchangePromise
    }

    // Token 过期或不存在，重新交换
    ssoLog('🔄 Token expired or not found, exchanging...')
    this.exchangePromise = this.exchangeToken().finally(() => {
      this.exchangePromise = null
    })
    return await this.exchangePromise
  }

  /**
   * 清除缓存的 Token
   */
  clearToken(): void {
    this.resetTokenCache(true)
  }

  /**
   * 检查 Token 是否有效
   */
  isTokenValid(): boolean {
    return Boolean(this.cachedToken && Date.now() < this.tokenExpiry)
  }

  /**
   * 获取 Token 过期时间
   */
  getTokenExpiry(): Date | null {
    if (!this.tokenExpiry) return null
    return new Date(this.tokenExpiry)
  }
}

/**
 * 单例实例
 */
export const thingsvisAuthService = new ThingsVisAuthService()

/**
 * 便捷方法：获取有效的 ThingsVis Token
 */
export async function getThingsVisToken(): Promise<string> {
  return thingsvisAuthService.getValidToken()
}

/**
 * 便捷方法：清除 ThingsVis Token
 */
export function clearThingsVisToken(): void {
  thingsvisAuthService.clearToken()
}

/*
 * 文件用途：定义 ThingsVis 集成所需的项目、字段、保存消息、平台数据和 SSO 类型。
 * 核心逻辑：集中声明 iframe 通信、平台字段和认证响应的数据结构。
 * 关键注意事项：类型变更会影响 SDK、URL 构建和嵌入页面契约。
 * 重构建议：后续可与后端 API schema 对齐，减少手写漂移。
 */
/**
 * ThingsVis 相关类型定义
 */

import type { ThingsVisCompatPlatform } from './constants'

/** 平台字段类型 */
export interface PlatformField {
  /** 字段唯一标识 */
  id: string
  /** 显示名称 */
  name: string
  /** 数据类型 */
  type: 'number' | 'string' | 'boolean' | 'json'
  /** 字段类型 */
  dataType: 'attribute' | 'telemetry' | 'command' | 'event'
  /** 单位(可选) */
  unit?: string
  /** 描述(可选) */
  description?: string
}

/** ThingsVis 项目配置 */
export interface ThingsVisProject {
  meta: {
    version: string
    id: string
    name: string
    createdAt?: number
    updatedAt?: number
  }
  canvas: {
    mode: string
    width: number
    height: number
    background: string
    gridEnabled?: boolean
  }
  nodes: any[]
  dataSources: any[]
  dataBindings: any[]
}

/** 保存请求消息 */
export interface SaveRequestMessage {
  type: 'tv:request-save'
  requestId: string
  payload: ThingsVisProject
}

/** 保存响应消息 */
export interface SaveResponseMessage {
  type: 'tv:save-response'
  requestId: string
  payload: {
    success: boolean
    data?: any
    error?: string
  }
}

/** 平台数据推送消息 */
export interface PlatformDataMessage {
  type: 'tv:platform-data'
  payload: {
    fieldId: string
    value: any
    timestamp: number
  }
}

/** SSO Token 交换请求 */
export interface SSOExchangeRequest {
  /** 平台标识 */
  platform: ThingsVisCompatPlatform
  /** AetherLink IoT JWT Token */
  platformToken: string
  /** 用户信息 */
  userInfo: {
    /** 用户 ID */
    id: string
    /** 用户邮箱 */
    email: string
    /** 用户名称 */
    name?: string
    /** 租户 ID */
    tenantId: string
  }
  /** ThingsVis 角色，用于注册时初始化默认看板。
   * SYS_ADMIN → SUPER_ADMIN, TENANT_ADMIN → TENANT_ADMIN, 其他 → EDITOR */
  role?: 'SUPER_ADMIN' | 'TENANT_ADMIN' | 'EDITOR' | 'VIEWER'
}

/** SSO Token 交换响应 */
export interface SSOExchangeResponse {
  /** ThingsVis JWT Access Token */
  accessToken: string
  /** 刷新 Token */
  refreshToken?: string
  /** Token 过期时间(秒) */
  expiresIn: number
  /** 用户信息 */
  user?: {
    id: string
    email: string
    name?: string
    role?: string
  }
}

