    bool: ref(false),
    setTrue: vi.fn(() => {}),
    setFalse: vi.fn(() => {}),
    setBool: vi.fn(() => {})
  })
}))

vi.mock('vue', async importOriginal => {
  const actual = await importOriginal<typeof import('vue')>()
  return {
    ...actual,
    getCurrentInstance: () => ({
      proxy: hoisted.currentInstanceProxy
    })
  }
})

vi.mock('naive-ui', async (importOriginal) => {
