import PopUp from '../pop-up.vue'

const mountedWrappers: Array<ReturnType<typeof shallowMount>> = []

const baseEditData = {
  id: 'alarm-1',
  name: 'Alarm 1',
  alarm_level: 'H',
  alarm_repeat_time: 2,
  alarm_keep_time: 5,
  notification_group_id: 'group-1',
  enabled: 'Y',
  description: 'desc'
}

const mountComponent = (props: Record<string, any> = {}) => {
  const wrapper = shallowMount(PopUp, {
    props: {
      visible: true,
      type: 'add',
      editData: null,
      ...props
    },
    global: {
      stubs: {
        NModal: defineComponent({
          props: { show: Boolean },
          emits: ['update:show'],
          setup(_, { slots }) {
            return () => h('div', slots.default ? slots.default() : [])
          }
        }),
        NForm: defineComponent({ setup(_, { slots }) { return () => h('form', slots.default ? slots.default() : []) } }),
        NFormItem: defineComponent({ setup(_, { slots }) { return () => h('div', slots.default ? slots.default() : []) } }),
        NInput: defineComponent({ setup() { return () => h('input') } }),
        NSelect: defineComponent({ setup() { return () => h('div') } }),
        NSpace: defineComponent({ setup(_, { slots }) { return () => h('div', slots.default ? slots.default() : []) } }),
        NButton: defineComponent({
          emits: ['click'],
          setup(_, { slots, emit }) {
            return () => h('button', { onClick: () => emit('click') }, slots.default ? slots.default() : [])
          }
        })
      }
    }
  })
  mountedWrappers.push(wrapper)
  return wrapper
}

const getSetupState = (wrapper: ReturnType<typeof shallowMount>) => wrapper.vm.$.setupState as Record<string, any>

describe('pop-up.vue', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    hoisted.getNotificationGroupList
      .mockResolvedValueOnce({
        data: {
          list: [
            { id: 'group-1', name: 'Open Group', status: 'OPEN' }
          ],
          total: 60
        }
      })
      .mockResolvedValue({
        data: {
          list: [
            { id: 'group-2', name: 'Closed Group', status: 'CLOSE' }
          ],
          total: 60
        }
      })
    hoisted.addWarningMessage.mockResolvedValue({ ok: true })
    hoisted.editInfo.mockResolvedValue({ data: true })
    hoisted.validateMock.mockImplementation(callback => callback(null))
  })

  afterEach(() => {
    while (mountedWrappers.length > 0) {
      mountedWrappers.pop()?.unmount()
    }
  })

  it('loads notification groups on mount and appends the next page on scroll', async () => {
    const wrapper = mountComponent()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    expect(setupState.state.generalOptions[0]).toMatchObject({
      id: 'group-1',
      name: 'Open Group',
      disabled: false
    })

    await setupState.notificationGroupHandleScroll({
      target: { scrollTop: 80, clientHeight: 20, scrollHeight: 100 }
    })
    await flushPromises()

    expect(hoisted.getNotificationGroupList).toHaveBeenCalledTimes(2)
    expect(setupState.state.generalOptions).toHaveLength(2)
    expect(setupState.state.generalOptions[1]).toMatchObject({
      id: 'group-2',
      name: 'Closed Group',
      disabled: true
    })
  })

  it('computes add and edit titles', async () => {
    const wrapper = mountComponent({ type: 'add' })
    await flushPromises()
    expect(getSetupState(wrapper).title).toBe('generate.addAlarm')

    await wrapper.setProps({ type: 'edit', editData: { ...baseEditData } })
    await flushPromises()
    expect(getSetupState(wrapper).title).toBe('generate.editAlarm')
  })

  it('fills edit data and stringifies numeric time fields', async () => {
    const wrapper = mountComponent()
    await flushPromises()

    await wrapper.setProps({ type: 'edit', editData: { ...baseEditData } })
    await flushPromises()

    const setupState = getSetupState(wrapper)
    expect(setupState.formData.alarm_keep_time).toBe('5')
    expect(setupState.formData.alarm_repeat_time).toBe('2')
    expect(setupState.formData.name).toBe('Alarm 1')
  })

  it('resets form data when switching back to add mode', async () => {
    const wrapper = mountComponent({ type: 'edit', editData: { ...baseEditData } })
    await flushPromises()

    await wrapper.setProps({ type: 'add', editData: null })
    await flushPromises()

    const setupState = getSetupState(wrapper)
    expect(setupState.formData.name).toBe('')
    expect(setupState.formData.alarm_level).toBe('')
    expect(setupState.formData.notification_group_id).toBe('')
  })

  it('closeModal emits visibility update and refresh callback', async () => {
    const wrapper = mountComponent()
    await flushPromises()

    getSetupState(wrapper).closeModal()

    expect(wrapper.emitted('update:visible')).toEqual([[false]])
    expect(wrapper.emitted('newEdit')).toEqual([[]])
    expect(wrapper.emitted('saved')).toBeUndefined()
  })

  it('submits add payload with numeric fields and reports success', async () => {
    hoisted.addWarningMessage.mockResolvedValueOnce({
      data: {
        id: 'alarm-new',
        name: 'New alarm'
      }
    })
    const wrapper = mountComponent({ type: 'add' })
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.formRef = {
      validate: (callback: (errors: unknown) => void) => hoisted.validateMock(callback)
    }
    setupState.formData.name = 'New alarm'
    setupState.formData.alarm_level = 'M'
    setupState.formData.alarm_repeat_time = '3'
    setupState.formData.alarm_keep_time = '6'
    setupState.formData.notification_group_id = 'group-1'
    setupState.formData.description = 'note'

    setupState.handleReset({ preventDefault: vi.fn() })
    await flushPromises()

    expect(hoisted.addWarningMessage).toHaveBeenCalledWith({
      name: 'New alarm',
      alarm_level: 'M',
      alarm_repeat_time: 3,
      alarm_keep_time: 6,
      notification_group_id: 'group-1',
      enabled: 'Y',
      description: 'note'
    })
    expect(hoisted.messageSuccess).toHaveBeenCalledWith('common.addSuccess')
    expect(wrapper.emitted('saved')).toEqual([
      [
        expect.objectContaining({
          id: 'alarm-new',
          name: 'New alarm',
          alarm_level: 'M',
          alarm_repeat_time: 3,
          alarm_keep_time: 6
        })
      ]
    ])
    expect(wrapper.emitted('newEdit')).toEqual([[]])
  })

  it('reports add failure when API returns a falsy result', async () => {
    hoisted.addWarningMessage.mockResolvedValueOnce(null)
    const wrapper = mountComponent({ type: 'add' })
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.formRef = {
      validate: (callback: (errors: unknown) => void) => hoisted.validateMock(callback)
    }
    setupState.formData.name = 'New alarm'
    setupState.formData.alarm_level = 'M'
    setupState.formData.alarm_repeat_time = '1'
    setupState.formData.alarm_keep_time = '2'

    setupState.handleReset({ preventDefault: vi.fn() })
    await flushPromises()

    expect(hoisted.messageError).toHaveBeenCalledWith('common.addFail')
  })

  it('submits edit payload and reports success', async () => {
    const wrapper = mountComponent({ type: 'edit', editData: { ...baseEditData } })
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.formRef = {
      validate: (callback: (errors: unknown) => void) => hoisted.validateMock(callback)
    }
    setupState.formData.id = 'alarm-1'
    setupState.formData.name = 'Updated alarm'
    setupState.formData.alarm_level = 'L'
    setupState.formData.alarm_repeat_time = '4'
    setupState.formData.alarm_keep_time = '8'
    setupState.formData.notification_group_id = 'group-2'
    setupState.formData.description = 'updated'

    setupState.handleReset({ preventDefault: vi.fn() })
    await flushPromises()

    expect(hoisted.editInfo).toHaveBeenCalledWith({
      id: 'alarm-1',
      name: 'Updated alarm',
      alarm_level: 'L',
      alarm_repeat_time: 4,
      alarm_keep_time: 8,
      notification_group_id: 'group-2',
      enabled: 'Y',
      description: 'updated'
    })
    expect(hoisted.messageSuccess).toHaveBeenCalledWith('common.editSuccess')
  })

  it('reports edit failure when API response has no data', async () => {
    hoisted.editInfo.mockResolvedValueOnce({ data: null })
    const wrapper = mountComponent({ type: 'edit', editData: { ...baseEditData } })
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.formRef = {
      validate: (callback: (errors: unknown) => void) => hoisted.validateMock(callback)
    }

    setupState.handleReset({ preventDefault: vi.fn() })
    await flushPromises()

    expect(hoisted.messageError).toHaveBeenCalledWith('common.editFail')
  })
})

/**
 * 文件用途：告警配置页闭环证据包的导出动作（下载 JSON 证据包、复制证据文本）。
 * 核心逻辑：由页面注入证据包构建器与各类文案来源，本模块只负责浏览器下载流程与剪贴板反馈。
 * 关键注意事项：下载文件名与成功/失败提示文案必须与拆分前保持一致。
 */
import dayjs from 'dayjs'
import { $t } from '@/locales'
import { writeClipboardText } from '@/utils/clipboard'
import { buildAlarmClosureEvidenceFileName } from './alarm-configuration.helpers'

export type UseAlarmClosureEvidenceExportOptions = {
  /** 聚合当前页面上下文构建完整证据包 */
  buildBundle: () => Record<string, unknown>
  /** 证据包文件名的主键来源（详情行 id 或最近单条操作的告警 id） */
  resolvePrimaryAlarmId: () => unknown
  /** 详情弹窗内的闭环证据纯文本 */
  closurePacketText: () => string
  /** 最近一次批量操作的证据复制文本（无证据时返回 undefined） */
  batchCopyText: () => string | undefined
}

export function useAlarmClosureEvidenceExport(options: UseAlarmClosureEvidenceExportOptions) {
  const downloadAlarmClosureEvidenceBundle = () => {
    try {
      const bundle = options.buildBundle() as Record<string, unknown> & { generatedAt: string }
      const blob = new Blob([JSON.stringify(bundle, null, 2)], { type: 'application/json;charset=utf-8' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = buildAlarmClosureEvidenceFileName({
        id: options.resolvePrimaryAlarmId() as string,
        generatedAt: bundle.generatedAt,
        formatTimestamp: value => dayjs(value).format('YYYYMMDD-HHmmss')
      })
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      window.$message?.success($t('custom.alarmPage.evidenceBundleDownloaded'))
    } catch {
      window.$message?.warning($t('custom.alarmPage.evidenceBundleDownloadFailed'))
    }
  }

  const copyAlarmClosureEvidence = async () => {
    const copied = await writeClipboardText(options.closurePacketText())
    if (copied) {
      window.$message?.success($t('custom.alarmPage.closureEvidenceCopied'))
    } else {
      window.$message?.warning($t('custom.alarmPage.closureEvidenceCopyFailed'))
    }
  }

  const copyLastBatchActionEvidence = async () => {
    const copyText = options.batchCopyText()
    if (copyText === undefined) return
    const copied = await writeClipboardText(copyText)
    if (copied) {
      window.$message?.success($t('custom.alarmPage.batchActionEvidenceCopied'))
    } else {
      window.$message?.warning($t('custom.alarmPage.batchActionEvidenceCopyFailed'))
    }
  }

  return {
    downloadAlarmClosureEvidenceBundle,
    copyAlarmClosureEvidence,
    copyLastBatchActionEvidence
  }
}

/**
 * 文件用途：提供 告警消息管理 页面内的 alarm-configuration.helpers 子组件。
 * 核心逻辑：封装局部表单、弹窗、列表或展示模块，通过 props、emit 与父页面协作。
 * 关键注意事项：保持组件边界清晰，避免在子组件中绕过父页面的数据刷新与权限控制。
 * 重构建议：后续可把重复表单规则、选项转换和弹窗状态管理抽成可复用组合函数。
 */
export type AlarmTranslate = (key: string) => string

export type AlarmOption = {
  label: string
  value: string
}

export type AlarmResolutionTimelineItem = {
  key: string
  title: string
  description: string
  time: string
  type: 'default' | 'info' | 'warning' | 'success' | 'error'
}

export type AlarmClosureNextAction = {
  key: 'acknowledge' | 'maintenance' | 'reset' | 'closed'
  status: string
  nextStep: string
  evidence: string
  type: 'default' | 'info' | 'warning' | 'success' | 'error'
}

export type AlarmClosureEvidenceDevice = {
  id?: string
  name?: string
  device_number?: string
  device_name?: string
}

export type AlarmClosureEvidenceRow = {
  name?: string
  alarm_config_name?: string
  alarm_device_list?: AlarmClosureEvidenceDevice[]
  alarm_level?: string
  alarm_status?: string
  content?: string
  create_at?: string
  description?: string
  remark?: unknown
}

export type AlarmBatchActionEvidence = {
  action: string
  generatedAt: string
  expectedCount: number
  successCount: number
  failureCount: number
  note: string
  failedItems: string[]
  summary: string
  detail: string
  copyText: string
  type: 'success' | 'warning'
}

export function sanitizeAlarmEvidenceFileToken(value: unknown) {
  const token = String(value || '')
    .trim()
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80)

  return token || 'current-page'
}

export function buildAlarmEvidenceRow(options: {
  row: any
  severityOptions: AlarmOption[]
  t: AlarmTranslate
  formatTime: (value: unknown) => string
}) {
  const row = options.row || {}
  return {
    id: row.id || '',
    name: row.name || '',
    alarmConfigName: row.alarm_config_name || '',
    status: row.alarm_status || '',
    severity: alarmSeverityValue(row),
    severityLabel: alarmSeverityLabel(alarmSeverityValue(row), options.severityOptions),
    alarmType: alarmTypeLabel(row, options.t),
    content: row.content || '',
    description: row.description || '',
    createdAt: options.formatTime(row.create_at),
    acknowledged: isAcknowledged(row),
    acknowledgedBy: alarmActionField(row, 'acknowledged_by'),
    acknowledgedAt: alarmActionField(row, 'acknowledged_at'),
    reset: isReset(row),
    resetBy: alarmActionField(row, 'reset_by'),
    resetAt: alarmActionField(row, 'reset_at'),
    devices: (Array.isArray(row.alarm_device_list) ? row.alarm_device_list : []).slice(0, 12).map((device: any) => ({
      id: device?.id || device?.device_id || device?.deviceId || '',
      number: device?.device_number || '',
      name: device?.name || device?.device_name || ''
    }))
  }
}

export function buildAlarmClosureEvidenceBundle(options: {
  tableData: any[]
  queryData: any
  pagination: { page?: number; pageSize?: number; itemCount?: number }
  selectedRowKeys: Array<string | number>
  infoData: any
  detailClosureNextAction: unknown
  detailTimelineItems: unknown[]
  alarmClosureEvidencePacket: unknown
  lastSingleClosureEvidence: unknown
  lastBatchActionEvidence: unknown
  focusedDeviceId: string
  hasRouteDeviceContext: boolean
  fleetDeviceCount: number
  currentFleetPageCount: number
  requestedFleetTotal: number
  boundary: string
  severityOptions: AlarmOption[]
  t: AlarmTranslate
  formatTime: (value: unknown) => string
}) {
  const generatedAt = new Date().toISOString()
  const selectedRowKeys = options.selectedRowKeys.map(key => String(key))
  const selectedRowKeySet = new Set(selectedRowKeys)
  const selectedLoadedRows = options.tableData.filter(row => selectedRowKeySet.has(String(row.id)))
  const evidenceRow = (row: any) =>
    buildAlarmEvidenceRow({
      row,
      severityOptions: options.severityOptions,
      t: options.t,
      formatTime: options.formatTime
    })

  return {
    schema: 'aetherlink.alarm.closure-evidence-bundle.v1',
    generatedAt,
    boundary: options.boundary,
    pageContext: {
      scope: options.t('custom.alarmPage.evidenceBundleCurrentPageScope'),
      filters: {
        alarmStatus: options.queryData.alarm_status || '',
        alarmType: options.queryData.alarm_type || '',
        focusedDeviceId: options.focusedDeviceId || '',
        startTime: options.queryData.start_time || '',
        endTime: options.queryData.end_time || ''
      },
      pagination: {
        page: options.pagination.page,
        pageSize: options.pagination.pageSize,
        totalRowsReportedByApi: options.pagination.itemCount || 0,
        loadedRowCount: options.tableData.length
      },
      routeContext: {
        hasDeviceContext: options.hasRouteDeviceContext,
        fleetDeviceCount: options.fleetDeviceCount,
        currentFleetPageCount: options.currentFleetPageCount,
        requestedFleetTotal: options.requestedFleetTotal
      },
      selection: {
        selectedRowKeys,
        selectedLoadedRowCount: selectedLoadedRows.length,
        selectedLoadedRows: selectedLoadedRows.map(evidenceRow)
      }
    },
    loadedPageEvidence: options.tableData.map(evidenceRow),
    currentSingleClosureEvidence: options.infoData?.id
      ? {
          row: evidenceRow(options.infoData),
          nextAction: options.detailClosureNextAction,
          timeline: options.detailTimelineItems,
          copyPacket: options.alarmClosureEvidencePacket
        }
      : null,
    latestSingleActionEvidence: options.lastSingleClosureEvidence,
    latestBatchActionEvidence: options.lastBatchActionEvidence,
    verificationBoundary: {
      platformEvidenceOnly: true,
      fieldRecoveryNotProven: true,
      message: options.boundary
    }
  }
}

export function buildAlarmClosureEvidenceFileName(options: {
  id: unknown
  generatedAt: string
  formatTimestamp: (value: string) => string
}) {
  const fileToken = sanitizeAlarmEvidenceFileToken(options.id)
  return `aetherlink-alarm-closure-evidence-${fileToken}-${options.formatTimestamp(options.generatedAt)}.json`
}

export function parseAlarmRemark(raw: unknown) {
  if (!raw) return {} as Record<string, unknown>
  if (typeof raw === 'object') return raw as Record<string, unknown>
  if (typeof raw !== 'string') return {} as Record<string, unknown>
  try {
    const parsed = JSON.parse(raw)
    return parsed && typeof parsed === 'object' ? (parsed as Record<string, unknown>) : {}
  } catch {
    return {} as Record<string, unknown>
  }
}

export function alarmActionField(row: { remark?: unknown }, key: string) {
  const remark = parseAlarmRemark(row.remark)
  const value = remark[key]
  return value === undefined || value === null || value === '' ? '-' : String(value)
}

export function isAcknowledged(row: { remark?: unknown }) {
  return parseAlarmRemark(row.remark).acknowledged === true
}

export function isReset(row: { alarm_status?: string }) {
  return row.alarm_status === 'N'
}

export function buildAlarmResolutionTimeline(
  row: {
    alarm_status?: string
    content?: string
    create_at?: string
    description?: string
    remark?: unknown
  },
  t: AlarmTranslate,
  formatTime: (value: unknown) => string
): AlarmResolutionTimelineItem[] {
  const acknowledged = isAcknowledged(row)
  const reset = isReset(row)
  const acknowledgedBy = alarmActionField(row, 'acknowledged_by')
  const resetBy = alarmActionField(row, 'reset_by')
  const maintenanceNote = row.description || ''

  return [
    {
      key: 'created',
      title: t('custom.alarmPage.timelineCreatedTitle'),
      description: row.content || t('custom.alarmPage.timelineCreatedDesc'),
      time: formatTime(row.create_at),
      type: 'error'
    },
    {
      key: 'acknowledged',
      title: acknowledged
        ? t('custom.alarmPage.timelineAcknowledgedTitle')
        : t('custom.alarmPage.timelineAcknowledgePendingTitle'),
      description: acknowledged
        ? t('custom.alarmPage.timelineAcknowledgedDesc').replace('{operator}', acknowledgedBy)
        : t('custom.alarmPage.timelineAcknowledgePendingDesc'),
      time: acknowledged ? alarmActionField(row, 'acknowledged_at') : '-',
      type: acknowledged ? 'success' : 'warning'
    },
    {
      key: 'reset',
      title: reset ? t('custom.alarmPage.timelineResetTitle') : t('custom.alarmPage.timelineResetPendingTitle'),
      description: reset
        ? t('custom.alarmPage.timelineResetDesc').replace('{operator}', resetBy)
        : t('custom.alarmPage.timelineResetPendingDesc'),
      time: reset ? alarmActionField(row, 'reset_at') : '-',
      type: reset ? 'success' : 'info'
    },
    {
      key: 'maintenance',
      title: t('custom.alarmPage.timelineMaintenanceTitle'),
      description: maintenanceNote || t('custom.alarmPage.timelineMaintenanceEmpty'),
      time: maintenanceNote ? t('custom.alarmPage.timelineMaintenanceRecorded') : '-',
      type: maintenanceNote ? 'info' : 'default'
    }
  ]
}

export function buildAlarmClosureNextAction(
  row: {
    alarm_status?: string
    create_at?: string
    description?: string
    remark?: unknown
  },
  t: AlarmTranslate,
  formatTime: (value: unknown) => string
): AlarmClosureNextAction {
  const acknowledged = isAcknowledged(row)
  const reset = isReset(row)
  const hasMaintenanceNote = Boolean(row.description?.trim())

  if (!acknowledged) {
    return {
      key: 'acknowledge',
      status: t('custom.alarmPage.closureNeedsAcknowledgeStatus'),
      nextStep: t('custom.alarmPage.closureNeedsAcknowledgeNext'),
      evidence: t('custom.alarmPage.closureCreatedEvidence').replace('{time}', formatTime(row.create_at)),
      type: 'warning'
    }
  }

  if (!hasMaintenanceNote && !reset) {
    return {
      key: 'maintenance',
      status: t('custom.alarmPage.closureNeedsMaintenanceStatus'),
      nextStep: t('custom.alarmPage.closureNeedsMaintenanceNext'),
      evidence: t('custom.alarmPage.closureAcknowledgedEvidence')
        .replace('{operator}', alarmActionField(row, 'acknowledged_by'))
        .replace('{time}', alarmActionField(row, 'acknowledged_at')),
      type: 'info'
    }
  }

  if (!reset) {
    return {
      key: 'reset',
      status: t('custom.alarmPage.closureNeedsResetStatus'),
      nextStep: t('custom.alarmPage.closureNeedsResetNext'),
      // The no-maintenance/no-reset case returns above, so reaching this
      // branch guarantees a maintenance note is present.
      evidence: t('custom.alarmPage.closureMaintenanceEvidence'),
      type: 'error'
    }
  }

  return {
    key: 'closed',
