          action_param_type: 'telemetry',
          action_param: 'temperature',
          action_value: '{"temperature":25}'
        },
        {
          action_type: '10',
          action_param_type: 'command',
          action_param: 'reboot',
          action_value: '{"method":"reboot","params":{"delay":1}}'
        },
        {
          action_type: '11',
          action_param_type: 'c_command',
          action_value: '{"raw":true}'
        },
        {
          action_type: '30',
