}

const JSON_ACTION_PARAM_TYPES = new Set(['command', 'c_attribute', 'c_telemetry', 'c_command'])
const HIDE_SUB_SELECT_PARAM_TYPES = new Set(['c_attribute', 'c_telemetry', 'c_command'])

const shouldShowSubSelect = (paramType: string) => !HIDE_SUB_SELECT_PARAM_TYPES.has(paramType)

const normalizeMetricMenu = (items: MetricMenuItem[]) =>
  items.map(item => ({
    ...item,
    value: item.data_source_type,
    label: `${item.data_source_type}${item.label ? `(${item.label})` : ''}`,
    options: item.options.map(subItem => ({
      ...subItem,
      value: subItem.key,
      label: `${subItem.key}${subItem.label ? `(${subItem.label})` : ''}`
    }))
  }))

const selectCurrentParamType = (instructItem: InstructActionItem) => {
  if (!instructItem.action_param_type) return

  instructItem.actionParamOptions =
    (instructItem.actionParamOptionsData as MetricMenuItem[]).find(
      item => item.data_source_type === instructItem.action_param_type
    )?.options || []
  instructItem.showSubSelect = shouldShowSubSelect(instructItem.action_param_type as string)
}

const selectCurrentParam = (instructItem: InstructActionItem) => {
  if (!instructItem.action_param || instructItem.actionParamOptions!.length <= 0) return

  const currentParam =
    (instructItem.actionParamOptions as MetricMenuSubItem[]).find(
      item => item.key === instructItem.action_param
    ) || null
  instructItem.actionParamData = currentParam
  if (currentParam?.data_type) {
    currentParam.data_type = currentParam.data_type?.toLowerCase()
  }
}

export const useLinkageActionParamState = (message: { error: (content: string) => void }) => {
  const actionParamShow = async (instructItem: InstructActionItem) => {
    if (!instructItem.action_target) return

    let res: { data?: unknown } | null = null
    if (instructItem.action_type === '10') {
      res = await deviceMetricsMenu({ device_id: instructItem.action_target })
    } else if (instructItem.action_type === '11') {
      res = await deviceConfigMetricsMenu({
        device_config_id: instructItem.action_target
      })
    }

    // Echoed forms may already carry a parameter catalog while the optional
    // refresh endpoint returns an empty list (offline/device-specific plugins).
    // Keep that usable state instead of replacing it with an empty selection.
    if (
      !res?.data ||
      (Array.isArray(res.data) && res.data.length === 0 && instructItem.actionParamOptions?.length)
    ) {
      selectCurrentParam(instructItem)
      return
    }

    const metricMenu = normalizeMetricMenu(res.data as MetricMenuItem[])
    instructItem.actionParamOptionsData = metricMenu
    instructItem.actionParamTypeOptions = metricMenu.map(item => ({
      label: item.label,
      value: item.value
    }))
    selectCurrentParamType(instructItem)
    selectCurrentParam(instructItem)
  }

  const actionParamTypeChange = (instructItem: InstructActionItem, data: string) => {
    instructItem.action_param = null
    instructItem.actionParamData = null
    instructItem.actionParamOptions =
      (instructItem.actionParamOptionsData as MetricMenuItem[]).find(item => item.data_source_type === data)
        ?.options || []
    instructItem.placeholder = placeholderMap[data]
    instructItem.actionValue = null
    instructItem.showSubSelect = shouldShowSubSelect(instructItem.action_param_type as string)
  }

  const actionParamChange = (instructItem: InstructActionItem, data: unknown) => {
    instructItem.actionValue = null
    const currentParam =
      (instructItem.actionParamOptions as MetricMenuSubItem[]).find(item => item.key === data) || null
    instructItem.actionParamData = currentParam
    if (currentParam?.data_type) {
      currentParam.data_type = currentParam.data_type?.toLowerCase()
    }
  }

  const actionValueChange = (instructItem: InstructActionItem) => {
    if (!JSON_ACTION_PARAM_TYPES.has(instructItem.action_param_type as string)) return

    try {
      JSON.parse(instructItem.actionValue as string)
      if (typeof JSON.parse(instructItem.actionValue as string) === 'object') {
        instructItem.inputFeedback = ''
        instructItem.inputValidationStatus = undefined
      } else {
        message.error($t('common.enterJson'))
        instructItem.inputValidationStatus = 'error'
      }
    } catch (e) {
      message.error($t('common.enterJson'))
      instructItem.inputValidationStatus = 'error'
    }
  }

  return {
    actionParamShow,
    actionParamTypeChange,
    actionParamChange,
    actionValueChange
  }
}

import { ref } from 'vue'
import { deviceGroupTree } from '@/service/api'
import { warningMessageList } from '@/service/api/alarm'
import { deviceConfigAll, deviceListAll, sceneGet } from '@/service/api/automation'

const pushUniqueLoader = (
  loaders: Array<Promise<void> | void>,
  loaderKeys: Set<string>,
  key: string,
  loader: () => Promise<void> | void
) => {
  if (loaderKeys.has(key)) return
  loaderKeys.add(key)
  loaders.push(loader())
}

export const useLinkageActionTargetOptions = () => {
  const loadingSelect = ref(false)
  const groupLoaded = ref(false)
  const deviceLoaded = ref(false)
  const deviceConfigLoaded = ref(false)
  const sceneLoaded = ref(false)
  const alarmLoaded = ref(false)
  let groupLoadPromise: Promise<void> | null = null
  let deviceLoadPromise: Promise<void> | null = null
  let deviceConfigLoadPromise: Promise<void> | null = null
  let sceneLoadPromise: Promise<void> | null = null
  let alarmLoadPromise: Promise<void> | null = null

  const deviceGroupOptions = ref<any[]>([])
  const getGroup = async () => {
    deviceGroupOptions.value = []
    const res = await deviceGroupTree({})
    res.data?.forEach(item => {
      deviceGroupOptions.value.push(item.group)
    })
    groupLoaded.value = true
  }

  const deviceOptions = ref<any[]>([])
  const queryDevice = ref({
    group_id: null,
    device_name: null,
    bind_config: 0
  })

  const getDevice = async (groupId: any, name: any) => {
    queryDevice.value.group_id = groupId || null
    queryDevice.value.device_name = name || null
    if (!groupLoaded.value) {
      await ensureGroupsLoaded()
    }
    const res = await deviceListAll(queryDevice.value)
    deviceOptions.value = res.data
    deviceLoaded.value = true
  }

  const deviceConfigOption = ref<any[]>([])
  const queryDeviceConfig = ref({
    device_config_name: ''
  })

  const getDeviceConfig = async (name: any) => {
    queryDeviceConfig.value.device_config_name = name || ''
    const res = await deviceConfigAll(queryDeviceConfig.value)
    deviceConfigOption.value = res.data || []
    deviceConfigLoaded.value = true
  }

  const sceneList = ref<any[]>([])
  const queryScene = ref({
    page: 1,
    page_size: 10,
    name: ''
  })

  const getSceneList = async (name: string) => {
    queryScene.value.name = name || ''
    loadingSelect.value = true
    try {
      const res = await sceneGet(queryScene.value)
      sceneList.value = res.data.list
      sceneLoaded.value = true
    } finally {
      loadingSelect.value = false
    }
  }

  const alarmList = ref<any[]>([])
  const queryAlarm = ref({
    page: 1,
    page_size: 10,
    name: ''
  })

  const getAlarmList = async (name: string) => {
    queryAlarm.value.name = name || ''
    loadingSelect.value = true
    try {
      const res = await warningMessageList(queryAlarm.value)
      alarmList.value = res.data.list
      alarmLoaded.value = true
    } finally {
      loadingSelect.value = false
    }
  }

  const ensureGroupsLoaded = () => {
    if (groupLoaded.value) return Promise.resolve()
    if (!groupLoadPromise) {
      groupLoadPromise = getGroup().finally(() => {
        groupLoadPromise = null
      })
    }
    return groupLoadPromise
  }
  const ensureDevicesLoaded = () => {
    if (deviceLoaded.value) return Promise.resolve()
    if (!deviceLoadPromise) {
      deviceLoadPromise = getDevice(null, null).finally(() => {
        deviceLoadPromise = null
      })
    }
    return deviceLoadPromise
  }
  const ensureDeviceConfigsLoaded = () => {
    if (deviceConfigLoaded.value) return Promise.resolve()
    if (!deviceConfigLoadPromise) {
      deviceConfigLoadPromise = getDeviceConfig('').finally(() => {
        deviceConfigLoadPromise = null
      })
    }
    return deviceConfigLoadPromise
  }
  const ensureScenesLoaded = () => {
    if (sceneLoaded.value) return Promise.resolve()
    if (!sceneLoadPromise) {
      sceneLoadPromise = getSceneList('').finally(() => {
        sceneLoadPromise = null
      })
    }
    return sceneLoadPromise
  }
  const ensureAlarmsLoaded = () => {
    if (alarmLoaded.value) return Promise.resolve()
    if (!alarmLoadPromise) {
      alarmLoadPromise = getAlarmList('').finally(() => {
        alarmLoadPromise = null
      })
    }
    return alarmLoadPromise
  }

  const hydrateActionTargetCatalogsForEcho = async (actionData: any) => {
    if (!Array.isArray(actionData)) return
    const loaders: Array<Promise<void> | void> = []
    const loaderKeys = new Set<string>()

    actionData.forEach((actionGroup: any) => {
      if (actionGroup.actionType === '1' && Array.isArray(actionGroup.actionInstructList)) {
        actionGroup.actionInstructList.forEach((instructItem: any) => {
          if (instructItem.action_type === '10') {
            pushUniqueLoader(loaders, loaderKeys, 'devices', ensureDevicesLoaded)
          }
          if (instructItem.action_type === '11') {
            pushUniqueLoader(loaders, loaderKeys, 'device-configs', ensureDeviceConfigsLoaded)
          }
        })
      }
      if (actionGroup.actionType === '20') {
        pushUniqueLoader(loaders, loaderKeys, 'scenes', ensureScenesLoaded)
      }
      if (actionGroup.actionType === '30') {
        pushUniqueLoader(loaders, loaderKeys, 'alarms', ensureAlarmsLoaded)
      }
    })

    await Promise.all(loaders)
  }

  return {
    loadingSelect,
    deviceGroupOptions,
    getGroup,
    ensureGroupsLoaded,
    deviceOptions,
    queryDevice,
    getDevice,
    ensureDevicesLoaded,
    deviceConfigOption,
    getDeviceConfig,
    ensureDeviceConfigsLoaded,
    sceneList,
    getSceneList,
    ensureScenesLoaded,
    alarmList,
    getAlarmList,
    ensureAlarmsLoaded,
    hydrateActionTargetCatalogsForEcho
  }
}

/**
 * 设备条件来源状态 helper。
 * - 负责单设备 / 单类设备的来源切换、设备分组与配置查询、输入聚焦和下拉交互状态。
 * - 这里只维护设备来源相关状态；触发参数 option 仍由 trigger-param 相关 helper 协调。
 */
import { computed, onBeforeUpdate, ref } from 'vue'

/** 触发条件行（编辑器表单数据，字段宽松） */
type PremiseIfItemLike = {
  trigger_source?: unknown
  trigger_conditions_type?: unknown
  group_id?: unknown
  device_name?: unknown
  [key: string]: unknown
}

/** 设备分组树响应行（后端返回，仅读取 group 字段） */
type DeviceGroupTreeRow = { group?: unknown }

type TriggerSelectionResetter = (ifItem: PremiseIfItemLike) => void

type CreatePremiseDeviceConditionStateOptions = {
  t: (key: string) => string
  resetTriggerSelection: TriggerSelectionResetter
  deviceGroupTreeRequest: (params: Record<string, unknown>) => Promise<{ data?: DeviceGroupTreeRow[] | null }>
  deviceListRequest: (params: Record<string, unknown>) => Promise<{ data?: unknown[] | null }>
  deviceConfigRequest: (params: Record<string, unknown>) => Promise<{ data?: unknown[] | null }>
  emitConditionChose: (value: unknown) => void
}

export const createPremiseDeviceConditionState = ({
  t,
  resetTriggerSelection,
  deviceGroupTreeRequest,
  deviceListRequest,
  deviceConfigRequest,
  emitConditionChose
}: CreatePremiseDeviceConditionStateOptions) => {
  const deviceConditionOptions = computed(() => [
    {
      label: t('common.singleDevice'),
      value: '10'
    },
    {
      label: t('common.singleClassDevice'),
      value: '11'
    }
  ])

  const deviceConfigDisabled = ref(false)

  const triggerConditionsTypeChange = (ifItem: PremiseIfItemLike, data: unknown) => {
    ifItem.trigger_source = null
    resetTriggerSelection(ifItem)
    deviceConfigDisabled.value = data === '11'
    emitConditionChose(data)
  }

  const deviceGroupOptions = ref<any[]>([])
  const groupLoaded = ref(false)
  const deviceLoaded = ref(false)
  const deviceConfigLoaded = ref(false)
  let groupLoadPromise: Promise<void> | null = null
  let deviceLoadPromise: Promise<void> | null = null
  let deviceConfigLoadPromise: Promise<void> | null = null

  const getGroup = async () => {
    deviceGroupOptions.value = []
    const res = await deviceGroupTreeRequest({})
    res.data?.forEach(item => {
      deviceGroupOptions.value.push(item.group)
    })
    groupLoaded.value = true
  }

  const deviceOptions = ref<any[]>([])
  const queryDevice = ref({
    group_id: null as string | null,
    device_name: null as string | null,
    bind_config: 0
  })
  const btnloading = ref(false)

  const selectInstRef = ref<Record<number, boolean>>({})
  const onKeydownEnter = (e: Event) => {
    e.preventDefault()
    return false
  }

  const onDeviceKeydownEnter = (e: Event, ifIndex: number) => {
    selectInstRef.value[ifIndex] = true
    e.preventDefault()
    return false
  }

  const getDevice = async (groupId: any, name: any) => {
    queryDevice.value.group_id = groupId || null
    queryDevice.value.device_name = name || null
    btnloading.value = false
    deviceOptions.value = []
    if (!groupLoaded.value) {
      await ensureGroupsLoaded()
    }
    const res = await deviceListRequest(queryDevice.value)
    btnloading.value = true
    deviceOptions.value = res.data || []
    deviceLoaded.value = true
  }

  const triggerSourceChange = (ifItem: PremiseIfItemLike, ifIndex: number) => {
    resetTriggerSelection(ifItem)
    selectInstRef.value[ifIndex] = false
  }

  const queryDeviceName = ref<Record<number, any>>({})

  onBeforeUpdate(() => {
    queryDeviceName.value = {}
  })

  const setQueryDeviceNameRef = (el: any, index: number) => {
    if (el) {
      queryDeviceName.value[index] = el
    }
  }

  const handleFocus = (ifIndex: number) => {
    if (queryDeviceName.value[ifIndex]) {
      queryDeviceName.value[ifIndex].focus()
    } else {
      console.error(`Missing queryDeviceName ref for index ${ifIndex}`)
    }
  }

  const onTapInput = (item: PremiseIfItemLike, ifIndex: number) => {
    if (item.group_id || item.device_name) {
      getDevice(item.group_id, item.device_name)
    } else {
      selectInstRef.value[ifIndex] = true
    }
  }

  const deviceConfigOption = ref<any[]>([])
  const queryDeviceConfig = ref({
    device_config_name: ''
  })

  const getDeviceConfig = async (name: string) => {
    queryDeviceConfig.value.device_config_name = name || ''
    const res = await deviceConfigRequest(queryDeviceConfig.value)
    deviceConfigOption.value = res.data || []
    deviceConfigLoaded.value = true
  }

  const ensureGroupsLoaded = () => {
    if (groupLoaded.value) return Promise.resolve()
    if (!groupLoadPromise) {
      groupLoadPromise = getGroup().finally(() => {
        groupLoadPromise = null
      })
    }
    return groupLoadPromise
  }

  const ensureDevicesLoaded = () => {
    if (deviceLoaded.value) return Promise.resolve()
    if (!deviceLoadPromise) {
      deviceLoadPromise = getDevice(null, null).finally(() => {
        deviceLoadPromise = null
      })
    }
    return deviceLoadPromise
  }

  const ensureDeviceConfigsLoaded = () => {
    if (deviceConfigLoaded.value) return Promise.resolve()
    if (!deviceConfigLoadPromise) {
      deviceConfigLoadPromise = getDeviceConfig('').finally(() => {
        deviceConfigLoadPromise = null
      })
    }
    return deviceConfigLoadPromise
  }

  return {
    btnloading,
    deviceConditionOptions,
    deviceConfigDisabled,
    deviceConfigOption,
    deviceGroupOptions,
    deviceOptions,
    ensureDeviceConfigsLoaded,
    ensureDevicesLoaded,
    ensureGroupsLoaded,
    getDevice,
    getDeviceConfig,
    getGroup,
    handleFocus,
    onDeviceKeydownEnter,
    onKeydownEnter,
    onTapInput,
    queryDevice,
    queryDeviceConfig,
    selectInstRef,
    setQueryDeviceNameRef,
    triggerConditionsTypeChange,
    triggerSourceChange
  }
}

type NormalizeIfItem = (ifItem: any) => void

type LoadTriggerParamOptions = (ifItem: any) => void | Promise<void>

type InitialConditionProps = {
  deviceId?: string
  deviceConfigId?: string
}

type RefreshableIfGroup = any[] | { ifItems?: any[] }

export const cloneConditionGroups = (conditionData: any[]) => JSON.parse(JSON.stringify(conditionData))

export const prepareEchoedIfGroups = (conditionData: any, normalizeIfItemForEcho: NormalizeIfItem) => {
  if (!conditionData || !Array.isArray(conditionData)) {
    return null
  }

  const ifGroups = cloneConditionGroups(conditionData)
  ifGroups.forEach((ifGroup) => {
    if (Array.isArray(ifGroup)) {
      ifGroup.forEach(normalizeIfItemForEcho)
    }
  })

  return ifGroups
}

export const hydrateEchoedIfGroupsOptions = (
  ifGroups: any[] = [],
  loadTriggerParamOptions: LoadTriggerParamOptions
) => {
  ifGroups.forEach((ifGroup) => {
    if (Array.isArray(ifGroup)) {
      ifGroup.forEach((ifItem) => {
        loadTriggerParamOptions(ifItem)
      })
    }
  })
}

export const createInitialConditionFromProps = (
  judgeItemTemplate: any,
  { deviceId, deviceConfigId }: InitialConditionProps
) => {
  const judgeItemData = JSON.parse(JSON.stringify(judgeItemTemplate))
  let deviceConfigDisabled = false

  if (deviceId) {
    judgeItemData.ifType = '1'
    judgeItemData.trigger_conditions_type = '10'
    judgeItemData.trigger_source = deviceId
  } else if (deviceConfigId) {
    judgeItemData.ifType = '1'
    judgeItemData.trigger_conditions_type = '11'
    judgeItemData.trigger_source = deviceConfigId
    deviceConfigDisabled = true
  }

  return {
    judgeItemData,
    deviceConfigDisabled
  }
}

const getIfItemsForUiRefresh = (ifGroup: RefreshableIfGroup) =>
  Array.isArray(ifGroup) ? ifGroup : ifGroup.ifItems || []

const updateStatusOptionLabel = (ifItem: any, statusOption: any) => {
  if (ifItem.triggerParamOptions && Array.isArray(ifItem.triggerParamOptions)) {
    const statusIndex = ifItem.triggerParamOptions.findIndex((opt: any) => opt.value === 'status')
    if (statusIndex !== -1) {
      ifItem.triggerParamOptions[statusIndex] = statusOption
    }
  }
}

export const refreshStatusOptionsForLocale = (ifGroups: RefreshableIfGroup[] = [], statusOption: any) => {
  ifGroups.forEach((ifGroup) => {
    const ifItems = getIfItemsForUiRefresh(ifGroup)
    ifItems.forEach((ifItem) => {
      updateStatusOptionLabel(ifItem, statusOption)
    })
  })
}

/**
 * 文件说明：
 * - 承接联动前提中“事件参数条件行”的轻量状态 helper。
 * - 负责参数选项读取、操作符列表切换，以及条件行的增删与值类型联动。
 * 维护提示：
 * - 这里只处理事件参数条件的局部状态，不应重新吸收父组件的设备来源、生命周期或整表单编排逻辑。
 */
import {
  createEventParamCondition,
  createEventParamUiState,
  parseEventParamOptions
} from './premise-trigger-param-state'
import { $t } from '@/locales'

type OperatorOption = {
  label: string
  value: string
}

type Translator = (key: string) => string

const eventParamExistsOperator = (t: Translator) => ({
  label: t('custom.automation.eventParam.existsOperator'),
  value: 'exists'
})

export const buildEventExistsOptions = (t: Translator = $t) => [
  {
    label: t('custom.automation.eventParam.exists'),
    value: true
  },
  {
    label: t('custom.automation.eventParam.notExists'),
    value: false
  }
]

export const getEventParamOptions = (ifItem: any) => {
  if (ifItem.eventParamOptions?.length) {
    return ifItem.eventParamOptions
  }
  return parseEventParamOptions(ifItem.eventParamsRaw)
}

export const resolveSelectedEventParams = (options: any[], triggerParam: string | null) => {
  if (!triggerParam) {
    return null
  }

  const eventGroup = options.find((item: any) => item.value === 'event')
  const selectedEvent = eventGroup?.options?.find((item: any) => item.key === triggerParam)
  return selectedEvent?.params || null
}

export const syncSelectedEventParams = (ifItem: any) => {
  const params = resolveSelectedEventParams(ifItem.triggerParamOptions || [], ifItem.trigger_param)
  if (!params && ifItem.eventParamsRaw) {
    return
  }

  Object.assign(
    ifItem,
    createEventParamUiState(
      ifItem.trigger_param_type,
      params,
      Array.isArray(ifItem.eventParamConditions) ? ifItem.eventParamConditions : []
    )
  )
}

export const getEventParamType = (ifItem: any, field: string) => {
  const option = getEventParamOptions(ifItem).find((item: any) => item.value === field)
  return String(option?.dataType || 'String').toLowerCase()
}

export const getEventOperatorOptions = (
  ifItem: any,
  condition: any,
  determineOptions: OperatorOption[],
  t: Translator = $t
) => {
  const dataType = getEventParamType(ifItem, condition.field)
  if (dataType === 'number') {
    return [...determineOptions, eventParamExistsOperator(t)]
  }
  if (dataType === 'boolean') {
    return determineOptions
      .filter((item) => item.value === '=' || item.value === '!=')
      .concat(eventParamExistsOperator(t))
  }
  return determineOptions
    .filter((item) => item.value === '=' || item.value === '!=' || item.value === 'in')
    .concat(eventParamExistsOperator(t))
}

export const addEventParamCondition = (ifItem: any) => {
  if (!Array.isArray(ifItem.eventParamConditions)) {
    ifItem.eventParamConditions = []
  }
  ifItem.eventParamConditions.push(createEventParamCondition())
}

export const deleteEventParamCondition = (ifItem: any, conditionIndex: number) => {
  ifItem.eventParamConditions.splice(conditionIndex, 1)
}

export const eventConditionOperatorChange = (condition: any) => {
  condition.value = condition.operator === 'exists' ? true : null
  condition.minValue = null
  condition.maxValue = null
}

