﻿import {
  createSelectedTriggerParamState,
  isTriggerParamPathSelected,
  type TriggerParamSelectionState
} from './premise-trigger-param-state'
import { prepareEchoedIfGroups } from './premise-edit-premise-state'
import {
  loadTriggerParamOptionsForIfItem,
  type TriggerParamOptionsLoadDeps
} from './premise-trigger-param-options'

type LoadTriggerParamOptionsDeps = Pick<
  TriggerParamOptionsLoadDeps,
  'deviceMetricsConditionMenu' | 'configMetricsConditionMenu' | 'statusOption' | 'syncSelectedEventParams'
> & {
  onError?: (error: unknown) => void
}

/** 触发条件行（编辑器表单数据，字段宽松） */
type TriggerIfItemLike = Record<string, unknown>

type NormalizeIfItemForEcho = (ifItem: TriggerIfItemLike) => void

type InitialConditionResult = {
  judgeItemData: Record<string, unknown>
  deviceConfigDisabled: boolean
}

export const loadPremiseTriggerParamOptions = async (ifItem: TriggerIfItemLike, deps: LoadTriggerParamOptionsDeps) => {
  await loadTriggerParamOptionsForIfItem(ifItem, deps)
}

export const handleTriggerParamOptionsShow = async (
  ifItem: TriggerIfItemLike,
  visible: boolean,
  loadTriggerParamOptions: (ifItem: TriggerIfItemLike) => Promise<void>
) => {
  if (visible) {
    await loadTriggerParamOptions(ifItem)
  }
}

export const applyTriggerParamSelectionChange = (
  ifItem: TriggerIfItemLike,
  data: unknown,
  commitSelection: (ifItem: TriggerIfItemLike, selectionState?: TriggerParamSelectionState) => void
) => {
  if (!isTriggerParamPathSelected(data)) {
    commitSelection(ifItem)
    return
  }

  commitSelection(ifItem, createSelectedTriggerParamState(data as unknown[]))
}

export const applyEchoedConditionData = (
  conditionData: unknown,
  normalizeIfItemForEcho: NormalizeIfItemForEcho,
  loadTriggerParamOptions: (ifItem: TriggerIfItemLike) => void | Promise<void>
) => {
  const ifGroups = prepareEchoedIfGroups(conditionData, normalizeIfItemForEcho)
  if (!ifGroups) {
    return null
  }

  ifGroups.forEach((ifGroup) => {
    if (Array.isArray(ifGroup)) {
      ifGroup.forEach((ifItem) => {
        loadTriggerParamOptions(ifItem)
      })
    }
  })

  return ifGroups
}

export const buildInitialPremiseCondition = (
  judgeItemTemplate: Record<string, unknown>,
  props: {
    deviceId?: string
    deviceConfigId?: string
  },
  createInitialConditionFromProps: (
    judgeItemTemplate: Record<string, unknown>,
    props: { deviceId?: string; deviceConfigId?: string }
  ) => InitialConditionResult
) => {
  return createInitialConditionFromProps(judgeItemTemplate, props)
}

export const applyInitialPremiseCondition = (options: {
  hasConfigId: boolean
  buildInitialCondition: () => InitialConditionResult
  addIfGroupItem: (data: Record<string, unknown>) => void
  emitConditionChose: (data: unknown) => void
  setDeviceConfigDisabled: (value: boolean) => void
}) => {
  if (options.hasConfigId) return

  const { judgeItemData, deviceConfigDisabled } = options.buildInitialCondition()
  options.setDeviceConfigDisabled(deviceConfigDisabled)
  options.emitConditionChose(judgeItemData.trigger_conditions_type)
  options.addIfGroupItem(judgeItemData)
}

﻿/** 触发条件行（编辑器表单数据，字段宽松） */
type TriggerIfItemLike = Record<string, unknown>

/** 条件指标菜单项（后端返回，字段宽松） */
type TriggerParamMenuItem = {
  data_source_type?: unknown
  label?: unknown
  key?: unknown
  options?: unknown[] | null
  [key: string]: unknown
}

export type TriggerParamOptionItem = Record<string, unknown>

/** 条件指标菜单接口（后端返回 data 列表） */
export type MetricMenuFetcher = (
  payload: Record<string, unknown>
) => Promise<{ data?: TriggerParamMenuItem[] | null } | null | undefined>

export type TriggerParamOptionsLoadDeps = {
  deviceMetricsConditionMenu: MetricMenuFetcher
  configMetricsConditionMenu: MetricMenuFetcher
  statusOption: TriggerParamOptionItem | null
  syncSelectedEventParams: (ifItem: TriggerIfItemLike) => void
  onError?: (error: unknown) => void
}

export const formatTriggerParamOptions = (items: TriggerParamMenuItem[] = []): TriggerParamOptionItem[] => {
  return items.map(item => ({
    ...item,
    value: item.data_source_type,
    label: `${item.data_source_type}${item.label ? `(${item.label})` : ''}`,
    options: ((item.options as TriggerParamMenuItem[] | null) || []).map(subItem => ({
      ...subItem,
      value: `${item.data_source_type}/${subItem.key}`,
      label: `${subItem.key}${subItem.label ? `(${subItem.label})` : ''}`
    }))
  }))
}

export const buildTriggerParamOptions = (
  items: TriggerParamMenuItem[] = [],
  statusOption: TriggerParamOptionItem | null
): Array<TriggerParamOptionItem | null> => {
  const options: Array<TriggerParamOptionItem | null> = formatTriggerParamOptions(items)
  if (!options.some(option => option?.value === 'status')) {
    options.push(statusOption)
  }
  return options
}

export const canLoadTriggerParamOptions = (ifItem: TriggerIfItemLike) => {
  return ifItem.trigger_source && (ifItem.trigger_conditions_type === '10' || ifItem.trigger_conditions_type === '11')
}

export const hasTriggerParamOptions = (ifItem: TriggerIfItemLike) => {
  return Array.isArray(ifItem.triggerParamOptions) && ifItem.triggerParamOptions.length > 0
}

export const fetchTriggerParamOptions = async (
  ifItem: TriggerIfItemLike,
  {
    deviceMetricsConditionMenu,
    configMetricsConditionMenu
  }: Pick<TriggerParamOptionsLoadDeps, 'deviceMetricsConditionMenu' | 'configMetricsConditionMenu'>
) => {
  if (ifItem.trigger_conditions_type === '10') {
    return deviceMetricsConditionMenu({
      device_id: ifItem.trigger_source
    })
  }

  if (ifItem.trigger_conditions_type === '11') {
    return configMetricsConditionMenu({
      device_config_id: ifItem.trigger_source
    })
  }

  return null
}

export const setTriggerParamOptions = (
  ifItem: TriggerIfItemLike,
  items: TriggerParamMenuItem[] = [],
  statusOption: TriggerParamOptionItem | null
) => {
  ifItem.triggerParamOptions = buildTriggerParamOptions(items, statusOption)
}

export const clearTriggerParamOptions = (ifItem: TriggerIfItemLike) => {
  ifItem.triggerParamOptions = []
}

export const resolveTriggerParamOptionItems = async (
  ifItem: TriggerIfItemLike,
  deps: Pick<TriggerParamOptionsLoadDeps, 'deviceMetricsConditionMenu' | 'configMetricsConditionMenu'>
) => {
  const res = await fetchTriggerParamOptions(ifItem, deps)
  return res?.data || []
}

export const loadTriggerParamOptionsForIfItem = async (ifItem: TriggerIfItemLike, deps: TriggerParamOptionsLoadDeps) => {
  if (!canLoadTriggerParamOptions(ifItem)) {
    return
  }

  if (hasTriggerParamOptions(ifItem)) {
    deps.syncSelectedEventParams(ifItem)
    return
  }

  clearTriggerParamOptions(ifItem)
  try {
    const items = await resolveTriggerParamOptionItems(ifItem, deps)
    setTriggerParamOptions(ifItem, items, deps.statusOption)
  } catch (error) {
    deps.onError?.(error)
    clearTriggerParamOptions(ifItem)
  } finally {
    deps.syncSelectedEventParams(ifItem)
  }
}

/**
 * 文件说明：
 * - 抽离联动条件编辑里“触发参数选择”的纯状态逻辑。
 * - 负责 event 参数条件的初始化、回显归一化、路径键生成与 JSON 值校验。
 * - 这里不直接依赖 Vue，目的是让 edit-premise.vue 只保留视图装配职责。
 */
export type EventParamCondition = {
  field: string | null
  operator: string
  value: unknown
  minValue: unknown
  maxValue: unknown
}

export type TriggerParamSelectionState = {
  triggerParamType?: string | null
  triggerParam?: string | null
  params?: unknown
  eventParamConditions?: EventParamCondition[]
}

export const createTriggerParamKey = (triggerParamType: string | null, triggerParam: string | null) => {
  return triggerParamType && triggerParam ? `${triggerParamType}/${triggerParam}` : null
}

export const createEventParamCondition = (): EventParamCondition => ({
  field: null,
  operator: '=',
  value: null,
  minValue: null,
  maxValue: null
})

export const parseEventParamOptions = (params: unknown) => {
  if (!params) {
    return []
  }

  try {
    // 事件参数来源既可能是字符串化 JSON，也可能已经是数组对象，这里统一兜底。
    const list = typeof params === 'string' ? JSON.parse(params) : params
    if (!Array.isArray(list)) {
      return []
    }

    return list.map((item: any) => ({
      label: `${item.data_identifier}${item.data_name ? `(${item.data_name})` : ''}`,
      value: item.data_identifier,
      dataType: item.read_write_flag || item.param_type || item.data_type || 'String'
    }))
  } catch {
    return []
  }
}

export const createEventParamUiState = (
  triggerParamType: string | null,
  params: unknown,
  eventParamConditions: EventParamCondition[] = []
) => {
  if (triggerParamType !== 'event') {
    return {
      eventParamsRaw: null,
      eventParamOptions: [],
      eventParamConditions: []
    }
  }

  return {
    eventParamsRaw: params || null,
    eventParamOptions: parseEventParamOptions(params),
    eventParamConditions
  }
}

export const applyTriggerParamSelectionState = (
  ifItem: Record<string, any>,
  {
    triggerParamType = null,
    triggerParam = null,
    params = null,
    eventParamConditions = []
  }: TriggerParamSelectionState,
  options: {
    resetComparatorState?: boolean
  } = {}
) => {
  const { resetComparatorState = false } = options

  ifItem.trigger_param_type = triggerParamType
  ifItem.trigger_param = triggerParam
  ifItem.trigger_param_key = createTriggerParamKey(triggerParamType, triggerParam)

  if (resetComparatorState) {
    // 切换触发参数后，旧比较符与旧输入值通常不再成立，需要一起清空。
    ifItem.trigger_operator = null
    ifItem.trigger_value = null
    ifItem.minValue = null
    ifItem.maxValue = null
  }

  Object.assign(ifItem, createEventParamUiState(triggerParamType, params, eventParamConditions))
}

export const isTriggerParamPathSelected = (data: unknown) => {
  return Array.isArray(data) && data.length >= 2
}

export const createSelectedTriggerParamState = (data: any[]) => {
  const triggerParamType = data[0].value
  return {
    triggerParamType,
    triggerParam: data[1].key,
    params: data[1].params || null,
    eventParamConditions: triggerParamType === 'event' ? [createEventParamCondition()] : []
  }
}

export const commitSelectedTriggerParam = (ifItem: Record<string, any>, selectionState: TriggerParamSelectionState = {}) => {
  applyTriggerParamSelectionState(ifItem, selectionState, { resetComparatorState: true })
}

export const normalizeEventConditionUiState = (ifItem: Record<string, any>) => {
  Object.assign(
    ifItem,
    createEventParamUiState(
      ifItem.trigger_param_type,
      ifItem.eventParamsRaw,
      Array.isArray(ifItem.eventParamConditions) ? ifItem.eventParamConditions : []
    )
  )
}

export const normalizeTriggerParamRule = (ifItem: Record<string, any>) => {
  ifItem.trigger_param_key =
    ifItem.trigger_conditions_type === '10' || ifItem.trigger_conditions_type === '11'
      ? createTriggerParamKey(ifItem.trigger_param_type, ifItem.trigger_param)
      : null
}

export const ensureTriggerParamOptionsState = (ifItem: Record<string, any>) => {
  if (!Array.isArray(ifItem.triggerParamOptions)) {
    ifItem.triggerParamOptions = []
  }
}

export const normalizeIfItemForEcho = (ifItem: Record<string, any>) => {
  // 编辑回显时补齐运行期 UI 字段，避免老数据直接渲染时报空。
  ensureTriggerParamOptionsState(ifItem)
  normalizeEventConditionUiState(ifItem)
  normalizeTriggerParamRule(ifItem)
}

export const validateEventTriggerJsonValue = (value: unknown) => {
  try {
    const parsedValue = JSON.parse(String(value))
    return !!parsedValue && typeof parsedValue === 'object'
  } catch {
    return false
  }
}

import { computed, nextTick, type ComputedRef, type Ref } from 'vue'
import {
  AUTOMATION_DRY_RUN_QUICK_FIX_KEYS,
  buildFirstAutomationDryRunQuickFixActions,
  buildGeneralAutomationDryRunQuickFixActions,
  createAlarmActionSlot
} from './automationDryRunQuickFixActions'
import type { AutomationDryRunQuickFixAction } from './automationDryRunPreview'
import { buildSubmitActions, buildSubmitConditionGroups } from './automationSubmitPayload'

type Translate = (key: string) => string

type AutomationDraftComponentRef = Ref<any>

export function useAutomationDryRunQuickFixes(options: {
  isFirstDeviceAutomationStarter: ComputedRef<boolean>
  previewConditionGroups: ComputedRef<any[]>
  previewActions: ComputedRef<any[]>
  conditionData: Ref<any[]>
  actionData: Ref<any[]>
  editPremise: AutomationDraftComponentRef
  editAction: AutomationDraftComponentRef
  applyFirstAutomationRecommendedAction: () => void
  openFirstAutomationAlarmCreator: () => void
  refreshLocalExecutionExplanation: () => unknown
  t: Translate
}) {
  const currentDraftConditionGroups = () => {
    if (options.editPremise.value?.ifGroupsData) {
      return buildSubmitConditionGroups(options.editPremise.value.ifGroupsData())
    }

    return buildSubmitConditionGroups(options.conditionData.value || [])
  }

  const currentDraftActions = () => {
    if (options.editAction.value?.actionGroupsReturn) {
      return buildSubmitActions(options.editAction.value.actionGroupsReturn())
    }

    return buildSubmitActions(options.actionData.value || [])
  }

  const firstAutomationDryRunQuickFixActions = computed<AutomationDryRunQuickFixAction[]>(() => {
    if (!options.isFirstDeviceAutomationStarter.value) return []

    const knownActions = options.previewActions.value.length > 0 ? options.previewActions.value : options.actionData.value
    return buildFirstAutomationDryRunQuickFixActions({
      actions: knownActions,
      texts: {
        applyActionTitle: options.t('custom.automation.firstRuleRecommendedActionTitle'),
        applyActionDesc: options.t('custom.automation.firstRuleDryRunQuickFixApplyActionDesc'),
        applyActionButton: options.t('custom.automation.firstRuleApplyRecommendedAction'),
        createAlarmTargetTitle: options.t('custom.automation.firstRuleCreateAlarmTarget'),
        createAlarmTargetDesc: options.t('custom.automation.firstRuleDryRunQuickFixCreateAlarmDesc'),
        createAlarmTargetButton: options.t('custom.automation.firstRuleCreateAlarmTarget')
      }
    })
  })

  const generalAutomationDryRunQuickFixActions = computed<AutomationDryRunQuickFixAction[]>(() => {
    if (options.isFirstDeviceAutomationStarter.value) return []

    const conditionGroups =
      options.previewConditionGroups.value.length > 0
        ? options.previewConditionGroups.value
        : currentDraftConditionGroups()
    const actions = options.previewActions.value.length > 0 ? options.previewActions.value : currentDraftActions()
    const conditionCount = conditionGroups.reduce((count: number, group: any[]) => count + group.length, 0)

    return buildGeneralAutomationDryRunQuickFixActions({
      conditionCount,
      actionCount: actions.length,
      actions,
      texts: {
        addConditionTitle: options.t('generate.automationDryRunQuickFixAddConditionTitle'),
        addConditionDesc: options.t('generate.automationDryRunQuickFixAddConditionDesc'),
        addConditionButton: options.t('generate.automationDryRunQuickFixAddConditionButton'),
        addAlarmActionTitle: options.t('generate.automationDryRunQuickFixAddAlarmActionTitle'),
        addAlarmActionDesc: options.t('generate.automationDryRunQuickFixAddAlarmActionDesc'),
        addAlarmActionButton: options.t('generate.automationDryRunQuickFixAddAlarmActionButton'),
        createAlarmTargetTitle: options.t('generate.automationDryRunQuickFixCreateAlarmTargetTitle'),
        createAlarmTargetDesc: options.t('generate.automationDryRunQuickFixCreateAlarmTargetDesc'),
        createAlarmTargetButton: options.t('generate.automationDryRunQuickFixCreateAlarmTargetButton')
      }
    })
  })

  const automationDryRunQuickFixActions = computed<AutomationDryRunQuickFixAction[]>(() =>
    options.isFirstDeviceAutomationStarter.value
      ? firstAutomationDryRunQuickFixActions.value
      : generalAutomationDryRunQuickFixActions.value
  )

  const refreshDryRunExplanationAfterQuickFix = () => {
    void nextTick(() => {
      options.refreshLocalExecutionExplanation()
    })
  }

  const addConditionGroupFromQuickFix = () => {
    if (options.editPremise.value?.addConditionGroup) {
      options.editPremise.value.addConditionGroup()
      window.$message?.success(options.t('generate.automationDryRunQuickFixConditionAdded'))
      refreshDryRunExplanationAfterQuickFix()
      return
    }

    options.conditionData.value = [...options.conditionData.value, [{ ifType: null }]]
    window.$message?.success(options.t('generate.automationDryRunQuickFixConditionAdded'))
    refreshDryRunExplanationAfterQuickFix()
  }

  const addAlarmActionSlotFromQuickFix = () => {
    if (options.editAction.value?.addAlarmActionSlot) {
      options.editAction.value.addAlarmActionSlot()
      window.$message?.success(options.t('generate.automationDryRunQuickFixAlarmActionAdded'))
      refreshDryRunExplanationAfterQuickFix()
      return
    }

    options.actionData.value = [...options.actionData.value, createAlarmActionSlot()]
    window.$message?.success(options.t('generate.automationDryRunQuickFixAlarmActionAdded'))
    refreshDryRunExplanationAfterQuickFix()
  }

  const handleAutomationDryRunQuickFix = (key: string) => {
    if (key === AUTOMATION_DRY_RUN_QUICK_FIX_KEYS.applyFirstAlarmAction) {
      options.applyFirstAutomationRecommendedAction()
      return
    }

    if (key === AUTOMATION_DRY_RUN_QUICK_FIX_KEYS.createFirstAlarmTarget) {
      options.openFirstAutomationAlarmCreator()
      return
    }

    if (key === AUTOMATION_DRY_RUN_QUICK_FIX_KEYS.addConditionGroup) {
      addConditionGroupFromQuickFix()
      return
    }

    if (key === AUTOMATION_DRY_RUN_QUICK_FIX_KEYS.addAlarmActionSlot) {
      addAlarmActionSlotFromQuickFix()
      return
    }

    if (key === AUTOMATION_DRY_RUN_QUICK_FIX_KEYS.createAlarmTarget) {
      options.openFirstAutomationAlarmCreator()
    }
  }

  return {
    automationDryRunQuickFixActions,
    handleAutomationDryRunQuickFix
  }
}

import { computed, ref } from 'vue'
import type { SceneAutomationDryRunPayload } from '@/service/api/automation'
import {
  buildAutomationDryRunBeginnerGuide,
  buildAutomationDryRunCustomerView,
  buildActionSummaryItems,
  buildAutomationOperatorPlan,
  buildBackendDryRunView,
  buildConditionSummaryItems,
  getAutomationDryRunAlertType,
  getAutomationDryRunStatusText,
  getPreviewErrorText,
  stringifyDryRunResponse,
  type BackendDryRunStatus
} from './automationDryRunPreview'

type ExecutionPreviewPayload = SceneAutomationDryRunPayload | (Partial<SceneAutomationDryRunPayload> & { actions: any[] })
type DryRunService = (payload: ExecutionPreviewPayload) => Promise<any>

export function useAutomationExecutionPreview(options: {
  buildPayload: () => ExecutionPreviewPayload
  dryRun: DryRunService
  getLocalBlocker?: (payload: ExecutionPreviewPayload) => string
}) {
  const executionPreview = ref<ExecutionPreviewPayload | null>(null)
  const backendDryRunStatus = ref<BackendDryRunStatus>('waiting')
  const backendDryRunResponse = ref<any>(null)
  const backendDryRunError = ref('')
  const isBackendDryRunLoading = ref(false)

  const previewConditionGroups = computed(() => executionPreview.value?.trigger_condition_groups || [])
  const previewActions = computed(() => executionPreview.value?.actions || [])
  const previewConditionCount = computed(() =>
    previewConditionGroups.value.reduce((count: number, group: any[]) => count + group.length, 0)
  )
  const previewActionCount = computed(() => previewActions.value.length)
  const localBlockingErrors = computed(() => {
    if (!executionPreview.value || !options.getLocalBlocker) return []
    const blocker = options.getLocalBlocker(executionPreview.value)

    return blocker ? [{ key: 'local-submit-blocker', text: blocker }] : []
  })
  const localPreviewStatusText = computed(() =>
    localBlockingErrors.value.length > 0
      ? 'Local explanation found a save blocker. Fix it before saving or running backend dry-run again.'
      : executionPreview.value
      ? 'Local explanation was generated from the current form. It is not a backend execution result.'
      : 'No local explanation yet. Refresh or save to generate one from the current form.'
  )
  const backendDryRunStatusText = computed(() => getAutomationDryRunStatusText(backendDryRunStatus.value))
  const backendDryRunAlertType = computed(() => getAutomationDryRunAlertType(backendDryRunStatus.value))
  const conditionSummaryItems = computed(() => buildConditionSummaryItems(previewConditionGroups.value))
  const actionSummaryItems = computed(() => buildActionSummaryItems(previewActions.value))
  const operatorPlan = computed(() =>
    buildAutomationOperatorPlan(
      executionPreview.value,
      backendDryRunStatus.value,
      backendDryRunResponse.value,
      backendDryRunError.value
    )
  )
  const backendDryRunView = computed(() => buildBackendDryRunView(backendDryRunResponse.value))
  const customerDryRunView = computed(() =>
    buildAutomationDryRunCustomerView(backendDryRunStatus.value, backendDryRunResponse.value, backendDryRunError.value)
  )
  const beginnerGuideCards = computed(() =>
    buildAutomationDryRunBeginnerGuide({
      status: backendDryRunStatus.value,
      response: backendDryRunResponse.value,
      backendError: backendDryRunError.value,
      customerView: customerDryRunView.value,
      localBlockingErrors: localBlockingErrors.value,
      conditionGroupCount: previewConditionGroups.value.length,
      conditionCount: previewConditionCount.value,
      actionCount: previewActionCount.value
    })
  )
  const dryRunResponseText = computed(() => stringifyDryRunResponse(backendDryRunResponse.value))

  const refreshLocalExecutionExplanation = () => {
    const payload = options.buildPayload()
    executionPreview.value = payload
    backendDryRunStatus.value = 'ready'
    backendDryRunResponse.value = null
    backendDryRunError.value = ''

    return payload
  }

  const runBackendDryRunForPayload = async (payload: ExecutionPreviewPayload) => {
    executionPreview.value = payload
    isBackendDryRunLoading.value = true
    backendDryRunStatus.value = 'pending'
    backendDryRunResponse.value = null
    backendDryRunError.value = ''

    try {
      const res = await options.dryRun(payload)
      if (!res || res?.error) {
        backendDryRunStatus.value = 'unavailable'
        backendDryRunError.value = getPreviewErrorText(res)
        return null
      }

      backendDryRunStatus.value = 'available'
      backendDryRunResponse.value = res?.data ?? res
      return backendDryRunResponse.value
    } catch (error: any) {
      backendDryRunStatus.value = 'unavailable'
      backendDryRunError.value = getPreviewErrorText(error)
      return null
    } finally {
      isBackendDryRunLoading.value = false
    }
  }

  const runBackendDryRun = async () => {
    const payload = refreshLocalExecutionExplanation()
    await runBackendDryRunForPayload(payload)
  }

  return {
    executionPreview,
    backendDryRunStatus,
    backendDryRunResponse,
    backendDryRunError,
    isBackendDryRunLoading,
    previewConditionGroups,
    previewActions,
    previewConditionCount,
    previewActionCount,
    localBlockingErrors,
    localPreviewStatusText,
    backendDryRunStatusText,
    backendDryRunAlertType,
    conditionSummaryItems,
    actionSummaryItems,
    operatorPlan,
    backendDryRunView,
    customerDryRunView,
    beginnerGuideCards,
    dryRunResponseText,
    refreshLocalExecutionExplanation,
    runBackendDryRunForPayload,
    runBackendDryRun
  }
}

import { ref } from 'vue'
import { runAutomationDryRunSaveGate } from './automationSaveFlow'

type DryRunService = (payload: any) => Promise<any>
type Translate = (key: string) => string

export function useAutomationSaveGate(options: {
  runBackendDryRunForPayload: DryRunService
  t: Translate
}) {
  const isSaveDryRunLoading = ref(false)

  const ensureBackendDryRunCanSave = async (payload: any) => {
    isSaveDryRunLoading.value = true
    try {
      const result = await runAutomationDryRunSaveGate({
        payload,
        runBackendDryRunForPayload: options.runBackendDryRunForPayload,
        backendUnavailableMessage: options.t('generate.automationDryRunBackendUnavailable'),
        saveBlockedMessage: options.t('generate.automationDryRunSaveBlocked')
      })
      if (!result.canSave) window.$message?.error(result.message)

      return result.canSave
    } finally {
      isSaveDryRunLoading.value = false
    }
  }

  return {
    ensureBackendDryRunCanSave,
    isSaveDryRunLoading
  }
}

