    trigger: 'change'
  },
  action_param_type: {
    required: true,
    message: $t('common.select'),
    trigger: 'change'
  },
  action_param: {
    required: true,
    message: $t('common.select'),
    trigger: 'change'
  },
  actionValue: {
    required: true,
    message: $t('common.select')
  }
})

// 激活场景/触发告警分支共用一个远程加载态，和设备动作目录的加载态分开维护。
const remoteSelectLoading = ref(false)

// 当前页面只开放“操作设备”动作；其余动作分支先保留模板兼容性，不在入口暴露。
const actionOptions = ref([
  {
    label: $t('common.operateDevice'),
    value: OPERATE_DEVICE_ACTION_TYPE,
    disabled: false
  }
])

// 提交阶段把表单中的 `actionValue` 转成接口要求的 `action_value`。
// 不同参数类型的序列化规则不同，这里是最关键的协议收口点之一。
const navigateToSceneManage = async () => {
  await tabStore.removeTab(route.path)
  router.replace({ path: '/automation/scene-manage' })
}

const resetActionOptionsDisabledState = () => {
  actionOptions.value.forEach((item) => {
    item.disabled = false
  })
}

const resetActionGroupSelection = (actionGroupItem: SceneActionGroup) => {
  actionGroupItem.actionInstructList = []
  actionGroupItem.action_type = null
  actionGroupItem.action_target = null
}

const syncActionOptionsForGroupChange = (actionType: string | null) => {
  resetActionOptionsDisabledState()

  if (actionType === OPERATE_DEVICE_ACTION_TYPE) {
    const operateDeviceOption = actionOptions.value.find((item) => item.value === OPERATE_DEVICE_ACTION_TYPE)
    if (operateDeviceOption) {
      operateDeviceOption.disabled = true
    }
  }
}

// 切换动作组类型时，先重置当前组，再按新类型补最小可编辑结构。
const actionChange = (actionGroupItem: SceneActionGroup, _actionGroupIndex: number, data: string | null) => {
  syncActionOptionsForGroupChange(data)
  resetActionGroupSelection(actionGroupItem)
  if (data === OPERATE_DEVICE_ACTION_TYPE) {
    actionGroupItem.actionInstructList = [createEmptySceneInstruction()]
  }
}

// 操作设备动作内部再区分“单个设备”和“单类设备”两条取数路径。
const actionTypeOptions = ref([
  {
    label: $t('common.singleDevice'),
    value: '10'
  },
  {
    label: $t('common.singleClassDevice'),
    value: '11'
  }
])
const {
  actionParamShow,
  actionTargetChange,
  actionTypeChange,
  deviceConfigOption,
  deviceGroupOptions,
  deviceOptions,
  ensureDeviceConfigOptionsLoaded,
  ensureDeviceGroupsLoaded,
  ensureDeviceOptionsLoaded,
  ensureDeviceTargetCatalogsLoaded,
  getDevice,
  getDeviceConfig,
  loadingSelect: actionTargetLoading,
  queryDevice
} = useSceneActionTargetCatalog()

// 激活场景/触发告警分支虽然暂未开放入口，但其远程选项加载逻辑仍需保留。
const sceneList = ref<SelectOption[]>([])
const queryScene = ref<NamePageQuery>({
  page: 1,
  page_size: 10,
  name: ''
})
const getSceneList = async (name: string) => {
  queryScene.value.name = name || ''
  remoteSelectLoading.value = true
  try {
    const res = await sceneGet(queryScene.value)
    sceneList.value = res.data?.list || []
  } finally {
    remoteSelectLoading.value = false
  }
}

const ensureSceneListLoaded = () => {
  if (sceneList.value.length > 0) return
  void getSceneList('')
}

const alarmList = ref<SelectOption[]>([])
const queryAlarm = ref<NamePageQuery>({
  page: 1,
  page_size: 10,
  name: ''
})

const getAlarmList = async (name: string) => {
  queryAlarm.value.name = name || ''
  remoteSelectLoading.value = true
  try {
    const res = await warningMessageList(queryAlarm.value)
    alarmList.value = res.data?.list || []
  } finally {
    remoteSelectLoading.value = false
  }
}

const ensureAlarmListLoaded = () => {
  if (alarmList.value.length > 0) return
  void getAlarmList('')
}

// 新增动作组前先触发表单校验，避免页面出现多组半成品配置。
const addActionGroupItem = async () => {
  if (configForm.value.actions.length !== 0) {
    await configFormRef.value?.validate()
  }
  configForm.value.actions.push(createEmptySceneActionGroup() as SceneActionGroup)
}

const deleteActionGroupItem = (actionGroupIndex: any) => {
  configForm.value.actions.splice(actionGroupIndex, 1)
}

const duplicateActionGroupItem = (actionGroupIndex: number) => {
  const duplicatedGroup = duplicateSceneActionGroup(configForm.value.actions[actionGroupIndex])
  configForm.value.actions.splice(actionGroupIndex + 1, 0, duplicatedGroup)
}

const tabStore = useTabStore()

// 提交前把页面维护的嵌套动作结构转回接口需要的扁平数组。
const buildSubmitPayload = () => {
  return buildSceneSubmitPayload(configForm.value as SceneConfigForm)
}

const buildSceneExecutionPreviewPayload = () => {
  return buildSceneActionDryRunPayload({
    form: configForm.value,
    buildSubmitPayload
  })
}

const {
  backendDryRunError,
  isBackendDryRunLoading,
  executionPreview,
  previewConditionGroups,
  previewActions,
  previewConditionCount,
  previewActionCount,
  localBlockingErrors,
  backendDryRunStatusText,
  backendDryRunAlertType,
  conditionSummaryItems,
  actionSummaryItems,
  operatorPlan,
  backendDryRunView,
  customerDryRunView,
  beginnerGuideCards,
  dryRunResponseText,
  refreshLocalExecutionExplanation,
  runBackendDryRunForPayload,
  runBackendDryRun
} = useAutomationExecutionPreview({
  buildPayload: buildSceneExecutionPreviewPayload,
  dryRun: sceneDryRun,
  getLocalBlocker: (payload) => getSceneActionLocalBlocker(payload, $t)
})

const sceneLocalPreviewStatusText = computed(() => {
  if (localBlockingErrors.value.length > 0) return $t('generate.sceneDryRunLocalHasBlocker')
  if (executionPreview.value) return $t('generate.sceneDryRunLocalReady')

  return $t('generate.sceneDryRunLocalEmpty')
})

const sceneDryRunQuickFixActions = computed<AutomationDryRunQuickFixAction[]>(() =>
  buildSceneDryRunQuickFixActions({
    actionGroups: configForm.value.actions,
    texts: {
      addActionGroupTitle: $t('generate.sceneDryRunQuickFixAddActionGroupTitle'),
      addActionGroupDesc: $t('generate.sceneDryRunQuickFixAddActionGroupDesc'),
      addActionGroupButton: $t('generate.sceneDryRunQuickFixAddActionGroupButton'),
      selectOperateDeviceTitle: $t('generate.sceneDryRunQuickFixSelectOperateDeviceTitle'),
      selectOperateDeviceDesc: $t('generate.sceneDryRunQuickFixSelectOperateDeviceDesc'),
      selectOperateDeviceButton: $t('generate.sceneDryRunQuickFixSelectOperateDeviceButton'),
      addDeviceInstructionTitle: $t('generate.sceneDryRunQuickFixAddDeviceInstructionTitle'),
      addDeviceInstructionDesc: $t('generate.sceneDryRunQuickFixAddDeviceInstructionDesc'),
      addDeviceInstructionButton: $t('generate.sceneDryRunQuickFixAddDeviceInstructionButton')
    }
  })
)

const refreshSceneDryRunExplanationAfterQuickFix = () => {
  void nextTick(() => {
    refreshLocalExecutionExplanation()
  })
}

const addSceneActionGroupFromQuickFix = () => {
  configForm.value.actions.push(createEmptySceneActionGroup() as SceneActionGroup)
  message.success($t('generate.sceneDryRunQuickFixAddActionGroupAdded'))
  refreshSceneDryRunExplanationAfterQuickFix()
}

const selectOperateDeviceFromQuickFix = () => {
  if (!configForm.value.actions[0]) {
    configForm.value.actions.push(createEmptySceneActionGroup() as SceneActionGroup)
  }

  const firstGroup = configForm.value.actions[0]
  firstGroup.actionType = OPERATE_DEVICE_ACTION_TYPE
  actionChange(firstGroup, 0, OPERATE_DEVICE_ACTION_TYPE)
  message.success($t('generate.sceneDryRunQuickFixSelectOperateDeviceApplied'))
  refreshSceneDryRunExplanationAfterQuickFix()
}

const addDeviceInstructionFromQuickFix = () => {
  const firstGroup = configForm.value.actions[0]
  if (!firstGroup) {
    addSceneActionGroupFromQuickFix()
    return
  }

  firstGroup.actionInstructList.push(createEmptySceneInstruction())
  message.success($t('generate.sceneDryRunQuickFixAddDeviceInstructionAdded'))
  refreshSceneDryRunExplanationAfterQuickFix()
}

const handleSceneDryRunQuickFix = (key: string) => {
  if (key === SCENE_DRY_RUN_QUICK_FIX_KEYS.addActionGroup) {
    addSceneActionGroupFromQuickFix()
    return
  }

  if (key === SCENE_DRY_RUN_QUICK_FIX_KEYS.selectOperateDevice) {
    selectOperateDeviceFromQuickFix()
    return
  }

  if (key === SCENE_DRY_RUN_QUICK_FIX_KEYS.addDeviceInstruction) {
    addDeviceInstructionFromQuickFix()
  }
}

const ensureSceneDryRunCanSave = async () => {
  const payload = buildSceneExecutionPreviewPayload()
  const localBlocker = getSceneActionLocalBlocker(payload, $t)
  if (localBlocker) {
    message.error(localBlocker)
    return false
  }

  isSaveDryRunLoading.value = true
  try {
    const result = await runAutomationDryRunSaveGate({
      payload,
      runBackendDryRunForPayload,
      backendUnavailableMessage: $t('generate.automationDryRunBackendUnavailable'),
      saveBlockedMessage: $t('generate.automationDryRunSaveBlocked')
    })
    if (!result.canSave) message.error(result.message)
    return result.canSave
  } finally {
    isSaveDryRunLoading.value = false
  }
}

// 新增与编辑共用同一套保存逻辑，只在接口入口上做分流。
const saveScene = async () => {
  const configFormData = buildSubmitPayload()
  const res = getCurrentSceneId() ? await sceneEdit(configFormData) : await sceneAdd(configFormData)

  if (!res.error) {
    await navigateToSceneManage()
  }
}

// 提交分两步: 先做前端校验，再弹确认框，最终由确认回调触发真正保存。
const submitData = async () => {
  await configFormRef.value?.validate()
  const jsonIssues = validateSceneActionJsonValues(configForm.value.actions, $t('common.enterJson'))
  if (jsonIssues.length > 0) {
    const firstIssue = jsonIssues[0]
    message.error(`${$t('common.enterJson')} #${firstIssue.actionGroupIndex + 1}.${firstIssue.instructIndex + 1}`)
    return
  }

  if (!(await ensureSceneDryRunCanSave())) {
    return
  }

  dialog.warning({
    title: $t('common.tip'),
    content: $t('common.saveSceneInfo'),
    positiveText: $t('device_template.confirm'),
    negativeText: $t('common.cancel'),
    onPositiveClick: saveScene
  })
}

// 编辑态只依赖 sceneId 拉详情，然后复用回显映射把接口数据还原回表单结构。
const getSceneInfo = async () => {
  const sceneId = getCurrentSceneId()
  if (!sceneId) {
    return
  }

  const res = await sceneInfo(sceneId)
  const info = res.data?.info || {}
  const actions = res.data?.actions || []
  configForm.value = { ...configForm.value, ...info, actions }
  dataEcho(actions)
}

// 场景详情回显的真正收口点，后续若拆纯函数，这里是最合适的落点。
const dataEcho = (actionsData: SceneInstruction[]) => {
  configForm.value.actions = formatSceneActionsForEdit<SceneActionGroup>(actionsData)
  configForm.value.actions
    .filter((actionGroup: SceneActionGroup) => actionGroup.actionType === OPERATE_DEVICE_ACTION_TYPE)
    .forEach((actionGroup: SceneActionGroup) => {
      actionGroup.actionInstructList.forEach((instructItem: SceneInstruction) => {
        if (instructItem.action_type === '10') {
          ensureDeviceTargetCatalogsLoaded()
        }
        if (instructItem.action_type === '11') {
          ensureDeviceConfigOptionsLoaded()
        }
        void actionParamShow(instructItem)
      })
    })
  configForm.value.actions.forEach((actionGroup: SceneActionGroup) => {
    if (actionGroup.actionType === '20') {
      ensureSceneListLoaded()
    }
    if (actionGroup.actionType === '30') {
      ensureAlarmListLoaded()
    }
  })
}

// 新增态默认插入一个空动作组，编辑态则先补 id 再拉详情。
const initializeSceneForm = () => {
  const sceneId = getCurrentSceneId()
  if (sceneId) {
    configForm.value.id = sceneId
    void getSceneInfo()
    return
  }

  void addActionGroupItem()
}

onMounted(() => {
  initializeSceneForm()
})
</script>

<template>
  <div class="scene-edit">
    <NCard :bordered="false" :title="`${configId ? $t('card.editScene') : $t('card.addScene')}`">
      <NForm
        ref="configFormRef"
        :model="configForm"
        :rules="configFormRules"
        label-placement="left"
        label-width="100"
        size="small"
      >
        <NFormItem :label="$t('generate.labelName')" path="name" class="w-150">
          <NInput v-model:value="configForm.name" :placeholder="$t('generate.enterSceneName')" />
        </NFormItem>
        <NFormItem :label="$t('generate.description')" path="description" class="w-150">
          <NInput
            v-model:value="configForm.description"
            type="textarea"
            :placeholder="$t('generate.enter-description')"
            rows="1"
          />
        </NFormItem>
        <NFormItem :label="$t('generate.action')" required class="w-100%" :show-feedback="false">
          <NFlex vertical class="mt-1 w-100%">
            <NFlex
              v-for="(actionGroupItem, actionGroupIndex) in configForm.actions"
              :key="actionGroupIndex"
              class="mt-1 w-100%"
            >
              <NFormItem
                :show-label="false"
                :show-feedback="false"
                :path="`actions[${actionGroupIndex}].actionType`"
                :rule="configFormRules.actionType"
                class="max-w-30 w-full"
              >
                <NSelect
                  v-model:value="actionGroupItem.actionType"
                  :options="actionOptions"
                  @update:value="(data) => actionChange(actionGroupItem, actionGroupIndex, data)"
                />
              </NFormItem>
              <template v-if="actionGroupItem.actionType === OPERATE_DEVICE_ACTION_TYPE">
                <SceneOperateDeviceActionGroupEditor
                  :action-group-item="actionGroupItem"
                  :action-group-index="actionGroupIndex"
                  :action-type-options="actionTypeOptions"
                  :config-form-rules="configFormRules"
                  :device-config-option="deviceConfigOption"
                  :device-group-options="deviceGroupOptions"
                  :device-options="deviceOptions"
                  :ensure-device-config-options-loaded="ensureDeviceConfigOptionsLoaded"
                  :ensure-device-groups-loaded="ensureDeviceGroupsLoaded"
                  :ensure-device-options-loaded="ensureDeviceOptionsLoaded"
                  :ensure-device-target-catalogs-loaded="ensureDeviceTargetCatalogsLoaded"
                  :get-device="getDevice"
                  :get-device-config="getDeviceConfig"
                  :loading-select="actionTargetLoading"
                  :query-device="queryDevice"
                  :action-target-change="actionTargetChange"
                  :action-type-change="actionTypeChange"
                  :create-instruction="createEmptySceneInstruction"
                />
              </template>
              <template v-if="actionGroupItem.actionType === '20'">
                <NFlex class="ml-6 w-auto" align="center">
                  <NFormItem
                    :label="$t('generate.activate')"
                    label-width="60px"
                    :show-feedback="false"
                    :path="`actions[${actionGroupIndex}].action_target`"
                    :rule="configFormRules.action_target"
                    class="w-full"
                  >
                    <NSelect
                      v-model:value="actionGroupItem.action_target"
                      :options="sceneList"
                      label-field="name"
                      value-field="id"
                      :placeholder="$t('common.select')"
                      :loading="remoteSelectLoading"
                      filterable
                      class="max-w-50"
                      remote
                      @search="getSceneList"
                      @update:show="(show) => show && ensureSceneListLoaded()"
                    />
                  </NFormItem>
                </NFlex>
              </template>
              <template v-if="actionGroupItem.actionType === '30'">
                <NFlex class="ml-6 w-auto">
                  <NFormItem
                    :label="$t('generate.trigger')"
                    label-width="60px"
                    :show-feedback="false"
                    :path="`actions[${actionGroupIndex}].action_target`"
                    :rule="configFormRules.action_target"
                  >
                    <NSelect
                      v-model:value="actionGroupItem.action_target"
                      :options="alarmList"
                      label-field="name"
                      value-field="id"
                      :placeholder="$t('common.select')"
                      class="max-w-50"
                      filterable
                      remote
                      :loading="remoteSelectLoading"
                      @search="getAlarmList"
                      @update:show="(show) => show && ensureAlarmListLoaded()"
                    />
                  </NFormItem>
                  <NButton class="w-20" dashed type="info" @click="popUpVisible = true">
                    {{ $t('generate.create-alarm') }}
                  </NButton>
                </NFlex>
              </template>
              <NButton type="default" @click="duplicateActionGroupItem(actionGroupIndex)">
                {{ $t('generate.copy') }}
              </NButton>
              <NButton v-if="actionGroupIndex > 0" type="error" @click="deleteActionGroupItem(actionGroupIndex)">
                {{ $t('generate.delete-execution-action') }}
              </NButton>
            </NFlex>
            <NButton type="primary" class="w-30" @click="addActionGroupItem()">
              {{ $t('generate.add-execution-action') }}
            </NButton>
          </NFlex>
        </NFormItem>
      </NForm>
      <LinkageActionExecutionSummary
        :action-groups="configForm.actions"
        :device-options="deviceOptions"
        :device-config-options="deviceConfigOption"
        :scene-options="sceneList"
        :alarm-options="alarmList"
      />
      <AutomationDryRunPreview
        :local-status-text="sceneLocalPreviewStatusText"
        :backend-status-text="backendDryRunStatusText"
        :backend-alert-type="backendDryRunAlertType"
        :backend-error="backendDryRunError"
        :condition-group-count="previewConditionGroups.length"
        :condition-count="previewConditionCount"
        :action-count="previewActionCount"
        :condition-summary-items="conditionSummaryItems"
        :action-summary-items="actionSummaryItems"
        :operator-plan="operatorPlan"
        :backend-dry-run-view="backendDryRunView"
        :customer-dry-run-view="customerDryRunView"
        :beginner-guide-cards="beginnerGuideCards"
        :quick-fix-actions="sceneDryRunQuickFixActions"
        :local-blocking-errors="localBlockingErrors"
        :dry-run-response-text="dryRunResponseText"
        :is-backend-dry-run-loading="isBackendDryRunLoading"
        :scene-action-only="true"
        @refresh="refreshLocalExecutionExplanation"
        @run-backend-dry-run="runBackendDryRun"
        @quick-fix="handleSceneDryRunQuickFix"
      />
      <n-divider class="divider-class" />
      <NFlex justify="center" class="mb-5">
        <NButton type="primary" :loading="isSaveDryRunLoading" @click="submitData">
          {{ $t('generate.save-scene-configuration') }}
        </NButton>
      </NFlex>
    </NCard>
    <PopUp v-model:visible="popUpVisible" type="add" :edit-data="null" @new-edit="handleAlarmCreated" />
  </div>
</template>

<style scoped>
:deep(.n-card__content) {
  padding: 10px 10px 4px 10px !important;
}
</style>

/**
 * 文件说明：
 * - 承载场景动作编辑表单的轻量状态辅助函数。
 * - 主要解决动作参数下拉、占位文案、联动清空与 JSON 输入校验。
 * - 与 mapper 文件配合使用：这里更偏 UI 状态，mapper 更偏提交/回显结构转换。
 */
import {
  ACTION_PARAM_TYPES_WITH_JSON_VALIDATION,
  ACTION_PARAM_TYPES_WITH_INLINE_JSON,
  OPERATE_DEVICE_ACTION_TYPE,
  type ActionParamOption,
  type ActionParamOptionGroup,
  type ActionParamTypeOption,
  type SceneActionGroupLike,
  type SceneInstructionLike
} from './scene-action-mappers'

export const ACTION_PARAM_PLACEHOLDERS: Record<string, string> = {
  telemetry: '20',
  attributes: 'on-line',
  command: '{"param1":1}',
  c_telemetry: '{"switch":1,"switch1":0}',
  c_attribute: '{"addr":1,"port":0}',
  c_command: '{"method":"switch1","params":{"false":0}}'
}

export const shouldHideActionParamSubSelect = (actionParamType: string | null | undefined) => {
  return ACTION_PARAM_TYPES_WITH_INLINE_JSON.has(actionParamType as string)
}

export const normalizeActionParamDataType = (actionParamData: ActionParamOption | null) => {
  if (actionParamData?.data_type) {
    // 表单组件通常按小写类型分支，这里统一一次，避免各处重复判断。
    actionParamData.data_type = actionParamData.data_type.toLowerCase()
  }

  return actionParamData
}

export const normalizeActionParamOptionsData = (source: ActionParamOptionGroup[] = []): ActionParamOptionGroup[] => {
  return source.map(item => ({
    ...item,
    value: item.data_source_type,
    label: `${item.label ? `(${item.label})` : ''}${item.data_source_type}`,
    options: (item.options || []).map((subItem: ActionParamOption) => ({
      ...subItem,
      value: subItem.key,
      label: `${subItem.key}${subItem.label ? `(${subItem.label})` : ''}`
    }))
  }))
}

export const buildActionParamTypeOptions = (actionParamOptionsData: ActionParamOptionGroup[] = []): ActionParamTypeOption[] => {
  return actionParamOptionsData.map(item => ({
    label: item.label || item.data_source_type,
    value: item.value || item.data_source_type
  }))
}

export const getActionParamOptionsByType = (
  instructItem: SceneInstructionLike,
  actionParamType = instructItem.action_param_type
) => {
  return (
    instructItem.actionParamOptionsData.find(item => item.data_source_type === actionParamType)?.options || []
  )
}

export const resetInstructionSelection = (instructItem: SceneInstructionLike) => {
  instructItem.action_target = null
  instructItem.action_param_type = null
  instructItem.action_param = null
  instructItem.action_param_key = null
  instructItem.action_value = null
}

export const resetInstructionTargetDependentState = (instructItem: SceneInstructionLike) => {
  // 切换动作目标后，下游参数来源、选项和输入值都必须一起失效。
  instructItem.action_param_type = null
  instructItem.action_param = null
  instructItem.actionValue = null
  instructItem.actionParamOptionsData = []
  instructItem.actionParamTypeOptions = []
  instructItem.actionParamOptions = []
}

export const updateInstructActionParamState = (instructItem: SceneInstructionLike) => {
  if (instructItem.action_param_type) {
    // 某些参数类型直接填写 JSON，不需要再展示二级字段选择框。
    instructItem.actionParamOptions = getActionParamOptionsByType(instructItem)
    instructItem.showSubSelect = !shouldHideActionParamSubSelect(instructItem.action_param_type)
  }

  if (instructItem.action_param && instructItem.actionParamOptions.length > 0) {
    instructItem.actionParamData = normalizeActionParamDataType(
      instructItem.actionParamOptions.find(item => item.key === instructItem.action_param) || null
    )
  }
}

export const applyActionParamOptionsData = (
  instructItem: SceneInstructionLike,
  actionParamOptionsData: ActionParamOptionGroup[]
) => {
  instructItem.actionParamOptionsData = actionParamOptionsData
  instructItem.actionParamTypeOptions = buildActionParamTypeOptions(actionParamOptionsData)
  updateInstructActionParamState(instructItem)
}

export const applyActionParamTypeChange = (instructItem: SceneInstructionLike, data: string) => {
  instructItem.action_param = null
  instructItem.actionParamData = null
  instructItem.actionParamOptions = getActionParamOptionsByType(instructItem, data)
  instructItem.placeholder = ACTION_PARAM_PLACEHOLDERS[data]
  instructItem.actionValue = null
  instructItem.showSubSelect = !shouldHideActionParamSubSelect(data)
}

export const applyActionParamSelection = (instructItem: SceneInstructionLike, data: string) => {
  instructItem.actionValue = null
  instructItem.actionParamData = normalizeActionParamDataType(
    instructItem.actionParamOptions.find(item => item.key === data) || null
  )
}

export const validateJsonActionValue = (actionParamType: string | null | undefined, actionValue: unknown) => {
  if (!actionParamType || !ACTION_PARAM_TYPES_WITH_INLINE_JSON.has(actionParamType) && actionParamType !== 'command') {
    return true
  }

  try {
    // 这里只做“是否为合法 JSON 对象”校验，字段语义仍由后端或更高层约束。
    const parsed = JSON.parse(String(actionValue))
    return typeof parsed === 'object' && parsed !== null
  } catch {
    return false
  }
}

export type SceneActionValueValidationIssue = {
  actionGroupIndex: number
  instructIndex: number
  actionParamType: string
  message: string
  instructItem: SceneInstructionLike
}

export const clearActionValueValidationState = (instructItem: SceneInstructionLike) => {
  instructItem.inputFeedback = ''
  instructItem.inputValidationStatus = undefined
}

export const markInvalidJsonActionValue = (
  instructItem: SceneInstructionLike,
  message = 'common.enterJson'
) => {
  instructItem.inputFeedback = message
  instructItem.inputValidationStatus = 'error'
}

export const validateSceneActionJsonValues = (
  actionGroups: SceneActionGroupLike[] = [],
  message = 'common.enterJson'
): SceneActionValueValidationIssue[] => {
  const issues: SceneActionValueValidationIssue[] = []

  actionGroups.forEach((actionGroup, actionGroupIndex) => {
    if (actionGroup.actionType !== OPERATE_DEVICE_ACTION_TYPE) return

    actionGroup.actionInstructList.forEach((instructItem, instructIndex) => {
      const actionParamType = instructItem.action_param_type
      if (!actionParamType || !ACTION_PARAM_TYPES_WITH_JSON_VALIDATION.has(actionParamType)) return

      if (validateJsonActionValue(actionParamType, instructItem.actionValue)) {
        clearActionValueValidationState(instructItem)
        return
      }

      markInvalidJsonActionValue(instructItem, message)
      issues.push({
        actionGroupIndex,
        instructIndex,
        actionParamType,
        message,
        instructItem
      })
    })
  })

  return issues
}

/**
 * 文件说明：
 * - 场景动作编辑的结构映射层，负责“表单分组态 <-> 接口 actions 扁平态”双向转换。
 * - 同时沉淀动作参数类型常量，避免页面与子模块散落硬编码。
 * - 这里的提交映射与回显映射需要长期保持对称，是联调与回归的高风险点。
 */
export const OPERATE_DEVICE_ACTION_TYPE = '1'
export const SINGLE_DEVICE_ACTION_TARGET_TYPE = '10'
export const SINGLE_CLASS_DEVICE_ACTION_TARGET_TYPE = '11'

export const ACTION_PARAM_TYPES_WITH_INLINE_JSON = new Set(['c_attribute', 'c_telemetry', 'c_command'])
export const ACTION_PARAM_TYPES_WITH_JSON_VALIDATION = new Set(['command', 'c_attribute', 'c_telemetry', 'c_command'])
export const ACTION_PARAM_TYPES_WITH_KEY_VALUE_PAYLOAD = new Set(['telemetry', 'attributes'])
const RESERVED_ACTION_PARAM_KEYS = new Set(['__proto__', 'prototype', 'constructor'])

export interface ActionParamOption {
  key: string
  value?: string
  label?: string
  data_type?: string | null
  [key: string]: any
}

export interface ActionParamOptionGroup {
  data_source_type: string
  label?: string
  value?: string
  options: ActionParamOption[]
  [key: string]: any
}

export interface ActionParamTypeOption {
  label: string
  value: string
}

export interface SceneInstructionLike {
  action_target: string | null
  action_type: string | null
  action_param_type: string | null
  action_param: string | null
  action_param_key?: string | null
  action_value?: any
  actionValue?: any
  deviceGroupId?: string | null
  actionParamOptions: ActionParamOption[]
  actionParamOptionsData: ActionParamOptionGroup[]
  actionParamTypeOptions: ActionParamTypeOption[]
  actionParamData?: ActionParamOption | null
  showSubSelect?: boolean
  placeholder?: string
  inputFeedback?: string
  inputValidationStatus?: string
  [key: string]: any
}

export interface SceneActionGroupLike {
  actionType: string | null
  action_type?: string | null
  action_target?: string | null
  actionInstructList: SceneInstructionLike[]
  [key: string]: any
}

export const isOperateDeviceInstructionAction = (actionType: any) => {
  return actionType === SINGLE_DEVICE_ACTION_TARGET_TYPE || actionType === SINGLE_CLASS_DEVICE_ACTION_TARGET_TYPE
}

const tryParseActionValueObject = (actionValue: any) => {
  if (typeof actionValue !== 'string') {
    return null
  }
  try {
    const parsed = JSON.parse(actionValue)
    return typeof parsed === 'object' && parsed !== null ? parsed : null
  } catch {
    return null
  }
}

const normalizeActionParamKey = (value: unknown) => {
  const key = typeof value === 'string' ? value.trim() : ''
  if (!key || RESERVED_ACTION_PARAM_KEYS.has(key) || key.length > 128) return null
  return key
}

export const buildActionValuePayload = (instructItem: SceneInstructionLike) => {
  if (ACTION_PARAM_TYPES_WITH_INLINE_JSON.has(instructItem.action_param_type as string)) {
    // c_* 类型约定直接透传 JSON 字符串，不再重复包装。
    return instructItem.actionValue
  }

  if (ACTION_PARAM_TYPES_WITH_KEY_VALUE_PAYLOAD.has(instructItem.action_param_type as string)) {
    const key = normalizeActionParamKey(instructItem.action_param)
    if (!key) return instructItem.action_value
    // Keep the key validation above, but serialize the one-entry JSON object
    // directly instead of assigning a remote value to an object property.
    // JSON.stringify quotes the key and escapes control characters for us.
    const serializedValue = JSON.stringify(instructItem.actionValue)
    return serializedValue === undefined
      ? '{}'
      : `{${JSON.stringify(key)}:${serializedValue}}`
  }

  if (instructItem.action_param_type === 'command') {
    // command 需要保留 method 与 params，两层结构由后端设备指令逻辑消费。
    return JSON.stringify({
      method: instructItem.action_param,
      params: JSON.stringify(JSON.parse(instructItem.actionValue))
    })
  }

  return instructItem.action_value
}

export const formatActionGroupForSubmit = (actionGroupItem: SceneActionGroupLike): any[] => {
  if (actionGroupItem.actionType === OPERATE_DEVICE_ACTION_TYPE) {
    // “操作设备”在 UI 中是一个动作组，但接口层需要拆成多条 action 记录。
    return actionGroupItem.actionInstructList.map((instructItem: SceneInstructionLike) => ({
      ...instructItem,
      action_value: buildActionValuePayload(instructItem)
    }))
  }

  return [
    {
      ...actionGroupItem,
      action_type: actionGroupItem.actionType
    }
  ]
}

export const buildActionsPayload = (actionGroups: SceneActionGroupLike[]) => {
  return actionGroups.flatMap(formatActionGroupForSubmit)
}

export const parseActionValueForEcho = (item: SceneInstructionLike) => {
  if (ACTION_PARAM_TYPES_WITH_INLINE_JSON.has(item.action_param_type as string)) {
    return item.action_value
  }

  const parsed = tryParseActionValueObject(item.action_value)

  if (ACTION_PARAM_TYPES_WITH_KEY_VALUE_PAYLOAD.has(item.action_param_type as string)) {
    return parsed?.[item.action_param as string]
  }

  if (item.action_param_type === 'command') {
    return parsed?.params ?? item.actionValue
  }

  return item.actionValue
}

export const formatActionGroupsForEcho = (actionsData: SceneInstructionLike[]) => {
  // 把接口层扁平 actions 回组装成 UI 可编辑的动作组，供编辑态回显使用。
  const actionGroupsData = [] as SceneActionGroupLike[]
  const actionInstructList = [] as SceneInstructionLike[]

  actionsData.forEach((item: SceneInstructionLike) => {
    if (isOperateDeviceInstructionAction(item.action_type)) {
      actionInstructList.push({
        ...item,
        actionParamOptions: [],
        actionValue: parseActionValueForEcho(item)
      })
      return
    }

    actionGroupsData.push({
      ...item,
      actionType: item.action_type
    } as unknown as SceneActionGroupLike)
  })

  if (actionInstructList.length > 0) {
    actionGroupsData.push({
      actionType: OPERATE_DEVICE_ACTION_TYPE,
      actionInstructList
    })
  }

  return actionGroupsData
}

import { OPERATE_DEVICE_ACTION_TYPE, type SceneActionGroupLike } from './scene-action-mappers'

export const SCENE_DRY_RUN_QUICK_FIX_KEYS = {
  addActionGroup: 'scene-add-action-group',
  selectOperateDevice: 'scene-select-operate-device',
  addDeviceInstruction: 'scene-add-device-instruction'
} as const

export interface SceneDryRunPayload {
  id?: string
  name?: string | null
  description?: string | null
  actions: any[]
  __localBuildError?: string
}

export interface SceneDryRunQuickFixTexts {
  addActionGroupTitle: string
  addActionGroupDesc: string
  addActionGroupButton: string
  selectOperateDeviceTitle: string
  selectOperateDeviceDesc: string
  selectOperateDeviceButton: string
  addDeviceInstructionTitle: string
  addDeviceInstructionDesc: string
  addDeviceInstructionButton: string
}

const getErrorMessage = (error: unknown) => {
  return error instanceof Error ? error.message : String(error || 'Unknown form error')
}

export const buildSceneActionDryRunPayload = (options: {
  form: { id?: string; name?: string | null; description?: string | null }
  buildSubmitPayload: () => { actions?: any[] }
}): SceneDryRunPayload => {
  try {
    const submitPayload = options.buildSubmitPayload()

    return {
      id: options.form.id,
      name: options.form.name,
      description: options.form.description,
      actions: submitPayload.actions || []
    }
  } catch (error) {
    return {
      id: options.form.id,
      name: options.form.name,
      description: options.form.description,
      actions: [],
      __localBuildError: getErrorMessage(error)
    }
  }
}

const isBlank = (value: unknown) => value === null || value === undefined || value === ''

const isOperateDeviceAction = (action: any) => action?.action_type === '10' || action?.action_type === '11'

const isSceneOrAlarmAction = (action: any) => action?.action_type === '20' || action?.action_type === '30'

export const getSceneActionLocalBlocker = (
  payload: SceneDryRunPayload,
  t: (key: string, options?: Record<string, any>) => string
) => {
  if (payload.__localBuildError) {
    return `${t('generate.sceneDryRunBuildError')}: ${payload.__localBuildError}`
  }

  if (!payload.actions.length) {
    return t('generate.sceneDryRunNoActionBlocker')
  }

  const incompleteIndex = payload.actions.findIndex((action: any) => {
    if (isSceneOrAlarmAction(action)) return isBlank(action.action_target)
    if (!isOperateDeviceAction(action)) return isBlank(action.action_type) || isBlank(action.action_target)

    return (
      isBlank(action.action_target) ||
      isBlank(action.action_param_type) ||
      isBlank(action.action_param) ||
      isBlank(action.action_value)
    )
  })

  if (incompleteIndex >= 0) {
    return t('generate.sceneDryRunIncompleteActionBlocker', { index: incompleteIndex + 1 })
  }

  return ''
}

export const buildSceneDryRunQuickFixActions = (options: {
  actionGroups: SceneActionGroupLike[]
  texts: SceneDryRunQuickFixTexts
}) => {
  const firstGroup = options.actionGroups[0]

  if (!firstGroup) {
    return [
      {
        key: SCENE_DRY_RUN_QUICK_FIX_KEYS.addActionGroup,
        title: options.texts.addActionGroupTitle,
        desc: options.texts.addActionGroupDesc,
        buttonLabel: options.texts.addActionGroupButton,
        type: 'primary' as const
      }
    ]
  }

  if (!firstGroup.actionType) {
    return [
      {
        key: SCENE_DRY_RUN_QUICK_FIX_KEYS.selectOperateDevice,
        title: options.texts.selectOperateDeviceTitle,
        desc: options.texts.selectOperateDeviceDesc,
        buttonLabel: options.texts.selectOperateDeviceButton,
        type: 'primary' as const
      }
    ]
  }

  if (firstGroup.actionType === OPERATE_DEVICE_ACTION_TYPE && firstGroup.actionInstructList.length === 0) {
    return [
      {
        key: SCENE_DRY_RUN_QUICK_FIX_KEYS.addDeviceInstruction,
        title: options.texts.addDeviceInstructionTitle,
        desc: options.texts.addDeviceInstructionDesc,
        buttonLabel: options.texts.addDeviceInstructionButton,
        type: 'primary' as const
      }
    ]
  }

  return []
}

import { ref } from 'vue'
import { deviceGroupTree } from '@/service/api'
import {
  deviceConfigAll,
  deviceConfigMetricsMenu,
  deviceListAll,
  deviceMetricsMenu
} from '@/service/api/automation'
import {
  applyActionParamOptionsData,
  normalizeActionParamOptionsData,
  resetInstructionSelection,
  resetInstructionTargetDependentState
} from './scene-action-form-state'
import {
  type ActionParamOptionGroup,
  type SceneInstructionLike,
  SINGLE_CLASS_DEVICE_ACTION_TARGET_TYPE,
  SINGLE_DEVICE_ACTION_TARGET_TYPE
} from './scene-action-mappers'

export type SelectOption = {
  id?: string
  name?: string
  label?: string
  value?: string
  disabled?: boolean
  [key: string]: any
}

type DeviceQuery = {
  group_id: string | null
  device_name: string | null
  bind_config: number
}

type DeviceConfigQuery = {
  device_config_name: string
}

export const useSceneActionTargetCatalog = () => {
  const loadingSelect = ref(false)
  const pendingCatalogRequests = ref(0)

  const deviceGroupOptions = ref<SelectOption[]>([])
  const deviceOptions = ref<SelectOption[]>([])
  const deviceConfigOption = ref<SelectOption[]>([])
  const hasLoadedDeviceGroups = ref(false)
  const hasLoadedDevices = ref(false)
  const hasLoadedDeviceConfigs = ref(false)
  let deviceGroupsLoadPromise: Promise<void> | null = null
  let deviceOptionsLoadPromise: Promise<void> | null = null
  let deviceConfigOptionsLoadPromise: Promise<void> | null = null

  const queryDevice = ref<DeviceQuery>({
    group_id: null,
    device_name: null,
    bind_config: 0
  })

  const queryDeviceConfig = ref<DeviceConfigQuery>({
    device_config_name: ''
  })

  const runWithLoading = async <T>(task: () => Promise<T>) => {
    pendingCatalogRequests.value += 1
    loadingSelect.value = true

    try {
      return await task()
    } finally {
      pendingCatalogRequests.value -= 1
      loadingSelect.value = pendingCatalogRequests.value > 0
    }
  }

  const getGroup = async () => {
    await runWithLoading(async () => {
      deviceGroupOptions.value = []
      const res = await deviceGroupTree({})
      deviceGroupOptions.value = (res.data || []).map((item: any) => item.group as SelectOption)
      hasLoadedDeviceGroups.value = true
      return res
    })
  }

  const getDevice = async (groupId: string | null, name: string | null) => {
    await runWithLoading(async () => {
      queryDevice.value.group_id = groupId || null
      queryDevice.value.device_name = name || null
      const res = await deviceListAll(queryDevice.value)
      deviceOptions.value = res.data || []
      hasLoadedDevices.value = true
      return res
    })
  }

  const getDeviceConfig = async (name: string | null) => {
    await runWithLoading(async () => {
      queryDeviceConfig.value.device_config_name = name || ''
      const res = await deviceConfigAll(queryDeviceConfig.value)
      deviceConfigOption.value = res.data || []
      hasLoadedDeviceConfigs.value = true
      return res
    })
  }

  const ensureDeviceGroupsLoaded = () => {
    if (hasLoadedDeviceGroups.value) return
    if (!deviceGroupsLoadPromise) {
      deviceGroupsLoadPromise = getGroup().finally(() => {
        deviceGroupsLoadPromise = null
      })
    }
    void deviceGroupsLoadPromise
  }

  const ensureDeviceOptionsLoaded = () => {
    if (hasLoadedDevices.value) return
    if (!deviceOptionsLoadPromise) {
      deviceOptionsLoadPromise = getDevice(null, null).finally(() => {
        deviceOptionsLoadPromise = null
      })
    }
    void deviceOptionsLoadPromise
  }

  const ensureDeviceConfigOptionsLoaded = () => {
    if (hasLoadedDeviceConfigs.value) return
    if (!deviceConfigOptionsLoadPromise) {
      deviceConfigOptionsLoadPromise = getDeviceConfig('').finally(() => {
        deviceConfigOptionsLoadPromise = null
      })
    }
    void deviceConfigOptionsLoadPromise
  }

  const ensureDeviceTargetCatalogsLoaded = () => {
    ensureDeviceGroupsLoaded()
    ensureDeviceOptionsLoaded()
  }

  const getActionParamMenuResponse = async (instructItem: SceneInstructionLike) => {
    if (instructItem.action_type === SINGLE_DEVICE_ACTION_TARGET_TYPE) {
      return deviceMetricsMenu({ device_id: instructItem.action_target })
    }

    if (instructItem.action_type === SINGLE_CLASS_DEVICE_ACTION_TARGET_TYPE) {
      return deviceConfigMetricsMenu({
        device_config_id: instructItem.action_target
      })
    }

    return null
  }

  const actionParamShow = async (instructItem: SceneInstructionLike) => {
    await runWithLoading(async () => {
      const res = await getActionParamMenuResponse(instructItem)
      if (res?.data) {
        const actionParamOptionsData = normalizeActionParamOptionsData(res.data as ActionParamOptionGroup[])
        applyActionParamOptionsData(instructItem, actionParamOptionsData)
      }
      return res
    })
  }

  const loadActionTargetCatalog = (actionType: string | null) => {
    if (actionType === SINGLE_DEVICE_ACTION_TARGET_TYPE) {
      void Promise.allSettled([getGroup(), getDevice(null, null)])
      return
    }

    if (actionType === SINGLE_CLASS_DEVICE_ACTION_TARGET_TYPE) {
      void getDeviceConfig('')
    }
  }

  const loadActionTargetCatalogsForEcho = (instructions: SceneInstructionLike[]) => {
    const tasks: Array<Promise<void>> = []

    if (instructions.some(item => item.action_type === SINGLE_DEVICE_ACTION_TARGET_TYPE)) {
      tasks.push(getGroup(), getDevice(null, null))
    }

    if (instructions.some(item => item.action_type === SINGLE_CLASS_DEVICE_ACTION_TARGET_TYPE)) {
      tasks.push(getDeviceConfig(''))
    }

    if (tasks.length > 0) {
      void Promise.allSettled(tasks)
    }
  }

  const actionTypeChange = (instructItem: SceneInstructionLike, actionType: string | null) => {
    resetInstructionSelection(instructItem)
    loadActionTargetCatalog(actionType)
  }

  const actionTargetChange = (instructItem: SceneInstructionLike) => {
    resetInstructionTargetDependentState(instructItem)
    void actionParamShow(instructItem)
  }

  const loadInitialSelectData = () => {
    void Promise.allSettled([getGroup(), getDevice(null, null), getDeviceConfig('')])
  }

  return {
    actionParamShow,
    actionTargetChange,
    actionTypeChange,
    deviceConfigOption,
    deviceGroupOptions,
    deviceOptions,
    ensureDeviceConfigOptionsLoaded,
    ensureDeviceGroupsLoaded,
    ensureDeviceOptionsLoaded,
    ensureDeviceTargetCatalogsLoaded,
    getDevice,
    getDeviceConfig,
    getGroup,
    loadActionTargetCatalogsForEcho,
    loadInitialSelectData,
    loadingSelect,
    queryDevice
  }
}

