import { ref } from 'vue'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const api = vi.hoisted(() => ({
  deviceList: vi.fn(),
  deviceAlarmStatus: vi.fn(),
  telemetryDataCurrentKeys: vi.fn(),
  rdiDeviceConfig: vi.fn()
}))

vi.mock('@/service/api/device', () => ({
  deviceList: api.deviceList,
  deviceAlarmStatus: api.deviceAlarmStatus,
  telemetryDataCurrentKeys: api.telemetryDataCurrentKeys
}))

vi.mock('@/service/api/rdi', () => ({ rdiDeviceConfig: api.rdiDeviceConfig }))

import { useRdiDeviceSnapshots } from '../useRdiDeviceSnapshots'

function deferred<T>() {
  let resolve!: (value: T) => void
  const promise = new Promise<T>((resolvePromise) => {
    resolve = resolvePromise
  })
  return { promise, resolve }
}

function createSnapshots(activeSystemsOnly = ref(false), isMasterAccount = ref(false)) {
  return useRdiDeviceSnapshots({ activeSystemsOnly, isMasterAccount })
}

describe('useRdiDeviceSnapshots', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    api.deviceList.mockResolvedValue({ data: { list: [], total: 0 } })
    api.telemetryDataCurrentKeys.mockResolvedValue({ data: [] })
    api.deviceAlarmStatus.mockResolvedValue({ data: { alarm: false } })
    api.rdiDeviceConfig.mockResolvedValue({ error: null, data: { system_info: {} } })
  })

  afterEach(() => {
    vi.useRealTimers()
    delete (window as any).requestIdleCallback
    delete (window as any).cancelIdleCallback
  })

  it('uses responsive default, active-system, and master request parameters', async () => {
    const activeSystemsOnly = ref(false)
    const isMasterAccount = ref(false)
    const snapshots = createSnapshots(activeSystemsOnly, isMasterAccount)

    await snapshots.fetchDeviceSnapshots()
    expect(api.deviceList).toHaveBeenLastCalledWith({
      page: 1,
      page_size: 12,
      include_rdi_system_info_summary: true
    })

    activeSystemsOnly.value = true
    await snapshots.fetchDeviceSnapshots()
    expect(api.deviceList).toHaveBeenLastCalledWith({
      page: 1,
      page_size: 12,
      include_rdi_system_info_summary: true,
      warn_status: 'Y'
    })

    isMasterAccount.value = true
    await snapshots.fetchDeviceSnapshots()
    expect(api.deviceList).toHaveBeenLastCalledWith({
      page: 1,
      page_size: 12,
      include_rdi_system_info_summary: true,
      warn_status: 'Y',
      all_tenants: true
    })
  })

  it('hydrates missing RDI system info but trusts an explicitly empty summary', async () => {
    api.deviceList.mockResolvedValue({
      data: {
        list: [
          { id: 'fallback', pid_number: 'PID-1', system_info: {} },
          { id: 'explicit-empty', pid_number: 'PID-2', rdi_system_info_summary: {} }
        ]
      }
    })
    api.rdiDeviceConfig.mockResolvedValue({
      error: null,
      data: { system_info: { controller_serial_number: 'CONFIG-SN', installation_location: 'Plant A' } }
    })
    const snapshots = createSnapshots()

    await snapshots.fetchDeviceSnapshots()

    expect(api.rdiDeviceConfig).toHaveBeenCalledTimes(1)
    expect(api.rdiDeviceConfig).toHaveBeenCalledWith('fallback')
    expect(snapshots.deviceSnapshots.value[0]).toMatchObject({ serialNumber: 'CONFIG-SN', installLocation: 'Plant A' })
    expect(snapshots.deviceSnapshots.value[1].serialNumber).toBe('--')
  })

  it('degrades telemetry and alarm failures without dropping the snapshot', async () => {
    api.deviceList.mockResolvedValue({ data: { list: [{ id: 'device-1', name: 'Device 1', is_online: 1 }] } })
    api.telemetryDataCurrentKeys.mockRejectedValue(new Error('telemetry unavailable'))
    api.deviceAlarmStatus.mockRejectedValue(new Error('alarm unavailable'))
    const snapshots = createSnapshots()

    await snapshots.fetchDeviceSnapshots()

    expect(snapshots.deviceSnapshots.value[0]).toMatchObject({ id: 'device-1', telemetry: {}, alarm: null })
    expect(snapshots.snapshotLoading.value).toBe(false)
  })

  it('keeps only the latest request result and loading ownership', async () => {
    const first = deferred<any>()
    const second = deferred<any>()
    api.deviceList.mockImplementationOnce(() => first.promise).mockImplementationOnce(() => second.promise)
    const snapshots = createSnapshots()

    const firstFetch = snapshots.fetchDeviceSnapshots()
    const secondFetch = snapshots.fetchDeviceSnapshots()
    second.resolve({ data: { list: [{ id: 'latest' }], total: 1 } })
    await secondFetch
    expect(snapshots.deviceSnapshots.value[0].id).toBe('latest')
    expect(snapshots.snapshotLoading.value).toBe(false)

    first.resolve({ data: { list: [{ id: 'stale' }], total: 99 } })
    await firstFetch
    expect(snapshots.deviceSnapshots.value[0].id).toBe('latest')
    expect(snapshots.snapshotTotal.value).toBe(1)
    expect(snapshots.snapshotLoading.value).toBe(false)
  })

  it('changes page before requesting the next server page', async () => {
    const snapshots = createSnapshots()

    snapshots.changeSnapshotPage(3)
    await vi.waitFor(() => expect(api.deviceList).toHaveBeenCalledTimes(1))

    expect(snapshots.snapshotPage.value).toBe(3)
    expect(api.deviceList).toHaveBeenCalledWith({
      page: 3,
      page_size: 12,
      include_rdi_system_info_summary: true
    })
  })

  it('schedules with the 350ms fallback and cancel prevents the request', async () => {
    vi.useFakeTimers()
    const snapshots = createSnapshots()

    snapshots.scheduleDeviceSnapshotsRefresh()
    expect(snapshots.snapshotLoading.value).toBe(true)
    await vi.advanceTimersByTimeAsync(349)
    expect(api.deviceList).not.toHaveBeenCalled()
    await vi.advanceTimersByTimeAsync(1)
    expect(api.deviceList).toHaveBeenCalledTimes(1)

    snapshots.scheduleDeviceSnapshotsRefresh()
    snapshots.cancelScheduledDeviceSnapshots()
    await vi.advanceTimersByTimeAsync(350)
    expect(api.deviceList).toHaveBeenCalledTimes(1)
  })

  it('uses and cancels idle callbacks when available', () => {
    const requestIdleCallback = vi.fn(() => 17)
    const cancelIdleCallback = vi.fn()
    ;(window as any).requestIdleCallback = requestIdleCallback
    ;(window as any).cancelIdleCallback = cancelIdleCallback
    const snapshots = createSnapshots()

    snapshots.scheduleDeviceSnapshotsRefresh()
    expect(requestIdleCallback).toHaveBeenCalledWith(expect.any(Function), { timeout: 1200 })
    snapshots.cancelScheduledDeviceSnapshots()
    expect(cancelIdleCallback).toHaveBeenCalledWith(17)
  })

  it('dispose invalidates an in-flight request', async () => {
    const pending = deferred<any>()
    api.deviceList.mockReturnValue(pending.promise)
    const snapshots = createSnapshots()

    const fetch = snapshots.fetchDeviceSnapshots()
    snapshots.dispose()
    pending.resolve({ data: { list: [{ id: 'after-dispose' }], total: 1 } })
    await fetch

    expect(snapshots.deviceSnapshots.value).toEqual([])
  })
})

/**
 * File purpose: pure state helpers for the RDI Overview device-card snapshot.
 * Inputs and outputs stay framework-agnostic so pagination, alarm state, and
 * system-info summary normalization can be reviewed and tested without page
 * lifecycle side effects. Keep network requests and reactive mutations in the
 * owning view rather than adding them here.
 */
export const RDI_SNAPSHOT_LIMIT = 12

export const RDI_SNAPSHOT_KEYS = [
  'temperature_1',
  'temperature_2',
  'switch_1',
  'switch_2',
  'dry_contact_output',
  'electricity_consumption'
]

export type TemperatureUnit = 'C' | 'F'

export interface AlarmRecord {
  id: string
  tenant_id?: string
  TenantID?: string
  name?: string
  content?: string
  description?: string
  alarm_status?: string
  alarm_level?: string
  create_at?: string
  alarm_device_list?: Array<{ id: string; name?: string }>
  remark?: string | Record<string, unknown>
}

export interface DeviceSnapshot {
  id: string
  name: string
  pid: string
  firmware: string
  online: boolean
  alarm: boolean | null
  // alarmLevel mirrors the backend warn_status (H/M/L/N). Empty when the
  // backend row does not carry a severity, so callers should still consult
  // `alarm` for the boolean intent.
  alarmLevel: string
  // groupId is the first device-group id the backend returned for the row.
  // It powers the client-side group filter without introducing an extra
  // relation query per snapshot; downstream code should treat it as an
  // opaque string and never assume a specific format.
  groupId: string
  serialNumber: string
  installLocation: string
  installAddress: string
  installDate: string
  installerName: string
  installerContact: string
  adminName: string
  tenantId: string
  telemetry: Record<string, unknown>
}

export interface SnapshotSystemInfo {
  present: boolean
  value: Record<string, unknown>
}

export interface RdiOverviewStats {
  totalDevices: number
  onlineDevices: number
  offlineDevices: number
  activeAlarms: number
}

export interface AlarmTrendPoint {
  month: number
  count: number
}

export type Translate = (key: string) => string

export function parseAlarmRemark(raw: unknown) {
  if (!raw) return {} as Record<string, unknown>
  if (typeof raw === 'object') return raw as Record<string, unknown>
  if (typeof raw !== 'string') return {} as Record<string, unknown>
  try {
    const parsed = JSON.parse(raw)
    return parsed && typeof parsed === 'object' ? (parsed as Record<string, unknown>) : {}
  } catch {
    return {} as Record<string, unknown>
  }
}

export function isAcknowledgedAlarm(row: AlarmRecord) {
  return parseAlarmRemark(row.remark).acknowledged === true
}

export function alarmStatusLabel(status: string | undefined, t: Translate) {
  const labels: Record<string, string> = {
    H: t('rdi.overview.high'),
    M: t('rdi.overview.medium'),
    L: t('rdi.overview.low'),
    N: t('rdi.overview.normal')
  }
  return labels[status || ''] || status || '-'
}

export function alarmTagType(status?: string) {
  if (status === 'H') return 'error'
  if (status === 'M') return 'warning'
  if (status === 'L') return 'info'
  return 'success'
}

export function alarmTypeLabel(row: AlarmRecord, t: Translate) {
  const remark = parseAlarmRemark(row.remark)
  const eventType = String(remark.event_type || '')
  const labels: Record<string, string> = {
    temperature_alarm: t('rdi.overview.temperatureAlarm'),
    switch_alarm: t('rdi.overview.switchAlarm'),
    warranty_alarm: t('rdi.overview.warrantyAlarm'),
    pressure_alarm: t('rdi.overview.pressureAlarm'),
    sw2_long_press: t('rdi.overview.sw2LongPress'),
    sw3_short_press: t('rdi.overview.sw3ShortPress'),
    sw3_long_press: t('rdi.overview.sw3LongPress'),
    PT: t('rdi.overview.pressureAlarm')
  }
  return labels[eventType] || row.name || row.content || '-'
}

export function normalizeDeviceRows(payload: any): Record<string, unknown>[] {
  const data = payload?.data ?? payload
  if (Array.isArray(data)) return data
  if (Array.isArray(data?.list)) return data.list
  if (Array.isArray(data?.data?.list)) return data.data.list
  return []
}

export function normalizeTelemetry(payload: unknown) {
  const data = (payload as any)?.data ?? payload
  const list = Array.isArray(data) ? data : Array.isArray((data as any)?.list) ? (data as any).list : null
  const result: Record<string, unknown> = {}
  if (list) {
    list.forEach((item: any) => {
      const key = String(item?.key || '')
      if (key) result[key] = item?.value ?? item?.number_v ?? item?.string_v ?? item?.bool_v
    })
    return result
  }
  return data && typeof data === 'object' ? (data as Record<string, unknown>) : result
}

export function rowText(row: Record<string, unknown>, keys: string[], fallback = '--') {
  for (const key of keys) {
    const value = row[key]
    if (value !== undefined && value !== null && value !== '') return String(value)
  }
  return fallback
}

function recordValue(value: unknown): Record<string, unknown> {
  if (!value) return {}
  if (typeof value === 'object' && !Array.isArray(value)) return value as Record<string, unknown>
  if (typeof value !== 'string') return {}
  try {
    const parsed = JSON.parse(value)
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? (parsed as Record<string, unknown>) : {}
  } catch {
    return {}
  }
}

export function snapshotSystemInfo(row: Record<string, unknown>): SnapshotSystemInfo {
  const additionalInfo = recordValue(row.additional_info)
  const hasListSummary = Object.prototype.hasOwnProperty.call(row, 'rdi_system_info_summary')
  const sources = [
    additionalInfo.system_info,
    additionalInfo.rdi_system_info,
    row.system_info,
    row.rdi_system_info,
    row.rdi_system_info_summary
  ]
  const present = hasListSummary || sources.some((source) => Object.keys(recordValue(source)).length > 0)
  const value = sources.reduce<Record<string, unknown>>((result, source) => {
    return { ...result, ...recordValue(source) }
  }, {})
  return {
    present,
    value: { ...recordValue(value.extra_fields), ...value }
  }
}

export function isRowOnline(row: Record<string, unknown>) {
  const value = row.is_online ?? row.online ?? row.status
  return value === true || value === 1 || value === '1' || value === 'online'
}

export function formatTemperature(value: unknown, unit: TemperatureUnit = 'C') {
  if (value === null || value === undefined || value === '') return '--'
  const numeric = Number(value)
  if (!Number.isFinite(numeric)) return '--'
  const converted = unit === 'F' ? (numeric * 9) / 5 + 32 : numeric
  return `${converted.toFixed(2)} ${unit}`
}

export function formatSwitch(value: unknown, t: Translate) {
  if (value === true || value === 1 || value === '1' || value === 'true' || value === 'high') {
    return t('rdi.overview.high')
  }
  if (value === false || value === 0 || value === '0' || value === 'false' || value === 'low') {
    return t('rdi.overview.low')
  }
  return value === undefined || value === null || value === '' ? '--' : String(value)
}

export function buildOperationsFocus(stats: RdiOverviewStats, alarmDeviceTotal: number) {
  if (stats.activeAlarms > 0) {
    return {
      type: 'error',
      titleKey: 'rdi.overview.focusAlarmTitle',
      descKey: 'rdi.overview.focusAlarmDesc',
      tags: [
        { labelKey: 'rdi.overview.activeAlarms', value: stats.activeAlarms, type: 'error' },
        { labelKey: 'rdi.overview.alarmDevices', value: alarmDeviceTotal, type: 'warning' }
      ]
    }
  }

  if (stats.offlineDevices > 0) {
    return {
      type: 'warning',
      titleKey: 'rdi.overview.focusOfflineTitle',
      descKey: 'rdi.overview.focusOfflineDesc',
      tags: [
        { labelKey: 'rdi.overview.offline', value: stats.offlineDevices, type: 'warning' },
        { labelKey: 'rdi.overview.online', value: stats.onlineDevices, type: 'success' }
      ]
    }
  }

  return {
    type: 'success',
    titleKey: 'rdi.overview.focusNormalTitle',
    descKey: 'rdi.overview.focusNormalDesc',
    tags: [
      { labelKey: 'rdi.overview.online', value: stats.onlineDevices, type: 'success' },
      { labelKey: 'rdi.overview.devices', value: stats.totalDevices, type: 'info' }
    ]
  }
}

export function normalizeAlarmMonthlyTrendPoints(rows: Array<Partial<AlarmTrendPoint>>): AlarmTrendPoint[] {
  const counts = new Map<number, number>()
  rows.forEach((row) => {
    const month = Number(row.month)
    const count = Number(row.count)
    if (!Number.isInteger(month) || month < 1 || month > 12 || counts.has(month)) return
    counts.set(month, Number.isFinite(count) && count > 0 ? count : 0)
  })
  return Array.from({ length: 12 }, (_, index) => ({
    month: index + 1,
    count: counts.get(index + 1) || 0
  }))
}

import { ref, toValue, type MaybeRefOrGetter } from 'vue'
import { deviceAlarmStatus, deviceList, telemetryDataCurrentKeys } from '@/service/api/device'
import { rdiDeviceConfig } from '@/service/api/rdi'
import {
  RDI_SNAPSHOT_KEYS,
  RDI_SNAPSHOT_LIMIT,
  isRowOnline,
  normalizeDeviceRows,
  normalizeTelemetry,
  rowText,
  snapshotSystemInfo,
  type DeviceSnapshot
} from './rdiOverviewState'

const RDI_SNAPSHOT_TELEMETRY_CONCURRENCY = 3
const RDI_SNAPSHOT_IDLE_DELAY_MS = 350

export async function mapWithConcurrency<T, R>(
  items: T[],
  concurrency: number,
  mapper: (item: T, index: number) => Promise<R>
): Promise<R[]> {
  const results = new Array<R>(items.length)
  let nextIndex = 0
  const workerCount = Math.min(Math.max(concurrency, 1), items.length)

  await Promise.all(
    Array.from({ length: workerCount }, async () => {
      while (nextIndex < items.length) {
        const currentIndex = nextIndex
        nextIndex += 1
        results[currentIndex] = await mapper(items[currentIndex], currentIndex)
      }
    })
  )
  return results
}

export function useRdiDeviceSnapshots(options: {
  activeSystemsOnly: MaybeRefOrGetter<boolean>
  isMasterAccount: MaybeRefOrGetter<boolean>
}) {
  const snapshotLoading = ref(false)
  const deviceSnapshots = ref<DeviceSnapshot[]>([])
  const snapshotPage = ref(1)
  const snapshotTotal = ref(0)
  let snapshotRequestSeq = 0
  let snapshotRefreshTimer: number | undefined
  let snapshotIdleCallbackId: number | undefined

  async function buildDeviceSnapshot(row: Record<string, unknown>): Promise<DeviceSnapshot> {
    const id = rowText(row, ['id', 'device_id'], '')
    const listSystemInfo = snapshotSystemInfo(row)
    const isRdiDevice = rowText(row, ['pid_number', 'PIDNumber'], '') !== ''
    let telemetry: Record<string, unknown> = {}
    let alarm: boolean | null = null
    let systemInfo = listSystemInfo.value
    if (id) {
      const [telemetryRes, alarmRes, configRes] = await Promise.all([
        telemetryDataCurrentKeys({ device_id: id, keys: RDI_SNAPSHOT_KEYS }).catch(() => null),
        deviceAlarmStatus({ device_id: id }).catch(() => null),
        // Older APIs may omit the opt-in list summary. Hydrate only in that
        // compatibility case; an explicitly returned empty summary is authoritative.
        isRdiDevice && !listSystemInfo.present ? rdiDeviceConfig(id).catch(() => null) : Promise.resolve(null)
      ])
      if (telemetryRes) {
        telemetry = normalizeTelemetry(telemetryRes)
      }
      const alarmValue = alarmRes?.data?.alarm ?? alarmRes?.data?.data?.alarm
      if (typeof alarmValue === 'boolean') alarm = alarmValue
      if (configRes && !configRes.error && configRes.data?.system_info) {
        systemInfo = snapshotSystemInfo({ system_info: configRes.data.system_info }).value
      }
    }
    const rowSerialNumber = rowText(row, ['serial_number', 'device_serial_number', 'rdi_serial_number', 'SerialNumber'])
    const rowInstallLocation = rowText(row, ['install_location', 'installation_location', 'location', 'address'])
    const rowInstallAddress = rowText(row, ['install_address', 'installation_address', 'device_address', 'address'])
    const rowInstallDate = rowText(row, ['install_date', 'installation_date', 'installed_at', 'InstallDate'])
    const rowInstallerName = rowText(row, ['installer_name', 'service_technician', 'technician_name', 'maintainer_name'])
    const rowInstallerContact = rowText(row, [
      'installer_contact',
      'installer_phone',
      'technician_phone',
      'technician_email'
    ])
    const installerContact = [rowText(systemInfo, ['installer_phone'], ''), rowText(systemInfo, ['installer_email'], '')]
      .filter(Boolean)
      .join(' · ')
    const alarmLevelRaw = rowText(row, ['alarm_level', 'AlarmLevel', 'warn_status', 'WarnStatus'], '')
    const alarmLevel = alarmLevelRaw && alarmLevelRaw !== '--' ? alarmLevelRaw : ''
    const groupIdRaw = rowText(row, ['group_id', 'GroupId', 'group_ids', 'GroupIds'], '')
    const groupId = groupIdRaw && groupIdRaw !== '--' ? groupIdRaw.split(',')[0].trim() : ''
    return {
      id,
      name: rowText(row, ['name', 'device_name', 'DeviceName'], id || '--'),
      pid: rowText(row, ['pid_number', 'device_number', 'DeviceNumber']),
      firmware: rowText(row, ['firmware_version', 'current_version', 'CurrentVersion']),
      online: isRowOnline(row),
      alarm,
      alarmLevel,
      groupId,
      serialNumber: rowText(systemInfo, ['controller_serial_number', 'rdi_serial_number'], rowSerialNumber),
      installLocation: rowText(systemInfo, ['installation_location'], rowInstallLocation),
      installAddress: rowText(systemInfo, ['address', 'installation_address'], rowInstallAddress),
      installDate: rowText(systemInfo, ['installation_date'], rowInstallDate),
      installerName: rowText(
        systemInfo,
        ['installer_name', 'installer_company', 'maintenance_technician', 'installer_contact'],
        rowInstallerName
      ),
      installerContact: installerContact || rowText(systemInfo, ['installer_contact'], rowInstallerContact),
      adminName: rowText(
        systemInfo,
        ['customer_name', 'admin_name', 'administrator'],
        rowText(row, ['admin_name', 'owner_name', 'user_name', 'UserName'])
      ),
      tenantId: rowText(row, ['scope_tenant_id', 'tenant_id', 'TenantID']),
      telemetry
    }
  }

  async function fetchDeviceSnapshots(requestSeq = ++snapshotRequestSeq) {
    snapshotLoading.value = true
    try {
      const res = await deviceList({
        page: snapshotPage.value,
        page_size: RDI_SNAPSHOT_LIMIT,
        include_rdi_system_info_summary: true,
        ...(toValue(options.activeSystemsOnly) ? { warn_status: 'Y' } : {}),
        ...(toValue(options.isMasterAccount) ? { all_tenants: true } : {})
      })
      const rows = normalizeDeviceRows(res).slice(0, RDI_SNAPSHOT_LIMIT)
      const snapshots = await mapWithConcurrency(rows, RDI_SNAPSHOT_TELEMETRY_CONCURRENCY, buildDeviceSnapshot)
      if (requestSeq === snapshotRequestSeq) {
        deviceSnapshots.value = snapshots.filter((item) => item.id)
        const payload = (res as any)?.data ?? res
        snapshotTotal.value = Number(payload?.total ?? payload?.data?.total ?? rows.length)
      }
    } finally {
      if (requestSeq === snapshotRequestSeq) {
        snapshotLoading.value = false
      }
    }
  }

  function changeSnapshotPage(page: number) {
    snapshotPage.value = page
    void fetchDeviceSnapshots()
  }

  function cancelScheduledDeviceSnapshots() {
    if (snapshotRefreshTimer !== undefined) {
      window.clearTimeout(snapshotRefreshTimer)
      snapshotRefreshTimer = undefined
    }
    if (snapshotIdleCallbackId !== undefined) {
      const cancelIdleCallback = (window as any).cancelIdleCallback
      if (typeof cancelIdleCallback === 'function') {
        cancelIdleCallback(snapshotIdleCallbackId)
      }
      snapshotIdleCallbackId = undefined
    }
  }

  function scheduleDeviceSnapshotsRefresh() {
    const requestSeq = ++snapshotRequestSeq
    snapshotLoading.value = true
    cancelScheduledDeviceSnapshots()
    const run = () => {
      snapshotRefreshTimer = undefined
      snapshotIdleCallbackId = undefined
      void fetchDeviceSnapshots(requestSeq).catch(() => {
        if (requestSeq === snapshotRequestSeq) {
          snapshotLoading.value = false
        }
      })
    }
    const requestIdleCallback = (window as any).requestIdleCallback
    if (typeof requestIdleCallback === 'function') {
      snapshotIdleCallbackId = requestIdleCallback(run, { timeout: 1200 })
      return
    }
    snapshotRefreshTimer = window.setTimeout(run, RDI_SNAPSHOT_IDLE_DELAY_MS)
  }

  function dispose() {
    cancelScheduledDeviceSnapshots()
    snapshotRequestSeq += 1
  }

  return {
    snapshotLoading,
    deviceSnapshots,
    snapshotPage,
    snapshotTotal,
    mapWithConcurrency,
    buildDeviceSnapshot,
    fetchDeviceSnapshots,
    changeSnapshotPage,
    scheduleDeviceSnapshotsRefresh,
    cancelScheduledDeviceSnapshots,
    dispose
  }
}

/**
 * File purpose: overview data-plane composable for the RDI Overview page.
 * Owns the summary stats, alarm history list/pagination, active-alarm counts,
 * and monthly trend state plus their request sequencing. Rendering, dialog and
 * navigation glue stay in the owning view. Request order and payload shapes
 * must stay identical to the previous inline implementation.
 */
import { reactive, ref, toValue, type MaybeRefOrGetter } from 'vue'
import type { PaginationProps } from 'naive-ui'
import dayjs from 'dayjs'
import { alarmHistory, alarmHistoryMonthlyTrend } from '@/service/api/alarm'
import { getAlarmCount, sumData } from '@/service/api/system-data'
import { normalizeAlarmMonthlyTrendPoints, type AlarmRecord, type AlarmTrendPoint } from './rdiOverviewState'

export function useRdiOverviewData(options: {
  isMasterAccount: MaybeRefOrGetter<boolean>
}) {
  const loading = ref(false)
  const alarmLoading = ref(false)
  const alarmTrendLoading = ref(false)
  const alarms = ref<AlarmRecord[]>([])
  const alarmTrendPoints = ref<AlarmTrendPoint[]>(normalizeAlarmMonthlyTrendPoints([]))
  const alarmTrendYear = ref(dayjs().year())
  const alarmTrendTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'
  const alarmDeviceTotal = ref(0)

  const stats = reactive({
    totalDevices: 0,
    onlineDevices: 0,
    offlineDevices: 0,
    activeAlarms: 0,
    alarmHistoryTotal: 0
  })

  const queryParams = reactive({
    page: 1,
    page_size: 10,
    alarm_status: 'ACTIVE'
  })

  async function fetchDevices() {
    loading.value = true
    try {
      const res = toValue(options.isMasterAccount) ? await sumData({ all_tenants: true }) : await sumData()
      const data = res?.data || {}
      stats.totalDevices = Number(data.device_total ?? data.DeviceTotal ?? 0)
      stats.onlineDevices = Number(data.device_on ?? data.DeviceOn ?? 0)
      stats.offlineDevices = Number(
        data.device_offline ?? data.DeviceOffline ?? Math.max(stats.totalDevices - stats.onlineDevices, 0)
      )
    } finally {
      loading.value = false
    }
  }

  async function fetchCounts() {
    const res = toValue(options.isMasterAccount)
      ? await getAlarmCount({ all_tenants: true })
      : await getAlarmCount()
    const data = (res?.data || {}) as any
    alarmDeviceTotal.value = Number(data.alarm_device_total ?? data.AlarmDeviceTotal ?? 0)
    stats.alarmHistoryTotal = Number(data.alarm_history_total ?? data.AlarmHistoryTotal ?? 0)
    const activeAlarmTotal = data.active_alarm_total ?? data.ActiveAlarmTotal
    if (activeAlarmTotal !== undefined && activeAlarmTotal !== null) {
      stats.activeAlarms = Number(activeAlarmTotal || 0)
      return true
    }
    return false
  }

  async function fetchActiveAlarmCounts() {
    const res = await alarmHistory({
      page: 1,
      page_size: 1,
      alarm_status: 'ACTIVE',
      ...(toValue(options.isMasterAccount) ? { all_tenants: true } : {})
    })
    stats.activeAlarms = Number(res?.data?.total || 0)
  }

  async function refreshAlarmSummaryCounts() {
    const hasActiveAlarmTotal = await fetchCounts()
    if (!hasActiveAlarmTotal) {
      await fetchActiveAlarmCounts()
    }
  }

  async function fetchAlarms() {
    alarmLoading.value = true
    try {
      const res = await alarmHistory({
        page: queryParams.page,
        page_size: queryParams.page_size,
        alarm_status: queryParams.alarm_status || undefined,
        ...(toValue(options.isMasterAccount) ? { all_tenants: true } : {})
      })
      alarms.value = res?.data?.list || []
      alarmPagination.itemCount = res?.data?.total || 0
    } finally {
      alarmLoading.value = false
    }
  }

  function searchAlarms() {
    queryParams.page = 1
    alarmPagination.page = 1
    fetchAlarms()
  }

  async function fetchAlarmTrend() {
    alarmTrendLoading.value = true
    try {
      const res = toValue(options.isMasterAccount)
        ? await alarmHistoryMonthlyTrend(alarmTrendYear.value, alarmTrendTimezone, { all_tenants: true })
        : await alarmHistoryMonthlyTrend(alarmTrendYear.value, alarmTrendTimezone)
      alarmTrendPoints.value = normalizeAlarmMonthlyTrendPoints(res?.data?.months || [])
    } finally {
      alarmTrendLoading.value = false
    }
  }

  const alarmPagination: PaginationProps = reactive({
    page: queryParams.page,
    pageSize: queryParams.page_size,
    itemCount: 0,
    showSizePicker: true,
    pageSizes: [10, 20, 50],
    onChange: (page) => {
      queryParams.page = page
      alarmPagination.page = page
      fetchAlarms()
    },
    onUpdatePageSize: (pageSize) => {
      queryParams.page = 1
      queryParams.page_size = pageSize
      alarmPagination.page = 1
      alarmPagination.pageSize = pageSize
      fetchAlarms()
    }
  })

  function resetAlarmFilter() {
    queryParams.alarm_status = 'ACTIVE'
    queryParams.page = 1
    alarmPagination.page = 1
    fetchAlarms()
  }

  return {
    loading,
    alarmLoading,
    alarmTrendLoading,
    alarms,
    alarmTrendPoints,
    alarmTrendYear,
    alarmDeviceTotal,
    stats,
    queryParams,
    alarmPagination,
    fetchDevices,
    fetchCounts,
    fetchActiveAlarmCounts,
    refreshAlarmSummaryCounts,
    fetchAlarms,
    searchAlarms,
    fetchAlarmTrend,
    resetAlarmFilter
  }
}

/**
 * File purpose: snapshot filter-panel composable for the RDI Overview page.
 * Owns the client-side keyword/status/level/group filter state, the advanced
 * panel visibility, group-tree options, active-filter chips, and the visible
 * snapshot list derived from the server page. The matching predicate and chip
 * assembly are exported as pure helpers so they stay testable without page
 * lifecycle side effects.
 */
import { computed, ref, toValue, type MaybeRefOrGetter } from 'vue'
import type { TreeSelectOption } from 'naive-ui/es/tree-select/src/interface'
import { deviceGroupTree } from '@/service/api/device'
import { $t } from '@/locales'
import { type DeviceSnapshot, type Translate } from './rdiOverviewState'

export interface SnapshotFilterCriteria {
  keyword: string
  status: 'all' | 'online' | 'offline' | 'alarm'
  alarmLevel: 'all' | 'H' | 'M' | 'L' | 'N'
  groupId: string | null
}

// matchSnapshotFilters narrows a single snapshot against the user-selected
// criteria. The keyword is trimmed and lowercased here so callers can pass the
// raw input binding; empty keyword means the field search is a no-op.
export function matchSnapshotFilters(device: DeviceSnapshot, criteria: SnapshotFilterCriteria): boolean {
  if (criteria.status === 'online' && !device.online) return false
  if (criteria.status === 'offline' && device.online) return false
  if (criteria.status === 'alarm' && device.alarm !== true) return false
  if (criteria.alarmLevel !== 'all') {
    const level = device.alarmLevel || (device.alarm === true ? 'H' : device.alarm === false ? 'N' : '')
    if (criteria.alarmLevel === 'N') {
      if (level && level !== 'N') return false
    } else if (level !== criteria.alarmLevel) {
      return false
    }
  }
  if (criteria.groupId && device.groupId !== criteria.groupId) return false
  const keyword = criteria.keyword.trim().toLowerCase()
  if (!keyword) return true
  const haystack = [
    device.name,
    device.id,
    device.pid,
    device.serialNumber,
    device.installLocation,
    device.installAddress,
    device.installerName,
    device.adminName
  ]
    .filter((value) => value && value !== '--')
    .join(' ')
    .toLowerCase()
  return haystack.includes(keyword)
}

export function buildSnapshotFilterChips(
  criteria: SnapshotFilterCriteria,
  groupNameById: Record<string, string>,
  t: Translate
): Array<{ key: string; label: string }> {
  const chips: Array<{ key: string; label: string }> = []
  const keyword = criteria.keyword.trim()
  if (keyword) {
    chips.push({ key: 'keyword', label: `${t('common.search')}: ${keyword}` })
  }
  if (criteria.status !== 'all') {
    const statusLabels: Record<string, string> = {
      online: t('rdi.overview.snapshotStatusOnline'),
      offline: t('rdi.overview.snapshotStatusOffline'),
      alarm: t('rdi.overview.snapshotStatusAlarm')
    }
    chips.push({ key: 'status', label: statusLabels[criteria.status] })
  }
  if (criteria.alarmLevel !== 'all') {
    const alarmLevelLabels: Record<string, string> = {
      H: t('rdi.overview.high'),
      M: t('rdi.overview.medium'),
      L: t('rdi.overview.low'),
      N: t('rdi.overview.normal')
    }
    chips.push({
      key: 'alarmLevel',
      label: `${t('common.alarm_level')}: ${alarmLevelLabels[criteria.alarmLevel]}`
    })
  }
  if (criteria.groupId) {
    const groupName = groupNameById[criteria.groupId] || criteria.groupId
    chips.push({ key: 'group', label: `${t('rdi.overview.snapshotFilterGroup')}: ${groupName}` })
  }
  return chips
}

export function useRdiSnapshotFilters(options: {
  deviceSnapshots: MaybeRefOrGetter<DeviceSnapshot[]>
}) {
  const snapshotFilterKeyword = ref('')
  const snapshotFilterStatus = ref<'all' | 'online' | 'offline' | 'alarm'>('all')
  const snapshotFilterAlarmLevel = ref<'all' | 'H' | 'M' | 'L' | 'N'>('all')
  const snapshotFilterGroupId = ref<string | null>(null)
  const snapshotFilterAdvancedVisible = ref(false)
  const snapshotGroupOptions = ref<TreeSelectOption[]>([])
  const snapshotGroupNameById = ref<Record<string, string>>({})

  const snapshotStatusOptions = computed(() => [
    { label: $t('rdi.overview.snapshotStatusAll'), value: 'all' },
    { label: $t('rdi.overview.snapshotStatusOnline'), value: 'online' },
    { label: $t('rdi.overview.snapshotStatusOffline'), value: 'offline' },
    { label: $t('rdi.overview.snapshotStatusAlarm'), value: 'alarm' }
  ])

  const snapshotAlarmLevelOptions = computed(() => [
    { label: $t('rdi.overview.snapshotAlarmLevelAll'), value: 'all' },
    { label: $t('rdi.overview.high'), value: 'H' },
    { label: $t('rdi.overview.medium'), value: 'M' },
    { label: $t('rdi.overview.low'), value: 'L' },
    { label: $t('rdi.overview.normal'), value: 'N' }
  ])

  // snapshotHasActiveFilters reports whether at least one user-selected filter
  // narrows the visible snapshot list beyond the raw server page.
  const snapshotHasActiveFilters = computed(() => {
    return (
      snapshotFilterKeyword.value.trim() !== '' ||
      snapshotFilterStatus.value !== 'all' ||
      snapshotFilterAlarmLevel.value !== 'all' ||
      !!snapshotFilterGroupId.value
    )
  })

  const snapshotActiveFilterChips = computed(() =>
    buildSnapshotFilterChips(
      {
        keyword: snapshotFilterKeyword.value,
        status: snapshotFilterStatus.value,
        alarmLevel: snapshotFilterAlarmLevel.value,
        groupId: snapshotFilterGroupId.value
      },
      snapshotGroupNameById.value,
      $t
    )
  )

  // visibleDeviceSnapshots filters the currently loaded snapshot page client-side.
  // Server-side pagination for the base list stays in fetchDeviceSnapshots so the
  // filter narrows the visible items without hiding pagination controls.
  const visibleDeviceSnapshots = computed(() => {
    const criteria: SnapshotFilterCriteria = {
      keyword: snapshotFilterKeyword.value,
      status: snapshotFilterStatus.value,
      alarmLevel: snapshotFilterAlarmLevel.value,
      groupId: snapshotFilterGroupId.value
    }
    return toValue(options.deviceSnapshots).filter((device) => matchSnapshotFilters(device, criteria))
  })

  function resetSnapshotFilters() {
    snapshotFilterKeyword.value = ''
    snapshotFilterStatus.value = 'all'
    snapshotFilterAlarmLevel.value = 'all'
    snapshotFilterGroupId.value = null
  }

  function removeSnapshotFilter(key: string) {
    if (key === 'keyword') snapshotFilterKeyword.value = ''
    else if (key === 'status') snapshotFilterStatus.value = 'all'
    else if (key === 'alarmLevel') snapshotFilterAlarmLevel.value = 'all'
    else if (key === 'group') snapshotFilterGroupId.value = null
  }

  function toggleSnapshotAdvancedFilters() {
    snapshotFilterAdvancedVisible.value = !snapshotFilterAdvancedVisible.value
  }

  // loadSnapshotGroupOptions fetches the device-group tree once and flattens the
  // labels for filter-chip lookup. Missing groups fall back to the raw id so a
  // stale filter still renders meaningfully.
  async function loadSnapshotGroupOptions() {
    try {
      const res = await deviceGroupTree({})
      const rootNodes = Array.isArray(res?.data) ? res.data : []
      const nameMap: Record<string, string> = {}
      function convert(node: any): TreeSelectOption {
        const group = node?.group || {}
        const children = Array.isArray(node?.children) ? node.children : []
        const id = String(group.id ?? '')
        const label = String(group.name ?? id ?? '')
        if (id) nameMap[id] = label
        const option: TreeSelectOption = { key: id, label }
        if (children.length > 0) option.children = children.map(convert)
        return option
      }
      snapshotGroupOptions.value = rootNodes.map(convert)
      snapshotGroupNameById.value = nameMap
    } catch {
      // A missing group tree only degrades the optional filter; keep the rest of
      // the overview page usable when the backend is unavailable.
      snapshotGroupOptions.value = []
      snapshotGroupNameById.value = {}
    }
  }

  return {
    snapshotFilterKeyword,
    snapshotFilterStatus,
    snapshotFilterAlarmLevel,
    snapshotFilterGroupId,
    snapshotFilterAdvancedVisible,
    snapshotGroupOptions,
    snapshotGroupNameById,
    snapshotStatusOptions,
    snapshotAlarmLevelOptions,
    snapshotHasActiveFilters,
    snapshotActiveFilterChips,
    visibleDeviceSnapshots,
    resetSnapshotFilters,
    removeSnapshotFilter,
    toggleSnapshotAdvancedFilters,
    loadSnapshotGroupOptions
  }
}

