/**
 * 文件用途: 覆盖TelemetryDataCards在移动端设备详情场景下的前端行为与契约。
 * 核心逻辑: 通过 Vitest、Vue Test Utils 和必要的接口 mock，验证关键渲染、交互和数据流。
 * 关键注意事项: Mock 数据要贴近真实接口字段，避免只证明组件能挂载。
 * 重构建议: 后续可抽取稳定的挂载工厂和业务 fixture，减少重复 mock 与选择器耦合。
 */
import { defineComponent, h } from 'vue'
import { flushPromises, shallowMount } from '@vue/test-utils'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const hoisted = vi.hoisted(() => ({
  telemetryDataCurrent: vi.fn()
}))

vi.mock('@/service/api/device', () => ({
  telemetryDataCurrent: hoisted.telemetryDataCurrent
}))

vi.mock('@/locales', () => ({
  $t: (key: string) => key
}))

vi.mock('@/utils/logger', () => ({
  createLogger: () => ({ info: vi.fn(), error: vi.fn(), warn: vi.fn() })
}))

vi.mock('dayjs', () => ({
  default: vi.fn(() => ({ format: vi.fn(() => '2024-01-01 12:00:00') }))
}))

vi.mock('@vicons/ionicons5', () => ({
  TrendingUpOutline: defineComponent({ setup: () => () => h('span') }),
  DocumentTextOutline: defineComponent({ setup: () => () => h('span') })
}))

vi.mock('../../device/details/modules/telemetry/modules/history-data.vue', () => ({
  default: defineComponent({ props: ['deviceId', 'theKey'], setup() { return () => h('div') } })
}))

vi.mock('../../device/details/modules/telemetry/modules/time-series-data.vue', () => ({
  default: defineComponent({ props: ['deviceId', 'theKey', 'theName', 'theUnit'], setup() { return () => h('div') } })
}))

import Component from '../telemetryDataCards.vue'

const mountedWrappers: Array<ReturnType<typeof shallowMount>> = []

const mountComponent = (props = {}) => {
  const wrapper = shallowMount(Component, {
    props: {
      id: 'device-1',
      cardHeight: 160,
      cardMargin: 15,
      ...props
    },
    global: {
      stubs: {
        NGrid: defineComponent({
          props: ['xGap', 'yGap', 'cols'],
          setup(stubProps, { slots }) {
            return () =>
              h('div', { 'data-test': 'telemetry-grid', 'data-cols': stubProps.cols as string }, slots.default?.())
          }
        }),
        NGi: defineComponent({ setup(_, { slots }) { return () => h('div', { 'data-test': 'telemetry-grid-item' }, slots.default?.()) } }),
        NCard: defineComponent({
          props: ['hoverable', 'headerClass'],
          setup(stubProps, { slots }) {
            return () =>
              h('article', { 'data-test': 'telemetry-card', 'data-hoverable': String(stubProps.hoverable), 'data-header-class': stubProps.headerClass as string }, [
                slots.header?.(),
                slots['header-extra']?.(),
                slots.default?.(),
                slots.footer?.()
              ])
          }
        }),
        NIcon: defineComponent({ props: ['size', 'color'], setup(_, { slots }) { return () => h('span', slots.default?.()) } }),
        NDivider: defineComponent({ props: ['vertical'], setup() { return () => h('hr') } }),
        NModal: defineComponent({
          props: ['show', 'title'],
          emits: ['update:show'],
          setup(stubProps, { slots }) {
            return () =>
              h('div', { 'data-test': 'history-modal', 'data-show': String(stubProps.show), 'data-title': stubProps.title as string }, slots.default?.())
          }
        }),
        AnimatedNumber: defineComponent({
          inheritAttrs: false,
          props: ['mNum', 'quantileShow'],
          setup(stubProps, { attrs }) {
            return () =>
              h('span', {
                ...attrs,
                'data-test': 'animated-number',
                'data-value': String(stubProps.mNum),
                'data-quantile': String(stubProps.quantileShow)
              })
          }
        }),
        HistoryData: defineComponent({ props: ['deviceId', 'theKey'], setup() { return () => h('div') } }),
        TimeSeriesData: defineComponent({ props: ['deviceId', 'theKey', 'theName', 'theUnit'], setup() { return () => h('div') } })
      }
    }
  })
  mountedWrappers.push(wrapper)
  return wrapper
}

const getSetupState = (wrapper: ReturnType<typeof shallowMount>) => wrapper.vm.$.setupState as Record<string, any>

describe('device-details-app/telemetryDataCards.vue', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    hoisted.telemetryDataCurrent.mockResolvedValue({
      data: [
        { key: 'temperature', value: 25.5, unit: '°C', ts: Date.now(), device_id: 'device-1', label: 'Temperature' },
        { key: 'humidity', value: 60, unit: '%', ts: Date.now(), device_id: 'device-1', label: 'Humidity' }
      ],
      error: null
    })
  })

  afterEach(() => {
    while (mountedWrappers.length > 0) {
      mountedWrappers.pop()?.unmount()
    }
  })

  it('renders telemetry card data with chart and history affordances', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    const cards = wrapper
      .findAll('[data-test="telemetry-card"]')
      .filter(card => card.text().includes('Temperature') || card.text().includes('Humidity'))

    expect(wrapper.get('[data-test="telemetry-grid"]').attributes('data-cols')).toBe('1 600:2 900:3 1200:4')
    expect(cards).toHaveLength(2)
    expect(wrapper.text()).toContain('Temperature')
    expect(wrapper.text()).toContain('(temperature)')
    expect(wrapper.text()).toContain('°C')
    expect(wrapper.text()).toContain('Humidity')
    expect(wrapper.text()).toContain('(humidity)')
    expect(wrapper.text()).toContain('%')
    expect(state.telemetryData.map((item: any) => String(item.value))).toEqual(['25.5', '60'])
    expect(wrapper.findAll('[data-test="animated-number"]').map(number => number.attributes())).toEqual([
      expect.objectContaining({ 'data-index': '0', 'data-value': '25.5', 'data-quantile': 'true' }),
      expect.objectContaining({ 'data-index': '1', 'data-value': '60', 'data-quantile': 'true' })
    ])
    expect(wrapper.get('[data-test="history-modal"]').attributes()).toMatchObject({
      'data-show': 'false',
      'data-title': 'generate.telemetry-history-data'
    })
    expect(state.telemetryData).toHaveLength(2)
    expect(state.telemetryData[0]).toMatchObject({ key: 'temperature', device_id: 'device-1' })
  })

  it('fetches telemetry data on mount', async () => {
    mountComponent()
    await flushPromises()
    expect(hoisted.telemetryDataCurrent).toHaveBeenCalledWith('device-1')
  })

  it('populates telemetryData on successful fetch', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(state.telemetryData).toHaveLength(2)
  })

  it('sets initTelemetryData from first item', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(state.telemetryData[0].key).toBe('temperature')
    expect(state.telemetryData[0].device_id).toBe('device-1')
  })

  it('isColor returns #cccccc for string values', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(state.isColor({ value: 'online' })).toBe('#cccccc')
  })

  it('isColor returns empty string for numeric values', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(state.isColor({ value: 25.5 })).toBe('')
  })

  it('onTapTableTools sets history state for numeric values', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    state.onTapTableTools({ value: 25.5, key: 'temp', device_id: 'dev-1', label: 'Temperature', unit: '°C' })
    expect(state.showHistory).toBe(true)
    expect(state.telemetryKey).toBe('temp')
    expect(state.telemetryId).toBe('dev-1')
    expect(state.modelType).toBe('custom.device_details.sequential')
  })

  it('onTapTableTools does nothing for string values', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    state.onTapTableTools({ value: 'online', key: 'status' })
    expect(state.showHistory).toBe(false)
  })

  it('accepts cardHeight and cardMargin props', async () => {
    const wrapper = mountComponent({ cardHeight: 200, cardMargin: 20 })
    await flushPromises()
    expect(wrapper.props('cardHeight')).toBe(200)
    expect(wrapper.props('cardMargin')).toBe(20)
  })

  it('handles empty telemetry data', async () => {
    hoisted.telemetryDataCurrent.mockResolvedValue({ data: [], error: null })
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(state.telemetryData).toHaveLength(0)
  })

  it('handles API error gracefully', async () => {
    hoisted.telemetryDataCurrent.mockResolvedValue({ data: null, error: true })
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(state.telemetryData).toHaveLength(0)
  })
})

import { describe, expect, it } from 'vitest'
import { buildBuiltInCommandTemplates } from '../commandCenterCommandTemplates'

describe('commandCenterCommandTemplates', () => {
  it('builds customer-safe built-in command templates', () => {
    const templates = buildBuiltInCommandTemplates()

    expect(templates.map((template) => template.key)).toEqual(['reboot', 'sync', 'diagnose'])
    expect(templates.map((template) => template.identify)).toEqual([
      'reboot',
      'sync_config',
      'collect_diagnostics'
    ])
    templates.forEach((template) => {
      expect(template.titleKey).toContain('custom.commandCenter.template')
      expect(template.descKey).toContain('custom.commandCenter.template')
      expect(template.timeoutSeconds).toBeGreaterThanOrEqual(60)
      expect(() => JSON.parse(template.value)).not.toThrow()
    })
  })

  it('keeps diagnostic collection broad enough for support handoff', () => {
    const diagnose = buildBuiltInCommandTemplates().find((template) => template.key === 'diagnose')
    expect(diagnose?.identify).toBe('collect_diagnostics')

    const payload = JSON.parse(diagnose?.value || '{}')
    expect(payload).toEqual({
      action: 'collect_diagnostics',
      include: ['status', 'logs', 'telemetry']
    })
  })
})

import { buildCommandCenterGuideSteps } from '../commandCenterGuide'

const actions = {
  openFleet: vi.fn(),
  previewCommandJob: vi.fn(),
  submitCommandJob: vi.fn()
}

describe('commandCenterGuide', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('points the operator back to fleet before a command scope exists', () => {
    const steps = buildCommandCenterGuideSteps(
      {
        hasCommandJobScope: false,
        hasCommandIdentifier: false,
        hasPreviewResult: false,
        hasSubmitResult: false,
        canPreviewCommandJob: false,
        canSubmitCommandJob: false,
        previewLoading: false,
        submitLoading: false
      },
      actions
    )

    expect(steps.map(step => step.key)).toEqual(['select', 'identify', 'preview', 'submit'])
    expect(steps[0]).toMatchObject({
      statusKey: 'custom.commandCenter.guideStatusAction',
      statusType: 'warning',
      disabled: false
    })
    expect(steps[2]).toMatchObject({
      statusKey: 'custom.commandCenter.guideStatusWait',
      statusType: 'default',
      disabled: true
    })
    expect(steps[3]).toMatchObject({
      statusKey: 'custom.commandCenter.guideStatusWait',
      statusType: 'default',
      disabled: true
    })
  })

  it('enables preview only after a scope exists and no preview is loading', () => {
    const steps = buildCommandCenterGuideSteps(
      {
        hasCommandJobScope: true,
        hasCommandIdentifier: true,
        hasPreviewResult: false,
        hasSubmitResult: false,
        canPreviewCommandJob: true,
        canSubmitCommandJob: false,
        previewLoading: false,
        submitLoading: false
      },
      actions
    )

    expect(steps[0]).toMatchObject({
      statusKey: 'custom.commandCenter.guideStatusReady',
      statusType: 'success'
    })
    expect(steps[1]).toMatchObject({
      statusKey: 'custom.commandCenter.guideStatusReady',
      statusType: 'success',
      disabled: true
    })
    expect(steps[2]).toMatchObject({
      action: actions.previewCommandJob,
      disabled: false
    })
  })

  it('shows submit as the next action only when the preview token is still valid', () => {
    const steps = buildCommandCenterGuideSteps(
      {
        hasCommandJobScope: true,
        hasCommandIdentifier: true,
        hasPreviewResult: false,
        hasSubmitResult: false,
        canPreviewCommandJob: true,
        canSubmitCommandJob: true,
        previewLoading: false,
        submitLoading: false
      },
      actions
    )

    expect(steps[3]).toMatchObject({
      statusKey: 'custom.commandCenter.guideStatusAction',
      statusType: 'warning',
      action: actions.submitCommandJob,
      disabled: false
    })
  })

  it('marks the job flow ready after submission and blocks duplicate submits while loading', () => {
    const steps = buildCommandCenterGuideSteps(
      {
        hasCommandJobScope: true,
        hasCommandIdentifier: true,
        hasPreviewResult: true,
        hasSubmitResult: true,
        canPreviewCommandJob: true,
        canSubmitCommandJob: true,
        previewLoading: false,
        submitLoading: true
      },
      actions
    )

    expect(steps[2]).toMatchObject({
      statusKey: 'custom.commandCenter.guideStatusReady',
      statusType: 'success'
    })
    expect(steps[3]).toMatchObject({
      statusKey: 'custom.commandCenter.guideStatusReady',
      statusType: 'success',
      disabled: true
    })
  })
})

import { afterEach, describe, expect, it, vi } from 'vitest'
import { useCommandCenterSavedFleetFilters } from '../useCommandCenterSavedFleetFilters'
import { createSavedFleetFilter, FLEET_SAVED_FILTER_STORAGE_KEY } from '../../manage/device-fleet-saved-filters'
import { deleteFleetSavedFilter, listFleetSavedFilters, updateFleetSavedFilter } from '@/service/api/device'

vi.mock('@/service/api/device', () => ({
  deleteFleetSavedFilter: vi.fn(),
  listFleetSavedFilters: vi.fn(),
  updateFleetSavedFilter: vi.fn()
}))

const mockedDeleteFleetSavedFilter = vi.mocked(deleteFleetSavedFilter)
const mockedListFleetSavedFilters = vi.mocked(listFleetSavedFilters)
const mockedUpdateFleetSavedFilter = vi.mocked(updateFleetSavedFilter)

const createStorage = (initialValue: string | null = null) => {
  let value = initialValue
  return {
    getItem: vi.fn(() => value),
    setItem: vi.fn((_: string, nextValue: string) => {
      value = nextValue
    })
  }
}

describe('useCommandCenterSavedFleetFilters', () => {
  afterEach(() => {
    vi.clearAllMocks()
    vi.unstubAllGlobals()
  })

  it('merges server filters into the command-center picker and syncs the route selection', async () => {
    const storage = createStorage()
    vi.stubGlobal('window', { localStorage: storage })
    mockedListFleetSavedFilters.mockResolvedValue({
      data: {
        list: [
          {
            id: 'server-filter-1',
            name: 'Online pumps',
            device_filter: { is_online: 1, unsafe: 'ignored' },
            preview_total: 12,
            created_at: '2026-07-05T12:00:00Z'
          }
        ]
      }
    } as any)

    const state = useCommandCenterSavedFleetFilters({
      getRouteSavedFilterId: () => 'server-filter-1'
    })

    await state.refreshCommandCenterSavedFilters()

    expect(state.selectedSavedFleetFilterId.value).toBe('server-filter-1')
    expect(state.savedFleetFilterStatus.value).toBe('server')
    expect(state.savedFleetFilterNoticeKey.value).toBe('')
    expect(state.activeSavedFleetFilter.value).toMatchObject({
      id: 'server-filter-1',
      name: 'Online pumps',
      previewTotal: 12
    })
    expect(state.savedFleetFilterOptions.value).toEqual([{ label: 'Online pumps (12)', value: 'server-filter-1' }])
    expect(storage.setItem).toHaveBeenCalledWith(
      FLEET_SAVED_FILTER_STORAGE_KEY,
      expect.stringContaining('server-filter-1')
    )
  })

  it('keeps local saved filters when the backend list cannot be loaded', async () => {
    const localFilter = createSavedFleetFilter({ is_online: 1 }, 5, new Date('2026-07-05T02:00:00.000Z'))
    const storage = createStorage(JSON.stringify([localFilter]))
    vi.stubGlobal('window', { localStorage: storage })
    mockedListFleetSavedFilters.mockRejectedValue(new Error('network unavailable'))

    const state = useCommandCenterSavedFleetFilters({
      getRouteSavedFilterId: () => localFilter.id
    })

    await state.refreshCommandCenterSavedFilters()

    expect(state.savedFleetFilters.value).toEqual([localFilter])
