})

import type { CommandJobRowsStatusFilter, FleetCommandJobSubmitResult } from '@/service/api/device'
import { buildCommandJobRowFacts } from './commandCenterJobRowFacts'

type Translate = (key: string) => string

export interface CommandJobTroubleshootingRow {
  key: string
  label: string
  value: string
  reviewRowsStatusFilter?: CommandJobRowsStatusFilter
  type: 'success' | 'info' | 'warning' | 'error'
}

export interface CommandJobOperatorNextAction {
  key:
    | 'retry'
    | 'retry-waiting'
    | 'retry-exhausted'
    | 'refresh'
    | 'logs'
    | 'blocked'
    | 'device-response'
    | 'support'
    | 'done'
  title: string
  description: string
  evidence: string
  primaryActionLabel: string
  primaryAction:
    | 'refresh'
    | 'retry'
    | 'copy-retryable'
    | 'preview-support'
    | 'copy-link'
    | 'none'
  reviewRowsStatusFilter?: CommandJobRowsStatusFilter
  type: 'success' | 'info' | 'warning' | 'error'
}

export interface CommandJobActionConsequenceRow {
  key: 'cancel' | 'retry' | 'waiting' | 'exhausted' | 'device-response' | 'logs'
  label: string
  value: string
  reviewRowsStatusFilter?: CommandJobRowsStatusFilter
  type: 'success' | 'info' | 'warning' | 'error'
}

type CommandJobOperatorDecisionFacts = {
  retryableCount: number
  retryReadyCount: number
  retryWaitingCount: number
  retryExhaustedCount: number
  missingLogCount: number
  pendingCount: number
  deviceFailedCount: number
  blockedCount: number
}

const buildCommandJobOperatorDecisionFacts = (
  result: FleetCommandJobSubmitResult
): CommandJobOperatorDecisionFacts => {
  const rowFacts = buildCommandJobRowFacts(result)
  return {
    retryableCount: result.retryable_count ?? rowFacts.retryableRows.length,
    retryReadyCount: result.retry_ready_count ?? rowFacts.retryReadyRows.length,
    retryWaitingCount: result.retry_waiting_count ?? rowFacts.retryWaitingRows.length,
    retryExhaustedCount: result.retry_exhausted_count ?? rowFacts.retryExhaustedRows.length,
    missingLogCount: result.log_missing_count ?? rowFacts.logMissingRows.length,
    pendingCount:
      result.progress_health?.pending_count ??
      Math.max(0, result.requested_count - (result.submitted_count || 0) - (result.failed_count || 0)),
    deviceFailedCount: rowFacts.deviceFailedRows.length,
    blockedCount: result.blocked_count || 0
  }
}

export function buildCommandJobActionConsequenceRows(
  result: FleetCommandJobSubmitResult | null,
  t: Translate
): CommandJobActionConsequenceRow[] {
  if (!result) return []

  const facts = buildCommandJobOperatorDecisionFacts(result)
  const rows: CommandJobActionConsequenceRow[] = [
    {
      key: 'cancel',
      label: t('custom.commandCenter.cancelJob'),
      value: result.can_cancel
        ? t('custom.commandCenter.actionConsequenceCancel')
            .replace('{pending}', String(facts.pendingCount))
            .replace('{status}', result.status)
        : t('custom.commandCenter.actionConsequenceCancelUnavailable').replace('{status}', result.status),
      reviewRowsStatusFilter: result.can_cancel && facts.pendingCount > 0 ? 'in_progress' : undefined,
      type: result.can_cancel ? 'warning' : 'info'
    },
    {
      key: 'retry',
      label: t('custom.commandCenter.retryFailedJob'),
      value: result.can_retry_failed
        ? t('custom.commandCenter.actionConsequenceRetry')
            .replace('{ready}', String(facts.retryReadyCount))
            .replace('{waiting}', String(facts.retryWaitingCount))
            .replace('{exhausted}', String(facts.retryExhaustedCount))
        : t('custom.commandCenter.actionConsequenceRetryUnavailable'),
      reviewRowsStatusFilter: result.can_retry_failed && facts.retryReadyCount > 0 ? 'retry_ready' : undefined,
      type: result.can_retry_failed && facts.retryReadyCount > 0 ? 'error' : 'info'
    }
  ]

  if (facts.retryWaitingCount > 0) {
    rows.push({
      key: 'waiting',
      label: t('custom.commandCenter.supportBundleRetryWaitingDevices'),
      value: t('custom.commandCenter.actionConsequenceWaiting').replace('{count}', String(facts.retryWaitingCount)),
      reviewRowsStatusFilter: 'retry_waiting',
      type: 'warning'
    })
  }

  if (facts.retryExhaustedCount > 0) {
    rows.push({
      key: 'exhausted',
      label: t('custom.commandCenter.supportBundleRetryExhaustedDevices'),
      value: t('custom.commandCenter.actionConsequenceExhausted').replace('{count}', String(facts.retryExhaustedCount)),
      reviewRowsStatusFilter: 'retry_exhausted',
      type: 'error'
    })
  }

  if (facts.deviceFailedCount > 0) {
    rows.push({
      key: 'device-response',
      label: t('custom.commandCenter.jobAttentionDeviceFailed'),
      value: t('custom.commandCenter.actionConsequenceDeviceFailed').replace('{count}', String(facts.deviceFailedCount)),
      reviewRowsStatusFilter: 'device_failed',
      type: 'error'
    })
  }

  if (facts.missingLogCount > 0) {
    rows.push({
      key: 'logs',
      label: t('custom.commandCenter.jobAttentionMissingLog'),
      value: t('custom.commandCenter.actionConsequenceLogs').replace('{count}', String(facts.missingLogCount)),
      reviewRowsStatusFilter: 'missing_log',
      type: 'warning'
    })
  }

  return rows
}

export function buildCommandJobTroubleshootingRows(
  result: FleetCommandJobSubmitResult | null,
  t: Translate
): CommandJobTroubleshootingRow[] {
  if (!result) return []

  const rows: CommandJobTroubleshootingRow[] = []
  const facts = buildCommandJobOperatorDecisionFacts(result)

  if (result.can_retry_failed && facts.retryReadyCount > 0) {
    rows.push({
      key: 'retry',
      label: t('custom.commandCenter.troubleshootingRetryTitle'),
      value: t('custom.commandCenter.troubleshootingRetryDesc').replace('{count}', String(facts.retryReadyCount)),
      reviewRowsStatusFilter: 'retry_ready',
      type: 'error'
    })
  }

  if (facts.retryWaitingCount > 0) {
    rows.push({
      key: 'retry-waiting',
      label: t('custom.commandCenter.troubleshootingRetryWaitingTitle'),
      value: t('custom.commandCenter.troubleshootingRetryWaitingDesc').replace('{count}', String(facts.retryWaitingCount)),
      reviewRowsStatusFilter: 'retry_waiting',
      type: 'warning'
    })
  }

  if (facts.retryExhaustedCount > 0) {
    rows.push({
      key: 'retry-exhausted',
      label: t('custom.commandCenter.troubleshootingRetryExhaustedTitle'),
      value: t('custom.commandCenter.troubleshootingRetryExhaustedDesc').replace('{count}', String(facts.retryExhaustedCount)),
      reviewRowsStatusFilter: 'retry_exhausted',
      type: 'error'
    })
  }

  if (result.can_cancel && facts.pendingCount > 0) {
    rows.push({
      key: 'cancel',
      label: t('custom.commandCenter.troubleshootingCancelTitle'),
      value: t('custom.commandCenter.troubleshootingCancelDesc').replace('{count}', String(facts.pendingCount)),
      reviewRowsStatusFilter: 'in_progress',
      type: 'warning'
    })
  }

  if (facts.missingLogCount > 0) {
    rows.push({
      key: 'logs',
      label: t('custom.commandCenter.troubleshootingLogsTitle'),
      value: t('custom.commandCenter.troubleshootingLogsDesc').replace('{count}', String(facts.missingLogCount)),
      reviewRowsStatusFilter: 'missing_log',
      type: 'warning'
    })
  }

  if (facts.blockedCount > 0) {
    rows.push({
      key: 'blocked',
      label: t('custom.commandCenter.troubleshootingBlockedTitle'),
      value: t('custom.commandCenter.troubleshootingBlockedDesc').replace('{count}', String(facts.blockedCount)),
      reviewRowsStatusFilter: 'needs_attention',
      type: 'error'
    })
  }

  if (rows.length === 0) {
    rows.push({
      key: 'support',
      label: t('custom.commandCenter.troubleshootingSupportTitle'),
      value: t('custom.commandCenter.troubleshootingSupportDesc'),
      type: result.status === 'completed' ? 'success' : 'info'
    })
  }

  return rows
}

export function buildCommandJobOperatorNextAction(
  result: FleetCommandJobSubmitResult | null,
  t: Translate
): CommandJobOperatorNextAction | null {
  if (!result) return null

  const facts = buildCommandJobOperatorDecisionFacts(result)
  const evidence = t('custom.commandCenter.operatorDecisionEvidence')
    .replace('{retryable}', String(facts.retryableCount))
    .replace('{pending}', String(facts.pendingCount))
    .replace('{missingLogs}', String(facts.missingLogCount))
    .replace('{blocked}', String(facts.blockedCount))
    .replace('{deviceFailed}', String(facts.deviceFailedCount))

  if (facts.deviceFailedCount > 0) {
    return {
      key: 'device-response',
      title: t('custom.commandCenter.operatorDecisionDeviceFailedTitle'),
      description: t('custom.commandCenter.operatorDecisionDeviceFailedDesc').replace('{count}', String(facts.deviceFailedCount)),
      evidence,
      primaryActionLabel: t('custom.commandCenter.previewSupportBundle'),
      primaryAction: 'preview-support',
      reviewRowsStatusFilter: 'device_failed',
      type: 'error'
    }
  }

  if (result.can_retry_failed && facts.retryReadyCount > 0) {
    return {
      key: 'retry',
      title: t('custom.commandCenter.operatorDecisionRetryTitle'),
      description: t('custom.commandCenter.operatorDecisionRetryDesc').replace('{count}', String(facts.retryReadyCount)),
      evidence,
      primaryActionLabel: t('custom.commandCenter.retryFailedJob'),
      primaryAction: 'retry',
      reviewRowsStatusFilter: 'retry_ready',
      type: 'error'
    }
  }

  if (facts.retryWaitingCount > 0) {
    return {
      key: 'retry-waiting',
      title: t('custom.commandCenter.operatorDecisionRetryWaitingTitle'),
      description: t('custom.commandCenter.operatorDecisionRetryWaitingDesc').replace('{count}', String(facts.retryWaitingCount)),
      evidence,
      primaryActionLabel: t('custom.commandCenter.refreshJob'),
      primaryAction: 'refresh',
      reviewRowsStatusFilter: 'retry_waiting',
      type: 'warning'
    }
  }

  if (facts.retryExhaustedCount > 0) {
    return {
      key: 'retry-exhausted',
      title: t('custom.commandCenter.operatorDecisionRetryExhaustedTitle'),
      description: t('custom.commandCenter.operatorDecisionRetryExhaustedDesc').replace('{count}', String(facts.retryExhaustedCount)),
      evidence,
      primaryActionLabel: t('custom.commandCenter.previewSupportBundle'),
      primaryAction: 'preview-support',
      reviewRowsStatusFilter: 'retry_exhausted',
      type: 'error'
    }
  }

  if (result.status === 'running' || facts.pendingCount > 0) {
    return {
      key: 'refresh',
      title: t('custom.commandCenter.operatorDecisionRefreshTitle'),
      description: t('custom.commandCenter.operatorDecisionRefreshDesc').replace('{count}', String(facts.pendingCount)),
      evidence,
      primaryActionLabel: t('custom.commandCenter.refreshJob'),
      primaryAction: 'refresh',
      reviewRowsStatusFilter: 'in_progress',
      type: 'info'
    }
  }

  if (facts.missingLogCount > 0) {
    return {
      key: 'logs',
      title: t('custom.commandCenter.operatorDecisionLogsTitle'),
      description: t('custom.commandCenter.operatorDecisionLogsDesc').replace('{count}', String(facts.missingLogCount)),
      evidence,
      primaryActionLabel: t('custom.commandCenter.refreshJob'),
      primaryAction: 'refresh',
      reviewRowsStatusFilter: 'missing_log',
      type: 'warning'
    }
  }

  if (facts.blockedCount > 0) {
    return {
      key: 'blocked',
      title: t('custom.commandCenter.operatorDecisionBlockedTitle'),
      description: t('custom.commandCenter.operatorDecisionBlockedDesc').replace('{count}', String(facts.blockedCount)),
      evidence,
      primaryActionLabel: t('custom.commandCenter.copyJobLink'),
      primaryAction: 'copy-link',
      reviewRowsStatusFilter: 'needs_attention',
      type: 'error'
    }
  }

  if (result.status === 'completed') {
    return {
      key: 'done',
      title: t('custom.commandCenter.operatorDecisionDoneTitle'),
      description: t('custom.commandCenter.operatorDecisionDoneDesc'),
      evidence,
      primaryActionLabel: t('custom.commandCenter.copyJobLink'),
      primaryAction: 'copy-link',
      type: 'success'
    }
  }

  return {
    key: 'support',
    title: t('custom.commandCenter.operatorDecisionSupportTitle'),
    description: t('custom.commandCenter.operatorDecisionSupportDesc'),
    evidence,
    primaryActionLabel: t('custom.commandCenter.previewSupportBundle'),
    primaryAction: 'preview-support',
    type: 'info'
  }
}

import type {
  FleetCommandJobExecutionSummary,
  FleetCommandJobGovernanceSummary,
  FleetCommandJobSupportBundle,
  FleetCommandJobSupportDiagnostic
} from '@/service/api/device'

type Translate = (key: string) => string

export interface CommandJobLabelValueRow {
  key?: string
  label: string
  value: string
}

export interface CommandJobSupportBundlePreview {
  summaryRows: CommandJobLabelValueRow[]
  executionSummary: CommandJobExecutionSummaryCard | null
  governanceSummary: CommandJobGovernanceSummaryCard | null
  nextActions: string[]
  failedDeviceEvidence: CommandJobSupportFailedDeviceEvidence[]
}

export interface CommandJobSupportFailedDeviceEvidence {
  key: string
  deviceId: string
  detailId?: string
  readyCheckUrl?: string
  jobDetailUrl?: string
  diagnosticSummary?: CommandJobSupportDiagnosticPreview
  rows: CommandJobLabelValueRow[]
}

export interface CommandJobSupportDiagnosticPreview {
  type: 'success' | 'info' | 'warning' | 'error'
  code: string
  summary: string
  evidence: string[]
  nextActions: string[]
}

export interface CommandJobExecutionSummaryCard {
  pathLabel: string
  decisionLabel: string
  canClose: boolean
  closeBlockers: string[]
  nextAction: string
  type: 'success' | 'info' | 'warning' | 'error'
  evidence: string[]
  checklist: CommandJobExecutionChecklistItem[]
}

export interface CommandJobExecutionChecklistItem {
  key: string
  label: string
  detail: string
  stateLabel: string
  type: 'success' | 'info' | 'warning' | 'error'
}

export interface CommandJobGovernanceSummaryCard {
  title: string
  levelLabel: string
  summary: string
  nextAction: string
  type: 'success' | 'info' | 'warning' | 'error'
  items: CommandJobGovernanceSummaryItem[]
}

export interface CommandJobGovernanceSummaryItem {
  key: string
  label: string
  value: string
  detail: string
  stateLabel: string
  type: 'success' | 'info' | 'warning' | 'error'
}

const commandJobExecutionDecisionType = (decision: string): CommandJobExecutionSummaryCard['type'] => {
  if (decision === 'close') return 'success'
  if (decision === 'monitor') return 'info'
  if (decision === 'wait' || decision === 'watch_timeout' || decision === 'collect_evidence') return 'warning'
  return 'error'
}

const commandJobChecklistStateType = (state: string): CommandJobExecutionChecklistItem['type'] => {
  if (state === 'done') return 'success'
  if (state === 'watch') return 'warning'
  if (state === 'blocked') return 'error'
  if (state === 'todo') return 'error'
  return 'info'
}

const commandJobGovernanceLevelType = (level: string): CommandJobGovernanceSummaryCard['type'] => {
  if (level === 'success') return 'success'
  if (level === 'warning') return 'warning'
  if (level === 'error' || level === 'blocked') return 'error'
  return 'info'
}

const commandJobGovernanceStateType = (state: string): CommandJobGovernanceSummaryItem['type'] => {
  if (state === 'done') return 'success'
  if (state === 'blocked') return 'error'
  if (state === 'watch' || state === 'todo') return 'warning'
  return 'info'
}

const formatCommandJobDateTime = (value?: string) => {
  if (!value) return '--'
  return value
    .replace('T', ' ')
    .replace(/\.\d+Z$/, ' UTC')
    .replace(/Z$/, ' UTC')
}

const formatCommandJobStatus = (status: string | undefined, t: Translate) => {
  if (!status) return '-'
  const key = `custom.commandCenter.jobStatus.${status}`
  const translated = t(key)
  return translated === key ? status : translated
}

const formatCommandJobReadiness = (readiness: string[] | undefined) => {
  const items = readiness?.filter(Boolean) ?? []
  return items.length ? items.join(', ') : '-'
}

const formatCommandJobResponseStatus = (statusLabel: string | undefined, t: Translate) => {
  if (!statusLabel) return t('custom.commandCenter.responseStatus.awaiting')
  const key = `custom.commandCenter.responseStatus.${statusLabel}`
  const translated = t(key)
  return translated === key ? statusLabel : translated
}

const formatCommandJobDispatchAttempts = (attempts?: number, maxAttempts?: number) => {
  const used = attempts ?? 0
  return maxAttempts ? `${used}/${maxAttempts}` : String(used)
}

const formatCommandJobRetryState = (state: string | undefined, t: Translate) => {
  if (!state) return '-'
  const key = `custom.commandCenter.retryState.${state}`
  const translated = t(key)
  return translated === key ? state : translated
}

const normalizeCommandJobSupportDiagnosticType = (
  level: string | undefined
): CommandJobSupportDiagnosticPreview['type'] => {
  if (level === 'ok' || level === 'success') return 'success'
  if (level === 'warning') return 'warning'
  if (level === 'error') return 'error'
  return 'info'
}

const formatCommandJobDiagnosticEvidence = (item: string, t: Translate) => {
  const attemptsPrefix = 'dispatch_attempts='
  if (item.startsWith(attemptsPrefix)) {
    return `${t('custom.commandCenter.dispatchAttempts')}: ${item.slice(attemptsPrefix.length)}`
  }
  const maxAttemptsPrefix = 'max_dispatch_attempts='
  if (item.startsWith(maxAttemptsPrefix)) {
    return `${t('custom.commandCenter.maxDispatchAttempts')}: ${item.slice(maxAttemptsPrefix.length)}`
  }
  const retryStatePrefix = 'retry_state='
  if (item.startsWith(retryStatePrefix)) {
    return `${t('custom.commandCenter.retryState')}: ${formatCommandJobRetryState(item.slice(retryStatePrefix.length), t)}`
  }
  const nextRetryPrefix = 'next_retry_after='
  if (item.startsWith(nextRetryPrefix)) {
    return `${t('custom.commandCenter.nextRetryAfter')}: ${formatCommandJobDateTime(item.slice(nextRetryPrefix.length))}`
  }
  return item
}

const buildCommandJobExecutionSummaryPreview = (
  summary: FleetCommandJobExecutionSummary | undefined,
  t: Translate
): CommandJobExecutionSummaryCard | null => {
  if (!summary) return null
  const decisionKey = `custom.commandCenter.executionDecision.${summary.decision}`
  const translatedDecision = t(decisionKey)

  return {
    pathLabel: summary.path_label || summary.path_type || '-',
    decisionLabel: translatedDecision === decisionKey ? summary.decision : translatedDecision,
    canClose: Boolean(summary.can_close),
    closeBlockers: summary.close_blockers?.filter(Boolean) ?? [],
    nextAction: summary.next_action,
    type: commandJobExecutionDecisionType(summary.decision),
    evidence: summary.evidence?.filter(Boolean) ?? [],
    checklist: (summary.checklist ?? []).map((item) => {
      const stateKey = `custom.commandCenter.executionChecklistState.${item.state}`
      const translatedState = t(stateKey)
      return {
        key: item.key || item.label,
        label: item.label || item.key,
        detail: item.detail || '-',
        stateLabel: translatedState === stateKey ? item.state : translatedState,
        type: commandJobChecklistStateType(item.state)
      }
    })
  }
}

export const buildCommandJobExecutionSummaryCard = (
  result: { execution_summary?: FleetCommandJobExecutionSummary } | null,
  t: Translate
): CommandJobExecutionSummaryCard | null => {
  if (!result?.execution_summary) return null
  return buildCommandJobExecutionSummaryPreview(result.execution_summary, t)
}

const buildCommandJobGovernanceSummaryPreview = (
  summary: FleetCommandJobGovernanceSummary | undefined,
  t: Translate
): CommandJobGovernanceSummaryCard | null => {
  if (!summary) return null
  const levelKey = `custom.commandCenter.governanceLevel.${summary.level}`
  const translatedLevel = t(levelKey)
  return {
    title: summary.title || t('custom.commandCenter.governanceSummaryTitle'),
    levelLabel: translatedLevel === levelKey ? summary.level || 'info' : translatedLevel,
    summary: summary.summary || '-',
    nextAction: summary.next_action || '-',
    type: commandJobGovernanceLevelType(summary.level),
    items: (summary.items ?? []).map((item) => {
      const stateKey = `custom.commandCenter.governanceState.${item.state}`
      const translatedState = t(stateKey)
      return {
        key: item.key || item.label,
        label: item.label || item.key,
        value: item.value || '-',
        detail: item.detail || '-',
        stateLabel: translatedState === stateKey ? item.state : translatedState,
        type: commandJobGovernanceStateType(item.state)
      }
    })
  }
}

const buildCommandJobSupportDiagnosticPreview = (
  diagnostic: FleetCommandJobSupportDiagnostic | undefined,
  t: Translate
): CommandJobSupportDiagnosticPreview | undefined => {
  if (!diagnostic) return undefined
  return {
    type: normalizeCommandJobSupportDiagnosticType(diagnostic.level),
    code: diagnostic.code || '-',
    summary: diagnostic.summary || diagnostic.code || '-',
    evidence: diagnostic.evidence?.filter(Boolean).map((item) => formatCommandJobDiagnosticEvidence(item, t)) ?? [],
    nextActions: diagnostic.next_actions?.filter(Boolean) ?? []
  }
}

export const buildCommandJobSupportBundlePreview = (
  bundle: FleetCommandJobSupportBundle | null,
  t: Translate
): CommandJobSupportBundlePreview | null => {
  if (!bundle) return null

  return {
    summaryRows: [
      { label: t('custom.commandCenter.supportBundleGeneratedAt'), value: formatCommandJobDateTime(bundle.generated_at) },
      ...(bundle.scheduled_at
        ? [{ label: t('custom.commandCenter.scheduledAt'), value: formatCommandJobDateTime(bundle.scheduled_at) }]
        : []),
      ...(bundle.next_dispatch_at
        ? [{ label: t('custom.commandCenter.nextDispatchAt'), value: formatCommandJobDateTime(bundle.next_dispatch_at) }]
        : []),
      {
        label: t('custom.commandCenter.supportBundleRetryableDevices'),
        value: String(bundle.retryable_device_ids?.length ?? 0)
      },
      {
        label: t('custom.commandCenter.supportBundleRetryReadyDevices'),
        value: String(bundle.retry_ready_count ?? 0)
      },
      {
        label: t('custom.commandCenter.supportBundleRetryWaitingDevices'),
        value: String(bundle.retry_waiting_count ?? 0)
      },
      {
        label: t('custom.commandCenter.supportBundleRetryExhaustedDevices'),
        value: String(bundle.retry_exhausted_count ?? 0)
      },
      {
        label: t('custom.commandCenter.supportBundleMissingLogDevices'),
        value: String(bundle.missing_log_device_ids?.length ?? 0)
      },
      { label: t('custom.commandCenter.supportBundleFailedDevices'), value: String(bundle.failed_devices?.length ?? 0) },
      { label: t('custom.commandCenter.supportBundleEvents'), value: String(bundle.events?.length ?? 0) },
      { label: t('custom.commandCenter.supportBundleShareHint'), value: bundle.share_hint || '-' }
    ],
    executionSummary: buildCommandJobExecutionSummaryPreview(bundle.execution_summary, t),
    governanceSummary: buildCommandJobGovernanceSummaryPreview(bundle.governance_summary, t),
    nextActions: bundle.next_actions ?? [],
    failedDeviceEvidence: (bundle.failed_devices ?? []).slice(0, 5).map((device, index) => {
      const diagnosticSummary = buildCommandJobSupportDiagnosticPreview(device.diagnostic_summary, t)
      const rows = [
        {
          label: t('custom.commandCenter.supportBundleDevice'),
          value: device.device_number || device.name || device.device_id
        },
        { label: t('common.status'), value: formatCommandJobStatus(device.status, t) },
        { label: t('custom.commandCenter.readinessEvidence'), value: formatCommandJobReadiness(device.readiness) },
        { label: t('custom.commandCenter.reason'), value: device.reason || '-' },
        { label: t('custom.commandCenter.advice'), value: device.advice || '-' },
        {
          label: t('custom.commandCenter.dispatchAttempts'),
          value: formatCommandJobDispatchAttempts(device.dispatch_attempts, device.max_dispatch_attempts)
        },
        {
          label: t('custom.commandCenter.retryState'),
          value: formatCommandJobRetryState(device.retry_state, t)
        },
        {
          label: t('custom.commandCenter.nextRetryAfter'),
          value: formatCommandJobDateTime(device.next_retry_after)
        },
        { label: t('custom.commandCenter.messageId'), value: device.message_id || '-' }
      ]
      if (device.response_status_label || device.response_status) {
        rows.push({
          label: t('custom.commandCenter.deviceResponseStatus'),
          value: formatCommandJobResponseStatus(device.response_status_label, t)
        })
      }
      if (device.response_error || device.response_data) {
        rows.push({
          label: t('custom.commandCenter.deviceResponseEvidence'),
          value: device.response_error || device.response_data || '-'
        })
      }
      return {
        key: device.device_id || device.message_id || `support-device-${index}`,
        deviceId: device.device_id,
        detailId: device.detail_id,
        readyCheckUrl: device.ready_check_url,
        jobDetailUrl: device.job_detail_url,
        diagnosticSummary,
        rows
      }
    })
  }
}

