import { ref, watch } from 'vue'
import type { Ref } from 'vue'

type ReadonlyRef<T> = {
  readonly value: T
}

interface CommandCenterRouteDraftShape {
  identify: string
  value: string
  source: string
  timeoutSeconds: number | null
  signature: string
  hasDraft: boolean
}

interface UseCommandCenterRouteDraftSyncOptions {
  routeCommandDraft: ReadonlyRef<CommandCenterRouteDraftShape>
  commandIdentify: Ref<string>
  commandValue: Ref<string>
  timeoutSeconds: Ref<number | null>
  resetCommandJobDraft: () => void
}

export function useCommandCenterRouteDraftSync(options: UseCommandCenterRouteDraftSyncOptions) {
  const reusedCommandJobDraft = ref<{ jobId: string; identify: string } | null>(null)
  const routeCommandDraftNotice = ref<{ identify: string; source: string } | null>(null)
  const appliedRouteCommandDraftSignature = ref('')

  const clearReusedCommandJobDraft = () => {
    reusedCommandJobDraft.value = null
  }

  const clearRouteCommandDraftNotice = () => {
    routeCommandDraftNotice.value = null
  }

  const applyRouteCommandDraft = () => {
    const draft = options.routeCommandDraft.value
    if (!draft.hasDraft || draft.signature === appliedRouteCommandDraftSignature.value) return

    options.commandIdentify.value = draft.identify
    options.commandValue.value = draft.value
    if (draft.timeoutSeconds) {
      options.timeoutSeconds.value = draft.timeoutSeconds
    }
    reusedCommandJobDraft.value = null
    routeCommandDraftNotice.value = {
      identify: draft.identify,
      source: draft.source
    }
    appliedRouteCommandDraftSignature.value = draft.signature
    options.resetCommandJobDraft()
  }

  watch(options.commandIdentify, identify => {
    if (reusedCommandJobDraft.value && identify !== reusedCommandJobDraft.value.identify) {
      clearReusedCommandJobDraft()
    }
    if (routeCommandDraftNotice.value && identify !== routeCommandDraftNotice.value.identify) {
      clearRouteCommandDraftNotice()
    }
  })

  watch(options.routeCommandDraft, () => {
    applyRouteCommandDraft()
  })

  return {
    applyRouteCommandDraft,
    clearReusedCommandJobDraft,
    clearRouteCommandDraftNotice,
    reusedCommandJobDraft,
    routeCommandDraftNotice
  }
}

import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import {
  buildCommandCenterFilterSummaryItems,
  normalizeQueryValue,
  parseCommandCenterScopeContext
} from './commandCenterState'
import type { QueryValue } from './commandCenterState'
import { parseCommandCenterRouteDraft } from './commandCenterRouteDraft'
import { buildActiveCommandJobQuery } from './commandCenterRouteQuery'

export function useCommandCenterRouteScope() {
  const route = useRoute()
  const router = useRouter()

  const scopeContext = computed(() => parseCommandCenterScopeContext(route.query as Record<string, any>))
  const selectedDeviceIds = computed(() => scopeContext.value.deviceIds)

  const selectedCount = computed(() => selectedDeviceIds.value.length)
  const requestedTotal = computed(() => scopeContext.value.requestedTotal)
  const currentPageCount = computed(() => scopeContext.value.currentPageCount)
  const scope = computed(() => scopeContext.value.scopeType)
  const routeScope = computed(() => scopeContext.value.routeScope)
  const deviceFilter = computed(() => scopeContext.value.deviceFilter)
  const filterSummaryItems = computed(() => buildCommandCenterFilterSummaryItems(deviceFilter.value))
  const hasDeviceFilter = computed(() => filterSummaryItems.value.length > 0)
  const isDeviceFilterScope = computed(() => scope.value === 'device_filter')
  const hasSelectedDevices = computed(() => selectedCount.value > 0)
  const hasCommandJobScope = computed(() =>
    isDeviceFilterScope.value ? hasDeviceFilter.value : hasSelectedDevices.value
  )
  const activeCommandJobId = computed(
    () =>
      normalizeQueryValue(route.query.command_job_id as QueryValue) ||
      normalizeQueryValue(route.query.job_id as QueryValue)
  )
  const routeCommandDraft = computed(() => parseCommandCenterRouteDraft(route.query))

  const setActiveCommandJobQuery = async (jobId: string) => {
    await router.replace({ query: buildActiveCommandJobQuery(route.query, jobId) })
  }

  return {
    activeCommandJobId,
    currentPageCount,
    deviceFilter,
    filterSummaryItems,
    hasCommandJobScope,
    hasDeviceFilter,
    hasSelectedDevices,
    isDeviceFilterScope,
    requestedTotal,
    routeCommandDraft,
    routeScope,
    scope,
    scopeContext,
    selectedCount,
    selectedDeviceIds,
    setActiveCommandJobQuery
  }
}

import { computed, ref } from 'vue'
import type { SelectOption } from 'naive-ui'
import { deleteFleetSavedFilter, listFleetSavedFilters, updateFleetSavedFilter } from '@/service/api/device'
import {
  buildFleetSavedFilterPayload,
  loadSavedFleetFilters,
  mergeSavedFleetFilters,
  normalizeServerFleetSavedFilter,
  normalizeServerFleetSavedFilters,
  saveFleetFiltersToStorage,
  type SavedFleetFilter
} from '../manage/device-fleet-saved-filters'

type UseCommandCenterSavedFleetFiltersOptions = {
  getRouteSavedFilterId: () => string
}

type SavedFleetFilterStatus = 'idle' | 'server' | 'local' | 'local-fallback' | 'empty'

const defaultStorage = () => (typeof window === 'undefined' ? null : window.localStorage)

const isLocalFleetFilter = (id: string) => id.startsWith('fleet-filter-')

const getApiErrorMessage = (error: unknown) => {
  const maybeError = error as {
    message?: string
    response?: { data?: { message?: string; msg?: string } }
    data?: { message?: string; msg?: string }
  }

  return (
    maybeError?.response?.data?.message ||
    maybeError?.response?.data?.msg ||
    maybeError?.data?.message ||
    maybeError?.data?.msg ||
    maybeError?.message ||
    ''
  )
}

export function useCommandCenterSavedFleetFilters(options: UseCommandCenterSavedFleetFiltersOptions) {
  const savedFleetFilters = ref<SavedFleetFilter[]>([])
  const savedFleetFilterLoading = ref(false)
  const savedFleetFilterLoaded = ref(false)
  const savedFleetFilterStatus = ref<SavedFleetFilterStatus>('idle')
  const savedFleetFilterActionError = ref('')
  const selectedSavedFleetFilterId = ref<string | null>(null)

  const syncSelectedSavedFleetFilterFromRoute = () => {
    const routeFilterId = options.getRouteSavedFilterId()
    if (!routeFilterId) {
      selectedSavedFleetFilterId.value = null
      return
    }
    const exists = savedFleetFilters.value.some((filter) => filter.id === routeFilterId)
    selectedSavedFleetFilterId.value = exists ? routeFilterId : null
  }

  const refreshCommandCenterSavedFilters = async () => {
    const storage = defaultStorage()
    const localFilters = loadSavedFleetFilters(storage)
    savedFleetFilterLoading.value = true
    savedFleetFilterActionError.value = ''
    savedFleetFilters.value = localFilters
    savedFleetFilterStatus.value = localFilters.length ? 'local' : 'empty'
    syncSelectedSavedFleetFilterFromRoute()

    try {
      const response = await listFleetSavedFilters()
      const data = (response as any).data ?? response
      const serverFilters = normalizeServerFleetSavedFilters(data?.list ?? [])
      savedFleetFilters.value = mergeSavedFleetFilters(serverFilters, localFilters)
      savedFleetFilterStatus.value = serverFilters.length ? 'server' : savedFleetFilters.value.length ? 'local' : 'empty'
      saveFleetFiltersToStorage(storage, savedFleetFilters.value)
      syncSelectedSavedFleetFilterFromRoute()
    } catch {
      savedFleetFilters.value = localFilters
      savedFleetFilterStatus.value = localFilters.length ? 'local-fallback' : 'empty'
      syncSelectedSavedFleetFilterFromRoute()
    } finally {
      savedFleetFilterLoaded.value = true
      savedFleetFilterLoading.value = false
    }
  }

  const savedFleetFilterOptions = computed<SelectOption[]>(() =>
    savedFleetFilters.value.map((filter) => ({
      label: `${filter.name}${typeof filter.previewTotal === 'number' ? ` (${filter.previewTotal})` : ''}`,
      value: filter.id
    }))
  )

  const activeSavedFleetFilter = computed(
    () =>
      savedFleetFilters.value.find((filter) => filter.id === selectedSavedFleetFilterId.value) ||
      savedFleetFilters.value.find((filter) => filter.id === options.getRouteSavedFilterId()) ||
      null
  )

  const staleRouteSavedFilter = computed(
    () => savedFleetFilterLoaded.value && Boolean(options.getRouteSavedFilterId()) && !activeSavedFleetFilter.value
  )

  const savedFleetFilterNoticeKey = computed(() => {
    if (staleRouteSavedFilter.value) return 'custom.commandCenter.savedFilterRouteMissing'
    if (savedFleetFilterStatus.value === 'local-fallback') return 'custom.commandCenter.savedFilterLocalFallback'
    if (savedFleetFilterStatus.value === 'local') return 'custom.commandCenter.savedFilterLocalOnly'
    return ''
  })

  const clearCommandCenterSavedFilterSelection = () => {
    selectedSavedFleetFilterId.value = null
  }

  const renameCommandCenterSavedFilter = async (filterId: string | number, name: string) => {
    const id = String(filterId)
    const nextName = name.trim()
    savedFleetFilterActionError.value = ''
    if (!nextName) return false

    const filter = savedFleetFilters.value.find((item) => item.id === id)
    if (!filter) return false

    const storage = defaultStorage()
    if (isLocalFleetFilter(id)) {
      savedFleetFilters.value = savedFleetFilters.value.map((item) =>
        item.id === id ? { ...item, name: nextName } : item
      )
      saveFleetFiltersToStorage(storage, savedFleetFilters.value)
      return true
    }

    try {
      const response = await updateFleetSavedFilter(
        id,
        buildFleetSavedFilterPayload(filter.params, filter.previewTotal, nextName)
      )
      const updated = normalizeServerFleetSavedFilter(((response as any).data ?? response) as any)
      savedFleetFilters.value = savedFleetFilters.value.map((item) =>
        item.id === id ? updated || { ...item, name: nextName } : item
      )
      saveFleetFiltersToStorage(storage, savedFleetFilters.value)
      return true
    } catch (error) {
      savedFleetFilterActionError.value = getApiErrorMessage(error)
      return false
    }
  }

  const deleteCommandCenterSavedFilter = async (filterId: string | number) => {
    const id = String(filterId)
    savedFleetFilterActionError.value = ''
    const filter = savedFleetFilters.value.find((item) => item.id === id)
    if (!filter) return false

    if (!isLocalFleetFilter(id)) {
      try {
        await deleteFleetSavedFilter(id)
      } catch (error) {
        savedFleetFilterActionError.value = getApiErrorMessage(error)
        return false
      }
    }

    const storage = defaultStorage()
    savedFleetFilters.value = savedFleetFilters.value.filter((item) => item.id !== id)
    if (selectedSavedFleetFilterId.value === id) selectedSavedFleetFilterId.value = null
    saveFleetFiltersToStorage(storage, savedFleetFilters.value)
    return true
  }

  return {
    activeSavedFleetFilter,
    clearCommandCenterSavedFilterSelection,
    deleteCommandCenterSavedFilter,
    renameCommandCenterSavedFilter,
    refreshCommandCenterSavedFilters,
    savedFleetFilterActionError,
    savedFleetFilterLoaded,
    savedFleetFilterLoading,
    savedFleetFilterNoticeKey,
    savedFleetFilterOptions,
    savedFleetFilterStatus,
    savedFleetFilters,
    selectedSavedFleetFilterId,
    staleRouteSavedFilter,
    syncSelectedSavedFleetFilterFromRoute
  }
}

import { computed, type Ref } from 'vue'
import type {
  FleetCommandJobSubmitResult,
  FleetCommandJobSubmitRow,
  FleetCommandJobSupportBundle
} from '@/service/api/device'
import {
  buildCommandJobActionConsequenceRows,
  buildCommandJobCapabilitySummary,
  buildCommandJobAuditSummaryCard,
  buildCommandJobEvidenceSummary,
  buildCommandJobExecutionSummaryCard,
  buildCommandJobGovernanceSummaryCard,
  buildCommandJobDeviceProgressTracks,
  buildCommandJobHandoffSummary,
  buildCommandJobOperatorNextAction,
  buildCommandJobOutcomeGroups,
  buildCommandJobProgressHealthCard,
  buildCommandJobProgressSummary,
  buildCommandJobStatusCountRows,
  buildCommandJobStatusRows,
  buildCommandJobSupportBundlePreview,
  buildCommandJobTimelineRows,
  buildCommandJobTroubleshootingRows,
  canRetryCommandJob,
  commandJobRetryReadyCount,
  commandJobRetryWaitingCount,
  commandJobRetryExhaustedCount,
  commandJobProgressPercent,
  formatCommandJobStatus
} from './commandCenterJobView'

type Translate = (key: string) => string
type CommandJobEvidenceAlertType = 'success' | 'info' | 'warning' | 'error'
const COMMAND_JOB_RESULT_DISPLAY_LIMIT = 200

const commandJobSubmitRowPriority = (row: FleetCommandJobSubmitRow) => {
  if (row.can_retry) return 0
  if (row.status === 'failed') return 1
  if (row.eligible && !row.log_recorded) return 2
  if (!row.eligible || row.recommended_path === 'blocked') return 3
  if (row.status && row.status !== 'completed') return 4
  return 10
}

export const commandJobSubmitRowsForCustomer = (
  rows: FleetCommandJobSubmitRow[],
  limit = COMMAND_JOB_RESULT_DISPLAY_LIMIT
) => {
  if (limit <= 0 || rows.length <= limit) {
    return [...rows].sort((left, right) => commandJobSubmitRowPriority(left) - commandJobSubmitRowPriority(right))
  }

  const buckets: FleetCommandJobSubmitRow[][] = Array.from({ length: 11 }, () => [])
  for (const row of rows) {
    const priority = commandJobSubmitRowPriority(row)
    buckets[Math.min(priority, buckets.length - 1)].push(row)
  }

  const selected: FleetCommandJobSubmitRow[] = []
  for (const bucket of buckets) {
    for (const row of bucket) {
      selected.push(row)
      if (selected.length >= limit) return selected
    }
  }
  return selected
}

export const commandJobSubmitRowsHiddenCount = (
  result: FleetCommandJobSubmitResult | null,
  displayedCount: number
) => {
  if (!result) return 0
  const total = Math.max(result.rows_total ?? result.rows.length, result.rows.length)
  return Math.max(0, total - displayedCount)
}

export function useCommandCenterSubmitEvidenceView(options: {
  submitResult: Ref<FleetCommandJobSubmitResult | null>
  supportBundle: Ref<FleetCommandJobSupportBundle | null>
  t: Translate
}) {
  const submitCapabilitySummary = computed(() => buildCommandJobCapabilitySummary(options.submitResult.value, options.t))
  const jobAuditSummaryCard = computed(() => buildCommandJobAuditSummaryCard(options.submitResult.value, options.t))
  const jobExecutionSummaryCard = computed(() => buildCommandJobExecutionSummaryCard(options.submitResult.value, options.t))
  const jobGovernanceSummaryCard = computed(() =>
    buildCommandJobGovernanceSummaryCard(options.submitResult.value?.governance_summary, options.t)
  )
  const submitEvidenceSummary = computed(() => buildCommandJobEvidenceSummary(options.submitResult.value, options.t))
  const jobHandoffSummary = computed(() => buildCommandJobHandoffSummary(options.submitResult.value))
  const submitEvidenceAlertType = computed<CommandJobEvidenceAlertType>(() => {
    const result = options.submitResult.value
    if (!result) return 'info'
    if ((result.blocked_count || 0) > 0 || commandJobRetryReadyCount(result) > 0 || commandJobRetryExhaustedCount(result) > 0) return 'error'
    if ((result.failed_count || 0) > 0 || commandJobRetryWaitingCount(result) > 0 || (result.log_missing_count || 0) > 0) return 'warning'
    return 'success'
  })
  const submitRowsForCustomer = computed(() => commandJobSubmitRowsForCustomer(options.submitResult.value?.rows ?? []))
  const submitRowsHiddenCount = computed(() =>
    commandJobSubmitRowsHiddenCount(options.submitResult.value, submitRowsForCustomer.value.length)
  )
  const jobProgressPercent = computed(() => commandJobProgressPercent(options.submitResult.value))
  const jobProgressHealthCard = computed(() => buildCommandJobProgressHealthCard(options.submitResult.value, options.t))
  const jobProgressSummary = computed(() => buildCommandJobProgressSummary(options.submitResult.value, options.t))
  const jobStatusLabel = computed(() => formatCommandJobStatus(options.submitResult.value?.status, options.t))
  const jobActionConsequenceRows = computed(() => buildCommandJobActionConsequenceRows(options.submitResult.value, options.t))
  const jobDeviceProgressTracks = computed(() => buildCommandJobDeviceProgressTracks(options.submitResult.value, options.t))
  const jobStatusRows = computed(() => buildCommandJobStatusRows(options.submitResult.value, options.t))
  const jobStatusCountRows = computed(() => buildCommandJobStatusCountRows(options.submitResult.value, options.t))
  const jobTimelineRows = computed(() => buildCommandJobTimelineRows(options.submitResult.value, options.t))
  const jobTroubleshootingRows = computed(() => buildCommandJobTroubleshootingRows(options.submitResult.value, options.t))
  const jobOperatorNextAction = computed(() => buildCommandJobOperatorNextAction(options.submitResult.value, options.t))
  const jobOutcomeGroups = computed(() => buildCommandJobOutcomeGroups(options.submitResult.value, options.t))
  const supportBundlePreview = computed(() => buildCommandJobSupportBundlePreview(options.supportBundle.value, options.t))
  const canRetryCurrentCommandJob = computed(() => canRetryCommandJob(options.submitResult.value))

  return {
    canRetryCurrentCommandJob,
    jobAuditSummaryCard,
    jobExecutionSummaryCard,
    jobGovernanceSummaryCard,
    jobActionConsequenceRows,
    jobOutcomeGroups,
    jobOperatorNextAction,
    jobProgressHealthCard,
    jobProgressPercent,
    jobProgressSummary,
    jobHandoffSummary,
    jobDeviceProgressTracks,
    jobStatusCountRows,
    jobStatusLabel,
    jobStatusRows,
    jobTimelineRows,
    jobTroubleshootingRows,
    submitCapabilitySummary,
    submitEvidenceAlertType,
    submitEvidenceSummary,
    submitRowsHiddenCount,
    submitRowsForCustomer,
    supportBundlePreview
  }
}

import type { Ref } from 'vue'
import { writeClipboardText } from '@/utils/clipboard'
import type { FleetCommandJobListItem } from '@/service/api/device'
import {
  serializeCommandTemplatesForExport,
  type CommandCenterCommandTemplateImportResult,
  type CommandCenterSavedCommandTemplate
} from './useCommandCenterCommandTemplates'

type CommandTemplateDraft = {
  identify: string
  value: string
  timeoutSeconds: number
  name?: string
  syncName?: boolean
}

type BuiltInCommandTemplate = {
  identify: string
  value: string
  timeoutSeconds: number
}

type UseCommandCenterTemplateActionsOptions = {
  commandIdentify: Ref<string>
  commandValue: Ref<string>
  timeoutSeconds: Ref<number>
  commandTemplateName: Ref<string>
  saveCommandTemplate: (draft: CommandTemplateDraft) => boolean
  deleteCommandTemplate: (templateId: string) => void
  importCommandTemplates: (raw: string) => CommandCenterCommandTemplateImportResult
  resetCommandJobDraft: () => void
  clearReusedCommandJobDraft: () => void
  t: (key: string) => string
  copyText?: (text: string) => Promise<boolean>
  notifySuccess?: (message: string) => void
  notifyWarning?: (message: string) => void
}

export const useCommandCenterTemplateActions = ({
  commandIdentify,
  commandValue,
  timeoutSeconds,
  commandTemplateName,
  saveCommandTemplate,
  deleteCommandTemplate,
  importCommandTemplates,
  resetCommandJobDraft,
  clearReusedCommandJobDraft,
  t,
  copyText = writeClipboardText,
  notifySuccess = message => window.$message?.success(message),
  notifyWarning = message => window.$message?.warning(message)
}: UseCommandCenterTemplateActionsOptions) => {
  const saveCurrentCommandTemplate = () => {
    const saved = saveCommandTemplate({
      identify: commandIdentify.value,
      value: commandValue.value,
      timeoutSeconds: timeoutSeconds.value
    })
    if (saved) {
      notifySuccess(t('custom.commandCenter.saveCommandTemplateSuccess'))
    } else {
      notifyWarning(t('custom.commandCenter.saveCommandTemplateMissingIdentify'))
    }
  }

  const saveCommandJobTemplate = (job: FleetCommandJobListItem) => {
    const templateName = `${job.identify || t('custom.commandCenter.commandIdentifier')} ${job.job_id.slice(0, 8)}`
    const saved = saveCommandTemplate({
      name: templateName,
      identify: job.identify || '',
      value: job.command_value || '',
      timeoutSeconds: job.timeout_seconds || 60,
      syncName: false
    })
    if (saved) {
      notifySuccess(t('custom.commandCenter.saveJobAsTemplateSuccess'))
    } else {
      notifyWarning(t('custom.commandCenter.saveCommandTemplateMissingIdentify'))
    }
  }

  const copyCommandTemplateExport = async (templates: CommandCenterSavedCommandTemplate[]) => {
    if (!templates.length) return
    const ok = await copyText(serializeCommandTemplatesForExport(templates))
    if (ok) {
      notifySuccess(
        templates.length === 1
          ? t('custom.commandCenter.copyCommandTemplateSuccess')
          : t('custom.commandCenter.copyCommandTemplatesSuccess')
      )
    } else {
      notifyWarning(t('common.copyFailed'))
    }
  }

  const importSavedCommandTemplates = (raw: string) => {
    try {
      const result = importCommandTemplates(raw)
      if (result.imported > 0) {
        notifySuccess(t('custom.commandCenter.importCommandTemplatesSuccess').replace('{count}', String(result.imported)))
        return
      }
    } catch {
      // Fall through to the same customer-facing warning for malformed or unsupported JSON.
    }
    notifyWarning(t('custom.commandCenter.importCommandTemplatesInvalid'))
  }

  const applyBuiltInCommandTemplate = (template: BuiltInCommandTemplate) => {
    commandIdentify.value = template.identify
    commandValue.value = template.value
    timeoutSeconds.value = template.timeoutSeconds
    clearReusedCommandJobDraft()
    resetCommandJobDraft()
  }

  const applySavedCommandTemplate = (template: CommandCenterSavedCommandTemplate) => {
    commandIdentify.value = template.identify
    commandValue.value = template.value
    timeoutSeconds.value = template.timeoutSeconds
    commandTemplateName.value = template.name
    clearReusedCommandJobDraft()
    resetCommandJobDraft()
    notifySuccess(t('custom.commandCenter.applyCommandTemplateSuccess'))
  }

  const deleteSavedCommandTemplate = (templateId: string) => {
    deleteCommandTemplate(templateId)
    notifySuccess(t('custom.commandCenter.deleteCommandTemplateSuccess'))
  }

  return {
    applyBuiltInCommandTemplate,
    applySavedCommandTemplate,
    copyCommandTemplateExport,
    deleteSavedCommandTemplate,
    importSavedCommandTemplates,
    saveCommandJobTemplate,
    saveCurrentCommandTemplate
  }
}

