/**
 * 文件用途: distribution-and-table 测试文件。
 * 核心逻辑: 验证对应组件或组合函数的关键用户路径和边界状态。
 * 关键注意事项: mock 数据应贴近真实接口字段，避免只断言组件存在。
 * 重构建议: 补齐失败、空数据和权限边界用例。
 */
import { defineComponent, h } from 'vue'
import { flushPromises, shallowMount } from '@vue/test-utils'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const hoisted = vi.hoisted(() => ({
  commandDataById: vi.fn(),
  commandDataPub: vi.fn(),
  deviceCustomCommandsIdList: vi.fn(),
  getAttributeDataSet: vi.fn(),
  fetchDataApi: vi.fn(),
  submitApi: vi.fn(),
  expectApi: vi.fn()
}))

vi.mock('@/service/api', () => ({
  commandDataById: hoisted.commandDataById,
  commandDataPub: hoisted.commandDataPub,
  deviceCustomCommandsIdList: hoisted.deviceCustomCommandsIdList,
  getAttributeDataSet: hoisted.getAttributeDataSet
}))

vi.mock('@/locales', () => ({
  $t: (key: string) => key
}))

vi.mock('@/utils/common/tool', () => ({
  isJSON: vi.fn((str: string) => { try { JSON.parse(str); return true } catch { return false } })
}))

vi.mock('@/utils/logger', () => ({
  createLogger: () => ({ info: vi.fn(), error: vi.fn(), warn: vi.fn() })
}))

vi.mock('@aetherlink/hooks', () => ({
  useLoading: (init = false) => {
    const loading = ref(init)
    return { loading, startLoading: vi.fn(() => { loading.value = true }), endLoading: vi.fn(() => { loading.value = false }) }
  }
}))

vi.mock('@vicons/ionicons5', () => ({
  Refresh: defineComponent({ setup: () => () => h('span') })
}))

vi.mock('dayjs', () => ({
  default: vi.fn(() => ({ format: vi.fn(() => '2024-01-01 00:00:00') }))
}))

import { ref } from 'vue'
import Component from '../distribution-and-table.vue'

const mountedWrappers: Array<ReturnType<typeof shallowMount>> = []

const mountComponent = (propsOverrides = {}) => {
  const wrapper = shallowMount(Component, {
    props: {
      id: 'device-1',
      tableColumns: [],
      fetchDataApi: hoisted.fetchDataApi,
      submitApi: hoisted.submitApi,
      expectApi: hoisted.expectApi,
      expect: true,
      ...propsOverrides
    },
    global: {
      mocks: {
        getPlatform: () => false
      },
      stubs: {
        NButton: defineComponent({ props: ['type', 'bordered', 'size', 'disabled'], emits: ['click'], setup(_, { slots, emit }) { return () => h('button', { onClick: () => emit('click') }, slots.default?.()) } }),
        NIcon: defineComponent({ props: ['size'], setup(_, { slots }) { return () => h('span', slots.default?.()) } }),
        NDataTable: defineComponent({ props: ['loading', 'columns', 'data'], setup() { return () => h('table') } }),
        NPagination: defineComponent({ props: ['pageCount', 'page', 'pageSize', 'prefix'], emits: ['update:page'], setup() { return () => h('div') } }),
        Pagination: defineComponent({ props: ['pageCount', 'page', 'pageSize', 'prefix'], emits: ['update:page'], setup() { return () => h('div') } }),
        NModal: defineComponent({ props: ['show'], emits: ['update:show'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NCard: defineComponent({ props: ['title'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        'n-card': defineComponent({ props: ['title'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NForm: defineComponent({ props: ['model', 'rules', 'labelPlacement'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NFormItem: defineComponent({ props: ['label', 'path', 'required', 'validationStatus', 'feedback'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NInput: defineComponent({ props: ['value', 'type', 'placeholder', 'disabled'], emits: ['update:value'], setup() { return () => h('input') } }),
        NSelect: defineComponent({ props: ['value', 'options', 'filterable', 'tag', 'clearable', 'placeholder'], emits: ['update:value', 'update:show'], setup() { return () => h('div') } }),
        NTabs: defineComponent({ props: ['value'], emits: ['update:value'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NTabPane: defineComponent({ props: ['name', 'tab'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NFlex: defineComponent({ props: ['justify'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NInputNumber: defineComponent({ props: ['value', 'showButton'], emits: ['update:value'], setup() { return () => h('input') } }),
        NSwitch: defineComponent({ props: ['value'], emits: ['update:value'], setup() { return () => h('div') } }),
        NGrid: defineComponent({ setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NGridItem: defineComponent({ setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NCheckbox: defineComponent({ props: ['checked', 'indeterminate'], emits: ['update:checked'], setup(_, { slots }) { return () => h('label', slots.default?.()) } }),
        SvgIcon: true
      }
    }
  })
  mountedWrappers.push(wrapper)
  return wrapper
}

const getSetupState = (wrapper: ReturnType<typeof shallowMount>) => wrapper.vm.$.setupState as Record<string, any>

describe('device/details/modules/public/distribution-and-table.vue', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    hoisted.fetchDataApi.mockResolvedValue({ data: { list: [], total: 0 }, error: null })
    hoisted.submitApi.mockResolvedValue({ error: null })
    hoisted.expectApi.mockResolvedValue({ error: null })
    hoisted.commandDataById.mockResolvedValue({ data: [] })
    hoisted.commandDataPub.mockResolvedValue({})
    hoisted.deviceCustomCommandsIdList.mockResolvedValue({ data: [] })
    hoisted.getAttributeDataSet.mockResolvedValue({ data: [], error: null })
  })

  afterEach(() => {
    while (mountedWrappers.length > 0) {
      mountedWrappers.pop()?.unmount()
    }
  })

  it('initializes paged device distribution table query and default dialog state', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(hoisted.fetchDataApi).toHaveBeenCalledWith({
      page: 1,
      page_size: 4,
      device_id: 'device-1'
    })
    expect(state.the_page).toBe(1)
    expect(state.page_coune).toBe(0)
    expect(state.tableData).toEqual([])
    expect(state.formModel).toMatchObject({
      commandValue: '',
      textValue: '',
      expected: false,
      time: null,
      timeoutSeconds: 10,
      waitForResponse: false
    })
    expect(state.activeTab).toBe('visual')
  })

  it('calls fetchDataApi on mount', async () => {
    mountComponent()
    await flushPromises()
    expect(hoisted.fetchDataApi).toHaveBeenCalledTimes(1)
    expect(hoisted.fetchDataApi).toHaveBeenCalledWith({
      page: 1,
      page_size: 4,
      device_id: 'device-1'
    })
  })

  it('refresh resets page and fetches data', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    vi.clearAllMocks()
    state.refresh()
    await flushPromises()
    expect(state.the_page).toBe(1)
    expect(hoisted.fetchDataApi).toHaveBeenCalledTimes(1)
    expect(hoisted.fetchDataApi).toHaveBeenCalledWith({
      page: 1,
      page_size: 4,
      device_id: 'device-1'
    })
  })

  it('updatePage updates page and fetches', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    vi.clearAllMocks()
    state.updatePage(3)
    await flushPromises()
    expect(state.the_page).toBe(3)
    expect(hoisted.fetchDataApi).toHaveBeenCalledTimes(1)
    expect(hoisted.fetchDataApi).toHaveBeenCalledWith({
      page: 3,
      page_size: 4,
      device_id: 'device-1'
    })
  })

  it('openDialog sets showDialog to true', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    state.openDialog()
    expect(state.showDialog).toBe(true)
  })

  it('closeDialog resets form state', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    state.showDialog = true
    state.formModel.textValue = 'test'
    state.closeDialog()
    expect(state.showDialog).toBe(false)
    expect(state.formModel.textValue).toBe('')
  })

  it('exposes refresh method', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    expect(typeof wrapper.vm.refresh).toBe('function')
  })

  it('fetches command list when isCommand is true', async () => {
    mountComponent({ isCommand: true })
    await flushPromises()
    expect(hoisted.deviceCustomCommandsIdList).toHaveBeenCalledWith('device-1')
  })

  it('does not fetch command list when isCommand is false', async () => {
    mountComponent({ isCommand: false })
    await flushPromises()
    expect(hoisted.deviceCustomCommandsIdList).toHaveBeenCalledTimes(0)
  })

  it('onCommandChange calls commandDataPub', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    await state.onCommandChange({ instruct: 'cmd1', data_identifier: 'id1' })
    await flushPromises()
    expect(hoisted.commandDataPub).toHaveBeenCalledWith({
      device_id: 'device-1',
      value: 'cmd1',
      identify: 'id1'
    })
  })
})

/**
 * 文件用途: tencent-map 测试文件。
 * 核心逻辑: 验证对应组件或组合函数的关键用户路径和边界状态。
 * 关键注意事项: mock 数据应贴近真实接口字段，避免只断言组件存在。
 * 重构建议: 补齐失败、空数据和权限边界用例。
 */
import { defineComponent, h } from 'vue'
import { flushPromises, shallowMount } from '@vue/test-utils'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const hoisted = vi.hoisted(() => ({
  sdkUrl: 'https://map.qq.com/api/gljs?v=1.exp&key=test',
  load: vi.fn().mockResolvedValue(undefined)
}))

vi.mock('@/constants/map-sdk', () => ({
  get TENCENT_MAP_SDK_URL() {
    return hoisted.sdkUrl
  }
}))

vi.mock('@/locales', () => ({
  $t: (key: string) => key
}))

vi.mock('@/utils/common/map-validator', () => ({
  isValidCoordinate: vi.fn((lat: number, lng: number) => lat >= -90 && lat <= 90 && lng >= -180 && lng <= 180),
  getCoordinateValidationError: vi.fn(() => 'Invalid coordinate')
}))

vi.mock('@vueuse/core', () => ({
  useScriptTag: () => ({ load: hoisted.load })
}))

globalThis.TMap = {
  Map: vi.fn(function MapMock() {
    return {
      on: vi.fn(),
      setCenter: vi.fn()
    }
  }),
  LatLng: vi.fn(function LatLngMock(lat: number, lng: number) {
    return { lat, lng }
  }),
  MultiMarker: vi.fn(function MultiMarkerMock() {
    return { setMap: vi.fn() }
  }),
  MarkerStyle: vi.fn(function MarkerStyleMock() {
    return {}
  })
} as any

import Component from '../tencent-map.vue'

const mountedWrappers: Array<ReturnType<typeof shallowMount>> = []

const mountComponent = (props = {}) => {
  const wrapper = shallowMount(Component, {
    props: {
      longitude: '116.307484',
      latitude: '39.98412',
      ...props
    },
    global: {
      stubs: {}
    }
  })
  mountedWrappers.push(wrapper)
  return wrapper
}

describe('device/details/modules/public/tencent-map.vue', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    hoisted.sdkUrl = 'https://map.qq.com/api/gljs?v=1.exp&key=test'
  })

  afterEach(() => {
    while (mountedWrappers.length > 0) {
      mountedWrappers.pop()?.unmount()
    }
  })

  it('uses a local unavailable state without loading an external script when unconfigured', async () => {
    hoisted.sdkUrl = ''

    const wrapper = mountComponent()
    await flushPromises()

    expect(hoisted.load).not.toHaveBeenCalled()
    expect(globalThis.TMap.Map).not.toHaveBeenCalled()
    expect(wrapper.text()).toContain('rdi.map.mapUnavailable')
  })

  it('initializes map with provided valid coordinate and current-location marker', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const mapContainer = wrapper.element.firstElementChild
    expect(globalThis.TMap.LatLng).toHaveBeenCalledWith(39.98412, 116.307484)
    expect(globalThis.TMap.Map).toHaveBeenCalledWith(
      mapContainer,
      expect.objectContaining({
        center: { lat: 39.98412, lng: 116.307484 },
        zoom: 15,
        maxZoom: 18,
        minZoom: 6
      })
    )
    expect(globalThis.TMap.MultiMarker).toHaveBeenCalledWith(
      expect.objectContaining({
        geometries: [
          expect.objectContaining({
            id: 'current-position',
            styleId: 'current-location',
            position: { lat: 39.98412, lng: 116.307484 }
          })
        ]
      })
    )
  })

  it('keeps the map mount container full size for embedding in device forms', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const mapContainer = wrapper.element.firstElementChild
    expect(wrapper.classes()).toEqual(['relative', 'w-full', 'h-full'])
    expect(mapContainer).toBeInstanceOf(HTMLElement)
    expect(Array.from(mapContainer!.classList)).toEqual(expect.arrayContaining(['w-full', 'h-full']))
    expect(globalThis.TMap.Map).toHaveBeenCalledWith(mapContainer, expect.any(Object))
  })

  it('emits position-selected event from a valid Tencent map click', async () => {
    const wrapper = mountComponent()
    await flushPromises()
    const mapInstance = (globalThis.TMap.Map as any).mock.results[0].value
    const clickHandler = mapInstance.on.mock.calls.find(([eventName]: [string]) => eventName === 'click')?.[1]
    clickHandler({
      latLng: {
        getLat: () => 40.123456,
        getLng: () => 116.654321
      }
    })
    expect(wrapper.emitted('position-selected')).toEqual([[{ lat: 40.123456, lng: 116.654321 }]])
    expect(globalThis.TMap.MultiMarker).toHaveBeenLastCalledWith(
      expect.objectContaining({
        geometries: [
          expect.objectContaining({
            id: 'current-position',
            position: { lat: 40.123456, lng: 116.654321 }
          })
        ]
      })
    )
  })

  it('falls back to default center and wider zoom when coordinates are empty', async () => {
    mountComponent({ longitude: '', latitude: '' })
    await flushPromises()
    expect(globalThis.TMap.Map).toHaveBeenCalledWith(
      expect.any(HTMLElement),
      expect.objectContaining({
        center: { lat: 39.98412, lng: 116.307484 },
        zoom: 9
      })
    )
    expect(globalThis.TMap.MultiMarker).toHaveBeenCalledTimes(0)
  })

  it('accepts numeric coordinate props and still renders the current marker', async () => {
    mountComponent({ longitude: 116.307484, latitude: 39.98412 })
    await flushPromises()
    expect(globalThis.TMap.Map).toHaveBeenCalledWith(
      expect.any(HTMLElement),
      expect.objectContaining({
        center: { lat: 39.98412, lng: 116.307484 },
        zoom: 15
      })
    )
    expect(globalThis.TMap.MultiMarker).toHaveBeenCalledWith(
      expect.objectContaining({
        geometries: [expect.objectContaining({ position: { lat: 39.98412, lng: 116.307484 } })]
      })
    )
  })
})

import { computed, reactive, ref } from 'vue'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { useDistributionSubmitFlow } from '../useDistributionSubmitFlow'

const hoisted = vi.hoisted(() => ({
  commandDataPub: vi.fn(),
  messageError: vi.fn(),
  messageSuccess: vi.fn(),
  messageWarning: vi.fn(),
  isJSON: vi.fn((value: string) => {
    try {
      JSON.parse(value)
      return true
    } catch {
      return false
    }
  })
}))

vi.mock('@/service/api', () => ({
  commandDataPub: hoisted.commandDataPub
}))

vi.mock('@/locales', () => ({
  $t: (key: string) => key
}))

vi.mock('@/utils/common/tool', () => ({
  isJSON: hoisted.isJSON
}))

vi.mock('dayjs', () => ({
  default: vi.fn(() => ({ format: vi.fn(() => '2024-01-01T00:00:00+00:00') }))
}))

const createFlow = (overrides: Partial<Parameters<typeof useDistributionSubmitFlow>[0]> = {}) => {
  const submitApi = vi.fn().mockResolvedValue({ error: null })
  const expectApi = vi.fn().mockResolvedValue({ error: null })
  const fetchData = vi.fn().mockResolvedValue(undefined)
  const closeDialog = vi.fn()
  const logger = { error: vi.fn() }
  const directMethodApi = vi.fn().mockResolvedValue({ error: null })
  const onDirectMethodResult = vi.fn()
  const onSubmitTracking = vi.fn()
  const formModel = reactive({
    commandValue: 'reboot',
    textValue: '',
    expected: false,
    time: null as number | null,
    timeoutSeconds: 10,
    waitForResponse: false
  })
  const paramsData = ref<any[]>([{ data_identifier: 'delay', delay: 5 }])
  const attributeList = ref<any[]>([
    { data_identifier: 'mode', inputValue: 'auto', attributeType: 'string', checked: true }
  ])

  const flow = useDistributionSubmitFlow({
    activeTab: ref('visual'),
    attributeList,
    closeDialog,
    deviceId: () => 'device-1',
    directMethodApi: () => directMethodApi,
    expectApi: () => expectApi,
    fetchData,
    formModel,
    formRef: ref({ validate: vi.fn().mockResolvedValue(undefined) } as any),
    hasAttributeSelection: computed(() => attributeList.value.some((item) => item.checked)),
    isCommand: () => true,
    logger,
    onDirectMethodResult,
    onSubmitTracking,
    paramsData,
    submitApi: () => submitApi,
    ...overrides
  })

  return {
    attributeList,
    closeDialog,
    directMethodApi,
    expectApi,
    fetchData,
    flow,
    formModel,
    logger,
    onDirectMethodResult,
    onSubmitTracking,
    paramsData,
    submitApi
  }
}

describe('useDistributionSubmitFlow', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    ;(window as any).$message = {
      error: hoisted.messageError,
      success: hoisted.messageSuccess,
      warning: hoisted.messageWarning
    }
    hoisted.commandDataPub.mockResolvedValue({ error: null })
  })

  it('submits visual command payload through the immediate command API', async () => {
    const { closeDialog, fetchData, flow, onSubmitTracking, submitApi } = createFlow()
    submitApi.mockResolvedValueOnce({ error: null, data: { message_id: 'cmd-track-1' } })

    await flow.submit()

    expect(submitApi).toHaveBeenCalledWith({
      device_id: 'device-1',
      identify: 'reboot',
      value: JSON.stringify({ delay: 5 })
    })
    expect(hoisted.messageSuccess).toHaveBeenCalledWith(
      'generate.commandSubmittedWithMessageId cmd-track-1'
    )
    expect(onSubmitTracking).toHaveBeenCalledWith({ logRecorded: undefined, messageId: 'cmd-track-1', status: undefined })
    expect(fetchData).toHaveBeenCalled()
    expect(closeDialog).toHaveBeenCalled()
  })

  it('submits expected attribute payload with expiry and attribute send type', async () => {
    const { expectApi, flow, formModel } = createFlow({
      isCommand: () => false
    })
    formModel.expected = true
    formModel.time = 2

    await flow.submit()

    expect(expectApi).toHaveBeenCalledWith({
      device_id: 'device-1',
      expiry: '2024-01-01T00:00:00+00:00',
      identify: null,
      payload: JSON.stringify({ mode: 'auto' }),
      send_type: 'attribute'
    })
  })

  it('uses the direct method API and preserves the correlated device result', async () => {
    const { directMethodApi, flow, formModel, onDirectMethodResult, onSubmitTracking, submitApi } = createFlow()
    formModel.waitForResponse = true
    formModel.timeoutSeconds = 12
    directMethodApi.mockResolvedValueOnce({
      error: null,
      data: {
        message_id: 'direct-1',
        device_id: 'device-1',
        identify: 'reboot',
        status: '3',
        outcome: 'device_succeeded',
        published: true,
        log_recorded: true,
        device_responded: true,
        device_succeeded: true,
        timed_out: false,
        response_payload: '{"result":0}',
        timeout_seconds: 12,
        elapsed_ms: 81
      }
    })

    await flow.submit()

    expect(submitApi).not.toHaveBeenCalled()
    expect(directMethodApi).toHaveBeenCalledWith({
      device_id: 'device-1',
      identify: 'reboot',
      timeout_seconds: 12,
      value: JSON.stringify({ delay: 5 })
    })
    expect(onSubmitTracking).toHaveBeenCalledWith({ logRecorded: true, messageId: 'direct-1', status: '3' })
    expect(onDirectMethodResult).toHaveBeenCalledWith(expect.objectContaining({
      message_id: 'direct-1',
      outcome: 'device_succeeded',
      response_payload: '{"result":0}'
    }))
    expect(hoisted.messageSuccess).toHaveBeenCalledWith('generate.directMethodSucceeded')
  })

  it('keeps the dialog open when attribute submit has no selected attributes', async () => {
    const { attributeList, closeDialog, flow, submitApi } = createFlow({
      isCommand: () => false
    })
    attributeList.value = [{ data_identifier: 'mode', inputValue: 'auto', attributeType: 'string', checked: false }]

    await flow.submit()

    expect(submitApi).not.toHaveBeenCalled()
    expect(closeDialog).not.toHaveBeenCalled()
  })

  it('guards quick command duplicate clicks and refreshes after a successful publish', async () => {
    const { fetchData, flow, onSubmitTracking } = createFlow()
    hoisted.commandDataPub.mockResolvedValueOnce({ error: null, data: { message_id: 'quick-track-1' } })

    await flow.onCommandChange({ id: 'cmd-1', instruct: '1', data_identifier: 'switch' })

    expect(hoisted.commandDataPub).toHaveBeenCalledWith({
      device_id: 'device-1',
      identify: 'switch',
      value: '1'
    })
    expect(hoisted.messageSuccess).toHaveBeenCalledWith(
      'generate.commandSubmittedWithMessageId quick-track-1'
    )
    expect(onSubmitTracking).toHaveBeenCalledWith({
      logRecorded: undefined,
      messageId: 'quick-track-1',
      status: undefined
    })
    expect(fetchData).toHaveBeenCalled()
    expect(flow.quickCommandLoadingId.value).toBe('')
  })

  it('does not imply command-log tracking when backend accepted publish but did not record the log', async () => {
    const { flow, submitApi } = createFlow()
    submitApi.mockResolvedValueOnce({ error: null, data: { log_recorded: false, message_id: 'cmd-no-log' } })

    await flow.submit()

    expect(hoisted.messageSuccess).toHaveBeenCalledWith(
      'generate.commandSubmittedLogUnavailable cmd-no-log'
    )
  })
})

﻿<!--
  文件用途: 设备详情页里的“分布/表格 + 下发弹窗”公共模块。
  核心逻辑: 承接父层传入的查询、下发、期望消息接口，统一维护列表展示、命令/属性下发和提交后刷新。
  查询/提交/期望消息联动链路:
  1. 页面挂载、手动刷新、翻页后，统一通过 fetchDataApi 拉取列表数据。
  2. 打开弹窗后，根据 isCommand 决定加载命令标识及参数模板，或加载属性集供勾选编辑。
  3. 提交时先把可视化表单统一折叠为 textValue JSON，再根据 expected 分流到 submitApi 或 expectApi。
  4. 成功后统一重新查询列表并关闭弹窗，确保表格展示与最近一次操作结果保持同一观察面。
  静态审查建议:
  - props、列表项、参数项大量使用 any，后续适合收敛成显式类型，降低接口口径漂移风险。
  - fetchDataApi / submitApi / expectApi 目前依赖多种 data 字段兜底兼容，建议沉淀统一返回契约。
  - visual 页签与文本页签共同读写 formModel.textValue，后续若继续扩展可考虑拆分“编辑态”和“提交态”。
-->
<script setup lang="ts">
import { computed, getCurrentInstance, onMounted, reactive, ref } from 'vue'
import {
  type FormInst,
  type FormRules,
  NAlert,
  NButton,
  NCard,
  NCheckbox,
  NDataTable,
  NFlex,
  NForm,
  NFormItem,
  NGrid,
  NGridItem,
  NIcon,
  NInput,
  NInputNumber,
  NModal,
  NPagination,
  NPopover,
  NSelect,
  NSwitch,
  NTabs,
  NTabPane
} from 'naive-ui'
import { useLoading } from '@aetherlink/hooks'
import { Refresh } from '@vicons/ionicons5'
import type { FlatResponseFailData, FlatResponseSuccessData } from '@aetherlink/axios'
import { commandDataById, deviceCustomCommandsIdList, getAttributeDataSet } from '@/service/api'
import type { DirectMethodResult } from '@/service/api'
import { $t } from '@/locales'
import { isJSON } from '@/utils/common/tool'
import { createLogger } from '@/utils/logger'
import { getDescriptionText, normalizeAttributeItem } from './distributionAttributePayload'
import { commandParamsForIdentifier } from './distributionCommandPayload'
import { quickCommandKey } from './distributionSubmitPayload'
import {
  createDeliveryModeView,
  createSubmitTrackingView,
  normalizeDistributionListView,
  shouldDisableDistributionSubmit
} from './distributionTableState'
import type { CommandSubmitTracking } from './useDistributionSubmitFlow'
import { useDistributionSubmitFlow } from './useDistributionSubmitFlow'
const logger = createLogger('Table')
// props 契约:
// - id 和 fetchDataApi 是最小必需输入，决定当前设备上下文和列表查询能力。
// - isCommand 决定弹窗走“命令下发”还是“属性下发”分支。
// - submitApi / expectApi 都是可选能力，由 formModel.expected 决定最终调用哪条提交链路。
// - tableColumns / buttonName / noRefresh / expect 只影响展示与交互开关，不改变核心载荷结构。
const props = defineProps<{
  id: string
  noRefresh?: boolean
  isCommand?: boolean
  buttonName?: string
  tableColumns: any[] | undefined
  expect?: boolean
  submitApi?: (params: any) => Promise<FlatResponseSuccessData | FlatResponseFailData>
  directMethodApi?: (params: any) => Promise<FlatResponseSuccessData | FlatResponseFailData>
  directMethodOnline?: boolean
  expectApi?: (params: any) => Promise<FlatResponseSuccessData | FlatResponseFailData>
  fetchDataApi: (params: any) => Promise<FlatResponseSuccessData | FlatResponseFailData>
  onDirectMethodResult?: (result: DirectMethodResult) => void | Promise<void>
  onSubmittedTracking?: (tracking: CommandSubmitTracking) => void | Promise<void>
}>()
const tableData = ref<any[] | undefined>()
const page_coune = ref(0)
const the_page = ref(1)
const showDialog = ref(false)
const formRef = ref<FormInst | null>(null)
const formModel = reactive({
  commandValue: '',
  textValue: '',
  expected: false,
  time: null as number | null,
  waitForResponse: false,
  timeoutSeconds: 10 as number | null
})
const options = ref()
const { loading, startLoading, endLoading } = useLoading()
const paramsSelect = ref<any>([
  { label: 'true', value: true },
  { label: 'false', value: false }
])
const paramsData = ref<any>([])
const attributeList = ref<any[]>([])
const attributeLoading = ref(false)
const isTextArea = ref<any>(true)
const latestSubmitTracking = ref<CommandSubmitTracking | null>(null)

// 管理弹窗里的“可视化配置 / 文本直输”页签。
const activeTab = ref('visual')
const rules = computed<FormRules>(() => {
  const r: FormRules = {}
  if (props.isCommand && isTextArea.value) {
    r.commandValue = {
      required: true,
      message: $t('page.manage.validation.commandIdentifierRequired'),
      trigger: ['input', 'blur']
    }
  }
  return r
})

// 查询链路入口:
// - 页面挂载、手动刷新、翻页、提交成功后都会回到这里。
// - noRefresh 为 true 时不带分页参数，表示由父层接口自行控制返回规模。
// - 当前兼容 data.value / data.list / 数组本体，以及 count / total 两类分页字段。
const fetchDataFunction = async () => {
  startLoading()

  try {
    const { data, error } = await props.fetchDataApi({
      page: !props.noRefresh ? the_page.value : undefined,
      page_size: !props.noRefresh ? 4 : undefined,
      device_id: props.id
    })
    if (!error) {
      const listView = normalizeDistributionListView(data)
      tableData.value = listView.rows
      page_coune.value = listView.pageCount
    }
  } catch (error) {
    logger.warn('[DistributionAndTable] Failed to fetch distribution table data.', {
      deviceId: props.id,
      error: error instanceof Error ? error.message : error
    })
  } finally {
    endLoading()
  }
}

// 属性下发弹窗打开前装载当前设备的属性集元数据，映射成勾选行模型。
const loadAttributeList = async () => {
  attributeLoading.value = true
  try {
    const { data, error } = await getAttributeDataSet(props.id)
    if (!error && Array.isArray(data)) {
      attributeList.value = data.map((item: any) => ({
        ...normalizeAttributeItem(item),
        checked: false,
        inputValue: ''
      }))
    } else {
      attributeList.value = []
    }
  } catch (error) {
    logger.error('loadAttributeList failed', {
      error: error instanceof Error ? error.message : error
    })
    attributeList.value = []
  } finally {
    attributeLoading.value = false
  }
}

const openDialog = async () => {
  // 属性下发依赖属性集元数据；命令下发则主要依赖命令标识变化时的参数模板装载。
  showDialog.value = true
  if (!props.isCommand) {
    await loadAttributeList()
  }
}

const closeDialog = () => {
  showDialog.value = false
  formModel.textValue = ''
  paramsData.value = []
  formModel.commandValue = ''
  isTextArea.value = true
  formModel.expected = false
  formModel.time = null
  formModel.waitForResponse = false
  formModel.timeoutSeconds = 10
  activeTab.value = 'visual'
  attributeList.value = []
  formRef.value?.restoreValidation?.()
}

const handleSubmitTracking = async (tracking: CommandSubmitTracking) => {
  latestSubmitTracking.value = tracking
  await props.onSubmittedTracking?.(tracking)
}

const updatePage = (page: number) => {
  the_page.value = page
  fetchDataFunction()
}
const refresh = () => {
  the_page.value = 1
  fetchDataFunction()
}

defineExpose({ refresh })
const getOptions = async (show) => {
  if (show) {
    const res = await commandDataById(props.id)

    if (res && Array.isArray(res.data)) {
      options.value = res.data
    } else {
      options.value = []
    }
  }
}

// 处理命令标识输入：既支持选择已有命令，也允许手输自定义标识。
// 若命中已有命令且携带 params，则自动把参数模板灌入 visual 页签。
const handleCommandInput = (value: string) => {
  formModel.commandValue = value
  paramsData.value = commandParamsForIdentifier(options.value, value)
}

const commandList = ref()

const getListData = async () => {
  const { data } = await deviceCustomCommandsIdList(props.id)
  commandList.value = data
}
onMounted(() => {
  props.isCommand && getListData()
  fetchDataFunction()
})
const getPlatform = computed(() => {
  const { proxy }: any = getCurrentInstance()
  return proxy.getPlatform()
})
const validationJson = computed(() => {
  // 命令与属性下发共用同一套 JSON 静态校验反馈。
  if (formModel.textValue && !isJSON(formModel.textValue)) {
    return 'error'
  }
  return undefined
})
const inputFeedback = computed(() => {
  if (formModel.textValue && !isJSON(formModel.textValue)) {
    return $t('generate.inputRightJson')
  }
  return ''
})

const hasAttributeSelection = computed(() => attributeList.value.some((item) => item.checked))
const { onCommandChange, quickCommandLoadingId, submit, submitting } = useDistributionSubmitFlow({
  activeTab,
  attributeList,
  closeDialog,
  deviceId: () => props.id,
  directMethodApi: () => props.directMethodApi,
  expectApi: () => props.expectApi,
  fetchData: fetchDataFunction,
  formModel,
  formRef,
  hasAttributeSelection,
  isCommand: () => props.isCommand,
  logger,
  onDirectMethodResult: props.onDirectMethodResult,
  onSubmitTracking: handleSubmitTracking,
  paramsData,
  submitApi: () => props.submitApi
})
const selectAllAttributes = computed({
  get: () => attributeList.value.length > 0 && attributeList.value.every((item: any) => item.checked),
  set: (value) => {
    attributeList.value.forEach((item) => {
      item.checked = value
    })
  }
})
const isAttributeIndeterminate = computed(() => {
  const checkedCount = attributeList.value.filter((item) => item.checked).length
  return checkedCount > 0 && checkedCount < attributeList.value.length
})

const isSubmitDisabled = computed(() => {
  const payloadDisabled = shouldDisableDistributionSubmit({
    isCommand: props.isCommand,
    commandValue: formModel.commandValue,
    textValue: formModel.textValue,
    isValidJson: isJSON
  })
  if (payloadDisabled) return true
  if (!formModel.waitForResponse) return false
  const timeoutSeconds = Number(formModel.timeoutSeconds)
  return props.directMethodOnline === false || !Number.isFinite(timeoutSeconds) || timeoutSeconds < 1 || timeoutSeconds > 30
})

const visualTabLabel = computed(() =>
  props.isCommand ? $t('generate.visual-config') : $t('generate.attribute-config')
)
const customTabLabel = computed(() => (props.isCommand ? $t('generate.command-line') : $t('generate.custom-attribute')))
const deliveryModeView = computed(() => createDeliveryModeView(formModel.expected, formModel.waitForResponse, $t))
const latestSubmitTrackingView = computed(() => createSubmitTrackingView(latestSubmitTracking.value, $t))
const directMethodModeDisabled = computed(() => props.directMethodOnline === false)
const submitButtonLabel = computed(() =>
  formModel.waitForResponse && !formModel.expected ? $t('generate.directMethodSendAndWait') : $t('common.send')
)
</script>

<template>
  <div class="">
    <div class="m-b-20px flex items-center">
      <NButton v-if="buttonName" type="primary" @click="openDialog">{{ buttonName }}</NButton>
      <div class="flex flex-1 flex-justify-end">
        <NButton v-if="!noRefresh" :bordered="false" class="justify-end" @click="refresh">
          <NIcon size="18">
            <Refresh />
          </NIcon>
          {{ $t('generate.refresh') }}
        </NButton>
      </div>
    </div>

    <NGrid v-if="isCommand" x-gap="20" y-gap="20" cols="1 s:2 m:3 l:4" responsive="screen">
      <NGridItem v-for="item in commandList" :key="item.id">
        <NButton
          size="large"
          :loading="quickCommandLoadingId === quickCommandKey(item)"
          :disabled="item.enable_status === 'disable' || Boolean(quickCommandLoadingId)"
          class="title w-160px p-24px cursor-pointer ellipsis-text text-16px font-600"
          @click="onCommandChange(item)"
        >
          {{ item.buttom_name }}
        </NButton>
      </NGridItem>
    </NGrid>
    <NDataTable class="mb-4 mt-4" :loading="loading" :columns="tableColumns" :data="tableData" />
    <div class="flex flex-justify-end">
      <NPagination
        v-if="!noRefresh"
        :page-count="page_coune"
        :page="the_page"
        :page-size="4"
        @update:page="updatePage"
      />
    </div>
    <NModal v-if="submitApi" v-model:show="showDialog" :class="getPlatform ? 'w-90%' : 'w-450px'">
      <n-card :title="isCommand ? $t('generate.issueCommand') : $t('generate.issue-attribute')">
        <NForm ref="formRef" :model="formModel" :rules="rules" :label-placement="formModel.expected ? 'left' : 'top'">
          <div v-if="expect" class="flex">
            <NFormItem>
              <template #label>
                <div class="flex-ai-c flex">
                  {{ $t('generate.expectedMessage') }}
                  <n-popover trigger="hover">
                    <template #trigger>
                      <SvgIcon icon="mdi:help-circle-outline" class="text-20px" />
                    </template>
                    <span>{{ $t('generate.expectedMessageTip') }}</span>
                  </n-popover>
                </div>
              </template>

              <n-switch v-model:value="formModel.expected" />
            </NFormItem>
            <NFormItem v-if="formModel.expected" :label="$t('generate.expirationTime')" class="ml-20px">
              <div class="flex-ai-c flex">
                <n-input-number v-model:value="formModel.time" :show-button="false" class="w-80px" />
                <div class="fs-0">{{ $t('generate.hour') }}</div>
              </div>
            </NFormItem>
          </div>
          <div v-if="isCommand && !formModel.expected && directMethodApi" class="direct-method-options">
            <NFormItem :label="$t('generate.waitForDeviceResponse')">
              <NSwitch v-model:value="formModel.waitForResponse" :disabled="directMethodModeDisabled" />
            </NFormItem>
            <NFormItem
              v-if="formModel.waitForResponse"
              :label="$t('generate.directMethodTimeoutSeconds')"
              class="direct-method-timeout"
            >
              <NInputNumber
                v-model:value="formModel.timeoutSeconds"
                :min="1"
                :max="30"
                :precision="0"
                :show-button="true"
              />
              <span>{{ $t('generate.second') }}</span>
            </NFormItem>
          </div>
          <NAlert
            v-if="isCommand && formModel.waitForResponse && directMethodModeDisabled"
            type="error"
            :show-icon="false"
            class="delivery-mode-hint"
          >
            {{ $t('generate.directMethodOfflineHint') }}
          </NAlert>
          <NAlert v-if="isCommand" type="info" :show-icon="false" class="delivery-mode-hint">
            <strong>{{ deliveryModeView.title }}</strong>
            <div>{{ deliveryModeView.hint }}</div>
          </NAlert>
          <NAlert
            v-if="isCommand && latestSubmitTrackingView.visible"
            :type="latestSubmitTrackingView.type"
            :show-icon="false"
            class="delivery-mode-hint"
          >
            <strong>{{ $t('custom.device_details.messageId') }}</strong>
            <div>{{ latestSubmitTrackingView.text }}</div>
          </NAlert>
          <NFormItem
            v-if="isCommand"
            path="commandValue"
            :label="$t('generate.command-identifier')"
            required
            class="command-selector"
          >
            <NSelect
              v-model:value="formModel.commandValue"
              label-field="data_name"
              value-field="data_identifier"
              :options="options"
              filterable
              tag
              clearable
              :placeholder="$t('generate.command-identifier-placeholder')"
              @update:show="getOptions"
              @update:value="handleCommandInput"
            />
          </NFormItem>

          <!-- 页签切换只影响载荷来源，不改变 submit / expect 的最终分流。 -->
          <NTabs v-model:value="activeTab" type="line" animated>
            <NTabPane name="visual" :tab="visualTabLabel">
              <template v-if="isCommand">
                <div v-if="formModel.commandValue !== ''">
                  <div v-for="item in paramsData" :key="item.id" class="form_box">
                    <div class="form_table">
                      <NFormItem :label="item.data_name" label-placement="left" label-width="80px" label-align="left">
                        <NInput v-if="item.param_type === 'string'" v-model:value="item[item.data_identifier]" />
                        <n-input-number
                          v-else-if="item.param_type === 'Number'"
                          v-model:value="item[item.data_identifier]"
                        />
                        <n-select
                          v-else-if="item.param_type === 'Boolean'"
                          v-model:value="item[item.data_identifier]"
                          :options="paramsSelect"
                        />
                        <n-select
                          v-else-if="item.param_type === 'Enum'"
                          v-model:value="item[item.data_identifier]"
                          :options="
                            item.enum_config?.map((v) => {
                              return {
                                ...v,
                                label: v.desc
                              }
                            }) || []
                          "
                          :placeholder="$t('generate.please-select')"
                        />
                        <div class="description">
                          {{ $t('generate.description-label') }}：{{
                            getDescriptionText(item) || $t('generate.description-empty')
                          }}
                        </div>
                      </NFormItem>
                    </div>
                  </div>
                  <div v-if="paramsData.length === 0" class="empty-params">
                    <p>{{ $t('generate.no-params-available') }}</p>
                  </div>
                </div>
                <div v-else class="empty-params">
                  <p>{{ $t('generate.select-command-first') }}</p>
                </div>
              </template>
              <template v-else>
                <div v-if="attributeLoading" class="empty-params">
                  <p>{{ $t('generate.loading') }}</p>
                </div>
                <div v-else-if="attributeList.length">
                  <div class="attribute-toolbar">
                    <NCheckbox v-model:checked="selectAllAttributes" :indeterminate="isAttributeIndeterminate">
                      {{ $t('generate.select-all') }}
                    </NCheckbox>
                  </div>
                  <div v-for="item in attributeList" :key="item.key || item.id" class="attribute-row">
                    <div class="attribute-info">
                      <NCheckbox v-model:checked="item.checked">
                        <div class="attribute-label">
                          <div v-if="item.data_name" class="attribute-name">
                            {{ item.data_name }}
                          </div>
                          <div class="attribute-key">{{ item.key }}</div>
                        </div>
                      </NCheckbox>
                    </div>
                    <div class="attribute-input">
                      <NInput
                        v-model:value="item.inputValue"
                        :placeholder="$t('generate.attribute-value-placeholder')"
                        :disabled="!item.checked"
                      />
                    </div>
                  </div>
                  <div v-if="!hasAttributeSelection" class="attribute-helper">
                    {{ $t('generate.attribute-helper-text') }}
                  </div>
                </div>
