import { createLogger } from '@/utils/logger'

const logger = createLogger('DistributionAttributePayload')

export function formatAttributeValue(value: any) {
  if (value === null || value === undefined) return ''
  if (typeof value === 'object') {
    try {
      return JSON.stringify(value)
    } catch (error) {
      logger.error('Failed to stringify attribute value:', error)
      return ''
    }
  }
  return value
}

export function normalizeAttributeItem(item: any) {
  const type = (item.data_type || typeof item.value || 'string').toString().toLowerCase()
  return {
    ...item,
    checked: false,
    attributeType: type,
    inputValue: type === 'number' ? Number(item.value ?? '') : formatAttributeValue(item.value)
  }
}

export function parseBooleanValue(value: any) {
  if (typeof value === 'boolean') return value
  if (value === 'true' || value === '1' || value === 1) return true
  if (value === 'false' || value === '0' || value === 0) return false
  return Boolean(value)
}

export function parseNumberValue(value: any) {
  if (typeof value === 'number') return value
  const num = Number(value)
  return Number.isNaN(num) ? value : num
}

export function parseJsonValue(value: any) {
  if (typeof value !== 'string') return value
  try {
    return JSON.parse(value)
  } catch (error) {
    logger.warn('attribute payload JSON parse failed:', error)
    return value
  }
}

export const getDescriptionText = (item: any) => item?.description_cn || item?.description || ''

export function buildAttributePayload(attributeList: any[]) {
  const payload: Record<string, any> = {}
  attributeList
    .filter((item) => item.checked)
    .forEach((item) => {
      const key = item.key || item.data_identifier || item.data_name
      if (!key) return

      let value = item.inputValue
      switch (item.attributeType) {
        case 'number':
          value = parseNumberValue(value)
          break
        case 'boolean':
          value = parseBooleanValue(value)
          break
        case 'object':
        case 'array':
        case 'json':
          value = parseJsonValue(value)
          break
        default:
          break
      }
      payload[key] = value
    })
  return payload
}

import { createLogger } from '@/utils/logger'

const logger = createLogger('DistributionCommandPayload')

export function buildCommandPayload(paramsData: any[]) {
  const payload: Record<string, any> = {}
  paramsData.forEach((item) => {
    if (!item?.data_identifier) return
    payload[item.data_identifier] = item[item.data_identifier]
  })
  return payload
}

export function parseCommandParamsTemplate(rawParams: unknown) {
  if (!rawParams) return []
  if (Array.isArray(rawParams)) return rawParams
  if (typeof rawParams !== 'string') return []

  try {
    const parsed = JSON.parse(rawParams)
    return Array.isArray(parsed) ? parsed : []
  } catch (error) {
    logger.error('Failed to parse command params template:', error)
    return []
  }
}

export function commandParamsForIdentifier(options: any[] | undefined, identifier: string) {
  const option = options?.find((item: any) => item.data_identifier === identifier)
  return parseCommandParamsTemplate(option?.params)
}

type DistributionSubmitInput = {
  deviceId: string
  isCommand?: boolean
  textValue?: string | null
  commandValue?: string | null
}

type ExpectedSubmitInput = DistributionSubmitInput & {
  expiry: string | null
}

export const normalizedPayloadValue = (textValue?: string | null) => (textValue ? textValue : null)

export function buildDistributionSubmitPayload(input: DistributionSubmitInput) {
  if (input.isCommand) {
    return {
      device_id: input.deviceId,
      value: normalizedPayloadValue(input.textValue),
      identify: input.commandValue
    }
  }

  return {
    device_id: input.deviceId,
    value: normalizedPayloadValue(input.textValue)
  }
}

export function buildExpectedMessagePayload(input: ExpectedSubmitInput) {
  return {
    device_id: input.deviceId,
    payload: normalizedPayloadValue(input.textValue),
    send_type: input.isCommand ? 'command' : 'attribute',
    expiry: input.expiry,
    identify: input.isCommand ? input.commandValue : null
  }
}

export function buildQuickCommandPayload(deviceId: string, row: any) {
  return {
    device_id: deviceId,
    value: row?.instruct,
    identify: row?.data_identifier
  }
}

export const quickCommandKey = (row: any) => String(row?.id || row?.data_identifier || row?.buttom_name || '')

export const isApiError = (response: { error?: unknown } | undefined) => Boolean(response?.error)

import type { CommandSubmitTracking } from './useDistributionSubmitFlow'

export type Translate = (key: string) => string

export type DistributionListView = {
  rows: any[]
  pageCount: number
}

export function normalizeDistributionListView(data: any, pageSize = 4): DistributionListView {
  const rows = data?.value || data?.list || (Array.isArray(data) ? data : []) || []
  const total = data?.count || data?.total || 0

  return {
    rows,
    pageCount: total ? Math.ceil(total / pageSize) : 0
  }
}

export function shouldDisableDistributionSubmit(options: {
  isCommand?: boolean
  commandValue?: string
  textValue?: string
  isValidJson: (value: string) => boolean
}) {
  if (options.isCommand && !options.commandValue) return true
  if (options.textValue && !options.isValidJson(options.textValue)) return true
  return false
}

export function createDeliveryModeView(isExpected: boolean, waitForResponse: boolean, t: Translate) {
  if (isExpected) {
    return {
      title: t('generate.deliveryModeExpectedTitle'),
      hint: t('generate.deliveryModeExpectedHint')
    }
  }
  if (waitForResponse) {
    return {
      title: t('generate.deliveryModeDirectTitle'),
      hint: t('generate.deliveryModeDirectHint')
    }
  }
  return {
    title: t('generate.deliveryModeImmediateTitle'),
    hint: t('generate.deliveryModeImmediateHint')
  }
}

export function createSubmitTrackingView(tracking: CommandSubmitTracking | null, t: Translate) {
  if (!tracking?.messageId) {
    return {
      visible: false,
      type: 'success' as const,
      text: ''
    }
  }

  const key =
    tracking.logRecorded === false ? 'generate.commandSubmittedLogUnavailable' : 'generate.commandSubmittedWithMessageId'

  return {
    visible: true,
    type: tracking.logRecorded === false ? ('warning' as const) : ('success' as const),
    text: `${t(key)} ${tracking.messageId}`
  }
}

import type { ComputedRef, Ref } from 'vue'
import { ref } from 'vue'
import type { FormInst } from 'naive-ui'
import type { FlatResponseFailData, FlatResponseSuccessData } from '@aetherlink/axios'
import dayjs from 'dayjs'
import { commandDataPub, type DirectMethodResult } from '@/service/api'
import { $t } from '@/locales'
import { isJSON } from '@/utils/common/tool'
import { buildAttributePayload } from './distributionAttributePayload'
import { buildCommandPayload } from './distributionCommandPayload'
import {
  buildDistributionSubmitPayload,
  buildExpectedMessagePayload,
  buildQuickCommandPayload,
  isApiError,
  quickCommandKey
} from './distributionSubmitPayload'

type SubmitApi = (params: any) => Promise<FlatResponseSuccessData | FlatResponseFailData>

export type CommandSubmitTracking = {
  logRecorded?: boolean
  messageId?: string
  status?: string | number
}

type DistributionFormModel = {
  commandValue: string
  textValue: string
  expected: boolean
  time: number | null
  waitForResponse: boolean
  timeoutSeconds: number | null
}

type DistributionSubmitFlowOptions = {
  activeTab: Ref<string>
  attributeList: Ref<any[]>
  closeDialog: () => void
  deviceId: () => string
  directMethodApi?: () => SubmitApi | undefined
  expectApi: () => SubmitApi | undefined
  fetchData: () => Promise<void>
  formModel: DistributionFormModel
  formRef: Ref<FormInst | null>
  hasAttributeSelection: ComputedRef<boolean>
  isCommand: () => boolean | undefined
  logger: { error: (...args: any[]) => void }
  onDirectMethodResult?: (result: DirectMethodResult) => void | Promise<void>
  onSubmitTracking?: (tracking: CommandSubmitTracking) => void | Promise<void>
  paramsData: Ref<any[]>
  submitApi: () => SubmitApi | undefined
}

function extractDirectMethodResult(result: unknown): DirectMethodResult | null {
  const payload = (result as any)?.data || result
  if (!payload?.message_id || !payload?.outcome) return null
  return payload as DirectMethodResult
}

function notifyDirectMethodResult(result: DirectMethodResult) {
  switch (result.outcome) {
    case 'device_succeeded':
      window.$message?.success($t('generate.directMethodSucceeded'))
      return
    case 'timeout':
      window.$message?.warning($t('generate.directMethodTimedOut'))
      return
    case 'device_failed':
      window.$message?.error($t('generate.directMethodDeviceFailed'))
      return
    default:
      window.$message?.error($t('generate.directMethodDeliveryFailed'))
  }
}

function extractCommandSubmitTracking(result: unknown): CommandSubmitTracking {
  const payload = (result as any)?.data || result
  return {
    logRecorded: payload?.log_recorded ?? payload?.logRecorded,
    messageId: payload?.message_id || payload?.messageId,
    status: payload?.status
  }
}

function buildSubmitSuccessMessage(result: unknown, isCommand?: boolean, isExpected?: boolean) {
  if (!isCommand || isExpected) return $t('generate.sendingSuccess')

  const tracking = extractCommandSubmitTracking(result)
  if (tracking.messageId) {
    if (tracking.logRecorded === false) {
      return `${$t('generate.commandSubmittedLogUnavailable')} ${tracking.messageId}`
    }
    return `${$t('generate.commandSubmittedWithMessageId')} ${tracking.messageId}`
  }
  return $t('generate.commandSubmittedAwaitingLog')
}

export function useDistributionSubmitFlow(options: DistributionSubmitFlowOptions) {
  const submitting = ref(false)
  const quickCommandLoadingId = ref('')

  const submit = async () => {
    if (submitting.value) return

    try {
      await options.formRef.value?.validate()
      submitting.value = true

      if (options.activeTab.value === 'visual') {
        if (options.isCommand() && options.paramsData.value.length > 0) {
          options.formModel.textValue = JSON.stringify(buildCommandPayload(options.paramsData.value))
        }
        if (!options.isCommand()) {
          if (!options.hasAttributeSelection.value) {
            window.$message?.warning($t('generate.select-attribute-first'))
            return
          }
          options.formModel.textValue = JSON.stringify(buildAttributePayload(options.attributeList.value))
        }
      }

      if (options.formModel.textValue && !isJSON(options.formModel.textValue)) {
        window.$message?.error($t('generate.inputRightJson'))
        return
      }

      const submitPayload = buildDistributionSubmitPayload({
        deviceId: options.deviceId(),
        isCommand: options.isCommand(),
        textValue: options.formModel.textValue,
        commandValue: options.formModel.commandValue
      })

      const useDirectMethod = Boolean(
        options.isCommand() && !options.formModel.expected && options.formModel.waitForResponse
      )

      let result: FlatResponseSuccessData | FlatResponseFailData | undefined
      if (options.formModel.expected) {
        const expectApi = options.expectApi()
        if (expectApi) {
          const expiry = options.formModel.time ? new Date().getTime() + options.formModel.time * 60 * 60 * 1000 : null
          result = await expectApi(
            buildExpectedMessagePayload({
              deviceId: options.deviceId(),
              isCommand: options.isCommand(),
              textValue: options.formModel.textValue,
              commandValue: options.formModel.commandValue,
              expiry: expiry ? dayjs(expiry).format('YYYY-MM-DDTHH:mm:ssZ') : null
            })
          )
        }
      } else if (useDirectMethod) {
        const directMethodApi = options.directMethodApi?.()
        if (!directMethodApi) {
          window.$message?.error($t('generate.directMethodUnavailable'))
          return
        }
        result = await directMethodApi({
          ...submitPayload,
          timeout_seconds: options.formModel.timeoutSeconds || 10
        })
      } else {
        const submitApi = options.submitApi()
        if (submitApi) {
          result = await submitApi(submitPayload)
        }
      }

      if (isApiError(result)) {
        window.$message?.error($t('generate.sendingFail'))
        return
      }

      if (options.isCommand() && !options.formModel.expected) {
        const tracking = extractCommandSubmitTracking(result)
        if (tracking.messageId) {
          await options.onSubmitTracking?.(tracking)
        }
      }
      if (useDirectMethod) {
        const directMethodResult = extractDirectMethodResult(result)
        if (!directMethodResult) {
          window.$message?.error($t('generate.directMethodInvalidResponse'))
          return
        }
        await options.onDirectMethodResult?.(directMethodResult)
        notifyDirectMethodResult(directMethodResult)
      } else {
        window.$message?.success(
          buildSubmitSuccessMessage(result, Boolean(options.isCommand()), options.formModel.expected)
        )
      }
      await options.fetchData()
      options.closeDialog()
    } catch (errors) {
      window.$message?.error($t('common.validateFail') || 'Validation failed, please check your input.')
      options.logger.error('Form validation failed:', errors)
    } finally {
      submitting.value = false
    }
  }

  const onCommandChange = async (row: any) => {
    const commandKey = quickCommandKey(row)
    if (quickCommandLoadingId.value) return

    quickCommandLoadingId.value = commandKey
    try {
      const result = await commandDataPub(buildQuickCommandPayload(options.deviceId(), row))
      if (isApiError(result)) {
        window.$message?.error($t('generate.sendingFail'))
        return
      }
      const tracking = extractCommandSubmitTracking(result)
      if (tracking.messageId) {
        await options.onSubmitTracking?.(tracking)
      }
      window.$message?.success(buildSubmitSuccessMessage(result, true, false))
      await options.fetchData()
    } finally {
      quickCommandLoadingId.value = ''
    }
  }

  return {
    onCommandChange,
    quickCommandLoadingId,
    submit,
    submitting
  }
}

