 * 核心逻辑: 通过 mock API、store 或时间行为验证 composable 的状态输出、动作和异常分支。
 * 关键注意事项: 测试应聚焦 composable 契约，避免依赖 RDI 操作视图 DOM 细节。
 * 重构建议: 继续补成功、失败、空数据和清理生命周期用例，提升组合函数边界可信度。
 */
import { defineComponent, nextTick } from 'vue'
import { mount } from '@vue/test-utils'
import { beforeEach, describe, expect, it, vi } from 'vitest'

const { mockTelemetryDataCurrentKeys, mockGetDeviceOnlineStatus } = vi.hoisted(() => ({
  mockTelemetryDataCurrentKeys: vi.fn(),
  mockGetDeviceOnlineStatus: vi.fn()
}))

vi.mock('@/service/api', () => ({
  telemetryDataCurrentKeys: (...args: any[]) => mockTelemetryDataCurrentKeys(...args),
  getDeviceOnlineStatus: (...args: any[]) => mockGetDeviceOnlineStatus(...args)
}))

vi.mock('@/store/modules/app', () => ({
  useAppStore: () => ({ locale: 'en-US' })
}))

import { useRdiTelemetry } from '../useRdiTelemetry'

const Harness = defineComponent({
  props: {
    id: { type: String, required: true },
    online: { type: Number, default: undefined },
    deviceData: { type: Object, default: () => ({}) }
  },
  setup(props, { expose }) {
    const state = useRdiTelemetry(
      () => props.id,
      () => props.online,
      () => props.deviceData as Record<string, any>,
      (key) => key
    )

    expose(state)
    return () => null
  }
})

function mountHarness(props?: { id?: string; online?: number; deviceData?: Record<string, any> }) {
  return mount(Harness, {
    props: {
      id: props?.id ?? 'dev-1',
      online: props?.online,
      deviceData: props?.deviceData ?? {}
    }
  })
}

describe('useRdiTelemetry', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    vi.useRealTimers()
    window.localStorage.clear()
    mockTelemetryDataCurrentKeys.mockResolvedValue({ error: null, data: {} })
    mockGetDeviceOnlineStatus.mockResolvedValue({ error: null, data: { device_status: 0 } })
  })

  it('loads the stored temperature unit and persists changes', async () => {
    window.localStorage.setItem('rdi-temperature-unit', 'F')

    const wrapper = mountHarness()
    const vm = wrapper.vm as any

    expect(vm.temperatureUnit).toBe('F')
    expect(vm.formatTemperatureValue(0)).toBe('32.00')

    vm.temperatureUnit = 'C'
    await nextTick()

    expect(window.localStorage.getItem('rdi-temperature-unit')).toBe('C')
    wrapper.unmount()
  })

  it('normalizes realtime telemetry data and online status responses', async () => {
    mockTelemetryDataCurrentKeys.mockResolvedValue({
      error: null,
      data: [
        { key: 'temperature_1', value: 12.34 },
        { key: 'switch_1', value: 1 },
        { key: 'dry_contact_output', value: '0' },
        { key: 'electricity_consumption', value: 5.678 },
        { key: 'led_status', value: 'slow_blink' }
      ]
    })
    mockGetDeviceOnlineStatus.mockResolvedValue({
      error: null,
      data: { device_status: '1' }
    })

    const wrapper = mountHarness({
      deviceData: { description: 'Cold room' }
    })
    const vm = wrapper.vm as any

    await vm.loadRealtimeState()

    expect(mockTelemetryDataCurrentKeys).toHaveBeenCalledWith({
      device_id: 'dev-1',
      keys: [
        'temperature_1',
        'temperature_2',
        'switch_1',
        'switch_2',
        'dry_contact_output',
        'electricity_consumption',
        'led_status'
      ]
    })
    expect(mockGetDeviceOnlineStatus).toHaveBeenCalledWith('dev-1')
    expect(vm.telemetry.temperature_1).toBe(12.34)
    expect(vm.liveOnlineStatus).toBe(1)
    expect(vm.deviceOnlineText).toBe('online')
    expect(vm.deviceDescriptionText).toBe('Cold room')
    expect(vm.telemetryRows).toEqual([
      { label: 'T1', value: '12.34', unit: 'C' },
      { label: 'T2', value: '--', unit: 'C' },
      { label: 'switch1', value: 'high', unit: '' },
      { label: 'switch2', value: '--', unit: '' },
      { label: 'dryContact', value: 'low', unit: '' },
      { label: 'kWh', value: '5.68', unit: 'kWh' },
      { label: 'LED1', value: 'ledSlowBlink', unit: '' }
    ])

    wrapper.unmount()
  })

  it('uses the parent device online state instead of refetching status', async () => {
    mockTelemetryDataCurrentKeys.mockResolvedValue({
      error: null,
      data: [{ key: 'temperature_1', value: 18 }]
    })

    const wrapper = mountHarness({
      online: 1,
      deviceData: { description: 'RDI cabinet' }
    })
    const vm = wrapper.vm as any

    await vm.loadRealtimeState()

    expect(mockTelemetryDataCurrentKeys).toHaveBeenCalledTimes(1)
    expect(mockGetDeviceOnlineStatus).not.toHaveBeenCalled()
    expect(vm.liveOnlineStatus).toBe(null)
    expect(vm.deviceOnlineText).toBe('online')
    expect(vm.deviceDescriptionText).toBe('RDI cabinet')

    wrapper.unmount()
  })

  it('ignores a stale telemetry response after the device id changes', async () => {
    let resolveFirstRequest: ((value: { error: null; data: Array<{ key: string; value: number }> }) => void) | undefined
    mockTelemetryDataCurrentKeys
      .mockImplementationOnce(
        () =>
          new Promise(resolve => {
            resolveFirstRequest = resolve
          })
      )
      .mockResolvedValueOnce({
        error: null,
        data: [{ key: 'temperature_1', value: 22 }]
      })

    const wrapper = mountHarness({ online: 1 })
    const vm = wrapper.vm as any
    const firstLoad = vm.loadTelemetry()

    await wrapper.setProps({ id: 'dev-2' })
    await vm.loadTelemetry()
    expect(vm.telemetry.temperature_1).toBe(22)

    if (!resolveFirstRequest) {
      throw new Error('first telemetry request did not start')
    }
    resolveFirstRequest({
      error: null,
      data: [{ key: 'temperature_1', value: 11 }]
    })
    await firstLoad

    expect(vm.telemetry.temperature_1).toBe(22)
    expect(mockTelemetryDataCurrentKeys).toHaveBeenNthCalledWith(1, expect.objectContaining({ device_id: 'dev-1' }))
    expect(mockTelemetryDataCurrentKeys).toHaveBeenNthCalledWith(2, expect.objectContaining({ device_id: 'dev-2' }))

    wrapper.unmount()
  })

  it('falls back to placeholder formatting for unknown values and empty descriptions', () => {
    const wrapper = mountHarness({
      deviceData: { Description: '   ' }
    })
    const vm = wrapper.vm as any

    expect(vm.formatSwitch('unexpected')).toBe('unexpected')
    expect(vm.formatLedStatus('mystery')).toBe('mystery')
    expect(vm.formatValue(undefined)).toBe('--')
    expect(vm.toAxisValue({ nested: true })).toBe('[object Object]')
    expect(vm.deviceDescriptionText).toBe('--')

    wrapper.unmount()
  })

  it('starts and stops the refresh timer around realtime loading', async () => {
    vi.useFakeTimers()
    mockTelemetryDataCurrentKeys.mockResolvedValue({
      error: null,
      data: [{ key: 'temperature_1', value: 21 }]
    })
    mockGetDeviceOnlineStatus.mockResolvedValue({
      error: null,
      data: { is_online: 1 }
    })

    const wrapper = mountHarness()
    const vm = wrapper.vm as any

    vm.startTelemetryRefresh()
    await vi.advanceTimersByTimeAsync(10_000)

    expect(mockTelemetryDataCurrentKeys).toHaveBeenCalledTimes(1)
    expect(mockGetDeviceOnlineStatus).toHaveBeenCalledTimes(1)

    vm.stopTelemetryRefresh()
    await vi.advanceTimersByTimeAsync(10_000)

    expect(mockTelemetryDataCurrentKeys).toHaveBeenCalledTimes(1)
    expect(mockGetDeviceOnlineStatus).toHaveBeenCalledTimes(1)

    wrapper.unmount()
  })
})

/**
 * 文件用途: RDI 操作视图命令下发 composable。
 * 核心逻辑: 构造命令 payload、发送 RDI command、维护 OTA 选择状态并统一处理命令错误。
 * 关键注意事项: public API 被 RdiDeviceOperationsView.vue 直接解构使用，字段名和 payload identifier 需与后端 RDI command 契约保持一致。
 * 重构建议: 保持 payload helper、发送 helper、状态 helper 和错误 helper 分离，避免面板层感知命令细节。
 */
import { computed, reactive, ref, watch } from 'vue'
import { rdiLatestFirmware, sendRdiCommand } from '@/service/api'
import type { RDICommandReq, RDICommandTracking, RDIConfig } from '@/service/api/rdi'
import { getOtaPackageList } from '@/service/product/update-package'
import { message } from '@/utils/common/discrete'
import { getBaseServerUrl } from '@/utils/common/tool'
import type { LabelKey } from '../constants/rdi-labels'

type TranslateRdiLabel = (key: LabelKey) => string
type DryContactLevel = 'high' | 'low'

type OtaCommandState = {
  firmware_url: string
  version: string
  size: number | null
  md5: string
}

type OtaPackageRecord = Record<string, unknown> & {
  id: string
  name?: string
  version?: string
  package_url?: string
  url?: string
  firmware_url?: string
  size?: number | string
  package_size?: number | string
  file_size?: number | string
  signature?: string
  md5?: string
  checksum?: string
  additional_info?: unknown
}

type LoadingRef = {
  value: boolean
}

type CommandSendResult = {
  success: boolean
  tracking: RDICommandTracking | null
}

function createOtaCommandState(): OtaCommandState {
  return {
    firmware_url: '',
    version: '',
    size: null,
    md5: ''
  }
}

function readPayloadList(payload: unknown): unknown[] {
  if (Array.isArray(payload)) return payload
  if (payload && typeof payload === 'object' && Array.isArray((payload as Record<string, unknown>).list)) {
    return (payload as { list: unknown[] }).list
  }
  return []
}

function normalizeOtaPackages(payload: unknown): OtaPackageRecord[] {
  return readPayloadList(payload)
    .filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === 'object')
    .map((item) => ({ ...item, id: String(item.id ?? '') }))
    .filter((item): item is OtaPackageRecord => Boolean(item.id))
}

function parsePackageAdditionalInfo(value: unknown): Record<string, unknown> {
  if (!value) return {}
  if (typeof value === 'object' && !Array.isArray(value)) return value as Record<string, unknown>
  if (typeof value !== 'string') return {}
  try {
    const parsed = JSON.parse(value)
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {}
  } catch {
    return {}
  }
}

function parsePackageSize(...values: unknown[]): number | null {
  for (const value of values) {
    const numeric = typeof value === 'string' && value.trim() ? Number(value) : value
    if (typeof numeric === 'number' && Number.isFinite(numeric) && numeric > 0) return numeric
  }
  return null
}

function resolvePackageUrl(rawUrl: unknown) {
  const url = String(rawUrl ?? '').trim()
  if (!url) return ''
  if (/^https?:\/\//i.test(url)) return url
  const baseUrlWithoutApi = getBaseServerUrl().replace('/api/v1', '/')
  return `${baseUrlWithoutApi.replace(/\/+$/, '')}/${url.replace(/^\/+/, '')}`
}

function readPackageVersion(pkg: OtaPackageRecord, additionalInfo: Record<string, unknown>) {
  return String(pkg.version ?? additionalInfo.version ?? '')
}

function readPackageChecksum(pkg: OtaPackageRecord, additionalInfo: Record<string, unknown>) {
  return String(pkg.signature ?? pkg.md5 ?? pkg.checksum ?? additionalInfo.md5 ?? additionalInfo.signature ?? '')
}

function readPackageUrl(pkg: OtaPackageRecord) {
  return pkg.package_url ?? pkg.firmware_url ?? pkg.url ?? ''
}

function buildOtaPackageLabel(pkg: OtaPackageRecord) {
  const name = String(pkg.name ?? pkg.id)
  return pkg.version ? `${name} (${pkg.version})` : name
}

function getOtaMissingFieldLabels(otaCommand: OtaCommandState, t: TranslateRdiLabel) {
  const size = Number(otaCommand.size)
  const missing: LabelKey[] = []

  if (!otaCommand.firmware_url.trim()) missing.push('firmwareUrl')
  if (!otaCommand.version.trim()) missing.push('version')
  if (!Number.isFinite(size) || size <= 0) missing.push('size')
  if (!otaCommand.md5.trim()) missing.push('md5')

  return missing.map((key) => t(key))
}

function applyOtaPackageToState(pkg: OtaPackageRecord, otaCommand: OtaCommandState) {
  const additionalInfo = parsePackageAdditionalInfo(pkg.additional_info)
  otaCommand.firmware_url = resolvePackageUrl(readPackageUrl(pkg))
  otaCommand.version = readPackageVersion(pkg, additionalInfo)
  otaCommand.size = parsePackageSize(pkg.size, pkg.package_size, pkg.file_size, additionalInfo.size)
  otaCommand.md5 = readPackageChecksum(pkg, additionalInfo)
}

function normalizeFieldSettingValue(key: string, value: unknown) {
  const normalizedKey = key.toLowerCase()
  if (normalizedKey.startsWith('n')) {
    if (Array.isArray(value)) return value
    if (typeof value === 'string') {
      return value
        .split(',')
        .map((item) => item.trim())
        .filter(Boolean)
    }
  }

  if (normalizedKey.startsWith('sw')) {
    if (value && typeof value === 'object' && !Array.isArray(value)) return value
    if (typeof value === 'string') return { label: value }
  }

  return value
}

function normalizeFieldSetting(fieldSetting: RDIConfig['field_setting']) {
  return Object.entries(fieldSetting || {}).reduce<Record<string, unknown>>((params, [key, value]) => {
    params[key] = normalizeFieldSettingValue(key, value)
    return params
  }, {})
}

function buildDryContactCommandPayload(level: DryContactLevel, delaySeconds: number): RDICommandReq {
  return {
    identifier: 'set_dry_contact',
    params: {
      level,
      delay_seconds: delaySeconds
    }
  }
}

function buildDryContactTestCommandPayload(config: RDIConfig, durationSeconds: number): RDICommandReq {
  return {
    identifier: 'test_dry_contact',
    params: {
      level: config.dry_contact_alarm_level,
      duration_seconds: durationSeconds
    }
  }
}

function buildFieldSettingCommandPayload(config: RDIConfig, t: TranslateRdiLabel): RDICommandReq | null {
  const params = normalizeFieldSetting(config.field_setting)
  if (!Object.keys(params).length) {
    message.error(t('empty'))
    return null
  }
  return {
    identifier: 'set_field_setting',
    params
  }
}

function buildOtaUpgradeCommandPayload(otaCommand: OtaCommandState, t: TranslateRdiLabel): RDICommandReq | null {
  const size = Number(otaCommand.size)
  const missingLabels = getOtaMissingFieldLabels(otaCommand, t)
  if (missingLabels.length) {
    message.error(`${t('otaMissingFields')}: ${missingLabels.join(', ')}`)
    return null
  }
  return {
    identifier: 'ota_upgrade',
    params: {
      firmware_url: otaCommand.firmware_url.trim(),
      version: otaCommand.version.trim(),
      size,
      md5: otaCommand.md5.trim()
    }
  }
}

function buildSimpleCommandPayload(
  identifier: Extract<RDICommandReq['identifier'], 'unbind_device' | 'factory_reset'>
): RDICommandReq {
  return {
    identifier,
    params: {}
  }
}

function getErrorText(error: unknown, fallback: string) {
  if (typeof error === 'string') return error
  if (error && typeof error === 'object' && 'message' in error)
    return String((error as { message?: unknown }).message || fallback)
  return fallback
}

function handleCommandError(error: unknown, t: TranslateRdiLabel) {
  message.error(getErrorText(error, t('ota')))
}

function handleOtaPackageError(error: unknown, t: TranslateRdiLabel) {
  message.error(getErrorText(error, t('empty')))
}

function handleLatestFirmwareResponse(
  data: any,
  latestFirmwarePackage: { value: OtaPackageRecord | null },
  otaCommand: OtaCommandState,
  t: TranslateRdiLabel
) {
  if (!data?.update_available || !data.package) {
    latestFirmwarePackage.value = null
    message.success(t('alreadyLatest'))
    return
  }

  const pkg = normalizeOtaPackages([data.package])[0]
  if (!pkg) {
    latestFirmwarePackage.value = null
    message.error(t('empty'))
    return
  }

  latestFirmwarePackage.value = pkg
  applyOtaPackageToState(pkg, otaCommand)
  message.success(
    `${t('updateAvailable')}: ${readPackageVersion(pkg, parsePackageAdditionalInfo(pkg.additional_info))}`
  )
}

function normalizeCommandTracking(payload: any): RDICommandTracking | null {
  if (payload?.command_tracking && typeof payload.command_tracking === 'object') {
    return payload.command_tracking as RDICommandTracking
  }
  if (!payload?.message_id) return null
  return {
    message_id: String(payload.message_id),
    status: String(payload.tracking_status ?? payload.status ?? ''),
    device_id: String(payload.device_id ?? ''),
    identifier: String(payload.identifier ?? ''),
    operation_type: String(payload.operation_type ?? ''),
    log_recorded: payload.log_recorded !== false
  }
}

function buildCommandTrackingSummary(tracking: RDICommandTracking | null) {
  if (!tracking) return ''
  const logState = tracking.log_recorded ? 'log recorded' : 'log not recorded'
  return `${tracking.identifier || 'command'} message_id=${tracking.message_id || '--'} status=${tracking.status || '--'} (${logState})`
}

async function sendCommandPayload(
  deviceId: string,
  payload: RDICommandReq,
  loading: LoadingRef,
  t: TranslateRdiLabel
): Promise<CommandSendResult> {
  loading.value = true
  try {
    const { error, data } = await sendRdiCommand(deviceId, payload)
    if (error) {
      handleCommandError(error, t)
      return { success: false, tracking: null }
    }
    return { success: true, tracking: normalizeCommandTracking(data) }
  } catch (error) {
    handleCommandError(error, t)
    return { success: false, tracking: null }
  } finally {
    loading.value = false
  }
}

export function useRdiCommands(deviceId: () => string, config: RDIConfig, t: TranslateRdiLabel) {
  const commandLoading = ref(false)
  const dryCommandDelay = ref(0)
  const dryTestDuration = ref(1)
  const otaPackageLoading = ref(false)
  const otaPackageId = ref('')
  const latestFirmwareLoading = ref(false)
  const latestFirmwarePackage = ref<OtaPackageRecord | null>(null)
  const lastCommandTracking = ref<RDICommandTracking | null>(null)
  const otaPackages = ref<OtaPackageRecord[]>([])
  const otaCommand = reactive(createOtaCommandState())

  const otaPackageOptions = computed(() =>
    otaPackages.value.map((pkg) => ({
      label: buildOtaPackageLabel(pkg),
      value: pkg.id
    }))
  )
  const otaMissingFieldLabels = computed(() => getOtaMissingFieldLabels(otaCommand, t))
  const canSendOtaUpgrade = computed(() => otaMissingFieldLabels.value.length === 0)
  const commandTrackingSummary = computed(() => buildCommandTrackingSummary(lastCommandTracking.value))

  function applySelectedOtaPackage(id: string) {
    const selectedPackage = otaPackages.value.find((pkg) => pkg.id === id)
    if (selectedPackage) applyOtaPackageToState(selectedPackage, otaCommand)
  }

  async function sendPayload(payload: RDICommandReq | null) {
    if (!payload) return false
    const id = deviceId()
    if (!id) return false
    const result = await sendCommandPayload(id, payload, commandLoading, t)
    if (result.success) {
      lastCommandTracking.value = result.tracking
      if (result.tracking?.message_id) {
        message.success(buildCommandTrackingSummary(result.tracking))
      } else {
        message.success(t('sent'))
      }
    }
    return result.success
  }

  async function setDryContact(level: DryContactLevel) {
    return sendPayload(buildDryContactCommandPayload(level, dryCommandDelay.value))
  }

  async function testDryContact() {
    return sendPayload(buildDryContactTestCommandPayload(config, dryTestDuration.value))
  }

  async function sendFieldSetting() {
    return sendPayload(buildFieldSettingCommandPayload(config, t))
  }

  async function sendOtaUpgrade() {
    return sendPayload(buildOtaUpgradeCommandPayload(otaCommand, t))
  }

  async function sendUnbindDevice() {
    return sendPayload(buildSimpleCommandPayload('unbind_device'))
  }

  async function sendFactoryReset() {
    return sendPayload(buildSimpleCommandPayload('factory_reset'))
  }

  async function loadOtaPackages() {
    otaPackageLoading.value = true
    try {
      const { error, data } = await getOtaPackageList({ page: 1, page_size: 100 })
      if (error) {
        handleOtaPackageError(error, t)
        return
      }
      otaPackages.value = normalizeOtaPackages(data)
      applySelectedOtaPackage(otaPackageId.value)
    } catch (error) {
      handleOtaPackageError(error, t)
    } finally {
      otaPackageLoading.value = false
    }
  }

  function applyLatestFirmwarePackage() {
    if (!latestFirmwarePackage.value) {
      message.error(t('empty'))
      return
    }
    applyOtaPackageToState(latestFirmwarePackage.value, otaCommand)
  }

  async function checkLatestFirmware() {
    const id = deviceId()
    if (!id) return
    latestFirmwareLoading.value = true
    try {
      const { error, data } = await rdiLatestFirmware(id)
      if (error) {
        handleOtaPackageError(error, t)
        return
      }
      handleLatestFirmwareResponse(data, latestFirmwarePackage, otaCommand, t)
    } catch (error) {
      handleOtaPackageError(error, t)
    } finally {
      latestFirmwareLoading.value = false
    }
  }

  watch(otaPackageId, (value) => {
    applySelectedOtaPackage(value)
  })

  return {
    commandLoading,
    dryCommandDelay,
    dryTestDuration,
    otaPackageLoading,
    otaPackageId,
    latestFirmwareLoading,
    latestFirmwarePackage,
    lastCommandTracking,
    otaCommand,
    otaPackages,
    otaPackageOptions,
    otaMissingFieldLabels,
    canSendOtaUpgrade,
    commandTrackingSummary,
    setDryContact,
    testDryContact,
    sendFieldSetting,
    sendOtaUpgrade,
    sendUnbindDevice,
    sendFactoryReset,
    loadOtaPackages,
    applyLatestFirmwarePackage,
    checkLatestFirmware
  }
}

/**
 * 文件用途: RDI 操作视图配置状态 composable。
 * 核心逻辑: 加载/保存 RDI 设备配置，维护系统信息、温度范围、字段标签和额外字段读写。
 * 关键注意事项: 配置字段默认值、读写权限和保存 payload 必须与 backend RDI 配置模型一致。
 * 重构建议: 将默认配置、字段 normalize 和保存 payload 拆成纯函数，并覆盖缺字段/保存失败测试。
 */
import { computed, reactive, ref } from 'vue'
import { rdiDeviceConfig, updateRdiDeviceConfig } from '@/service/api'
import type { RDICommandTracking, RDIConfig, RDISystemInfo } from '@/service/api/rdi'
import { message } from '@/utils/common/discrete'
import { useAppStore } from '@/store/modules/app'
import { labels, systemExtraFieldLabels, systemExtraFieldDefinitions } from '../constants/rdi-labels'
import type { LabelKey, SystemExtraFieldKey } from '../constants/rdi-labels'

type FieldRecord = Record<string, unknown>

const promotedSystemInfoExtraKeys = [
  'address',
  'installation_date',
  'installer_company',
  'installer_contact',
  'installer_name',
  'installer_phone',
  'installer_email',
  'controller_serial_number'
] as const

export function defaultConfig(): RDIConfig {
  return {
    data_collection_interval: 60,
    alarm_sensor_1_enabled: true,
    alarm_sensor_2_enabled: true,
    sensor_1_upper: 80,
    sensor_1_lower: -10,
    sensor_2_upper: 80,
    sensor_2_lower: -10,
    sensor_1_duration: 30,
    sensor_2_duration: 30,
    switch_1_alarm_mode: 'disabled',
    switch_2_alarm_mode: 'disabled',
    switch_1_alarm_duration: 30,
    switch_2_alarm_duration: 30,
    dry_contact_alarm_level: 'high',
    dry_contact_normal_level: 'low',
    dry_contact_alarm_delay: 0,
    dry_contact_normal_delay: 0,
    notification_enabled: false,
    notification_temperature_alarm: true,
    notification_switch_alarm: true,
    notification_warranty_alarm: true,
    sensor_alarm_emails: '',
    switch_alarm_emails: '',
    warranty_alarm_emails: '',
    sensor_1_alarm_emails: '',
    sensor_2_alarm_emails: '',
    switch_1_alarm_emails: '',
    switch_2_alarm_emails: '',
    field_setting: {}
  }
}

export function defaultSystemInfo(): RDISystemInfo {
  return {
    installation_location: '',
    address: '',
    installation_date: '',
    installer_company: '',
    installer_contact: '',
    installer_name: '',
    installer_phone: '',
    installer_email: '',
    controller_serial_number: '',
    maintenance_technician: '',
    customer_name: '',
    contact_email: '',
    contact_phone: '',
    warranty_status: '',
    extra_fields: {}
  }
}

function normalizeFieldRecord(value: unknown): FieldRecord {
  return value && typeof value === 'object' && !Array.isArray(value) ? { ...(value as FieldRecord) } : {}
}

function normalizeCollectionInterval(value: unknown) {
  const interval = Number(value)
  return Number.isFinite(interval) && interval >= 45 && interval <= 60 ? interval : defaultConfig().data_collection_interval
}

function normalizeConfig(config?: Partial<RDIConfig>): RDIConfig {
  const next = {
    ...defaultConfig(),
    ...(config || {}),
    field_setting: normalizeFieldRecord(config?.field_setting)
  }
  next.data_collection_interval = normalizeCollectionInterval(next.data_collection_interval)
  return next
}

function normalizeSystemInfo(systemInfo?: Partial<RDISystemInfo>): RDISystemInfo {
  const extraFields = normalizeFieldRecord(systemInfo?.extra_fields)
  const promotedValues = promotedSystemInfoExtraKeys.reduce<Partial<RDISystemInfo>>((acc, key) => {
    const value = systemInfo?.[key] || extraFields[key]
    if (typeof value === 'string' && value.trim()) {
      acc[key] = value.trim()
    }
    return acc
  }, {})

  return {
    ...defaultSystemInfo(),
    ...(systemInfo || {}),
    ...promotedValues,
    extra_fields: extraFields
  }
}

function withoutPromotedSystemInfoExtraFields(extraFields?: Record<string, unknown>) {
  const next = normalizeFieldRecord(extraFields)
  promotedSystemInfoExtraKeys.forEach((key) => {
    delete next[key]
  })
  return next
}

function applyConfigSnapshot(
  config: RDIConfig,
  systemInfo: RDISystemInfo,
  snapshot?: { config?: Partial<RDIConfig>; system_info?: Partial<RDISystemInfo> }
) {
  Object.assign(config, normalizeConfig(snapshot?.config))
  Object.assign(systemInfo, normalizeSystemInfo(snapshot?.system_info))
}

function buildSavePayload(config: RDIConfig, systemInfo: RDISystemInfo, applyToDevice: boolean) {
  return {
    config: { ...config, field_setting: normalizeFieldRecord(config.field_setting) },
    system_info: { ...systemInfo, extra_fields: withoutPromotedSystemInfoExtraFields(systemInfo.extra_fields) },
    apply_to_device: applyToDevice
  }
}

function parseFieldValue(key: string, value: string): unknown {
  const trimmed = value.trim()
  if (key.startsWith('n')) {
    return trimmed
      .split(',')
      .map((item) => item.trim())
      .filter(Boolean)
  }

  if (key.startsWith('sw')) {
    try {
      const parsed = JSON.parse(trimmed)
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : { label: trimmed }
    } catch {
      return { label: trimmed }
    }
  }

  return trimmed
}

function writeTextField(
  record: FieldRecord | undefined,
  key: string,
  value: string,
  parser = parseFieldValue
): FieldRecord {
  const next = { ...(record || {}) }
  const trimmed = value.trim()
  if (!trimmed) {
    delete next[key]
    return next
  }

  next[key] = parser(key, trimmed)
  return next
}

function readFieldValue(record: FieldRecord | undefined, key: string) {
  const value = record?.[key]
  if (value === undefined || value === null) return ''
  if (Array.isArray(value)) return value.join(',')
  if (typeof value === 'object') {
    const label = (value as FieldRecord).label
    return label === undefined || label === null ? JSON.stringify(value) : String(label)
  }
  return String(value)
}

function readPlainExtraField(record: FieldRecord | undefined, key: string) {
  const value = record?.[key]
  return value === undefined || value === null ? '' : String(value)
}

function createSensorRange(
  config: RDIConfig,
  lowerKey: 'sensor_1_lower' | 'sensor_2_lower',
  upperKey: 'sensor_1_upper' | 'sensor_2_upper'
) {
  return computed<[number, number]>({
    get: () => [config[lowerKey], config[upperKey]] as [number, number],
    set: (value) => {
      config[lowerKey] = value[0]
      config[upperKey] = value[1]
    }
  })
}

function createDerivedState(config: RDIConfig, locale: () => App.I18n.LangType) {
  const text = computed(() => labels[locale()] || labels['en-US'])
  const systemExtraText = computed(() => systemExtraFieldLabels[locale()] || systemExtraFieldLabels['en-US'])

  return {
    sensor1Range: createSensorRange(config, 'sensor_1_lower', 'sensor_1_upper'),
    sensor2Range: createSensorRange(config, 'sensor_2_lower', 'sensor_2_upper'),
    fieldEntries: computed(() => Object.entries(config.field_setting || {})),
    t: (key: LabelKey) => text.value[key],
    systemExtraFieldLabel: (key: SystemExtraFieldKey) => systemExtraText.value[key] || key
  }
}

export function useRdiConfig(deviceId: () => string, onChange: () => void) {
  const appStore = useAppStore()
  const loading = ref(false)
  const applyToDevice = ref(true)
  const lastConfigCommandTracking = ref<RDICommandTracking | null>(null)

  const config = reactive<RDIConfig>(defaultConfig())
  const systemInfo = reactive<RDISystemInfo>(defaultSystemInfo())

  const { sensor1Range, sensor2Range, fieldEntries, t, systemExtraFieldLabel } = createDerivedState(
    config,
    () => appStore.locale
  )
  const configCommandTrackingSummary = computed(() => {
    const tracking = lastConfigCommandTracking.value
    if (!tracking) return ''
    const logState = tracking.log_recorded ? 'log recorded' : 'log not recorded'
    return `set_alarm_config message_id=${tracking.message_id || '--'} status=${tracking.status || '--'} (${logState})`
  })

  function setFieldValue(key: string, value: string) {
    config.field_setting = writeTextField(config.field_setting, key, value)
  }

  function getFieldValue(key: string) {
    return readFieldValue(config.field_setting, key)
  }

  function setSystemExtraField(key: string, value: string) {
    systemInfo.extra_fields = writeTextField(systemInfo.extra_fields, key, value, (_key, trimmed) => trimmed)
  }

  function getSystemExtraField(key: string) {
    return readPlainExtraField(systemInfo.extra_fields, key)
  }

  async function loadConfig() {
    const id = deviceId()
    if (!id) return
    loading.value = true
    try {
      const { error, data } = await rdiDeviceConfig(id)
      if (!error && data) {
        lastConfigCommandTracking.value = null
        applyConfigSnapshot(config, systemInfo, data)
      }
    } finally {
      loading.value = false
    }
  }

  async function saveConfig() {
    const id = deviceId()
    loading.value = true
    try {
      const { error, data } = await updateRdiDeviceConfig(id, buildSavePayload(config, systemInfo, applyToDevice.value))
      if (!error && data) {
        lastConfigCommandTracking.value = data.command_tracking || null
        applyConfigSnapshot(config, systemInfo, data)
        message.success(configCommandTrackingSummary.value || t('saved'))
        onChange()
      }
    } finally {
      loading.value = false
    }
  }

  return {
    loading,
    applyToDevice,
    lastConfigCommandTracking,
    configCommandTrackingSummary,
    config,
    systemInfo,
    sensor1Range,
    sensor2Range,
    fieldEntries,
    t,
    systemExtraFieldLabel,
    systemExtraFieldDefinitions,
    setFieldValue,
    getFieldValue,
    setSystemExtraField,
    getSystemExtraField,
    loadConfig,
    saveConfig
  }
}

/**
 * 文件用途: RDI 设备基础信息展示 composable。
 * 核心逻辑: 归一化设备名称、编号、安装时间与心跳时间等元数据，推导在线状态并输出双列基础信息卡片配置。
 * 关键注意事项: 时间格式化需兼容 ISO 与 "YYYY-MM-DD HH:mm:ss" 两种输入；缺失值统一回退为 "--"。
 * 重构建议: 新增基础信息字段时优先扩展 basicInfoColumns，避免在模板中散落格式化判断。
 */
import { computed } from 'vue'
import dayjs from 'dayjs'
import type { ComputedRef, Ref } from 'vue'
import type { LabelKey } from '../constants/rdi-labels'

export type BasicInfoItem = {
  key: string
  label: string
  value: string
  kind?: 'status' | 'chip'
}

type UseRdiDeviceBasicInfoOptions = {
  deviceId: () => string
  online: () => number | undefined
  onlineUpdatedAt: () => string | undefined
  deviceData: () => Record<string, any> | undefined
  liveOnlineStatus: Ref<number | null>
  deviceOnlineText: ComputedRef<string>
  deviceDescriptionText: ComputedRef<string>
  t: (key: LabelKey) => string
}

export function useRdiDeviceBasicInfo(options: UseRdiDeviceBasicInfoOptions) {
  const { t, liveOnlineStatus, deviceOnlineText, deviceDescriptionText } = options

  function toDisplayText(value: unknown) {
    if (value === null || value === undefined) return '--'
    const text = String(value).trim()
    return text || '--'
  }

  function formatDeviceMetaTime(value: unknown) {
    const text = toDisplayText(value)
    if (text === '--') return text
    const isoLikeMatch = text.match(/^(\d{4}-\d{2}-\d{2})[T\s](\d{2}:\d{2}:\d{2})/)
    if (isoLikeMatch) return `${isoLikeMatch[1]} ${isoLikeMatch[2]}`
    const parsed = dayjs(text)
    return parsed.isValid() ? parsed.format('YYYY-MM-DD HH:mm:ss') : text
  }

  const deviceData = computed(options.deviceData)

  const deviceNameText = computed(() => toDisplayText(deviceData.value?.name || deviceData.value?.device_name))
  const deviceIdentifierText = computed(() => toDisplayText(deviceData.value?.device_number || options.deviceId()))
  const deviceAddedAtText = computed(() =>
    formatDeviceMetaTime(
      deviceData.value?.created_at || deviceData.value?.create_time || deviceData.value?.createdAt
    )
  )
  const deviceLastHeartbeatText = computed(() =>
    formatDeviceMetaTime(
      options.onlineUpdatedAt() ||
        deviceData.value?.last_heartbeat ||
        deviceData.value?.lastHeartbeat ||
        deviceData.value?.update_at ||
        deviceData.value?.updated_at
    )
  )
  const isDeviceOnline = computed(() => {
    const status = options.online() ?? deviceData.value?.is_online ?? liveOnlineStatus.value
    return status === 1 || status === true
  })

  const basicInfoColumns = computed<BasicInfoItem[][]>(() => [
    [
      { key: 'status', label: t('statusLabel'), value: deviceOnlineText.value, kind: 'status' },
      { key: 'deviceId', label: t('deviceId'), value: deviceIdentifierText.value, kind: 'chip' },
      { key: 'description', label: t('description'), value: deviceDescriptionText.value },
      { key: 'addedAt', label: t('addedAt'), value: deviceAddedAtText.value }
    ],
    [
      { key: 'deviceName', label: t('deviceName'), value: deviceNameText.value },
      { key: 'firmware', label: t('firmware'), value: toDisplayText(deviceData.value?.current_version) },
      { key: 'lastHeartbeat', label: t('lastHeartbeat'), value: deviceLastHeartbeatText.value }
    ]
  ])

  return {
    deviceNameText,
    deviceIdentifierText,
    deviceAddedAtText,
    deviceLastHeartbeatText,
    isDeviceOnline,
    basicInfoColumns
  }
}

/**
 * 文件用途: RDI 操作视图历史数据 composable。
 * 核心逻辑: 管理历史查询参数、加载状态、图表选项和后端历史数据响应。
 * 关键注意事项: 时间范围、聚合粒度、导出 URL 和字段名需与 RDI history API 及图表展示保持一致。
 * 重构建议: 将查询参数构造、响应 normalize 和图表配置拆成纯函数，并补空数据/失败/时间范围测试。
 */
import { computed, reactive, ref, watch } from 'vue'
import type { EChartsCoreOption } from 'echarts/core'
import { rdiDeviceHistory } from '@/service/api'
import type { RDIHistoryParams } from '@/service/api/rdi'
import { message } from '@/utils/common/discrete'
import { getBaseServerUrl } from '@/utils/common/tool'
import type { LabelKey } from '../constants/rdi-labels'
import { RDI_DURATION_MAX_SECONDS } from '../constants/rdi-ranges'

type EnergyPoint = {
  x: number
  y: number
}

type HistoryExportRow = {
  ts: number | string
  value: unknown
}

type HistoryExportFormat = 'excel' | 'csv'
type EnergyRange = 'last_1h' | 'last_24h' | 'last_7d' | 'last_30d' | 'custom'
type PresetEnergyRange = Exclude<EnergyRange, 'custom'>
type HistoryRange = [number, number]

type RDIHistorySeriesKey =
  | 'temperature_1'
  | 'temperature_2'
  | 'switch_1'
  | 'switch_2'
  | 'dry_contact_output'
  | 'electricity_consumption'

type HistoryPoint = {
  ts: number
  value: number | null
}

type HistorySeriesStatus = 'loaded' | 'empty' | 'partial' | 'failed'

type HistorySeriesDefinition = {
  key: RDIHistorySeriesKey
  label: string
  color: string
  required?: boolean
  switchSeries?: boolean
}

type EnergyStatsSnapshot = {
  sample_count: number
  latest: number | null
  min: number | null
  max: number | null
  delta: number | null
}

type HistoryChartData = Partial<Record<RDIHistorySeriesKey, HistoryPoint[]>>

type HistorySeriesResult = {
  key: RDIHistorySeriesKey
  status: HistorySeriesStatus
  points: HistoryPoint[]
  loadedCount: number
  expectedCount: number | null
  missingCount: number
  invalidCount: number
  failedPage?: number
  truncated: boolean
  detectedGapCount: number
}

type HistoryChartLoadResult = {
  chartData: HistoryChartData
  seriesResults: HistorySeriesResult[]
}

type NormalizedHistoryPage = {
  points: HistoryPoint[]
  invalidCount: number
}

type TemperatureUnit = 'C' | 'F'
type RDIHistoryTranslate = (key: LabelKey) => string
type FormatHistoryChartValue = (key: RDIHistorySeriesKey, value: number) => number

const HISTORY_QUERY_PAGE = 1
const HISTORY_CHART_PAGE_SIZE = 5000
const HISTORY_CHART_MAX_POINTS_PER_SERIES = 100000
const HISTORY_CHART_MAX_PAGES_PER_SERIES = Math.ceil(
  HISTORY_CHART_MAX_POINTS_PER_SERIES / HISTORY_CHART_PAGE_SIZE
)
const HISTORY_GAP_THRESHOLD_MS = 90 * 1000
const HISTORY_EXPORT_PAGE_SIZE = 10000
const DEFAULT_ENERGY_RANGE: PresetEnergyRange = 'last_1h'

const energyRangeDurations: Record<PresetEnergyRange, number> = {
  last_1h: 60 * 60 * 1000,
  last_24h: 24 * 60 * 60 * 1000,
  last_7d: 7 * 24 * 60 * 60 * 1000,
  last_30d: 30 * 24 * 60 * 60 * 1000
}

const historySeriesDefinitions: HistorySeriesDefinition[] = [
  { key: 'temperature_1', label: 'T1', color: '#f43f5e' },
  { key: 'temperature_2', label: 'T2', color: '#2563eb' },
  { key: 'switch_1', label: 'SW1', color: '#7c3aed', switchSeries: true },
  { key: 'switch_2', label: 'SW2', color: '#f97316', switchSeries: true },
  { key: 'dry_contact_output', label: 'DO', color: '#16a34a', switchSeries: true },
  { key: 'electricity_consumption', label: 'kWh', color: '#0891b2', required: true }
]

const DEFAULT_HISTORY_CHART_SERIES_KEYS: RDIHistorySeriesKey[] = [
  'temperature_1',
  'temperature_2',
  'switch_1',
  'switch_2',
  'dry_contact_output',
  'electricity_consumption'
]

function createEmptyEnergyStats(): EnergyStatsSnapshot {
  return {
    sample_count: 0,
    latest: null,
    min: null,
    max: null,
    delta: null
  }
}

function isTemperatureHistoryKey(key: string) {
  return key === 'temperature_1' || key === 'temperature_2'
}

function normalizeHistoryTimestamp(value: unknown): number | null {
  if (value instanceof Date) return value.getTime()
  if (typeof value === 'number' && Number.isFinite(value)) return value < 1_000_000_000_000 ? value * 1000 : value
  if (typeof value === 'string') {
    const numeric = Number(value)
    if (Number.isFinite(numeric)) return numeric < 1_000_000_000_000 ? numeric * 1000 : numeric
    const parsed = Date.parse(value)
    if (Number.isFinite(parsed)) return parsed
  }
  return null
}

function normalizeHistoryValue(value: unknown): number | null {
  if (typeof value === 'boolean') return value ? 1 : 0
  if (typeof value === 'number' && Number.isFinite(value)) return value
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase()
    if (normalized === 'true' || normalized === 'high' || normalized === 'open' || normalized === 'on') return 1
    if (
      normalized === 'false' ||
      normalized === 'low' ||
      normalized === 'close' ||
      normalized === 'closed' ||
      normalized === 'off'
    ) {
      return 0
    }
    const numeric = Number(value)
    if (Number.isFinite(numeric)) return numeric
  }
  return null
}

function normalizeHistoryList(payload: any): any[] {
  return Array.isArray(payload) ? payload : Array.isArray(payload?.list) ? payload.list : []
}

function normalizeHistoryTotal(payload: any): number | null {
  const rawTotal = payload?.total
  if (rawTotal === null || rawTotal === undefined || rawTotal === '') return null
  const total = Number(rawTotal)
  return Number.isFinite(total) && total >= 0 ? Math.floor(total) : null
}

function readHistoryPointTimestamp(item: any) {
  return item?.ts ?? item?.x ?? item?.time ?? item?.UpdateAt ?? item?.created_at
}

function readHistoryPointValue(item: any, key: RDIHistorySeriesKey) {
  return item?.value ?? item?.y ?? item?.number_v ?? item?.bool_v ?? item?.string_v ?? item?.[key]
}

function normalizeHistoryPoints(payload: any, key: RDIHistorySeriesKey): NormalizedHistoryPage {
  const points: HistoryPoint[] = []
  let invalidCount = 0

  for (const item of normalizeHistoryList(payload)) {
    const ts = normalizeHistoryTimestamp(readHistoryPointTimestamp(item))
    if (ts === null) {
      invalidCount += 1
      continue
    }
    points.push({ ts, value: normalizeHistoryValue(readHistoryPointValue(item, key)) })
  }

  return {
    points: points.sort((a, b) => a.ts - b.ts),
    invalidCount
  }
}

function historyPointIdentity(point: HistoryPoint) {
  return `${point.ts}\u0000${point.value}`
}

function appendUniqueHistoryPoints(
  target: HistoryPoint[],
  seenPointIdentities: Set<string>,
  nextPoints: HistoryPoint[],
  maxPoints: number
) {
  let addedCount = 0
  for (const point of nextPoints) {
    if (target.length >= maxPoints) break
    const identity = historyPointIdentity(point)
    if (seenPointIdentities.has(identity)) continue
    seenPointIdentities.add(identity)
    target.push(point)
    addedCount += 1
  }
  return addedCount
}

function insertHistoryGapMarkers(points: HistoryPoint[]) {
  const sortedPoints = [...points].sort((a, b) => a.ts - b.ts)
  if (!sortedPoints.length) return { points: sortedPoints, detectedGapCount: 0 }

  const markedPoints: HistoryPoint[] = [sortedPoints[0]]
  let detectedGapCount = sortedPoints[0].value === null ? 1 : 0

  for (let index = 1; index < sortedPoints.length; index += 1) {
    const previousPoint = sortedPoints[index - 1]
    const currentPoint = sortedPoints[index]
    const gapDuration = currentPoint.ts - previousPoint.ts

    if (
      gapDuration > HISTORY_GAP_THRESHOLD_MS &&
      previousPoint.value !== null &&
      currentPoint.value !== null
    ) {
      markedPoints.push({
        ts: previousPoint.ts + Math.floor(gapDuration / 2),
        value: null
      })
      detectedGapCount += 1
    }

    markedPoints.push(currentPoint)
    if (currentPoint.value === null) detectedGapCount += 1
  }

  return { points: markedPoints, detectedGapCount }
}

function finalizeHistorySeriesResult(
  key: RDIHistorySeriesKey,
  points: HistoryPoint[],
  expectedCount: number | null,
  invalidCount: number,
  failedPage: number | undefined,
  truncated: boolean
): HistorySeriesResult {
  const loadedCount = points.length
  const missingCount = expectedCount === null ? 0 : Math.max(0, expectedCount - loadedCount)
  const chartEvidence = insertHistoryGapMarkers(points)
  const failed = failedPage !== undefined && loadedCount === 0
  const partial =
    !failed &&
    (failedPage !== undefined ||
      truncated ||
      invalidCount > 0 ||
      missingCount > 0)

  return {
    key,
    status: failed ? 'failed' : partial ? 'partial' : loadedCount === 0 ? 'empty' : 'loaded',
    points: chartEvidence.points,
    loadedCount,
    expectedCount,
    missingCount,
    invalidCount,
    failedPage,
    truncated,
    detectedGapCount: chartEvidence.detectedGapCount
  }
}

function normalizeHistoryExportRows(payload: any): HistoryExportRow[] {
  return normalizeHistoryList(payload)
    .map((item: any) => ({
      ts: item?.ts ?? item?.x ?? item?.time ?? '',
      value: item?.value ?? item?.y ?? item?.number_v ?? item?.string_v ?? item?.bool_v ?? ''
    }))
    .filter((item: HistoryExportRow) => item.ts !== '')
}

function csvEscape(value: unknown) {
  const text = value === undefined || value === null ? '' : String(value)
  return `"${text.replace(/"/g, '""')}"`
}

function downloadCsv(filename: string, rows: unknown[][]) {
  const csvContent = rows.map((row) => row.map(csvEscape).join(',')).join('\n')
  const blob = new Blob(['\uFEFF', csvContent], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  link.click()
  URL.revokeObjectURL(url)
}

function resolveHistoryRange(range: string, customRange: HistoryRange | null, now = Date.now()): HistoryRange | null {
  if (range === 'custom') return customRange
  const duration = energyRangeDurations[range as PresetEnergyRange] ?? energyRangeDurations[DEFAULT_ENERGY_RANGE]
  return [now - duration, now]
}

function buildHistoryQueryParams(
  key: RDIHistorySeriesKey,
  range: HistoryRange,
  pageSize: number,
  page = HISTORY_QUERY_PAGE,
  options: Pick<RDIHistoryParams, 'export_excel' | 'export_format'> = {}
): RDIHistoryParams {
  return {
    key,
    start_time: range[0],
    end_time: range[1],
    page,
    page_size: pageSize,
    ...options
  }
}

function buildHistoryChartQueryParams(key: RDIHistorySeriesKey, range: HistoryRange, page = HISTORY_QUERY_PAGE) {
  return buildHistoryQueryParams(key, range, HISTORY_CHART_PAGE_SIZE, page)
}

function buildHistoryExportQueryParams(key: RDIHistorySeriesKey, range: HistoryRange, format: HistoryExportFormat) {
  return buildHistoryQueryParams(key, range, HISTORY_EXPORT_PAGE_SIZE, HISTORY_QUERY_PAGE, {
    export_excel: format === 'excel',
    export_format: format
  })
}

async function fetchHistorySeries(
  id: string,
  definition: HistorySeriesDefinition,
  range: HistoryRange
): Promise<HistorySeriesResult> {
  const points: HistoryPoint[] = []
  const seenPointIdentities = new Set<string>()
  let expectedPointCount: number | null = null
  let invalidCount = 0
  let failedPage: number | undefined
  let truncated = false

  for (let page = HISTORY_QUERY_PAGE; page <= HISTORY_CHART_MAX_PAGES_PER_SERIES; page += 1) {
    try {
      const { error, data } = await rdiDeviceHistory(id, buildHistoryChartQueryParams(definition.key, range, page))
      if (error) {
        failedPage = page
        break
      }

      const rawPageItems = normalizeHistoryList(data)
      const responseTotal = normalizeHistoryTotal(data)
      if (responseTotal !== null) {
        expectedPointCount = Math.max(expectedPointCount ?? 0, responseTotal)
      }

      const normalizedPage = normalizeHistoryPoints(rawPageItems, definition.key)
      invalidCount += normalizedPage.invalidCount

      const addedCount = appendUniqueHistoryPoints(
        points,
        seenPointIdentities,
        normalizedPage.points,
        HISTORY_CHART_MAX_POINTS_PER_SERIES
      )

      if (points.length >= HISTORY_CHART_MAX_POINTS_PER_SERIES) {
        truncated = expectedPointCount === null || expectedPointCount > points.length
        break
      }
      if (expectedPointCount !== null && points.length >= expectedPointCount) break
      if (rawPageItems.length === 0) break
      if (addedCount === 0) {
        // A repeated full page without a total cannot prove that the series ended.
        if (expectedPointCount === null && rawPageItems.length >= HISTORY_CHART_PAGE_SIZE) truncated = true
        break
      }
      if (expectedPointCount === null && rawPageItems.length < HISTORY_CHART_PAGE_SIZE) break
      if (page === HISTORY_CHART_MAX_PAGES_PER_SERIES) {
        // A full final page means the bounded client stopped before the server proved exhaustion.
        truncated = expectedPointCount === null || points.length < expectedPointCount
      }
    } catch {
      failedPage = page
      break
    }
  }

  return finalizeHistorySeriesResult(
    definition.key,
    points,
    expectedPointCount,
    invalidCount,
    failedPage,
    truncated
  )
}

function normalizeHistoryChartSeriesKeys(keys: RDIHistorySeriesKey[]): RDIHistorySeriesKey[] {
  const allowedKeys = new Set(historySeriesDefinitions.map((item) => item.key))
  // 空选择恢复初始默认；只要用户已有选择，就不能再把其余默认曲线隐式加回。
  if (keys.length === 0) return [...DEFAULT_HISTORY_CHART_SERIES_KEYS]

  const selectedKeys = keys.filter((key) => allowedKeys.has(key))
  return Array.from(new Set(selectedKeys))
}

async function fetchHistoryChartData(
  id: string,
  range: HistoryRange,
  seriesKeys: RDIHistorySeriesKey[]
): Promise<HistoryChartLoadResult> {
  const selectedKeySet = new Set(seriesKeys)
  const selectedDefinitions = historySeriesDefinitions.filter((item) => selectedKeySet.has(item.key))
  const seriesResults = await Promise.all(selectedDefinitions.map((item) => fetchHistorySeries(id, item, range)))
  const chartData = seriesResults.reduce<HistoryChartData>((nextChartData, item) => {
    nextChartData[item.key] = item.points
    return nextChartData
  }, {})
  return { chartData, seriesResults }
}

function calculateEnergyStats(points: EnergyPoint[]): EnergyStatsSnapshot {
  const sorted = [...points].sort((a, b) => a.x - b.x)
  if (!sorted.length) return createEmptyEnergyStats()

  const values = sorted.map((item) => item.y)
  return {
    sample_count: sorted.length,
    latest: sorted[sorted.length - 1].y,
    min: Math.min(...values),
    max: Math.max(...values),
    delta: sorted.length > 1 ? Math.max(0, sorted[sorted.length - 1].y - sorted[0].y) : 0
  }
}

function toEnergyPoints(points: HistoryPoint[] = []): EnergyPoint[] {
  return points.flatMap((item) =>
    item.value === null
      ? []
      : [
          {
            x: item.ts,
            y: item.value
          }
        ]
  )
}

function formatHistoryChartValueForUnit(key: RDIHistorySeriesKey, value: number, unit: TemperatureUnit) {
  if (isTemperatureHistoryKey(key) && unit === 'F') {
    return (value * 9) / 5 + 32
  }
  return value
}

function historyExportValueLabelForUnit(key: string, unit: TemperatureUnit) {
  return isTemperatureHistoryKey(key) ? `value (${unit})` : 'value'
}

function formatHistoryExportValueForUnit(key: string, value: unknown, unit: TemperatureUnit) {
  if (isTemperatureHistoryKey(key) && unit === 'F') {
    const numeric = normalizeHistoryValue(value)
    return numeric === null
      ? value
      : formatHistoryChartValueForUnit(key as RDIHistorySeriesKey, numeric, unit).toFixed(2)
  }
  return value
}

function formatHistoryExportTimestamp(ts: number | string) {
  return typeof ts === 'number' ? new Date(ts).toISOString() : ts
}

function buildHistoryExportCsvRows(
  key: RDIHistorySeriesKey,
  rows: HistoryExportRow[],
  unit: TemperatureUnit
): unknown[][] {
  return [
    ['time', 'key', historyExportValueLabelForUnit(key, unit)],
    ...rows.map((row) => [
      formatHistoryExportTimestamp(row.ts),
      key,
      formatHistoryExportValueForUnit(key, row.value, unit)
    ])
  ]
}

function getExportedHistoryFilePath(payload: any) {
  return payload?.filePath || payload?.file_path
}

function buildExportFileUrl(filePath: unknown) {
  const baseUrlWithoutApi = getBaseServerUrl().replace('/api/v1', '/')
  return `${baseUrlWithoutApi}${filePath}`
}

function buildHistoryChartOptions(
  t: RDIHistoryTranslate,
  chartData: HistoryChartData,
  formatValue: FormatHistoryChartValue
): EChartsCoreOption {
  const activeDefinitions = historySeriesDefinitions.filter((item) =>
    Object.prototype.hasOwnProperty.call(chartData, item.key)
  )
  return {
    color: activeDefinitions.map((item) => item.color),
    title: {
      text: t('historyChart'),
      left: 8,
      top: 0,
      textStyle: {
        fontSize: 13,
        fontWeight: 600
      }
    },
    tooltip: {
      trigger: 'axis'
    },
    legend: {
      top: 28,
      type: 'scroll'
    },
    grid: {
      top: 72,
      left: 48,
      right: 48,
      bottom: 56
    },
    xAxis: {
      type: 'time'
    },
    yAxis: [
      {
        type: 'value',
        name: t('valueAxis'),
        scale: true
      },
      {
        type: 'value',
        name: t('switchAxis'),
        min: -0.1,
        max: 1.1,
        interval: 1,
        axisLabel: {
          formatter: (value: number | string) => {
            const numeric = Number(value)
            if (numeric === 1) return t('high')
            if (numeric === 0) return t('low')
            return ''
          }
        }
      }
    ],
    dataZoom: [
      { type: 'inside', throttle: 80 },
      { type: 'slider', height: 22, bottom: 18 }
    ],
    series: activeDefinitions.map((item) => ({
      name: item.label,
      type: 'line',
      animation: false,
      smooth: !item.switchSeries,
      step: item.switchSeries ? 'middle' : false,
      showSymbol: false,
      sampling: item.switchSeries ? undefined : 'lttb',
      connectNulls: false,
      emphasis: {
        disabled: true
      },
      yAxisIndex: item.switchSeries ? 1 : 0,
      lineStyle: {
        width: 2,
        color: item.color
      },
      itemStyle: {
        color: item.color
      },
      data: (chartData[item.key] || []).map((point) => [
        point.ts,
        point.value === null ? null : formatValue(item.key, point.value)
      ])
    }))
  }
}

export function useRdiHistory(deviceId: () => string, temperatureUnit: () => 'C' | 'F', t: (key: LabelKey) => string) {
  const energyLoading = ref(false)
  const historyExportLoading = ref(false)
  const energyRange = ref<string>(DEFAULT_ENERGY_RANGE)
  const energyCustomRange = ref<HistoryRange | null>(null)
  const historyExportKey = ref<RDIHistorySeriesKey>('electricity_consumption')
  const historyChartSeriesKeys = ref<RDIHistorySeriesKey[]>([...DEFAULT_HISTORY_CHART_SERIES_KEYS])
  const historyExportFormat = ref<HistoryExportFormat>('excel')

  const energyStats = reactive(createEmptyEnergyStats())

  const historyChartData = ref<HistoryChartData>({})
  const historySeriesResults = ref<HistorySeriesResult[]>([])
  let historyContextRevision = 0
  let historyLoadSequence = 0
  let historyExportSequence = 0

  function formatHistoryChartValue(key: RDIHistorySeriesKey, value: number) {
    return formatHistoryChartValueForUnit(key, value, temperatureUnit())
  }

  function formatEnergyValue(value: number | null) {
    return value === null ? '--' : `${value.toFixed(2)} kWh`
  }

  function formatDurationLabel(value: number | null | undefined) {
    const seconds = Math.max(0, Math.min(RDI_DURATION_MAX_SECONDS, Number(value) || 0))
    if (seconds === 0) return '0H'
    if (seconds % 3600 === 0) return `${seconds / 3600}H`
    if (seconds >= 3600) {
      const hours = Math.floor(seconds / 3600)
      const minutes = Math.round((seconds % 3600) / 60)
      return minutes ? `${hours}H ${minutes}M` : `${hours}H`
    }
    if (seconds % 60 === 0) return `${seconds / 60}M`
    return `${seconds}S`
  }

  function updateEnergyStats(points: EnergyPoint[]) {
    Object.assign(energyStats, calculateEnergyStats(points))
  }

  function resolveEnergyHistoryRange() {
    return resolveHistoryRange(energyRange.value, energyCustomRange.value)
  }

  const energyRangeOptions = computed(() => [
    { label: t('last1Hour'), value: 'last_1h' },
    { label: t('last1Day'), value: 'last_24h' },
    { label: t('last1Week'), value: 'last_7d' },
    { label: t('last30Days'), value: 'last_30d' },
    { label: t('customRange'), value: 'custom' }
  ])

  const historyExportKeyOptions = computed(() => [
    ...historySeriesDefinitions.map((item) => ({ label: item.label, value: item.key }))
  ])

  const historyChartSeriesOptions = computed(() =>
    historySeriesDefinitions.map((item) => ({
      label: item.required ? `${item.label} (${t('energy')})` : item.label,
      value: item.key,
      disabled: item.required
    }))
  )

  const historyExportFormatOptions = computed(() => [
    { label: t('excelFormat'), value: 'excel' },
    { label: t('csvFormat'), value: 'csv' }
  ])

  const historyChartOptions = computed<EChartsCoreOption>(() =>
    buildHistoryChartOptions(t, historyChartData.value, formatHistoryChartValue)
  )

  function labelsForHistoryResults(predicate: (result: HistorySeriesResult) => boolean) {
    const labelsByKey = new Map(historySeriesDefinitions.map((definition) => [definition.key, definition.label]))
    return historySeriesResults.value
      .filter(predicate)
      .map((result) => labelsByKey.get(result.key) || result.key)
  }

  const failedHistorySeriesLabels = computed(() =>
    labelsForHistoryResults((result) => result.status === 'failed')
  )
  const partialHistorySeriesLabels = computed(() =>
    labelsForHistoryResults((result) => result.status === 'partial')
  )
  const gappedHistorySeriesLabels = computed(() =>
    labelsForHistoryResults((result) => result.detectedGapCount > 0)
  )
  const hasHistoryFailures = computed(() =>
    historySeriesResults.value.some((result) => result.status === 'failed' || result.status === 'partial')
  )
  const hasSuccessfulHistoryData = computed(() =>
    historySeriesResults.value.some((result) => result.status !== 'failed')
  )
  const hasHistoryChartData = computed(() =>
    Object.values(historyChartData.value).some((points) => points?.some((point) => point.value !== null))
  )
  const energyStatisticsAvailable = computed(() => {
    const result = historySeriesResults.value.find((item) => item.key === 'electricity_consumption')
    if (!result || result.status === 'failed') return false
    return result.status === 'empty' || result.points.some((point) => point.value !== null)
  })

  async function loadEnergyStatistics() {
    const id = deviceId()
    if (!id) return
    const range = resolveEnergyHistoryRange()
    if (!range) {
      message.error(t('customRange'))
      return
    }
    const contextRevision = historyContextRevision
    const requestSequence = ++historyLoadSequence
    energyLoading.value = true
    try {
      const selectedSeriesKeys = normalizeHistoryChartSeriesKeys(historyChartSeriesKeys.value)
      historyChartSeriesKeys.value = selectedSeriesKeys
      const nextHistory = await fetchHistoryChartData(id, range, selectedSeriesKeys)
      if (
        contextRevision !== historyContextRevision ||
        requestSequence !== historyLoadSequence ||
        id !== deviceId()
      ) {
        return
      }
      historySeriesResults.value = nextHistory.seriesResults
      historyChartData.value = nextHistory.chartData
      updateEnergyStats(toEnergyPoints(nextHistory.chartData.electricity_consumption))
    } finally {
      if (contextRevision === historyContextRevision && requestSequence === historyLoadSequence) {
        energyLoading.value = false
      }
    }
  }

  async function exportHistoryData() {
    const id = deviceId()
    if (!id) return
    const range = resolveEnergyHistoryRange()
    if (!range) {
      message.error(t('customRange'))
      return
    }
    const contextRevision = historyContextRevision
    const requestSequence = ++historyExportSequence
    const exportKey = historyExportKey.value
    const exportFormat = historyExportFormat.value
    const exportTemperatureUnit = temperatureUnit()
    historyExportLoading.value = true
    try {
      const { error, data } = await rdiDeviceHistory(
        id,
        buildHistoryExportQueryParams(exportKey, range, exportFormat)
      )
      if (
        contextRevision !== historyContextRevision ||
        requestSequence !== historyExportSequence ||
        id !== deviceId()
      ) {
        return
      }
      if (error) return
      const exportedFilePath = getExportedHistoryFilePath(data)
      if (exportedFilePath) {
        window.open(buildExportFileUrl(exportedFilePath))
        return
      }
      const rows = normalizeHistoryExportRows(data)
      if (!rows.length) {
        message.error(t('empty'))
        return
      }
      downloadCsv(
        `rdi_${id}_${exportKey}.csv`,
        buildHistoryExportCsvRows(exportKey, rows, exportTemperatureUnit)
      )
    } finally {
      if (contextRevision === historyContextRevision && requestSequence === historyExportSequence) {
        historyExportLoading.value = false
      }
    }
  }

  watch(
    deviceId,
    (nextId, previousId) => {
      if (nextId === previousId) return
      historyContextRevision += 1
      historyChartData.value = {}
      historySeriesResults.value = []
      updateEnergyStats([])
      energyLoading.value = false
      historyExportLoading.value = false
    },
    { flush: 'sync' }
  )

  watch(energyRange, (value) => {
    if (value !== 'custom') energyCustomRange.value = null
  })

  return {
    RDI_DURATION_MAX_SECONDS,
    energyLoading,
    historyExportLoading,
    energyRange,
    energyCustomRange,
    historyExportKey,
    historyChartSeriesKeys,
    historyExportFormat,
    energyStats,
    historyChartData,
    historySeriesResults,
    historyChartOptions,
    failedHistorySeriesLabels,
    partialHistorySeriesLabels,
    gappedHistorySeriesLabels,
    hasHistoryFailures,
    hasSuccessfulHistoryData,
    hasHistoryChartData,
    energyStatisticsAvailable,
    energyRangeOptions,
    historyChartSeriesOptions,
    historyExportKeyOptions,
    historyExportFormatOptions,
    formatDurationLabel,
    formatEnergyValue,
    loadEnergyStatistics,
    exportHistoryData
  }
}

/**
 * 文件用途: RDI 详情视图按需加载与设备切换编排 composable。
 * 核心逻辑: 能耗统计与 OTA 固件包首次按需加载；挂载与设备切换时统一触发"配置 -> 实时状态 -> 能耗"刷新链路。
 * 关键注意事项: 设备切换后需先复位分享状态与在线缓存，再重新启动加载与轮询链路，避免旧设备状态残留。
 * 重构建议: 新增懒加载数据块时复用 hasXxxLoaded 标记模式，保持首屏不请求重数据。
 */
import { onMounted, ref, watch } from 'vue'
import type { Ref } from 'vue'

type UseRdiOnDemandLoadsOptions = {
  deviceId: () => string
  loadConfig: () => Promise<unknown>
  loadRealtimeState: () => Promise<unknown>
  loadEnergyStatistics: () => Promise<unknown>
  loadOtaPackages: () => Promise<unknown>
  otaPackageLoading: Ref<boolean>
  resetShareState: () => unknown
  liveOnlineStatus: Ref<number | null>
  startTelemetryRefresh: () => void
}

export function useRdiOnDemandLoads(options: UseRdiOnDemandLoadsOptions) {
  const hasLoadedEnergyStatistics = ref(false)
  const hasRequestedOtaPackages = ref(false)

  async function loadEnergyStatisticsOnDemand() {
    hasLoadedEnergyStatistics.value = true
    await options.loadEnergyStatistics()
  }

  async function ensureOtaPackagesLoaded() {
    if (hasRequestedOtaPackages.value || options.otaPackageLoading.value) return

    hasRequestedOtaPackages.value = true
    await options.loadOtaPackages()
  }

  async function reloadOtaPackages() {
    hasRequestedOtaPackages.value = true
    await options.loadOtaPackages()
  }

  async function loadConfigAndRefresh() {
    await options.loadConfig()
    await options.loadRealtimeState()
    hasLoadedEnergyStatistics.value = true
    await options.loadEnergyStatistics()
  }

  onMounted(() => {
    loadConfigAndRefresh()
    options.startTelemetryRefresh()
  })

  watch(
    options.deviceId,
    () => {
      options.resetShareState()
      options.liveOnlineStatus.value = null
      hasLoadedEnergyStatistics.value = false
      loadConfigAndRefresh()
      options.startTelemetryRefresh()
    }
  )

  return {
    hasLoadedEnergyStatistics,
    loadEnergyStatisticsOnDemand,
    ensureOtaPackagesLoaded,
    reloadOtaPackages,
    loadConfigAndRefresh
  }
}

/**
 * 文件用途: RDI 分享链接 composable。
 * 核心逻辑: 管理分享过期时间、调用分享 token API，并生成可复制的分享链接。
 * 关键注意事项: deviceId 为空、token 过期时间和 window origin 会影响外部分享入口。
 * 重构建议: 抽出分享链接构造 helper，并补 token 缺失、接口失败和不同过期时间测试。
 */
import { computed, ref } from 'vue'
import { createRdiShareToken } from '@/service/api'
import { message } from '@/utils/common/discrete'
import { writeClipboardText } from '@/utils/clipboard'
import type { LabelKey } from '../constants/rdi-labels'

export function useRdiShare(
  deviceId: () => string,
  t: (key: LabelKey) => string
) {
  const shareLoading = ref(false)
  const shareExpiresIn = ref(7 * 24 * 60 * 60)
  const shareLink = ref('')

  const shareExpiryOptions = computed(() => [
    { label: t('oneDay'), value: 24 * 60 * 60 },
    { label: t('sevenDays'), value: 7 * 24 * 60 * 60 },
    { label: t('thirtyDays'), value: 30 * 24 * 60 * 60 }
  ])

  const shareExpiresAt = computed(() => {
    if (!shareLink.value) return ''
    return new Date((Math.floor(Date.now() / 1000) + shareExpiresIn.value) * 1000).toLocaleString()
  })

  function resetShareState() {
    shareLink.value = ''
    shareExpiresIn.value = shareExpiryOptions.value[1]?.value ?? 7 * 24 * 60 * 60
    return shareExpiresAt.value
  }

  async function createShareLink() {
    shareLoading.value = true
    try {
      const { error, data } = await createRdiShareToken(deviceId(), { expires_in: shareExpiresIn.value })
      if (!error && data) {
        const path = data.share_path || (data.token ? `/device/share?share_token=${encodeURIComponent(data.token)}` : '')
        if (!path) return
        shareLink.value = `${window.location.origin}${path.startsWith('/') ? path : `/${path}`}`
        await copyShareLink()
      }
    } finally {
      shareLoading.value = false
    }
  }

  async function copyShareLink() {
    if (!shareLink.value) return false
    const copied = await writeClipboardText(shareLink.value)
    if (copied) {
      message.success(t('sent'))
    }
    return copied
  }

  const shareActions = {
    create: createShareLink,
    copy: copyShareLink
  }

  return {
    shareLoading,
    shareExpiresIn,
    shareLink,
    shareExpiryOptions,
    shareExpiresAt,
    shareActions,
    resetShareState,
    createShareLink,
    copyShareLink
  }
}

/**
 * 文件用途: RDI 操作视图实时遥测 composable。
 * 核心逻辑: 按设备 ID 轮询当前遥测和在线状态，计算温度单位、字段展示和刷新生命周期。
 * 关键注意事项: 轮询间隔、组件卸载清理、温度单位偏好和在线态字段会影响详情页实时性。
 * 重构建议: 抽出温度转换和遥测 normalize helper，并补轮询清理、离线状态和接口失败测试。
 */
import { computed, onUnmounted, ref, watch } from 'vue'
import { telemetryDataCurrentKeys, getDeviceOnlineStatus } from '@/service/api'
import type { LabelKey } from '../constants/rdi-labels'
import { useRdiTemperatureUnit } from './useRdiTemperatureUnit'

type TemperatureUnit = 'C' | 'F'

const RDI_TELEMETRY_REFRESH_MS = 10_000
const RDI_TELEMETRY_KEYS = [
  'temperature_1',
  'temperature_2',
  'switch_1',
  'switch_2',
  'dry_contact_output',
  'electricity_consumption',
  'led_status'
]

type TranslateRdiLabel = (key: LabelKey) => string

function isBlankValue(value: unknown) {
  return value === undefined || value === null || value === ''
}

function toFallbackText(value: unknown) {
  return isBlankValue(value) ? '--' : String(value)
}

function normalizeTelemetryPayload(payload: unknown) {
  const result: Record<string, unknown> = {}
  if (Array.isArray(payload)) {
    payload.forEach((item) => {
      if (item && typeof item === 'object') {
        const row = item as Record<string, unknown>
        const key = String(row.key || '')
        if (key) result[key] = row.value
      }
    })
    return result
  }
  if (payload && typeof payload === 'object') return payload as Record<string, unknown>
  return result
}

function formatTelemetryValue(value: unknown) {
  const numeric = Number(value)
  if (Number.isFinite(numeric)) return numeric.toFixed(2)
  return toFallbackText(value)
}

function formatTemperatureTelemetryValue(value: unknown, temperatureUnit: TemperatureUnit) {
  const numeric = Number(value)
  if (!Number.isFinite(numeric)) return toFallbackText(value)
  const converted = temperatureUnit === 'F' ? (numeric * 9) / 5 + 32 : numeric
  return converted.toFixed(2)
}

function formatSwitchTelemetryValue(value: unknown, t: TranslateRdiLabel) {
  if (value === true || value === 1 || value === '1' || value === 'true') return t('high')
  if (value === false || value === 0 || value === '0' || value === 'false') return t('low')
  return toFallbackText(value)
}

function formatLedTelemetryValue(value: unknown, t: TranslateRdiLabel) {
  const raw = String(value ?? '')
    .trim()
    .toLowerCase()
  if (!raw) return '--'
  switch (raw) {
    case 'off':
      return t('ledOff')
    case 'solid':
      return t('ledSolid')
    case 'slow_blink':
    case 'slowblink':
      return t('ledSlowBlink')
    case 'fast_blink':
    case 'fastblink':
      return t('ledFastBlink')
    case 'error':
      return t('ledError')
    default:
      return String(value)
  }
}

function toAxisValue(value: unknown): string | number | null | undefined {
  if (value === undefined || value === null) return value
  if (typeof value === 'string' || typeof value === 'number') return value
  return String(value)
}

function deriveOnlineStatus(
  liveOnlineStatus: number | null,
  onlineStatus: number | undefined,
  deviceData: Record<string, any> | undefined
) {
  const status = liveOnlineStatus ?? onlineStatus ?? deviceData?.is_online
  return status === 1 || status === true
}

function deriveDeviceDescription(deviceData: Record<string, any> | undefined) {
  const description = deviceData?.description ?? deviceData?.device_description ?? deviceData?.Description
  if (description === null || description === undefined) return '--'
  const descText = String(description).trim()
  return descText || '--'
}

function normalizeOnlineStatus(data: unknown) {
  if (!data || typeof data !== 'object') return null
  const row = data as Record<string, unknown>
  const rawStatus = row.device_status ?? row.is_online
  const normalizedStatus = Number(rawStatus)
  return Number.isFinite(normalizedStatus) ? normalizedStatus : null
}

function hasExternalOnlineStatus(onlineStatus: number | undefined, deviceData: Record<string, any> | undefined) {
  return onlineStatus !== undefined || deviceData?.is_online !== undefined
}

async function fetchTelemetrySnapshot(deviceId: string) {
  const { error, data } = await telemetryDataCurrentKeys({ device_id: deviceId, keys: RDI_TELEMETRY_KEYS })
  return error ? null : normalizeTelemetryPayload(data)
}

async function fetchOnlineStatusSnapshot(deviceId: string) {
  const { error, data } = await getDeviceOnlineStatus(deviceId)
  if (error || !data) return null
  return normalizeOnlineStatus(data)
}

function clearTelemetryRefresh(timer: { value: number | null }) {
  if (timer.value === null) return
  if (typeof window !== 'undefined') {
    window.clearTimeout(timer.value)
  }
  timer.value = null
}

function scheduleTelemetryRefresh(
  timer: { value: number | null },
  refresh: () => Promise<void>,
  isActive: () => boolean
) {
  if (typeof window === 'undefined' || timer.value !== null || !isActive()) return
  timer.value = window.setTimeout(() => {
    timer.value = null
    if (!isActive()) return
    void refresh().finally(() => {
      if (isActive()) {
        scheduleTelemetryRefresh(timer, refresh, isActive)
      }
    })
  }, RDI_TELEMETRY_REFRESH_MS)
}

export function useRdiTelemetry(
  deviceId: () => string,
  online: () => number | undefined,
  deviceData: () => Record<string, any> | undefined,
  t: (key: LabelKey) => string
) {
  const telemetry = ref<Record<string, unknown>>({})
  const liveOnlineStatus = ref<number | null>(null)
  const temperatureUnit = useRdiTemperatureUnit()
  const telemetryRefreshTimer = ref<number | null>(null)
  const telemetryRefreshActive = ref(false)
  let telemetryRequestSequence = 0
  let onlineStatusRequestSequence = 0

  function formatValue(value: unknown) {
    return formatTelemetryValue(value)
  }

  function formatTemperatureValue(value: unknown) {
    return formatTemperatureTelemetryValue(value, temperatureUnit.value)
  }

  function formatSwitch(value: unknown) {
    return formatSwitchTelemetryValue(value, t)
  }

  function formatLedStatus(value: unknown) {
    return formatLedTelemetryValue(value, t)
  }

  const telemetryRows = computed(() => [
    { label: 'T1', value: formatTemperatureValue(telemetry.value.temperature_1), unit: temperatureUnit.value },
    { label: 'T2', value: formatTemperatureValue(telemetry.value.temperature_2), unit: temperatureUnit.value },
    { label: t('switch1'), value: formatSwitch(telemetry.value.switch_1), unit: '' },
    { label: t('switch2'), value: formatSwitch(telemetry.value.switch_2), unit: '' },
    { label: t('dryContact'), value: formatSwitch(telemetry.value.dry_contact_output), unit: '' },
    { label: 'kWh', value: formatValue(telemetry.value.electricity_consumption), unit: 'kWh' },
    { label: 'LED1', value: formatLedStatus(telemetry.value.led_status), unit: '' }
  ])

  const deviceOnlineText = computed(() => {
    return deriveOnlineStatus(liveOnlineStatus.value, online(), deviceData()) ? t('online') : t('offline')
  })

  const deviceDescriptionText = computed(() => {
    return deriveDeviceDescription(deviceData())
  })

  async function loadTelemetry() {
    const id = deviceId()
    if (!id) return
    const sequence = ++telemetryRequestSequence
    const snapshot = await fetchTelemetrySnapshot(id)
    if (sequence !== telemetryRequestSequence || id !== deviceId()) return
    if (snapshot) telemetry.value = snapshot
  }

  async function loadOnlineStatus() {
    const id = deviceId()
    if (!id) return
    const sequence = ++onlineStatusRequestSequence
    if (hasExternalOnlineStatus(online(), deviceData())) {
      liveOnlineStatus.value = null
      return
    }

    const status = await fetchOnlineStatusSnapshot(id)
    if (sequence !== onlineStatusRequestSequence || id !== deviceId()) return
    if (status !== null) liveOnlineStatus.value = status
  }

  async function loadRealtimeState() {
    await Promise.all([loadTelemetry(), loadOnlineStatus()])
  }

  function stopTelemetryRefresh() {
    telemetryRefreshActive.value = false
    clearTelemetryRefresh(telemetryRefreshTimer)
  }

  function startTelemetryRefresh() {
    stopTelemetryRefresh()
    if (typeof window === 'undefined' || !deviceId()) return
    telemetryRefreshActive.value = true
    scheduleTelemetryRefresh(telemetryRefreshTimer, loadRealtimeState, () => telemetryRefreshActive.value)
  }

  watch(
    () => [online(), deviceData()?.is_online],
    () => {
      if (hasExternalOnlineStatus(online(), deviceData())) {
        onlineStatusRequestSequence += 1
        liveOnlineStatus.value = null
      }
    }
  )

  watch(deviceId, () => {
    telemetryRequestSequence += 1
    onlineStatusRequestSequence += 1
    telemetry.value = {}
    liveOnlineStatus.value = null
  })

  onUnmounted(() => {
    stopTelemetryRefresh()
  })

  return {
    telemetry,
    liveOnlineStatus,
    temperatureUnit,
    telemetryRows,
    deviceOnlineText,
    deviceDescriptionText,
    formatTemperatureValue,
    formatSwitch,
    formatLedStatus,
    formatValue,
