} from './telemetrySimulationState'

type UseTelemetrySimulationDialogOptions = {
  getDeviceId: () => string
  getSimulationInitRequest: (params: { device_id: string }) => Promise<any>
  sendSimulationDataRequest: (payload: Record<string, any>) => Promise<any>
