  isJSON: (value: string) => boolean
}

export const useTelemetrySimulationDialog = ({
  getDeviceId,
  getSimulationInitRequest,
  sendSimulationDataRequest,
  translate,
  isJSON
}: UseTelemetrySimulationDialogOptions) => {
  const showLogDialog = ref(false)
  const showError = ref(false)
  const erroMessage = ref('')
  const showAdvanced = ref(false)
  const simulationLoading = ref(false)
  const simulationForm = reactive(createTelemetrySimulationFormState())

  const requestSimulationInit = async () => {
    const { data, error } = await getSimulationInitRequest({
      device_id: getDeviceId()
    })
    if (!error && data) {
      applySimulationInitData(simulationForm, data)
    } else {
      applySimulationPayloadDefaults(simulationForm)
    }
  }

  const openUpLog = () => {
    openTelemetrySimulationDialog(showError, showLogDialog, showAdvanced)
    void requestSimulationInit()
  }

  const handleSimulationSubmitSuccess = () => {
    applyTelemetrySimulationSubmitSuccess(showLogDialog, showError)
    window.$message?.success(translate('custom.devicePage.success'))
  }

  const handleSimulationSubmitError = (error: any) => {
    applyTelemetrySimulationSubmitError(showError, erroMessage, extractSimulationErrorMessage(error))
  }

  const sendSimulationDataByForm = async () => {
    if (!simulationForm.default_data) {
      window.$message?.error(translate('custom.device_details.sendInputData'))
      return
    }

    simulationLoading.value = true
    try {
      const { error } = await sendSimulationDataRequest(buildSimulationPayload(simulationForm, getDeviceId()))
      if (!error) {
        handleSimulationSubmitSuccess()
      } else {
        handleSimulationSubmitError(error)
      }
    } catch (error) {
      handleSimulationSubmitError(error)
    } finally {
      simulationLoading.value = false
    }
  }

  const copySimulationData = async () => {
    if (!simulationForm.default_data) return
    try {
      await navigator.clipboard.writeText(simulationForm.default_data)
      window.$message?.success(translate('theme.configOperation.copySuccess'))
    } catch {
      window.$message?.error(translate('common.copyFailed'))
    }
  }

  const formatSimulationData = () => {
    if (!simulationForm.default_data) return
    const nextValue = formatSimulationJson(simulationForm.default_data, isJSON)
    if (!nextValue) {
      window.$message?.warning(translate('custom.device_details.notJsonNoFormat'))
      return
    }
    simulationForm.default_data = nextValue
  }

  const clearSimulationData = () => {
    clearSimulationPayload(simulationForm)
  }

  const toggleAdvanced = () => {
    toggleTelemetryAdvanced(showAdvanced)
  }

  const closeSimulationDialog = () => {
    closeTelemetrySimulationDialog(showLogDialog)
  }

  watch(
    () => simulationForm.topic,
    (val) => {
      syncSimulationPayloadByTopic(simulationForm, val)
    }
  )

  watch(
    () => simulationForm.default_data,
    (value) => {
      rememberSimulationPayloadByTopic(simulationForm, simulationForm.topic, value)
    }
  )

  return {
    closeSimulationDialog,
    clearSimulationData,
    copySimulationData,
    erroMessage,
    formatSimulationData,
    openUpLog,
    requestSimulationInit,
    sendSimulationDataByForm,
    showAdvanced,
    showError,
    showLogDialog,
    simulationForm,
    simulationLoading,
    toggleAdvanced
  }
}

/**
 * 文件用途：承接遥测页面中纯展示壳层的常量和平台判断。
 * 核心逻辑：集中卡片尺寸、筛选/排序选项文案和平台宽度判断，避免这些展示状态堆回 `telemetry.vue`。
 * 关键注意事项：这里故意不接入日志、控制项、实时流或弹窗副作用，只服务页面展示层。
 * 重构建议：后续若卡片头部图标、时间展示或布局断点继续增长，可继续沿该壳层 helper 下沉。
 */
import { computed, getCurrentInstance, ref } from 'vue'
import { TELEMETRY_CARD_FRESHNESS_FILTER, TELEMETRY_CARD_SORT_MODE } from './telemetryCardViewState'

type TelemetrySortOption = {
  label: string
  value: string
}

type UseTelemetryViewShellOptions = {
  translate: (key: string) => string
}

export const useTelemetryViewShell = ({ translate }: UseTelemetryViewShellOptions) => {
  const nowTime = ref<unknown>()
  const cardHeight = ref(160)
  const cardMargin = ref(15)

  const telemetrySortOptions = computed<TelemetrySortOption[]>(() => [
    { label: translate('custom.device_details.telemetrySortDefault'), value: TELEMETRY_CARD_SORT_MODE.default },
    { label: translate('custom.device_details.telemetrySortName'), value: TELEMETRY_CARD_SORT_MODE.name },
    { label: translate('custom.device_details.telemetrySortLastUpdate'), value: TELEMETRY_CARD_SORT_MODE.lastUpdate }
  ])

  const telemetryFreshnessOptions = computed<TelemetrySortOption[]>(() => [
    {
      label: translate('custom.device_details.telemetryFreshnessAll'),
      value: TELEMETRY_CARD_FRESHNESS_FILTER.all
    },
    {
      label: translate('custom.device_details.telemetryFreshnessAttention'),
      value: TELEMETRY_CARD_FRESHNESS_FILTER.attention
    },
    {
      label: translate('custom.device_details.telemetryFreshnessStaleOnly'),
      value: TELEMETRY_CARD_FRESHNESS_FILTER.stale
    },
    {
      label: translate('custom.device_details.telemetryFreshnessMissingOnly'),
      value: TELEMETRY_CARD_FRESHNESS_FILTER.missingTimestamp
    }
  ])

  const instance = getCurrentInstance()
  const getPlatform = computed(() => {
    const { proxy }: any = instance
    return proxy.getPlatform()
  })

  return {
    cardHeight,
    cardMargin,
    getPlatform,
    nowTime,
    telemetryFreshnessOptions,
    telemetrySortOptions
  }
}

import { ref } from 'vue'
import { commandDataById, getDeviceConnectionDiagnostics, getDeviceConnectionGuide } from '@/service/api/device'
import { getReadyCheckViewEvidence } from './device-connection-diagnostics-state'
import type { DeviceConnectionGuideStateInput } from './device-access-guide-state'
import { buildRecommendedCommandDraft, type RecommendedCommandDraft } from './ready-check-command-draft'

export type ReadyCheckCollectionFailure = {
  key: 'diagnostics' | 'connectionGuide' | 'commands'
  labelKey: string
}

const allCollectorFailures = (): ReadyCheckCollectionFailure[] => [
  { key: 'diagnostics', labelKey: 'custom.device_details.readyCheckCollectionDiagnostics' },
  { key: 'connectionGuide', labelKey: 'custom.device_details.readyCheckCollectionGuide' },
  { key: 'commands', labelKey: 'custom.device_details.readyCheckCollectionCommands' }
]

export const useReadyCheckCollectors = () => {
  const diagnosticsLoading = ref(false)
  const diagnostics = ref<ReturnType<typeof getReadyCheckViewEvidence>>(getReadyCheckViewEvidence({}))
  const connectionGuide = ref<DeviceConnectionGuideStateInput | null>(null)
  const recommendedCommandLoading = ref(false)
  const recommendedCommandDraft = ref<RecommendedCommandDraft | null>(null)
  const collectionFailures = ref<ReadyCheckCollectionFailure[]>([])
  let collectorRequestSeq = 0
  let inFlightDeviceId = ''
  let inFlightRefresh: Promise<void> | null = null

  const resetCollectors = () => {
    diagnostics.value = getReadyCheckViewEvidence({})
    connectionGuide.value = null
    recommendedCommandDraft.value = null
    collectionFailures.value = []
  }

  const refreshDiagnostics = async (deviceId: string) => {
    if (deviceId && inFlightRefresh && inFlightDeviceId === deviceId) {
      return inFlightRefresh
    }

    const requestSeq = ++collectorRequestSeq
    if (!deviceId) {
      inFlightDeviceId = ''
      inFlightRefresh = null
      resetCollectors()
      diagnosticsLoading.value = false
      recommendedCommandLoading.value = false
      return
    }

    inFlightDeviceId = deviceId
    diagnosticsLoading.value = true
    recommendedCommandLoading.value = true

    const refreshPromise = (async () => {
      const commandsRequest = commandDataById(deviceId).then(
        value => ({ status: 'fulfilled' as const, value }),
        () => ({ status: 'rejected' as const })
      )
      const [diagnosticsResponse, guideResponse] = await Promise.allSettled([
        getDeviceConnectionDiagnostics(deviceId, { debug_log_limit: 3 }),
        getDeviceConnectionGuide(deviceId, { debug_log_limit: 3, command_log_limit: 3 })
      ])

      if (requestSeq !== collectorRequestSeq) return

      collectionFailures.value = [
        diagnosticsResponse.status === 'rejected'
          ? { key: 'diagnostics', labelKey: 'custom.device_details.readyCheckCollectionDiagnostics' }
          : null,
        guideResponse.status === 'rejected'
          ? { key: 'connectionGuide', labelKey: 'custom.device_details.readyCheckCollectionGuide' }
          : null
      ].filter(Boolean) as ReadyCheckCollectionFailure[]

      diagnostics.value =
        diagnosticsResponse.status === 'fulfilled'
          ? getReadyCheckViewEvidence(diagnosticsResponse.value)
          : getReadyCheckViewEvidence({})
      connectionGuide.value =
        guideResponse.status === 'fulfilled' ? guideResponse.value?.data || guideResponse.value || null : null

      diagnosticsLoading.value = false

      const commandsResponse = await commandsRequest

      if (requestSeq !== collectorRequestSeq) return

      recommendedCommandDraft.value =
        commandsResponse.status === 'fulfilled' ? buildRecommendedCommandDraft(commandsResponse.value?.data) : null
      if (commandsResponse.status === 'rejected') {
        collectionFailures.value = [
          ...collectionFailures.value.filter(failure => failure.key !== 'commands'),
          { key: 'commands', labelKey: 'custom.device_details.readyCheckCollectionCommands' }
        ]
      }
    })()

    inFlightRefresh = refreshPromise

    try {
      await refreshPromise
    } catch {
      if (requestSeq === collectorRequestSeq) {
        resetCollectors()
        collectionFailures.value = allCollectorFailures()
      }
    } finally {
      if (requestSeq === collectorRequestSeq) {
        diagnosticsLoading.value = false
        recommendedCommandLoading.value = false
      }
      if (inFlightRefresh === refreshPromise) {
        inFlightDeviceId = ''
        inFlightRefresh = null
      }
    }
  }

  return {
    diagnosticsLoading,
    diagnostics,
    connectionGuide,
    recommendedCommandLoading,
    recommendedCommandDraft,
    collectionFailures,
    refreshDiagnostics
  }
}

import { nextTick, ref } from 'vue'

import { createDeviceTabPlan, resolveDeviceChartTabResolution } from './device-tab-plan'
import { applyRdiCustomerTabs, createBaseDeviceTabs, type DeviceDetailTabComponent } from './device-tab-registry'
import { bumpDeviceTabRefreshKey } from './device-tab-render-state'

type DeviceDetailData = Record<string, any>

type UseDeviceDetailTabsControllerOptions = {
  startLoading: () => void
  endLoading: () => void
  onDeviceTypeChange: (deviceType: string) => void
  onTabChange?: (tabKey: string) => void
}

export const useDeviceDetailTabsController = ({
  startLoading,
  endLoading,
  onDeviceTypeChange,
  onTabChange
}: UseDeviceDetailTabsControllerOptions) => {
  const components = ref<DeviceDetailTabComponent[]>([])
  const tabsRenderKey = ref(0)
  const tabValue = ref<string>('')

  let lastTabsSig = ''
  let lastConfigId = ''
  let chartResolutionSeq = 0
  let currentHiddenKeys = new Set<string>()
  let currentIsRdi = false
  let pendingRequestedTabKey = ''

  const getTabKeys = (tabs = components.value) => tabs.map((item) => item.key)

  const getPreferredTabKey = (tabs = components.value) => {
    const keys = getTabKeys(tabs)
    if (currentIsRdi && keys.includes('message')) return 'message'
    if (keys.includes('rdi')) return 'rdi'
    if (keys.includes('ready-check')) return 'ready-check'
    if (keys.includes('chart')) return 'chart'
    if (keys.includes('telemetry')) return 'telemetry'
    return tabs[0]?.key || ''
  }

  const ensureActiveTab = () => {
    const preferredKey = getPreferredTabKey()
    if (!preferredKey) {
      tabValue.value = ''
      return
    }

    const exists = components.value.some((item) => item.key === tabValue.value)
    if (!exists) tabValue.value = preferredKey
  }

  const setActiveTabIfVisible = (tabKey: string) => {
    const exists = components.value.some((item) => item.key === tabKey)
    if (!exists) return false
    tabValue.value = tabKey
    return true
  }

  const activatePendingRequestedTabIfVisible = () => {
    if (!pendingRequestedTabKey) return false
    const activated = setActiveTabIfVisible(pendingRequestedTabKey)
    if (activated) pendingRequestedTabKey = ''
    return activated
  }

  const activateTabIfVisible = (tabKey: string | null | undefined) => {
    if (!tabKey) return false
    const normalizedTabKey = String(tabKey)
    const activated = setActiveTabIfVisible(normalizedTabKey)
    pendingRequestedTabKey = activated ? '' : normalizedTabKey
    return activated
  }

  const bumpRefreshKey = (targetKey: string) => {
    bumpDeviceTabRefreshKey(components.value, targetKey)
  }

  const cloneBaseComponents = (isRdi = false) => {
    const tabs = createBaseDeviceTabs().map((item) => ({ ...item }))
    return isRdi ? applyRdiCustomerTabs(tabs) : tabs
  }

  const finishTabLoadingAfterRender = () => {
    void nextTick(() => {
      endLoading()
    })
  }

  const applyActiveTabValue = (nextTabValue: string | number) => {
    tabValue.value = String(nextTabValue)
  }

  const changeTabs = (nextTabValue: string | number) => {
    startLoading()
    applyActiveTabValue(nextTabValue)
    onTabChange?.(tabValue.value)
    finishTabLoadingAfterRender()
  }

  const applyDeviceTabPlan = (hiddenKeys: Set<string>, deviceType: string, isRdi = false) => {
    if (deviceType) {
      onDeviceTypeChange(deviceType)
    }

    currentHiddenKeys = new Set(hiddenKeys)
    currentIsRdi = isRdi
    components.value = cloneBaseComponents(isRdi).filter((item) => !hiddenKeys.has(item.key))
    ensureActiveTab()
  }

  const applyChartTabResolution = async (data: DeviceDetailData, shouldShowChart: boolean) => {
    const nextHiddenKeys = new Set(currentHiddenKeys)
    if (shouldShowChart) {
      nextHiddenKeys.delete('chart')
    } else {
      nextHiddenKeys.add('chart')
    }

    const tabPlan = createDeviceTabPlan(data)
    applyDeviceTabPlan(nextHiddenKeys, tabPlan.deviceType, tabPlan.isRdi)
    activatePendingRequestedTabIfVisible()
    await refreshTabsRenderIfNeeded(data)
  }

  const scheduleChartTabResolution = (data: DeviceDetailData) => {
    const resolveSeq = ++chartResolutionSeq
    void resolveDeviceChartTabResolution(data).then((resolution) => {
      if (resolveSeq !== chartResolutionSeq || !resolution) return

      void applyChartTabResolution(data, resolution.shouldShowChart)
    })
  }

  const buildVisibleTabs = async (data: DeviceDetailData) => {
    const tabPlan = createDeviceTabPlan(data)
    applyDeviceTabPlan(tabPlan.hiddenKeys, tabPlan.deviceType, tabPlan.isRdi)
    scheduleChartTabResolution(data)
  }

  const getTabsSignature = () => getTabKeys().join('|')

  const getDeviceConfigId = (data: DeviceDetailData) => data?.device_config_id || ''

  const shouldRefreshTabsRender = (nextSig: string, currentConfigId: string) =>
    nextSig !== lastTabsSig || (lastConfigId && lastConfigId !== currentConfigId)

  const cacheTabsRenderIdentity = (signature: string, configId: string) => {
    lastTabsSig = signature
    lastConfigId = configId
  }

  const refreshTabsRenderIfNeeded = async (data: DeviceDetailData) => {
    const signature = getTabsSignature()
    const configId = getDeviceConfigId(data)
    const shouldRefresh = shouldRefreshTabsRender(signature, configId)
    const isFirstRender = lastTabsSig === ''

    cacheTabsRenderIdentity(signature, configId)

    if (!shouldRefresh || isFirstRender) return

    await nextTick()
    tabsRenderKey.value += 1
  }

  const syncDeviceDetailTabs = async (data: DeviceDetailData) => {
    await buildVisibleTabs(data)
    await refreshTabsRenderIfNeeded(data)
  }

  const refreshActiveTabIfNeeded = (shouldRefreshActiveTab = false) => {
    if (!shouldRefreshActiveTab) return
    bumpRefreshKey(tabValue.value)
  }

  const remountActiveTabLabel = () => {
    const preservedTabValue = tabValue.value
    tabValue.value = ''
    setTimeout(() => {
      tabValue.value = preservedTabValue
    }, 50)
  }

  return {
    activateTabIfVisible,
    changeTabs,
    components,
    refreshActiveTabIfNeeded,
    remountActiveTabLabel,
    syncDeviceDetailTabs,
    tabValue,
    tabsRenderKey
  }
}

