    hoisted.route.query.page = 1
    hoisted.route.query.page_size = 10

    hoisted.routerPush.mockReset()
    hoisted.routerPushByKey.mockReset()
    hoisted.deviceDictProtocolServiceFirstLevel.mockReset()
    hoisted.deviceDictProtocolServiceSecondLevel.mockReset()
    hoisted.deviceGroupRelation.mockReset()
    hoisted.deviceGroupTree.mockReset()
    hoisted.getDeviceConfigList.mockReset()
    hoisted.deviceList.mockReset()
    hoisted.listFleetSavedFilters.mockReset()
    hoisted.createFleetSavedFilter.mockReset()
    hoisted.deleteFleetSavedFilter.mockReset()
    hoisted.updateFleetSavedFilter.mockReset()
    hoisted.deviceConnectForm.mockReset()
    hoisted.checkDevice.mockReset()
    hoisted.activateRdiDevice.mockReset()
    hoisted.wsConnect.mockReset()
    hoisted.wsDisconnect.mockReset()
    hoisted.loggerError.mockReset()

    hoisted.deviceDictProtocolServiceFirstLevel.mockResolvedValue({
      data: {
        protocol: [],
        service: []
      }
    })
    hoisted.deviceDictProtocolServiceSecondLevel.mockResolvedValue({
      data: {
        list: [],
        total: 0
      }
    })
    hoisted.deviceGroupRelation.mockResolvedValue({ data: [] })
    hoisted.deviceGroupTree.mockResolvedValue({ data: [] })
    hoisted.getDeviceConfigList.mockResolvedValue({
      data: {
        list: []
      }
    })
    hoisted.deviceList.mockResolvedValue({
      data: {
        list: [],
        total: 0
      }
    })
    hoisted.listFleetSavedFilters.mockResolvedValue({
      data: {
        list: []
      }
    })
    hoisted.createFleetSavedFilter.mockRejectedValue(new Error('saved filter API unavailable in this test'))
    hoisted.deleteFleetSavedFilter.mockResolvedValue({})
    hoisted.updateFleetSavedFilter.mockResolvedValue({})
    hoisted.deviceConnectForm.mockResolvedValue({ data: {} })
    hoisted.checkDevice.mockResolvedValue({
      error: null,
      data: {
        is_available: true
      }
    })
    hoisted.activateRdiDevice.mockResolvedValue({
      error: null
    })
  })

  it('normalizes uppercase PID and marks valid numbers as available', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.deviceNumber = 'abc123def456'
    await flushPromises()
    await flushPromises()

    expect(setupState.deviceNumber).toBe('ABC123DEF456')

    await flushPromises()

    expect(hoisted.checkDevice).toHaveBeenCalledWith('ABC123DEF456')
    expect(setupState.buttonDisabled).toBe(false)
    expect(setupState.showMessage).toBe(true)
    expect(setupState.messageStyle.color).toBe('rgb(2,153,52)')
  })

  it('rejects malformed PID locally without calling availability API', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.deviceNumber = 'bad-pid'
    await flushPromises()
    await flushPromises()

    expect(hoisted.checkDevice).toHaveBeenCalledTimes(0)
    expect(setupState.buttonDisabled).toBe(true)
    expect(setupState.showMessage).toBe(true)
    expect(setupState.messageStyle.color).toBe('rgb(255, 26, 26)')
  })

  it('activates a valid PID and refreshes the table after success', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    const tableRef = getTableRef(wrapper)

    setupState.active = true
    setupState.deviceNumber = 'abc123def456'
    await setupState.completeAdd()
    await flushPromises()

    expect(hoisted.activateRdiDevice).toHaveBeenCalledWith({
      pid_number: 'ABC123DEF456'
    })
    expect(setupState.active).toBe(false)
    expect(setupState.deviceNumber).toBe('')
    expect(setupState.showMessage).toBe(false)
    expect(setupState.buttonDisabled).toBe(true)
    expect(tableRef.handleSearch).toHaveBeenCalledTimes(1)
  })

  it('uses click trigger for add-device dropdown and opens manual add drawer on manual selection', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    expect(deviceManageSource).toContain('trigger="click"')

    setupState.handleSelect('hands')
    await flushPromises()

    expect(setupState.addKey).toBe('hands')
    expect(setupState.active).toBe(true)
    expect(setupState.placement).toBe('bottom')
  })

  it('routes to service access when selecting add by server', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)

    setupState.handleSelect('server')
    await flushPromises()

    expect(hoisted.routerPush).toHaveBeenCalledWith('/device/service-access')
  })

  it('applies fleet target presets through the table query bridge', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.applyFleetTargetPreset('offline')
    await flushPromises()

    expect(getTableRef(wrapper).forceChangeParamsByKey).toHaveBeenCalledWith({
      is_online: 0,
      warn_status: null,
      shared_status: null,
      device_type: null,
      last_reported_after: null,
      last_reported_before: null,
      never_reported: null
    })
  })

  it('applies the never-reported fleet preset without retaining other target filters', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.applyFleetTargetPreset('never_reported')
    await flushPromises()

    expect(getTableRef(wrapper).forceChangeParamsByKey).toHaveBeenCalledWith({
      is_online: null,
      warn_status: null,
      shared_status: null,
      device_type: null,
      last_reported_after: null,
      last_reported_before: null,
      never_reported: true
    })
  })

  it('updates the fleet target preview count from the device list total', async () => {
    hoisted.deviceList.mockResolvedValueOnce({
      data: {
        list: [],
        total: 42
      }
    })

    const wrapper = mountDeviceManage()
    await flushPromises()

    expect(getSetupState(wrapper).targetPreviewTotal).toBe(42)
  })

  it('saves and reapplies the current fleet filter locally', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.syncFleetQueryResult({
      is_online: 1,
      warn_status: 'Y',
      page: 1
    }, 5, [])

    setupState.saveCurrentFleetFilter()
    await flushPromises()

    expect(setupState.savedFleetFilters).toHaveLength(1)
    expect(setupState.savedFleetFilters[0].previewTotal).toBe(5)
    expect(setupState.savedFleetFilterOptions[0]).toMatchObject({
      rawName: setupState.savedFleetFilters[0].name
    })

    setupState.applySavedFleetFilter(setupState.savedFleetFilters[0].id)
    await flushPromises()

    expect(getTableRef(wrapper).forceChangeParamsByKey).toHaveBeenCalledWith(
      expect.objectContaining({
        is_online: 1,
        warn_status: 'Y'
      })
    )
  })

  it('deletes local-only saved fleet filters without calling the backend', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.syncFleetQueryResult({
      is_online: 1,
      warn_status: 'Y'
    }, 5, [])

    setupState.saveCurrentFleetFilter()
    await flushPromises()

    const filterID = setupState.savedFleetFilters[0].id
    await setupState.deleteSavedFleetFilter(filterID)

    expect(hoisted.deleteFleetSavedFilter).not.toHaveBeenCalled()
    expect(setupState.savedFleetFilters).toHaveLength(0)
  })

  it('deletes backend saved fleet filters through the saved-filter API', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.savedFleetFilters = [
      {
        id: 'server-filter-1',
        name: 'Online devices',
        params: { is_online: 1 },
        previewTotal: 5,
        createdAt: '2026-07-05T12:00:00Z'
      }
    ]

    await setupState.deleteSavedFleetFilter('server-filter-1')

    expect(hoisted.deleteFleetSavedFilter).toHaveBeenCalledWith('server-filter-1')
    expect(setupState.savedFleetFilters).toHaveLength(0)
  })

  it('renames local-only saved fleet filters without calling the backend', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.syncFleetQueryResult({
      is_online: 1
    }, 5, [])

    setupState.saveCurrentFleetFilter()
    await flushPromises()

    const filterID = setupState.savedFleetFilters[0].id
    const renamed = await setupState.renameSavedFleetFilter(filterID, 'Online devices')

    expect(renamed).toBe(true)
    expect(hoisted.updateFleetSavedFilter).not.toHaveBeenCalled()
    expect(setupState.savedFleetFilters[0].name).toBe('Online devices')
  })

  it('renames backend saved fleet filters through the saved-filter API', async () => {
    hoisted.updateFleetSavedFilter.mockResolvedValueOnce({
      data: {
        id: 'server-filter-1',
        name: 'Online pumps',
        device_filter: { is_online: 1 },
        preview_total: 5,
        updated_at: '2026-07-06T00:00:00Z'
      }
    })

    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.savedFleetFilters = [
      {
        id: 'server-filter-1',
        name: 'Online devices',
        params: { is_online: 1 },
        previewTotal: 5,
        createdAt: '2026-07-05T12:00:00Z'
      }
    ]

    const renamed = await setupState.renameSavedFleetFilter('server-filter-1', 'Online pumps')

    expect(renamed).toBe(true)
    expect(hoisted.updateFleetSavedFilter).toHaveBeenCalledWith(
      'server-filter-1',
      expect.objectContaining({
        name: 'Online pumps',
        device_filter: {
          is_online: 1
        },
        preview_total: 5
      })
    )
    expect(setupState.savedFleetFilters[0].name).toBe('Online pumps')
  })

  it('opens selected-device command center with fleet context', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.handleFleetSelectionUpdate([{ id: 'device-command-1' }, { id: 'device-command-2' }])
    setupState.openSelectedDeviceCommandContext()
    await flushPromises()

    expect(hoisted.routerPush).toHaveBeenCalledWith({
      path: '/device/command-center',
      query: {
        device_ids: 'device-command-1,device-command-2',
        fleet_source: 'device_manage',
        fleet_scope: 'selected_devices',
        fleet_selected_count: 2,
        first_device_id: 'device-command-1'
      }
    })
  })

  it('requires scope confirmation before opening filter-result fleet OTA', async () => {
    const wrapper = mountDeviceManage()
    await flushPromises()

    const setupState = getSetupState(wrapper)
    setupState.syncFleetQueryResult({
      page: 1,
      page_size: 10,
      group_id: 'group-1',
      is_online: 1
    }, 42, [])
    setupState.openFleetOtaContext()
    await flushPromises()

    expect(setupState.fleetScopeConfirmVisible).toBe(true)
    expect(setupState.pendingFleetScopeAction?.path).toBe('/product/update-ota')
    expect(hoisted.routerPush).not.toHaveBeenCalled()

    setupState.confirmFleetCurrentPageAction()
    await flushPromises()

    expect(hoisted.routerPush).toHaveBeenCalledWith(
      expect.objectContaining({
        path: '/product/update-ota',
        query: expect.objectContaining({
          fleet_source: 'device_manage',
          fleet_scope: 'filter_result',
          fleet_requested_total: 42,
          group_id: 'group-1',
          is_online: 1
        })
      })
    )
  })

  it('cancels pending device-status subscription when unmounted', async () => {
    vi.useFakeTimers()

    try {
      const wrapper = mountDeviceManage()
      await flushPromises()

      wrapper.unmount()
      vi.advanceTimersByTime(100)

      expect(hoisted.wsConnect).not.toHaveBeenCalled()
      expect(hoisted.wsDisconnect).toHaveBeenCalledTimes(1)
    } finally {
      vi.useRealTimers()
    }
  })
})

import {
  buildFleetRolloutDeviceIds,
  buildFleetRolloutQuery,
  getFleetRolloutDeviceId
} from '../modules/fleet-rollout-context'

export type DeviceFleetOperationRow = Record<string, any>

export type FleetSelectionSummary = {
  total: number
  online: number
  offline: number
  alarmed: number
  missingVersion: number
}

export function getDeviceRowId(row: DeviceFleetOperationRow) {
  return getFleetRolloutDeviceId(row)
}

export function buildFleetDeviceIds(rows: DeviceFleetOperationRow[]) {
  return buildFleetRolloutDeviceIds(rows)
}

function csvCell(value: unknown) {
  const text = value === null || value === undefined ? '' : String(value)
  return `"${text.replace(/"/g, '""')}"`
}

export function buildFleetDeviceCsv(rows: DeviceFleetOperationRow[]) {
  const headers = [
    'id',
    'device_number',
    'name',
    'device_config_name',
    'is_online',
    'warn_status',
    'current_version',
    'pid_number',
    'firmware_version',
    'description'
  ]
  const csvRows = rows.map((row) => headers.map((header) => csvCell(row[header])).join(','))

  return [headers.join(','), ...csvRows].join('\r\n')
}

export function buildFleetSelectionSummary(rows: DeviceFleetOperationRow[]): FleetSelectionSummary {
  return {
    total: rows.length,
    online: rows.filter((row) => row?.is_online === 1).length,
    offline: rows.filter((row) => row?.is_online === 0).length,
    alarmed: rows.filter((row) => row?.warn_status === 'Y').length,
    missingVersion: rows.filter((row) => !String(row?.current_version || row?.firmware_version || '').trim()).length
  }
}

export function buildFleetSelectedDeviceIdentifiers(rows: DeviceFleetOperationRow[]) {
  return rows
    .map((row) => row?.device_number || row?.pid_number || row?.id)
    .filter((value): value is string => Boolean(value))
    .join('\n')
}

export function downloadFleetDeviceCsv(rows: DeviceFleetOperationRow[], filename = `fleet-devices-${Date.now()}.csv`) {
  const blob = new Blob(['\uFEFF', buildFleetDeviceCsv(rows)], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')

  link.href = url
  link.download = filename
  link.click()
  URL.revokeObjectURL(url)
}

export function buildFleetContextQuery(
  rows: DeviceFleetOperationRow[],
  fallbackParams: Record<string, unknown>,
  requestedTotal?: number | null
) {
  return buildFleetRolloutQuery(rows, fallbackParams, undefined, requestedTotal)
}

export function cleanFleetFilterParams(params: Record<string, unknown>) {
  return Object.fromEntries(
    Object.entries(params).filter(([, value]) => value !== null && value !== undefined && String(value).trim() !== '')
  )
}

/**
 * 文件用途: 表达 Fleet 批量选择的两种语义（仅当页勾选 / 全部匹配筛选结果）并计算真实作用范围。
 * 核心逻辑: 全量选择走 device_filter 交接，作用台数受安全上限截断，截断量必须如实呈现给操作员。
 * 关键注意事项: 上限默认值必须与 Command Center 的 DEFAULT_FILTER_JOB_MAX_DEVICES 保持一致，否则 UI 会谎报。
 */

export type FleetSelectionMode = 'current_page' | 'all_matching'

/** 与 Command Center DEFAULT_FILTER_JOB_MAX_DEVICES 及后端 defaultFleetCommandDeviceFilterMaxDevices 对齐。 */
export const FLEET_SELECT_ALL_DEFAULT_MAX_DEVICES = 200
/** 与后端 maxFleetCommandDeviceFilterMaxDevices 对齐。 */
export const FLEET_SELECT_ALL_HARD_MAX_DEVICES = 1000

export type FleetSelectionScope = {
  mode: FleetSelectionMode
  /** 当前筛选条件匹配到的设备总数（来自设备列表 total）。 */
  matchedTotal: number
  /** 当前页加载的设备数。 */
  currentPageCount: number
  /** 当页真正被勾选的行数。 */
  checkedCount: number
  /** 下一个批量动作实际会作用到的设备数。 */
  effectiveCount: number
  maxDevices: number
  /** 匹配总数超过安全上限时为 true。 */
  truncated: boolean
  /** 因为上限而不会被作用到的设备数。 */
  skippedCount: number
}

export type FleetSelectionScopeMessage = {
  key: string
  params: Record<string, number>
}

export function normalizeFleetSelectAllMaxDevices(value?: number | null) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {
    return FLEET_SELECT_ALL_DEFAULT_MAX_DEVICES
  }
  return Math.min(Math.floor(value), FLEET_SELECT_ALL_HARD_MAX_DEVICES)
}

export function canSelectAllMatchingFleetDevices(matchedTotal?: number | null) {
  return typeof matchedTotal === 'number' && Number.isFinite(matchedTotal) && matchedTotal > 0
}

export function buildFleetSelectionScope(input: {
  mode: FleetSelectionMode
  matchedTotal?: number | null
  currentPageCount?: number | null
  checkedCount?: number | null
  maxDevices?: number | null
}): FleetSelectionScope {
  const matchedTotal = canSelectAllMatchingFleetDevices(input.matchedTotal) ? Number(input.matchedTotal) : 0
  const currentPageCount = Math.max(Number(input.currentPageCount) || 0, 0)
  const checkedCount = Math.max(Number(input.checkedCount) || 0, 0)
  const maxDevices = normalizeFleetSelectAllMaxDevices(input.maxDevices)

  if (input.mode !== 'all_matching') {
    return {
      mode: 'current_page',
      matchedTotal,
      currentPageCount,
      checkedCount,
      effectiveCount: checkedCount,
      maxDevices,
      truncated: false,
      skippedCount: 0
    }
  }

  const effectiveCount = Math.min(matchedTotal, maxDevices)

  return {
    mode: 'all_matching',
    matchedTotal,
    currentPageCount,
    checkedCount,
    effectiveCount,
    maxDevices,
    truncated: matchedTotal > maxDevices,
    skippedCount: Math.max(matchedTotal - maxDevices, 0)
  }
}

/**
 * 输出用于展示的 i18n key 与参数：当页语义、全量语义、以及全量被上限截断三种情况分别有独立文案，
 * 避免操作员把「当页勾选」误当成「全部匹配」。
 */
export function formatFleetSelectionScopeText(template: string, params: Record<string, number>) {
  return Object.entries(params).reduce(
    (text, [name, value]) => text.replaceAll(`{${name}}`, String(value)),
    template
  )
}

export function buildFleetSelectionScopeMessage(scope: FleetSelectionScope): FleetSelectionScopeMessage {
  if (scope.mode !== 'all_matching') {
    return {
      key: 'custom.devicePage.fleetSelectionScopeCurrentPage',
      params: {
        checked: scope.checkedCount,
        page: scope.currentPageCount,
        matched: scope.matchedTotal
      }
    }
  }

  if (scope.truncated) {
    return {
      key: 'custom.devicePage.fleetSelectionScopeCapped',
      params: {
        matched: scope.matchedTotal,
        effective: scope.effectiveCount,
        max: scope.maxDevices,
        skipped: scope.skippedCount
      }
    }
  }

  return {
    key: 'custom.devicePage.fleetSelectionScopeAllMatching',
    params: {
      matched: scope.matchedTotal,
      effective: scope.effectiveCount,
      max: scope.maxDevices
    }
  }
}

export type FleetTargetPresetKey =
  | 'all'
  | 'online'
  | 'offline'
  | 'never_reported'
  | 'alarmed'
  | 'unshared'
  | 'direct'
  | 'gateway'

export type FleetTargetPreset = {
  key: FleetTargetPresetKey
  labelKey: string
  params: Record<string, string | number | boolean | null>
}

const FLEET_TARGET_FILTER_KEYS = [
  'is_online',
  'warn_status',
  'shared_status',
  'device_type',
  'last_reported_after',
  'last_reported_before',
  'never_reported'
] as const

export const fleetTargetPresets: FleetTargetPreset[] = [
  {
    key: 'all',
    labelKey: 'custom.devicePage.fleetTargetAll',
    params: {}
  },
  {
    key: 'online',
    labelKey: 'custom.devicePage.fleetTargetOnline',
    params: { is_online: 1 }
  },
  {
    key: 'offline',
    labelKey: 'custom.devicePage.fleetTargetOffline',
    params: { is_online: 0 }
  },
  {
    key: 'never_reported',
    labelKey: 'custom.devicePage.neverReported',
    params: { never_reported: true }
  },
  {
    key: 'alarmed',
    labelKey: 'custom.devicePage.fleetTargetAlarmed',
    params: { warn_status: 'Y' }
  },
  {
    key: 'unshared',
    labelKey: 'custom.devicePage.fleetTargetUnshared',
    params: { shared_status: 'unshared' }
  },
  {
    key: 'direct',
    labelKey: 'custom.devicePage.fleetTargetDirect',
    params: { device_type: '1' }
  },
  {
    key: 'gateway',
    labelKey: 'custom.devicePage.fleetTargetGateway',
    params: { device_type: '2' }
  }
]

export function buildFleetTargetPresetParams(presetKey: FleetTargetPresetKey) {
  const preset = fleetTargetPresets.find((item) => item.key === presetKey) || fleetTargetPresets[0]
  const clearedParams = Object.fromEntries(FLEET_TARGET_FILTER_KEYS.map((key) => [key, null]))

  return {
    ...clearedParams,
    ...preset.params
  }
}

