/**
 * 文件用途: 覆盖Add Devices Step2在设备场景下的前端行为与契约。
 * 核心逻辑: 通过 Vitest、Vue Test Utils 和必要的接口 mock，验证关键渲染、交互和数据流。
 * 关键注意事项: Mock 数据要贴近真实接口字段，避免只证明组件能挂载。
 * 重构建议: 后续可抽取稳定的挂载工厂和业务 fixture，减少重复 mock 与选择器耦合。
 */
import { defineComponent, h } from 'vue'
import { flushPromises, shallowMount } from '@vue/test-utils'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const hoisted = vi.hoisted(() => ({
  getDeviceConnectInfo: vi.fn(),
  updateDeviceVoucher: vi.fn()
}))

vi.mock('@/service/api/device', () => ({
  getDeviceConnectInfo: hoisted.getDeviceConnectInfo,
  updateDeviceVoucher: hoisted.updateDeviceVoucher
}))

vi.mock('@/locales', () => ({
  $t: (key: string) => key
}))

vi.mock('@/utils/clipboard', () => ({
  writeClipboardText: vi.fn().mockResolvedValue(true)
}))

import Component from '../add-devices-step2.vue'

const mountedWrappers: Array<ReturnType<typeof shallowMount>> = []

const mountComponent = (props = {}) => {
  const wrapper = shallowMount(Component, {
    props: {
      formElements: [],
      nextCallback: vi.fn(),
      device_id: 'device-1',
      formData: {},
      setIsSuccess: vi.fn(),
      ...props
    },
    global: {
      stubs: {
        NForm: defineComponent({ props: ['rules', 'model'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NFormItem: defineComponent({ props: ['label', 'path'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NInput: defineComponent({ props: ['value', 'placeholder'], emits: ['update:value', 'click'], setup() { return () => h('input') } }),
        NSelect: defineComponent({ props: ['value', 'options'], emits: ['update:value'], setup() { return () => h('div') } }),
        NButton: defineComponent({ props: ['type'], emits: ['click'], setup(_, { slots, emit }) { return () => h('button', { onClick: () => emit('click') }, slots.default?.()) } }),
        NScrollbar: defineComponent({ props: ['style'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NCard: defineComponent({ props: ['title'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NDescriptions: defineComponent({ props: ['column'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        NDescriptionsItem: defineComponent({ props: ['label'], setup(_, { slots }) { return () => h('div', slots.default?.()) } }),
        DeviceAccessGuide: defineComponent({
          props: ['accessGuide', 'connectInfo'],
          emits: ['copy'],
          setup(_, { slots }) {
            return () => h('section', slots['credential-form']?.())
          }
        })
      }
    }
  })
  mountedWrappers.push(wrapper)
  return wrapper
}

const getSetupState = (wrapper: ReturnType<typeof shallowMount>) => wrapper.vm.$.setupState as Record<string, any>

describe('device/manage/modules/add-devices-step2.vue', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    hoisted.getDeviceConnectInfo.mockResolvedValue({ data: { host: 'localhost', port: '1883' } })
    hoisted.updateDeviceVoucher.mockResolvedValue({ error: null })
  })

  afterEach(() => {
    while (mountedWrappers.length > 0) {
      mountedWrappers.pop()?.unmount()
    }
  })

  it('initializes dynamic voucher fields and connection info for the created device', async () => {
    const formElements = [
      {
        type: 'input',
        dataKey: 'username',
        label: 'Username',
        placeholder: 'Enter username',
        validate: { required: true, message: 'Username required' }
      },
      {
        type: 'table',
        dataKey: 'mqtt',
        label: 'MQTT',
        array: [
          {
            type: 'input',
            dataKey: 'clientId',
            label: 'Client ID',
            validate: { required: true, message: 'Client ID required' }
          }
        ]
      }
    ]
    const wrapper = mountComponent({
      formElements,
      formData: {
        username: 'device-user',
        clientId: 'client-1'
      }
    })
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(hoisted.getDeviceConnectInfo).toHaveBeenCalledWith({ device_id: 'device-1' })
    expect(state.connectInfo).toEqual({ host: 'localhost', port: '1883' })
    expect(state.formRules).toMatchObject({
      username: { required: true, message: 'Username required' },
      clientId: { required: true, message: 'Client ID required' }
    })
    expect(state.editableFormData).toMatchObject({
      username: 'device-user',
      clientId: 'client-1'
    })
  })

  it('fetches connect info on mount', async () => {
    mountComponent()
    await flushPromises()
    expect(hoisted.getDeviceConnectInfo).toHaveBeenCalledWith({ device_id: 'device-1' })
  })

  it('handleSubmit calls updateDeviceVoucher', async () => {
    const setIsSuccess = vi.fn()
    const nextCallback = vi.fn()
    const wrapper = mountComponent({ setIsSuccess, nextCallback })
    await flushPromises()
    const state = getSetupState(wrapper)
    state.formRef = { validate: vi.fn().mockResolvedValue(undefined) }
    await state.handleSubmit()
    expect(hoisted.updateDeviceVoucher).toHaveBeenCalledWith({
      device_id: 'device-1',
      voucher: expect.any(String)
    })
  })

  it('handleSubmit calls setIsSuccess true on success', async () => {
    const setIsSuccess = vi.fn()
    const nextCallback = vi.fn()
    hoisted.updateDeviceVoucher.mockResolvedValue({ error: null })
    const wrapper = mountComponent({ setIsSuccess, nextCallback })
    await flushPromises()
    const state = getSetupState(wrapper)
    state.formRef = { validate: vi.fn().mockResolvedValue(undefined) }
    await state.handleSubmit()
    expect(setIsSuccess).toHaveBeenCalledWith(true)
  })

  it('handleSubmit calls setIsSuccess false on error', async () => {
    const setIsSuccess = vi.fn()
    const nextCallback = vi.fn()
    hoisted.updateDeviceVoucher.mockResolvedValue({ error: 'fail' })
    const wrapper = mountComponent({ setIsSuccess, nextCallback })
    await flushPromises()
    const state = getSetupState(wrapper)
    state.formRef = { validate: vi.fn().mockResolvedValue(undefined) }
    await state.handleSubmit()
    expect(setIsSuccess).toHaveBeenCalledWith(false)
  })

  it('populates connectInfo on fetch', async () => {
    hoisted.getDeviceConnectInfo.mockResolvedValue({ data: { host: 'broker.local', port: '8883' } })
    const wrapper = mountComponent()
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(state.connectInfo).toEqual({ host: 'broker.local', port: '8883' })
  })

  it('processes formElements with input type', async () => {
    const formElements = [
      { type: 'input', dataKey: 'username', label: 'Username', placeholder: 'Enter username', validate: {} }
    ]
    const wrapper = mountComponent({ formElements, formData: { username: 'test' } })
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(state.editableFormData.username).toBe('test')
  })

  it('processes formElements with table type', async () => {
    const formElements = [
      { type: 'table', dataKey: 'table1', label: 'Table', array: [
        { type: 'input', dataKey: 'field1', label: 'Field1', validate: {} }
      ]}
    ]
    const wrapper = mountComponent({ formElements, formData: { field1: 'value1' } })
    await flushPromises()
    const state = getSetupState(wrapper)
    expect(state.editableFormData.field1).toBe('value1')
  })
})

import { ref, type Ref } from 'vue'
import type { Router } from 'vue-router'
import {
  buildFleetCurrentPageActionRoute,
  buildFleetCurrentPageHandoffQuery,
  type FleetCurrentPageAction
} from './device-fleet-handoff-routes'

type TablePageRef = Ref<
  | {
      dataList?: any[]
    }
  | undefined
>

type MessageApi = {
  warning?: (message: string) => void
}

type UseDeviceManageFleetCurrentPageActionsOptions = {
  tablePageRef: TablePageRef
  router: Router
  t: (key: string) => string
  message?: MessageApi
  lastDeviceQueryParams: Ref<Record<string, unknown>>
  targetPreviewTotal: Ref<number | null>
}

export function useDeviceManageFleetCurrentPageActions(
  options: UseDeviceManageFleetCurrentPageActionsOptions
) {
  const fleetScopeConfirmVisible = ref(false)
  const pendingFleetScopeAction = ref<FleetCurrentPageAction | null>(null)

  const getCurrentPageDeviceRows = () => options.tablePageRef.value?.dataList || []

  const buildFleetCurrentPageQuery = () => {
    const rows = getCurrentPageDeviceRows()
    if (rows.length === 0) {
      options.message?.warning?.(options.t('custom.devicePage.noFleetDevicesToOperate'))
      return null
    }

    return buildFleetCurrentPageHandoffQuery(
      rows,
      options.lastDeviceQueryParams.value,
      options.targetPreviewTotal.value
    )
  }

  const requestFleetCurrentPageAction = (action: FleetCurrentPageAction) => {
    if (!buildFleetCurrentPageQuery()) return

    pendingFleetScopeAction.value = action
    fleetScopeConfirmVisible.value = true
  }

  const confirmFleetCurrentPageAction = () => {
    if (!pendingFleetScopeAction.value) return

    const query = buildFleetCurrentPageQuery()
    if (!query) return

    options.router.push(buildFleetCurrentPageActionRoute(pendingFleetScopeAction.value, query))
    fleetScopeConfirmVisible.value = false
    pendingFleetScopeAction.value = null
  }

  const cancelFleetCurrentPageAction = () => {
    fleetScopeConfirmVisible.value = false
    pendingFleetScopeAction.value = null
  }

  const openFleetOtaContext = () =>
    requestFleetCurrentPageAction({ path: '/product/update-ota', labelKey: 'custom.devicePage.openFleetOta' })
  const openFleetAlarmContext = () =>
    requestFleetCurrentPageAction({ path: '/alarm/warning-message', labelKey: 'custom.devicePage.openFleetAlarms' })

  const openFleetAuditContext = () =>
    requestFleetCurrentPageAction({ path: '/alarm/warning-message', labelKey: 'custom.devicePage.openFleetAudit' })

  return {
    fleetScopeConfirmVisible,
    pendingFleetScopeAction,
    confirmFleetCurrentPageAction,
    cancelFleetCurrentPageAction,
    openFleetOtaContext,
    openFleetAlarmContext,
    openFleetAuditContext
  }
}

import { computed, ref, type Ref } from 'vue'
import type { Router } from 'vue-router'
import type { TreeSelectOption } from 'naive-ui/es/tree-select/src/interface'
import {
  buildFleetTargetPresetParams,
  fleetTargetPresets,
  type FleetTargetPresetKey
} from './device-fleet-target-presets'
import {
  buildFleetSelectionSummary,
  downloadFleetDeviceCsv
} from './device-fleet-operations'
import { buildSelectAllMatchingCommandCenterRoute } from './device-fleet-handoff-routes'
import {
  buildFleetSelectionScope,
  buildFleetSelectionScopeMessage,
  canSelectAllMatchingFleetDevices,
  normalizeFleetSelectAllMaxDevices,
  type FleetSelectionMode
} from './device-fleet-select-all'
import { useDeviceManageFleetCurrentPageActions } from './useDeviceManageFleetCurrentPageActions'
import { useDeviceManageFleetSavedFilters } from './useDeviceManageFleetSavedFilters'
import { useDeviceManageFleetSelectionActions } from './useDeviceManageFleetSelectionActions'

type TablePageRef = Ref<
  | {
      dataList?: any[]
      forceChangeParamsByKey?: (params: Record<string, unknown>) => void
      clearSelection?: () => void
      handleSearch?: () => void
    }
  | undefined
>

type MessageApi = {
  success?: (message: string) => void
  warning?: (message: string) => void
}

type UseDeviceManageFleetOperationsOptions = {
  tablePageRef: TablePageRef
  router: Router
  t: (key: string) => string
  message?: MessageApi
  getGroupOptions: () => Promise<TreeSelectOption[]>
  assignDevicesToGroup: (payload: {
    group_id: string | number
    device_id_list: string[]
  }) => Promise<{ error?: unknown }>
  getStorage?: () => Pick<Storage, 'getItem' | 'setItem'> | null
  /** 全量选择的安全上限，默认与 Command Center / 后端 device_filter 上限一致。 */
  selectAllMaxDevices?: number | null
}

export function useDeviceManageFleetOperations(options: UseDeviceManageFleetOperationsOptions) {
  const activeFleetTargetPreset = ref<FleetTargetPresetKey>('all')
  const targetPreviewTotal = ref<number | null>(null)
  const lastDeviceQueryParams = ref<Record<string, unknown>>({})
  const currentPageDeviceCount = ref(0)
  const currentPageFleetSummary = ref(buildFleetSelectionSummary([]))

  const fleetSelectionMode = ref<FleetSelectionMode>('current_page')
  const fleetSelectAllMaxDevices = ref(normalizeFleetSelectAllMaxDevices(options.selectAllMaxDevices))

  const getCurrentPageDeviceRows = () => options.tablePageRef.value?.dataList || []

  const applyFleetTargetPreset = (presetKey: FleetTargetPresetKey) => {
    activeFleetTargetPreset.value = presetKey
    fleetSelectionMode.value = 'current_page'
    options.tablePageRef.value?.forceChangeParamsByKey?.(buildFleetTargetPresetParams(presetKey))
  }

  const {
    savedFleetFilters,
    savedFleetFilterOptions,
    canSaveCurrentFleetFilter,
    refreshSavedFleetFilters,
    saveCurrentFleetFilter,
    applySavedFleetFilter,
    openSavedFleetFilterCommandContext,
    deleteSavedFleetFilter,
    renameSavedFleetFilter,
    shareSavedFleetFilter
  } = useDeviceManageFleetSavedFilters({
    tablePageRef: options.tablePageRef,
    router: options.router,
    t: options.t,
    message: options.message,
    activeFleetTargetPreset,
    lastDeviceQueryParams,
    targetPreviewTotal,
    getStorage: options.getStorage
  })

  const {
    selectedFleetDeviceRows,
    selectedFleetDeviceIds,
    selectedFleetSummary,
    selectedFleetSummaryVisible,
    selectedFleetDeviceIdentifiers,
    bulkGroupModalVisible,
    bulkGroupOptions,
    bulkGroupId,
    bulkGroupAssigning,
    openSelectedDeviceGroupDialog,
    assignSelectedDevicesToGroup,
    handleFleetSelectionUpdate: applyFleetRowSelection,
    openSelectedFleetSummary,
    copySelectedFleetDeviceIdentifiers,
    openSelectedDeviceCommandContext,
    openFleetConfigContext
  } = useDeviceManageFleetSelectionActions({
    tablePageRef: options.tablePageRef,
    router: options.router,
    t: options.t,
    message: options.message,
    getGroupOptions: options.getGroupOptions,
    assignDevicesToGroup: options.assignDevicesToGroup
  })

  const {
    fleetScopeConfirmVisible,
    pendingFleetScopeAction,
    confirmFleetCurrentPageAction,
    cancelFleetCurrentPageAction,
    openFleetOtaContext,
    openFleetAlarmContext,
    openFleetAuditContext
  } = useDeviceManageFleetCurrentPageActions({
    tablePageRef: options.tablePageRef,
    router: options.router,
    t: options.t,
    message: options.message,
    lastDeviceQueryParams,
    targetPreviewTotal
  })

  const exportCurrentFleetPage = () => {
    const rows = getCurrentPageDeviceRows()
    if (rows.length === 0) {
      options.message?.warning?.(options.t('custom.devicePage.noFleetDevicesToOperate'))
      return
    }

    downloadFleetDeviceCsv(rows)
    options.message?.success?.(options.t('custom.devicePage.fleetExportStarted'))
  }

  const syncFleetQueryResult = (params: Record<string, unknown>, total?: number, rows?: any[]) => {
    const previousTotal = targetPreviewTotal.value
    lastDeviceQueryParams.value = { ...params }
    if (typeof total === 'number') {
      targetPreviewTotal.value = total
    }
    currentPageDeviceCount.value = Array.isArray(rows) ? rows.length : 0
    currentPageFleetSummary.value = buildFleetSelectionSummary(Array.isArray(rows) ? rows : [])

    // 筛选条件/结果总数变了以后，"全部匹配" 的含义也变了；退回当页语义，避免沿用过期的全量范围。
    if (fleetSelectionMode.value === 'all_matching' && typeof total === 'number' && total !== previousTotal) {
      fleetSelectionMode.value = 'current_page'
    }
  }

  // 操作员手动改动当页勾选时，"全部匹配" 语义立即失效，否则两种语义会同时显示、互相矛盾。
  const handleFleetSelectionUpdate = (rows: any[]) => {
    fleetSelectionMode.value = 'current_page'
    applyFleetRowSelection(rows)
  }

  const canSelectAllMatchingDevices = computed(() => canSelectAllMatchingFleetDevices(targetPreviewTotal.value))

  const fleetSelectionScope = computed(() =>
    buildFleetSelectionScope({
      mode: fleetSelectionMode.value,
      matchedTotal: targetPreviewTotal.value,
      currentPageCount: currentPageDeviceCount.value,
      checkedCount: selectedFleetDeviceIds.value.length,
      maxDevices: fleetSelectAllMaxDevices.value
    })
  )

  const fleetSelectionScopeMessage = computed(() => buildFleetSelectionScopeMessage(fleetSelectionScope.value))

  const selectAllMatchingFleetDevices = () => {
    if (!canSelectAllMatchingDevices.value) {
      options.message?.warning?.(options.t('custom.devicePage.fleetSelectAllUnavailable'))
      return
    }
    fleetSelectionMode.value = 'all_matching'
  }

  const clearFleetSelectAllMatching = () => {
    fleetSelectionMode.value = 'current_page'
  }

  const openFleetSelectAllCommandContext = () => {
    const scope = fleetSelectionScope.value
    if (scope.mode !== 'all_matching') {
      options.message?.warning?.(options.t('custom.devicePage.fleetSelectAllRequired'))
      return
    }

    const route = buildSelectAllMatchingCommandCenterRoute({
      params: lastDeviceQueryParams.value,
      matchedTotal: scope.matchedTotal,
      effectiveCount: scope.effectiveCount,
      maxDevices: scope.maxDevices
    })
    if (!route) {
      options.message?.warning?.(options.t('custom.devicePage.fleetSelectAllUnavailable'))
      return
    }

    options.router.push(route)
  }

  return {
    activeFleetTargetPreset,
    targetPreviewTotal,
    lastDeviceQueryParams,
    savedFleetFilters,
    currentPageDeviceCount,
    currentPageFleetSummary,
    selectedFleetDeviceRows,
    selectedFleetDeviceIds,
    selectedFleetSummary,
    selectedFleetSummaryVisible,
    selectedFleetDeviceIdentifiers,
    savedFleetFilterOptions,
    canSaveCurrentFleetFilter,
    bulkGroupModalVisible,
    bulkGroupOptions,
    bulkGroupId,
    bulkGroupAssigning,
    fleetScopeConfirmVisible,
    pendingFleetScopeAction,
    fleetSelectionMode,
    fleetSelectAllMaxDevices,
    fleetSelectionScope,
    fleetSelectionScopeMessage,
    canSelectAllMatchingDevices,
    selectAllMatchingFleetDevices,
    clearFleetSelectAllMatching,
    openFleetSelectAllCommandContext,
    fleetTargetPresets,
    applyFleetTargetPreset,
    refreshSavedFleetFilters,
    saveCurrentFleetFilter,
    applySavedFleetFilter,
    openSavedFleetFilterCommandContext,
    deleteSavedFleetFilter,
    renameSavedFleetFilter,
    shareSavedFleetFilter,
    exportCurrentFleetPage,
    openSelectedDeviceGroupDialog,
    assignSelectedDevicesToGroup,
    handleFleetSelectionUpdate,
    openSelectedFleetSummary,
    copySelectedFleetDeviceIdentifiers,
    confirmFleetCurrentPageAction,
    cancelFleetCurrentPageAction,
    openFleetOtaContext,
    openFleetAlarmContext,
    openSelectedDeviceCommandContext,
    openFleetConfigContext,
    openFleetAuditContext,
    syncFleetQueryResult
  }
}

import { computed, ref, type Ref } from 'vue'
import type { Router } from 'vue-router'
import {
  createFleetSavedFilter,
  deleteFleetSavedFilter,
  listFleetSavedFilters,
  updateFleetSavedFilter
} from '@/service/api/device'
import type { FleetTargetPresetKey } from './device-fleet-target-presets'
import { buildSavedFilterCommandCenterRoute } from './device-fleet-handoff-routes'
import {
  buildFleetSavedFilterPayload,
  hasUsableFleetFilterParams,
  loadSavedFleetFilters,
  mergeSavedFleetFilters,
  normalizeServerFleetSavedFilter,
  normalizeServerFleetSavedFilters,
  saveFleetFilter,
  saveFleetFiltersToStorage,
  type SavedFleetFilter
} from './device-fleet-saved-filters'

type TablePageRef = Ref<
  | {
      forceChangeParamsByKey?: (params: Record<string, unknown>) => void
    }
  | undefined
>

type MessageApi = {
  success?: (message: string) => void
  warning?: (message: string) => void
}

type UseDeviceManageFleetSavedFiltersOptions = {
  tablePageRef: TablePageRef
  router: Router
  t: (key: string) => string
  message?: MessageApi
  activeFleetTargetPreset: Ref<FleetTargetPresetKey>
  lastDeviceQueryParams: Ref<Record<string, unknown>>
  targetPreviewTotal: Ref<number | null>
  getStorage?: () => Pick<Storage, 'getItem' | 'setItem'> | null
}

const defaultStorage = () => (typeof window === 'undefined' ? null : window.localStorage)

const getApiErrorMessage = (error: unknown) => {
  const maybeError = error as {
    message?: string
    response?: {
      data?: {
        message?: string
        msg?: string
      }
    }
    data?: {
      message?: string
      msg?: string
    }
  }

  return (
    maybeError?.response?.data?.message ||
    maybeError?.response?.data?.msg ||
    maybeError?.data?.message ||
    maybeError?.data?.msg ||
    maybeError?.message ||
    ''
  )
}

export function useDeviceManageFleetSavedFilters(options: UseDeviceManageFleetSavedFiltersOptions) {
  const savedFleetFilters = ref<SavedFleetFilter[]>([])
  const getStorage = options.getStorage || defaultStorage

  const savedFleetFilterOptions = computed(() =>
    savedFleetFilters.value.map((filter) => ({
      key: filter.id,
      rawName: filter.name,
      label: typeof filter.previewTotal === 'number' ? `${filter.name} (${filter.previewTotal})` : filter.name,
      shared: filter.shared,
      owned: filter.owned,
      ownerUserId: filter.ownerUserId
    }))
  )

  const canSaveCurrentFleetFilter = computed(() =>
    hasUsableFleetFilterParams(options.lastDeviceQueryParams.value)
  )

  const refreshSavedFleetFilters = async () => {
    const storage = getStorage()
    const localFilters = loadSavedFleetFilters(storage)
    savedFleetFilters.value = localFilters

    try {
      const response = await listFleetSavedFilters()
      const data = (response as any).data ?? response
      const serverFilters = normalizeServerFleetSavedFilters(data?.list ?? [])
      const localOnly = mergeSavedFleetFilters(localFilters, serverFilters).filter(
        (filter) =>
          !serverFilters.some(
            (item) => item.name === filter.name && JSON.stringify(item.params) === JSON.stringify(filter.params)
          )
      )
      const importedFilters: SavedFleetFilter[] = []
      for (const filter of localOnly) {
        const response = await createFleetSavedFilter(
          buildFleetSavedFilterPayload(filter.params, filter.previewTotal, filter.name)
        )
        const created = normalizeServerFleetSavedFilter(((response as any).data ?? response) as any)
        if (created) importedFilters.push(created)
      }
      savedFleetFilters.value = mergeSavedFleetFilters([...importedFilters, ...serverFilters], localFilters)
      saveFleetFiltersToStorage(storage, savedFleetFilters.value)
    } catch {
      savedFleetFilters.value = localFilters
    }
  }

  const saveCurrentFleetFilter = async () => {
    const storage = getStorage()
    try {
      const response = await createFleetSavedFilter(
        buildFleetSavedFilterPayload(
          options.lastDeviceQueryParams.value,
          options.targetPreviewTotal.value
        )
      )
      const created = normalizeServerFleetSavedFilter(((response as any).data ?? response) as any)
      if (created) {
        savedFleetFilters.value = mergeSavedFleetFilters([created], savedFleetFilters.value)
        saveFleetFiltersToStorage(storage, savedFleetFilters.value)
        options.message?.success?.(options.t('custom.devicePage.fleetFilterSaved'))
        return
      }
    } catch {
      // Keep the operator flow usable when the backend saved-filter API is unavailable.
    }

    savedFleetFilters.value = saveFleetFilter(
      storage,
      savedFleetFilters.value,
      options.lastDeviceQueryParams.value,
      options.targetPreviewTotal.value
    )
    options.message?.success?.(options.t('custom.devicePage.fleetFilterSaved'))
  }

  const applySavedFleetFilter = (filterID: string | number) => {
    const filter = savedFleetFilters.value.find((item) => item.id === String(filterID))
    if (!filter) return

    options.activeFleetTargetPreset.value = 'all'
    options.tablePageRef.value?.forceChangeParamsByKey?.(filter.params)
  }

  const openSavedFleetFilterCommandContext = (filterID: string | number) => {
    const filter = savedFleetFilters.value.find((item) => item.id === String(filterID))
    if (!filter) return

    const route = buildSavedFilterCommandCenterRoute(filter.params, filter.previewTotal, filter)
    if (!route) {
      options.message?.warning?.(options.t('custom.devicePage.savedFleetFilterEmpty'))
      return
    }

    options.router.push(route)
  }

  const deleteSavedFleetFilter = async (filterID: string | number) => {
    const id = String(filterID)
    const storage = getStorage()
    const target = savedFleetFilters.value.find((item) => item.id === id)
    if (target && target.owned === false) {
      options.message?.warning?.(options.t('custom.devicePage.savedFleetFilterNotOwned'))
      return
    }
    const nextFilters = savedFleetFilters.value.filter((item) => item.id !== id)

    if (!id.startsWith('fleet-filter-')) {
      try {
        await deleteFleetSavedFilter(id)
      } catch {
        options.message?.warning?.(options.t('custom.devicePage.savedFleetFilterDeleteFailed'))
        return
      }
    }

    savedFleetFilters.value = nextFilters
    saveFleetFiltersToStorage(storage, savedFleetFilters.value)
    options.message?.success?.(options.t('custom.devicePage.savedFleetFilterDeleted'))
  }

  const renameSavedFleetFilter = async (filterID: string | number, name: string) => {
    const id = String(filterID)
    const nextName = name.trim()
    if (!nextName) {
      options.message?.warning?.(options.t('custom.devicePage.savedFleetFilterNameRequired'))
      return false
    }

    const filter = savedFleetFilters.value.find((item) => item.id === id)
    if (!filter) return false
    if (filter.owned === false) {
      options.message?.warning?.(options.t('custom.devicePage.savedFleetFilterNotOwned'))
      return false
    }

    const storage = getStorage()
    if (id.startsWith('fleet-filter-')) {
      savedFleetFilters.value = savedFleetFilters.value.map((item) =>
        item.id === id ? { ...item, name: nextName } : item
      )
      saveFleetFiltersToStorage(storage, savedFleetFilters.value)
      options.message?.success?.(options.t('custom.devicePage.savedFleetFilterRenamed'))
      return true
    }

    try {
      const response = await updateFleetSavedFilter(
        id,
        buildFleetSavedFilterPayload(filter.params, filter.previewTotal, nextName)
      )
      const updated = normalizeServerFleetSavedFilter(((response as any).data ?? response) as any)
      savedFleetFilters.value = savedFleetFilters.value.map((item) =>
        item.id === id ? updated || { ...item, name: nextName } : item
      )
      saveFleetFiltersToStorage(storage, savedFleetFilters.value)
      options.message?.success?.(options.t('custom.devicePage.savedFleetFilterRenamed'))
      return true
    } catch (error) {
      options.message?.warning?.(
        getApiErrorMessage(error) || options.t('custom.devicePage.savedFleetFilterRenameFailed')
      )
      return false
    }
  }

  const shareSavedFleetFilter = async (filterID: string | number, shared: boolean) => {
    const id = String(filterID)
    const filter = savedFleetFilters.value.find((item) => item.id === id)
    if (!filter) return false
    if (filter.owned === false) {
      options.message?.warning?.(options.t('custom.devicePage.savedFleetFilterNotOwned'))
      return false
    }
    // Sharing lives on the backend row; a local-only filter must be persisted first.
    if (id.startsWith('fleet-filter-')) {
      options.message?.warning?.(options.t('custom.devicePage.savedFleetFilterShareNeedsSync'))
      return false
    }

    const storage = getStorage()
    try {
      const response = await updateFleetSavedFilter(
        id,
        buildFleetSavedFilterPayload(filter.params, filter.previewTotal, filter.name, shared)
      )
      const updated = normalizeServerFleetSavedFilter(((response as any).data ?? response) as any)
      savedFleetFilters.value = savedFleetFilters.value.map((item) =>
        item.id === id ? updated || { ...item, shared } : item
      )
      saveFleetFiltersToStorage(storage, savedFleetFilters.value)
      options.message?.success?.(
        options.t(shared ? 'custom.devicePage.savedFleetFilterShared' : 'custom.devicePage.savedFleetFilterUnshared')
      )
      return true
    } catch (error) {
      options.message?.warning?.(
        getApiErrorMessage(error) || options.t('custom.devicePage.savedFleetFilterShareFailed')
      )
      return false
    }
  }

  return {
    savedFleetFilters,
    savedFleetFilterOptions,
    canSaveCurrentFleetFilter,
    refreshSavedFleetFilters,
    saveCurrentFleetFilter,
    applySavedFleetFilter,
    openSavedFleetFilterCommandContext,
    deleteSavedFleetFilter,
    renameSavedFleetFilter,
    shareSavedFleetFilter
  }
}

import { computed, ref, type Ref } from 'vue'
import type { Router } from 'vue-router'
import type { TreeSelectOption } from 'naive-ui/es/tree-select/src/interface'
import {
  buildFleetSelectedDeviceIdentifiers,
  buildFleetSelectionSummary
} from './device-fleet-operations'
import { buildSelectedDeviceCommandCenterRoute } from './device-fleet-handoff-routes'

type TablePageRef = Ref<
  | {
      clearSelection?: () => void
      handleSearch?: () => void
    }
  | undefined
>

type MessageApi = {
  success?: (message: string) => void
  warning?: (message: string) => void
}

type UseDeviceManageFleetSelectionActionsOptions = {
  tablePageRef: TablePageRef
  router: Router
  t: (key: string) => string
  message?: MessageApi
  getGroupOptions: () => Promise<TreeSelectOption[]>
  assignDevicesToGroup: (payload: {
    group_id: string | number
    device_id_list: string[]
  }) => Promise<{ error?: unknown }>
}

export function useDeviceManageFleetSelectionActions(options: UseDeviceManageFleetSelectionActionsOptions) {
  const selectedFleetDeviceRows = ref<any[]>([])
  const selectedFleetSummaryVisible = ref(false)
  const bulkGroupModalVisible = ref(false)
  const bulkGroupOptions = ref<TreeSelectOption[]>([])
  const bulkGroupId = ref<string | number | null>(null)
  const bulkGroupAssigning = ref(false)

  const selectedFleetDeviceIds = computed(() =>
    selectedFleetDeviceRows.value.map((row) => row?.id).filter((id): id is string => Boolean(id))
  )
  const selectedFleetSummary = computed(() => buildFleetSelectionSummary(selectedFleetDeviceRows.value))
  const selectedFleetDeviceIdentifiers = computed(() =>
    buildFleetSelectedDeviceIdentifiers(selectedFleetDeviceRows.value)
  )

  const openSelectedDeviceGroupDialog = async () => {
    if (selectedFleetDeviceIds.value.length === 0) {
      options.message?.warning?.(options.t('custom.devicePage.selectFleetDevicesFirst'))
      return
    }

    bulkGroupId.value = null
    bulkGroupOptions.value = await options.getGroupOptions()
    bulkGroupModalVisible.value = true
  }

  const assignSelectedDevicesToGroup = async () => {
    if (!bulkGroupId.value) {
      options.message?.warning?.(options.t('custom.devicePage.selectTargetGroupFirst'))
      return
    }

    const deviceIds = selectedFleetDeviceIds.value
    if (deviceIds.length === 0) {
      options.message?.warning?.(options.t('custom.devicePage.selectFleetDevicesFirst'))
      return
    }

    bulkGroupAssigning.value = true
    try {
      const { error } = await options.assignDevicesToGroup({
        group_id: bulkGroupId.value,
        device_id_list: deviceIds
      })

      if (error) return

      options.message?.success?.(options.t('custom.devicePage.selectedDevicesAddedToGroup'))
      bulkGroupModalVisible.value = false
      selectedFleetDeviceRows.value = []
      options.tablePageRef.value?.clearSelection?.()
      options.tablePageRef.value?.handleSearch?.()
    } finally {
      bulkGroupAssigning.value = false
    }
  }

  const handleFleetSelectionUpdate = (rows: any[]) => {
    selectedFleetDeviceRows.value = rows
    if (rows.length === 0) {
      selectedFleetSummaryVisible.value = false
    }
  }

  const openSelectedFleetSummary = () => {
    if (selectedFleetDeviceRows.value.length === 0) {
      options.message?.warning?.(options.t('custom.devicePage.selectFleetDevicesFirst'))
      return
    }
    selectedFleetSummaryVisible.value = true
  }

  const copySelectedFleetDeviceIdentifiers = async () => {
    if (!selectedFleetDeviceIdentifiers.value) {
      options.message?.warning?.(options.t('custom.devicePage.selectFleetDevicesFirst'))
      return
    }
    try {
      await navigator.clipboard.writeText(selectedFleetDeviceIdentifiers.value)
      options.message?.success?.(options.t('custom.devicePage.selectedDeviceIdentifiersCopied'))
    } catch {
      options.message?.warning?.(options.t('custom.devicePage.selectedDeviceIdentifiersCopyFailed'))
    }
  }

  const openSelectedDeviceCommandContext = () => {
    const route = buildSelectedDeviceCommandCenterRoute(selectedFleetDeviceIds.value)
    if (!route) {
      options.message?.warning?.(options.t('custom.devicePage.selectFleetDevicesFirst'))
      return
    }

    options.router.push(route)
  }

  const openFleetConfigContext = () => {
    if (selectedFleetDeviceIds.value.length === 0) {
      options.message?.warning?.(options.t('custom.devicePage.selectFleetDevicesFirst'))
      return
    }

    options.message?.warning?.(options.t('custom.devicePage.fleetConfigTagUseGroupAction'))
    openSelectedDeviceGroupDialog()
  }

  return {
    selectedFleetDeviceRows,
    selectedFleetDeviceIds,
    selectedFleetSummary,
    selectedFleetSummaryVisible,
    selectedFleetDeviceIdentifiers,
    bulkGroupModalVisible,
    bulkGroupOptions,
    bulkGroupId,
    bulkGroupAssigning,
    openSelectedDeviceGroupDialog,
    assignSelectedDevicesToGroup,
    handleFleetSelectionUpdate,
    openSelectedFleetSummary,
    copySelectedFleetDeviceIdentifiers,
    openSelectedDeviceCommandContext,
    openFleetConfigContext
  }
}

import type { Ref } from 'vue'
import { ref } from 'vue'
import { deviceDictProtocolServiceFirstLevel, deviceDictProtocolServiceSecondLevel } from '@/service/api/device'
import type { SearchConfig } from '@/components/data-table-page/types'
import { $t } from '@/locales'
import { localStg } from '@/utils/storage'

interface ServiceIds {
  service_identifier: string
  service_plugin_id: string
}

interface ServiceAccessFilterOptions {
  searchConfigs: Ref<SearchConfig[]>
  tablePageRef: Ref<any>
  initialServiceIdentifier: unknown
  initialServiceAccessId: unknown
}

const SERVICE_ACCESS_FILTER_KEY = 'service_access_id'

const normalizeServiceIdentifier = (value: unknown) => String(value || '')

const createServiceAccessSearchConfig = (): SearchConfig => ({
  key: SERVICE_ACCESS_FILTER_KEY,
  label: 'custom.devicePage.selectSecondLevelService',
  type: 'select',
  options: []
})

const setSelectOptions = (item: SearchConfig, options: any[]) => {
  if (item.type === 'select') {
    item.options = options
  }
}

export const useDeviceManageServiceAccessFilters = ({
  searchConfigs,
  tablePageRef,
  initialServiceIdentifier,
  initialServiceAccessId
}: ServiceAccessFilterOptions) => {
  const secondLevelOptions = ref<DeviceManagement.ServiceData[]>([])
  const selectedFirstLevel = ref<string | null>(null)
  const serviceIds = ref<ServiceIds[]>([])
  const queryOfServiceIdentifier = ref(initialServiceIdentifier)
  const queryOfServiceAccessId = ref(initialServiceAccessId)
  const serviceFiltersReady = ref(false)
  let secondLevelRequestId = 0

  const getSearchConfigIndex = (key: string) => searchConfigs.value.findIndex((item) => item.key === key)

  const updateSearchConfigsByKey = (key: string, update: (item: SearchConfig) => void) => {
    searchConfigs.value.forEach((item) => {
      if (item.key === key) {
        update(item)
      }
    })
  }

  const getServiceFilterIndexes = () => ({
    identifierIndex: getSearchConfigIndex('service_identifier'),
    accessIndex: getSearchConfigIndex(SERVICE_ACCESS_FILTER_KEY)
  })

  const isServiceIdentifier = (identifier: string) =>
    serviceIds.value.some((item) => item.service_identifier === identifier)

  const getServicePluginId = (identifier: string) =>
    serviceIds.value.find((item) => item.service_identifier === identifier)?.service_plugin_id

  const clearServiceAccessOptions = () => {
    updateSearchConfigsByKey(SERVICE_ACCESS_FILTER_KEY, (item) => {
      setSelectOptions(item, [])
    })
  }

  const applySecondLevelOptions = () => {
    updateSearchConfigsByKey(SERVICE_ACCESS_FILTER_KEY, (item) => {
      setSelectOptions(
        item,
        secondLevelOptions.value.map((item2) => ({
          label: item2.name,
          value: item2.id
        }))
      )
    })
  }

  const resetServiceAccessQueryParam = () => {
    tablePageRef.value?.forceChangeParamsByKey({
      [SERVICE_ACCESS_FILTER_KEY]: null
    })
  }

  const ensureServiceAccessFilter = (identifierIndex: number, accessIndex: number) => {
    if (identifierIndex === -1) return
    if (accessIndex === -1) {
      searchConfigs.value.splice(identifierIndex + 1, 0, createServiceAccessSearchConfig())
      return
    }

    resetServiceAccessQueryParam()
  }

  const removeServiceAccessFilter = (accessIndex: number) => {
    searchConfigs.value.splice(accessIndex, 1)
    resetServiceAccessQueryParam()
  }

  const buildRouteServiceParams = () => ({
    service_identifier: queryOfServiceIdentifier.value,
    [SERVICE_ACCESS_FILTER_KEY]: queryOfServiceAccessId.value
  })

  const hasInitialServiceAccessRoute = () =>
    Boolean(normalizeServiceIdentifier(queryOfServiceIdentifier.value) || queryOfServiceAccessId.value)

  const primeInitialServiceAccessFilter = () => {
    if (!queryOfServiceAccessId.value) return
    const { identifierIndex, accessIndex } = getServiceFilterIndexes()
    ensureServiceAccessFilter(identifierIndex, accessIndex)
  }

  const initializeServiceAccessFilters = async () => {
    const { data } = await deviceDictProtocolServiceFirstLevel({
      language_code: localStg.get('lang')
    })
    if (!data) return

    serviceIds.value = []
    const protocolOptions = data.protocol.map((item) => ({
      label: item.name,
      value: item.service_identifier,
      type: 'protocol'
    }))

    const serviceOptions = data.service
      ? data.service.map((item) => {
          serviceIds.value.push({
            service_identifier: item.service_identifier,
            service_plugin_id: item.service_plugin_id
          })

          return {
            label: item.name,
            value: item.service_identifier,
            type: 'service'
          }
        })
      : []

    updateSearchConfigsByKey('service_identifier', (item) => {
      setSelectOptions(item, [
        { label: $t('card.anyProtocolService'), value: '' },
        {
          type: 'group',
          label: $t('common.protocol'),
          key: 'protocol',
          children: [...protocolOptions]
        },
        {
          type: 'group',
          label: $t('common.service'),
          key: 'service',
          children: [...serviceOptions]
        }
      ])
    })
    serviceFiltersReady.value = true
  }

  const fetchSecondLevelOptionsPage = async (firstLevelValue: string, page: number, requestId: number) => {
    if (!firstLevelValue) return
    if (page === 1) {
      secondLevelOptions.value = []
      clearServiceAccessOptions()
    }

    const pluginId = getServicePluginId(firstLevelValue)
    const { data } = await deviceDictProtocolServiceSecondLevel({
      params: {
        service_plugin_id: pluginId,
        page,
        page_size: 100
      }
    })

    if (!data) return
    const { list, total } = data
    if (requestId !== secondLevelRequestId || selectedFirstLevel.value !== firstLevelValue) return

    if (page === 1) {
      secondLevelOptions.value = list
    } else {
      secondLevelOptions.value = [...secondLevelOptions.value, ...list]
    }
    applySecondLevelOptions()

    if (total > secondLevelOptions.value.length) {
      void fetchSecondLevelOptionsPage(firstLevelValue, page + 1, requestId)
    }
  }

  const fetchSecondLevelOptions = async (firstLevelValue: string) => {
    secondLevelRequestId += 1
    await fetchSecondLevelOptionsPage(firstLevelValue, 1, secondLevelRequestId)
  }

  const paramsUpdateHandle = async (params: Record<string, unknown>) => {
    if (!serviceFiltersReady.value) return
    const firstSelected = normalizeServiceIdentifier(params.service_identifier)
    if (firstSelected && selectedFirstLevel.value !== firstSelected) {
      selectedFirstLevel.value = firstSelected
      const { identifierIndex, accessIndex } = getServiceFilterIndexes()
      if (isServiceIdentifier(firstSelected)) {
        ensureServiceAccessFilter(identifierIndex, accessIndex)
        await fetchSecondLevelOptions(firstSelected)
      } else if (accessIndex > -1) {
        removeServiceAccessFilter(accessIndex)
      }
    }
  }

  const setServiceParams = () => {
    tablePageRef.value?.forceChangeParamsByKey(buildRouteServiceParams())
  }

  const initializeServiceAccessFiltersInBackground = async () => {
    try {
      await initializeServiceAccessFilters()
      if (hasInitialServiceAccessRoute()) {
        setServiceParams()
      }
    } catch {
      serviceFiltersReady.value = false
    }
  }

  return {
    initializeServiceAccessFilters,
    initializeServiceAccessFiltersInBackground,
    primeInitialServiceAccessFilter,
    paramsUpdateHandle,
    setServiceParams
  }
}

import { describe, expect, it } from 'vitest'
import {
  buildFleetRolloutQuery,
  buildFleetRolloutSelectionResult,
  FLEET_DEVICE_FILTER_SCOPE,
  FLEET_FILTER_RESULT_SCOPE,
  parseFleetRolloutContext
} from '../fleet-rollout-context'

describe('fleet-rollout-context', () => {
  it('carries a backend-safe device filter for full-filter OTA rollouts', () => {
    const context = parseFleetRolloutContext({
      device_ids: 'dev-1,dev-2',
