    ).toEqual(
      expect.objectContaining({
        fleet_scope: FLEET_FILTER_RESULT_SCOPE,
        fleet_current_page_count: 1,
        fleet_requested_total: 42,
        device_ids: 'dev-1',
        group_id: 'group-1'
      })
    )
  })

  it('accepts command-center device_filter scope and preserves preview sample ids for OTA', () => {
