        '{"group_id":"group-1","is_online":1,"last_reported_after":1752883200000,"never_reported":false}'
    })

    expect(context).toMatchObject({
      scope: FLEET_DEVICE_FILTER_SCOPE,
      deviceIds: ['dev-1', 'dev-2'],
      requestedTotal: 42,
      currentPageCount: 2,
