const isGuideStepComplete = (step: HomeCustomerGuideStep, input: HomeCustomerGuideProgressInput) => {
  switch (step.id) {
    case 'setup':
      return input.setupReady
    case 'deployment':
      return input.deploymentHealthy
    case 'template':
      return input.hasTemplate
    case 'device':
      return input.hasDevice && input.deviceOnline
    case 'telemetry':
      return input.hasTelemetry && input.hasFirstChart
    case 'automation':
      return input.hasAutomation
    case 'dashboard':
      return input.hasDashboard
    default:
      return false
  }
}

export const buildHomeCustomerGuideProgress = (
  input: HomeCustomerGuideProgressInput
): HomeCustomerGuideProgressStep[] => {
  let activeAssigned = false

  return homeCustomerGuideSteps.map((step) => {
    const resolvedStep =
      step.id === 'setup' && input.setupStep
        ? {
            ...step,
            ...input.setupStep
          }
        : step.id === 'template' && !input.hasTemplate
        ? {
            ...step,
            description:
              '不用先离开首页配置物模型；留在“接入第一台设备”工作台，一键生成时会同时创建默认产品、物模型、MQTT/HTTP 配置和第一台设备。',
            route: '/home?onboarding=first-device&focus=device',
            action: '生成默认物模型和设备'
          }
        : step.id === 'device' && !input.hasDevice
        ? {
            ...step,
            description: '留在首页即可一键生成产品、物模型、MQTT/HTTP 配置和第一台设备；生成后继续在这里复制参数并发送第一条遥测。',
            route: '/home?onboarding=first-device&focus=device',
            action: '一键生成设备'
          }
        : step.id === 'device' && input.hasDevice && !input.deviceOnline
        ? {
            ...step,
            description: '已经有第一台设备；现在留在首页继续复制参数、浏览器在线测试和在线状态确认。',
            route: '/home?onboarding=first-device&focus=test',
            action: '继续接入'
          }
        : step.id === 'telemetry' && !input.hasTelemetry
        ? {
            ...step,
            description: '回到首页第 3 步，复制命令或直接点击浏览器在线测试，先发出第一条可见遥测。',
            route: '/home?onboarding=first-device&focus=test',
            action: '发送第一条遥测'
          }
        : step.id === 'telemetry' && input.hasTelemetry && !input.hasFirstChart
        ? {
            ...step,
            description: '最新遥测已经到了，留在首页第 4 步确认第一张图表和可交付状态。',
            route: '/home?onboarding=first-device&focus=chart',
            action: '查看第一张图表'
          }
        : step
    const complete = isGuideStepComplete(step, input)
    if (complete) {
      return {
        ...resolvedStep,
        status: 'done',
        statusLabel: '已完成',
        statusType: 'success'
      }
    }

    if (!activeAssigned) {
      activeAssigned = true
      return {
        ...resolvedStep,
        status: 'active',
        statusLabel: '当前要做',
        statusType: 'warning'
      }
    }

    return {
      ...resolvedStep,
      status: 'todo',
      statusLabel: '待处理',
      statusType: 'default'
    }
  })
}

export const buildHomeCustomerGuideSummary = (steps: HomeCustomerGuideProgressStep[]): HomeCustomerGuideSummary => {
  const totalCount = steps.length
  const doneCount = steps.filter((step) => step.status === 'done').length
  const nextStep = steps.find((step) => step.status === 'active') ?? null
  const percent = totalCount > 0 ? Math.round((doneCount / totalCount) * 100) : 0

  if (!nextStep) {
    return {
      doneCount,
      totalCount,
      percent: 100,
      nextStep,
      headline: '首次接入闭环已完成',
      description: '部署、物模型、设备、遥测、自动化和看板都已具备，可以复制到批量设备或交付客户看板。'
    }
  }

  return {
    doneCount,
    totalCount,
    percent,
    nextStep,
    headline: `下一步：${nextStep.title}`,
    description: nextStep.description
  }
}

import { createProxyPattern } from '~/env.config'
import { getPlatformApiBaseUrl } from '@/utils/common/tool'

export type DeploymentHealthCheck = {
  ok: boolean
  latency_ms: number
  error?: string
}

export type NormalizedDeploymentHealthRow = {
  key: string
  label: string
  description: string
  source: string
  sourceLabel: string
  nextAction: string
  ok: boolean
  latency: number
  error: string
}

export type DeploymentHealthReport = {
  status: 'ok' | 'down' | 'degraded' | string
  version?: string
  timestamp?: string
  http_status?: number
  frontend_proxy?: DeploymentHealthCheck
  api?: DeploymentHealthCheck
  checks?: Record<string, DeploymentHealthCheck>
}

type Translate = (key: string, params?: Record<string, unknown>) => string

type DeploymentHealthEndpointOptions = {
  httpProxyEnabled?: boolean
  platformApiBaseUrl?: string
}

export const resolveDeploymentHealthEndpoint = (options: DeploymentHealthEndpointOptions = {}): string => {
  const httpProxyEnabled = options.httpProxyEnabled ?? import.meta.env.VITE_HTTP_PROXY === 'Y'
  if (httpProxyEnabled) return `${createProxyPattern()}/deployment/health`

  const platformApiBaseUrl = options.platformApiBaseUrl ?? getPlatformApiBaseUrl()
  return `${platformApiBaseUrl.replace(/\/$/, '')}/deployment/health`
}

const healthCopyKeyMap: Record<string, { label: string; description: string; nextAction: string }> = {
  frontend_proxy: {
    label: 'custom.home.firstDevice.health.checks.frontendProxy.label',
    description: 'custom.home.firstDevice.health.checks.frontendProxy.description',
    nextAction: 'custom.home.firstDevice.health.checks.frontendProxy.nextAction'
  },
  api: {
    label: 'custom.home.firstDevice.health.checks.api.label',
    description: 'custom.home.firstDevice.health.checks.api.description',
    nextAction: 'custom.home.firstDevice.health.checks.api.nextAction'
  },
  database: {
    label: 'custom.home.firstDevice.health.checks.database.label',
    description: 'custom.home.firstDevice.health.checks.database.description',
    nextAction: 'custom.home.firstDevice.health.checks.database.nextAction'
  },
  redis: {
    label: 'custom.home.firstDevice.health.checks.redis.label',
    description: 'custom.home.firstDevice.health.checks.redis.description',
    nextAction: 'custom.home.firstDevice.health.checks.redis.nextAction'
  },
  status_redis: {
    label: 'custom.home.firstDevice.health.checks.statusRedis.label',
    description: 'custom.home.firstDevice.health.checks.statusRedis.description',
    nextAction: 'custom.home.firstDevice.health.checks.statusRedis.nextAction'
  },
  mqtt: {
    label: 'custom.home.firstDevice.health.checks.mqtt.label',
    description: 'custom.home.firstDevice.health.checks.mqtt.description',
    nextAction: 'custom.home.firstDevice.health.checks.mqtt.nextAction'
  }
}

const healthSourceMap: Record<string, string> = {
  frontend_proxy: 'browser-same-origin',
  api: 'browser-api-fetch',
  database: 'backend-health-api',
  redis: 'backend-health-api',
  status_redis: 'backend-health-api',
  mqtt: 'backend-mqtt-probe'
}

const healthSourceLabelKeyMap: Record<string, string> = {
  'browser-same-origin': 'custom.home.firstDevice.health.sources.browserSameOrigin',
  'browser-api-fetch': 'custom.home.firstDevice.health.sources.browserApiFetch',
  'backend-health-api': 'custom.home.firstDevice.health.sources.backendHealthApi',
  'backend-mqtt-probe': 'custom.home.firstDevice.health.sources.backendMqttProbe'
}

const requiredDeploymentHealthKeys = ['frontend_proxy', 'api', 'database', 'redis', 'mqtt']

const translateHealthCopy = (key: string, field: 'label' | 'description' | 'nextAction', t: Translate) => {
  const translationKey = healthCopyKeyMap[key]?.[field]
  if (!translationKey) return field === 'label' ? key : ''
  return t(translationKey)
}

const missingDeploymentHealthCheck = (key: string, t: Translate): DeploymentHealthCheck => ({
  ok: false,
  latency_ms: 0,
  error: t('custom.home.firstDevice.health.missingCheck', {
    label: translateHealthCopy(key, 'label', t)
  })
})

export const normalizeDeploymentHealth = (
  report: DeploymentHealthReport | null,
  t: Translate
): NormalizedDeploymentHealthRow[] => {
  if (!report) return []
  const optionalChecks = report.checks || {}
  const checks: Record<string, DeploymentHealthCheck> = {}

  for (const key of requiredDeploymentHealthKeys) {
    const check = key === 'frontend_proxy' ? report.frontend_proxy : key === 'api' ? report.api : optionalChecks[key]
    checks[key] = check || missingDeploymentHealthCheck(key, t)
  }

  for (const [key, check] of Object.entries(optionalChecks)) {
    if (check && !checks[key]) checks[key] = check
  }

  return Object.entries(checks)
    .map(([key, check]) => {
      const source = healthSourceMap[key] || 'backend-health-api'
      const sourceLabelKey = healthSourceLabelKeyMap[source]

      return {
        key,
        label: translateHealthCopy(key, 'label', t),
        description: translateHealthCopy(key, 'description', t),
        source,
        sourceLabel: sourceLabelKey
          ? t(sourceLabelKey)
          : t('custom.home.firstDevice.health.sources.default'),
        nextAction:
          translateHealthCopy(key, 'nextAction', t) || t('custom.home.firstDevice.health.defaultNextAction'),
        ok: Boolean(check.ok),
        latency: Number(check.latency_ms || 0),
        error: check.error || ''
      }
    })
}

export const fetchDeploymentHealthReport = async (t: Translate): Promise<DeploymentHealthReport | null> => {
  const started = performance.now()
  try {
    const response = await fetch(resolveDeploymentHealthEndpoint(), {
      cache: 'no-store',
      headers: {
        Accept: 'application/json'
      }
    })
    const report = (await response.json()) as DeploymentHealthReport
    const latencyMS = Math.max(0, Math.round(performance.now() - started))
    return {
      ...report,
      http_status: response.status,
      api: {
        ok: response.ok,
        latency_ms: latencyMS,
        error: response.ok ? '' : `HTTP ${response.status}`
      },
      frontend_proxy: {
        ok: response.ok,
        latency_ms: latencyMS,
        error: response.ok ? '' : `HTTP ${response.status}`
      }
    }
  } catch (error: any) {
    const latencyMS = Math.max(0, Math.round(performance.now() - started))
    return {
      status: 'down',
      timestamp: new Date().toISOString(),
      api: {
        ok: false,
        latency_ms: latencyMS,
        error: error?.message || t('custom.home.firstDevice.health.apiUnavailable')
      },
      frontend_proxy: {
        ok: true,
        latency_ms: 0
      },
      checks: {}
    }
  }
}

import type {
  FirstDeviceBrowserTestState,
  FirstDeviceChartState,
  FirstDeviceOnboardingGuard,
  FirstDeviceOnlineTesterState
} from './homeFirstDeviceWorkbench'

// Keep the browser-test status precedence separate from the broader workbench
// builders so the deferred connection panel has one focused presentation mapper.
export const buildFirstDeviceOnlineTesterState = (options: {
  guard: FirstDeviceOnboardingGuard
  browserTest?: FirstDeviceBrowserTestState | null
  chart: FirstDeviceChartState
  activeTestCommandLabel?: string
}): FirstDeviceOnlineTesterState => {
  const status = options.browserTest?.status || 'idle'
  const telemetryKey = options.browserTest?.telemetryKey || options.chart.primaryKey
  const telemetryValue = options.browserTest?.telemetryValue || options.chart.primaryValue
  const disabledReason = options.guard.canRunBrowserTest
    ? ''
    : options.guard.activeStep?.description || options.guard.summary || '先补齐连接参数，再运行浏览器在线测试。'
  const echoRows = [
    {
      label: '测试入口',
      value: options.guard.canRunBrowserTest ? '浏览器直接发送一条遥测' : '等待参数补齐'
    },
    {
      label: '测试命令',
      value: options.activeTestCommandLabel || '当前测试命令'
    },
    {
      label: '最后发送',
      value: options.browserTest?.sentAt || '尚未发送'
    },
    {
      label: '回显遥测',
      value: telemetryKey ? `${telemetryKey} = ${telemetryValue || '--'}` : '等待上报确认'
    },
    {
      label: '成功证明',
      value: options.chart.ready ? options.chart.summary : '等待在线、最新遥测和首图变绿'
    }
  ]

  if (status === 'confirmed') {
    return {
      type: 'success',
      statusLabel: '已确认',
      title: '浏览器测试已打通',
      description: options.browserTest?.message || '首页已经用最新遥测确认这条浏览器测试。',
      actionLabel: '再次发送测试',
      disabledReason,
      lastSignal: options.chart.ready ? options.chart.summary : '等待首张图表刷新。',
      echoRows
    }
  }

  if (status === 'failed') {
    return {
      type: 'error',
      statusLabel: '发送失败',
      title: '浏览器测试失败',
      description: options.browserTest?.message || '测试没有发出去，请先打开 Ready Check 查看端点、凭证或网络诊断。',
      actionLabel: '重试测试',
      disabledReason,
      lastSignal: disabledReason || '查看 Ready Check 的连接诊断后再重试。',
      echoRows
    }
  }

  if (status === 'sending') {
    return {
      type: 'info',
      statusLabel: '发送中',
      title: '正在发送测试遥测',
      description: options.browserTest?.message || '浏览器正在把测试遥测发到当前设备接入入口。',
      actionLabel: '发送中',
      disabledReason,
      lastSignal: '等待首页刷新在线状态和最新遥测。',
      echoRows
    }
  }

  if (status === 'sent') {
    return {
      type: 'warning',
      statusLabel: '等待确认',
      title: '测试已发送，等待遥测确认',
      description: options.browserTest?.message || '如果几秒后还没有最新遥测，请打开 Ready Check 查看诊断。',
      actionLabel: '再次发送测试',
      disabledReason,
      lastSignal: options.chart.ready ? options.chart.summary : '等待最新遥测生成第一张图表。',
      echoRows
    }
  }

  return {
    type: options.guard.canRunBrowserTest ? 'info' : 'warning',
    statusLabel: options.guard.canRunBrowserTest ? '可测试' : '待补齐',
    title: options.guard.canRunBrowserTest ? '现在可以直接在线测试' : '在线测试还差一步',
    description: options.guard.canRunBrowserTest
      ? '点一次按钮，浏览器会发送一条测试遥测；成功后首页会自动更新在线、最新遥测和首张图表。'
      : disabledReason,
    actionLabel: '浏览器在线测试',
    disabledReason,
    lastSignal: options.guard.canRunBrowserTest ? '完成标准：回显遥测出现具体 key/value，证明项逐步变绿。' : disabledReason,
    echoRows
  }
}

import {
  buildFirstDeviceSuccessProofPacket,
  type FirstDeviceSuccessProofPacket
} from './homeFirstDeviceSuccessProof'

export interface FirstDeviceProofDeliveryState {
  device: any
  accessGuide: any
  simulation: any
  readyProof: any
  onboardingGuard: any
  chart: any
  browserTest: any
  deploymentHealthRows: any[]
}

export interface FirstDeviceSupportSummaryDelivery {
  firstDeviceUrl: string
  proofUrl: string
  proofFileHint: string
}

export const buildFirstDeviceWorkbenchUrl = (focus = 'quickstart', origin?: string) => {
  const path = `/home?onboarding=first-device&focus=${encodeURIComponent(focus)}`
  return origin ? new URL(path, origin).toString() : path
}

export const buildFirstDeviceEntryUrl = (origin?: string) => {
  return origin ? new URL('/first-device', origin).toString() : '/first-device'
}

export const buildFirstDeviceProofFilename = (device: any) => {
  const number = String(device?.number || device?.name || 'first-device')
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 48)
  return `aetherlink-first-device-proof-${number || 'first-device'}.json`
}

export const buildFirstDeviceProofDelivery = (
  state: FirstDeviceProofDeliveryState,
  origin?: string
): FirstDeviceSupportSummaryDelivery => ({
  firstDeviceUrl: buildFirstDeviceEntryUrl(origin),
  proofUrl: buildFirstDeviceWorkbenchUrl('proof', origin),
  proofFileHint: buildFirstDeviceProofFilename(state.device)
})

export const buildFirstDeviceSuccessProofDeliveryPacket = (
  state: FirstDeviceProofDeliveryState,
  origin?: string
): FirstDeviceSuccessProofPacket =>
  buildFirstDeviceSuccessProofPacket({
    device: state.device,
    accessGuide: state.accessGuide,
    simulation: state.simulation,
    readyProof: state.readyProof,
    onboardingGuard: state.onboardingGuard,
    chart: state.chart,
    browserTest: state.browserTest,
    deploymentHealthRows: state.deploymentHealthRows,
    delivery: {
      ...buildFirstDeviceProofDelivery(state, origin),
      generatedFromPage: '/first-device'
    }
  })

export const downloadFirstDeviceSuccessProofPacket = (
  packet: FirstDeviceSuccessProofPacket,
  filename: string,
  documentRef: Document = document,
  urlRef: Pick<typeof URL, 'createObjectURL' | 'revokeObjectURL'> = URL
) => {
  const blob = new Blob([JSON.stringify(packet, null, 2)], {
    type: 'application/json;charset=utf-8'
  })
  const url = urlRef.createObjectURL(blob)
  const link = documentRef.createElement('a')
  link.href = url
  link.download = filename
  link.click()
  urlRef.revokeObjectURL(url)
}

