    }
  }
  if (!options.chartReady && options.canRunBrowserTest) {
    return {
      type: 'warning',
      title: options.testResult ? '继续确认遥测并生成首图' : '下一步：发送测试遥测并生成首图',
      detail: options.testResult
        ? '测试已经发出，仍可再次发送一条测试遥测；首页会继续刷新最新遥测，并在收到数据后生成第一张图表。'
        : '设备已经创建，现在最该做的是点一次浏览器在线测试，让平台收到第一条遥测并自动生成首图。',
      label: options.testResult ? '再次发送并确认' : '发送测试遥测并确认',
      secondaryLabel: '定位测试区',
      action: 'simulate',
      section: 'test',
      loading: options.actionLoading,
      disabled: false
    }
  }
  if (!options.chartReady) {
    return {
      type: 'warning',
      title: '下一步：补齐参数再验证',
      detail: options.currentBlocker
        ? `当前还差：${options.currentBlocker.label}。先打开 Ready Check 看诊断，或回到参数区补齐端点、凭证和 topic。`
        : '设备存在，但暂时还不能直接发送浏览器测试；先确认连接参数和 Ready Check 诊断。',
      label: '打开 Ready Check',
      secondaryLabel: '定位参数区',
      action: 'ready-check',
      section: 'connection',
      loading: false,
      disabled: false
    }
  }
  return {
    type: 'warning',
    title: '首图已生成，继续确认最终证明',
    detail: options.currentBlocker
      ? `首张图表已经出来，当前还差：${options.currentBlocker.label}。把右侧证明项处理完，首页就会显示“设备已准备好”。`
      : '首张图表已经出来，继续查看证明项是否全部变绿。',
    label: '查看证明项',
    secondaryLabel: '复制首图证明',
    action: 'proof',
    section: 'proof',
    loading: false,
    disabled: false
  }
}

export const hasConnectionPlaceholder = (value: string) => PLACEHOLDER_PATTERN.test(value.trim())

const quickstartStep = (
  options: Omit<FirstDeviceQuickstartStep, 'statusLabel' | 'statusType'> & {
    status: FirstDeviceQuickstartStep['status']
  }
): FirstDeviceQuickstartStep => ({
  ...options,
  statusLabel: options.status === 'done' ? '已完成' : options.status === 'active' ? '现在做' : '待处理',
  statusType: options.status === 'done' ? 'success' : options.status === 'active' ? 'warning' : 'default'
})

export const buildFirstDeviceOnboardingGuard = (options: {
  device: FirstDeviceSummary | null
  telemetry: FirstTelemetryPoint[]
  accessGuide: DeviceAccessGuideState | null
  publishCommand: string
  actionLoading?: boolean
  deploymentHealthy?: boolean
}): FirstDeviceOnboardingGuard => {
  const deploymentHealthy = options.deploymentHealthy !== false
  const hasDevice = Boolean(options.device)
  const hasTelemetry = options.telemetry.length > 0
  const commandHasPlaceholders = !options.publishCommand || hasConnectionPlaceholder(options.publishCommand)
  const endpointUsable =
    options.accessGuide?.endpointKind === 'http' ? isUsableHttpEndpoint(options.accessGuide.endpoint) : hasDevice
  const canCopyCommand = hasDevice && Boolean(options.publishCommand) && !commandHasPlaceholders
  const canRunBrowserTest =
    deploymentHealthy &&
    hasDevice &&
    Boolean(options.publishCommand) &&
    endpointUsable &&
    !commandHasPlaceholders &&
    !options.actionLoading
  const ready = deploymentHealthy && isFirstDeviceReady(options.device, options.telemetry)
  const activeKey = !deploymentHealthy
    ? 'health'
    : !hasDevice
      ? 'create'
      : !canCopyCommand
        ? 'connect'
        : !hasTelemetry
          ? 'publish'
          : !ready
            ? 'verify'
            : ''

  const steps = [
    quickstartStep({
      key: 'health',
      title: '0. 检查部署健康',
      description: deploymentHealthy
        ? '前端、API、数据库、Redis 和 MQTT Broker 已经可以支撑首台设备接入。'
        : '先确认前端、API、数据库、Redis 和 MQTT Broker 都正常，再创建或测试第一台设备。',
      status: deploymentHealthy ? 'done' : 'active',
      action: 'health',
      actionLabel: '检查部署健康',
      disabled: false
    }),
    quickstartStep({
      key: 'create',
      title: '1. 生成第一台设备',
      description: hasDevice
        ? `已找到 ${options.device?.name || options.device?.number || '第一台设备'}`
        : '一键创建产品、物模型、MQTT/HTTP 配置和第一台设备，也可以手动添加。',
      status: hasDevice ? 'done' : activeKey === 'create' ? 'active' : 'todo',
      action: 'create',
      actionLabel: hasDevice ? '定位设备信息' : '一键生成',
      disabled: !deploymentHealthy
    }),
    quickstartStep({
      key: 'connect',
      title: '2. 拿到可用连接参数',
      description: canCopyCommand
        ? '命令里已经没有占位符，可以复制到设备端或终端测试。'
        : '连接参数还不完整，请打开 Ready Check 查看缺少的端点、凭证或 topic。',
      status: canCopyCommand ? 'done' : activeKey === 'connect' ? 'active' : 'todo',
      action: canCopyCommand ? 'copy' : 'ready-check',
      actionLabel: canCopyCommand ? '复制命令' : '打开 Ready Check',
      disabled: !deploymentHealthy || !hasDevice
    }),
    quickstartStep({
      key: 'publish',
      title: '3. 发一条遥测',
      description: hasTelemetry
        ? `已收到 ${options.telemetry[0]?.key || 'telemetry'} 的最新数据。`
        : '复制命令到真实设备，或直接点浏览器在线测试发送一条测试遥测。',
      status: hasTelemetry ? 'done' : activeKey === 'publish' ? 'active' : 'todo',
      action: 'test',
      actionLabel: '浏览器在线测试',
      disabled: !canRunBrowserTest
    }),
    quickstartStep({
      key: 'verify',
      title: '4. 确认设备真的可交付',
      description: ready
        ? '设备在线且已有最新遥测，可以继续做告警、自动化和看板。'
        : '进入 Ready Check 看在线、最新遥测、命令回包和下一步修复建议。',
      status: ready ? 'done' : activeKey === 'verify' ? 'active' : 'todo',
      action: 'ready-check',
      actionLabel: '打开 Ready Check',
      disabled: !deploymentHealthy || !hasDevice
    })
  ]

  const activeStep = steps.find((step) => step.status === 'active')
  return {
    commandHasPlaceholders,
    canCopyCommand,
    canRunBrowserTest,
    summary: ready
      ? '第一台设备已跑通，可以复制这套流程给更多设备。'
      : activeStep?.description || '按步骤完成第一台设备接入。',
    nextAction: activeStep?.actionLabel || '继续下一步',
    activeStep: activeStep ?? null,
    steps
  }
}

export const buildFirstDeviceReadyProof = (options: {
  device: FirstDeviceSummary | null
  telemetry: FirstTelemetryPoint[]
  accessGuide: DeviceAccessGuideState | null
  publishCommand: string
  deploymentHealthy: boolean
  browserTest?: FirstDeviceBrowserTestState
  chart?: FirstDeviceChartState
}): FirstDeviceReadyProof => {
  const hasDevice = Boolean(options.device?.id)
  const connectionReady = Boolean(options.accessGuide?.endpoint) && !hasConnectionPlaceholder(options.publishCommand)
  const browserTestOk = options.browserTest?.status === 'confirmed'
  const online = Boolean(options.device?.online)
  const hasTelemetry = options.telemetry.length > 0
  const chart = options.chart || buildFirstDeviceChartState(options.telemetry, options.browserTest)
  const firstReportConfirmed = browserTestOk || (online && hasTelemetry && chart.ready)

  const items: FirstDeviceReadyProofItem[] = [
    {
      key: 'deployment',
      label: '部署健康',
      ok: options.deploymentHealthy,
      detail: options.deploymentHealthy
        ? '前端、API、数据库、Redis 和 MQTT 已通过健康检查。'
        : '先处理部署健康里的红色依赖。'
    },
    {
      key: 'identity',
      label: '设备身份',
      ok: hasDevice,
      detail: hasDevice
        ? `${options.device?.name || options.device?.number || '第一台设备'} 已创建。`
        : '还没有可验证的第一台设备。'
    },
    {
      key: 'connection',
      label: '连接参数',
      ok: connectionReady,
      detail: connectionReady
        ? `${options.accessGuide?.protocol || 'MQTT/HTTP'} 参数和发布命令已经可用。`
        : '连接端点、凭证或发布命令仍未完整。'
    },
    {
      key: 'browser_test',
      label: '首条上报确认',
      ok: firstReportConfirmed,
      detail: browserTestOk
        ? `${options.browserTest?.telemetryKey || 'telemetry'} = ${options.browserTest?.telemetryValue || '--'}，测试上报已被最新遥测确认。`
        : firstReportConfirmed
          ? `${options.telemetry[0]?.key || 'telemetry'} = ${options.telemetry[0]?.value || '--'}，真实设备上报已被在线状态、最新遥测和首图确认。`
          : options.browserTest?.message ||
            '点击浏览器在线测试，或让真实设备发送一条测试遥测。'
    },
    {
      key: 'online',
      label: '在线状态',
      ok: online,
      detail: online ? '设备当前在线。' : '还没有看到设备在线。'
    },
    {
      key: 'telemetry',
      label: '最新遥测',
      ok: hasTelemetry,
      detail: hasTelemetry
        ? `已收到 ${options.telemetry[0]?.key || 'telemetry'} = ${options.telemetry[0]?.value || '--'}。`
        : '还没有收到第一条遥测。'
    },
    {
      key: 'chart',
      label: '首张图表',
      ok: chart.ready,
      detail: chart.ready ? chart.summary : '先从最新遥测自动生成第一张图表，再交付给客户。'
    }
  ]
  const ready = items.every((item) => item.ok)

  return {
    ready,
    title: ready ? '设备已准备好' : '设备还没完全准备好',
    summary: ready
      ? '第一台设备已经完成部署、身份、连接、在线和遥测闭环，可以继续配置告警、自动化和看板。'
      : '按下面红色或灰色项继续处理，全部变绿后就是可交付的第一台设备。',
    items
  }
}

export const buildFirstDeviceChartProofSummary = (options: {
  device: any
  chart: Partial<FirstDeviceChartState> | null | undefined
  readyProof: Partial<FirstDeviceReadyProof> | null | undefined
}): string => {
  const chart = options.chart || {}
  const chartPoints = Array.isArray(chart.points) ? chart.points : []
  const readyProof = options.readyProof || {}
  const proofItems = Array.isArray(readyProof.items) ? readyProof.items : []

  return [
    '# AetherLink 首次接入首图证明',
    '',
    '## 设备',
    `id=${options.device?.id || '<未知>'}`,
    `name=${options.device?.name || '<未知>'}`,
    `number=${options.device?.device_number || options.device?.number || '<未知>'}`,
    `online=${Boolean(options.device?.online)}`,
    '',
    '## 首图证明',
    `ready=${Boolean(chart.ready)}`,
    `source=${chart.generatedFrom === 'browser_test' ? '浏览器在线测试' : '最新遥测'}`,
    `primary=${chart.primaryKey || 'telemetry'}=${chart.primaryValue ?? '--'}`,
    `summary=${chart.summary || '<空>'}`,
    '',
    '## 图表点位',
    chartPoints.length
      ? chartPoints.map((point: any, index: number) => `${index + 1}. ${point.key}=${point.value}`).join('\n')
      : '<暂无>',
    '',
    '## 跑通证明',
    `ready=${Boolean(readyProof.ready)}`,
    `title=${readyProof.title || '<空>'}`,
    `summary=${readyProof.summary || '<空>'}`,
    proofItems.length
      ? proofItems
          .map(
            (item: any, index: number) =>
              `${index + 1}. ${item.label}: ${item.ok ? '已通过' : '待处理'} - ${item.detail || ''}`
          )
          .join('\n')
      : '<暂无>',
    '',
    '## 证据边界',
    '此证明来自首页首次接入流程展示的在线状态、最新遥测和首图结果。若要作为发版门禁，请再结合运行时 API 或端到端验证。'
  ].join('\n')
}

export const buildFirstDeviceLatestProofText = (options: {
  device: any
  chart: Partial<FirstDeviceChartState> | null | undefined
  testResult: string
}) => {
  const chart = options.chart || {}
  if (chart.ready) {
    return `${chart.primaryKey || 'telemetry'} = ${chart.primaryValue || '--'}`
  }
  if (options.testResult) return options.testResult
  if (options.device?.online) return `${options.device.name} 当前在线`
  return '等待第一条可见遥测'
}

export const buildFirstDeviceSuccessFacts = (options: {
  device: any
  chart: Partial<FirstDeviceChartState> | null | undefined
  latestProofText: string
}) => {
  const chart = options.chart || {}

  return [
    {
      key: 'online',
      label: '在线状态',
      value: options.device?.online ? '已在线' : '未在线'
    },
    {
      key: 'latest-proof',
      label: '最新证据',
      value: options.latestProofText
    },
    {
      key: 'chart-source',
      label: '图表来源',
      value: chart.ready ? (chart.generatedFrom === 'browser_test' ? '浏览器测试确认' : '最新遥测生成') : '等待生成'
    }
  ]
}

export const buildFirstDevicePostReadyHandoff = (options: {
  ready: boolean
  nextStep?: FirstDevicePostReadyStep | null
}): FirstDevicePostReadyHandoff | null => {
  if (!options.ready) return null

  const nextStep = options.nextStep || null
  if (!nextStep) {
    return {
      title: '首台设备已准备好',
      description: '首页已经看到了在线状态、最新遥测和第一张图表；现在这套接入方式可以继续复制给更多设备。',
      primaryLabel: '查看完整接入指南',
      secondaryLabel: '定位成功证明',
      completionSignal: '完成标准：第 5 步显示“设备已准备好”，并且在线状态、最新遥测和首图都通过。',
      action: 'guide',
      section: 'proof'
    }
  }

  const title =
    nextStep.id === 'automation'
      ? '下一步：配置第一条自动化'
      : nextStep.id === 'dashboard'
        ? '下一步：创建第一个客户看板'
        : `下一步：${nextStep.title || '继续闭环'}`
  const defaultAction =
    nextStep.id === 'automation'
      ? '新建首条联动规则'
      : nextStep.id === 'dashboard'
        ? '创建客户看板'
        : nextStep.action || '继续下一步'

  return {
    title,
    description: `首台设备已跑通。现在去做「${nextStep.title || '下一步'}」：${nextStep.description || '继续把首台设备接入闭环做完整。'}`,
    primaryLabel: nextStep.action || defaultAction,
    secondaryLabel: '查看完整指南',
    completionSignal: `下一步完成标准：${nextStep.description || '完成当前交接动作，并留下可见证据。'}`,
    action: 'next-guide',
    section: 'proof'
  }
}

import {
  deviceAdd,
  deviceConfigAdd,
  deviceConfigVoucherType,
  deviceProtocolServiceList,
  deviceTemplateAdd
} from '@/service/api/device'

export type HomeFirstRunProtocol = 'MQTT' | 'HTTP'

export interface HomeFirstRunQuickCreateResult {
  templateId: string
  configId: string
  deviceId: string
  deviceName: string
  protocol: HomeFirstRunProtocol
  configName: string
}

export const HOME_FIRST_RUN_TENANT_REQUIRED_CODE = 'HOME_FIRST_RUN_TENANT_REQUIRED'

export class HomeFirstRunTenantRequiredError extends Error {
  code = HOME_FIRST_RUN_TENANT_REQUIRED_CODE

  constructor() {
    super('当前账号还没有有效租户上下文，请先创建租户管理员/租户，再生成第一台设备。')
  }
}

export function getHomeFirstRunTenantId(userInfo: Record<string, unknown> | null | undefined) {
  return String(userInfo?.tenant_id || userInfo?.tenantId || userInfo?.TenantID || '').trim()
}

export function assertHomeFirstRunTenantContext(userInfo: Record<string, unknown> | null | undefined) {
  if (!getHomeFirstRunTenantId(userInfo)) {
    throw new HomeFirstRunTenantRequiredError()
  }
}

function unwrapResponseData(response: any): any {
  if (!response) return null
  if (response.data?.id) return response.data
  if (response.data?.data?.id) return response.data.data
  if (response.id) return response
  return response.data ?? response
}

function requireCreatedId(response: any, label: string): string {
  if (response?.error) {
    throw new Error(response.error?.message || response.message || `${label} 创建失败`)
  }
  const data = unwrapResponseData(response)
  const id = data?.id
  if (typeof id !== 'string' || !id) {
    throw new Error(`${label} 创建成功但未返回 ID`)
  }
  return id
}

function buildQuickCreateSuffix() {
  const now = new Date()
  const pad = (value: number) => String(value).padStart(2, '0')
  return `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}${pad(now.getHours())}${pad(
    now.getMinutes()
  )}${pad(now.getSeconds())}`
}

function normalizeHomeFirstRunProtocol(protocol?: string): HomeFirstRunProtocol {
  return String(protocol || '').toUpperCase() === 'HTTP' ? 'HTTP' : 'MQTT'
}

function unwrapProtocolServiceList(response: any) {
  return response?.data?.data || response?.data || response || {}
}

function unwrapVoucherTypeOptions(response: any) {
  return response?.data?.data || response?.data || response || {}
}

function findHTTPServiceIdentifier(services: any[]): string {
  const service = services.find((item) => {
    const identifier = String(item?.service_identifier || item?.value || item?.id || '').trim()
    const name = String(item?.name || item?.label || '').trim()
    return /http/i.test(identifier) || /http/i.test(name)
  })
  return String(service?.service_identifier || service?.value || service?.id || '').trim()
}

function getVoucherOptionText(option: any): string {
  return [
    option?.key,
    option?.value,
    option?.label,
    option?.name,
    option?.service_identifier,
    typeof option === 'string' ? option : ''
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase()
}

function normalizeVoucherOptions(raw: any): Array<{ key: string; value: string; label: string }> {
  if (Array.isArray(raw)) {
    return raw
      .map((item) => ({
        key: String(item?.key || item?.value || item?.id || item?.name || '').trim(),
        value: String(item?.value || item?.id || item?.key || item?.name || '').trim(),
        label: String(item?.label || item?.name || item?.key || item?.value || '').trim()
      }))
      .filter((item) => item.value)
  }
  if (raw && typeof raw === 'object') {
    return Object.entries(raw)
      .map(([key, value]) => ({
        key,
        value: String(value || key).trim(),
        label: key
      }))
      .filter((item) => item.value)
  }
  return []
}

async function resolveHomeFirstRunVoucherType(protocol: HomeFirstRunProtocol, protocolType: string): Promise<string> {
  if (protocol === 'MQTT') return 'ACCESSTOKEN'

  const response = await deviceConfigVoucherType({ device_type: '1', protocol_type: protocolType })
  const options = normalizeVoucherOptions(unwrapVoucherTypeOptions(response))
  const preferred = options.find((option) => /access|token|bearer/i.test(getVoucherOptionText(option)))
  const selected = preferred || options[0]
  if (!selected?.value) {
    throw new Error('HTTP 接入服务没有返回可用凭证类型。请先完善 HTTP 服务/协议插件配置，或先选择 MQTT 生成第一台设备。')
  }
  return selected.value
}

async function resolveHomeFirstRunDeviceProtocol(protocol: HomeFirstRunProtocol): Promise<string> {
  if (protocol === 'MQTT') return 'MQTT'

  const response = await deviceProtocolServiceList({ device_type: '1' })
  const data = unwrapProtocolServiceList(response)
  const serviceIdentifier = findHTTPServiceIdentifier(Array.isArray(data.service) ? data.service : [])
  if (!serviceIdentifier) {
    throw new Error('没有找到可用的 HTTP 接入服务。请先在服务/协议插件里配置 HTTP 服务，或先选择 MQTT 生成第一台设备。')
  }
  return serviceIdentifier
}

export async function createHomeFirstRunFirstDevice(
  options: { userInfo?: Record<string, unknown> | null; protocol?: HomeFirstRunProtocol } = {}
): Promise<HomeFirstRunQuickCreateResult> {
  assertHomeFirstRunTenantContext(options.userInfo)

  const protocol = normalizeHomeFirstRunProtocol(options.protocol)
  const protocolType = await resolveHomeFirstRunDeviceProtocol(protocol)
  const voucherType = await resolveHomeFirstRunVoucherType(protocol, protocolType)
  const suffix = buildQuickCreateSuffix()
  const templateName = `首台设备物模型 ${suffix}`
  const configName = `首台设备 ${protocol} 配置 ${suffix}`
  const deviceName = `第一台设备 ${suffix}`

  const templateResult = await deviceTemplateAdd({
    name: templateName,
    author: 'AetherLink',
    version: '1.0.0',
    label: 'first-device',
    description: '首页首次接入向导自动创建的默认物模型'
  })
  const templateId = requireCreatedId(templateResult, '物模型')

  const configResult = await deviceConfigAdd({
    name: configName,
    device_template_id: templateId,
    device_type: '1',
    device_conn_type: 'A',
    protocol_type: protocolType,
    voucher_type: voucherType,
    protocol_config: '{}',
    additional_info: JSON.stringify({
      source: 'home_first_run_quick_create',
      preferred_protocol: protocol,
      resolved_protocol_type: protocolType,
      resolved_voucher_type: voucherType,
      created_at: new Date().toISOString()
    }),
    description: `首页首次接入向导自动创建的 ${protocol} 直连设备配置`
  })
  const configId = requireCreatedId(configResult, '设备配置')

  const deviceResult = await deviceAdd({
    name: deviceName,
    device_number: `FIRST-${suffix}`,
    device_config_id: configId,
    access_way: 'A',
    protocol,
    label: 'first-device',
    description: '首页首次接入向导自动创建的第一台设备'
  })
  const deviceId = requireCreatedId(deviceResult, '设备')

  return {
    templateId,
    configId,
    deviceId,
    deviceName,
    protocol,
    configName
  }
}

﻿<!--
文件用途：承载首页和第一台设备接入控制台的页面级视图。
核心逻辑：组合首次接入向导、设备状态、可视化仪表盘、接口请求和国际化文案，完成页面初始化、查询与交互反馈。
关键注意事项：页面通常依赖权限、分页、远端接口和路由状态，改动时需同步检查测试与接口契约。
重构建议：租户引导、后台探测、workbench 门控与客户引导动作已拆分至同目录 composable，新增逻辑优先沉淀到对应模块。
-->
<script setup lang="ts">
import { computed, defineAsyncComponent, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { router } from '@/router'
import { $t } from '@/locales'
import { useAuthStore } from '@/store/modules/auth'
import { isSysAdminUser } from '@/utils/thingsvis/space'
import { createHomeGuideRefreshCoordinator } from './homeGuideRefreshCoordinator'
