          <n-button
            type="primary"
            @click="
              () => {
                router.push(homeVisualizationPath)
              }
            "
          >
            {{ sysAdminSetupAction }}
          </n-button>
          <n-button
            @click="
              () => {
                router.go(0)
              }
            "
          >
            {{ $t('custom.home.actions.reload') }}
