const unwrapConnectionGuideResponse = (response: any) => {
  if (response?.error) return null
  return response?.data?.data ?? response?.data ?? response ?? null
}

const hasUsableConnectionGuideAccess = (guide: any) => {
  if (!guide || typeof guide !== 'object') return false
  const access = guide.access
  if (!access || typeof access !== 'object') return false
  return Boolean(access.connection_profile || access.connection_info || access.credential_form)
}

const telemetryTimestampIsAfter = (timestamp: string | undefined, sentAt: string) => {
  if (!timestamp) return false
  const telemetryTime = Date.parse(timestamp)
  const sentTime = Date.parse(sentAt)
  return Number.isFinite(telemetryTime) && Number.isFinite(sentTime) && telemetryTime >= sentTime - 1000
}

const buildTelemetrySignature = (telemetry: FirstTelemetryPoint[]) =>
  telemetry.map((point) => `${point.key}:${point.value}:${point.ts || ''}`).join('|')

const BROWSER_TEST_CONFIRM_ATTEMPTS = 5
const BROWSER_TEST_CONFIRM_INTERVAL_MS = 1200

const waitForBrowserTestConfirmation = () =>
  new Promise((resolve) => {
    window.setTimeout(resolve, BROWSER_TEST_CONFIRM_INTERVAL_MS)
  })

const findConfirmedBrowserTelemetry = (
  telemetry: FirstTelemetryPoint[],
  options: {
    sentAt: string
    previousSignature: string
  }
) => {
  const latestTelemetry = telemetry[0]
  if (!latestTelemetry) return null
  if (telemetryTimestampIsAfter(latestTelemetry.ts, options.sentAt)) return latestTelemetry
  if (!latestTelemetry.ts && buildTelemetrySignature(telemetry) !== options.previousSignature) return latestTelemetry
  return null
}

export function useHomeFirstDeviceWorkbench(options: UseHomeFirstDeviceWorkbenchOptions) {
  const loading = ref(false)
  const device = ref<FirstDeviceSummary | null>(null)
  const telemetry = ref<FirstTelemetryPoint[]>([])
  const simulation = ref<SimulationInitState | null>(null)
  const accessGuide = ref<DeviceAccessGuideState | null>(null)
  const diagnostics = ref<DeviceAccessGuideDiagnosticsSummary>({})
  const actionLoading = ref(false)
  const testResult = ref('')
  const browserTest = ref<FirstDeviceBrowserTestState>(createIdleFirstDeviceBrowserTestState())
  let refreshPromise: Promise<void> | null = null

  const ready = computed(() => isFirstDeviceReady(device.value, telemetry.value))
  const firstChart = computed(() => buildFirstDeviceChartState(telemetry.value, browserTest.value))
  const publishCommand = computed(
    () => accessGuide.value?.commands?.[0]?.code || (simulation.value ? buildPublishCommand(simulation.value) : '')
  )
  const onboardingGuard = computed(() =>
    buildFirstDeviceOnboardingGuard({
      device: device.value,
      telemetry: telemetry.value,
      accessGuide: accessGuide.value,
      publishCommand: publishCommand.value,
      actionLoading: actionLoading.value,
      deploymentHealthy: options.deploymentHealthy.value
    })
  )
  const readyProof = computed(() =>
    buildFirstDeviceReadyProof({
      device: device.value,
      telemetry: telemetry.value,
      accessGuide: accessGuide.value,
      publishCommand: publishCommand.value,
      deploymentHealthy: options.deploymentHealthy.value,
      browserTest: browserTest.value,
      chart: firstChart.value
    })
  )
  const buildSupportSummary = (summaryOptions: {
    latestProofText: string
    activeTestCommand?: FirstDeviceSupportTestCommand | null
    delivery?: {
      firstDeviceUrl?: string
      proofUrl?: string
      proofFileHint?: string
    }
  }) =>
    buildFirstDeviceSupportSummary({
      device: device.value,
      accessGuide: accessGuide.value,
      diagnostics: diagnostics.value,
      simulation: simulation.value,
      readyProof: readyProof.value,
      latestProofText: summaryOptions.latestProofText,
      browserTest: browserTest.value,
      testResult: testResult.value,
      chart: firstChart.value,
      activeTestCommand: summaryOptions.activeTestCommand,
      onboardingGuard: onboardingGuard.value,
      deploymentHealthRows: options.deploymentHealthRows?.value || [],
      delivery: summaryOptions.delivery
    })

  const resetDeviceDetails = (resetBrowserTest = false) => {
    telemetry.value = []
    simulation.value = null
    accessGuide.value = null
    diagnostics.value = {}
    testResult.value = ''
    if (resetBrowserTest) {
      browserTest.value = createIdleFirstDeviceBrowserTestState()
    }
  }

  const loadConnectionGuide = async (currentDevice: FirstDeviceSummary) => {
    try {
      const response = await getDeviceConnectionGuide(currentDevice.id, { debug_log_limit: 3, command_log_limit: 3 })
      const guide = unwrapConnectionGuideResponse(response)
      if (!hasUsableConnectionGuideAccess(guide)) return false
      diagnostics.value = {}
      accessGuide.value = buildDeviceAccessGuideStateFromConnectionGuide(guide, currentDevice.number)
      return true
    } catch {
      return false
    }
  }

  const loadCompatConnectionInfo = async (currentDevice: FirstDeviceSummary) => {
    const [connectInfoResult, diagnosticsResult] = await Promise.all([
      getDeviceConnectInfo({ device_id: currentDevice.id }),
      getDeviceConnectionDiagnostics(currentDevice.id, { debug_log_limit: 3 }).catch(() => ({}))
    ])
    diagnostics.value = summarizeFirstDeviceConnectionDiagnostics(diagnosticsResult)
    accessGuide.value = buildDeviceAccessGuideState(
      connectInfoResult?.data || {},
      currentDevice.number,
      {},
      diagnostics.value
    )
  }

  const runRefresh = async () => {
    loading.value = true
    try {
      const previousDeviceId = device.value?.id || ''
      const listResult = await deviceList({ page: 1, page_size: 1 })
      const currentDevice = normalizeFirstDevice(listResult)
      device.value = currentDevice
      resetDeviceDetails(!currentDevice || Boolean(previousDeviceId && previousDeviceId !== currentDevice.id))

      if (!currentDevice) return

      const [telemetryResult, simulationResult, guideLoaded] = await Promise.all([
        telemetryDataCurrent(currentDevice.id, { silentError: true }),
        getSimulationInit({ device_id: currentDevice.id }),
        loadConnectionGuide(currentDevice)
      ])
      telemetry.value = normalizeTelemetryPoints(telemetryResult)
      simulation.value = normalizeSimulationInit(simulationResult)
      if (!guideLoaded) {
        await loadCompatConnectionInfo(currentDevice)
      }
    } catch {
      device.value = null
      resetDeviceDetails(true)
    } finally {
      loading.value = false
    }
  }

  const refresh = () => {
    if (refreshPromise) return refreshPromise

    refreshPromise = runRefresh().finally(() => {
      refreshPromise = null
    })

    return refreshPromise
  }

  const openReadyCheck = () => {
    if (!device.value) {
      router.push('/device/manage')
      return
    }
    router.push({
      path: '/device/details',
      query: {
        d_id: device.value.id,
        tab: 'ready-check',
        onboarding: 'first-device'
      }
    })
  }

  const openFullGuide = () => {
    if (!device.value) {
      router.push('/device/manage?onboarding=first-device&add=manual')
      return
    }
    router.push({
      path: '/device/details',
      query: {
        d_id: device.value.id,
        tab: 'join',
        onboarding: 'first-device'
      }
    })
  }

  const copyPublishCommand = async () => {
    if (!onboardingGuard.value.canCopyCommand) {
      window.$message?.warning(onboardingGuard.value.summary)
      return
    }
    const copied = await writeClipboardText(publishCommand.value)
    if (copied) {
      window.$message?.success($t('theme.configOperation.copySuccess'))
    } else {
      window.$message?.error($t('common.copyFailed'))
    }
  }

  const runHttpTelemetryTest = async (currentAccessGuide: DeviceAccessGuideState) => {
    if (!isUsableHttpEndpoint(currentAccessGuide.endpoint)) {
      window.$message?.warning($t('custom.home.browserTest.httpEndpointUnavailable'))
      return false
    }
    try {
      const request = buildHttpTelemetryRequest({
        endpoint: currentAccessGuide.endpoint,
        token: currentAccessGuide.username || currentAccessGuide.password,
        payload: currentAccessGuide.payload
      })
      const response = await fetch(request.url, request.init)
      if (!response.ok) {
        throw new Error($t('custom.home.browserTest.httpReportFailed', { status: response.status }))
      }
    } catch (error: any) {
      window.$message?.error(error?.message || $t('custom.home.browserTest.httpRequestFailed'))
      return false
    }
    return true
  }

  const confirmBrowserTelemetryTest = async (sentAt: string, sentMessage: string, previousSignature: string) => {
    browserTest.value = buildFirstDeviceBrowserTestState({
      status: 'sent',
      message: sentMessage,
      sentAt
    })
    testResult.value = sentMessage
    let latestTelemetry: FirstTelemetryPoint | null = null
    for (let attempt = 1; attempt <= BROWSER_TEST_CONFIRM_ATTEMPTS; attempt += 1) {
      if (attempt > 1) {
        await waitForBrowserTestConfirmation()
      }
      browserTest.value = buildFirstDeviceBrowserTestState({
        status: 'sent',
        message: $t('custom.home.browserTest.confirmProgress', { sentMessage, attempt, total: BROWSER_TEST_CONFIRM_ATTEMPTS }),
        sentAt
      })
      testResult.value = browserTest.value.message
      await refresh()
      latestTelemetry = findConfirmedBrowserTelemetry(telemetry.value, {
        sentAt,
        previousSignature
      })
      if (latestTelemetry) {
        browserTest.value = buildFirstDeviceBrowserTestState({
          status: 'confirmed',
          telemetry: latestTelemetry,
          sentAt
        })
        testResult.value = browserTest.value.message
        return
      }
    }
    browserTest.value = buildFirstDeviceBrowserTestState({
      status: 'sent',
      message: $t('custom.home.browserTest.confirmTimeout', { total: BROWSER_TEST_CONFIRM_ATTEMPTS }),
      sentAt
    })
    testResult.value = browserTest.value.message
  }

  const simulateTelemetry = async () => {
    if (!device.value) {
      router.push('/device/manage')
      return
    }
    if (!onboardingGuard.value.canRunBrowserTest) {
      window.$message?.warning(onboardingGuard.value.summary)
      return
    }

    actionLoading.value = true
    testResult.value = ''
    const sentAt = new Date().toISOString()
    const previousTelemetrySignature = buildTelemetrySignature(telemetry.value)
    browserTest.value = buildFirstDeviceBrowserTestState({ status: 'sending', sentAt })
    try {
      if (accessGuide.value?.endpointKind === 'http') {
        const sent = await runHttpTelemetryTest(accessGuide.value)
        if (!sent) {
          browserTest.value = buildFirstDeviceBrowserTestState({
            status: 'failed',
            message: $t('custom.home.browserTest.httpRequestFailed'),
            sentAt
          })
          testResult.value = browserTest.value.message
          return
        }
        const message = $t('custom.home.browserTest.httpRequestSent')
        window.$message?.success(message)
        await confirmBrowserTelemetryTest(sentAt, message, previousTelemetrySignature)
        return
      }

      if (!simulation.value) {
        browserTest.value = buildFirstDeviceBrowserTestState({
          status: 'failed',
          message: $t('custom.home.browserTest.simulationNotReady'),
          sentAt
        })
        testResult.value = browserTest.value.message
        router.push('/device/manage')
        return
      }

      const { error } = await sendSimulationData({
        device_id: device.value.id,
        data: simulation.value.payload,
        server: simulation.value.server,
        port: simulation.value.port,
        topic: simulation.value.topic
      })
      if (error) {
        browserTest.value = buildFirstDeviceBrowserTestState({
          status: 'failed',
          message: error?.message || $t('custom.home.browserTest.simulationFailed'),
          sentAt
        })
        testResult.value = browserTest.value.message
        window.$message?.error(testResult.value)
        return
      }
      const message = $t('custom.home.browserTest.mqttRequestSent')
      window.$message?.success(message)
      await confirmBrowserTelemetryTest(sentAt, message, previousTelemetrySignature)
    } catch (error: any) {
      if (error?.code === HOME_FIRST_RUN_TENANT_REQUIRED_CODE) {
        options.onTenantRequired?.()
      }
      browserTest.value = buildFirstDeviceBrowserTestState({
        status: 'failed',
        message: error?.message || $t('custom.home.browserTest.failed'),
        sentAt
      })
      testResult.value = browserTest.value.message
      window.$message?.error(testResult.value)
    } finally {
      actionLoading.value = false
    }
  }

  const runQuickstartAction = (
    action: FirstDeviceQuickstartAction | string,
    createDevice: () => void | Promise<void>
  ) => {
    if (action === 'copy') {
      void copyPublishCommand()
      return
    }
    if (action === 'test') {
      void simulateTelemetry()
      return
    }
    if (action === 'ready-check') {
      openReadyCheck()
      return
    }
    void createDevice()
  }

  return {
    loading,
    device,
    telemetry,
    simulation,
    accessGuide,
    diagnostics,
    actionLoading,
    testResult,
    browserTest,
    firstChart,
    ready,
    publishCommand,
    onboardingGuard,
    readyProof,
    refresh,
    openReadyCheck,
    openFullGuide,
    copyPublishCommand,
    simulateTelemetry,
    runQuickstartAction,
    buildSupportSummary
  }
}

// 文件用途：承载首页引导相关的后台探测状态（部署健康、场景自动化）。
// 核心逻辑：各自维护加载态与在途请求去重，为客户引导进度提供健康与自动化判定输入。
// 关键注意事项：探测失败时回退为不可用默认值，不阻断页面主链路。
import { computed, ref } from 'vue'
import { sceneAutomationsGet } from '@/service/api/automation'
import { $t } from '@/locales'
import {
  fetchDeploymentHealthReport,
  normalizeDeploymentHealth,
  type DeploymentHealthReport
} from './homeDeploymentHealth'

const unwrapListResponse = (response: any): any[] => {
  const data = response?.data?.data ?? response?.data ?? response ?? {}
  const list = data?.list ?? data?.records ?? data?.data ?? []
  return Array.isArray(list) ? list : []
}

export function useHomeGuideProbes() {
  let deploymentHealthRefreshPromise: Promise<void> | null = null
  let automationGuideRefreshPromise: Promise<void> | null = null

  const deploymentHealthLoading = ref(false)
  const deploymentHealth = ref<DeploymentHealthReport | null>(null)
  const deploymentHealthRows = computed(() => normalizeDeploymentHealth(deploymentHealth.value, $t))
  const deploymentHealthOk = computed(
    () =>
      deploymentHealth.value?.status === 'ok' &&
      deploymentHealthRows.value.length > 0 &&
      deploymentHealthRows.value.every((row) => row.ok)
  )

  const refreshDeploymentHealth = () => {
    if (deploymentHealthRefreshPromise) return deploymentHealthRefreshPromise

    deploymentHealthLoading.value = true
    deploymentHealthRefreshPromise = fetchDeploymentHealthReport($t)
      .then((report) => {
        deploymentHealth.value = report
      })
      .finally(() => {
        deploymentHealthLoading.value = false
        deploymentHealthRefreshPromise = null
      })

    return deploymentHealthRefreshPromise
  }

  const automationGuideLoading = ref(false)
  const hasSceneAutomation = ref(false)

  const refreshAutomationGuideState = () => {
    if (automationGuideRefreshPromise) return automationGuideRefreshPromise

    automationGuideLoading.value = true
    automationGuideRefreshPromise = sceneAutomationsGet({ page: 1, page_size: 1 })
      .then((response) => {
        hasSceneAutomation.value = unwrapListResponse(response).length > 0
      })
      .catch(() => {
        hasSceneAutomation.value = false
      })
      .finally(() => {
        automationGuideLoading.value = false
        automationGuideRefreshPromise = null
      })

    return automationGuideRefreshPromise
  }

  return {
    deploymentHealthLoading,
    deploymentHealthRows,
    deploymentHealthOk,
    refreshDeploymentHealth,
    automationGuideLoading,
    hasSceneAutomation,
    refreshAutomationGuideState
  }
}

// 文件用途：承载首页布局解析编排（ThingsVis 仪表盘探测、兼容首页配置与超管初始化分支）。
// 核心逻辑：从 home/index.vue 抽出的数据编排层，负责缓存读取、预算内加载、后台刷新与状态回写。
// 关键注意事项：对外仅暴露与原页面同名同语义的状态与方法，调用方需注入鉴权与租户上下文。
import { computed, ref, type Ref } from 'vue'
import { normalizeLocalDashboard } from '@/components/local-visualization-viewer'
import { fetchCompatHomeConfig } from '@/service/api'
import {
  loadVisualizationHomeDashboard,
  probeVisualizationHomeDashboard,
  type VisualizationHomeDashboard,
  type VisualizationHomeLoadResult
} from '@/service/visualization-provider/home-dashboard'
import { $t } from '@/locales'
import { clearThingsVisHomeCache, readThingsVisHomeCache, writeThingsVisHomeCache } from '@/utils/thingsvis/home-cache'
import { NATIVE_BOARD_PROVIDER_ID } from '@/service/visualization-provider/provider-ids'
import { useViewportDeferredMount } from './useViewportDeferredMount'

export const isNativeHomeProvider = import.meta.env.VITE_ENABLE_THINGSVIS_COMPAT !== 'Y'

export function isCompleteThingsVisDashboard(dashboard?: VisualizationHomeDashboard | null): boolean {
  if (!dashboard || !dashboard.canvasConfig || typeof dashboard.canvasConfig !== 'object') return false

  if (dashboard.providerId === NATIVE_BOARD_PROVIDER_ID) {
    return normalizeLocalDashboard(dashboard.rendererData).ok
  }

  if (!Array.isArray(dashboard.nodes) || dashboard.nodes.length === 0) return false
  if (!Array.isArray(dashboard.dataSources) || dashboard.dataSources.length === 0) return false
  return true
}

type UseHomeLayoutResolverOptions = {
  isSysAdmin: Readonly<Ref<boolean>>
  nativeTenantId: Readonly<Ref<string>>
  hasNativeHomeTenantContext: Readonly<Ref<boolean>>
  shouldShowSecondarySections: Readonly<Ref<boolean>>
  scheduleIdleTask: (task: () => void, fallbackDelay?: number) => void
}

export function useHomeLayoutResolver(options: UseHomeLayoutResolverOptions) {
  const {
    isSysAdmin,
    nativeTenantId,
    hasNativeHomeTenantContext,
    shouldShowSecondarySections,
    scheduleIdleTask
  } = options

  const layoutFetched = ref(false)
  const hasCompatHomeConfig = ref(false)
  const compatHomeConfigCount = ref(0)
  const isError = ref<boolean>(false)
  const showSysAdminSetup = ref(false)

  // ThingsVis 首页相关
  const thingsVisHome = ref<VisualizationHomeDashboard | null>(null)
  const useThingsVis = ref(false)
  const isThingsVisLoading = ref(false)
  const homeThingsVisSectionRef = ref<HTMLElement | null>(null)
  const homeThingsVisFrameMount = useViewportDeferredMount(homeThingsVisSectionRef, {
    rootMargin: '360px 0px',
    fallbackDelay: 600
  })
  const shouldMountHomeThingsVisFrame = homeThingsVisFrameMount.shouldMount
  const showCompatHomeNotice = computed(() => !useThingsVis.value && layoutFetched.value && hasCompatHomeConfig.value)
  const isHomeResolving = computed(() => !layoutFetched.value || isThingsVisLoading.value)

  const nativeTenantContextRequired = ref(false)
  const homeDashboardUnavailable = ref(false)
  const sysAdminSetupTitle = computed(() => {
    if (nativeTenantContextRequired.value) return $t('custom.home.sysAdminSetup.nativeTenantContextTitle')
    if (homeDashboardUnavailable.value) {
      return $t(
        isNativeHomeProvider
          ? 'custom.home.sysAdminSetup.nativeUnavailableTitle'
          : 'custom.home.sysAdminSetup.unavailableTitle'
      )
    }
    return $t('custom.home.sysAdminSetup.missingDashboardTitle')
  })
  const sysAdminSetupDescription = computed(() => {
    if (nativeTenantContextRequired.value) return $t('custom.home.sysAdminSetup.nativeTenantContextDescription')
    if (homeDashboardUnavailable.value) {
      return $t(
        isNativeHomeProvider
          ? 'custom.home.sysAdminSetup.nativeUnavailableDescription'
          : 'custom.home.sysAdminSetup.unavailableDescription'
      )
    }
    return $t('custom.home.sysAdminSetup.missingDashboardDescription')
  })

  // ThingsVis 请求失败时的重试状态（针对超管首次登录场景）
  const thingsVisRetryCount = ref(0)
  const MAX_THINGSVIS_RETRY = 5 // 增加到 5 次重试
  const THINGSVIS_HOME_DASHBOARD_BUDGET_MS = 1800

  const homeResolvingDescription = computed(() => {
    if (thingsVisRetryCount.value > 0) {
      return $t('custom.home.resolvingRetryDescription', { count: thingsVisRetryCount.value })
    }

    if (isThingsVisLoading.value) {
      return $t('custom.home.resolvingThingsVisDescription')
    }

    return $t('custom.home.resolvingDescription')
  })

  const parseCompatHomeConfigCount = (config: unknown): number => {
    if (Array.isArray(config)) return config.length
    if (config && typeof config === 'object' && Array.isArray((config as { layout?: unknown[] }).layout)) {
      return (config as { layout: unknown[] }).layout.length
    }
    return 0
  }

  const loadCompatHomeState = async () => {
    const { data, error } = await fetchCompatHomeConfig({})

    if (error || !data?.config) {
      isError.value = Boolean(error)
      hasCompatHomeConfig.value = false
      compatHomeConfigCount.value = 0
      layoutFetched.value = true
      return
    }

    try {
      const configJson = JSON.parse(data.config)
      compatHomeConfigCount.value = parseCompatHomeConfigCount(configJson)
      hasCompatHomeConfig.value = compatHomeConfigCount.value > 0
      isError.value = false
    } catch {
      isError.value = true
      hasCompatHomeConfig.value = false
      compatHomeConfigCount.value = 0
    }
    layoutFetched.value = true
  }

  const loadThingsVisHomeDashboardWithBudget = async (
    fallbackDashboard: VisualizationHomeDashboard | null,
    budgetMs = THINGSVIS_HOME_DASHBOARD_BUDGET_MS,
    tenantId?: string
  ) : Promise<VisualizationHomeLoadResult & { timedOut?: boolean }> => {
    if (fallbackDashboard) {
      return { ok: true, data: fallbackDashboard, timedOut: false }
    }

    let timeoutId: ReturnType<typeof setTimeout> | undefined
    const dashboardRequest = loadVisualizationHomeDashboard(tenantId ? { tenantId } : undefined)
    const timeoutRequest = new Promise<{ result: VisualizationHomeLoadResult; timedOut: true }>((resolve) => {
      timeoutId = setTimeout(() => resolve({ result: { ok: true, data: null }, timedOut: true }), budgetMs)
    })

    const result = await Promise.race([
      dashboardRequest.then((result) => ({ result, timedOut: false as const })),
      timeoutRequest
    ])
    if (timeoutId) clearTimeout(timeoutId)
    if (result.timedOut && !isSysAdmin.value) {
      void dashboardRequest
        .then((lateResult) => {
          const dashboard = lateResult.ok ? lateResult.data : null
          if (lateResult.ok && isCompleteThingsVisDashboard(dashboard)) {
            writeThingsVisHomeCache('thingsvis', dashboard)
          }
        })
        .catch(() => {})
    }
    return { ...result.result, timedOut: result.timedOut }
  }

  const refreshThingsVisHomeDashboardInBackground = async () => {
    if (isSysAdmin.value) return
    try {
      const probe = await probeVisualizationHomeDashboard()
      if (!probe.reachable) return
      const result = probe.dashboard
        ? { ok: true as const, data: probe.dashboard }
        : await loadThingsVisHomeDashboardWithBudget(null, THINGSVIS_HOME_DASHBOARD_BUDGET_MS)
      if ('timedOut' in result && result.timedOut) return

      const dashboard = result.ok ? result.data : null
      if (result.ok && isCompleteThingsVisDashboard(dashboard)) {
        thingsVisHome.value = dashboard
        useThingsVis.value = true
        thingsVisRetryCount.value = 0
        writeThingsVisHomeCache('thingsvis', dashboard)
        return
      }

      const resultStatus = result.ok === false ? result.error.status : undefined
      if (!dashboard && (result.ok || resultStatus === 404)) {
        writeThingsVisHomeCache('classic')
      }
    } catch {
      // Keep the current homepage fallback usable when ThingsVis is slow or unavailable.
    }
  }

  let layoutLoadPromise: Promise<void> | null = null

  const resolveHomeLayout = async (retryCount = 0): Promise<void> => {
    isError.value = false
    showSysAdminSetup.value = false
    useThingsVis.value = false
    thingsVisHome.value = null
    nativeTenantContextRequired.value = false
    homeDashboardUnavailable.value = false
    layoutFetched.value = false
    hasCompatHomeConfig.value = false
    compatHomeConfigCount.value = 0

    // Native home boards are tenant-scoped. SYS_ADMIN must select the target
    // tenant from Native boards before this page can read or modify a board;
    // never infer a tenant from the first available record.
    if (isNativeHomeProvider && isSysAdmin.value && !hasNativeHomeTenantContext.value) {
      nativeTenantContextRequired.value = true
      showSysAdminSetup.value = true
      layoutFetched.value = true
      return
    }

    const cachedHome = readThingsVisHomeCache()
    if (!isNativeHomeProvider && cachedHome?.state === 'thingsvis' && isCompleteThingsVisDashboard(cachedHome.dashboard)) {
      thingsVisHome.value = cachedHome.dashboard ?? null
      useThingsVis.value = true
      layoutFetched.value = true
      return
    }
    if (cachedHome?.state === 'thingsvis') {
      clearThingsVisHomeCache()
    }

    if (cachedHome?.state === 'sysadmin-setup' && isSysAdmin.value) {
      showSysAdminSetup.value = true
      layoutFetched.value = true
      return
    }

    if (cachedHome?.state === 'classic' && !isSysAdmin.value) {
      await loadCompatHomeState()
      scheduleIdleTask(() => {
        void refreshThingsVisHomeDashboardInBackground()
      }, 300)
      return
    }

    if (!isSysAdmin.value) {
      await loadCompatHomeState()
      scheduleIdleTask(() => {
        void refreshThingsVisHomeDashboardInBackground()
      }, 300)
      return
    }

    const thingsVisProbe = await probeVisualizationHomeDashboard(
      nativeTenantId.value ? { tenantId: nativeTenantId.value } : undefined
    )
    if (!thingsVisProbe.reachable) {
      homeDashboardUnavailable.value = true

      if (isSysAdmin.value) {
        showSysAdminSetup.value = true
        layoutFetched.value = true
        return
      }

      if (isSysAdmin.value) {
        writeThingsVisHomeCache('classic')
      }
      await loadCompatHomeState()
      return
    }

    // 先检查 ThingsVis 是否有首页的仪表盘
    try {
      isThingsVisLoading.value = true
      const thingsVisResult = thingsVisProbe.dashboard
        ? { ok: true as const, data: thingsVisProbe.dashboard }
        : await loadThingsVisHomeDashboardWithBudget(null, THINGSVIS_HOME_DASHBOARD_BUDGET_MS, nativeTenantId.value)
      isThingsVisLoading.value = false
      if ('timedOut' in thingsVisResult && thingsVisResult.timedOut) {
        if (isSysAdmin.value) {
          showSysAdminSetup.value = true
          layoutFetched.value = true
          return
        }
        await loadCompatHomeState()
        return
      }
      const homeNotConfigured = thingsVisResult.ok ? !thingsVisResult.data : thingsVisResult.error.status === 404
      const dashboard = thingsVisResult.ok ? thingsVisResult.data : null
      if (thingsVisResult.ok && dashboard) {
        thingsVisHome.value = dashboard
        useThingsVis.value = true
        layoutFetched.value = true
        thingsVisRetryCount.value = 0
        writeThingsVisHomeCache('thingsvis', dashboard)
        return
      }

      // ThingsVis 请求成功但没有数据，可能是首次登录看板尚未创建
      // 等待一下再重试
      if (homeNotConfigured && isSysAdmin.value && retryCount < MAX_THINGSVIS_RETRY) {
        thingsVisRetryCount.value = retryCount + 1
        await new Promise((resolve) => setTimeout(resolve, 500 * (retryCount + 1)))
        return resolveHomeLayout(retryCount + 1)
      }

      if (isSysAdmin.value) {
        if (!homeNotConfigured && !thingsVisResult.ok) {
          isError.value = true
          layoutFetched.value = true
          return
        }

        showSysAdminSetup.value = true
        layoutFetched.value = true
        thingsVisRetryCount.value = 0
        writeThingsVisHomeCache('sysadmin-setup')
        return
      }

      if (homeNotConfigured) {
        writeThingsVisHomeCache('classic')
      }
    } catch (e) {
      // ThingsVis 服务不可用，继续使用现有首页兜底
      isThingsVisLoading.value = false
      homeDashboardUnavailable.value = true
      if (isSysAdmin.value) {
        showSysAdminSetup.value = true
        layoutFetched.value = true
        return
      }
    }

    // 使用轻量兼容首页提示，避免再走已退场的 classic card 渲染链
    await loadCompatHomeState()
  }

  const getLayout = async () => {
    if (layoutLoadPromise) return layoutLoadPromise

    const currentLoad = resolveHomeLayout().finally(() => {
      if (layoutLoadPromise === currentLoad) {
        layoutLoadPromise = null
      }
    })
    layoutLoadPromise = currentLoad
    return currentLoad
  }

  const mountHomeThingsVisFrame = () => {
    if (!useThingsVis.value || !thingsVisHome.value) return
    homeThingsVisFrameMount.mountNow()
  }

  const resetHomeThingsVisFrame = () => {
    homeThingsVisFrameMount.reset()
  }

  const observeHomeThingsVisFrame = async () => {
    if (!shouldShowSecondarySections.value || !useThingsVis.value || !thingsVisHome.value) {
      homeThingsVisFrameMount.reset()
      return
    }

    if (shouldMountHomeThingsVisFrame.value) return
    await homeThingsVisFrameMount.observe()
  }

  return {
    layoutFetched,
    hasCompatHomeConfig,
    compatHomeConfigCount,
    isError,
    showSysAdminSetup,
    thingsVisHome,
    useThingsVis,
    nativeTenantContextRequired,
    homeDashboardUnavailable,
    showCompatHomeNotice,
    isHomeResolving,
    sysAdminSetupTitle,
    sysAdminSetupDescription,
    homeResolvingDescription,
    homeThingsVisSectionRef,
    shouldMountHomeThingsVisFrame,
    mountHomeThingsVisFrame,
    resetHomeThingsVisFrame,
    observeHomeThingsVisFrame,
    refreshThingsVisHomeDashboardInBackground,
    getLayout
  }
}

// 文件用途：承载租户初始化状态拉取与首页安装引导步骤推导。
// 核心逻辑：带在途去重地获取租户初始化状态，推导下一步动作、就绪判定与引导卡片内容。
// 关键注意事项：引导步骤的文案与路由是页面对外契约，调整需同步客户引导进度与测试。
import { computed, ref, type ComputedRef } from 'vue'
import { fetchTenantSetupState } from '@/service/api/auth'
import { $t } from '@/locales'

export type TenantSetupNextStep = 'create_super_admin' | 'create_tenant_admin' | 'login'

export type TenantSetupState = {
  has_admin: boolean
  has_tenant_admin?: boolean
  has_tenant?: boolean
  entry: 'login' | 'register'
  next_step?: TenantSetupNextStep
  market_base_url?: string
  market_register_url?: string
}

export const defaultTenantSetupState = (): TenantSetupState => ({
  has_admin: true,
  has_tenant_admin: true,
  has_tenant: true,
  entry: 'login',
  next_step: 'login'
})

type UseHomeTenantSetupGuideOptions = {
  hasFirstRunTenantContext: ComputedRef<boolean>
}

export function useHomeTenantSetupGuide(options: UseHomeTenantSetupGuideOptions) {
  let tenantSetupGuideStateRefreshPromise: Promise<void> | null = null

  const tenantSetupState = ref<TenantSetupState>(defaultTenantSetupState())

  const refreshTenantSetupGuideState = () => {
    if (tenantSetupGuideStateRefreshPromise) return tenantSetupGuideStateRefreshPromise

    tenantSetupGuideStateRefreshPromise = fetchTenantSetupState()
      .then((response) => {
        tenantSetupState.value = response.data ?? defaultTenantSetupState()
      })
      .catch(() => {
        tenantSetupState.value = defaultTenantSetupState()
      })
      .finally(() => {
        tenantSetupGuideStateRefreshPromise = null
      })

    return tenantSetupGuideStateRefreshPromise
  }

  const tenantSetupNextStep = computed<TenantSetupNextStep>(() => {
    if (!tenantSetupState.value?.has_admin) return 'create_super_admin'
    return tenantSetupState.value?.next_step || 'login'
  })

  const homeSetupReady = computed(
    () => tenantSetupNextStep.value === 'login' && options.hasFirstRunTenantContext.value
  )

  const homeSetupGuideStep = computed(() => {
    if (tenantSetupNextStep.value === 'create_super_admin') {
      return {
        id: 'setup',
        title: $t('custom.home.setup.createSuperAdmin.title'),
        description: $t('custom.home.setup.createSuperAdmin.description'),
        route: '/login/register-super-admin',
        action: $t('custom.home.setup.createSuperAdmin.action')
      }
    }

    if (
      tenantSetupNextStep.value === 'create_tenant_admin' ||
      !tenantSetupState.value?.has_tenant_admin ||
      !tenantSetupState.value?.has_tenant
    ) {
      return {
        id: 'setup',
        title: $t('custom.home.setup.createTenantAdmin.title'),
        description: $t('custom.home.setup.createTenantAdmin.description'),
        route: '/management/user?setup=tenant-admin',
        action: $t('custom.home.setup.createTenantAdmin.action')
      }
    }

    if (!homeSetupReady.value) {
      return {
        id: 'setup',
        title: $t('custom.home.setup.loginAsTenantAdmin.title'),
        description: $t('custom.home.setup.loginAsTenantAdmin.description'),
        route: '/login',
        action: $t('custom.home.setup.loginAsTenantAdmin.action')
      }
    }

    return {
      id: 'setup',
      title: $t('custom.home.setup.ready.title'),
      description: $t('custom.home.setup.ready.description'),
      route: '/management/user',
      action: $t('custom.home.setup.ready.action')
    }
  })

  return {
    tenantSetupState,
    refreshTenantSetupGuideState,
    tenantSetupNextStep,
    homeSetupReady,
    homeSetupGuideStep
  }
}

