/**
 * 文件用途：覆盖 table-action-modal 在角色管理场景下的前端行为与契约。
 * 核心逻辑：通过 Vue Test Utils 与 Vitest mock 服务、路由或组件依赖，断言关键渲染、交互和数据流。
 * 关键注意事项：仅作为视图层回归用例，mock 数据需与页面接口契约同步，避免把实现细节当成唯一断言。
 * 重构建议：后续可抽取稳定的工厂数据和挂载工具，减少重复 mock 与选择器耦合。
 */
import { defineComponent, h } from 'vue'
import { flushPromises, shallowMount } from '@vue/test-utils'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const hoisted = vi.hoisted(() => ({
  createRole: vi.fn(),
  updateRole: vi.fn()
}))

vi.mock('@/service/api', () => ({
  createRole: hoisted.createRole,
  updateRole: hoisted.updateRole
}))

vi.mock('@/locales', () => ({
  $t: (key: string) => key
}))

vi.mock('@/utils/form/rule', () => ({
  createRequiredFormRule: (msg: string) => ({ required: true, message: msg, trigger: ['input', 'blur'] })
}))

import TableActionModal from '../table-action-modal.vue'

const mountedWrappers: Array<ReturnType<typeof shallowMount>> = []

const mountComponent = (props: Record<string, any> = {}) => {
  const wrapper = shallowMount(TableActionModal, {
    props: {
      visible: false,
      type: 'add',
      editData: null,
      ...props
    },
    global: {
      stubs: {
        NModal: defineComponent({ name: 'NModal', props: { show: Boolean }, emits: ['update:show'], setup(_, { slots }) { return () => h('div', slots.default ? slots.default() : []) } }),
        NForm: defineComponent({ name: 'NForm', props: { model: Object, rules: [Object, Array] }, setup(_, { slots }) { return () => h('form', slots.default ? slots.default() : []) } }),
        NFormItem: defineComponent({ name: 'NFormItem', setup(_, { slots }) { return () => h('div', slots.default ? slots.default() : []) } }),
        NInput: defineComponent({ name: 'NInput', props: { value: { default: '' } }, emits: ['update:value'], setup() { return () => h('div') } }),
        NSpace: defineComponent({ name: 'NSpace', setup(_, { slots }) { return () => h('div', slots.default ? slots.default() : []) } }),
        NButton: defineComponent({ name: 'NButton', emits: ['click'], setup(_, { slots, emit }) { return () => h('button', { onClick: () => emit('click') }, slots.default ? slots.default() : []) } })
      }
    }
  })
  mountedWrappers.push(wrapper)
  return wrapper
}

const getSetupState = (wrapper: ReturnType<typeof shallowMount>) => wrapper.vm.$.setupState as Record<string, any>

describe('management/role/modules/table-action-modal.vue', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    hoisted.createRole.mockResolvedValue({ error: null })
    hoisted.updateRole.mockResolvedValue({ error: null })
  })

  afterEach(() => {
    while (mountedWrappers.length > 0) {
      mountedWrappers.pop()?.unmount()
    }
  })

  it('binds the role modal, form model and validation rules', () => {
    const wrapper = mountComponent()
    const state = getSetupState(wrapper)

    expect(state.modalVisible).toBe(false)
    expect(state.formModel).toEqual({
      name: '',
      email: '',
      description: ''
    })
    expect(state.rules).toMatchObject({
      name: { required: true, trigger: ['input', 'blur'] },
      description: { required: true, trigger: ['input', 'blur'] },
      email: {}
    })
  })

  it('title returns add translation for add type', () => {
    const wrapper = mountComponent({ type: 'add' })
    const state = getSetupState(wrapper)
    expect(state.title).toBe('page.manage.role.title')
  })

  it('title returns edit translation for edit type', () => {
    const wrapper = mountComponent({ type: 'edit' })
    const state = getSetupState(wrapper)
    expect(state.title).toBe('page.manage.role.editRole')
  })

  it('modalVisible get returns props.visible', () => {
    const wrapper = mountComponent({ visible: true })
    const state = getSetupState(wrapper)
    expect(state.modalVisible).toBe(true)
  })

  it('modalVisible set emits update:visible', () => {
    const wrapper = mountComponent()
    const state = getSetupState(wrapper)
    state.modalVisible = false
    expect(wrapper.emitted('update:visible')).toEqual([[false]])
  })

  it('closeModal emits update:visible false', () => {
    const wrapper = mountComponent()
    const state = getSetupState(wrapper)
    state.closeModal()
    expect(wrapper.emitted('update:visible')![0]).toEqual([false])
  })

  it('createDefaultFormModel returns default values', () => {
    const wrapper = mountComponent()
    const state = getSetupState(wrapper)
    const model = state.createDefaultFormModel()
    expect(model.name).toBe('')
    expect(model.email).toBe('')
    expect(model.description).toBe('')
  })

  it('handleUpdateFormModel merges model into formModel', () => {
    const wrapper = mountComponent()
    const state = getSetupState(wrapper)
    state.handleUpdateFormModel({ name: 'Admin', description: 'Admin role' })
    expect(state.formModel.name).toBe('Admin')
    expect(state.formModel.description).toBe('Admin role')
  })

  it('handleUpdateFormModelByModalType resets form for add type', () => {
    const wrapper = mountComponent({ type: 'add' })
    const state = getSetupState(wrapper)
    state.formModel.name = 'Old Name'
    state.handleUpdateFormModelByModalType()
    expect(state.formModel.name).toBe('')
  })

  it('handleUpdateFormModelByModalType populates form with editData for edit type', () => {
    const editData = { id: 'r-1', name: 'Admin', description: 'Admin role', email: 'admin@test.com' } as any
    const wrapper = mountComponent({ type: 'edit', editData })
    const state = getSetupState(wrapper)
    state.handleUpdateFormModelByModalType()
    expect(state.formModel.name).toBe('Admin')
    expect(state.formModel.description).toBe('Admin role')
  })

  it('handleSubmit calls createRole for add type and emits success', async () => {
    const wrapper = mountComponent({ type: 'add', visible: true })
    const state = getSetupState(wrapper)
    state.formRef = { validate: vi.fn().mockResolvedValue(undefined), restoreValidation: vi.fn() }
    state.formModel.name = 'Operator'
    state.formModel.description = 'Operate devices'
    await state.handleSubmit()
    await flushPromises()
    expect(hoisted.createRole).toHaveBeenCalledWith({
      name: 'Operator',
      email: '',
      description: 'Operate devices'
    })
    expect(wrapper.emitted('success')).toEqual([[]])
    expect(wrapper.emitted('update:visible')).toEqual([[false]])
  })

  it('handleSubmit calls updateRole for edit type and emits success', async () => {
    const editData = { id: 'r-1', name: 'Admin', description: 'Admin role', email: 'admin@test.com' } as any
    const wrapper = mountComponent({ type: 'edit', editData, visible: false })
    const state = getSetupState(wrapper)
    await wrapper.setProps({ visible: true })
    await flushPromises()
    state.formRef = { validate: vi.fn().mockResolvedValue(undefined), restoreValidation: vi.fn() }
    state.formModel.description = 'Updated role'
    await state.handleSubmit()
    await flushPromises()
    expect(hoisted.updateRole).toHaveBeenCalledWith({
      id: 'r-1',
      name: 'Admin',
      description: 'Updated role',
      email: 'admin@test.com'
    })
    expect(wrapper.emitted('success')).toEqual([[]])
    expect(wrapper.emitted('update:visible')).toEqual([[false]])
  })

  it('handleSubmit does not emit success when API returns error', async () => {
    hoisted.createRole.mockResolvedValue({ error: 'fail' })
    const wrapper = mountComponent({ type: 'add', visible: true })
    const state = getSetupState(wrapper)
    state.formRef = { validate: vi.fn().mockResolvedValue(undefined), restoreValidation: vi.fn() }
    await state.handleSubmit()
    await flushPromises()
    expect(wrapper.emitted('success')).toBeUndefined()
    expect(wrapper.emitted('update:visible')).toEqual([[false]])
  })

  it('watch on visible triggers handleUpdateFormModelByModalType when visible becomes true', async () => {
    const wrapper = mountComponent({ type: 'add', visible: false })
    const state = getSetupState(wrapper)
    state.formModel.name = 'Old'
    await wrapper.setProps({ visible: true })
    await flushPromises()
    expect(state.formModel.name).toBe('')
  })

  it('rules are defined for name, description and email', () => {
    const wrapper = mountComponent()
    const state = getSetupState(wrapper)
    expect(state.rules.name).toMatchObject({ required: true, message: expect.any(String), trigger: ['input', 'blur'] })
    expect(state.rules.description).toMatchObject({ required: true, message: expect.any(String), trigger: ['input', 'blur'] })
    expect(state.rules.email).toEqual({})
  })
})

/**
 * 文件用途：覆盖 index 在 系统与账号设置 场景下的前端行为与契约。
 * 核心逻辑：通过 Vue Test Utils 与 Vitest mock 服务、路由或组件依赖，断言关键渲染、交互和数据流。
 * 关键注意事项：仅作为视图层回归用例，mock 数据需与页面接口契约同步，避免把实现细节当成唯一断言。
 * 重构建议：后续可抽取稳定的工厂数据和挂载工具，减少重复 mock 与选择器耦合。
 */
import { defineComponent, h, inject, provide, ref } from 'vue'
import { mount } from '@vue/test-utils'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const paneSpecs = [
  { name: 'data-clear', label: 'page.manage.setting.dataClearSetting.title', section: 'data-clear' },
  {
    name: 'telemetry-dead-letter',
    label: 'custom.management.telemetryDeadLetter.title',
    section: 'telemetry-dead-letter'
  },
  { name: 'account-profile', label: 'custom.management.accountProfile.title', section: 'account-profile' },
  { name: 'account-email', label: 'custom.personalCenter.changeAccountEmail', section: 'account-email' },
  { name: 'warning-email', label: 'custom.management.warningEmail', section: 'warning-email' },
  { name: 'branding', label: 'custom.management.branding', section: 'branding' },
  { name: 'function', label: 'custom.management.configSetting', section: 'function' }
] as const

function createSettingStub(stubName: string, section: string) {
  return defineComponent({
    name: stubName,
    setup() {
      return () => h('div', { class: `${section}-setting-stub`, 'data-setting-section': section })
    }
  })
}

vi.mock('@/locales', () => ({
  $t: (key: string) => key
}))

vi.mock('../components/function-setting.vue', () => ({
  default: createSettingStub('FunctionSettingStub', 'function')
}))

vi.mock('../components/data-clear-setting.vue', () => ({
  default: createSettingStub('DataClearSettingStub', 'data-clear')
}))

vi.mock('../components/account-email-setting.vue', () => ({
  default: createSettingStub('AccountEmailSettingStub', 'account-email')
}))

vi.mock('../components/account-profile-setting.vue', () => ({
  default: createSettingStub('AccountProfileSettingStub', 'account-profile')
}))

vi.mock('../components/branding-setting.vue', () => ({
  default: createSettingStub('BrandingSettingStub', 'branding')
}))

vi.mock('../components/warning-email-setting.vue', () => ({
  default: createSettingStub('WarningEmailSettingStub', 'warning-email')
}))

vi.mock('../components/telemetry-dead-letter-setting.vue', () => ({
  default: createSettingStub('TelemetryDeadLetterSettingStub', 'telemetry-dead-letter')
}))

import SettingIndex from '../index.vue'

const mountedWrappers: Array<ReturnType<typeof mount>> = []
const tabsActiveKey = Symbol('tabs-active-key')

const NTabsStub = defineComponent({
  name: 'NTabsStub',
  setup(_props, { slots }) {
    const activeTab = ref<(typeof paneSpecs)[number]['name']>(paneSpecs[0].name)
    provide(tabsActiveKey, activeTab)

    return () =>
      h('div', { class: 'n-tabs-stub' }, [
        h(
          'div',
          { class: 'n-tabs-stub__triggers' },
          paneSpecs.map(spec =>
            h(
              'button',
              {
                type: 'button',
                'data-tab-trigger': spec.name,
                'data-active': String(activeTab.value === spec.name),
                onClick: () => {
                  activeTab.value = spec.name
                }
              },
              spec.label
            )
          )
        ),
        h('div', { class: 'n-tabs-stub__content' }, slots.default ? slots.default() : [])
      ])
  }
})

const NTabPaneStub = defineComponent({
  name: 'NTabPaneStub',
  props: {
    name: {
      type: String,
      required: true
    },
    tab: {
      type: String,
      required: true
    }
  },
  setup(props, { slots }) {
    const activeTab = inject<ReturnType<typeof ref<string>>>(tabsActiveKey)

    return () =>
      h(
        'section',
        {
          class: 'n-tab-pane-stub',
          'data-pane-name': props.name,
          'data-pane-tab': props.tab,
          'data-visible': String(activeTab?.value === props.name)
        },
        activeTab?.value === props.name && slots.default ? slots.default() : []
      )
  }
})

const mountComponent = () => {
  const wrapper = mount(SettingIndex, {
    global: {
      renderStubDefaultSlot: true,
      stubs: {
        NCard: true,
        NTabs: NTabsStub,
        NTabPane: NTabPaneStub
      }
    }
  })
  mountedWrappers.push(wrapper)
  return wrapper
}

describe('management/setting/index.vue', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  afterEach(() => {
    while (mountedWrappers.length > 0) {
      mountedWrappers.pop()?.unmount()
    }
  })

  it('renders the setting page shell with the default data-clear pane active', () => {
    const wrapper = mountComponent()

    expect(wrapper.classes()).toContain('overflow-hidden')
    expect(wrapper.findAll('.n-tab-pane-stub').map(pane => pane.attributes('data-visible'))).toEqual([
      'true',
      'false',
      'false',
      'false',
      'false',
      'false',
      'false'
    ])
    expect(wrapper.get('[data-visible="true"] [data-setting-section]').attributes('data-setting-section')).toBe(
      'data-clear'
    )
  })

  it('renders all setting panes in the expected order', () => {
    const wrapper = mountComponent()
    const paneNames = wrapper.findAll('.n-tab-pane-stub').map(pane => pane.attributes('data-pane-name'))
    expect(paneNames).toEqual(paneSpecs.map(spec => spec.name))
  })

  it('renders translated labels for each setting pane', () => {
    const wrapper = mountComponent()
    const labels = wrapper.findAll('.n-tab-pane-stub').map(pane => pane.attributes('data-pane-tab'))
    expect(labels).toEqual(paneSpecs.map(spec => spec.label))
  })

  it('renders each setting section inside its matching pane', () => {
    const wrapper = mountComponent()
    expect(wrapper.get('[data-visible="true"] [data-setting-section]').attributes('data-setting-section')).toBe('data-clear')
  })

  it('switches visible content when a different tab is selected', async () => {
    const wrapper = mountComponent()

    const accountProfileTrigger = wrapper.get('[data-tab-trigger="account-profile"]')
    await accountProfileTrigger.trigger('click')
    expect(wrapper.get('[data-visible="true"] [data-setting-section]').attributes('data-setting-section')).toBe(
      'account-profile'
    )

    const brandingTrigger = wrapper.get('[data-tab-trigger="branding"]')
    await brandingTrigger.trigger('click')
    expect(wrapper.get('[data-visible="true"] [data-setting-section]').attributes('data-setting-section')).toBe('branding')

    const deadLetterTrigger = wrapper.get('[data-tab-trigger="telemetry-dead-letter"]')
    await deadLetterTrigger.trigger('click')
    expect(wrapper.get('[data-visible="true"] [data-setting-section]').attributes('data-setting-section')).toBe(
      'telemetry-dead-letter'
    )

    const functionTrigger = wrapper.get('[data-tab-trigger="function"]')
    await functionTrigger.trigger('click')
    expect(wrapper.get('[data-visible="true"] [data-setting-section]').attributes('data-setting-section')).toBe('function')
  })
})

