import { ref } from 'vue'
import { describe, expect, it, vi } from 'vitest'
import { formatOtaTaskTime, useOtaTaskDetail } from '../useOtaTaskDetail'

const t = (key: string) => key

describe('useOtaTaskDetail', () => {
  it('builds status options and rollout summary bindings for the task detail modal', () => {
    const detail = useOtaTaskDetail({
      selectedPackage: ref({ id: 'pkg-1', version: '2.0.0' }),
      selectedTask: ref(null),
      detailLoading: ref(false),
      detailList: ref([]),
      detailStatistics: ref([
        { status: 4, count: 3 },
        { status: 5, count: 1 }
      ]),
      loadTaskDetail: vi.fn(),
      fetchTaskDetails: vi.fn(),
      editTaskDetail: vi.fn(),
      t,
      message: {},
      dialog: {}
    })

    expect(detail.statusOptions.value[0]).toEqual({
      label: 'page.product.update-ota.allStatus',
      value: 0
    })
    expect(detail.rolloutFailedCount.value).toBe(1)
    expect(detail.rolloutSuccessRate.value).toBe('75%')
    expect(detail.rolloutSummaryItems.value.map((item) => item.key)).toEqual([
      'total',
      'pending',
      'pushed',
      'upgrading',
      'success',
      'failed',
      'canceled'
    ])
    expect(detail.detailColumns.length).toBeGreaterThan(0)
  })

  it('formats empty and real OTA timestamps consistently', () => {
    expect(formatOtaTaskTime()).toBe('-')
    expect(formatOtaTaskTime('2026-07-05T01:02:03Z')).toContain('2026-07-05')
  })

  it('copies an OTA failed-rollout support package from loaded detail state', async () => {
    const writeText = vi.fn().mockResolvedValue(undefined)
    Object.defineProperty(navigator, 'clipboard', {
      configurable: true,
      value: { writeText }
    })
    const message = {
      success: vi.fn(),
      warning: vi.fn()
    }
    const detail = useOtaTaskDetail({
      selectedPackage: ref({ id: 'pkg-1', name: 'Pkg', version: '2.0.0' }),
      selectedTask: ref({ id: 'task-1', name: 'Factory rollout', device_count: 2 }),
      detailLoading: ref(false),
      detailList: ref([
        {
          id: 'detail-1',
          name: 'Pump A',
          device_number: 'SN-001',
          current_version: '1.0.0',
          version: '2.0.0',
          status: 5,
          status_description: 'download failed'
        }
      ]),
      detailStatistics: ref([{ status: 5, count: 1 }]),
      loadTaskDetail: vi.fn(),
      fetchTaskDetails: vi.fn(),
      editTaskDetail: vi.fn(),
      t,
      message,
      dialog: {}
    })

    await detail.copyFailureSupportBundle()

    expect(writeText).toHaveBeenCalledWith(expect.stringContaining('taskId=task-1'))
    expect(writeText).toHaveBeenCalledWith(expect.stringContaining('download failed'))
    expect(writeText).toHaveBeenCalledWith(expect.stringContaining('Evidence boundary'))
    expect(message.success).toHaveBeenCalledWith('page.product.update-ota.failureSupportBundleCopied')
  })

  it('maps OTA task status codes to labels and tag types', () => {
    const detail = useOtaTaskDetail({
      selectedPackage: ref(null),
      selectedTask: ref(null),
      detailLoading: ref(false),
      detailList: ref([]),
      detailStatistics: ref([]),
      loadTaskDetail: vi.fn(),
      fetchTaskDetails: vi.fn(),
      editTaskDetail: vi.fn(),
      t,
      message: {},
      dialog: {}
    })

    expect(detail.statusLabel(1)).toBe('page.product.update-ota.pendingTask')
    expect(detail.statusLabel(2)).toBe('page.product.update-ota.pushTask')
    expect(detail.statusLabel(3)).toBe('page.product.update-ota.upgradingTask')
    expect(detail.statusLabel(4)).toBe('page.product.update-ota.completeTask')
    expect(detail.statusLabel(5)).toBe('page.product.update-ota.failTask')
    expect(detail.statusLabel(6)).toBe('page.product.update-ota.cancelTask')
    // 未知状态回落成原始码，未传状态回落成占位符，避免表格出现空单元格
    expect(detail.statusLabel(99)).toBe('99')
    expect(detail.statusLabel(undefined)).toBe('-')

    expect(detail.statusTagType(4)).toBe('success')
    expect(detail.statusTagType(5)).toBe('error')
    expect(detail.statusTagType(3)).toBe('warning')
    expect(detail.statusTagType(6)).toBe('default')
    expect(detail.statusTagType(1)).toBe('info')
  })

  it('confirms cancel and retry detail actions before calling the edit API', async () => {
    const editTaskDetail = vi.fn().mockResolvedValue({ error: null })
    const fetchTaskDetails = vi.fn().mockResolvedValue(undefined)
    const dialogWarning = vi.fn()
    const message = { success: vi.fn(), warning: vi.fn() }

    const detail = useOtaTaskDetail({
      selectedPackage: ref({ id: 'pkg-1', version: '2.0.0' }),
      selectedTask: ref({ id: 'task-1', name: 'Task 1' }),
      detailLoading: ref(false),
      detailList: ref([]),
      detailStatistics: ref([]),
      loadTaskDetail: vi.fn(),
      fetchTaskDetails,
      editTaskDetail,
      t,
      message,
      dialog: { warning: dialogWarning }
    })

    // 取消动作：必须先弹确认框，确认后才调用后端
    detail.updateTaskDetailStatus({ id: 'detail-1', name: 'Device A', status: 3 } as any, 6 as any)
    expect(editTaskDetail).not.toHaveBeenCalled()
    await dialogWarning.mock.calls[0][0].onPositiveClick()
    expect(editTaskDetail).toHaveBeenNthCalledWith(1, { id: 'detail-1', action: 6 })

    // 重试动作走同一条确认链路
    detail.updateTaskDetailStatus({ id: 'detail-1', name: 'Device A', status: 6 } as any, 1 as any)
    await dialogWarning.mock.calls[1][0].onPositiveClick()
    expect(editTaskDetail).toHaveBeenNthCalledWith(2, { id: 'detail-1', action: 1 })

    expect(message.success).toHaveBeenCalledWith('common.operationSuccess')
  })

  it('does not refresh detail rows when the edit API reports an error', async () => {
    const editTaskDetail = vi.fn().mockResolvedValue({ error: { message: 'boom' } })
    const fetchTaskDetails = vi.fn().mockResolvedValue(undefined)
    const dialogWarning = vi.fn()
    const message = { success: vi.fn(), warning: vi.fn() }

    const detail = useOtaTaskDetail({
      selectedPackage: ref({ id: 'pkg-1', version: '2.0.0' }),
      selectedTask: ref({ id: 'task-1', name: 'Task 1' }),
      detailLoading: ref(false),
      detailList: ref([]),
      detailStatistics: ref([]),
      loadTaskDetail: vi.fn(),
      fetchTaskDetails,
      editTaskDetail,
      t,
      message,
      dialog: { warning: dialogWarning }
    })

    detail.updateTaskDetailStatus({ id: 'detail-1', name: 'Device A', status: 3 } as any, 6 as any)
    await dialogWarning.mock.calls[0][0].onPositiveClick()

    expect(editTaskDetail).toHaveBeenCalledTimes(1)
    expect(message.success).not.toHaveBeenCalled()
  })
})

import { ref } from 'vue'
import { describe, expect, it, vi } from 'vitest'
import { useOtaTaskFlow } from '../useOtaTaskFlow'
import {
  FLEET_CURRENT_PAGE_SCOPE,
  FLEET_DEVICE_FILTER_SCOPE,
  FLEET_FILTER_RESULT_SCOPE
} from '../../../device/modules/fleet-rollout-context'

const t = (key: string) => key

function createFlowHarness(fleetRolloutContext = ref(null as any)) {
  const fetchDevices = vi.fn().mockResolvedValue(undefined)
  const fetchTasks = vi.fn().mockResolvedValue(undefined)
  const clearDeviceCandidates = vi.fn()
  const addTask = vi.fn().mockResolvedValue({ error: null })
  const previewTask = vi.fn().mockResolvedValue({
    data: { selected_count: 42, total_matched: 42, over_limit: false, max_devices: 5000 },
    error: null
  })
  const message = {
    success: vi.fn(),
    warning: vi.fn()
  }

  const flow = useOtaTaskFlow({
    data: {
      selectedPackageId: ref<string | null>('pkg-1'),
      selectedPackage: ref({ id: 'pkg-1', target_version: '2.0' }),
      deviceCandidates: ref([
        { id: 'dev-1', name: 'Offline Device', current_version: '1.0', is_online: 0 },
        { id: 'dev-2', name: 'Current Device', current_version: '2.0' }
      ]),
      deviceOptions: ref([{ label: 'Offline Device', value: 'dev-1' }]),
      fetchDevices,
      fetchTasks,
      clearDeviceCandidates
    },
    services: {
      addTask,
      previewTask
    },
    t,
    message,
    fleetRolloutContext
  })

  return {
    flow,
    fetchDevices,
    fetchTasks,
    clearDeviceCandidates,
    addTask,
    previewTask,
    message
  }
}

describe('useOtaTaskFlow', () => {
  it('opens the task modal after resetting form state and loading eligible devices', async () => {
    const harness = createFlowHarness()

    await harness.flow.openTaskModal()

    expect(harness.clearDeviceCandidates).toHaveBeenCalledTimes(1)
    expect(harness.fetchDevices).toHaveBeenCalledTimes(1)
    expect(harness.flow.taskModalVisible.value).toBe(true)
    expect(harness.message.warning).not.toHaveBeenCalled()
  })

  it('saves the current task form without changing the backend create-task payload', async () => {
    const harness = createFlowHarness()
    harness.flow.taskForm.name = '  Batch 1  '
    harness.flow.taskForm.description = '  staged rollout  '
    harness.flow.taskForm.device_id_list = ['dev-1']

    await harness.flow.saveTask()

    expect(harness.addTask).toHaveBeenCalledWith({
      name: 'Batch 1',
      ota_upgrade_package_id: 'pkg-1',
      description: 'staged rollout',
      device_id_list: ['dev-1']
    })
    expect(harness.message.success).toHaveBeenCalledWith('common.saveSuccess')
    expect(harness.fetchTasks).toHaveBeenCalledTimes(1)
    expect(harness.flow.taskModalVisible.value).toBe(false)
  })

  it('saves a fleet filter rollout as a backend device_filter contract instead of a current-page id list', async () => {
    const fleetRolloutContext = ref({
      source: 'device_manage',
      scope: FLEET_FILTER_RESULT_SCOPE,
      deviceIds: ['dev-1'],
      requestedTotal: 42,
      currentPageCount: 1,
      deviceFilter: { group_id: 'group-1', is_online: 1 }
    })
    const harness = createFlowHarness(fleetRolloutContext)
    harness.flow.taskForm.name = '  Filter rollout  '
    harness.flow.taskForm.device_id_list = ['dev-1']

    await harness.flow.saveTask()

    expect(harness.previewTask).toHaveBeenCalledWith({
      ota_upgrade_package_id: 'pkg-1',
      device_filter: { group_id: 'group-1', is_online: 1 },
      exclude_device_id_list: [],
      max_devices: 5000
    })
    expect(harness.addTask).not.toHaveBeenCalled()
    expect(harness.flow.filterPreviewResult.value).toEqual(
      expect.objectContaining({ selected_count: 42, total_matched: 42, max_devices: 5000 })
    )

    await harness.flow.saveTask()

    expect(harness.addTask).toHaveBeenCalledWith({
      name: 'Filter rollout',
      ota_upgrade_package_id: 'pkg-1',
      description: undefined,
      device_filter: { group_id: 'group-1', is_online: 1 },
      exclude_device_id_list: [],
      expected_total: 42,
      max_devices: 5000
    })
  })

  it('keeps compatible current-page fleet links working when they include a backend device filter', async () => {
    const fleetRolloutContext = ref({
      source: 'device_manage',
      scope: FLEET_CURRENT_PAGE_SCOPE,
      deviceIds: ['dev-1'],
      requestedTotal: 42,
      currentPageCount: 1,
      deviceFilter: { group_id: 'group-1' }
    })
    const harness = createFlowHarness(fleetRolloutContext)
    harness.flow.taskForm.name = 'Compatible filter rollout'
    harness.flow.taskForm.device_id_list = ['dev-1']

    await harness.flow.saveTask()

    expect(harness.previewTask).toHaveBeenCalledWith({
      ota_upgrade_package_id: 'pkg-1',
      device_filter: { group_id: 'group-1' },
      exclude_device_id_list: [],
      max_devices: 5000
    })
    expect(harness.addTask).not.toHaveBeenCalled()
  })

  it('treats device_filter scope as a full backend-filter OTA rollout', async () => {
    const fleetRolloutContext = ref({
      source: 'device_manage',
      scope: FLEET_DEVICE_FILTER_SCOPE,
      deviceIds: ['dev-1', 'dev-2'],
      requestedTotal: 42,
      currentPageCount: 2,
      deviceFilter: { search: 'pump', is_online: 1 }
    })
    const harness = createFlowHarness(fleetRolloutContext)
    harness.flow.taskForm.name = 'Command center filter rollout'

    await harness.flow.saveTask()

    expect(harness.previewTask).toHaveBeenCalledWith({
      ota_upgrade_package_id: 'pkg-1',
      device_filter: { search: 'pump', is_online: 1 },
      exclude_device_id_list: [],
      max_devices: 5000
    })
    expect(harness.addTask).not.toHaveBeenCalled()
    expect(harness.flow.filterPreviewResult.value).toMatchObject({
      selected_count: 42,
      total_matched: 42,
      max_devices: 5000
    })
  })

  it('blocks a fleet filter rollout when backend preview finds no devices', async () => {
    const fleetRolloutContext = ref({
      source: 'device_manage',
      scope: FLEET_FILTER_RESULT_SCOPE,
      deviceIds: ['dev-1'],
      requestedTotal: 1,
      currentPageCount: 1,
      deviceFilter: { group_id: 'group-1' }
    })
    const harness = createFlowHarness(fleetRolloutContext)
    harness.previewTask.mockResolvedValueOnce({ data: { selected_count: 0, over_limit: false }, error: null })
    harness.flow.taskForm.name = 'Filter rollout'

    await harness.flow.saveTask()

    expect(harness.addTask).not.toHaveBeenCalled()
    expect(harness.message.warning).toHaveBeenCalledWith('page.product.update-ota.filterPreviewNoDevices')
  })

  it('blocks a fleet filter rollout when backend preview exceeds the task limit', async () => {
    const fleetRolloutContext = ref({
      source: 'device_manage',
      scope: FLEET_FILTER_RESULT_SCOPE,
      deviceIds: ['dev-1'],
      requestedTotal: 6000,
      currentPageCount: 1,
      deviceFilter: { group_id: 'group-1' }
    })
    const harness = createFlowHarness(fleetRolloutContext)
    harness.previewTask.mockResolvedValueOnce({
      data: { selected_count: 6000, over_limit: true, max_devices: 5000 },
      error: null
    })
    harness.flow.taskForm.name = 'Filter rollout'

    await harness.flow.saveTask()

    expect(harness.addTask).not.toHaveBeenCalled()
    expect(harness.message.warning).toHaveBeenCalledWith(
      'page.product.update-ota.filterPreviewOverLimit'.replace('{selected}', '6000').replace('{max}', '5000')
    )
  })

  it('uses local preflight data to explain selected rollout risks', () => {
    const harness = createFlowHarness()
    harness.flow.taskForm.device_id_list = ['dev-1', 'dev-2']

    expect(harness.flow.taskPreflight.value).toEqual({
      eligible: 2,
      selected: 2,
      offline: 1,
      sameVersion: 1,
      missingVersion: 0,
      riskCount: 2
    })
    expect(harness.flow.taskRiskDevices.value.map((item) => item.id)).toEqual(['dev-1', 'dev-2'])
  })

})

