    expect(hoisted.getDashboard).toHaveBeenCalledTimes(1)
    expect(hoisted.getDashboard).toHaveBeenCalledWith('param-1')
    const state = getState(wrapper)
    expect(state.dashboardTitle).toBe('Menu Dashboard')
